INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('JAMB', 'Igbo', 2024, NULL, 'Gịnị bụ isiokwu edemede a?', '["Ihe gbasara ọrụ ugbo","Ịlụ nwaanyị n''ala Igbo","Echichi","Ịgba mgba"]', 1, NULL, 'Gụọ mbadamba edemede a nke ọma ma zaa ajụjụ ndị nọ n''okpuru ya: <br/><br/>Ịlụ nwaanyị n''ala Igbo abụghị ihe egwuregwu. Ọ bụ njikọ dị n''etiti ezinụlọ abụọ, ọ bụghị naanị mmadụ abụọ. N''oge gboo, nne na nna na-achọrọ nwa ha nwoke nwaanyị ha ga-alụ. Ha na-agakwuru ezinụlọ nwaanyị ahụ jụọ ase gbasara ha. Ajụjụ ha na-ajụ na-agụnyekarị ma hà nwere ọrịa ọjọọ, ma hà bụ ndị ohi, ma ọ bụ ma hà bụ ndị nwere agwa ọma. Ọ bụrụ na ase ahụ gaa nke ọma, a na-amalite usoro ịkụ aka n''ọnụ ụzọ. N''ebe a, a na-eweta mmanya na ọjị. Emesịa, a na-ekpebi ego nwaanyị, nke a na-akpọ ''ego nnabata''. Ememe kachasị mma bụ ''Igba nkwụ'', ebe nwaanyị na-achọ di ya n''ime igwe mmadụ ma nye ya mmanya. Nke a na-egosi na ọ nabatala ya dịka di ya nke iwu kwadoro.', 'JAMB_Igbo_2024.json', '014e3d1bc67db961c1670d0bef0406901ca4dc36c9f174bd6e6a9251d5a88d2e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('JAMB', 'Igbo', 2024, NULL, 'Ònye na-achọrọ nwa nwoke nwaanyị ọ ga-alụ n''oge gboo?', '["Ndị enyi ya","Nne na nna ya","Dibia","Eze"]', 1, NULL, 'Gụọ mbadamba edemede a nke ọma ma zaa ajụjụ ndị nọ n''okpuru ya: <br/><br/>Ịlụ nwaanyị n''ala Igbo abụghị ihe egwuregwu. Ọ bụ njikọ dị n''etiti ezinụlọ abụọ, ọ bụghị naanị mmadụ abụọ. N''oge gboo, nne na nna na-achọrọ nwa ha nwoke nwaanyị ha ga-alụ. Ha na-agakwuru ezinụlọ nwaanyị ahụ jụọ ase gbasara ha. Ajụjụ ha na-ajụ na-agụnyekarị ma hà nwere ọrịa ọjọọ, ma hà bụ ndị ohi, ma ọ bụ ma hà bụ ndị nwere agwa ọma. Ọ bụrụ na ase ahụ gaa nke ọma, a na-amalite usoro ịkụ aka n''ọnụ ụzọ. N''ebe a, a na-eweta mmanya na ọjị. Emesịa, a na-ekpebi ego nwaanyị, nke a na-akpọ ''ego nnabata''. Ememe kachasị mma bụ ''Igba nkwụ'', ebe nwaanyị na-achọ di ya n''ime igwe mmadụ ma nye ya mmanya. Nke a na-egosi na ọ nabatala ya dịka di ya nke iwu kwadoro.', 'JAMB_Igbo_2024.json', '67e8827c3671227d99f2e8e257e9b4ed726751893b30e3ba311dfdfda4b11c42');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('JAMB', 'Igbo', 2024, NULL, 'Gịnị kpatara eji ajụ ase tupu a lụọ nwaanyị?', '["Iji mara ego ha nwere","Iji mara agwa na akụkọ ezinụlọ","Iji mara ebe ha bi","Iji mara nri ha na-eri"]', 1, NULL, 'Gụọ mbadamba edemede a nke ọma ma zaa ajụjụ ndị nọ n''okpuru ya: <br/><br/>Ịlụ nwaanyị n''ala Igbo abụghị ihe egwuregwu. Ọ bụ njikọ dị n''etiti ezinụlọ abụọ, ọ bụghị naanị mmadụ abụọ. N''oge gboo, nne na nna na-achọrọ nwa ha nwoke nwaanyị ha ga-alụ. Ha na-agakwuru ezinụlọ nwaanyị ahụ jụọ ase gbasara ha. Ajụjụ ha na-ajụ na-agụnyekarị ma hà nwere ọrịa ọjọọ, ma hà bụ ndị ohi, ma ọ bụ ma hà bụ ndị nwere agwa ọma. Ọ bụrụ na ase ahụ gaa nke ọma, a na-amalite usoro ịkụ aka n''ọnụ ụzọ. N''ebe a, a na-eweta mmanya na ọjị. Emesịa, a na-ekpebi ego nwaanyị, nke a na-akpọ ''ego nnabata''. Ememe kachasị mma bụ ''Igba nkwụ'', ebe nwaanyị na-achọ di ya n''ime igwe mmadụ ma nye ya mmanya. Nke a na-egosi na ọ nabatala ya dịka di ya nke iwu kwadoro.', 'JAMB_Igbo_2024.json', '0ad3ee2e2ecf676166d388dd5fa346d88286192a2541147d450db462c028e993');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('JAMB', 'Igbo', 2024, NULL, 'Kedu ihe a na-eweta n''usoro ịkụ aka n''ọnụ ụzọ?', '["Ego na nri","Mmanya na ọjị","Akwa na akpụkpọ ụkwụ","Ji na ede"]', 1, NULL, 'Gụọ mbadamba edemede a nke ọma ma zaa ajụjụ ndị nọ n''okpuru ya: <br/><br/>Ịlụ nwaanyị n''ala Igbo abụghị ihe egwuregwu. Ọ bụ njikọ dị n''etiti ezinụlọ abụọ, ọ bụghị naanị mmadụ abụọ. N''oge gboo, nne na nna na-achọrọ nwa ha nwoke nwaanyị ha ga-alụ. Ha na-agakwuru ezinụlọ nwaanyị ahụ jụọ ase gbasara ha. Ajụjụ ha na-ajụ na-agụnyekarị ma hà nwere ọrịa ọjọọ, ma hà bụ ndị ohi, ma ọ bụ ma hà bụ ndị nwere agwa ọma. Ọ bụrụ na ase ahụ gaa nke ọma, a na-amalite usoro ịkụ aka n''ọnụ ụzọ. N''ebe a, a na-eweta mmanya na ọjị. Emesịa, a na-ekpebi ego nwaanyị, nke a na-akpọ ''ego nnabata''. Ememe kachasị mma bụ ''Igba nkwụ'', ebe nwaanyị na-achọ di ya n''ime igwe mmadụ ma nye ya mmanya. Nke a na-egosi na ọ nabatala ya dịka di ya nke iwu kwadoro.', 'JAMB_Igbo_2024.json', 'c5e76745d8ad162914e4013e0dbad97785e453476e6723a52edf3ec73572bdb4');
