INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('JAMB', 'Igbo', 2024, NULL, 'Gịnị ka nwaanyị na-enye di ya n''ememe ịgba nkwụ?', '["Mmiri","Ọjị","Mmanya","Nri"]', 2, NULL, 'Gụọ mbadamba edemede a nke ọma ma zaa ajụjụ ndị nọ n''okpuru ya: <br/><br/>Ịlụ nwaanyị n''ala Igbo abụghị ihe egwuregwu. Ọ bụ njikọ dị n''etiti ezinụlọ abụọ, ọ bụghị naanị mmadụ abụọ. N''oge gboo, nne na nna na-achọrọ nwa ha nwoke nwaanyị ha ga-alụ. Ha na-agakwuru ezinụlọ nwaanyị ahụ jụọ ase gbasara ha. Ajụjụ ha na-ajụ na-agụnyekarị ma hà nwere ọrịa ọjọọ, ma hà bụ ndị ohi, ma ọ bụ ma hà bụ ndị nwere agwa ọma. Ọ bụrụ na ase ahụ gaa nke ọma, a na-amalite usoro ịkụ aka n''ọnụ ụzọ. N''ebe a, a na-eweta mmanya na ọjị. Emesịa, a na-ekpebi ego nwaanyị, nke a na-akpọ ''ego nnabata''. Ememe kachasị mma bụ ''Igba nkwụ'', ebe nwaanyị na-achọ di ya n''ime igwe mmadụ ma nye ya mmanya. Nke a na-egosi na ọ nabatala ya dịka di ya nke iwu kwadoro.', 'JAMB_Igbo_2024.json', '90897bf2df5e042dcbe8bc48ddb8fa76c9edee49b0d4a4dd4f457b170ab1bc29');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('JAMB', 'Igbo', 2024, NULL, 'Ịlụ nwaanyị n''ala Igbo bụ njikọ dị n''etiti ole?', '["Mmadụ abụọ naanị","Ezinụlọ abụọ","Obodo abụọ","Ndị enyi abụọ"]', 1, NULL, 'Gụọ mbadamba edemede a nke ọma ma zaa ajụjụ ndị nọ n''okpuru ya: <br/><br/>Ịlụ nwaanyị n''ala Igbo abụghị ihe egwuregwu. Ọ bụ njikọ dị n''etiti ezinụlọ abụọ, ọ bụghị naanị mmadụ abụọ. N''oge gboo, nne na nna na-achọrọ nwa ha nwoke nwaanyị ha ga-alụ. Ha na-agakwuru ezinụlọ nwaanyị ahụ jụọ ase gbasara ha. Ajụjụ ha na-ajụ na-agụnyekarị ma hà nwere ọrịa ọjọọ, ma hà bụ ndị ohi, ma ọ bụ ma hà bụ ndị nwere agwa ọma. Ọ bụrụ na ase ahụ gaa nke ọma, a na-amalite usoro ịkụ aka n''ọnụ ụzọ. N''ebe a, a na-eweta mmanya na ọjị. Emesịa, a na-ekpebi ego nwaanyị, nke a na-akpọ ''ego nnabata''. Ememe kachasị mma bụ ''Igba nkwụ'', ebe nwaanyị na-achọ di ya n''ime igwe mmadụ ma nye ya mmanya. Nke a na-egosi na ọ nabatala ya dịka di ya nke iwu kwadoro.', 'JAMB_Igbo_2024.json', 'e8d35598c3b69b55c28a864d30d60267ce19a8be232570e73dcd97dfed23637b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('JAMB', 'Igbo', 2024, NULL, 'Kedu n''ime ndị a abụghị ajụjụ a na-ajụ n''ase?', '["Ma hà bụ ndị ohi","Ma hà nwere agwa ọma","Ma nwaanyị ahụ mara mma","Ma hà nwere ọrịa ọjọọ"]', 2, NULL, 'Gụọ mbadamba edemede a nke ọma ma zaa ajụjụ ndị nọ n''okpuru ya: <br/><br/>Ịlụ nwaanyị n''ala Igbo abụghị ihe egwuregwu. Ọ bụ njikọ dị n''etiti ezinụlọ abụọ, ọ bụghị naanị mmadụ abụọ. N''oge gboo, nne na nna na-achọrọ nwa ha nwoke nwaanyị ha ga-alụ. Ha na-agakwuru ezinụlọ nwaanyị ahụ jụọ ase gbasara ha. Ajụjụ ha na-ajụ na-agụnyekarị ma hà nwere ọrịa ọjọọ, ma hà bụ ndị ohi, ma ọ bụ ma hà bụ ndị nwere agwa ọma. Ọ bụrụ na ase ahụ gaa nke ọma, a na-amalite usoro ịkụ aka n''ọnụ ụzọ. N''ebe a, a na-eweta mmanya na ọjị. Emesịa, a na-ekpebi ego nwaanyị, nke a na-akpọ ''ego nnabata''. Ememe kachasị mma bụ ''Igba nkwụ'', ebe nwaanyị na-achọ di ya n''ime igwe mmadụ ma nye ya mmanya. Nke a na-egosi na ọ nabatala ya dịka di ya nke iwu kwadoro.', 'JAMB_Igbo_2024.json', '085a195471297733be5c34e5669c740055b2d7092b0ea8dba45bf1b03315f9b9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('JAMB', 'Igbo', 2024, NULL, 'Gịnị na-eme ma ọ bụrụ na ase agaghị nke ọma?', '["A na-alụ nwaanyị ahụ","A na-akwụsị usoro ọlụlụ","A na-enye ego karịa","A na-akpọ ndị uwe ojii"]', 1, NULL, 'Gụọ mbadamba edemede a nke ọma ma zaa ajụjụ ndị nọ n''okpuru ya: <br/><br/>Ịlụ nwaanyị n''ala Igbo abụghị ihe egwuregwu. Ọ bụ njikọ dị n''etiti ezinụlọ abụọ, ọ bụghị naanị mmadụ abụọ. N''oge gboo, nne na nna na-achọrọ nwa ha nwoke nwaanyị ha ga-alụ. Ha na-agakwuru ezinụlọ nwaanyị ahụ jụọ ase gbasara ha. Ajụjụ ha na-ajụ na-agụnyekarị ma hà nwere ọrịa ọjọọ, ma hà bụ ndị ohi, ma ọ bụ ma hà bụ ndị nwere agwa ọma. Ọ bụrụ na ase ahụ gaa nke ọma, a na-amalite usoro ịkụ aka n''ọnụ ụzọ. N''ebe a, a na-eweta mmanya na ọjị. Emesịa, a na-ekpebi ego nwaanyị, nke a na-akpọ ''ego nnabata''. Ememe kachasị mma bụ ''Igba nkwụ'', ebe nwaanyị na-achọ di ya n''ime igwe mmadụ ma nye ya mmanya. Nke a na-egosi na ọ nabatala ya dịka di ya nke iwu kwadoro.', 'JAMB_Igbo_2024.json', '4a8a13982559eab4ea46b70f5031e2820b7c537de749ca365ddc331f538b9314');
