INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('JAMB', 'Literature', 2022, NULL, 'The mood of the scene is:', '["Romantic","Tense","Joyful","Indifferent"]', 1, NULL, '<h3>The King''s Verdict</h3>BAROKA: (To the Bale) I have told you, the matter is settled. The girl stays. She has seen the palace and tasted the wine of royalty. Would you have her return to the dust of the village square?<br>BALE: But my Lord, she is betrothed to the hunter. The bride price has been paid in yams and goats.<br>BAROKA: Yams and goats! Is that the worth of a jewel? Return them. Double them. But the girl remains.<br>SADIQ: (Whispering) The hunter will not take this lightly, my Lord. His gun speaks louder than his voice.', 'JAMB_Literature_2022.json', '06631d781d0cd717a4839c715d470c15bc73da5f33f7bcb44c427254ef8b1236');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('JAMB', 'Literature', 2022, NULL, 'Baroka''s attitude towards the village life is one of:', '["Admiration","Disdain/Contempt","Nostalgia","Envy"]', 1, NULL, '<h3>The King''s Verdict</h3>BAROKA: (To the Bale) I have told you, the matter is settled. The girl stays. She has seen the palace and tasted the wine of royalty. Would you have her return to the dust of the village square?<br>BALE: But my Lord, she is betrothed to the hunter. The bride price has been paid in yams and goats.<br>BAROKA: Yams and goats! Is that the worth of a jewel? Return them. Double them. But the girl remains.<br>SADIQ: (Whispering) The hunter will not take this lightly, my Lord. His gun speaks louder than his voice.', 'JAMB_Literature_2022.json', 'c3f8200b235f4aa04ae377bc05a1d9e73004a6c584e8a684dd9e76d20d82d601');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('JAMB', 'Literature', 2022, NULL, 'The phrase ''His gun speaks louder than his voice'' is an example of:', '["Personification","Metaphor","Simile","Irony"]', 0, NULL, '<h3>The King''s Verdict</h3>BAROKA: (To the Bale) I have told you, the matter is settled. The girl stays. She has seen the palace and tasted the wine of royalty. Would you have her return to the dust of the village square?<br>BALE: But my Lord, she is betrothed to the hunter. The bride price has been paid in yams and goats.<br>BAROKA: Yams and goats! Is that the worth of a jewel? Return them. Double them. But the girl remains.<br>SADIQ: (Whispering) The hunter will not take this lightly, my Lord. His gun speaks louder than his voice.', 'JAMB_Literature_2022.json', '30a008a1b68ebe54bc2e2f4d43733b901092df06d09455c443b26d082c7e67db');
