INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('JAMB', 'Literature', 2023, NULL, 'The simile ''hands trembling like leaves'' suggests:', '["The accused was cold","The accused was innocent","The accused was terrified","The accused was dancing"]', 2, NULL, 'The courtroom was silent as the judge adjusted his spectacles. The accused stood in the dock, his hands trembling like leaves in a storm. He looked at the gallery, searching for a friendly face, but found only eyes of stone. The prosecutor''s voice cut through the air, sharp and unforgiving, listing the crimes one by one. It was a theatre of justice, but to the young man, it felt more like a slaughterhouse.', 'JAMB_Literature_2023.json', '74da8d5e1c53679aecffafe18c19540aec301ba345c6c2a82cf89b503aaa497a');
