INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('JAMB', 'Literature', 2025, NULL, 'The description of the windows as ''hollow eyes'' is a:', '["Simile","Metaphor","Pun","Synecdoche"]', 0, NULL, 'The old mansion stood on the hill, a skeleton of its former self. Its windows were like hollow eyes staring blankly at the village below. Ivy strangled the stone pillars, and the roof sagged under the weight of a century of neglect. Villagers whispered that the house breathed at night, exhaling cold drafts that chilled the bone. No one dared approach the iron gates, which were rusted shut, guarding secrets that time had forgotten.', 'JAMB_Literature_2025.json', 'ec67a3a6292ec353ab3f22c1705d23932257268f06dde6a68690bb4a20236cc1');
