INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The accounting concept which states that for every debit entry, there must be a corresponding credit entry is the _____ concept.', '["Dual Aspect","Going Concern","Matching","Accrual"]', 0, 'The Dual Aspect concept is the foundation of double-entry bookkeeping, ensuring that the accounting equation (Assets = Liabilities + Equity) remains in balance.', NULL, 'NECO_Accounting_2024.json', 'a17386bdc750947ab24b78cfac2329796b2fc824f856465e471406ca3328a519');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following is an example of a nominal account?', '["Cash at bank","Plant and Machinery","Discount Received","Trade Debtors"]', 2, 'Nominal accounts are accounts for income, expenses, gains, and losses. Discount Received is an income/gain, while the others are real or personal accounts.', NULL, 'NECO_Accounting_2024.json', '6c4be3b1114e5fdf4025bd28aab712f5ed0ba2150c307254e47837c70a746e7c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The process of transferring transactions from the journals to the ledger is known as _____.', '["Balancing","Totaling","Posting","Summarizing"]', 2, 'Posting is the technical term for transferring entries from the books of original entry (journals) to the principal book of accounts (the ledger).', NULL, 'NECO_Accounting_2024.json', '6ad4c3c86673733704b1d47d22ee448e740931647da9887d3a25dfff0fff927a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The document sent by a supplier to a buyer when goods are returned as being faulty is a _____.', '["Debit note","Credit note","Receipt","Invoice"]', 1, 'A credit note is issued by a seller to a buyer to reduce the amount the buyer owes, typically due to returns or overcharges.', NULL, 'NECO_Accounting_2024.json', '3957a78c90867b4050c4a96ba61ae9deb4803ce3f31c4eed8fad8c9dc9e9c04f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following errors will cause the Trial Balance not to agree?', '["Complete omission of a transaction","Error of original entry","Error of transposition in one ledger account","Error of principle"]', 2, 'Transposition in only one account affects only one side of the double entry, leading to an imbalance. The other errors affect both sides equally, so the Trial Balance still balances.', NULL, 'NECO_Accounting_2024.json', '6d4dc520a07d124b2d9c818ac8a7ff0a5e5981818ff98fc3d6162e66dfed21c8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'A credit balance in the Cash Book (Bank column) indicates a/an _____.', '["Bank deposit","Bank overdraft","Cash in hand","Unpresented cheque"]', 1, 'In the bank account (an asset), a debit balance is money owned, while a credit balance represents a liability to the bank, known as an overdraft.', NULL, 'NECO_Accounting_2024.json', 'bd47c7dfa750651af4d022680d0c175322377ec687cbf78ff5bab06cf02d73d3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The petty cash system where the petty cashier is given a fixed sum at the start of a period is the _____ system.', '["Floating","Imprest","Fixed","Direct"]', 1, 'In the Imprest system, the petty cashier starts with a float and is reimbursed exactly what was spent at the end of the period.', NULL, 'NECO_Accounting_2024.json', '2179fe8c5e38cff607d7af045abd0177eed6dcb18c34fc06e3daf4eaa4ad1601');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'An entry made on both the debit and credit sides of the same three-column cash book is a _____.', '["Single entry","Double entry","Contra entry","Reverse entry"]', 2, 'Contra entries (like cash deposited into bank) involve both cash and bank columns of the same book, representing internal movements of funds.', NULL, 'NECO_Accounting_2024.json', '266e6be4901a5dc11e9ddf1b91d6bfbac8729a00cdf05477800100f96d1959aa');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following is a capital expenditure?', '["Payment of wages","Cost of fueling the delivery van","Purchase of a new office building","Repairs of a machine"]', 2, 'Capital expenditure is spending on non-current assets that provide long-term benefits to the business, rather than day-to-day running costs.', NULL, 'NECO_Accounting_2024.json', 'e1921490022cc3659e43f21f9a8ea0805e38ddd0fb27bbdcc827b0aa16981e19');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The accounting equation is expressed as _____.', '["Capital = Assets + Liabilities","Assets = Liabilities + Capital","Liabilities = Assets + Capital","Assets = Liabilities - Capital"]', 1, 'The fundamental equation states that the resources owned by a business (Assets) are provided either by creditors (Liabilities) or the owner (Capital).', NULL, 'NECO_Accounting_2024.json', '0e40f268c3ec3dd2bb79638dca725800cc521c7621f3c4ec069f222a73aa6fd9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Calculate the Cost of Goods Available for Sale.', '["#50,000","#58,000","#63,000","#65,000"]', 2, 'Available for sale = Opening Stock + (Purchases - Returns Outwards) + Carriage Inwards = 10,000 + (50,000 - 2,000) + 5,000 = #63,000.', 'The following data relates to the trading activities of Emeka Ltd for the year ended 31st December, 2023:
Opening Stock: #10,000
Purchases: #50,000
Sales: #80,000
Returns Outwards: #2,000
Closing Stock: #12,000
Carriage Inwards: #5,000', 'NECO_Accounting_2024.json', '226ab3425921ffdb9684fc4c8f59800a57fb6f1bc2a5101bd29c3a6562edb2a1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Calculate the Cost of Goods Sold.', '["#41,000","#51,000","#63,000","#50,000"]', 1, 'COGS = Cost of Goods Available for Sale - Closing Stock = 63,000 - 12,000 = #51,000.', 'The following data relates to the trading activities of Emeka Ltd for the year ended 31st December, 2023:
Opening Stock: #10,000
Purchases: #50,000
Sales: #80,000
Returns Outwards: #2,000
Closing Stock: #12,000
Carriage Inwards: #5,000', 'NECO_Accounting_2024.json', '635bb2f2ad03d728ec8c670310b4cd56b5089b3d00c9ad192d1fd7b1735aa204');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Calculate the Gross Profit.', '["#29,000","#30,000","#32,000","#35,000"]', 0, 'Gross Profit = Sales - Cost of Goods Sold = 80,000 - 51,000 = #29,000.', 'The following data relates to the trading activities of Emeka Ltd for the year ended 31st December, 2023:
Opening Stock: #10,000
Purchases: #50,000
Sales: #80,000
Returns Outwards: #2,000
Closing Stock: #12,000
Carriage Inwards: #5,000', 'NECO_Accounting_2024.json', '83660088c5445be48a6a2135073b6b0692135657a1b9f16a9b68bedfcc234225');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following is a current liability?', '["Prepaid insurance","Accrued electricity bills","Plant and Machinery","Goodwill"]', 1, 'Accrued expenses are debts currently owed for services already enjoyed but not yet paid for, representing a short-term liability.', NULL, 'NECO_Accounting_2024.json', 'df776b1df199f74e356a0f0bbde8a8bcd1f72c3bdc3ae5842789c8c8607d8e25');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Bad debts are categorized as _____.', '["Current Assets","Operating Income","Operating Expenses","Intangible Assets"]', 2, 'Bad debts are losses resulting from uncollectible trade receivables and are charged as an expense to the Profit and Loss Account.', NULL, 'NECO_Accounting_2024.json', '9b2fc7afdddbbfcfdff57551ed7025bc48e54acc661f8ad091ca9a2e05633399');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The value of a non-current asset after deducting accumulated depreciation is its _____.', '["Market value","Scrap value","Net Book Value","Replacement value"]', 2, 'Net Book Value (NBV) is the historical cost of an asset minus the total depreciation charged against it since its acquisition.', NULL, 'NECO_Accounting_2024.json', 'f3783ef144e5529e3783e7c990f3a84e873dd716a390c868ecb0f681b8642c0f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'A machine was purchased for #20,000. It is to be depreciated at 10% per annum using the Reducing Balance method. Calculate the depreciation charge for the second year.', '["#2,000","#1,800","#1,500","#4,000"]', 1, 'Year 1 Depr = 10% of 20,000 = 2,000. NBV end of Y1 = 18,000. Year 2 Depr = 10% of 18,000 = #1,800.', NULL, 'NECO_Accounting_2024.json', '522d5215b3c9db88099b314feb3002eb63d22c818bcd6b1541e326375543b050');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which book of original entry is used to record credit sales of furniture by a company that deals in electronics?', '["Sales Journal","Purchases Journal","Cash Book","General Journal"]', 3, 'Sales Journals are for credit sales of trading stock only. Credit sales of non-current assets (furniture) must be recorded in the General Journal (Journal Proper).', NULL, 'NECO_Accounting_2024.json', '2eab43753971d6c5821191a8a07a54ce7cce0c84a2b2317ddcb6870d5b070669');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The Sales Ledger contains the accounts of _____.', '["Creditors","Debtors","Owners","Suppliers"]', 1, 'The Sales Ledger is used to maintain individual accounts for customers (trade debtors) who buy goods on credit.', NULL, 'NECO_Accounting_2024.json', '046a1ca7bd07230b4e25acaf969cbc9668098e46ab53cc6f3a28c6d59d577a63');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'A Bank Reconciliation Statement is prepared to _____.', '["Know the profit for the year","Check errors in the ledger","Reconcile the Cash Book and Bank Statement balances","Prevent theft of cash"]', 2, 'Discrepancies often exist between a business''s Cash Book records and the Bank''s Statement due to timing differences or errors; the statement aligns both.', NULL, 'NECO_Accounting_2024.json', 'bba5fe1ffa6a1b9e702c691c2c5b85e690c499180dbbf111dc14aa1bf1636f3c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Unpresented cheques are cheques _____.', '["Received but not yet recorded in the cash book","Drawn by the firm but not yet paid by the bank","Paid into the bank but not yet credited","Dishonored by the bank"]', 1, 'Unpresented cheques have been issued to suppliers (credited in Cash Book) but haven''t reached the bank for payment yet.', NULL, 'NECO_Accounting_2024.json', '668c71031ec4e5cf22753e2d08cc66109a25989a52b33f36f20ad3848949702d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following is an intangible asset?', '["Copyright","Inventory","Accounts Receivable","Bank Balance"]', 0, 'Intangible assets lack physical substance but have long-term value, such as copyrights, patents, and goodwill.', NULL, 'NECO_Accounting_2024.json', '8e7eb42c9fcf4cec037203f57611c0aba3c26ac75d27f93a497441ea82151fa0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The ledger that contains all accounts except personal accounts is the _____ ledger.', '["General","Private","Nominal","Sales"]', 0, 'The General Ledger houses the real and nominal accounts (impersonal accounts), whereas personal accounts are in the Sales and Purchases ledgers.', NULL, 'NECO_Accounting_2024.json', '8b633fd7c6962b01cfe94be61c74fe1c2a2e5607ca55a977357dd3195b7b9191');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Provision for doubtful debts is based on the _____ concept.', '["Consistency","Prudence","Entity","Materiality"]', 1, 'The Prudence concept dictates that a business should anticipate losses but not profits. Creating provisions ensures assets are not overstated.', NULL, 'NECO_Accounting_2024.json', '4ee60233776eae36c8a122040fe3a4fa7bfc8a140861601e78ef5413ebb1f1be');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'In a partnership, where there is no deed, profits and losses are shared _____.', '["In the ratio of capital contributed","Equally","According to the age of partners","By the senior partner''s decision"]', 1, 'According to the Partnership Act of 1890, in the absence of a formal agreement, all partners share profits and losses equally regardless of capital contribution.', NULL, 'NECO_Accounting_2024.json', '616015e40e810222689c8fd794999074deee0181768a720371dfd3fe5f82e5f0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The interest charged on money withdrawn by a partner for personal use is _____.', '["Interest on capital","Interest on drawings","Partner''s salary","Commission"]', 1, 'Interest on drawings is an income to the partnership firm and is charged to discourage partners from taking excessive cash out of the business.', NULL, 'NECO_Accounting_2024.json', '36dca5a0211b5aee7172c06dc14521f8df2c4afee151b8d8b4f9716da0de3d3e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following is recorded in the Profit and Loss Appropriation Account?', '["General expenses","Interest on capital","Audit fees","Insurance premiums"]', 1, 'The Appropriation Account is used to show how net profit is distributed among partners (interest on capital, salaries, drawings, shared profit).', NULL, 'NECO_Accounting_2024.json', '69d2b9cf864cbda570651a38b151227c5109902c183d139cd82bae94c2702c4e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'In a limited liability company, the part of authorized capital that has been taken up by the public is _____.', '["Paid-up capital","Issued capital","Reserve capital","Nominal capital"]', 1, 'Issued capital is the portion of authorized capital that the directors have decided to offer to the public for subscription.', NULL, 'NECO_Accounting_2024.json', '28c687a9455473ba556795f0bb6a065ee0e11fb5697cedc178ab2d95f1ec4fa8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Shares that carry a fixed rate of dividend and have priority over others are _____.', '["Ordinary shares","Preference shares","Deferred shares","Equity shares"]', 1, 'Preference shares grant holders the right to receive dividends before ordinary shareholders and usually at a fixed percentage.', NULL, 'NECO_Accounting_2024.json', '1c7f487561a4d3b4f30fb2a53088876f1571502a8ceb5ef9399b8c2746078051');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The document that regulates the internal rules of a company is the _____.', '["Memorandum of Association","Articles of Association","Prospectus","Certificate of Incorporation"]', 1, 'Articles of Association define the internal management, powers of directors, and rights of shareholders within a company.', NULL, 'NECO_Accounting_2024.json', 'e37588dbbb102d1429337f8c8ffb5088f24a0dc3aa691dead3c24fd4cff55f67');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'A debenture represents a _____.', '["Short-term bank loan","Long-term loan to the company","Share of profit","Gift from the government"]', 1, 'A debenture is a debt instrument used by companies to borrow money from the public at a fixed interest rate.', NULL, 'NECO_Accounting_2024.json', '2ca851480fa6efb89feeb8b8002871ddc14a711a6c369c36cc56632a4f596962');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The excess of assets over liabilities in a non-profit organization is called _____.', '["Net Profit","Gross Profit","Accumulated Fund","Capital"]', 2, 'Non-profit organizations use the term ''Accumulated Fund'' instead of ''Owner''s Equity'' or ''Capital''.', NULL, 'NECO_Accounting_2024.json', '92bf3ffae9c6d4c11ed02d3d32b8a9dc11ff0622d7831cd7eabba2939ad63597');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'A Receipts and Payments Account is essentially a summary of the _____.', '["Trading account","Income and Expenditure account","Cash Book","Balance Sheet"]', 2, 'A Receipts and Payments account records all cash inflows and outflows for the period, functioning similarly to a Cash Book.', NULL, 'NECO_Accounting_2024.json', '5e49da7d305d2a031d43e5a96113040090fa187d24d6cc5eef31d9072190f880');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Subscription received in advance for the following year is a/an _____ in the current year''s balance sheet.', '["Current Asset","Current Liability","Operating Income","Long-term Loan"]', 1, 'Money received in advance for a service yet to be provided is a liability because the organization ''owes'' the service or a refund.', NULL, 'NECO_Accounting_2024.json', 'a4e294adcb7519c6c9427544524956da4def1a7bc78506c9721aca440f390392');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Prime cost consists of _____.', '["Direct materials + Direct labour","Direct materials + Direct labour + Direct expenses","Direct materials + Factory overheads","Manufacturing cost + Selling expenses"]', 1, 'Prime cost is the sum of all direct manufacturing costs. Direct expenses (like royalties) are included along with materials and labour.', NULL, 'NECO_Accounting_2024.json', '78ebf496e29b08fbf34cfc7557e6ff0d3ed9d16b25335087f1ab4bb58d116134');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following is a factory overhead?', '["Direct raw materials","Factory rent","Salesman''s commission","Office manager''s salary"]', 1, 'Factory overheads are indirect manufacturing costs. Factory rent relates to the production area but cannot be traced to a single unit.', NULL, 'NECO_Accounting_2024.json', 'f6d40ceaf0bec8e9d78d21642a71b4abea352bd23019f8af600003192cd5e5ec');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The method of converting incomplete records to double entry using a balancing figure for credit sales is _____.', '["Analysis method","Statement of affairs method","Comparative method","Single entry method"]', 0, 'The Analysis method involves using Total Debtors and Total Creditors accounts to derive missing figures for sales and purchases.', NULL, 'NECO_Accounting_2024.json', '5c73f702ba20daa3e9f3b0b8371060a4650f88f7c389c8c1e3d517d21a4bdc08');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'A Statement of Affairs is prepared to determine the _____.', '["Net Profit","Cash balance","Opening Capital","Total Assets"]', 2, 'In single-entry systems, a Statement of Affairs (Assets minus Liabilities) is prepared at the start of the period to find the opening capital.', NULL, 'NECO_Accounting_2024.json', 'fe765618c586cf59a9b260f8accd08d4f57412cafaa41c8ce4fba903a7daa59e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The account used to record the authority to spend in government accounting is the _____.', '["Vote account","Capital account","Revenue account","Journal"]', 0, 'In Public Sector accounting, a ''Vote'' is the specific legislative approval or authority granted to a head of expenditure.', NULL, 'NECO_Accounting_2024.json', 'c52d5f86ebfb734a1d8c370c11a4613a9b966459597d03f52e7564d4f9d4e244');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following is a source of government revenue?', '["Grants to schools","Direct and Indirect taxes","Construction of roads","Payment of salaries"]', 1, 'Taxes (CIT, VAT, etc.) are the primary means through which the government generates revenue for public expenditure.', NULL, 'NECO_Accounting_2024.json', 'c7e7f89e74588f27b59fe7423249d15a24206f0276b851d276954d6eb394c0a8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The official in charge of the accounts of a government ministry is the _____.', '["Auditor General","Accountant General","Accounting Officer","Sub-Treasurer"]', 2, 'The Permanent Secretary of a ministry is usually the Accounting Officer, responsible for the funds voted for that ministry.', NULL, 'NECO_Accounting_2024.json', 'c951d2c33546fa05c2593b92b42832cd1052b07101bd24dd6d5c8c3f84d41f22');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The Matching Concept requires that _____.', '["Assets must match liabilities","Income should be matched against the cost of generating it in the same period","Debit must match credit","Opening stock must match closing stock"]', 1, 'This principle ensures that the Profit and Loss Account correctly reflects the performance of the period by comparing revenue with related expenses.', NULL, 'NECO_Accounting_2024.json', '5f7fb84959e8fd3f711b502b1c33dad9065496eff81a3129421508ce91019a1d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following is a book of original entry and also a ledger?', '["Sales Journal","Cash Book","Purchases Journal","Returns Inwards Book"]', 1, 'The Cash Book is unique because it serves both as the initial record of transactions and the final T-account for cash and bank balances.', NULL, 'NECO_Accounting_2024.json', 'cc9f080b2bc7f14827c0d079af10809f1d077fb4ec8c541894b9655791337908');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'A suspense account is used to _____.', '["Record bad debts","Temporarily balance the trial balance","Keep track of cash shortages","Hide illegal transactions"]', 1, 'When a Trial Balance fails to agree, the difference is placed in a Suspense Account until the error is found and corrected.', NULL, 'NECO_Accounting_2024.json', 'f2e2d50b9f6d653f5c4bbc19cd6339e1a3e3030432c23b5141bc6939018f8c3f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Drawings by a proprietor for personal use results in a/an _____.', '["Increase in capital","Decrease in capital","Increase in liability","Decrease in assets"]', 1, 'Drawings represent the withdrawal of resources from the business by the owner, thereby reducing the owner''s stake (Capital).', NULL, 'NECO_Accounting_2024.json', 'fe91bcafa090c46c56f878d8a5c6ba2b660e5e30b2db2e50e946cb25ab01f548');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The historical cost of an asset is #50,000, and its accumulated depreciation is #20,000. Its current market value is #35,000. At what value should it be shown in the Balance Sheet?', '["#50,000","#35,000","#30,000","#20,000"]', 2, 'According to the Historical Cost concept, assets are shown at cost less accumulated depreciation (50,000 - 20,000 = 30,000), not current market value.', NULL, 'NECO_Accounting_2024.json', 'c1b032d12b8526a3a2e452695fb8db2e87abe607de693e1be4da71c7737e1f48');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The Sales Ledger Control Account is also known as _____.', '["Total Creditors Account","Total Debtors Account","Private Ledger","Nominal Ledger"]', 1, 'The Sales Ledger Control Account summarizes all transactions related to credit customers (debtors) to check the accuracy of the individual ledger accounts.', NULL, 'NECO_Accounting_2024.json', 'd9b68f35e2076b934bec776e87003ff9f867b9aec814c093e11ae8b639ab65ac');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following describes ''Consolidated Revenue Fund''?', '["Money set aside for debt","A fund where all government revenues are paid","Profit from a company","A reserve for partners"]', 1, 'In Nigerian public finance, all revenues received by the Federation (unless otherwise directed) must be paid into the CRF.', NULL, 'NECO_Accounting_2024.json', '6101d3aa3fc754b9d372a1b7bcc55ceb3e1e26af292c0f309654e0ed1e6e838d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The principle of ''Going Concern'' assumes that _____.', '["The business will close soon","The business will continue to operate for the foreseeable future","The owner is separate from the business","Prices will remain stable"]', 1, 'This assumption allows the business to carry forward its assets and liabilities from one period to another without intending to liquidate.', NULL, 'NECO_Accounting_2024.json', '5c7d294a2968f0ac7e7ae5d7dffd67d530bd882913b7e984ef260e91619ae020');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Discount allowed is _____.', '["An income","An expense","A liability","An asset"]', 1, 'Discount allowed is a reduction in the price given to customers for prompt payment, representing a cost or expense to the business.', NULL, 'NECO_Accounting_2024.json', 'd814c38ae865daccfae5e4297a92d35fb4fa035f5c71c53bd77279d1c1e3e93c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'A debit balance brought down in the Insurance Account at the start of a period represents _____.', '["Insurance owed","Insurance prepaid","Insurance expense for the year","Insurance refund"]', 1, 'A debit balance at the start of an expense account signifies that a portion of the payment relates to the current period (Prepayment/Asset).', NULL, 'NECO_Accounting_2024.json', '81074d0ac18f133e1f6d4b44a2320642eac3697f2a9721900c8f400dd9469191');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following is NOT an internal user of accounting information?', '["Marketing manager","Production supervisor","Tax authorities","Managing director"]', 2, 'Tax authorities are external users who need information for regulatory and assessment purposes.', NULL, 'NECO_Accounting_2024.json', '2c3205c1fadc0f592aed528c887e351272a254e6aebef4a9d08fab148120c8cd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The ratio that measures the ability of a business to pay its short-term debts is the _____ ratio.', '["Profitability","Liquidity","Gearing","Efficiency"]', 1, 'Liquidity ratios (like Current Ratio or Acid Test Ratio) assess the ease with which a business can meet its current obligations.', NULL, 'NECO_Accounting_2024.json', '507a5c9a17102be5f62e98cd181eb36c880e149692213819a66a83a6abb94a8d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The accounting concept that requires transactions to be recorded in physical currency is the _____ concept.', '["Money Measurement","Business Entity","Realization","Periodicity"]', 0, 'The Money Measurement concept limits accounting records to items and events that can be expressed in monetary terms.', NULL, 'NECO_Accounting_2024.json', 'fe0c954b7535109292b9f67f6af3cfc4765be1c7caa075be3140022df21ac96b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'What is the correct entry for recording a cash purchase of goods?', '["Debit: Cash; Credit: Purchases","Debit: Purchases; Credit: Cash","Debit: Suppliers; Credit: Cash","Debit: Cash; Credit: Sales"]', 1, 'Purchases (an expense) increase on the debit side, and Cash (an asset) decreases on the credit side.', NULL, 'NECO_Accounting_2024.json', 'e3cba0615ea61152d31b2cb93ead42dd0a13a0c429c9347a60241dc71ec871ed');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Goodwill is usually brought into the books when _____.', '["A business is making a loss","A business is purchased as a going concern","The owner decides to increase the asset value","Depreciation is too high"]', 1, 'Goodwill is only recognized in the accounts when a business is bought or when there is a change in the partnership structure.', NULL, 'NECO_Accounting_2024.json', '7c19cf667d6147cb2a87feb53df951f0b3be388cba763071e0dcd9a84ae998f3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following is a fictitious asset?', '["Building","Inventory","Preliminary expenses","Prepaid rent"]', 2, 'Fictitious assets are capitalized expenses/losses that have no real value but are temporarily shown as assets (e.g., promotional expenses, discount on issue of shares).', NULL, 'NECO_Accounting_2024.json', '7d23bf8598f5ff7fe26574461720db8550a3232db6cec31161f6e08807ec11fe');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The Purchases Ledger Control Account is used to check the accuracy of the _____.', '["Sales Ledger","General Ledger","Purchases Ledger","Private Ledger"]', 2, 'The Purchases Ledger Control account summarizes all transactions involving suppliers (creditors) to detect errors in the subsidiary ledger.', NULL, 'NECO_Accounting_2024.json', 'c7bddbcd7a3f8d4becd44f1843147ff3f84d27cea4bbeecad544c65d9203ceed');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Authorized Capital is also known as _____.', '["Issued capital","Paid-up capital","Nominal capital","Reserve capital"]', 2, 'Nominal or registered capital is the maximum amount of share capital a company is legally permitted to issue.', NULL, 'NECO_Accounting_2024.json', '0bfb6e8c0b28bab09254898800ddefbdf6ce6851e7becbdb84d16cfc8991deb0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'In Departmental Accounts, rent is usually allocated to departments based on _____.', '["Volume of sales","Floor area occupied","Number of employees","Value of stock"]', 1, 'Rent is a space-related cost, so it is most logically apportioned based on the physical space (floor area) used by each department.', NULL, 'NECO_Accounting_2024.json', '37af142cb176b124876acc4aa5ad9127d558d9474f42e8aec4c3139d05c67017');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The systematic record of all cash and bank transactions is the _____.', '["Journal","Petty Cash Book","Cash Book","Ledger"]', 2, 'The Cash Book is the primary book of original entry for recording all money received and paid out by the business.', NULL, 'NECO_Accounting_2024.json', 'd4bdb7225e224df4a5cf448d20a5e31b9ac4fe8a5178a515095cef8580da7925');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Under incomplete records, profit is calculated by _____.', '["Sales - Purchases","Opening Capital - Closing Capital","(Closing Capital + Drawings) - (Opening Capital + Additional Capital)","Assets - Liabilities"]', 2, 'This is the ''Capital Comparison'' method. Drawings increase the calculated profit, while new capital introduced reduces it.', NULL, 'NECO_Accounting_2024.json', 'caa560562e6dfddebfc974e3746843cdc1e2e90949b00ed67dcdac860cc08951');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following is a bookkeeping function?', '["Auditing financial records","Recording financial transactions","Interpreting financial statements","Providing tax advice"]', 1, 'Bookkeeping is the routine clerical task of identifying and recording financial data. Accounting involves analysis and interpretation.', NULL, 'NECO_Accounting_2024.json', 'bb5f62496737f4cabd0ad33ae6d6e3df2866ffb07216e2f1b059eaab8c2a2908');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following appears in the Trading Account?', '["Carriage outwards","General expenses","Carriage inwards","Salaries"]', 2, 'Carriage inwards (cost of bringing goods into the business) is added to purchases to determine the cost of goods sold.', NULL, 'NECO_Accounting_2024.json', '0be8e1de55e602cdb6b13e378e8a81908e1dfa81b7ac3426d2a05541d3c38406');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'An asset with an original cost of #5,000 and a scrap value of #500 has an estimated life of 5 years. Calculate its annual depreciation using the Straight Line method.', '["#1,000","#900","#500","#1,100"]', 1, 'Annual Depreciation = (Cost - Scrap Value) / Estimated Life = (5,000 - 500) / 5 = 4,500 / 5 = #900.', NULL, 'NECO_Accounting_2024.json', 'd58d8f89428b6668d1ed4db5883031f9bf5f7da1428e35c1f1c5190bb800d77c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'When a partner retires, the profit on the revaluation of assets is credited to _____.', '["Remaining partners only","Retiring partner only","All partners in their old profit-sharing ratio","New partners only"]', 2, 'Revaluation relates to the time when all partners were in the firm, so any gain or loss belongs to all partners according to their existing ratio.', NULL, 'NECO_Accounting_2024.json', '78583d8c652f13c4bdfd9d4741a199b721de74dd245a95c573c4d14864befb13');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'A credit entry in the Sales Account represents _____.', '["A decrease in sales","An increase in sales","A return by a customer","Cash received from a customer"]', 1, 'Sales is an income account. Incomes increase on the credit side and decrease on the debit side.', NULL, 'NECO_Accounting_2024.json', '7ea7bddba76c61c65f52b020c635960fee01f2ff8460c637ec04751048aeb59e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The primary objective of Financial Accounting is to _____.', '["Detect and prevent fraud","Determine the tax payable","Provide information for stakeholders to make decisions","Keep track of employees'' attendance"]', 2, 'Accounting is the ''language of business'' meant to communicate financial performance and position to interested parties like investors and lenders.', NULL, 'NECO_Accounting_2024.json', 'e0b023d8cbff14997db329520ffc9e0c2dcf65f87c59135b03866c39b516c9c4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following is a real account?', '["Rent account","Sales account","Furniture account","Salary account"]', 2, 'Real accounts relate to tangible or intangible property (assets) such as land, buildings, furniture, and machinery.', NULL, 'NECO_Accounting_2024.json', '9fc6671692b8d45b7c1149995a43addd426a941b2a7e47ed401bbd0034f2e32a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Working Capital is defined as _____.', '["Total Assets - Total Liabilities","Fixed Assets - Current Liabilities","Current Assets - Current Liabilities","Capital + Reserves"]', 2, 'Working capital measures the liquidity and short-term financial health of a business, calculated by subtracting current debts from current resources.', NULL, 'NECO_Accounting_2024.json', 'c3278b10cc48ce99a06fac96740b56357dd43e890fda57297eded948c91d6ef5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'An example of a government ''Accounting Officer'' is the _____.', '["Auditor General","Governor","Permanent Secretary","Central Bank Governor"]', 2, 'In ministries and departments, the Permanent Secretary is designated as the Accounting Officer responsible for managing the funds allocated (voted) to that unit.', NULL, 'NECO_Accounting_2024.json', '7e29e9abe7b68359ea099846f00801a2b89b19dffd1d838f3dc13cfc8b37841d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'The error where a transaction is recorded in the correct class of account but the wrong personal account is an error of _____.', '["Commission","Principle","Omission","Original Entry"]', 0, 'An error of commission occurs when a transaction is entered in the correct ledger type (e.g., Sales Ledger) but for the wrong person (e.g., T. Bello instead of A. Bello).', NULL, 'NECO_Accounting_2024.json', 'ef7a2cb87bf440d1f6535b144ecf54e85a93ff1cc38b7c6c3125d44d141126d0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2024, NULL, 'Which of the following will result in an increase in Gross Profit?', '["Reduction in Closing Stock","Increase in Sales Returns","Reduction in Carriage Inwards","Increase in Purchases"]', 2, 'Carriage inwards increases the cost of sales. Reducing it lowers the cost of goods sold, thereby increasing the gross profit.', NULL, 'NECO_Accounting_2024.json', 'aac0fcd3ebb6140e085dbd08242c53f0e9c097110526ce6907549eabefc2bbe3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Accounting', 2025, NULL, 'Accounting Equation:', '["$$ A = C + L $$","$$ A = C - L $$","$$ C = A + L $$","$$ L = A + C $$"]', 0, NULL, NULL, 'NECO_Accounting_2025.json', 'b86bc8488f5292f997fbaf3de21b5ec08aea24c1157807c1953ff5a7b2a2568e');
