INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The Land Use Act of 1978 in Nigeria vests the ownership of all land in the _____.', '["Federal Government","Local Government Chairmen","State Governors","Traditional Rulers"]', 2, 'The Land Use Act of 1978 vests all land within a state in the Governor of that state, to be held in trust for the people.', NULL, 'NECO_Agric_2024.json', 'd3e95ff7c2e28e366006cc63fd4843ef9a55c8c1a427fae43485eff22c985ee2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is a major problem of agricultural development in Nigeria?', '["Inadequate land mass","Lack of interest in farming","Inadequate credit facilities","Excessive rainfall"]', 2, 'Access to finance or credit is a significant bottleneck for small-scale farmers to expand or modernize their operations.', NULL, 'NECO_Agric_2024.json', '16b505471f1b5dd6a339f06ce2b5590cf3d2ceb5fa902a5534921d8f73165e26');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Subsistence agriculture is characterized by _____.', '["Small land holdings","Use of heavy machinery","High capital investment","Production for export"]', 0, 'Subsistence farming involves small plots of land primarily used to produce food for the farmer''s family.', NULL, 'NECO_Agric_2024.json', '96997009bceac65bd598b09f89784864027cac1cb3f176554244eb4ac0ab004c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which type of rock is formed from the cooling and solidification of molten magma?', '["Sedimentary","Metamorphic","Igneous","Sandstone"]', 2, 'Igneous rocks, such as granite and basalt, are formed directly from the cooling of magma or lava.', NULL, 'NECO_Agric_2024.json', 'b40011bb237eb7823630fc0fc9106fe25d19580dd6f1864fb756369bcbc7c0cc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The process of rock weathering that involves the reaction of minerals with oxygen is _____.', '["Hydration","Oxidation","Carbonation","Hydrolysis"]', 1, 'Oxidation occurs when minerals react with oxygen, often changing the color and structural integrity of the rock (e.g., rusting of iron-rich rocks).', NULL, 'NECO_Agric_2024.json', 'fa99de00a7f07697787c6ab2ec30f61d915287c3d0183dc219860418db212b35');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Soil texture refers to the _____.', '["Arrangement of soil particles","Relative proportion of sand, silt, and clay","Level of soil fertility","Amount of water in the soil"]', 1, 'Texture is an inherent physical property determined by the percentage distribution of different-sized mineral particles.', NULL, 'NECO_Agric_2024.json', '8313acf20e1079f5d2379fdd3251fb5c7208454769bca9dca1ae3eb513b8abc9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'A soil sample with a pH of 4.5 is considered to be _____.', '["Alkaline","Neutral","Strongly acidic","Saline"]', 2, 'The pH scale runs from 0-14. Values below 7 are acidic; 4.5 is significantly low, making it strongly acidic.', NULL, 'NECO_Agric_2024.json', '76864f9cd8c59bc6d2a56a23deddd8d45ab77c127d015c7a811fb53a03a3ef0e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is a primary macronutrient for plants?', '["Iron","Zinc","Phosphorus","Boron"]', 2, 'The primary macronutrients are Nitrogen (N), Phosphorus (P), and Potassium (K).', NULL, 'NECO_Agric_2024.json', '165dd365283b98c43aa467c85d971ad605d35229e48594857f4f6366314bf4f8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The removal of the upper layer of soil by water or wind is known as _____.', '["Mulching","Erosion","Leaching","Irrigation"]', 1, 'Soil erosion is the displacement of the fertile topsoil by environmental agents like water and wind.', NULL, 'NECO_Agric_2024.json', '02d9fe0dcc73705dd1c612839dd6f15df8f5d8e17c8c4a4e02f2ab7ec6cb63ee');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The symbiotic relationship between Rhizobium bacteria and legumes results in _____.', '["Nitrogen fixation","Carbon fixation","Phosphorus mobilization","Soil sterilization"]', 0, 'Rhizobium bacteria live in root nodules and convert atmospheric nitrogen into nitrates that plants can absorb.', NULL, 'NECO_Agric_2024.json', 'af6fa01a0ce6365732856535b0db1190911fa6b65f93f133d1459ed58df742e4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The implement used for the initial breaking and turning of the soil is the _____.', '["Harrow","Ridger","Plough","Planter"]', 2, 'The plough (disc or mouldboard) is used for primary tillage to break up and turn the soil.', NULL, 'NECO_Agric_2024.json', '77de20ba55750dc6eefb19797808ad7933106f8350cda5e81828600c2fa54cd1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which part of the tractor is used to lift and lower implements?', '["Power Take-Off (PTO)","Drawbar","Hydraulic system","Clutch"]', 2, 'The hydraulic system provides the power to raise or lower attached farm tools like ploughs.', NULL, 'NECO_Agric_2024.json', 'afe6c89f6632995e70da87bfb6b4e476fcddf3148baf50ee82c690715798c196');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'A simple farm tool used for harvesting rice is the _____.', '["Spade","Sickle","Pick-axe","Rake"]', 1, 'A sickle has a curved blade suitable for cutting grasses and cereal stalks like rice.', NULL, 'NECO_Agric_2024.json', '8cad5149bb70d669cc1af96125590b02e32db5e6f3fb51cb47f267c507ad5940');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The process of applying water to the soil artificially is called _____.', '["Drainage","Evaporation","Irrigation","Transpiration"]', 2, 'Irrigation ensures plants have enough moisture in areas or seasons with low rainfall.', NULL, 'NECO_Agric_2024.json', '976413d02ec41682b6e4965540b001079391f8fdc904bbf0de8c11d7b90617ec');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is a form of surface irrigation?', '["Sprinkler","Drip","Furrow","Overhead"]', 2, 'Furrow irrigation involves creating small channels (furrows) along the crop rows and filling them with water.', NULL, 'NECO_Agric_2024.json', 'f9916f5851bd21d522125069fd584d4f94313b4b74aba54b2a9679bc9cb409cf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The botanical name for Cowpea is _____.', '["Zea mays","Vigna unguiculata","Oryza sativa","Manihot esculenta"]', 1, 'Vigna unguiculata is the scientific name for cowpea. Zea mays is maize, Oryza sativa is rice.', NULL, 'NECO_Agric_2024.json', 'b432ab86ebb98f9600e890454e7fe466f0fa78938a96198a8e40fe699573717e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is a cereal crop?', '["Groundnut","Cassava","Millet","Soybean"]', 2, 'Cereals are grasses grown for their edible grains. Millet, maize, and sorghum are common cereals.', NULL, 'NECO_Agric_2024.json', 'f3c1ce0563c42fffd1c342bb7da5ea221533ec00ba9a3b6da979e5ac98c025cd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The removal of excess seedlings from a stand is known as _____.', '["Supplying","Thinning","Pruning","Mulching"]', 1, 'Thinning is done to reduce competition for light, space, and nutrients among seedlings.', NULL, 'NECO_Agric_2024.json', 'acc6c5c48926199198221331ece89d36c382441e8d79ff69aa6307b9ab9ab18f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is a viral disease of cassava?', '["Blast","Mosaic","Smut","Red rot"]', 1, 'Cassava Mosaic Disease (CMD) is a well-known viral infection transmitted by whiteflies.', NULL, 'NECO_Agric_2024.json', 'f7c40d90a8b01d35d47f873c71774055ff988d26e3b182998be18acac3f9ec4e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The chemical used specifically to kill weeds is a/an _____.', '["Insecticide","Fungicide","Herbicide","Rodenticide"]', 2, 'Herbicides are pesticides used to kill unwanted plants or weeds.', NULL, 'NECO_Agric_2024.json', '7b55dbca938e7606de1ceaf47ba859a60c60248f46a52d3675d7a58b151eaf08');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following crops is a legume?', '["Yam","Sweet potato","Soybean","Plantain"]', 2, 'Legumes are plants from the family Fabaceae, characterized by seed pods and nitrogen-fixing roots.', NULL, 'NECO_Agric_2024.json', 'cdf283867eb2ebd69fe3bb639125bdb7ced2cf2ed12a1b1a2f0f3ad5b7218f4e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The period between mating and the birth of young in animals is _____.', '["Lactation","Gestation","Incubation","Parturition"]', 1, 'Gestation is the pregnancy period, lasting from conception to birth.', NULL, 'NECO_Agric_2024.json', '6ad2466ef662428505f4918fa882740abf45f660a6318c9a2a7049ab6e7bf278');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is a ruminant animal?', '["Pig","Chicken","Goat","Rabbit"]', 2, 'Goats are ruminants because they have a complex four-compartment stomach and chew the cud.', NULL, 'NECO_Agric_2024.json', '773dfa9a6a7bbc7fed21e05f9a1547e6e4e67b69c4409a4e9ec31315320e677a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The part of the poultry digestive system that grinds food is the _____.', '["Crop","Proventriculus","Gizzard","Cloaca"]', 2, 'The gizzard (ventriculus) contains grit or small stones to mechanically grind down grain and feed.', NULL, 'NECO_Agric_2024.json', '149e1453c564e1bab5fed1bbe4aa9bb1c3aad53f307fa698c5e741922e63453f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Newcastle disease is a highly contagious _____ disease in poultry.', '["Fungal","Bacterial","Viral","Protozoan"]', 2, 'Newcastle disease is caused by a virulent virus and often results in high mortality rates in birds.', NULL, 'NECO_Agric_2024.json', '71ee49e242850c3ba672b58677b733bf2cff6d90fcbe150a3df8a13b328a34c3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The act of giving birth in rabbits is called _____.', '["Farrowing","Kindling","Kidding","Lambing"]', 1, 'Kindling is the term for parturition in rabbits. Farrowing is for pigs, kidding for goats.', NULL, 'NECO_Agric_2024.json', '1021760d83b8617372623eadb2c8ac6c84d824aef85b2e0b5ef5f149fd8db264');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'A castrated male cattle is called a _____.', '["Bull","Steer","Boar","Wether"]', 1, 'A steer is a male bovine castrated before reaching sexual maturity.', NULL, 'NECO_Agric_2024.json', '7423a54a544a8786b0025a6950d3328638e1429289233dac70c8025010c17c93');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The first milk produced by a female animal after birth is called _____.', '["Whole milk","Skimmed milk","Colostrum","Pasteurized milk"]', 2, 'Colostrum is rich in antibodies (immunoglobulins) that provide passive immunity to the newborn.', NULL, 'NECO_Agric_2024.json', '803fb7c913117e38a36c8412666eedc94df875fe4e2dca54c7d13dcf6e827d30');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Ticks and lice are examples of _____ of livestock.', '["Endoparasites","Ectoparasites","Pathogens","Vectors"]', 1, 'Ectoparasites live on the external surface (skin) of the host animal.', NULL, 'NECO_Agric_2024.json', '6e5598e6b79d943cfe6a169d8932c5a02fb4749bcfa86ab244f18f7f8d159128');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is a roughage feed?', '["Maize offal","Groundnut cake","Silage","Fish meal"]', 2, 'Roughages are feeds high in fiber and low in digestible nutrients, such as hay, straw, and silage.', NULL, 'NECO_Agric_2024.json', 'e334b115c6197ba61930f4abf5d5d579c2844e8d21437dbfb4c387d5f62a72ec');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The law of diminishing marginal returns states that as more variable inputs are added to a fixed input, the _____.', '["Total product will increase forever","Marginal product will eventually decrease","Fixed costs will disappear","Average product becomes zero"]', 1, 'This fundamental economic principle states that adding more of one factor of production while holding others constant will eventually yield lower per-unit returns.', NULL, 'NECO_Agric_2024.json', '93c7089838ee65a204fcf8a80a1cafb191042504ac018d6688d1b9bbf36d0d0c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'In farm records, a list of all assets and liabilities of a farm at a specific time is the _____.', '["Cash book","Inventory","Balance sheet","Diary"]', 2, 'A balance sheet (or net worth statement) summarizes the financial position of the farm business.', NULL, 'NECO_Agric_2024.json', 'cb4d0b73a644fd3dc348fea2a399ddfa4ff4b74ee9be0d0a9ec0a4073c3e56ab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The people who buy agricultural produce from farmers and sell to retailers are _____.', '["Consumers","Wholesalers","Processors","Extension agents"]', 1, 'Wholesalers act as middlemen who buy in bulk from producers and distribute to retailers.', NULL, 'NECO_Agric_2024.json', '3529bbd7f2994209c3efe191dc80ccfbae3162ef08e70a158f51547461693c32');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is a fixed cost in agriculture?', '["Cost of seeds","Cost of fertilizers","Interest on land mortgage","Wages of casual labor"]', 2, 'Fixed costs (like interest or insurance) do not change regardless of the level of output in the short run.', NULL, 'NECO_Agric_2024.json', '7c4f7a3cefd86376c437a7d3ff1a9f251e9536df78af09371573f3348bc9e0da');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Agricultural extension aims to _____.', '["Force farmers to grow specific crops","Give free food to rural people","Disseminate research findings to farmers","Collect taxes from farmers"]', 2, 'Extension is an educational process that brings scientific knowledge and modern techniques to farmers to improve productivity.', NULL, 'NECO_Agric_2024.json', '4cfd395373a96335bcdd8ad71f7c9bcf107c8e3c3286501e4ffce8e736182bff');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is a mass media method of extension?', '["Result demonstration","Farm visit","Radio program","Method demonstration"]', 2, 'Radio allows information to reach a very large audience simultaneously, making it a mass contact method.', NULL, 'NECO_Agric_2024.json', '03ec192213b8fc416a87f2a8e9f7a746894dc6b2579eb6ffd743eae2e68e211d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The science of rock study is called _____.', '["Pedology","Geology","Petrology","Physiology"]', 2, 'Petrology is the specific branch of geology that studies the origin, composition, and structure of rocks.', NULL, 'NECO_Agric_2024.json', '8255ddd3f548921f3e2b48cdd9f3708147926bef0a4f97affe0dc80082c07c4a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'A soil with high clay content is likely to have _____.', '["Good drainage","Poor water-holding capacity","High capillarity","Large pore spaces"]', 2, 'Clay has very small pores, which allows water to rise easily through capillary action but makes it prone to waterlogging.', NULL, 'NECO_Agric_2024.json', 'ccdfdf860ea28fb5f3a5dc2ea09a71424f8fa4dd8162fdf94aab31810cbaeb3a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Green manuring involves _____.', '["Applying urea to the soil","Growing a legume and ploughing it into the soil while green","Using animal dung only","Painting the soil green"]', 1, 'Green manure crops are incorporated back into the soil to improve organic matter and nitrogen levels.', NULL, 'NECO_Agric_2024.json', 'dd160855d48bcd458a6ef020b93a97716574c8c961e4b30d0a716b5007997f85');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is a fungal disease of maize?', '["Maize streak","Cassava mosaic","Smut","Citrus tristeza"]', 2, 'Maize smut is caused by a fungus that creates large galls filled with black spores on the ears or tassels.', NULL, 'NECO_Agric_2024.json', 'f0de07c64e81b3c63335fd278c864642f0d6add0c87a0713ab46b9f6547d23a7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'In the nitrogen cycle, the conversion of nitrates to atmospheric nitrogen is _____.', '["Nitrification","Nitrogen fixation","Denitrification","Ammonification"]', 2, 'Denitrification is performed by bacteria in anaerobic conditions, releasing nitrogen gas back into the air.', NULL, 'NECO_Agric_2024.json', 'c95b5866cde1fdc7e2fb610a1333cfa5c5c0a10e0ab3c7b37675d6981cc6388d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The botanical name for Cassava is _____.', '["Oryza sativa","Manihot esculenta","Zea mays","Dioscorea spp"]', 1, 'Manihot esculenta is the scientific name for cassava, a major root tuber in Nigeria.', NULL, 'NECO_Agric_2024.json', '83e1f407ee8d1b951334af5ee6e91035e30bcf946a10f29641c6caf149149caa');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The primary objective of pruning in cocoa is to _____.', '["Increase the height of the tree","Control the shape and improve air circulation","Kill pests on the bark","Ensure the seeds are sweet"]', 1, 'Pruning removes unwanted branches to allow better light penetration and reduce disease spread by improving airflow.', NULL, 'NECO_Agric_2024.json', '358bda4d16188512d70facb0699a04d1cfc80dd4d5eb0ce7b3e39746b8ade80b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is a storage pest of cowpea?', '["Aphid","Stem borer","Pulse beetle (Callosobruchus)","Whitefly"]', 2, 'The cowpea weevil or pulse beetle is the most destructive pest of stored beans.', NULL, 'NECO_Agric_2024.json', '92960f747cd00754ebba6aa8915a6b0ef98ab9c736423a58e01f183640614a8e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'A tractor-mounted implement used for creating ridges is the _____.', '["Harrow","Plough","Ridger","Cultivator"]', 2, 'The ridger is designed to form the mounds or ridges required for planting crops like yams and potatoes.', NULL, 'NECO_Agric_2024.json', 'e278d13e9ff558577cf7218bc54d7f755a683e77b316c6f3951274a6f8a30dae');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The gestation period of a sow (pig) is approximately _____.', '["21 days","114 days","280 days","150 days"]', 1, 'The standard gestation for a pig is 3 months, 3 weeks, and 3 days (roughly 114 days).', NULL, 'NECO_Agric_2024.json', 'b5587869b9c44793a34af879e92fee2b6c8eee8d0ac2febddf8fff1aac815321');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following poultry systems requires the most labor per bird?', '["Battery cage system","Deep litter system","Free range system","Fold system"]', 2, 'While free range has low equipment costs, managing and protecting birds in the open requires significant labor/monitoring compared to intensive systems.', NULL, 'NECO_Agric_2024.json', '15774774e4d6b3e9ba41402698320b99884ef924e5a402930c3c53544cb5765c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The process of removing the horns of an animal is known as _____.', '["Docking","Dehorning","Castration","Culling"]', 1, 'Dehorning prevents animals from injuring each other or the farm handlers.', NULL, 'NECO_Agric_2024.json', '7873e009373ade0fd1abadf283d546874357d7af70931bd807c5e0082952c4a8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'In animal nutrition, maintenance ration is intended to _____.', '["Help the animal gain weight rapidly","Ensure the animal produces more milk","Keep the animal alive without gaining or losing weight","Cure the animal of diseases"]', 2, 'Maintenance ration provides just enough nutrients for vital body processes like heartbeat and breathing.', NULL, 'NECO_Agric_2024.json', '38756308b559321225770dbb2a4dc3d985f135964209a4e2598ad39294f5a08a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is an example of a concentrate feed?', '["Hay","Straw","Soybean meal","Grass"]', 2, 'Concentrates are high in energy or protein and low in fiber, unlike roughages.', NULL, 'NECO_Agric_2024.json', '76c76b01bc98240ab2b59d2a14b8c5652e9607d78cc5a6d908144c217948ea0d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The study of the relationship between organisms and their environment is _____.', '["Anatomy","Ecology","Genetics","Pathology"]', 1, 'Agricultural ecology focuses on how crops and livestock interact with soil, climate, and other organisms.', NULL, 'NECO_Agric_2024.json', '24e4e83a9896485138d06837250b893565186c6e75226fad12b648f91554889f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'A piece of land covered with grasses and legumes for livestock grazing is a _____.', '["Forest","Pasture","Orchard","Nursery"]', 1, 'Pastures are specifically managed land units used for feeding ruminant animals.', NULL, 'NECO_Agric_2024.json', 'd8aef3194338d9ed700939a50a6ec03b1980adc5b84cfb92a917ae9620a99016');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is a biotic factor affecting agricultural production?', '["Soil pH","Rainfall","Pests","Temperature"]', 2, 'Biotic factors are living components; pests, parasites, and weeds are examples.', NULL, 'NECO_Agric_2024.json', '885178774d143bc8c4ebc3e3408f6e8b719f847b1403d3da2cc82f61598bec47');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The process by which plants lose water through their leaves is _____.', '["Translocation","Respiration","Transpiration","Photosynthesis"]', 2, 'Transpiration is the evaporation of water from the stomata of leaves into the atmosphere.', NULL, 'NECO_Agric_2024.json', '03cdd18ebf4ffda3ae5db5f72f9a7a73257dcaefe59e5d7a01eec56150c04ccf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is a metamorphic rock?', '["Granite","Limestone","Marble","Shale"]', 2, 'Marble is formed from the transformation of limestone under high heat and pressure.', NULL, 'NECO_Agric_2024.json', 'e3abdf5b3871e34c6dc38ea6714314d62d0dd82c39af2dee64bfa4ec926703e8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The survey instrument used for measuring horizontal and vertical angles is the _____.', '["Theodolite","Prismatic compass","Measuring tape","Gunter''s chain"]', 0, 'The theodolite is a precision instrument used in land surveying for measuring angles.', NULL, 'NECO_Agric_2024.json', 'afb320d5bc8f1b9170c8cf077cf741f7b1a0d1100f1ee18006fda7ffee676ab2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'A farm record that tracks the day-to-day work done on the farm is the _____.', '["Labour record","Inventory","Cash book","Yield record"]', 0, 'Labour records help the farmer calculate the cost of man-days and manage human resources.', NULL, 'NECO_Agric_2024.json', 'a735aa81f45bd71993db4dec4f40e480c1492957f69f1642d94373dbe190a955');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Monopoly is a market situation characterized by _____.', '["Many buyers and many sellers","A few large sellers","A single seller","Two sellers"]', 2, 'In a monopoly, one firm dominates the supply of a particular product or service.', NULL, 'NECO_Agric_2024.json', 'c7320bafa62ec0cbc9d2433ebd4096f352bf7cd92d7ec93553b04fa764911e83');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The function of farm management which involves setting goals for the future is _____.', '["Organizing","Planning","Coordinating","Directing"]', 1, 'Planning is the foundational management task that decides the ''what, how, and when'' of farm activities.', NULL, 'NECO_Agric_2024.json', '7ae1c2d36dff9c268ef03728f39899912693716ef180c18022bc8855b9bc6ec9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is an example of an indigenous cattle breed in West Africa?', '["Holstein","Jersey","N''dama","Ayrshire"]', 2, 'N''dama is a trypano-tolerant breed native to West Africa, well-adapted to the humid tropics.', NULL, 'NECO_Agric_2024.json', 'e437f302acf57f03fcddc684e6299a5067b536cc750c9b9916970a5be3d38c53');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The act of removing an inferior animal from a herd is known as _____.', '["Castration","Kindling","Culling","Docking"]', 2, 'Culling improves the overall quality of the herd by removing unproductive or diseased animals.', NULL, 'NECO_Agric_2024.json', 'dd3845d9c781f2458720a48d7adb3618d0749f175d688832264b9fc0c6855d87');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The first step in the formation of soil from rocks is _____.', '["Leaching","Weathering","Erosion","Humification"]', 1, 'Weathering is the mechanical and chemical breakdown of rocks into smaller mineral particles.', NULL, 'NECO_Agric_2024.json', 'cc37a3ea5b9a52d7d013979013187047dbed722ffd9885e9c0a707db48df6975');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The type of soil with the highest water-holding capacity is _____.', '["Sandy soil","Silty soil","Clayey soil","Loamy soil"]', 2, 'Due to its very small particle size and narrow pore spaces, clay retains more water than other soil types.', NULL, 'NECO_Agric_2024.json', 'e91bb87f0bba7dd18a03cf35a70b375134308bf393b7632685427f2f79017762');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'An example of a micro-nutrient required in trace amounts by plants is _____.', '["Nitrogen","Potassium","Zinc","Calcium"]', 2, 'Zinc, along with copper and boron, is needed only in very small quantities compared to macronutrients.', NULL, 'NECO_Agric_2024.json', '4ce9b8a9f81eaa7e2b9723a7f28272c0aa6172d18bcd08cda139cb5ad9725807');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is a characteristic of a good irrigation water source?', '["High salt content","Nearness to the farm","High pollution levels","Low reliability"]', 1, 'Proximity to the farm reduces the cost of pumping and transporting water to the fields.', NULL, 'NECO_Agric_2024.json', '23246140d749ac3ef1ee2cde95d7e16c81cab6cc363ba93bb00ab905a6a885ac');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The part of the plant that grows towards a light source exhibits _____.', '["Geotropism","Phototropism","Hydrotropism","Thigmotropism"]', 1, 'Positive phototropism ensures that leaves and stems receive maximum sunlight for photosynthesis.', NULL, 'NECO_Agric_2024.json', '43c9ff8bdabec0a9b3fe0a73c84eb0b14e229a20992be6f79dc04f66874c3b7a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'A crop that completes its life cycle in one growing season is a/an _____.', '["Perennial","Biennial","Annual","Ephemeral"]', 2, 'Annual crops, like maize and rice, germinate, flower, and die within a single year or season.', NULL, 'NECO_Agric_2024.json', '0833072b5716f470db3ceca3e63379976b3f3502c12f903a46550c38b6c9ce55');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following is a viral disease in livestock?', '["Anthrax","Brucellosis","Foot and Mouth Disease","Coccidiosis"]', 2, 'Foot and Mouth Disease (FMD) is a highly infectious viral disease of cloven-hoofed animals.', NULL, 'NECO_Agric_2024.json', '68df6e55835a5680ee132e2e246e0853f822d99179c65be16b42f8f599297b84');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'The primary role of the entrepreneur in agriculture is _____.', '["To do the manual labor","To provide the land","To bear the risks and make decisions","To repair the tractors"]', 2, 'The entrepreneur (farmer) coordinates land, labor, and capital and accepts the financial risk of the enterprise.', NULL, 'NECO_Agric_2024.json', '64318848dd899da750aea737596e785086a9e6167b7cf0e08dfe30ba2f79264e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Agric', 2024, NULL, 'Which of the following helps to maintain soil fertility in a crop rotation system?', '["Continuous cropping","Inclusion of a legume","Monoculture","Excessive irrigation"]', 1, 'Legumes fix nitrogen into the soil, benefiting the subsequent crops in the rotation cycle.', NULL, 'NECO_Agric_2024.json', '5600957a6e84d76fe23db81f478e925316dce409667839133c7d073ba9a80484');
