INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The level of organization of life exemplified by a heart is the _____.', '["Cell","Tissue","Organ","System"]', 2, 'The heart consists of different tissues working together to perform a specific function, which defines the organ level of organization.', NULL, 'NECO_Biology_2024.json', 'fe8ef6c444965656886483a4ef4708add06eea61492d15351a4dd37f5b4ee39a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following cell organelles is responsible for the synthesis of proteins?', '["Ribosome","Mitochondrion","Lysosome","Golgi body"]', 0, 'Ribosomes are the sites of protein synthesis within the cell, often found attached to the rough endoplasmic reticulum.', NULL, 'NECO_Biology_2024.json', '2c4628da12539a1d80a8ded5a78d5d29a99a78d1a6c9b8d87333fe5a51ef4876');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The movement of molecules from a region of higher concentration to a region of lower concentration until equilibrium is reached is _____.', '["Osmosis","Diffusion","Active transport","Plasmolysis"]', 1, 'Diffusion is the passive movement of particles down a concentration gradient. Osmosis involves a semi-permeable membrane and solvent movement.', NULL, 'NECO_Biology_2024.json', 'e209d9c52269e5e7bbc1e4193de742608f9e626e46f43e9570dbfb8d399fdb3e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'In the binomial system of nomenclature, the first name represents the _____.', '["Species","Family","Order","Genus"]', 3, 'Scientific names consist of two parts: the Genus (first, capitalized) and the species (second, lowercase).', NULL, 'NECO_Biology_2024.json', 'b00e4f22a084dfc8af0d57e4f333cd5f5283cd4a14dc4c7dca0759b362af6338');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following organisms exhibits holozoic nutrition?', '["Mushroom","Spirogyra","Amoeba","Tapeworm"]', 2, 'Amoeba ingests solid food particles (phagocytosis), which is the hallmark of holozoic nutrition.', NULL, 'NECO_Biology_2024.json', '841506b524b6a878059353e136566790c85873cd850d4d50469b5ef511c4f351');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The enzyme ptyalin acts on cooked starch to produce _____.', '["Glucose","Maltose","Galactose","Fructose"]', 1, 'Salivary amylase (ptyalin) breaks down complex starch molecules into the disaccharide maltose in the mouth.', NULL, 'NECO_Biology_2024.json', '0ade7daa4d5ead272ea8c6314eecb45e32851149e4f83f7b6f8a62ef3bbc97ba');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'A solution that has a lower osmotic pressure than the cell sap is described as _____.', '["Hypertonic","Isotonic","Hypotonic","Saturated"]', 2, 'A hypotonic solution has a lower solute concentration compared to the cell, leading to water entering the cell via osmosis.', NULL, 'NECO_Biology_2024.json', '370abb4d540cc0419d2d8ebff2468b476df82cac9faa2fcae97ca61dd2caff00');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following blood vessels carries deoxygenated blood from the heart to the lungs?', '["Pulmonary vein","Pulmonary artery","Aorta","Vena cava"]', 1, 'The pulmonary artery is the only artery that carries deoxygenated blood; it takes it to the lungs for gaseous exchange.', NULL, 'NECO_Biology_2024.json', '61463e4db982c62dbcd492476736419e46073758f1900b7e61b69f747860f43f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The part of the mammalian brain responsible for the regulation of body temperature is the _____.', '["Cerebrum","Cerebellum","Medulla oblongata","Hypothalamus"]', 3, 'The hypothalamus acts as the body''s thermostat, coordinating homeostasis, including temperature and thirst.', NULL, 'NECO_Biology_2024.json', '2c8a5cd28f0d68837990ee14f8aafaaa021e8bd761ef5e7278b92c0ecde6fa3d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following is a nitrogen-fixing bacterium found in the root nodules of legumes?', '["Nitrosomonas","Nitrobacter","Rhizobium","Azotobacter"]', 2, 'Rhizobium lives symbiotically in legume roots, converting atmospheric nitrogen into nitrates the plant can use.', NULL, 'NECO_Biology_2024.json', '7d7a517414b3964ebc8fbfa65072f9781f6ae3fcb7085326e1907bbfb0733564');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The process by which green plants lose water through the stomata in the form of vapor is _____.', '["Evaporation","Guttation","Transpiration","Exudation"]', 2, 'Transpiration is the biological loss of water vapor from the aerial parts of plants, primarily the leaves.', NULL, 'NECO_Biology_2024.json', 'd89fb6f798c7632de3d875c1a7b18c3f2ae197b7347016bbae3864f0ad3a8ad1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The structural and functional unit of the kidney is the _____.', '["Neuron","Nephron","Ureter","Cortex"]', 1, 'The nephron is responsible for filtration, reabsorption, and secretion, forming urine in the process.', NULL, 'NECO_Biology_2024.json', '47d4bdd0e9cf8dcc14b13a7fa92a28e5e728bda8b9d31858df7823c44c91041f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'In a cross between a homozygous red flower (RR) and a homozygous white flower (rr), what is the genotype of the F1 generation if red is dominant?', '["RR","rr","Rr","RW"]', 2, 'A cross between RR and rr results in 100% Rr (heterozygous) offspring.', NULL, 'NECO_Biology_2024.json', '13b56b9a4f07754016e0ccfb6b0b01d0ab20ca4649b5f27f278efe419b83ee55');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following is an example of continuous variation?', '["Blood group","Tongue rolling","Fingerprint","Height"]', 3, 'Height shows a range of intermediate phenotypes and is controlled by multiple genes (polygenic), unlike discrete categorical traits.', NULL, 'NECO_Biology_2024.json', '5fc4417b491d24ecbc4d0120fe3aa7fc1f09b25aceacd29013b58f18104cb278');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The sequence of energy flow in an ecosystem is _____.', '["Producer -> Carnivore -> Herbivore","Producer -> Herbivore -> Carnivore","Herbivore -> Producer -> Carnivore","Carnivore -> Herbivore -> Producer"]', 1, 'Energy flows from primary producers (plants) to primary consumers (herbivores) and then to secondary consumers (carnivores).', NULL, 'NECO_Biology_2024.json', '469fd35ca0c2a53448db86947deb9f98ec5ad589cbf7fa2204be4603b0a365e5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following characters is sex-linked in humans?', '["Skin color","Albinism","Color blindness","Intelligence"]', 2, 'Color blindness is a recessive trait carried on the X-chromosome, making it more common in males.', NULL, 'NECO_Biology_2024.json', 'd4e5f46fc49242f0634ce04c2aa7c18cfe3e46e67df518726e66694f2d93c492');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The deficiency of Vitamin D in children leads to _____.', '["Scurvy","Pellagra","Rickets","Beri-beri"]', 2, 'Vitamin D is essential for calcium absorption; its lack causes softening and weakening of bones (rickets).', NULL, 'NECO_Biology_2024.json', '5ae000ce6724243aad673c19aea891151a98f29a963153929b38235674387aff');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The site of gaseous exchange in the mammalian lung is the _____.', '["Bronchus","Trachea","Alveolus","Bronchiole"]', 2, 'Alveoli are thin-walled air sacs where oxygen diffuses into the blood and carbon dioxide diffuses out.', NULL, 'NECO_Biology_2024.json', '29d7f8fd622393c368bffcfb3bb3104d456a0877f1129223014e0c33f4872334');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The hormone that regulates the blood sugar level is _____.', '["Thyroxine","Insulin","Adrenaline","Auxin"]', 1, 'Insulin, secreted by the pancreas, lowers blood glucose levels by promoting glucose uptake by cells.', NULL, 'NECO_Biology_2024.json', 'ff1db502083220a3631e5f1567e8d7dfae952dec585141e94d406fae461e58fe');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following is a function of the liver?', '["Production of bile","Production of digestive enzymes","Filtration of urine","Production of white blood cells"]', 0, 'The liver produces bile, which emulsifies fats to aid digestion. It does not produce digestive enzymes (pancreas/stomach).', NULL, 'NECO_Biology_2024.json', '1f5669e5323e450eb635f9d09ad3d66af141f218e69dd44dcf313f807218ea73');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The movement of a plant part in response to gravity is known as _____.', '["Phototropism","Hydrotropism","Geotropism","Thigmotropism"]', 2, 'Geotropism (or gravitropism) is the growth of plant parts towards (roots) or away (shoots) from the force of gravity.', NULL, 'NECO_Biology_2024.json', '8768297eb6cd86444fabd1065a3d3c020fd6268b82ebe842fe8389aaccb206c7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'A group of organisms of the same species living in a particular habitat at a particular time is a _____.', '["Community","Population","Ecosystem","Niche"]', 1, 'Population refers to members of a single species in a defined area, while community includes all species in that area.', NULL, 'NECO_Biology_2024.json', 'ac29a4b5eba6dc495ef57ae15215d3152d352c031360a75b76e16b30ed41c118');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The dental formula 2/2, 1/1, 2/2, 3/3 represents the dentition of an adult _____.', '["Dog","Human","Rabbit","Sheep"]', 1, 'The human adult dental formula (half-jaw) is 2 incisors, 1 canine, 2 premolars, and 3 molars, totaling 32 teeth.', NULL, 'NECO_Biology_2024.json', 'b2ad5d062b62594e6a2382db37cd3f9065038ca371c719da456dd225bd24ea26');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The tissue that conducts water and dissolved mineral salts from the roots to the leaves is the _____.', '["Phloem","Xylem","Cambium","Pith"]', 1, 'Xylem is the vascular tissue responsible for the upward transport of water and minerals.', NULL, 'NECO_Biology_2024.json', 'a1208991b29d86aa7743c6a0d79d4a0f8ed5511c9873a3b5bb8276b6d3607696');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following is a characteristic of wind-pollinated flowers?', '["Large brightly colored petals","Presence of nectar","Sticky pollen grains","Long feathery stigmas"]', 3, 'Feathery stigmas provide a large surface area to catch wind-borne pollen grains.', NULL, 'NECO_Biology_2024.json', 'bf1a99cd624a1aec8f1239d1491bf62a58f5845e7ebd0eac6eb4aa75736183f0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The process of anaerobic respiration in yeast is called _____.', '["Fermentation","Glycolysis","Oxidation","Transamination"]', 0, 'Fermentation in yeast produces ethanol and carbon dioxide in the absence of oxygen.', NULL, 'NECO_Biology_2024.json', 'cbc09f9a1f51c3574ffc8a5df297c569e9300e68955db06eb6daff17de3df113');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The part of the eye that contains light-sensitive cells is the _____.', '["Choroid","Sclera","Retina","Iris"]', 2, 'The retina contains photoreceptors (rods and cones) that convert light into nerve impulses.', NULL, 'NECO_Biology_2024.json', '0c4ffbd75edadb71512462427d87eb760c33d8a0b9d94783acbd553ba1a90883');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following is a social insect?', '["Housefly","Mosquito","Termite","Cockroach"]', 2, 'Termites live in colonies with a structured division of labor (queen, soldiers, workers), defining them as social.', NULL, 'NECO_Biology_2024.json', 'd52891d96967baa6b96b8ba3047e7431b6c6b15b74b3b39090b867901a6dab5a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The theory of evolution by natural selection was proposed by _____.', '["Jean Lamarck","Charles Darwin","Gregor Mendel","Robert Hooke"]', 1, 'Darwin''s ''The Origin of Species'' detailed how survival of the fittest drives evolutionary change.', NULL, 'NECO_Biology_2024.json', '925047a82daf0fdd7f25899805f64ef0a568f0fc4608ecf895aaca3826187c21');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The maintenance of a constant internal environment is _____.', '["Metabolism","Homeostasis","Osmoregulation","Catabolism"]', 1, 'Homeostasis ensures stable conditions (temperature, pH, water) for optimal body function.', NULL, 'NECO_Biology_2024.json', 'bfdbf2838c6a116a77990511aea4035fc4f76336764504a123d6727ed2ac1c6f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following is NOT an excretory product in plants?', '["Oxygen","Carbon dioxide","Urea","Tannins"]', 2, 'Urea is a nitrogenous waste found in animals. Plants excrete O2, CO2, and secondary metabolites like tannins.', NULL, 'NECO_Biology_2024.json', '758215a517bdd6c02ee90e93cc092b15c0b787c5dba5711653b2f80ed2e6d54c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The enzyme renin is found in the stomach of young mammals to _____.', '["Digest proteins","Curdle milk","Digest fats","Kill bacteria"]', 1, 'Renin (or chymosin) coagulates milk protein (caseinogen) to slow its passage through the gut for better digestion.', NULL, 'NECO_Biology_2024.json', 'ac8cbc06b8d50cd54322535809682b1368932b21db02e951b3ea3a3982c7ae40');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following is an example of a vestigial organ in humans?', '["Liver","Appendix","Kidney","Pancreas"]', 1, 'The appendix is considered vestigial because it has lost its original ancestral function in human digestion.', NULL, 'NECO_Biology_2024.json', '9b08c10db1510f72821502077ee0cf2ff0bbc994df915fab4bcb893a8bf6da12');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The unit of classification that contains organisms that can interbreed to produce fertile offspring is _____.', '["Genus","Order","Species","Class"]', 2, 'The species is the biological unit of reproduction and the most specific rank in classification.', NULL, 'NECO_Biology_2024.json', '5bcc875ce6c4669c2dce2758a85992c8207fedbc90cf3a933b80d86a12d7d1a4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'In the nitrogen cycle, the conversion of nitrates to atmospheric nitrogen is known as _____.', '["Nitrification","Denitrification","Nitrogen fixation","Putrefaction"]', 1, 'Denitrifying bacteria convert nitrates in the soil back into gaseous nitrogen, completing the cycle.', NULL, 'NECO_Biology_2024.json', '6d73a04460eb325e8909701deb8ff223567e6fc070e0984bf3ebb03759e2c093');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following is a physical factor in an ecosystem?', '["Predation","Symbiosis","Temperature","Competition"]', 2, 'Temperature is an abiotic (physical) factor. Predation, symbiosis, and competition are biotic factors.', NULL, 'NECO_Biology_2024.json', '4f017fbff0944fb394795fbe58f83cc71dfad3a7bba131daf6dcaa7ece6050e6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The part of the flower that develops into a fruit after fertilization is the _____.', '["Ovule","Ovary","Stigma","Style"]', 1, 'The ovary ripens into the fruit, while the ovules develop into seeds.', NULL, 'NECO_Biology_2024.json', 'ec1f05f68a7fd63b0888329ff46a7d7e773618b16d3a6105316760a179f6b0bf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following organisms has a single-circuit circulatory system?', '["Fish","Amphibian","Reptile","Mammal"]', 0, 'Fish have a two-chambered heart where blood flows from the heart to the gills, then to the body, and back to the heart in one loop.', NULL, 'NECO_Biology_2024.json', '3d7b904fd8dd312f25c863e82200e14b4938ee3b603928a0da9d0844167f9034');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The vitamin essential for the clotting of blood is _____.', '["Vitamin A","Vitamin B","Vitamin C","Vitamin K"]', 3, 'Vitamin K is a cofactor for enzymes involved in the synthesis of prothrombin and other clotting factors.', NULL, 'NECO_Biology_2024.json', 'fc88dc03bf12adff640709e517c5246ac5c699399d0c72a1f4212d4450961a7d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The phenotypic ratio of the F2 generation in a monohybrid cross according to Mendel''s law is _____.', '["1:2:1","3:1","9:3:3:1","1:1"]', 1, 'In the F2 generation of a monohybrid cross, 3 show the dominant trait and 1 shows the recessive trait.', NULL, 'NECO_Biology_2024.json', '0082fe44efacd3ad2ddb83bd8ec190ee315f71062f77ba61eddf4f5641f4d95d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following bones is part of the axial skeleton?', '["Femur","Humerus","Scapula","Skull"]', 3, 'The axial skeleton consists of the skull, vertebral column, and rib cage. The others are part of the appendicular skeleton.', NULL, 'NECO_Biology_2024.json', '543738aed2cfb3e763e3355fd55ae87575ce713334e527f9a4ce0d2180b4f269');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The symbiotic relationship where both organisms benefit is _____.', '["Parasitism","Commensalism","Mutualism","Saprophytism"]', 2, 'Mutualism is a type of symbiosis where both parties derive advantage (e.g., lichens).', NULL, 'NECO_Biology_2024.json', 'da936b6c2d6489b8a579c54cd135e5982b3aba266a43efad136008f8f9f70920');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following is the respiratory organ of an earthworm?', '["Gills","Lungs","Tracheae","Skin"]', 3, 'Earthworms undergo cutaneous respiration, exchanging gases directly through their moist body surface.', NULL, 'NECO_Biology_2024.json', 'b284f979121f182b84883a5c67f2cb459f07af06f1d6871bd74e3eed6ee713b9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The part of the seed that provides food for the embryo during germination is the _____.', '["Radicle","Plumule","Cotyledon","Testa"]', 2, 'Cotyledons (or endosperm in some seeds) store nutrients required until the first leaves can photosynthesize.', NULL, 'NECO_Biology_2024.json', 'a687a2fcfda977b065f405d238d3b472e5a082800d49f45b9fb9793dc17e64e5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following is a symptom of nitrogen deficiency in plants?', '["Purple leaves","Yellowing of leaves","Stunted root growth","Small fruits"]', 1, 'Chlorosis (yellowing) of older leaves is the primary sign of nitrogen deficiency as chlorophyll production is hindered.', NULL, 'NECO_Biology_2024.json', 'f69ac1a84fc31561b27e7a6c40524bdabee54cda2647be5194806e24b34ba773');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The hormone responsible for the ''fight or flight'' response is _____.', '["Thyroxine","Insulin","Adrenaline","Estrogen"]', 2, 'Adrenaline (epinephrine) increases heart rate and blood flow to muscles during stress or danger.', NULL, 'NECO_Biology_2024.json', '7b00b212f8d0435ef4e877269c34cc08dcb2971054fc90c85e931091be7ed073');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The movement of water across a semi-permeable membrane from a dilute to a concentrated solution is _____.', '["Diffusion","Active transport","Osmosis","Hemolysis"]', 2, 'This is the specific definition of osmosis regarding solvent movement.', NULL, 'NECO_Biology_2024.json', '1c239a9bf302fd5762fe0c2f8aa4e6d2149e86113d617882d30c92a7bcb0c039');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'A cell placed in a hypertonic solution will undergo _____.', '["Turgidity","Plasmolysis","Hemolysis","Cyclosis"]', 1, 'In a hypertonic solution, water leaves the cell, causing the cytoplasm to shrink away from the cell wall.', NULL, 'NECO_Biology_2024.json', '1e6d5855f7389bb8d69756d5445f339876a4f87dab24785f095590eba4033641');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The primary structure for hearing in the mammalian ear is the _____.', '["Pinna","Ossicles","Cochlea","Tympanum"]', 2, 'The cochlea contains the sensory receptors (organ of Corti) that convert sound vibrations into nerve impulses.', NULL, 'NECO_Biology_2024.json', 'ae816385899f9eb0c7aa61f6a8f413570dd6524b7f80b98fd542f3284e843396');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following is a dry indehiscent fruit?', '["Legume","Capsule","Caryopsis","Follicle"]', 2, 'A caryopsis (e.g., maize grain) is a dry fruit that does not split open at maturity.', NULL, 'NECO_Biology_2024.json', '283b028c7db3ff18fbda5f824cb227fc973043e31f18a1fa8d19da97b986b23b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The structural unit of the nervous system is the _____.', '["Brain","Spinal cord","Neuron","Axon"]', 2, 'Neurons are the specialized cells that transmit electrochemical signals throughout the body.', NULL, 'NECO_Biology_2024.json', 'b49c018876baab80ce5b0ccdb337bcc11d772b26d856521eca9a5a5fa3dbfe34');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following organelles is NOT found in an animal cell?', '["Cell membrane","Chloroplast","Nucleus","Mitochondrion"]', 1, 'Chloroplasts are exclusive to plant cells and some protists for the process of photosynthesis.', NULL, 'NECO_Biology_2024.json', 'cb9d353ee294a4356d59b458cf5dafae16995cfbe938c35abd1018052c92d246');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The sequence of stages in complete metamorphosis is _____.', '["Egg -> Larva -> Pupa -> Adult","Egg -> Nymph -> Adult","Egg -> Pupa -> Larva -> Adult","Larva -> Egg -> Pupa -> Adult"]', 0, 'Complete metamorphosis involves four distinct stages: egg, larva, pupa, and adult (imago).', NULL, 'NECO_Biology_2024.json', '9199278e4768e201e71eb5aef7f69a178d603730343c91b2d0656d18ca5217af');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The joint found between the atlas and axis vertebrae is the _____.', '["Hinge joint","Gliding joint","Pivot joint","Saddle joint"]', 2, 'The pivot joint allows for the rotational movement of the head (the ''no'' movement).', NULL, 'NECO_Biology_2024.json', 'e7b761fb832767843ebe27aa57c7c53265c30e21f6b7872682a07f9b2d2daefd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following blood cells is responsible for engulfing bacteria?', '["Erythrocytes","Thrombocytes","Phagocytes","Lymphocytes"]', 2, 'Phagocytes (a type of white blood cell) ingest and destroy pathogens through phagocytosis.', NULL, 'NECO_Biology_2024.json', '237abbba3fa3419c08389ad4eac7af6ab6436bcf5cc9e8942ee516fdd3994335');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The growth response of a plant towards water is _____.', '["Phototropism","Hydrotropism","Geotropism","Chemotropism"]', 1, 'Hydrotropism ensures that roots grow towards moisture in the soil.', NULL, 'NECO_Biology_2024.json', 'b5efab87826ab0cb951937e3d3f063e1e7532323df1d75f5a6587b22ee35cb59');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The instrument used to measure the rate of transpiration is the _____.', '["Photometer","Potometer","Hygrometer","Anemometer"]', 1, 'A potometer measures the rate of water uptake, which is nearly proportional to the rate of transpiration.', NULL, 'NECO_Biology_2024.json', 'f26ea823408f4288681f7705fa8d331033d84c8ea8facf981a77615f11acdbcf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The deficiency of Vitamin A results in _____.', '["Scurvy","Beri-beri","Night blindness","Rickets"]', 2, 'Vitamin A is essential for the health of the retina; its deficiency leads to impaired vision in low light.', NULL, 'NECO_Biology_2024.json', 'b3f82d56ae7d2c0988dac20629fb633af1ade706295ecfaca5dba05fbccef981');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The first step in the testing of a leaf for starch is _____.', '["Adding iodine","Boiling in alcohol","Boiling in water","De-starching the plant"]', 2, 'Boiling the leaf in water kills the cells and stops all chemical reactions before starch extraction.', NULL, 'NECO_Biology_2024.json', '238f3773139627b5f410da025c11ae0e43e8ccc7809ad4f3e51dabd53480f8b4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following is a predatory animal?', '["Goat","Hawk","Sheep","Rabbit"]', 1, 'Hawks are birds of prey (carnivores) that hunt and feed on other animals.', NULL, 'NECO_Biology_2024.json', 'e47defde2fb7aaa20578431ba4d7a74c92cb6c48e603aada64698da9e7a104c8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The term ''Survival of the Fittest'' is associated with _____.', '["Mendel","Lamarck","Darwin","Hooke"]', 2, 'This phrase describes the mechanism of natural selection proposed by Charles Darwin.', NULL, 'NECO_Biology_2024.json', '9f20aa85fcc0ea8808d37f2fae9368d0361555a4cca5be89738970094e886884');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The part of the brain that controls balance and muscular coordination is the _____.', '["Cerebrum","Medulla oblongata","Thalamus","Cerebellum"]', 3, 'The cerebellum coordinates voluntary movements, posture, and equilibrium.', NULL, 'NECO_Biology_2024.json', 'd96150ba19355cc6a71f43bcf8c2d0a324360d8b0755c91af7c6d45f68affac8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following excretory organs is found in insects?', '["Flame cells","Nephridia","Malpighian tubules","Contractile vacuole"]', 2, 'Malpighian tubules extract metabolic wastes from the hemolymph of insects and dump them into the gut.', NULL, 'NECO_Biology_2024.json', '470b544e2e0128d4dd2133dbcd73a3e0eacde94c7e3f21df2c7fdf39cbcc3d16');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The functional part of the chromosome that carries genetic information is the _____.', '["Centromere","Gene","Chromatid","Histone"]', 1, 'Genes are segments of DNA that serve as the basic units of heredity.', NULL, 'NECO_Biology_2024.json', '7ebaf1162ff70a6c2bfb0070d03b1c29780bc6d993ff9d8efa0bbb68e24ef537');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The state of a plant cell when it is fully distended with water is _____.', '["Flaccidity","Turgidity","Plasmolysis","Etiolation"]', 1, 'Turgidity occurs when the cell membrane pushes against the cell wall due to high internal osmotic pressure.', NULL, 'NECO_Biology_2024.json', '4592dbbb4e840aa5c1cc78b4d757c68f31f91bdc18ccc89c2fd5171f96f64877');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following is a polysaccharide?', '["Glucose","Sucrose","Cellulose","Maltose"]', 2, 'Cellulose is a complex carbohydrate made of many glucose units. Glucose is a monosaccharide; sucrose and maltose are disaccharides.', NULL, 'NECO_Biology_2024.json', '57b9e64758173b2cd61c5fec1c693990844ab7e96479bd2bc7c4b80e3a4cb820');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The part of the mammalian heart with the thickest muscular wall is the _____.', '["Right atrium","Left atrium","Right ventricle","Left ventricle"]', 3, 'The left ventricle must pump blood under high pressure to the entire body, necessitating a thicker wall.', NULL, 'NECO_Biology_2024.json', '6f5c8e839a3d80b8f42ca23d82463b4de239dc0cb7641c0cfd7c913d2cda8181');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'Which of the following is NOT an evidence of evolution?', '["Fossil records","Comparative anatomy","Embryology","The size of the population"]', 3, 'Population size is a demographic factor, whereas fossils, anatomy, and embryology provide structural/historical proof of change.', NULL, 'NECO_Biology_2024.json', 'caaac238c05cadb9ff2c4c4565b396fd3505224e39d53993a970521ba143ae25');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'The process by which an organism maintains a constant internal salt and water balance is _____.', '["Excretion","Osmoregulation","Homeostasis","Secretion"]', 1, 'Osmoregulation specifically focuses on the balance of water and electrolytes.', NULL, 'NECO_Biology_2024.json', '4105f6e55811389c02e98035ef5339465e5d44a4a83c1c01432e52dcd50b3005');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Biology', 2024, NULL, 'A collection of similar cells performing a specific function is a _____.', '["Organ","Tissue","System","Organism"]', 1, 'Tissues are the next level of organization above cells (e.g., muscle tissue).', NULL, 'NECO_Biology_2024.json', '6b18edb18b3e33c267589748f62f7c397537d3a1f78a003cb41bd5a2f321b8c2');
