INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'According to the first account of creation, God created the firmament on the _____ day.', '["first","second","third","fourth"]', 1, 'In Genesis 1:6-8, God created the firmament (the expanse) on the second day to separate the waters from the waters.', NULL, 'NECO_CRS_2024.json', '58d072f811d6ab6db07ebe50fd6b8608f8acacaa6dc7abb2dab15cc3376c158d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The creation of man in the second account of creation was primarily from _____.', '["the spoken word of God","the dust of the ground","the rib of an animal","the water of the sea"]', 1, 'Genesis 2:7 states that the Lord God formed man of dust from the ground and breathed into his nostrils the breath of life.', NULL, 'NECO_CRS_2024.json', '4690bea86c2610cb8e14de5504f2fac13c6a63a06f85295564a48efc8e15cb6c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Joseph was sold by his brothers to the Ishmaelites for _____ pieces of silver.', '["ten","twenty","thirty","fifty"]', 1, 'According to Genesis 37:28, Joseph''s brothers sold him to the Midianite/Ishmaelite traders for twenty shekels of silver.', NULL, 'NECO_CRS_2024.json', 'd2eb02569239ba447132dda8233c9bf759406edcdc15280389e565e002727d95');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'God''s promise to Abraham that he would be the father of many nations was sealed with the sign of _____.', '["circumcision","baptism","a rainbow","sacrificing a bull"]', 0, 'In Genesis 17, God established circumcision as the physical sign of the covenant between Him and Abraham''s descendants.', NULL, 'NECO_CRS_2024.json', '80510ae7d6020b39456506059142bb490a270601caeebe694dd8f250aa5f613a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Moses'' father-in-law, who advised him on how to delegate judicial duties, was _____.', '["Aaron","Joshua","Jethro","Potiphera"]', 2, 'Jethro, the priest of Midian, observed Moses wearing himself out and advised him to appoint capable men as leaders over thousands, hundreds, fifties, and tens.', NULL, 'NECO_CRS_2024.json', '1ca071e92c9092d3b2c8943daa5cf31254bc0755e3704fdcc5361b4c2d5a1e01');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The passover feast was instituted in Egypt to commemorate the _____.', '["crossing of the Red Sea","giving of the Ten Commandments","sparing of the first-born of the Israelites","destruction of the Egyptian crops"]', 2, 'The Passover was established so the Angel of Death would pass over the houses marked with lamb''s blood, sparing the Israelite first-borns.', NULL, 'NECO_CRS_2024.json', '67fa734a7861747eabd81d015409473d7cd71ae477568b6b6a39eb98efe95fd6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The golden calf made by the Israelites in the wilderness was facilitated by _____.', '["Moses","Joshua","Aaron","Hur"]', 2, 'While Moses was on Mount Sinai, the people pressured Aaron, who took their gold and fashioned it into a molten calf.', NULL, 'NECO_CRS_2024.json', '624a8caacd973d43d35be56e7193b6697a4f5d4a72f532488226476ccbab0c7d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Which of the following women was a judge in Israel?', '["Ruth","Deborah","Esther","Naomi"]', 1, 'Deborah was a prophetess and the only female judge mentioned in the Book of Judges who led Israel to victory over Jabin''s army.', NULL, 'NECO_CRS_2024.json', '48fb6ffea34753ff5b5dc21e7ea2b9bdeb41ec984dc9d2c9e59a4fe3200ce56c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The high priest who fell and died upon hearing that the Ark of God had been captured was _____.', '["Eli","Samuel","Hophni","Phinehas"]', 0, 'Eli died at age ninety-eight when he heard the news of the capture of the Ark and the death of his two sons.', NULL, 'NECO_CRS_2024.json', 'a72d2e5e1d61439ed6d2784d5a74cfe7c0f2bcc0c78871503e801462d8c0af11');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Saul was rejected as king over Israel primarily because of his _____.', '["defeat in battle","uncontrolled anger","disobedience to God''s command regarding the Amalekites","attempt to kill David"]', 2, '1 Samuel 15 records that Saul spared Agag and the best of the livestock, violating God''s command of total destruction (herem).', NULL, 'NECO_CRS_2024.json', '0a019bb68365ca84d83e091c159bc4238d9bc7f6551e6bd114cd3f7fd46eca23');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'David''s sin with Bathsheba was exposed by the prophet _____.', '["Samuel","Nathan","Gad","Elijah"]', 1, 'Prophet Nathan used a parable about a rich man stealing a poor man''s ewe lamb to convict David of his adultery and murder.', NULL, 'NECO_CRS_2024.json', 'c330e67a999faf217e516ce990ab025c4705b37bcf948c604237c42712dda078');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The wisdom of Solomon was notably demonstrated in his judgment between _____.', '["two brothers fighting for land","two harlots claiming a living child","two priests arguing over sacrifice","two kings planning a war"]', 1, 'Solomon proposed to divide the living child in half, knowing the real mother would prefer to give up the child than see it killed.', NULL, 'NECO_CRS_2024.json', '84ef4c9488268d9d6a6d281e1fab4a48bc23daaeaf3032eb09d496acd6dedb53');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The division of the kingdom of Israel took place during the reign of _____.', '["Solomon","Rehoboam","Jeroboam","Asa"]', 1, 'Rehoboam''s refusal to lighten the labor yoke imposed by his father Solomon led to the rebellion of the ten northern tribes.', NULL, 'NECO_CRS_2024.json', '0dbdd63c85255f05667cb1012c0ddbf112c3f41a2b104ef46a58c63f79676cad');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Elijah''s contest with the prophets of Baal took place on Mount _____.', '["Sinai","Nebo","Carmel","Hermon"]', 2, 'Mount Carmel was the site where Elijah proved that Yahweh is God by calling down fire to consume the sacrifice.', NULL, 'NECO_CRS_2024.json', '1cca899ff7667db159ce3346af5aa1bfa79a8c9c4d0ff38f31d2338e47787cb3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The prophet who was a shepherd from Tekoa and preached against social injustice was _____.', '["Hosea","Isaiah","Amos","Jeremiah"]', 2, 'Amos was a simple shepherd and dresser of sycamore trees who fearlessly condemned the wealthy for oppressing the poor.', NULL, 'NECO_CRS_2024.json', '36931b26e8d62c90b13e5fe881f203311155c0f69c752e5528998d4acef0bf31');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Hosea’s marriage to _____ was a symbolic representation of God’s relationship with unfaithful Israel.', '["Jezebel","Gomer","Rahab","Delilah"]', 1, 'God commanded Hosea to marry an unfaithful woman (Gomer) to illustrate Israel''s spiritual adultery through idol worship.', NULL, 'NECO_CRS_2024.json', 'bedf5c6de4df01841f2c22a225c20d2d31b5513e23e3c34052153e5550dc4ef3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The king of Babylon who destroyed Jerusalem and took the people into exile was _____.', '["Cyrus","Darius","Nebuchadnezzar","Sennacherib"]', 2, 'Nebuchadnezzar II led the siege that resulted in the burning of the Temple and the deportation of the Jews to Babylon.', NULL, 'NECO_CRS_2024.json', '3156b54b4eedec422f36bd45795244332f6516051ac3901a38ddf6074ef5baea');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Nehemiah''s primary mission in Jerusalem was to _____.', '["rebuild the Temple","rebuild the walls of the city","reform the priesthood","fight the Samaritans"]', 1, 'Nehemiah was the cupbearer to the Persian king who obtained permission to return to Jerusalem to rebuild its broken walls.', NULL, 'NECO_CRS_2024.json', '62c6635d99277ff3ad30a7cf727a710b813ab29b4657707308c873f4c11bcdba');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'According to the Gospel of Luke, the angel who announced the birth of Jesus to Mary was _____.', '["Michael","Uriel","Gabriel","Raphael"]', 2, 'Luke 1:26 states that the angel Gabriel was sent from God to a city in Galilee named Nazareth.', NULL, 'NECO_CRS_2024.json', '529127ccc41cdc32f364427de19e14337e9932b6bec08f5aed0c661fcded9e6d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Jesus was born in Bethlehem during the census ordered by _____.', '["Herod the Great","Augustus Caesar","Tiberius Caesar","Pontius Pilate"]', 1, 'Luke 2 records that a decree went out from Caesar Augustus that all the world should be registered.', NULL, 'NECO_CRS_2024.json', '8259f6bb95471899cf3cafee174f084fb98022fc98c98591ae92c09ec2b47aff');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'John the Baptist''s message centered on ''Repent, for the _____ is at hand''.', '["Judgment of God","Kingdom of Heaven","End of the World","Day of the Lord"]', 1, 'Matthew 3:2 records John preaching in the wilderness of Judea, announcing the proximity of the Kingdom of Heaven.', NULL, 'NECO_CRS_2024.json', '6f5c02684d6405aee0f78131f61675ece18b334d4d8e8c74cba16f4929722560');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Jesus was baptized by John in the River Jordan to _____.', '["wash away His sins","fulfill all righteousness","show He was a disciple of John","become a Jewish priest"]', 1, 'In Matthew 3:15, Jesus told John to permit the baptism to ''fulfill all righteousness'', identifying with humanity.', NULL, 'NECO_CRS_2024.json', 'f850c0875d192ed1f5229730293c04eae4af55b159b994d6242e7b20e249e1d3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'During the temptation, the devil asked Jesus to turn stones into bread to test His _____.', '["patience","miraculous power","humanity/sonship","faith in the Word"]', 2, 'The temptation ''If you are the Son of God...'' was an attempt to make Jesus use His divine power for selfish physical needs.', NULL, 'NECO_CRS_2024.json', '0be4f9a54ee9e9279220f0fe906654ccbbb82e635234ae4f88e6a12a01cbf48f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The first four disciples called by Jesus were _____.', '["Peter, Andrew, James and John","Philip, Bartholomew, Thomas and Matthew","James, Jude, Simon and Judas","Peter, John, Philip and Thomas"]', 0, 'Mark 1:16-20 records the calling of the two pairs of brothers: Simon (Peter) and Andrew, then James and John.', NULL, 'NECO_CRS_2024.json', '1f6aaf9c3bb29d2952fd14f1840bdea1e99fbc323e8496af1aa2dafc120286fb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'In the Sermon on the Mount, Jesus taught that the _____ shall inherit the earth.', '["poor in spirit","merciful","meek","pure in heart"]', 2, 'Matthew 5:5 (The Beatitudes) states: ''Blessed are the meek, for they shall inherit the earth''.', NULL, 'NECO_CRS_2024.json', '7b21f9d895912211869ea6f47d94df57ee64580e0b0b7d6117e5434a65a57707');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The miracle of the feeding of the five thousand involved _____.', '["seven loaves and a few fish","five loaves and two fish","ten loaves and five fish","two loaves and five fish"]', 1, 'Matthew 14:17 specifies the boy''s offering was five barley loaves and two fish.', NULL, 'NECO_CRS_2024.json', '556e2a64463e11969ce74f2c941caf4f9d0d1436e4eafd8a9d9db27660ebfd70');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The Transfiguration of Jesus took place in the presence of _____.', '["Peter, James and Andrew","Peter, James and John","All twelve apostles","Mary and Martha"]', 1, 'Jesus took the inner circle of Peter, James, and John up into a high mountain where He was transfigured before them.', NULL, 'NECO_CRS_2024.json', 'a64f9f16808523048b9338df0ac44eb73d64cbcb73e6b05ac285e2f1bbf3917b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'In the parable of the Good Samaritan, the two religious figures who passed by the wounded man were a _____ and a _____.', '["Priest / Pharisee","Priest / Levite","Levite / Scribe","Pharisee / Sadducee"]', 1, 'Luke 10:31-32 mentions that first a priest and then a Levite saw the man and passed by on the other side.', NULL, 'NECO_CRS_2024.json', '5cae7b3ff726b1f14ad4175f07a85888c50dde677fb54fe79065f3788cc7b52d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The parable of the Prodigal Son was primarily told to illustrate _____.', '["the dangers of wastefulness","the importance of farming","the love and forgiveness of God","the jealousy of siblings"]', 2, 'The father''s reception of the lost son represents God''s joy and eagerness to welcome back repentant sinners.', NULL, 'NECO_CRS_2024.json', '33930782a954bcf82e29cc58f0718510188144e49d3d09732b59429f5244d044');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The request of the sons of Zebedee for positions of honor in Jesus’ kingdom showed their _____.', '["faith in Jesus","humility","ambition and lack of understanding","love for the church"]', 2, 'James and John sought seats at the right and left of Jesus, failing to understand that greatness in His kingdom comes through service and suffering.', NULL, 'NECO_CRS_2024.json', 'c3cb200931ba6c4eec966998312df3e592995c0f4b6b93bddbd5a75a910974fe');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Jesus'' triumphal entry into Jerusalem on a donkey was a fulfillment of the prophecy of _____.', '["Isaiah","Jeremiah","Zechariah","Malachi"]', 2, 'Zechariah 9:9 prophesied the King coming to Zion ''humble and riding on a donkey''.', NULL, 'NECO_CRS_2024.json', '1ef1afc38284d0049ec15fa8f15dd959ff766274d21d5408a1ce04dd3a2b92fd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'At the Last Supper, the bread represents Jesus’ _____.', '["spirit","word","body","suffering"]', 2, 'Jesus took bread, blessed it, and said, ''Take, eat; this is my body'' (Matthew 26:26).', NULL, 'NECO_CRS_2024.json', 'c53e1774ce70aebe34d7bb7bdb3823277b5c89f0749f23b80ae70dcc8efd1581');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The garden where Jesus prayed in agony before His arrest was _____.', '["Eden","Gethsemane","Golgotha","Bethany"]', 1, 'Gethsemane, located on the Mount of Olives, was the site where Jesus asked that ''this cup'' might pass from Him.', NULL, 'NECO_CRS_2024.json', 'b5eafa6e4eb0a0ef4a575134988b99b56030f4c84d67ec4e19285599f094f8d5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Judas Iscariot betrayed Jesus with a _____.', '["handshake","hug","kiss","pointed finger"]', 2, 'Judas used a kiss as the signal to the soldiers to identify which man was Jesus.', NULL, 'NECO_CRS_2024.json', 'c9c928f28ea1fd1d0589962e6095a42de051775fcc90252fc3b66100419fe757');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The Jewish high priest who presided over the trial of Jesus was _____.', '["Annas","Caiaphas","Gamaliel","Nicodemus"]', 1, 'Caiaphas was the high priest that year who organized the plot to kill Jesus.', NULL, 'NECO_CRS_2024.json', '5578cc51806ac4a424f7ff6af21740e72d50d6fa4b7454d57f0025e0e1c16147');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The Roman Governor who reluctantly sentenced Jesus to death was _____.', '["Herod Antipas","Felix","Festus","Pontius Pilate"]', 3, 'Pilate found no guilt in Jesus but gave in to the pressure of the crowd to avoid a riot.', NULL, 'NECO_CRS_2024.json', 'df3d61ad671d046dc318676e16f5f76016fb30e753995befcf7f6ce6869a6e30');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The criminal who was released instead of Jesus was _____.', '["Barabbas","Barnabas","Silas","Dismas"]', 0, 'The crowd chose Barabbas, a notorious prisoner/insurrectionist, to be released according to the custom of the feast.', NULL, 'NECO_CRS_2024.json', 'dfb9d2bcc4a5af96c11ee8df083a91f9395f4fe0e358556d4b6176fb6873ae01');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Jesus was crucified at a place called Golgotha, which means _____.', '["House of Bread","City of David","Place of the Skull","Garden of Peace"]', 2, 'Golgotha is an Aramaic word meaning ''Skull'', referring to the hill''s shape or its function as an execution site.', NULL, 'NECO_CRS_2024.json', '7c179eb85fd915bc17a0f1abf6b5a4f918f9f0a939d097090120e21a442fbfcc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The person who provided the tomb for the burial of Jesus was _____.', '["Simon of Cyrene","Joseph of Arimathea","Nicodemus","Lazarus"]', 1, 'Joseph of Arimathea, a wealthy member of the Council, asked Pilate for the body and placed it in his own new tomb.', NULL, 'NECO_CRS_2024.json', '8ef83773ef6736c4700a20000dd24464744517b481e23678fc21fec7b45910f8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The resurrection of Jesus took place on the _____ day.', '["first","second","third","seventh"]', 2, 'Biblical accounts and creeds affirm that Jesus rose from the dead on the third day (Friday to Sunday morning).', NULL, 'NECO_CRS_2024.json', 'c3aea1bcc527cc32a217533f2b3c7a9d8c6ed45b12e5459861b32fd9e47fed81');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Before His ascension, Jesus commanded His disciples to wait in Jerusalem for the _____.', '["return of Elijah","Promise of the Father (Holy Spirit)","Day of Judgment","Establishment of the Temple"]', 1, 'Acts 1:4-5 records Jesus telling them to wait for the Holy Spirit who would empower them.', NULL, 'NECO_CRS_2024.json', '33c176be6e8daceed822574c78a8dd923290117bfa1327b40ee89c2816fe7dd0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The replacement for Judas Iscariot among the twelve apostles was _____.', '["Paul","Barnabas","Matthias","Stephen"]', 2, 'In Acts 1, the disciples cast lots and the lot fell on Matthias to join the eleven apostles.', NULL, 'NECO_CRS_2024.json', 'db67156fb9f92b6606a5eb59ed0b98197f3b48a0f43f798a999ada9ea2f80574');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The Holy Spirit descended on the disciples on the Day of _____.', '["Passover","Tabernacles","Pentecost","Purim"]', 2, 'Pentecost, a Jewish harvest festival occurring 50 days after Passover, was when the disciples spoke in tongues as the Spirit gave them utterance.', NULL, 'NECO_CRS_2024.json', '723f9055141ad960a74d13e59abecf6830704a7714608828bde48b14fa041322');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The first Christian martyr was _____.', '["James","Peter","Stephen","Philip"]', 2, 'Stephen, one of the first seven deacons, was stoned to death for his testimony about Jesus (Acts 7).', NULL, 'NECO_CRS_2024.json', '9285ede111ab87e2a238900b0eb96c3e3b58e31e190c5f80bfeeebd178bc2b30');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Saul''s conversion took place on the road to _____.', '["Damascus","Antioch","Rome","Tarsus"]', 0, 'Saul was traveling to Damascus to arrest Christians when he was blinded by a light and heard the voice of Jesus.', NULL, 'NECO_CRS_2024.json', '233aab449f88064c77cebc52275181a3dda6e9c5858bc07366cdaa385d33c97d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The first place where the disciples were called ''Christians'' was _____.', '["Jerusalem","Antioch","Ephesus","Rome"]', 1, 'Acts 11:26 notes that it was in Antioch (Syria) that the name ''Christian'' was first applied to believers.', NULL, 'NECO_CRS_2024.json', 'cf165382ce45524341ef98e426a05aef1d6001e99202c1130e5f5f46db9b7a89');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The Jerusalem Council (Acts 15) met primarily to discuss _____.', '["how to distribute food","the collection for the poor","the circumcision of Gentile converts","Paul''s authority as an apostle"]', 2, 'The council determined that Gentile believers did not need to be circumcised or follow the whole Mosaic Law to be saved.', NULL, 'NECO_CRS_2024.json', '63cb8ab9eb3c60f66407d37add6c5f4423256d95b0494ab727f72673c87c6634');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Paul was known as the ''Apostle to the _____''.', '["Jews","Gentiles","Romans","Greeks"]', 1, 'Paul received a specific commission to preach the Gospel to the non-Jewish world (Gentiles).', NULL, 'NECO_CRS_2024.json', '7590ac7df9b92e7b481fac7ff67ca7a25c680e52d4d12b2c62e4d4b1d36b1516');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'According to Paul in 1 Corinthians 13, the greatest virtue is _____.', '["faith","hope","love","wisdom"]', 2, 'Paul concludes the chapter by stating: ''So now faith, hope, and love abide... but the greatest of these is love''.', NULL, 'NECO_CRS_2024.json', '22d6e4150c75d1785857e81f8042564c6bb9b143c27724508d6bc99d697cf7ce');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'James teaches that ''faith by itself, if it has no _____, is dead''.', '["preaching","works","fasting","knowledge"]', 1, 'James 2:17 emphasizes that true saving faith will naturally result in good deeds or ''works''.', NULL, 'NECO_CRS_2024.json', 'a7acc149a90548fec28414cba594d64d625ea04c97bb5d73b3b63c4f6c3041e4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The person who helped Jesus carry the cross was _____.', '["Simon Peter","Simon of Cyrene","Joseph of Arimathea","John the Beloved"]', 1, 'As Jesus was led away, the soldiers seized Simon of Cyrene and laid the cross on him to carry it behind Jesus.', NULL, 'NECO_CRS_2024.json', '6a75bda778925fecbc2b0500fca131fccb5695385782eefaf4e14fd8bfa18c8b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'God''s promise to Noah was symbolized by a _____.', '["rainbow","stone altar","burning bush","pillar of fire"]', 0, 'Genesis 9:13 describes the rainbow as the sign of the covenant that God would never again destroy all life with a flood.', NULL, 'NECO_CRS_2024.json', '73b9572934c81c954d77671219ca8c114e57ce09339221a1cc5e15f7bd76d627');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The son of Abraham born to the Egyptian maid Hagar was _____.', '["Isaac","Ishmael","Jacob","Esau"]', 1, 'Ishmael was Abraham''s first son, born when Sarah remained childless.', NULL, 'NECO_CRS_2024.json', 'b893021973e3f53a515413ad830461ca7f7f49d06a4106bc13d553f17f125683');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The first king of Israel was _____.', '["David","Saul","Solomon","Samuel"]', 1, 'Saul was anointed by Samuel after the people of Israel demanded a king to be like other nations.', NULL, 'NECO_CRS_2024.json', 'c7eb0c23ce0b47c4889cc4ce9004454461e9f813e8cd73b045d343fd681fec1b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The city of Jericho was captured by the Israelites under the leadership of _____.', '["Moses","Joshua","Caleb","Gideon"]', 1, 'Joshua led the miraculous fall of Jericho''s walls after circling the city for seven days.', NULL, 'NECO_CRS_2024.json', 'e8c31b4883511c318acef16259e7ac0cfcef810c6c98227e2fb3ffd59db9078a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Samson''s strength was tied to his vow as a _____.', '["Priest","Prophet","Nazirite","King"]', 2, 'As a Nazirite, Samson was consecrated to God from birth, and one of his conditions was never to cut his hair.', NULL, 'NECO_CRS_2024.json', '8da12671be8a31e322de3f329812a656901671a210026611476dc67dd77c8f80');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The mother of Samuel was _____.', '["Hannah","Peninnah","Naomi","Ruth"]', 0, 'Hannah was barren but prayed fervently at the temple in Shiloh, and God gave her Samuel.', NULL, 'NECO_CRS_2024.json', '966715edbcbcb8ede44ea4c1197ba0d7a59527564b8e476685db58788c6cad2c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'Solomon built the Temple of the Lord in the city of _____.', '["Bethlehem","Hebron","Jerusalem","Samaria"]', 2, 'Jerusalem was the capital and the religious center where the First Temple was constructed.', NULL, 'NECO_CRS_2024.json', '08f67463d16a0f9e4be1f978fcb93d368f6ceb375521acc26fb10e3f4907211e');
