INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'CRS', 2024, NULL, 'The ''Valley of Dry Bones'' vision was seen by Prophet _____.', '["Isaiah","Jeremiah","Ezekiel","Daniel"]', 2, 'Ezekiel 37 records this vision symbolizing the restoration and spiritual revival of the house of Israel.', NULL, 'NECO_CRS_2024.json', 'dbf4cb71bd51cc421ddfb085d670b112c121b99060c6e79644155f475fc7a7fe');
