INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Chemistry', 2024, NULL, 'Which of the following processes is used to separate a mixture of iodine and common salt?', '["Distillation","Sublimation","Filtration","Evaporation"]', 1, 'Iodine is a substance that undergoes sublimation (changes from solid to gas directly), while common salt does not. Heating the mixture allows the iodine to be collected as a vapor.', NULL, 'NECO_Chemistry_2024.json', 'fa83ba8d6551dc3f6f90a443d69f55b951a14009fc24bab60af382e0bb8e6409');
