INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Chemistry', 2024, NULL, 'Which of the following statements is true of the isotopes of an element?', '["They have the same mass number","They have the same number of neutrons","They have the same atomic number","They have different chemical properties"]', 2, 'Isotopes are atoms of the same element with the same atomic number (number of protons) but different mass numbers due to different numbers of neutrons.', NULL, 'NECO_Chemistry_2024.json', '33b2fa5d1b4af356d76c1dac9968f1e95d8e59bcb52baa75d017ae1409c2303b');
