INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Chemistry', 2024, NULL, 'Which of the following elements has the highest electronegativity?', '["Chlorine","Fluorine","Oxygen","Nitrogen"]', 1, 'Fluorine is the most electronegative element in the periodic table because it has the strongest tendency to attract a shared pair of electrons.', NULL, 'NECO_Chemistry_2024.json', 'bcecfe1fabab8f7212dabed562d89df5a2860c84ffb53a0a0c3fd7d379f71b5f');
