INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Chemistry', 2024, NULL, 'A solution with pH 3 is _____.', '["Strongly alkaline","Weakly alkaline","Strongly acidic","Weakly acidic"]', 2, 'The pH scale ranges from 0 to 14. 7 is neutral; values from 0-3 are generally considered strongly acidic.', NULL, 'NECO_Chemistry_2024.json', '4037fa61bf4aeecf45ecfa169cafc30068254efb6cb200f84be68b7a1152235b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Chemistry', 2024, NULL, 'Which of the following salts is used in the laboratory to dry gases?', '["\r\n𝑁\r\n𝑎\r\n𝐶\r\n𝑙\r\nNaCl\r\n","\r\n𝐶\r\n𝑎\r\n𝐶\r\n𝑙\r\n2\r\nCaCl\r\n2\r\n\t​\r\n\r\n (anhydrous)","\r\n𝐶\r\n𝑢\r\n𝑆\r\n𝑂\r\n4\r\n.5\r\n𝐻\r\n2\r\n𝑂\r\nCuSO\r\n4\r\n\t​\r\n\r\n.5H\r\n2\r\n\t​\r\n\r\nO\r\n","\r\n𝑁\r\n𝑎\r\n2\r\n𝐶\r\n𝑂\r\n3\r\nNa\r\n2\r\n\t​\r\n\r\nCO\r\n3\r\n\t​\r\n\r\n"]', 1, 'Anhydrous Calcium Chloride is hygroscopic and is commonly used as a desiccant (drying agent) in desiccators.', NULL, 'NECO_Chemistry_2024.json', '5a47c21767b8b14bb7b5b179c31d5a76c64a7a735e2bf6bb1d0aafa70cd09997');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Chemistry', 2024, NULL, 'The loss of water of crystallization to the atmosphere by a salt is known as _____.', '["Deliquescence","Hygroscopy","Efflorescence","Hydrolysis"]', 2, 'Efflorescence is the property of some hydrated salts to lose their water of crystallization when exposed to air.', NULL, 'NECO_Chemistry_2024.json', '08c28147c26de21713d453d36b1ffa2a39e248800dc8bc58542874cc9241ef17');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Chemistry', 2024, NULL, 'Which of the following factors will NOT affect the solubility of a gas in a liquid?', '["Nature of solvent","Pressure","Temperature","Stirring"]', 3, 'Stirring affects the rate of dissolving, not the actual solubility (the maximum amount that can dissolve) of a gas.', NULL, 'NECO_Chemistry_2024.json', '3c16ecf2da890c8044cd829f246b1b2bb9764ebe39a08498aa91eeaecb5f22a8');
