INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The totality of the beliefs and ideas that a person or group considers important and useful is called _____.', '["Norms","Apathy","Values","Culture"]', 2, 'Values represent the principles or standards of behavior; they are the internal judgments of what is right, useful, or important in a society.', NULL, 'NECO_Civic_2024.json', 'e188f171649fdccb3fd6ddaf71f8adae4792851fc7550ee554a3a800000045e0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'A core attribute of honesty is _____.', '["Dishonesty","Discipline","Integrity","Kindness"]', 2, 'Integrity involves being honest and having strong moral principles. It is the quality of being whole and undivided in truthfulness.', NULL, 'NECO_Civic_2024.json', 'f61373f72d077248a0497f79449e2bdd39526b0185ffc2590aa60a25875587ab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The ability to depend on one’s own effort and abilities to satisfy needs is known as _____.', '["Self-interest","Self-reliance","Self-glory","Selfishness"]', 1, 'Self-reliance is a key value in Civic Education that encourages individuals to be independent and resourceful rather than waiting for external aid.', NULL, 'NECO_Civic_2024.json', '567dd859db6e4f41a821651cd59c6d3ea73ea6dba35b3f6502638a52c79352fc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Which of the following is a way through which Nigerian citizenship can be acquired?', '["By migration","By force","By naturalization","By theft"]', 2, 'The Nigerian constitution identifies three ways of acquiring citizenship: Birth, Registration, and Naturalization.', NULL, 'NECO_Civic_2024.json', '48586a3b7b4e6add7d8a2ea56046796ae36d0803b0f5ec708d6a7b1073e27562');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The process of depriving a person of his citizenship is called _____.', '["Renunciation","Deprivation","Expatriation","Disenfranchisement"]', 1, 'Deprivation occurs when the state legally strips an individual of their citizenship, usually due to criminal acts or fraud in naturalization.', NULL, 'NECO_Civic_2024.json', '67a8843a39cd20d33e4968f27cde94d08887a42c3091c6ac35ced171b1d15d0e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'A citizen by registration is a person who _____.', '["Is born in Nigeria","Is married to a Nigerian citizen","Found a job in Nigeria","Studied in Nigeria"]', 1, 'According to Section 26 of the 1999 Constitution, a non-Nigerian woman married to a Nigerian man can become a citizen through registration.', NULL, 'NECO_Civic_2024.json', '5bb36dc489c3cb1458cb8f828fd70d3a78606baa68ebd897bee8ee53e3fcc56c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The Universal Declaration of Human Rights (UDHR) was adopted by the United Nations on _____.', '["10th December, 1948","1st October, 1960","29th May, 1999","24th October, 1945"]', 0, 'The UDHR was adopted by the UN General Assembly on December 10, 1948, in Paris as a common standard for all peoples.', NULL, 'NECO_Civic_2024.json', '764c326acc5c39fec176ca0f7a9b9ed17a47348d47b8c2cfb40e6f1dfb3bf540');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Human rights are said to be ''inalienable'' because _____.', '["They are given by the President","They can be sold to others","They are inherent and cannot be taken away","They are only for adults"]', 2, 'Inalienable rights are fundamental rights that are inherent in every human being and cannot be surrendered or taken away by the state.', NULL, 'NECO_Civic_2024.json', '46bb036436cd2dad2249e7080e3078ed65e8225c4f38b3558208f126ae1a67e3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Which article of the UDHR states that ''Everyone has the right to life, liberty and security of person''?', '["Article 1","Article 3","Article 5","Article 7"]', 1, 'Article 3 of the UDHR covers the foundational right to life and physical safety of every individual.', NULL, 'NECO_Civic_2024.json', 'c6225d7989f4b52dbf6f1d268103aec25dcc86fd5b17d8c7016c1e7818ea8d6c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Cultism was first introduced in Nigerian tertiary institutions in 1952 by the _____.', '["Black Axe","Eiye Confraternity","Pyrates Confraternity","Vikings"]', 2, 'The Pyrates Confraternity (Seadogs) was founded at the University of Ibadan by Wole Soyinka and others to fight against colonial mentality and social injustice.', NULL, 'NECO_Civic_2024.json', '11264d60a9c491be481e58f91e83c2cc6cde57c9302d49314d6d3c47c88051a9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'A major consequence of cultism on the academic environment is _____.', '["High grades","Peaceful co-existence","Disruption of academic activities","Financial stability"]', 2, 'Cult activities often lead to violence, strikes, and closures of schools, which severely disrupt the academic calendar.', NULL, 'NECO_Civic_2024.json', 'ed204bcf142da0fc0762909a4dcfb11559032391fa5ea52e78d0e1d47bb1a272');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The government agency responsible for the prevention of drug abuse and trafficking in Nigeria is _____.', '["EFCC","NAFDAC","NDLEA","ICPC"]', 2, 'The National Drug Law Enforcement Agency (NDLEA) is specifically tasked with eliminating the growing, processing, selling, and trafficking of hard drugs.', NULL, 'NECO_Civic_2024.json', 'cbf1a993dbb470f12d1d507a5b657ab3770e32782975855e7b01c1374864dc13');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'A situation where a person is treated unfairly because they are living with HIV/AIDS is known as _____.', '["Sensitization","Rehabilitation","Stigmatization","Isolation"]', 2, 'Stigmatization is the social disapproval and discrimination against people based on their health status, which discourages testing and treatment.', NULL, 'NECO_Civic_2024.json', '52f2bb8baa8c970c06ec1e22c9d0d4112a9fecd0a0baafdd9965e0c783a611ba');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Which of the following is a symptom of HIV/AIDS?', '["Sudden weight gain","Persistent fever and cough","Clear skin","Strong immune system"]', 1, 'Persistent fever, chronic diarrhea, and significant weight loss are common symptoms of the late stages of HIV infection (AIDS).', NULL, 'NECO_Civic_2024.json', 'ffa17b5e2b7a0e80fd3d02ad0d187137dd8c386cc39288a6340af0b6e2f6e9c9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'A major way of preventing the transmission of HIV/AIDS is _____.', '["Sharing needles","Using the same toilet","Abstinence","Handshaking"]', 2, 'Abstinence from unprotected sexual intercourse is the most effective way to prevent the transmission of HIV.', NULL, 'NECO_Civic_2024.json', '85b5fc1d5ac7a9541ab3fab3b86134ea050be2421b0e3439ea7476ee9466e2c4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The concept of ''Rule of Law'' implies that _____.', '["The President is above the law","Law is supreme over everyone","Military rule is the best","Judges can do whatever they like"]', 1, 'Rule of Law means that the law is the highest authority and is applicable to both the rulers and the ruled equally.', NULL, 'NECO_Civic_2024.json', '44052a2cbe39631bebce91ff622d168880bb13242389796c1c29cd5f13874317');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Who popularized the principle of the Rule of Law?', '["A.V. Dicey","Thomas Hobbes","John Locke","Baron de Montesquieu"]', 0, 'Albert Venn Dicey, a British jurist, outlined the three pillars of the rule of law: Supremacy of law, Equality before the law, and Fundamental Human Rights.', NULL, 'NECO_Civic_2024.json', '8c9a7391c5be1bd8680b873f32ba182448d02ad5670fa9f0d53facd7e9d6c0d9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Which organ of government is responsible for interpreting laws?', '["Executive","Legislature","Judiciary","Bureaucracy"]', 2, 'The Judiciary is the arm of government that interprets the law and adjudicates disputes in courts.', NULL, 'NECO_Civic_2024.json', '6289b687c63f1774fd8dc56e078f2620140eeb3a2037e421fb9383bad48d9554');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The primary function of the Legislature is to _____.', '["Enforce laws","Make laws","Interpret laws","Appoint ministers"]', 1, 'The Legislature (National Assembly in Nigeria) is constitutionally empowered to debate and pass laws for the governance of the state.', NULL, 'NECO_Civic_2024.json', '5b6f16f08a4503b85dfd5533bfbeb62340a395f32cb28067d23af493e14f50be');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Representative democracy is also known as _____.', '["Direct democracy","Indirect democracy","Monarchy","Oligarchy"]', 1, 'In indirect or representative democracy, citizens elect officials to represent their interests and make laws on their behalf.', NULL, 'NECO_Civic_2024.json', '1094e450af437396682654aee5b6c040df0b29f42c1cb6aa265a87d62d2dce9e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'A major pillar of democracy is _____.', '["Secret cults","The Independent Judiciary","Single-party system","Military interference"]', 1, 'An independent judiciary ensures that democratic processes are followed and that the rights of citizens are protected from executive overreach.', NULL, 'NECO_Civic_2024.json', 'e33beb52671958d53db894cce10bc99848228738e64b98f7bde45ef22de8a63d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Voter apathy refers to _____.', '["Enthusiasm in voting","Lack of interest in elections","Rigging of elections","Political education"]', 1, 'Voter apathy is a state where qualified voters lose interest in the electoral process, resulting in low turnout during elections.', NULL, 'NECO_Civic_2024.json', 'ab32e7e58de9ab54ea4435b0236974cb7e91253ccb8985ca79172414f068b4dc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The administrative machinery of government through which policies are implemented is the _____.', '["Private Sector","Civil Service","Pressure Group","Judiciary"]', 1, 'The Civil Service (Public Service) consists of career officials who implement the programs and policies of the government of the day.', NULL, 'NECO_Civic_2024.json', 'bd29a6b5919a4687f63e4a3eda180e85b5253ce544f87272cbffa40cf1c2ceed');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'A permanent feature of the Civil Service is _____.', '["Partisanship","Anonymity","Inconsistency","Political headship"]', 1, 'Anonymity means civil servants are neither praised nor blamed publicly for policy outcomes; they work behind the scenes and remain out of the public eye.', NULL, 'NECO_Civic_2024.json', '565e5f9cf1ddbfb2966702c30a28a3669c5669b5e2a1d1fe9583ce09d0c174aa');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Which of the following can lead to road accidents in Nigeria?', '["Obeying traffic signs","Regular vehicle maintenance","Overspeeding","Driving within the speed limit"]', 2, 'Overspeeding is a leading cause of fatal road crashes as it reduces the driver''s control over the vehicle.', NULL, 'NECO_Civic_2024.json', '86065142f77c4767675c9b190e165eb3ee7546aff5341353a687e61350fc1e53');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The agency responsible for safety on Nigerian roads is the _____.', '["NDLEA","FRSC","NAFDAC","ICPC"]', 1, 'The Federal Road Safety Corps (FRSC) is the lead government agency for road safety administration and traffic management in Nigeria.', NULL, 'NECO_Civic_2024.json', 'efc61984ec4753b5968c9987c8df0de27c29adac7e1d75397a6d24b7d2d7fb45');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Inter-communal conflict can be caused by _____.', '["Inter-marriage","Land disputes","Peaceful dialogue","Religious tolerance"]', 1, 'Disputes over land ownership and boundaries are the most frequent causes of violent clashes between neighboring communities.', NULL, 'NECO_Civic_2024.json', 'd089e2a9dd42b1211c26092adbc132ab3dc2496fc9765da3031a14f6ddfa6ee9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Which of these is a way of resolving conflict?', '["Use of force","Mediation","Suppressing the truth","Weaponry"]', 1, 'Mediation involves a neutral third party helping the disputing sides reach a mutually acceptable agreement.', NULL, 'NECO_Civic_2024.json', '8cb8c7c8705061240bc4c4b7aea7409dc48122bfd292d751321f1a04693fe693');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The first Nigerian national flag was designed by _____.', '["Taiwo Akinkunmi","Nnamdi Azikiwe","Obafemi Awolowo","Herbert Macaulay"]', 0, 'Michael Taiwo Akinkunmi designed the Green-White-Green flag in 1959 while he was a student in London.', NULL, 'NECO_Civic_2024.json', 'a3823c556567f51c2c445fb19a6be99ecb3e57649e99ef86d6f52ea950afb394');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'On the Nigerian Coat of Arms, the ''Y'' shape represents the _____.', '["Unity of Nigeria","Fertile soil","Rivers Niger and Benue","Strength of the nation"]', 2, 'The silver-white wavy bands forming a ''Y'' represent the confluence of Africa''s two great rivers, the Niger and the Benue, at Lokoja.', NULL, 'NECO_Civic_2024.json', 'f142764a42ae121bd02a368341d431dde38a6a62c544b683ce9e726c9320d197');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The motto of Nigeria as inscribed on the Coat of Arms is _____.', '["Unity and Faith","Peace and Progress","Unity and Faith, Peace and Progress","Justice and Service"]', 2, 'The current national motto of Nigeria is ''Unity and Faith, Peace and Progress''.', NULL, 'NECO_Civic_2024.json', 'e357a8c68f9b0613fd4d88e32e488ab7d2c59a9f842666fc5edbdc5081a008ae');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Popular participation can be encouraged through _____.', '["Political apathy","Civil education","Rigging","Thuggery"]', 1, 'Civic education enlightens citizens on their rights and the importance of participating in governance, thereby increasing engagement.', NULL, 'NECO_Civic_2024.json', '68a11159092406d01bb6f9a15c59ae18356ef6a80aefffcb793fa87379e2a24e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'A society that is independent of government and includes NGOs and community groups is called _____.', '["Military society","Civil society","Political party","Unitary state"]', 1, 'Civil society consists of non-governmental organizations and institutions that manifest the interests and will of citizens.', NULL, 'NECO_Civic_2024.json', '6c098b1503290d943218c26d0dc62dd78abfed93c85b803ebb14d50d765ad749');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Which of the following is a skill for youth empowerment?', '["Gambling","Communication skills","Drug trafficking","Exam malpractice"]', 1, 'Communication skills are essential soft skills that empower youths to interact, negotiate, and succeed in the professional world.', NULL, 'NECO_Civic_2024.json', '768cc22a27e907320a16ae207d661bdcfc54dc0ece112d14703ebcb677b7bdce');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Responsible followership involves _____.', '["Blindly obeying leaders","Passive silence","Obeying laws and constructive criticism","Destroying public property"]', 2, 'Responsible followers are law-abiding but also engage in constructive criticism to hold leaders accountable.', NULL, 'NECO_Civic_2024.json', '91df9e16c653a5a3f2ab7a32fb633c52181ac2f01c84b87fc0ba66d27cfbf64f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Nationalism is defined as _____.', '["Hatred for other nations","Devotion and loyalty to one''s own country","Fighting in a war","Traveling abroad"]', 1, 'Nationalism is the sense of belonging and loyalty that an individual feels towards their nation, often characterized by the desire for its independence and prosperity.', NULL, 'NECO_Civic_2024.json', '57befcb431fe0d10c1a1d1cee1951d8be07ab28d406f85f74600737207ec310c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The agency that fights against the distribution of fake drugs in Nigeria is _____.', '["ICPC","NAFDAC","EFCC","SON"]', 1, 'The National Agency for Food and Drug Administration and Control (NAFDAC) regulates the quality of food, drugs, and chemicals.', NULL, 'NECO_Civic_2024.json', '3dd8256f8840b2315a0c31a50d9bba46c618850be4032ed5e05504b9ed327d78');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Constitutionalism means that _____.', '["There is no constitution","Government power is limited by the constitution","The military can suspend the constitution","Only lawyers are citizens"]', 1, 'Constitutionalism is the principle that government authority is derived from and limited by a system of fundamental law.', NULL, 'NECO_Civic_2024.json', '6b112f18749017b42e9fcad350b1c526d8c519ab96448daaa927a6477f354a22');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The ''Ombudsman'' in Nigeria is also known as the _____.', '["Public Complaints Commission","Economic and Financial Crimes Commission","Federal High Court","Code of Conduct Bureau"]', 0, 'The Public Complaints Commission acts as an ombudsman, investigating citizens'' complaints against administrative injustice by the government or private companies.', NULL, 'NECO_Civic_2024.json', 'd7bbc626097539297a1382d247e8ea5672b40c1139b88e8ede607b070a9acbcc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'A major cause of the 1929 Aba Women’s Riot was _____.', '["Lack of hospitals","Introduction of taxes on women","Demand for independence","Protest against education"]', 1, 'The Aba Women''s Riot was sparked by the rumor that the colonial government intended to impose taxes on women, which was culturally and economically unacceptable.', NULL, 'NECO_Civic_2024.json', 'e12c6a0226d6ea570cc850d2ce870653604eac40b72b465cc7e8972bf3d78680');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'A state of harmony where there is no war or disturbance is called _____.', '["Crisis","Peace","Conflict","Apathy"]', 1, 'Peace is the absence of hostility and the presence of social order and mutual understanding.', NULL, 'NECO_Civic_2024.json', 'c667c75cd36493e6cf09f4ae3f942389aa0df4055b30a75d4c52aa333cd1763f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The green light on a traffic signal indicates that motorists should _____.', '["Stop","Ready to move","Go","Warning"]', 2, 'In the standard traffic light sequence, green always means ''go'' if the road is clear.', NULL, 'NECO_Civic_2024.json', '25bb2309b236fa633a6571b1e58e7ea8ae109bb24a9b6b2f0747e1f113aa5163');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Which of these is a limitation to human rights?', '["Education","Wealth","State of Emergency","Gender"]', 2, 'During a State of Emergency, the government may legally suspend certain individual rights to maintain public security.', NULL, 'NECO_Civic_2024.json', 'f87cd07eec9f275c654e0c6d83205752a9ebc8b0bb94857adb8963036d8dfef6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Cultism on campus leads to _____.', '["Better library facilities","Expulsion of students","Financial wealth for students","More time for study"]', 1, 'Participation in cultism is a serious offense that results in the immediate expulsion (rustication) of students from tertiary institutions.', NULL, 'NECO_Civic_2024.json', '865ae81eeae2cc2241c60703f90906981a2c830526d109ad0a07205b85e0973a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Which of the following is a duty of a citizen?', '["Right to life","Payment of taxes","Right to fair hearing","Freedom of speech"]', 1, 'Payment of taxes is an obligatory duty of every citizen to enable the government to provide public services.', NULL, 'NECO_Civic_2024.json', '216128cc926d150c35175546e92417313b32a8823d4e3bcbb4d4e2e1df18f0d9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'What value did Mr. Okon display in the passage?', '["Greed","Self-reliance","Integrity","Apathy"]', 2, 'By refusing to be corrupt and standing for what is right despite threats, Mr. Okon displayed integrity.', 'Mr. Okon, a civil servant, was asked by his boss to help inflate the contract for building a new primary healthcare center. Mr. Okon refused, citing that it would lead to poor work and would be unfair to the community. His boss threatened to fire him, but Mr. Okon stood his ground and reported the matter to the ICPC.', 'NECO_Civic_2024.json', '3c7b48b19fc75d1bc4968e76c61b01870a987c408ce9cf71369bccc9acd8c7f7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'What would have been the consequence of Mr. Okon''s boss''s plan?', '["Better healthcare","Economic progress","Poor quality of service/infrastructure","Promotion for Mr. Okon"]', 2, 'Inflating contracts (corruption) leads to ''cutting corners'', resulting in substandard buildings and poor services for the public.', 'Mr. Okon, a civil servant, was asked by his boss to help inflate the contract for building a new primary healthcare center. Mr. Okon refused, citing that it would lead to poor work and would be unfair to the community. His boss threatened to fire him, but Mr. Okon stood his ground and reported the matter to the ICPC.', 'NECO_Civic_2024.json', '4f60d079c0fba9324a96457b62fd849446f7f31df41743be8b6ffd634d48123a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Inflating a contract is an example of _____.', '["Efficiency","Bureaucracy","Corruption","Anonymity"]', 2, 'Corruption involves the abuse of entrusted power for private gain, such as inflating government contracts.', 'Mr. Okon, a civil servant, was asked by his boss to help inflate the contract for building a new primary healthcare center. Mr. Okon refused, citing that it would lead to poor work and would be unfair to the community. His boss threatened to fire him, but Mr. Okon stood his ground and reported the matter to the ICPC.', 'NECO_Civic_2024.json', 'd4a29ed95f02a69f7058b35475d74ae3260a609d9b599c8a1ba1aac9eafd79a5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Popular participation helps to _____.', '["Encourage rigging","Promote good governance","Restrict human rights","Create one-party systems"]', 1, 'When many people participate in politics, they hold the government accountable, which leads to transparency and good governance.', NULL, 'NECO_Civic_2024.json', '97cb2a1e94e50defbda0e536003040d93140397265f22a23230fd752dab1d233');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The eagle on the Nigerian Coat of Arms represents _____.', '["Peace","Dignity","Strength","Agriculture"]', 2, 'The red eagle standing on the black shield represents the strength and pride of Nigeria.', NULL, 'NECO_Civic_2024.json', '5dd1b517a716175ebe533b993667e026708ddc835598e741987f116dea74a0c6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'A person who is not a citizen of a country but resides there is an _____.', '["Indigene","Alien","Refugee","Diplomat"]', 1, 'An alien is a resident of a country who does not have the legal status of a citizen of that country.', NULL, 'NECO_Civic_2024.json', '8a19173e751a51235eef1d1cb6d3a587a4b9938da022d2cf45afc565fba52fbf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The red light on a traffic signal indicates that the motorist should _____.', '["Go","Stop","Ready to move","Drive slowly"]', 1, 'Red signifies danger or mandatory ''stop'' in traffic regulations.', NULL, 'NECO_Civic_2024.json', '9537613ad991a358f6d484a68cfd05ad2ab5cda6075cdc9ae5f2ceedeacebc56');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Which of these is a function of the Independent National Electoral Commission (INEC)?', '["Appointing the President","Registering voters","Making laws for Nigeria","Judging criminal cases"]', 1, 'INEC is the body empowered by the constitution to register voters and conduct elections in Nigeria.', NULL, 'NECO_Civic_2024.json', 'ff64d5853c94d736e3b0cac5895eb3cc18bca446b863d464a7c70faa61b7e33e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Integrity is a value that helps to eliminate _____ in the public service.', '["Efficiency","Corruption","Discipline","Orderliness"]', 1, 'Honesty and integrity prevent public officers from engaging in bribery and embezzlement.', NULL, 'NECO_Civic_2024.json', 'a34529d5e2802951f7ee60ff281eafdcf96f35de6d5e3854051036eae6b5fe6a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Which of the following is an example of an inter-communal conflict in Nigeria?', '["Election rigging","Aba Women''s Riot","The Ife-Modakeke crisis","The 1966 coup"]', 2, 'The Ife-Modakeke crisis is a classic example of long-standing conflict between two neighboring communities in Osun State.', NULL, 'NECO_Civic_2024.json', 'f0eebb1f40971a421ca07b9cafad21da192d4e036c15531f4e910b4fcb0e7209');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Universal Adult Suffrage ensures that _____.', '["Only rich people vote","Only men vote","All qualified adults can vote","The military decides the winner"]', 2, 'Suffrage is the right to vote. Universal adult suffrage means that all adults, regardless of property or gender, have the right to vote.', NULL, 'NECO_Civic_2024.json', '65e7d909fe056db99a97d0b91d1f54629593df52c4fe1f1c74981a8ff1f12f45');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The primary goal of the UDHR is to _____.', '["Start a war","Protect the rights of the wealthy","Promote global peace and human dignity","Make the UN more powerful"]', 2, 'The UDHR serves as a blueprint for world peace by ensuring every human is treated with dignity and fairness.', NULL, 'NECO_Civic_2024.json', 'bd577f18b77e9688e53b4b25fbee6e80f30c7eeee2d08ca8ee7e2d1a78044e20');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Orderliness in a society involves _____.', '["Jumping queues","Breaking traffic laws","Following laid down rules","Disrespecting elders"]', 2, 'Orderliness is the quality of behaving in an organized way and respecting social regulations.', NULL, 'NECO_Civic_2024.json', '374588a0ce96b572d600fd193690bba8880fb9b4221103be9afdf6ec7ed7f243');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The black shield on the Nigerian Coat of Arms represents _____.', '["Nigeria''s strength","Fertile soil","Peace of the land","Mineral resources"]', 1, 'The black shield represents the rich agricultural heritage and fertile soil of Nigeria.', NULL, 'NECO_Civic_2024.json', '9df39f8ccbd74fdc36fef3d0d627c60b20abb55a959aa767523a53f68bf5b439');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Cultism is most common in which of the following places?', '["Primary schools","Tertiary institutions","Markets","Hospitals"]', 1, 'Secret cults are a major menace specifically associated with universities, polytechnics, and colleges of education.', NULL, 'NECO_Civic_2024.json', '0bc2797f147c4380094184ab668476f7ae73de45ffe783e771d786bec43cbfaf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The yellow light on a traffic signal means _____.', '["Ready/Caution","Go","Stop","Park"]', 0, 'Amber (Yellow) signifies that the light is about to change to red, advising motorists to slow down and prepare to stop.', NULL, 'NECO_Civic_2024.json', 'f62e5ddf7173f8a8fc981c19bf7ed0bc1efbd5f365f1b8bc2542fb03aa580a2b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Which of the following is a way to reduce drug abuse among youths?', '["Encouraging drug peddlers","Providing drug education and counseling","Buying drugs for friends","Advertising alcohol on TV"]', 1, 'Education and counseling help youths understand the dangers of drug addiction and make better life choices.', NULL, 'NECO_Civic_2024.json', 'a7bc6495536b99f8e4774ecf8b2443cd804acdac6b20ddc6566a9ef67d8052d4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Democracy is often defined as _____.', '["Rule by the military","Government of the people, by the people, and for the people","Rule by the wealthy","Rule by a single king"]', 1, 'This famous definition by Abraham Lincoln highlights that the power in a democracy belongs to the citizens.', NULL, 'NECO_Civic_2024.json', '320088a8f163074e88fd2b0bc2d31f20feb0a9af3ded736f70096643d4b94a6c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'In Nigeria, the President is elected for a term of _____ years.', '["2","4","5","6"]', 1, 'The 1999 Constitution provides for a four-year tenure for the President and Governors, renewable only once.', NULL, 'NECO_Civic_2024.json', 'fabccf86bd373b9eda0bad76b5380bf4e8e74422fb2f7697897c202f8ada7b4a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'A major disadvantage of voter apathy is _____.', '["It leads to better leaders","It allows bad leaders to stay in power","It reduces the cost of elections","It makes the country peaceful"]', 1, 'When good citizens refuse to vote, they give room for incompetent leaders to be elected by a small, manipulated minority.', NULL, 'NECO_Civic_2024.json', 'bc6e89670be40f9701ea0f85c2d6e74906bbcf3ade740012fa1089f52d90f54b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The white horses on the Nigerian Coat of Arms represent _____.', '["Unity","Fertile soil","Dignity and Pride","Rivers"]', 2, 'The two horses standing on the sides of the shield represent the dignity and pride of Nigeria.', NULL, 'NECO_Civic_2024.json', '3cb82a976e00b5dc46be9db42064fc0767bdedb8dc6e079c926bfeeb6128b467');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'A written constitution is a document that _____.', '["Is stored in the memory of elders","Is found in a single legal book","Cannot be amended","Is only for the President"]', 1, 'A written constitution is a formal document defining the nature of the constitutional settlement, the rules that govern the political system, and the rights of citizens.', NULL, 'NECO_Civic_2024.json', '471918629d4e55c620c1fa4c7bd2410c3b607fbf843cca0d88073e011247c64f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'Public service in Nigeria is hampered by ''Red-tapism'', which means _____.', '["Using red pens for work","Excessive adherence to formal rules and bureaucracy","Speedy processing of documents","Painting offices red"]', 1, 'Red-tapism involves excessive regulations or rigid conformity to formal rules that delay action or decision-making.', NULL, 'NECO_Civic_2024.json', '5c9f088c91187a301ce74db0472d90ef388d3ddfc5943ac801d43f5a934b290c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'HIV can be transmitted through _____.', '["Sharing of toilets","Mosquito bites","Sharing of unsterilized sharp objects","Hugging"]', 2, 'Sharing needles or blades contaminated with infected blood is a primary mode of HIV transmission.', NULL, 'NECO_Civic_2024.json', '590b2c782db363967eefb12f4303997a513baeb03198f51ab0d42456b9453269');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The ability to work together with others to achieve a common goal is _____.', '["Competition","Cooperation","Isolation","Discrimination"]', 1, 'Cooperation is a social value that encourages team effort and collective success.', NULL, 'NECO_Civic_2024.json', 'ac874fff5e0cf9f977f93e6b07225ccf089a52b20e087c3044ffb382993ccff3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'The supreme law of Nigeria is the _____.', '["Bible","Quran","Constitution","Criminal Code"]', 2, 'The Constitution of the Federal Republic of Nigeria is the highest law; any other law that contradicts it is null and void.', NULL, 'NECO_Civic_2024.json', '2191a693a3aaddd752f5ff16a73f98fb1fa09c98924be99e981d2682b44bd0f6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Civic', 2024, NULL, 'One of the following is a symptom of a disciplined citizen _____.', '["Tax evasion","Self-control","Disorderliness","Apathy"]', 1, 'Self-control is a hallmark of discipline, allowing a citizen to obey laws even when no one is watching.', NULL, 'NECO_Civic_2024.json', '6d06175a9cdd5ad8f3bfda48ab881257f67c3aaab973d8b9f2e602f5cadddebe');
