INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The core objective of commerce is the _____ of goods and services.', '["production","distribution","warehousing","consumption"]', 1, 'Commerce focuses on the exchange and distribution aspect of economics, ensuring goods move from producers to final consumers.', NULL, 'NECO_Commerce_2024.json', '3920a203af7b74d14a748a2199b7202e229c07ec63f2881c6fe1888ae0c080b6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following is an auxiliary to trade?', '["Mining","Farming","Insurance","Fishing"]', 2, 'Insurance is an aid to trade because it helps manage the risks involved in business activities.', NULL, 'NECO_Commerce_2024.json', '3c422c5fd2023836f2c4ea9600de78c6da1209f6efbe21e1df27166c4c1e75cb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The process of buying and selling goods within the boundaries of a single country is _____ trade.', '["foreign","entrepot","home","bilateral"]', 2, 'Home or internal trade occurs within a specific nation, involving wholesalers and retailers.', NULL, 'NECO_Commerce_2024.json', '07a4a876e6eca77efd27c42de7af3f2b743b7f2a47ce2494fa3e4d7496885814');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'A person who buys in large quantities from producers and sells in smaller quantities to retailers is a _____.', '["consumer","wholesaler","broker","factor"]', 1, 'The wholesaler acts as a middleman between the manufacturer and the retailer, performing the function of ''breaking bulk''.', NULL, 'NECO_Commerce_2024.json', '2cc944c1325fe8904c30491500f4c22fe2111191be9675919ee00323eab6493a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following is a function of the retailer?', '["Financing the manufacturer","Providing warehousing for raw materials","Selling in small units to consumers","Buying only in bulk"]', 2, 'Retailers bridge the gap between wholesalers and final users by selling goods in units that meet consumer needs.', NULL, 'NECO_Commerce_2024.json', 'a212fba7c53058356bbe0d13da3b7d15a1cd99f0d78c52bf2efbf6cf698cc5fd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'A specialized retailer that deals in only one line of products is a _____.', '["supermarket","department store","specialty shop","itinerant trader"]', 2, 'Specialty shops focus on a specific niche, such as a pharmacy, a boutique, or a bookshop.', NULL, 'NECO_Commerce_2024.json', '469a75db7c45b1423a0cb4928df5257bf7e35ea81a4e0b422ed26e00292ecaad');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The document issued by a seller to a buyer when goods are returned is a _____.', '["debit note","credit note","invoice","pro-forma invoice"]', 1, 'A credit note is issued to inform the buyer that their account has been credited for returned or overcharged goods.', NULL, 'NECO_Commerce_2024.json', '5ac776a9d3712f2e81b4ec38cdc7f607410da758b255ee81ea0d865e85b4fc4b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'An ''unpaid seller'' has the right of _____ which allows him to keep the goods until the price is paid.', '["stoppage in transit","lien","resale","re-entry"]', 1, 'A lien is a legal right to keep possession of property belonging to another person until a debt owed by that person is discharged.', NULL, 'NECO_Commerce_2024.json', '6f0a0779745945c8c2f02ca5834acb0d7d857882607007d1427725a5fd606775');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The term ''entrepot'' trade refers to _____.', '["trading with neighboring countries","importing goods for re-export","selling goods on the high seas","trade by barter"]', 1, 'Entrepot trade involves importing goods from one country and exporting them to another without significant processing.', NULL, 'NECO_Commerce_2024.json', 'd23d1675615f3f7a85f934cd5b1ec3e7a26ce69c6933f8ef3ce4195e83e727d5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which document is required when goods are to be exported to a country with which the exporter''s country has a trade agreement?', '["Bill of Lading","Consular Invoice","Certificate of Origin","Airway Bill"]', 2, 'A Certificate of Origin proves the country where goods were manufactured, often used to qualify for lower tariffs.', NULL, 'NECO_Commerce_2024.json', 'df2b3fffa541b8085bd2f61596cfd4e0f6ca4bafc2a2276653e1e20d5d659984');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The physical path over which goods are transported by sea is governed by a document called a _____.', '["Shipping Note","Bill of Lading","Manifest","Dock Warrant"]', 1, 'The Bill of Lading is a document of title and a contract of carriage for goods shipped by sea.', NULL, 'NECO_Commerce_2024.json', '9a9ac938643b07334e568a8397ffc66e505acd197fa90b910c9c8edf298a8da1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The act of selling goods in a foreign market at a price lower than the cost of production or the price in the home market is _____.', '["hedging","arbitrage","dumping","smuggling"]', 2, 'Dumping is a predatory pricing strategy used to gain market share in another country, often seen as unfair competition.', NULL, 'NECO_Commerce_2024.json', 'b21294043a5ce5a608e523e79480dc613da42f04946ebd3ff07b0c2673072dbd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following is a function of the Nigerian Export Promotion Council (NEPC)?', '["Regulating local markets","Promoting non-oil exports","Fixing the price of fuel","Issuing national passports"]', 1, 'The NEPC is tasked with diversifying the Nigerian economy by encouraging the export of non-petroleum products.', NULL, 'NECO_Commerce_2024.json', 'b54d8170d1f44afa9acd023d5994b170763a9faad44e6a330e3266f3b807e15a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'A warehouse used for storing dutiable goods until the customs duties are paid is a _____ warehouse.', '["private","public","bonded","state"]', 2, 'Bonded warehouses are controlled by customs authorities; goods cannot be removed until the required taxes are settled.', NULL, 'NECO_Commerce_2024.json', '166a4ba6f66a1ad7e44b600b3905473124042a399e034ce86be99948d91403f9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The most suitable mode of transport for bulky and heavy goods over long distances across the ocean is _____.', '["Air","Rail","Sea","Pipeline"]', 2, 'Sea transport is cost-effective for large volumes of cargo that do not require rapid delivery.', NULL, 'NECO_Commerce_2024.json', '06040060894fedde4d1cbdd5ff6ca94adf62fd7ca4e2ffff277b61f1e4631619');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'In insurance, the principle of ''Indemnity'' means _____.', '["the insured must tell the truth","the insured must not make a profit from a loss","only the owner can insure a property","the cause of loss must be direct"]', 1, 'Indemnity ensures the insured is restored to their pre-loss financial position without gaining any extra benefit.', NULL, 'NECO_Commerce_2024.json', '5a7f95677efe7cbb32ead5d942fc0a497ed8ba344a8f1c2405fa95ca93f9ec7e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The risk that can be calculated and predicted using mathematical models is a/an _____ risk.', '["insurable","non-insurable","speculative","fundamental"]', 0, 'Insurable risks are those that insurance companies can estimate using probability and statistics.', NULL, 'NECO_Commerce_2024.json', '9a9a4027023bdfc54b9ac2e6b86fea0a360aa6accbb43af3b0f82c872a93562f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which type of insurance policy covers a ship''s hull and machinery?', '["Marine Cargo","Marine Hull","Third Party","Life Assurance"]', 1, 'Marine Hull insurance specifically covers the physical structure and equipment of the vessel.', NULL, 'NECO_Commerce_2024.json', 'e665e7738f18946a8c5cbcf8908557f44cf32402108fe4452cf6d172bd438103');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The fee paid periodically to an insurance company to maintain a policy is the _____.', '["Commission","Dividend","Premium","Interest"]', 2, 'The premium is the consideration paid by the insured for the protection provided by the insurer.', NULL, 'NECO_Commerce_2024.json', 'abff6b67ad70494fd5b431537021864bc19e2238b776189af3905cdf11e58e97');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Advertising that aims at building a company''s reputation rather than selling a specific product is _____ advertising.', '["persuasive","informative","institutional","competitive"]', 2, 'Institutional or corporate advertising focuses on the image and goodwill of the organization.', NULL, 'NECO_Commerce_2024.json', '67e17eb089da4d01d58bae91fe7959bea90a43e263eb15ecefad33145f16aa8a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following is a medium of outdoor advertising?', '["Radio","Newspapers","Billboards","Magazines"]', 2, 'Billboards are placed in public areas to capture the attention of people while they are outside their homes.', NULL, 'NECO_Commerce_2024.json', 'ff56f0d6a4534d2261dea524921a194e35de9ab2a4d5eb431832cb583ebf06a8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The method of communication where many people participate in a discussion across different locations via video is _____.', '["telex","teleconferencing","e-mail","paging"]', 1, 'Teleconferencing allows for real-time visual and audio interaction between groups in diverse geographic areas.', NULL, 'NECO_Commerce_2024.json', 'efcd5ad111e7b8ef0293bfb92cc26d2bde75990d9b3f29ab2f8b9bd247f13c60');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'In a partnership business, the liability of ''Limited Partners'' is _____.', '["unlimited","restricted to their capital contribution","equal to the firm''s total debt","zero"]', 1, 'Limited partners are only liable for the amount they have invested in the business, unlike general partners.', NULL, 'NECO_Commerce_2024.json', '0902f8e600ef60c45f90da5087bfc82753945fb4a47b420b47b25259e0acf7c6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following business units is owned and controlled by a single person?', '["Public Limited Company","Partnership","Sole Proprietorship","Cooperative Society"]', 2, 'A sole proprietorship (or one-man business) is the simplest form of business ownership.', NULL, 'NECO_Commerce_2024.json', '350fa59d2e7e523d6a3a5e6a97487a1015ec144658f47bfab0172cf3f184a483');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The minimum number of members in a Public Limited Company in Nigeria is _____.', '["2","7","50","unlimited"]', 1, 'Under the Companies and Allied Matters Act (CAMA), at least seven persons are required to form a public company.', NULL, 'NECO_Commerce_2024.json', 'c497079d27e120b7fae7e334eb5cf8b0e757b3bdeed4581ed9b3ee5669621041');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The document that defines the relationship between a company and the outside world is the _____.', '["Articles of Association","Memorandum of Association","Prospectus","Certificate of Trading"]', 1, 'The Memorandum of Association outlines the company''s objects, name, and powers regarding external parties.', NULL, 'NECO_Commerce_2024.json', 'ef5b9e21d7a6b2b30a530e953c18ee897c95f29941cb30d29b33cf4779de4b1d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'A Public Corporation is established by _____.', '["the Registrar of Companies","an Act of Parliament","a Deed of Partnership","a Prospectus"]', 1, 'Public corporations (statutory bodies) are created by specific laws to provide essential social or utility services.', NULL, 'NECO_Commerce_2024.json', '30c76a7e61bc161c6bcd2829d210951720ca8723bfb8df98a823b7c0e67634a9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The profit shared among members of a Cooperative Society based on their patronage is the _____.', '["Interest","Dividend","Commission","Premium"]', 1, 'Cooperatives distribute surpluses to members known as dividends, often in proportion to how much the member used the society''s services.', NULL, 'NECO_Commerce_2024.json', 'effa65bcacfaf486c775b207a418b69f9ac0b284d4307c583e959f18f2bc6eff');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following is a disadvantage of a Sole Proprietorship?', '["Quick decision making","Privacy of accounts","Lack of continuity","Low tax rate"]', 2, 'Since the business is tied to the owner, the death or illness of the owner often leads to the end of the business.', NULL, 'NECO_Commerce_2024.json', '48f91025778cd189fb4e3f864c58390a243d7af5e3fe2c8dd4016bbc28eaebd2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The abbreviation ''PLC'' stands for _____.', '["Private Limited Company","Public Liability Company","Public Limited Company","Partnership Limited Company"]', 2, 'PLC denotes a company whose shares are available for subscription by the general public.', NULL, 'NECO_Commerce_2024.json', 'e2b17b891008be07b39e2d1e14b0a1fb035562213db1e8167332229073ddd595');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'A market for short-term loans and financial instruments like Treasury Bills is the _____ market.', '["Capital","Commodity","Money","Labour"]', 2, 'The money market deals with high-liquidity financial assets with a maturity of one year or less.', NULL, 'NECO_Commerce_2024.json', '698cb88f1c8a70767246526a1183e68e623df973c816a2fd8aca08fe4f02df0c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The ''Bear'' in the Stock Exchange is a person who _____.', '["expects share prices to rise","expects share prices to fall","buys only government bonds","refuses to sell his shares"]', 1, 'A Bear is a pessimistic investor who sells shares in the hope of buying them back later at a lower price.', NULL, 'NECO_Commerce_2024.json', '01bf393616236c3e2f9cbe7ddee45a0771b7ce5819bbaab85112b005f501cf28');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The secondary market where existing shares and stocks are traded is the _____.', '["Commercial Bank","Central Bank","Stock Exchange","Bureau de Change"]', 2, 'The Stock Exchange provides a platform for investors to buy and sell already issued securities.', NULL, 'NECO_Commerce_2024.json', 'd775ffa9c310dfebdd1d861bece44c66b57f9f13b5b298c3b7b411b012d9f984');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following is a function of the Central Bank of Nigeria?', '["Accepting deposits from the public","Lending to small businesses","Issuing legal tender","Selling consumer goods"]', 2, 'The Central Bank has the sole authority to issue and manage the national currency (Naira).', NULL, 'NECO_Commerce_2024.json', 'ca2231dacae06f918955c302663618f956a6ef2a61a6489c51123d0a4bb6179f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'A ''Crossing'' on a cheque is intended to _____.', '["make it invalid","ensure it is paid only into a bank account","allow it to be cashed over the counter","increase its value"]', 1, 'Crossed cheques provide security because they must be processed through a bank account, creating a paper trail.', NULL, 'NECO_Commerce_2024.json', '3a14418fcb19c9ea34470b476bc01eed8b8d3c08fa0fdabe544d957da52ba040');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The automated system that allows customers to withdraw cash outside banking hours is the _____.', '["POS","E-mail","ATM","Telex"]', 2, 'Automated Teller Machines (ATMs) provide 24/7 access to basic banking services.', NULL, 'NECO_Commerce_2024.json', 'cd4b6e9db951c45fec7b59f50841e7c0063c69d1fff41427584d7006c1d6ec13');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'A bank account that allows the holder to withdraw more than the balance is a _____ account.', '["Savings","Current","Fixed Deposit","Domiciliary"]', 1, 'Current accounts offer overdraft facilities, which allow customers to borrow money on a short-term basis.', NULL, 'NECO_Commerce_2024.json', '24ae0b75459a7d75d43935a633b59e98baf5cd269f20edb6ff24b6841717d0de');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The principle of ''Caveat Emptor'' means _____.', '["the seller must be honest","let the buyer beware","goods must be of high quality","the buyer is always right"]', 1, 'It is a legal doctrine that warns the buyer to examine the goods before purchasing, as the seller is not responsible for defects unless stated.', NULL, 'NECO_Commerce_2024.json', 'f5e3a89b3552a40173d16c1d3c5dfc000f75e925deaff2af34b30ed2327fdcde');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which agency in Nigeria is responsible for the standard and quality of food and drugs?', '["SON","NAFDAC","NDLEA","EFCC"]', 1, 'The National Agency for Food and Drug Administration and Control (NAFDAC) regulates and controls the manufacture and sale of food and drugs.', NULL, 'NECO_Commerce_2024.json', 'de090ab59942edb945dd866b94e9571802e90dcb817884ea4aff4494673088f5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The use of computers and the internet to conduct business transactions is _____.', '["E-government","E-commerce","E-learning","E-banking"]', 1, 'Electronic commerce (E-commerce) encompasses buying, selling, and marketing goods online.', NULL, 'NECO_Commerce_2024.json', '4b9d39febd9866a107430ebfc1740cf9c15b2cbcae7046e88673dc27cae84e08');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'In a contract, an ''Offer'' must be followed by _____ for a valid agreement to exist.', '["a rejection","an acceptance","a counter-offer","a lawsuit"]', 1, 'Offer and acceptance are the two primary requirements for the formation of a binding contract.', NULL, 'NECO_Commerce_2024.json', 'aed89a12f3caabddec78524648c91981cd79020c23caca59f0201b66795122d7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'A person who is authorized by another to act on their behalf in business dealings is a/an _____.', '["Employee","Partner","Agent","Contractor"]', 2, 'The law of agency describes the relationship where an agent acts for a principal.', NULL, 'NECO_Commerce_2024.json', '3568a43937d54ba506a17b3cf462520e4decca57b15a6015c7b26919e25a4983');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following is an example of an extractive occupation?', '["Carpentry","Banking","Quarrying","Bricklaying"]', 2, 'Extractive occupations involve taking resources directly from the earth or sea.', NULL, 'NECO_Commerce_2024.json', '50324a27e96decd470d399d1e119f26e3ac8b70bf277fae3b57ebbecc967712b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The reward for an entrepreneur for taking risk is _____.', '["Wages","Interest","Profit","Rent"]', 2, 'Entrepreneurs organize other factors of production and receive profit as a reward for their management and risk-taking.', NULL, 'NECO_Commerce_2024.json', '193183faa19a4f6e3f7118fad76b79ec3beaf7c1b948360dd07669aeb8232841');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following documents is used to move goods from one place to another by road?', '["Invoice","Waybill","Debit Note","Credit Note"]', 1, 'A waybill serves as a delivery note and a record of the items being transported by a carrier.', NULL, 'NECO_Commerce_2024.json', '8cdef8a863f18bfb168fd953e1d089bf8cbca02af0747b74d75dfd0d777a82cd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The practice of selling off government-owned businesses to private individuals is _____.', '["nationalization","commercialization","privatization","diversification"]', 2, 'Privatization is the transfer of ownership from the public sector to the private sector.', NULL, 'NECO_Commerce_2024.json', 'e699c8455a9d74188f1c72960fafd9158e902bc7368e9ae68eb2eb0ea2cbbb37');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following is a component of the ''marketing mix''?', '["Planning","Product","Purchase","Profit"]', 1, 'The 4 Ps of marketing are Product, Price, Place, and Promotion.', NULL, 'NECO_Commerce_2024.json', 'a47a69c345a7ac7056f4654a343be642121d8ce5b9cd0b23ecf7c13c818ed378');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'A market where a single buyer dominates the market for a product is a _____.', '["Monopoly","Oligopoly","Monopsony","Duopoly"]', 2, 'Monopsony occurs when there is only one buyer, giving that buyer significant power over sellers.', NULL, 'NECO_Commerce_2024.json', '249e9e0b03f0036c3068d5327da97ce65886ae1443cc0059159b8738baa78db2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The record of all financial transactions of a business in a systematic way is _____.', '["Auditing","Accounting","Commerce","Budgeting"]', 1, 'Accounting involves the identifying, measuring, and communicating of financial information.', NULL, 'NECO_Commerce_2024.json', '30d0a3c58c4102fbc93a78441aacbb0c635351b8fdd0d6a11fdad5f1aea962c9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following allows a trader to buy goods now and pay at a future date?', '["Cash trade","Credit trade","Barter trade","Entrepot trade"]', 1, 'Credit trade enables business expansion by allowing buyers to manage their cash flow.', NULL, 'NECO_Commerce_2024.json', 'e09d9e7d609074ba26290f843f9b3847b34fefaf14635e8fc044873af2ab3c76');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The person who is appointed to oversee the winding up of a company is the _____.', '["Promoter","Director","Liquidator","Auditor"]', 2, 'A liquidator is responsible for selling the assets of a company to pay off its debts when it is being dissolved.', NULL, 'NECO_Commerce_2024.json', 'abc12cc60a01d081e5019e3045808c6dfe06d2f481198b98956767896cd1c650');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following is a source of long-term capital for a company?', '["Bank Overdraft","Trade Credit","Issue of Shares","Bill of Exchange"]', 2, 'Issuing shares provides equity capital that does not need to be repaid in the short term.', NULL, 'NECO_Commerce_2024.json', '1b6188ca89630bf63a80fbd82573b2c363a6fdb970bc5e04945f2f19c7dc3677');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The act of using a well-known name or symbol to distinguish a product is _____.', '["Packaging","Branding","Labeling","Grading"]', 1, 'Branding helps to create product identity and build customer loyalty.', NULL, 'NECO_Commerce_2024.json', '63420023653059e73ed48d7fe7cfdcb468270bc5d2a4652de536a44fcf81b628');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The most important document for a Public Company to invite the public to buy shares is the _____.', '["Articles of Association","Memorandum of Association","Prospectus","Trading License"]', 2, 'A prospectus is a legal document that provides details about the company and its share offer to potential investors.', NULL, 'NECO_Commerce_2024.json', '1d46018bf47a07d923842c290b94712569062822f6fb8485ccd5f1516bcefc90');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which transport mode is most affected by weather conditions like fog and storms?', '["Rail","Road","Air","Pipeline"]', 2, 'Air transport is highly sensitive to visibility and atmospheric turbulence, leading to delays or cancellations.', NULL, 'NECO_Commerce_2024.json', 'd408d41bdf263d9045336fca03e731b71a3677a2daa22844282987125d0bdb63');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The term ''F.O.B'' in international trade stands for _____.', '["Freight on Board","Free on Board","Fixed on Board","Forward on Board"]', 1, 'Free on Board means the seller is responsible for the goods until they are loaded onto the ship.', NULL, 'NECO_Commerce_2024.json', '40eba8c29ed2a6b1b36f857e9d59fac0febd9834c0997fd5c4db067df70bf2ea');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'A contract that is not legally enforceable from the beginning is _____.', '["Valid","Voidable","Void","Implied"]', 2, 'A void contract has no legal effect and cannot be enforced by either party.', NULL, 'NECO_Commerce_2024.json', '3dc60297e9a7d9cf1c5c1b4762bf9927a93d9dc4d650c944e5b95d28e0138259');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following is a function of the Stock Exchange?', '["Lending money to individuals","Fixing the exchange rate","Protecting the value of the currency","Providing a market for old securities"]', 3, 'The Stock Exchange facilitates the ''liquidity'' of investments by allowing investors to sell their shares.', NULL, 'NECO_Commerce_2024.json', '4f166cbdac94a288161e8db7e7c570a8f6a5eebd80cd20c8bf81b4e6f3f75df8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The ''Standard Organization of Nigeria'' (SON) is primarily concerned with _____.', '["labor disputes","quality control of manufactured goods","issuing international passports","controlling the price of fuel"]', 1, 'SON ensures that products manufactured or sold in Nigeria meet required safety and quality specifications.', NULL, 'NECO_Commerce_2024.json', '0012ae1e2d667ae8e5d0b05bf5ad5a4b49d51ceaf3c41940ee84eb2919a06ea8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which type of communication involves the use of facial expressions and body language?', '["Written","Oral","Non-verbal","Visual"]', 2, 'Non-verbal communication conveys messages without using spoken or written words.', NULL, 'NECO_Commerce_2024.json', 'bdaf7ee75abc504d868326267098a1ffcd9d9a64e6d3a36faa22a30bfb106a9b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'A bank draft is safer than a personal cheque because _____.', '["it is cheaper","it cannot be lost","the bank guarantees payment","it is signed by the President"]', 2, 'A bank draft is drawn by the bank on its own funds, so there is no risk of the cheque ''bouncing''.', NULL, 'NECO_Commerce_2024.json', 'f19bae390e4655693e1a3f8dba8fb14e7f9ca31bbab25e0ec104a571507ef250');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The process of a manufacturer selling directly to the consumer is an example of _____.', '["indirect distribution","direct distribution","wholesale trade","retail trade"]', 1, 'Direct distribution eliminates middlemen, allowing the producer to keep all the profit margin.', NULL, 'NECO_Commerce_2024.json', '51901fa9f91dcb4a8f7b0864d2f25eff5bc9615b37068d7dce307a8972d64d2e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following allows a person to withdraw money from their bank account at any time using a machine?', '["Credit card","ATM card","Voucher","Pay slip"]', 1, 'An ATM card linked to a bank account allows for immediate cash withdrawals.', NULL, 'NECO_Commerce_2024.json', 'a58db5f033c4a0ccd9a95ea4645b47ff5f529d5218513ef1f2c33760810717cb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'A person who buys and sells shares on behalf of the public for a commission is a _____.', '["Jobber","Broker","Stag","Bull"]', 1, 'Stockbrokers act as agents for clients in the buying and selling of securities on the exchange floor.', NULL, 'NECO_Commerce_2024.json', '6a865be0cdfc9521b79ca84a4b4d88646807957d32dd9fd808259551d1df048a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The document showing the evidence of a contract of insurance is the _____.', '["Premium","Policy","Proposal form","Cover note"]', 1, 'The insurance policy is the formal document containing all the terms and conditions of the contract.', NULL, 'NECO_Commerce_2024.json', 'a5b5591bd1abba9ea35cad6f66bf6b71b203c4746677365deaead720205d8553');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following is a type of internal trade?', '["Export trade","Import trade","Wholesale trade","Entrepot trade"]', 2, 'Wholesale trade happens within a country, involving the purchase of goods in bulk from local or foreign producers for local resale.', NULL, 'NECO_Commerce_2024.json', 'b7e055723f1d996f427d68eaba0c50cf401abfffdd1ef68665b006fe5a1a2ca9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The systematic record of all economic transactions between a country and the rest of the world is the _____.', '["Terms of trade","Balance of payments","Balance of trade","National income"]', 1, 'The Balance of Payments (BOP) accounts for all visible and invisible trade plus capital movements.', NULL, 'NECO_Commerce_2024.json', '41e413b01673f1c992b8237947f5f98050d1ff256567673ee5c99b2b027c6bf8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'A ''Stale'' cheque is one that _____.', '["has been rejected by the bank","is presented before its date","is presented more than six months after its date","has no signature"]', 2, 'In banking practice, a cheque becomes stale and is usually not honored if it is too old (usually 6 months).', NULL, 'NECO_Commerce_2024.json', '3ba79eb5dd8e8e5a381ac46ab17284feab9ef93ee70d15a62dba674265be66f2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'Which of the following is a barrier to international trade?', '["Language differences","Use of the internet","Efficient transport","Standardization of products"]', 0, 'Differences in language can make communication and negotiations difficult between international traders.', NULL, 'NECO_Commerce_2024.json', '8c0baec26d639d7077865e9321487df9b9d9a49dd8925b33dece8703fa9777b1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Commerce', 2024, NULL, 'The use of the internet to buy and sell goods and services is _____.', '["E-mail","E-commerce","E-government","E-learning"]', 1, 'E-commerce encompasses online shopping, digital payments, and electronic business processes.', NULL, 'NECO_Commerce_2024.json', 'bc0a07eb4204243ba2335f266acf4e51ad992b188b1085daa747a8762452ac7a');
