INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The first generation of computers (1940-1956) used _____ as the basic components for memory and circuitry for CPU.', '["Transistors","Integrated Circuits","Vacuum Tubes","Microprocessors"]', 2, 'First-generation computers relied on vacuum tubes for circuitry and magnetic drums for memory, making them enormous and prone to frequent overheating.', NULL, 'NECO_Computer_2024.json', 'f3d0b493a8bc29fd487e77d39212f9a433c8f979fc660e00aed986842990cdf9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which of the following is an example of an open-source operating system?', '["Windows 11","macOS","Linux","iOS"]', 2, 'Linux is open-source, meaning its source code is available for anyone to study, change, and distribute, unlike proprietary systems like Windows.', NULL, 'NECO_Computer_2024.json', '1a46dff29e486fca213be7d74bfe981db076a87f4c412e44cb8dc07acba22473');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Convert the decimal number 25 to its binary equivalent.', '["11001","10111","11101","10011"]', 0, '25 divided by 2 gives 12 R 1; 12/2 = 6 R 0; 6/2 = 3 R 0; 3/2 = 1 R 1; 1/2 = 0 R 1. Reading remainders bottom-up gives 11001.', NULL, 'NECO_Computer_2024.json', '3badac39b72f8f174680a375b88618e9e2f41dce3f2a6cf07c583ec9a68ca15c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'In the CPU, the _____ is responsible for performing all mathematical calculations and logical comparisons.', '["Control Unit","Registers","Arithmetic and Logic Unit","Cache"]', 2, 'The Arithmetic and Logic Unit (ALU) is the part of the CPU where actual data processing (addition, subtraction, AND, OR) occurs.', NULL, 'NECO_Computer_2024.json', '9c2f4ce3bf31ace793cf5972fe342c71882dd18e63ec0c16505899676c4fd88f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'A collection of 4 bits is commonly referred to as a _____.', '["Byte","Nibble","Word","Kilobyte"]', 1, 'A nibble is exactly half of an 8-bit byte. It is often used in the context of hexadecimal representation.', NULL, 'NECO_Computer_2024.json', '7bda6d58cd224199f6a0f8cab11cf552f99c3f260909e4a14416dc5b0c536584');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which of the following logic gates produces an output of 0 only when both inputs are 1?', '["AND","OR","NAND","NOR"]', 2, 'A NAND (Not-AND) gate is a universal gate that produces a high output (1) in all cases except when both inputs are high (1).', NULL, 'NECO_Computer_2024.json', 'f3ff3ee14cba8ce1d1aaf7362fd9c5b4b897f540b4058704ebf62cb1dd85f586');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The process of starting a computer that is already turned on (usually after a system crash) is known as _____.', '["Cold Booting","Warm Booting","Hibernating","Formatting"]', 1, 'Warm booting (or soft boot) is restarting a computer without turning off the power, often using Ctrl+Alt+Del or a reset button.', NULL, 'NECO_Computer_2024.json', '47eec7f3ea0acdbef30d4c4b7f8a1b2942d817e68d6d9222862380b4ef48b2e5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'In networking, which topology connects all devices to a single central cable known as the backbone?', '["Star","Mesh","Bus","Ring"]', 2, 'In a bus topology, all nodes share a single communication line. If the main cable fails, the entire network goes down.', NULL, 'NECO_Computer_2024.json', 'a3c2b6f2708b9d7e2410c83884095856bb8fa0293e8df475b22a9d9c440f7080');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which of the following is a permanent storage device that uses flash memory and has no moving parts?', '["Hard Disk Drive","Floppy Disk","Solid State Drive","CD-ROM"]', 2, 'Solid State Drives (SSDs) are faster and more durable than HDDs because they store data in electrical cells rather than on spinning magnetic platters.', NULL, 'NECO_Computer_2024.json', '3baa74174d2e7eafbdc2daba65b3562c19424709a25c110264dca397ce15779a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The protocol used for securely transferring web pages over the internet is _____.', '["HTTP","FTP","HTTPS","SMTP"]', 2, 'HTTPS (Hypertext Transfer Protocol Secure) uses encryption (SSL/TLS) to protect data transmitted between a web browser and a server.', NULL, 'NECO_Computer_2024.json', '9ab9dfd03887c8e49f8de34de75c119e4eb8838f15cde98b8b46750bdf5abd25');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'A unique field in a database table that uniquely identifies each record is called the _____.', '["Foreign Key","Candidate Key","Primary Key","Composite Key"]', 2, 'A primary key must contain unique values and cannot be null, ensuring every row in a database table can be precisely targeted.', NULL, 'NECO_Computer_2024.json', 'a9fbc4f0ce009ce220d610ac84583975339b6cdd88ba04ad9851d72ef1a2491f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'What is the function of an Interpreter in computer programming?', '["Translates the whole program at once","Translates and executes code line-by-line","Converts high-level language to assembly","Detects logical errors only"]', 1, 'An interpreter translates source code into machine code and executes it one line at a time, making debugging easier but execution slower than a compiler.', NULL, 'NECO_Computer_2024.json', 'ac1de81b146c700bcaeeb1831a689115df8e6e7a438373fba2a4686ecf414f41');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which of the following is NOT an application software?', '["CorelDraw","Device Driver","MS Word","Adobe Photoshop"]', 1, 'A device driver is a system software that tells the operating system how to communicate with specific hardware like printers or scanners.', NULL, 'NECO_Computer_2024.json', '24e1339d661df9d83f3993f4d4367f2750bb2305ca69c32e653dcf02909a240a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The primary language used to create and structure content for the World Wide Web is _____.', '["Python","HTML","Java","PHP"]', 1, 'HTML (Hypertext Markup Language) uses tags to define headings, paragraphs, links, and other elements on a web page.', NULL, 'NECO_Computer_2024.json', '6c6a48dc8ee6df27df73d933503b24183efbdd7629ee49484e1424e6cad025e6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Convert the hexadecimal number ''A'' to its decimal equivalent.', '["1","10","12","15"]', 1, 'In hexadecimal (base-16), digits 0-9 are followed by A=10, B=11, C=12, D=13, E=14, and F=15.', NULL, 'NECO_Computer_2024.json', 'd23df79660e10c4ec5878f88fa2cea23a8e05739507082f4a58aae7f497e51da');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The act of pretending to be a trustworthy entity in an email to steal sensitive information like passwords is _____.', '["Hacking","Spamming","Phishing","Cracking"]', 2, 'Phishing is a form of social engineering where attackers trick users into clicking malicious links or providing private data.', NULL, 'NECO_Computer_2024.json', '9e895950fc9221e2a23555baec6ec0b8219b1b67bd56158a97644f885f0aa9cb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which layer of the OSI model is responsible for routing data packets from source to destination across different networks?', '["Data Link Layer","Transport Layer","Network Layer","Session Layer"]', 2, 'The Network Layer (Layer 3) handles logical addressing (IP addresses) and finds the best physical path for data to travel.', NULL, 'NECO_Computer_2024.json', '0a25cfccc03567b6581da4abb663bb2fe22da55c751efaff4245ed8f1872bf71');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'A computer program that spreads by inserting copies of itself into other executable code or documents is a _____.', '["Worm","Trojan Horse","Virus","Spyware"]', 2, 'A computer virus requires a host program or human action to spread, whereas a worm can spread autonomously across networks.', NULL, 'NECO_Computer_2024.json', '008b04444d54206ccf6e11e00bf94360912f6afbbec901e439c5869ffc085f7a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The hexadecimal number system uses base _____.', '["2","8","10","16"]', 3, 'Hexadecimal is base-16, using digits 0-9 and letters A-F to represent values.', NULL, 'NECO_Computer_2024.json', 'b1a6c5c47503ccce8f71ce8fa3b99c1bcfd219cc5b12914b113381ed51a98ce4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'What is the decimal result of the binary addition 1010 + 0101?', '["10","15","20","25"]', 1, '1010 is 10 in decimal. 0101 is 5 in decimal. 10 + 5 = 15.', NULL, 'NECO_Computer_2024.json', '6ee2326c86d18a7fc700e8ae73a206b2b1e545f637a25ed54f0fe82652821e89');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The BIOS (Basic Input/Output System) is stored in which type of memory?', '["RAM","ROM","Cache","Hard Disk"]', 1, 'The BIOS is firmware stored on a Read-Only Memory (ROM) chip so it can be available immediately when the computer is powered on.', NULL, 'NECO_Computer_2024.json', '4937a479ef29604f01db40cd9c7b4ca2bc30a9bc0688dbbb6d3eee33dc0a2cc3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which unit of measurement is used to determine the speed of a modern CPU?', '["MBps","Gigahertz (GHz)","DPI","PPM"]', 1, 'GHz measures the clock speed of a processor, representing billions of cycles per second.', NULL, 'NECO_Computer_2024.json', '7b047ab8a47fd14b868bfa5ea0590002086f46877a4815dacc23882a608ad3a1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'In a flowchart, the ''Parallelogram'' symbol is used to represent _____.', '["Process","Decision","Input/Output","Start/Stop"]', 2, 'A parallelogram indicates a data input from the user or an output to a device like a monitor.', NULL, 'NECO_Computer_2024.json', 'd9fc52bd5e63b2c44130fa8c6af3c1cadd5c3ce9df12323083946daf386cdab1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The physical components of a computer that you can see and touch are collectively called _____.', '["Software","Firmware","Hardware","Liveware"]', 2, 'Hardware includes internal components like the motherboard and external peripherals like the keyboard.', NULL, 'NECO_Computer_2024.json', 'fb052189499c47c37dd50dd1b6f7b38e0cc5afbe495d930fb8c439de087c5d8c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which of the following is a high-level programming language?', '["Machine Code","Assembly Language","Python","Mnemonics"]', 2, 'High-level languages like Python, Java, and C++ use English-like syntax and are easier for humans to read than low-level languages.', NULL, 'NECO_Computer_2024.json', '3d97c6904dd5c9112582f765ade0d52f16da50cf5944540cc086dd390e608194');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The ''logical'' part of a computer that is invisible to the user and manages hardware is the _____.', '["Application software","Utility software","Operating system","Database management system"]', 2, 'The OS (Operating System) acts as an interface between the hardware and the user/applications.', NULL, 'NECO_Computer_2024.json', '7d379688a94e1305004ca4f86865c6c7b3ff91db7d11dc8e69fff563e6a8ad5a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'What does the acronym URL stand for?', '["Uniform Resource Locator","Universal Radio Link","Unified Resource Line","Uniform Road Locator"]', 0, 'A URL is the address of a specific resource (like a webpage) on the internet.', NULL, 'NECO_Computer_2024.json', 'e35fbb670f8357e44c1bf6523046f6f942830836e46ac55dce331c182a2c3390');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which of the following units is the largest?', '["1024 Kilobytes","1 Gigabyte","1 Megabyte","1 Terabyte"]', 3, 'Order: KB < MB < GB < TB. One Terabyte is 1024 Gigabytes.', NULL, 'NECO_Computer_2024.json', 'a64ca9b56a019b00ee009a07f95391d8f281b4267093dd142ae95d37e703368a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The keyboard shortcut to ''Undo'' the last action in most Windows applications is _____.', '["Ctrl + Y","Ctrl + X","Ctrl + Z","Ctrl + V"]', 2, 'Ctrl + Z is the universal shortcut for reverting the most recent change.', NULL, 'NECO_Computer_2024.json', 'd7e099494205d806884c1e22246c24547dcea09572ca9ee755a5aa02a79024e6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which component is used to connect a computer to a telephone line for internet access?', '["Router","Modem","Switch","Hub"]', 1, 'A modem (Modulator-Demodulator) converts digital signals to analog for telephone lines and vice-versa.', NULL, 'NECO_Computer_2024.json', 'ab579cfc7a851ad0da4d1a41ce795d6522e5f2396b9256bc7b609ff50a8c28be');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'A network that spans a large city or a campus is called a _____.', '["LAN","PAN","MAN","WAN"]', 2, 'Metropolitan Area Network (MAN) covers a larger area than a LAN but smaller than a Wide Area Network (WAN).', NULL, 'NECO_Computer_2024.json', 'de4a7c93537fa5278bf5638f07ed29a050705e2c4ab04137f031f00ca70a3ebe');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'In word processing, the feature that automatically moves a word to the next line when it doesn''t fit at the end of the current line is _____.', '["Word Wrap","Line Break","Pagination","Indentation"]', 0, 'Word wrap ensures text stays within margins without the user having to press Enter at the end of every line.', NULL, 'NECO_Computer_2024.json', 'e6aa935c2b1fe8cbb783f178170641fe2dbf587b838ae3a3d2725949f38002ed');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The primary purpose of a ''Firewall'' is to _____.', '["Increase internet speed","Block unauthorized access to a network","Store backup data","Delete viruses from the hard drive"]', 1, 'A firewall acts as a barrier between a trusted network and untrusted networks, filtering incoming and outgoing traffic.', NULL, 'NECO_Computer_2024.json', '0968a80830af53a2ac63d769c7ba087749d4763816fd5d5a2d80e3db2b1a9b9e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which of the following is a non-impact printer?', '["Dot Matrix","Daisy Wheel","Laser Printer","Line Printer"]', 2, 'Laser and Inkjet printers are non-impact because they do not strike an inked ribbon against the paper.', NULL, 'NECO_Computer_2024.json', '5d6d8313b49da7d2e8b60453099a8ae9002a7feb02c34fb82665fee4af24499a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'In the System Development Life Cycle (SDLC), the stage where the actual coding is done is _____.', '["Feasibility Study","System Design","Implementation","Maintenance"]', 2, 'Implementation involves writing the code, installing hardware, and training users.', NULL, 'NECO_Computer_2024.json', '414a116ad73e91a170456e8c30006f07dbb0ed3443ef51b71dd0209fec59784f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'What is the octal equivalent of the decimal number 8?', '["8","10","11","7"]', 1, 'In octal (base-8), the digits are 0-7. After 7, the next number is 10 (which represents one 8 and zero 1s).', NULL, 'NECO_Computer_2024.json', 'fc9e9d0a8566d4053f7356e2705dfc9d2fe6a4a27fb67cace5d89651fc71d83d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which of the following is an example of ''Volatile'' memory?', '["Hard Disk","ROM","RAM","Pen Drive"]', 2, 'Volatile memory (RAM) loses its content as soon as the power is turned off.', NULL, 'NECO_Computer_2024.json', '89b18db4ebedd620c3181d7448130e96bf5d62d51d2ca02008debbe27e26747e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The ''Brain'' of the computer system is the _____.', '["Monitor","RAM","CPU","Motherboard"]', 2, 'The Central Processing Unit (CPU) executes instructions and tells other parts of the computer what to do.', NULL, 'NECO_Computer_2024.json', '5ead56c21a0a8a8bc6f051234ac2b7370587b8a594553ea6f5ad2bd42a5e331b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which file extension is commonly used for standard text files without formatting?', '[".docx",".pdf",".txt",".rtf"]', 2, '.txt files contain plain text only and can be opened by almost any basic text editor like Notepad.', NULL, 'NECO_Computer_2024.json', 'd45905f349e23cb2265ae0fdecfe7f35ed6c7d6bb8dace286027d8a0cbbd4024');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The binary number 1111 is equivalent to the decimal number _____.', '["7","8","15","16"]', 2, '(12^3) + (12^2) + (12^1) + (12^0) = 8 + 4 + 2 + 1 = 15.', NULL, 'NECO_Computer_2024.json', '8ea7dee73b80f0d0cc04460c7674f2802335edc853f5412d0534cb3627d35e80');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which of the following is used to uniquely identify a computer on the internet?', '["MAC Address","IP Address","Home Address","URL"]', 1, 'An IP (Internet Protocol) address is a numerical label assigned to each device connected to a computer network.', NULL, 'NECO_Computer_2024.json', '7f9fbfe442fbf86eb7f60c558b0047b07b9b09bf79eb00be346328036ac33bb8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'A program used to view web pages is called a _____.', '["Web Server","Search Engine","Web Browser","Website"]', 2, 'Web browsers like Chrome, Firefox, and Edge interpret HTML/CSS/JS to display web content to users.', NULL, 'NECO_Computer_2024.json', 'd131feef447a019abf6b27652235ce37c01479f58a851643c3368ca0e5d59920');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'What is the function of the ''UPS'' in a computer setup?', '["To increase processor speed","To provide backup power during a failure","To store large files","To connect to the internet"]', 1, 'Uninterruptible Power Supply (UPS) provides battery backup to allow users to save work and shut down properly during power outages.', NULL, 'NECO_Computer_2024.json', '1fd766e7a645bcb52589704b1a9399c428bb165969104098c8a03ccdd0af50de');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which of the following is a database management software?', '["MS Word","MS Access","MS Excel","MS Publisher"]', 1, 'Microsoft Access is used for creating and managing relational databases.', NULL, 'NECO_Computer_2024.json', '189ac8d733e78749596bc83fb1cf98d96913d69c92d073c43f4c0c0eebecc420');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The symbols used in a flowchart to represent a ''Decision'' or ''Condition'' is _____.', '["Rectangle","Oval","Diamond","Parallelogram"]', 2, 'The diamond symbol represents a branching point where a ''Yes'' or ''No'' / ''True'' or ''False'' condition is evaluated.', NULL, 'NECO_Computer_2024.json', 'aea9e9df8a51863e68fd98c77623e953c0792a7fb70249d61c9c240408cfb181');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which protocol is primarily used for sending emails across the internet?', '["POP3","IMAP","SMTP","FTP"]', 2, 'Simple Mail Transfer Protocol (SMTP) is used for outgoing mail, while POP3/IMAP are used for receiving mail.', NULL, 'NECO_Computer_2024.json', '58da4482479c302424b2d6327e053125a66afb54e912ae8baec8575136a8ad0c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'A pixel is _____.', '["A computer program","A type of memory","The smallest unit of a digital image","A network protocol"]', 2, 'Digital images are made up of tiny dots called pixels; higher pixel density results in higher resolution.', NULL, 'NECO_Computer_2024.json', '41cd279e0a4a6ebd6edc526b5b5fe47e10eee32d8257c4ed688fb967b61c74f3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which of the following is an input device used primarily for playing computer games?', '["Scanner","Light Pen","Joystick","Plotter"]', 2, 'A joystick allows users to control movement in games by tilting a stick.', NULL, 'NECO_Computer_2024.json', 'ef88f72f98aca9886f71393499534d8dd2d953cb98b0f941b62fab9951016d46');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The ''logic'' gate that has only one input and one output is the _____.', '["AND gate","OR gate","NOT gate","XOR gate"]', 2, 'The NOT gate (inverter) always outputs the opposite of its single input.', NULL, 'NECO_Computer_2024.json', '9490073a2dc89ea5cf1256a423e0751250d1013cd89157b485a67442ca0397ec');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The capacity of a standard DVD is usually _____.', '["700 MB","4.7 GB","1.44 MB","25 GB"]', 1, 'A standard single-layer DVD can hold 4.7 GB, while a CD usually holds 700 MB.', NULL, 'NECO_Computer_2024.json', '8f7fa34dc320a90f6380e302707e346557cade3253e154e8e05d0b5e587e7734');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which of the following is a disadvantage of a computer network?', '["Resource sharing","Communication","Data Security risks","Centralized data"]', 2, 'Networks are vulnerable to unauthorized access, hacking, and the spread of malware.', NULL, 'NECO_Computer_2024.json', 'e662466181e777d97139ba4df46f9502ad9fce0f24f037eba209e7cd09c44c9d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which generation of computers introduced the use of ''Transistors''?', '["First","Second","Third","Fourth"]', 1, 'Second-generation computers (1956-1963) replaced vacuum tubes with transistors, which were smaller, faster, and more reliable.', NULL, 'NECO_Computer_2024.json', 'db69c7199680ed97054f709530acb855eccf218e5413033192d2aab2d13aa55e');
