INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'In Excel, a group of cells is known as a _____.', '["Field","Range","Record","Column"]', 1, 'A range is a collection of two or more cells, often denoted as A1:B10.', NULL, 'NECO_Computer_2024.json', '36f7ac86e3eb60c475941025366bc779205a6b57ae830ba8478cbf291dbac8df');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'Which of the following is a search engine?', '["Google Chrome","Safari","Bing","Mozilla Firefox"]', 2, 'Bing is a search engine. Chrome, Safari, and Firefox are web browsers.', NULL, 'NECO_Computer_2024.json', 'c7bf72155821825b90e14f85b26e176683a4a2b71a7134dc0d0dd00e8232e0bb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Computer', 2024, NULL, 'The smallest unit of data in a computer is a _____.', '["Bit","Byte","Character","Pixel"]', 0, 'A bit (binary digit) can have only two values: 0 or 1.', NULL, 'NECO_Computer_2024.json', 'eebc0332c94ca342980df999ec628389cf2c9e6ff298eb065f6c6e539b40f0a1');
