INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Economics is a science which studies human behavior as a relationship between ends and scarce means which have alternative uses. This definition was given by _____.', '["Adam Smith","Alfred Marshall","Lionel Robbins","John Stuart Mill"]', 2, 'Lionel Robbins provided this definition in 1932, emphasizing the relationship between unlimited ends (wants) and scarce resources.', NULL, 'NECO_Economics_2024.json', 'a9b05483747add86f0259ca564c914d7bf27fa98c9cd7944be08b1df7d90772f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The fundamental economic problem common to all societies is _____.', '["Unemployment","Inflation","Scarcity","Poverty"]', 2, 'Scarcity is the basic economic problem because resources are finite while human wants are infinite, requiring choices to be made.', NULL, 'NECO_Economics_2024.json', 'adcfa5eb97bd2d55b62d1cc3acfb815b064a1bb3d282c2b739f42271e5e8f33f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'A consumer who has #100 and buys a book instead of a pen has made an economic choice. The pen in this context is the _____.', '["Total cost","Opportunity cost","Explicit cost","Marginal cost"]', 1, 'Opportunity cost is the next best alternative forgone when a choice is made.', NULL, 'NECO_Economics_2024.json', 'c3673c5a686b1904e66980f8102788202dba7163e8be67ceef8ebf3fb4cf6510');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Which of the following will cause an inward shift of the Production Possibility Curve (PPC)?', '["Improvement in technology","Increase in the labor force","A natural disaster destroying resources","Discovery of new oil reserves"]', 2, 'An inward shift represents a decrease in the economy''s productive capacity, which happens when resources are destroyed or lost.', NULL, 'NECO_Economics_2024.json', '9093f32324cd157ed21e11aa8b79783349e5cd47b91ecc06ce7bbbca5faa4370');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The branch of economics that deals with the behavior of individual households and firms is _____.', '["Macroeconomics","Microeconomics","Positive economics","Normative economics"]', 1, 'Microeconomics focuses on small units of the economy, such as individual consumers, prices, and firms.', NULL, 'NECO_Economics_2024.json', '4cd2b91c4e553962cfd29840352ae6a12cc4d539bc1a3876e4377ba1845f1978');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'In a socialist economy, the decision on what to produce is made by _____.', '["The price mechanism","Private individuals","The central planning authority","Consumers"]', 2, 'Socialism (or command economy) is characterized by state ownership of resources and centralized decision-making.', NULL, 'NECO_Economics_2024.json', '4161c0e4527f67151a41d4126c92542aefedfa7f173aeb6df64b17963f305f12');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Which of the following is a characteristic of a capitalist economy?', '["Public ownership of means of production","Consumer sovereignty","Price control by government","Equal distribution of wealth"]', 1, 'Consumer sovereignty means that consumers'' preferences determine what goods and services are produced in a free market.', NULL, 'NECO_Economics_2024.json', '0340a958f5e3d56fccfb7a6d27150634b3b86b4a1b8582e23a2aa3ea444d02d9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'A major disadvantage of a traditional economic system is that it _____.', '["Encourages competition","Resists change and innovation","Is highly complex","Leads to high inflation"]', 1, 'Traditional systems rely on customs and heritage, which often discourages new technology and modern methods of production.', NULL, 'NECO_Economics_2024.json', '307321b72fa81957508d4b5934ce0fd61a18977ad42b30e1d4383aa161b15ede');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The law of demand states that, other things being equal, the higher the price _____.', '["The higher the quantity demanded","The lower the quantity demanded","The higher the quantity supplied","The lower the quantity supplied"]', 1, 'There is an inverse relationship between price and quantity demanded, according to the Law of Demand.', NULL, 'NECO_Economics_2024.json', 'e129f4282debcb7810003774b6dd7d000ba335b09c0c3083a177bffd94f5f644');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'A shift in the demand curve to the right indicates _____.', '["An increase in quantity demanded due to price fall","A decrease in demand","An increase in demand due to factors other than price","A contraction in demand"]', 2, 'A shift (rather than a movement along the curve) is caused by changes in income, tastes, or population, leading to a change in demand at all price levels.', NULL, 'NECO_Economics_2024.json', 'f084dfac8cdf7915d6f1829e9ce2651cfe13bb03a1fecbf532e9daeda4167b1b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'If an increase in the price of tea leads to an increase in the demand for coffee, tea and coffee are _____.', '["Complements","Substitutes","Inferior goods","Giffen goods"]', 1, 'Substitutes are goods that can be used in place of one another; an increase in the price of one increases the demand for the other.', NULL, 'NECO_Economics_2024.json', 'd29ce0f6a0e95a09af00d4cb0844463f3125b7313e95a7c9b0f1aa101b7b24c6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The demand for a factor of production is a _____.', '["Joint demand","Derived demand","Competitive demand","Composite demand"]', 1, 'Derived demand occurs when a resource (like labor) is demanded because of its contribution to the production of another good.', NULL, 'NECO_Economics_2024.json', '20b334f84313d64b607bba4fde3a69a60116596cde3b31189a39b00eb19027c5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The point where the quantity demanded equals the quantity supplied is known as _____.', '["Equilibrium point","Surplus point","Shortage point","Inflection point"]', 0, 'Market equilibrium is the price-quantity combination where there is no tendency for change because buyers and sellers are satisfied.', NULL, 'NECO_Economics_2024.json', '3b37a956673b0ddca534649890de71af6f2f45c5e1133209a93658e38dd405d0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'A government-imposed maximum price below the equilibrium price is called a _____.', '["Price floor","Price ceiling","Subsidy","Minimum wage"]', 1, 'A price ceiling is a legal maximum designed to protect consumers, but it often leads to shortages.', NULL, 'NECO_Economics_2024.json', '0d6338e6a5b2ac27352ea90a411c8650d32fe0368be95e24466832ad0689fbec');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'If the price of a commodity increases from #10 to #12 and the quantity supplied rises from 100 to 140 units, the price elasticity of supply is _____.', '["0.5","1.0","2.0","1.5"]', 2, 'ES = (% change in Qs) / (% change in P). % change Qs = 40%; % change P = 20%. 40/20 = 2.0.', NULL, 'NECO_Economics_2024.json', 'a37868961f4b41ee6be380bbfd58a288d7d0db1041f811725bd76b1d1ea8d4a2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'When the percentage change in quantity demanded is exactly equal to the percentage change in price, demand is _____.', '["Perfectly elastic","Perfectly inelastic","Unitary elastic","Inelastic"]', 2, 'Unitary elasticity occurs when the elasticity coefficient is exactly 1.', NULL, 'NECO_Economics_2024.json', '885ff9f34d51514c9fbbf36400f622f49514611d0b38b2cc5fbca5adeaf57567');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'For a normal good, the income elasticity of demand is _____.', '["Negative","Zero","Positive","Infinite"]', 2, 'Income elasticity is positive for normal goods because as income increases, demand also increases.', NULL, 'NECO_Economics_2024.json', '65623d3df02c247dcd5eb969092ee03cd7264b868e21a3fb6e258831b4ffecff');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'If the cross elasticity of demand between two goods is negative, the goods are _____.', '["Substitutes","Complements","Independent","Luxuries"]', 1, 'Negative cross elasticity means that an increase in the price of one good (e.g., cars) leads to a decrease in demand for the other (e.g., petrol).', NULL, 'NECO_Economics_2024.json', '8bc51255b9550e0197163d5e266605f3a0b53f65e2876f7ae14d45fc21ac51fe');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Total utility is at its maximum when marginal utility is _____.', '["Negative","Positive","Zero","Constant"]', 2, 'When marginal utility becomes zero, it means the consumer has reached the point of satiation, and total utility stops increasing.', NULL, 'NECO_Economics_2024.json', 'd2ddb34e87bcc8e0a087b6fb15b779c2125422aeac74f7d9ef38ab036560ec9e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The Law of Diminishing Marginal Utility states that as more of a commodity is consumed _____.', '["Total utility increases at an increasing rate","Marginal utility increases","Additional satisfaction from an extra unit decreases","Total utility decreases immediately"]', 2, 'This law explains that the satisfaction derived from each additional unit of a good falls as consumption increases.', NULL, 'NECO_Economics_2024.json', '6ed58229ca7c51c9350e05f74c4a8f04a9b4cc01569136da9da35ce524f645a5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'An ''Inferior Good'' is defined as one for which demand falls when _____.', '["Price falls","Income rises","Income falls","Price of complements rises"]', 1, 'As consumers'' income rises, they switch from low-quality (inferior) goods to higher-quality substitutes.', NULL, 'NECO_Economics_2024.json', '6c9668a447d54a02a83f0877e57812dc41707a3cc52542f2d2a75b680328c07a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The primary objective of a firm in a capitalist system is to _____.', '["Provide social services","Maximize profit","Minimize employment","Control the government"]', 1, 'The profit motive is the driving force for production in a free-market economy.', NULL, 'NECO_Economics_2024.json', 'c14fb69c04dcba9bc5bba21182ea3a60f93e313b68d7b27071a0040481eb8f21');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Which factor of production is geographically immobile but occupationally mobile?', '["Labor","Capital","Land","Entrepreneur"]', 2, 'Land cannot be moved from one location to another (geographically immobile), but its use can change from agriculture to housing (occupationally mobile).', NULL, 'NECO_Economics_2024.json', '5eacf823438c855ca037eb4eb35c416179c4ac840255ce59b677f143d3b47e0d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The reward for Land as a factor of production is _____.', '["Wages","Interest","Profit","Rent"]', 3, 'Rent is the payment made for the use of land and other natural resources.', NULL, 'NECO_Economics_2024.json', '6377b9f892d83126bccdec1c38f8be2757ae2af11dc9218d233f0daa168b10a1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Division of labor is limited by _____.', '["Government policy","The size of the market","The number of factories","The availability of money"]', 1, 'Adam Smith noted that the degree of specialization (division of labor) depends on the extent of the market or the volume of demand.', NULL, 'NECO_Economics_2024.json', '142b8b48e2b32be4e829ad50cce6dc4b2c2946880f4a0ad15b621ded2e2ef4f4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The ''Short Run'' in production is a period where _____.', '["All factors are fixed","All factors are variable","At least one factor is fixed","Production is stopped"]', 2, 'In the short run, some inputs (like machinery or land) cannot be changed, while others (like labor) can.', NULL, 'NECO_Economics_2024.json', 'c3bf494b741446045fe0a7e4df89ab10c04457839741cd7b5314e051066b22b1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The Law of Diminishing Returns occurs when _____.', '["Total product starts decreasing","Average product is zero","Marginal product begins to decline","Fixed costs increase"]', 2, 'The law states that adding more of a variable factor to a fixed factor will eventually lead to a decline in the marginal output.', NULL, 'NECO_Economics_2024.json', '43d97392fbaf4c401fe47b3c7a58133a8976c269aa5b725f86f6280a911a32b2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'A production process that results in a double output for a more than double increase in input exhibits _____.', '["Constant returns to scale","Increasing returns to scale","Decreasing returns to scale","Diminishing returns"]', 2, 'Decreasing returns to scale occur when the percentage increase in output is less than the percentage increase in inputs.', NULL, 'NECO_Economics_2024.json', '7744f1efb5228238d4bbbfc9ed9d4b057efdd836f5f53321a4a84e4417685f25');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Which cost remains constant regardless of the level of output?', '["Variable cost","Marginal cost","Total Fixed Cost","Average Variable Cost"]', 2, 'Fixed costs (like rent or insurance) do not change with the volume of production in the short run.', NULL, 'NECO_Economics_2024.json', '227c38ccaa7b93529cef03d40f7eb106acfe9d3aa7a556dc3d9a12f1607a4251');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Average Cost is calculated as _____.', '["TC / Q","TVC / Q","Change in TC / Change in Q","TFC + TVC"]', 0, 'Average Total Cost (AC) is the total cost of production divided by the number of units produced.', NULL, 'NECO_Economics_2024.json', '28e5ba2cfcbff237d0bb057061d68914023be4073171d63f9de5e9a3f297a152');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'In a perfectly competitive market, the firm is a _____.', '["Price maker","Price taker","Monopolist","Oligopolist"]', 1, 'Because there are many firms producing identical products, no single firm can influence the market price.', NULL, 'NECO_Economics_2024.json', '8c824a459b720298325987a86857ed12c3cf76c1319b9237e9106479b415d94d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'A market structure with only one seller and no close substitutes is a _____.', '["Duopoly","Oligopoly","Monopoly","Monopsony"]', 2, 'Monopoly refers to a single producer dominating the entire market.', NULL, 'NECO_Economics_2024.json', '7c5f59fd9efcd44adb752e604686d2ef295f664cd922e6a1a087c630e11954fc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The ''Monopsony'' market is characterized by _____.', '["One seller","One buyer","Many sellers","Many buyers"]', 1, 'Monopsony occurs when there is only one buyer for a product or service, such as a single large employer in a small town.', NULL, 'NECO_Economics_2024.json', '54107bae5a5fc22ab4876949946c24ef0a3f180d20fac993802a1ff191730b17');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Cartels are typically found in which market structure?', '["Perfect competition","Monopolistic competition","Oligopoly","Monopoly"]', 2, 'In an oligopoly, a few large firms may collude (form a cartel) to set prices or restrict output to increase profits.', NULL, 'NECO_Economics_2024.json', 'fdccfe2f0963d5c8f45fbf6f8e9cdc8585dda2f06fa5b23702809de71afcd75b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Gross Domestic Product (GDP) measures the value of goods and services produced _____.', '["By citizens of a country only","Within the geographical boundaries of a country","By government agencies only","For export only"]', 1, 'GDP is location-based; it includes everything produced inside the country, regardless of the nationality of the producer.', NULL, 'NECO_Economics_2024.json', 'fb9d8795ba86f8a9740c0241f07184b0696adf597262f14e618dc07e3830133c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The formula for calculating National Income using the Expenditure approach is _____.', '["C + I + G + (X - M)","C + I + G + (M - X)","Wages + Rent + Interest + Profit","Output - Intermediate consumption"]', 0, 'Expenditure method sums Consumption, Investment, Government spending, and Net Exports (Exports minus Imports).', NULL, 'NECO_Economics_2024.json', '7936d8dba7f1e99df6310c9fc45a45a8afcc0706659ebc5553303cb38f641304');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Real National Income is National Income adjusted for _____.', '["Depreciation","Taxes","Inflation","Subsidies"]', 2, 'Real values account for changes in the price level (inflation) to show the actual volume of production.', NULL, 'NECO_Economics_2024.json', '04e049fd8325d91a067f77ba969ce81233a1132afbd5cfaafdc5a9ba8227d451');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The difference between Gross National Product (GNP) and Net National Product (NNP) is _____.', '["Net income from abroad","Indirect taxes","Depreciation","Subsidies"]', 2, 'NNP = GNP minus Depreciation (consumption of fixed capital).', NULL, 'NECO_Economics_2024.json', '3df8288c8f6f531a2683c859001aa4fed250631ff9d21c7dbdcc13cba2948908');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Which of the following is a function of money?', '["Standard for deferred payment","Cause of inflation","Fixed value","Tool for hoarding"]', 0, 'Money allows for credit transactions where payments are made at a future date.', NULL, 'NECO_Economics_2024.json', '1478e88eca2072decd1d262f70608517f1b2d12e9f7a6083ee410920585a346e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'M1 money supply consists of _____.', '["Currency in circulation and demand deposits","Savings deposits and time deposits","Gold and silver","Foreign exchange reserves"]', 0, 'M1 is the narrowest definition of money, consisting of highly liquid assets like cash and bank checking accounts.', NULL, 'NECO_Economics_2024.json', '202de7f9a8685a1f6812c85a8a7feb4a56c1155eb0af888a3b947a0869c5766f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The rate at which the Central Bank lends money to commercial banks is the _____.', '["Interest rate","Lending rate","Bank rate","Exchange rate"]', 2, 'The bank rate (or discount rate) is a tool used by the Central Bank to control the money supply.', NULL, 'NECO_Economics_2024.json', '2214ab469092b6dfdded6f758ecf52dece805a181fee7be1855a913dd7a46a9a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'To control inflation, the Central Bank should _____.', '["Buy government securities","Reduce the reserve requirement","Sell government securities","Lower the bank rate"]', 2, 'Selling securities (Open Market Operations) mops up excess cash from the banking system, reducing the money supply.', NULL, 'NECO_Economics_2024.json', 'c44b4c1b9bb50678ac2d6d01bc5c520f53c28780325e009582c52b4b78af7ff2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Inflation caused by an increase in the cost of production is _____.', '["Demand-pull inflation","Cost-push inflation","Hyperinflation","Creeping inflation"]', 1, 'Cost-push inflation happens when rising wages or raw material prices force producers to increase their prices.', NULL, 'NECO_Economics_2024.json', '007f8226e8767723769e664386401771f6f1df5feeb9523f68decf8cc0464fe1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'A person who is out of work because of a mismatch between their skills and the available jobs is experiencing _____.', '["Frictional unemployment","Cyclical unemployment","Structural unemployment","Seasonal unemployment"]', 2, 'Structural unemployment occurs when the structure of the economy changes, making certain skills obsolete.', NULL, 'NECO_Economics_2024.json', '2f2530ea03358e245094731f4736d32d90621e01835fe64859ccd366ddd86e90');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Malthus''s theory of population suggests that population grows _____.', '["Arithmetically","Geometrically","Linearly","Slowly"]', 1, 'Thomas Malthus argued that population increases in a geometric progression (1, 2, 4, 8...), outstripping food supply.', NULL, 'NECO_Economics_2024.json', '403d6005ce0ef34bd98e5d8bd2f6d9861f103cffd71119ab3bd5f214ecaeb158');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The Dependency Ratio is the ratio of _____.', '["Men to women","Workers to the total population","The non-working population to the working population","Births to deaths"]', 2, 'It measures the pressure on the productive part of the population to support the young and the elderly.', NULL, 'NECO_Economics_2024.json', '682783545b1d3857207d4f1922a7e6a9ebb0243b8dee1d4fa787260a30b7be69');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'A budget deficit occurs when _____.', '["Revenue equals expenditure","Expenditure exceeds revenue","Revenue exceeds expenditure","Exports exceed imports"]', 1, 'A deficit means the government is spending more than it earns from taxes and other sources.', NULL, 'NECO_Economics_2024.json', 'f5ffed36a4f652e9c9c629262dbe974d4c3fbaa4c41f0c1406424813df39d76e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Which of the following is a direct tax?', '["Value Added Tax (VAT)","Excise duty","Personal Income Tax","Customs duty"]', 2, 'Direct taxes are levied on individuals or companies and cannot be shifted to others.', NULL, 'NECO_Economics_2024.json', 'ec9f75ee9644eedd27475e5c52cf1d7be9ce354b6e223ec63ac5cc6a117d5dd3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The ''Ability to Pay'' principle of taxation suggests that _____.', '["Everyone should pay the same amount","Tax should be based on the benefits received","Rich people should pay a higher percentage of their income","Taxes should be voluntary"]', 2, 'This principle supports progressive taxation, where those with higher income contribute more to the state.', NULL, 'NECO_Economics_2024.json', '76bd9e7b02cbf04da638ae3c81c58ded7153402bb959d09224882cb7410bef20');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'A tax system where the rate of tax increases as income increases is _____.', '["Regressive","Proportional","Progressive","Specific"]', 2, 'Progressive taxes (like income tax in Nigeria) aim to reduce income inequality.', NULL, 'NECO_Economics_2024.json', '3b53a89bda66e6e23b8eaa793103a5351b7e7022751fd09e066e17f20c96054a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Comparative advantage theory was popularized by _____.', '["Adam Smith","David Ricardo","J.M. Keynes","Milton Friedman"]', 1, 'David Ricardo argued that countries should specialize in producing goods for which they have the lowest opportunity cost.', NULL, 'NECO_Economics_2024.json', 'fd30d18d53a6de87763d994dd0533efa49e53599742730c8dd60a3d60c293467');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The ''Terms of Trade'' is defined as the ratio of _____.', '["Export prices to import prices","Export volume to import volume","Net exports to GDP","National income to population"]', 0, 'Terms of Trade = (Index of Export Prices / Index of Import Prices) x 100.', NULL, 'NECO_Economics_2024.json', '1aa95413ccfad8a51e065a16e8e7d08675d69524aac83c6d7936c285b898395f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'A systematic record of all economic transactions between a country and the rest of the world is the _____.', '["Balance of Trade","Balance of Payments","Current Account","Capital Account"]', 1, 'Balance of Payments (BOP) includes the trade of goods, services, and capital movements.', NULL, 'NECO_Economics_2024.json', '901e0b0e42411f0550a3263019ff5c072ed27b38767fd17bb3da03b9bed94175');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Devaluation of a currency is intended to _____.', '["Make imports cheaper","Increase the value of the currency","Make exports cheaper and imports more expensive","Reduce the money supply"]', 2, 'By lowering the value of the currency, a country''s goods become cheaper for foreigners, theoretically improving the trade balance.', NULL, 'NECO_Economics_2024.json', '4ac57313922acc746a450aef66582396a6093af047ccf22e19c3d2793e083e0e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Which of the following is a member of OPEC?', '["Ghana","Nigeria","South Africa","Kenya"]', 1, 'Nigeria joined the Organization of the Petroleum Exporting Countries (OPEC) in 1971.', NULL, 'NECO_Economics_2024.json', '3bfd5ff57e1c79af550f67e71a7dded39bb9aa47da65ec305e909ba8e0b6df44');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The ''Petro-dollar'' refers to _____.', '["Currency used only in oil markets","US dollars earned from the export of petroleum","A special currency created by OPEC","The cost of refining one barrel of oil"]', 1, 'Because oil is globally traded in US dollars, the revenue generated by oil-exporting nations is called petro-dollars.', NULL, 'NECO_Economics_2024.json', 'd2755821e2ba1635442392798286bc56d67b5d49981a0c05a706314e1cdad33e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The main objective of the Economic Community of West African States (ECOWAS) is _____.', '["Military defense","Economic integration","Political unification","Religious harmony"]', 1, 'ECOWAS aims to foster cooperation and development in all fields of economic activity among West African nations.', NULL, 'NECO_Economics_2024.json', '06b6856f0c499400dcca593c9d868b07446a65851135ac26222f7089f8de2320');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Economic growth is best measured by an increase in _____.', '["Nominal GDP","Real GDP","Total population","Money supply"]', 1, 'Real GDP growth indicates an actual increase in the production of goods and services over time.', NULL, 'NECO_Economics_2024.json', '626a74a6f9fc6aeda051cd64be9cffa856cb66b3859d9cbc79dd2da312658ef2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The ''Primary Sector'' of the Nigerian economy is dominated by _____.', '["Manufacturing","Banking","Agriculture and Mining","Telecommunications"]', 2, 'The primary sector involves the extraction of natural resources.', NULL, 'NECO_Economics_2024.json', '19549add256b8d4cc79a3b01a08ca6e1df8f582b02b963bf4986e0782ee18371');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Which of the following is a barrier to international trade?', '["Free trade zones","Tariffs","Bilateral agreements","Globalization"]', 1, 'Tariffs are taxes on imported goods used to protect local industries and raise revenue.', NULL, 'NECO_Economics_2024.json', 'b2fc6d9f7a31ba982c44946d352bebd8310eb888cf9ff7649aaabe1456d12df3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The ''Laffer Curve'' shows the relationship between _____.', '["Inflation and unemployment","Tax rates and tax revenue","Income and consumption","Price and quantity supplied"]', 1, 'It suggests that there is an optimal tax rate that maximizes revenue; rates beyond that point may discourage work and reduce total revenue.', NULL, 'NECO_Economics_2024.json', '3734c2c581fbd73ba63d4d2a7b93714c87de8484c3cf80e630f6f73629f6af98');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Public goods are characterized by _____.', '["Excludability and rivalry","Non-excludability and non-rivalry","High market prices","Private ownership"]', 1, 'Public goods (like street lights) can be used by anyone without reducing availability for others, and nobody can be easily prevented from using them.', NULL, 'NECO_Economics_2024.json', 'cb29b1955ee64c38b557644f294d0da6d298f22e93cb9d6755e5f74c2857a75f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'A ''Giffen Good'' is one whose demand curve is _____.', '["Downward sloping","Upward sloping","Vertical","Horizontal"]', 1, 'Giffen goods are a rare exception to the law of demand; as their price rises, people buy more because they cannot afford better substitutes.', NULL, 'NECO_Economics_2024.json', '9745665388b76e4697ce34ae6370aab5982a919ad7f600d861388dbfc960452f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The average number of children born to a woman during her lifetime is the _____.', '["Birth rate","Death rate","Fertility rate","Growth rate"]', 2, 'The total fertility rate is a key demographic indicator used to project population growth.', NULL, 'NECO_Economics_2024.json', 'b694177cfcbf70ea1f1f8805be65f882750aff8e75f3e13037d3f0e499c74406');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Which of the following is an example of an indirect tax?', '["Company profit tax","Capital gains tax","Value Added Tax (VAT)","Personal income tax"]', 2, 'Indirect taxes are levied on goods and services; the burden is often passed to the final consumer.', NULL, 'NECO_Economics_2024.json', '9f4b81777142d5b200138206bb75aa9951bec44385e44bcf142613cef30dc841');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The process of moving from a centrally planned economy to a market economy is _____.', '["Nationalization","Privatization","Commercialization","Deregulation"]', 1, 'Privatization involves transferring the ownership of state-run enterprises to the private sector.', NULL, 'NECO_Economics_2024.json', '79a46c0ceaefaf8eb28b64c94e383d42a036f11a527e35c4d83c70156bdcdbbe');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The World Bank is also known as the _____.', '["IMF","IBRD","WTO","UNCTAD"]', 1, 'The International Bank for Reconstruction and Development (IBRD) is the core arm of the World Bank.', NULL, 'NECO_Economics_2024.json', 'e0a3c91abef180b6a3182baa6ac28ea991bc07770882c494a6ada8958a830813');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Deflation is a period of _____.', '["Rising prices","Falling prices","High unemployment","Rapid economic growth"]', 1, 'Deflation is a sustained decrease in the general price level of goods and services.', NULL, 'NECO_Economics_2024.json', '81f75e6746df5fa4cba3afa075d670039aaaffd9b568db2c6edb868c8de26dc5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'The demand for labor by a firm is determined by the _____.', '["Marginal Physical Product","Price of the product","Marginal Revenue Product","All of the above"]', 3, 'A firm will hire labor up to the point where the cost of the last worker (wage) equals the value of what that worker produces (MRP).', NULL, 'NECO_Economics_2024.json', 'fe933a6847d11e34ff9ad99b1153cfaa75e9fdeaebbfe89725966e71efde6369');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Economics', 2024, NULL, 'Economic development differs from economic growth because it includes _____.', '["Only quantitative changes","Only qualitative changes","Both quantitative and qualitative changes","Neither"]', 2, 'Growth is an increase in output, while development includes structural changes, better health, and higher literacy rates.', NULL, 'NECO_Economics_2024.json', 'a1eec8510af6291a4953378efffcacb33b0210c2b5e40f768cce566060f6dca0');
