INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Which of the following planets is known as the ''Red Planet''?', '["Venus","Mars","Jupiter","Saturn"]', 1, 'Mars is often called the Red Planet because of the iron oxide (rust) on its surface, which gives it a reddish appearance.', NULL, 'NECO_Geography_2024.json', '2c790adcc18440a67d7c2f26c7c8926dbec459fb3b867b54eca722e9364dff49');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The spinning of the earth on its axis from West to East once every 24 hours is called _____.', '["Revolution","Rotation","Inclination","Precision"]', 1, 'Rotation is the Earth''s movement around its axis, which causes day and night. Revolution is the movement around the sun.', NULL, 'NECO_Geography_2024.json', '612a98eddbaf3a1b2232db45bd1e7136da5589e66868f7c62e54eca269f582d2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Calculate the time at Longitude 45°W when the time at the Greenwich Meridian is 12:00 noon.', '["9:00 am","3:00 pm","9:00 pm","3:00 am"]', 0, 'The earth rotates 15° per hour. 45°/15° = 3 hours. Since the location is West of Greenwich, we subtract: 12 noon - 3 hours = 9:00 am.', NULL, 'NECO_Geography_2024.json', '1f8965278acf7337953614340c59d0fe902c1ace65f1f02c8268023a7a4d275c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The layer of the earth''s atmosphere where weather phenomena occur is the _____.', '["Stratosphere","Mesosphere","Troposphere","Thermosphere"]', 2, 'The troposphere is the lowest layer of the atmosphere and contains most of the water vapor and dust, making it the primary site for weather activity.', NULL, 'NECO_Geography_2024.json', '8b9e11677651bd85bf934ffbf85dc07da1f43b8f16a4b08b3a7db6b3d5c19b5d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Which of the following is a sedimentary rock formed by chemical processes?', '["Coal","Sandstone","Limestone","Granite"]', 2, 'Limestone can be formed chemically through the precipitation of calcium carbonate from water, making it a chemically formed sedimentary rock.', NULL, 'NECO_Geography_2024.json', '2199194a1bd8774e06cdd2e4643d842b656961d81524aaf2df024f9d45c04ea4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The point on the Earth''s surface directly above the origin of an earthquake is the _____.', '["Focus","Hypocenter","Epicenter","Crater"]', 2, 'The epicenter is the point on the surface directly above the focus (or hypocenter) where the seismic waves originate inside the earth.', NULL, 'NECO_Geography_2024.json', '9f8f4529d4168564a061712b79be66211960ac1d2727738c2276fbb3b5ec945b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'A plateau surrounded by mountains is known as a/an _____ plateau.', '["Piedmont","Continental","Intermontane","Volcanic"]', 2, 'Intermontane plateaus are the highest and most extensive plateaus in the world, completely enclosed by mountain ranges (e.g., the Tibetan Plateau).', NULL, 'NECO_Geography_2024.json', 'ce28e7a1eb04b91dbd940bb056595f963ff2987da3e095ddfcaf3cbdfd1acae2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The process by which rocks are broken down by the action of plants and animals is _____ weathering.', '["Physical","Chemical","Biological","Exfoliation"]', 2, 'Biological weathering involves the disintegration of rocks caused by living organisms, such as tree roots growing into cracks.', NULL, 'NECO_Geography_2024.json', 'dab1422bb05419825e24e5e3462941d876c2655e173554778f0223f5120faec7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Which of the following landforms is associated with the middle course of a river?', '["V-shaped valley","Meander","Delta","Gorge"]', 1, 'Meanders are loop-like bends in a river that develop as it enters its middle course and starts eroding laterally.', NULL, 'NECO_Geography_2024.json', '91b2248b404221ced0bca2ad7216586e0ef891e9dd2a2f4a32df4c5e3ebcfd87');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The type of rainfall associated with the meeting of warm and cold air masses is _____.', '["Convectional","Orographic","Cyclonic","Relief"]', 2, 'Cyclonic (or Frontal) rainfall occurs when a warm, moist air mass meets a cold, dry air mass; the warm air is forced upward, leading to condensation.', NULL, 'NECO_Geography_2024.json', '0f8d94e8e57073222a40cbafb60c3bcad8200aee87fa40c670cf317d75767fae');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The instrument used to measure the intensity of solar radiation is the _____.', '["Thermometer","Barometer","Pyranometer","Anemometer"]', 2, 'A pyranometer is a sensor designed to measure solar irradiance on a planar surface.', NULL, 'NECO_Geography_2024.json', 'c757762d863b66a0a55a0f8abc92d86c2136eec17e4d7cc8efa66e6904ea608f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The transfer of heat through the movement of a fluid (liquid or gas) is _____.', '["Conduction","Convection","Radiation","Insulation"]', 1, 'Convection is the transfer of heat by the actual movement of the heated parts of a liquid or gas.', NULL, 'NECO_Geography_2024.json', '3457043fd7f098db5deb8c99a3ca968d5af653c08e0792b076081da243b8cf24');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Which of the following is a characteristic of Mediterranean vegetation?', '["Buttress roots","Conical shapes","Thick waxy leaves","Tall grass"]', 2, 'Mediterranean plants have thick, waxy, or leathery leaves (sclerophyllous) to reduce transpiration during the hot, dry summers.', NULL, 'NECO_Geography_2024.json', 'bc96a3e51015004916b51ab926f9037fa419955641c7810625b54f14053c0755');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The ratio of the map distance to the actual ground distance is called the _____.', '["Legend","Scale","Grid","Projection"]', 1, 'The scale of a map tells us the relationship between distance on the map and the corresponding distance on the ground.', NULL, 'NECO_Geography_2024.json', '6dd7ec15a73666010b92bbff7d5d4e6c15659198165b5d799c26db5474834d29');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Which of the following is a primary economic activity?', '["Banking","Manufacturing","Mining","Teaching"]', 2, 'Primary activities involve the extraction of natural resources directly from the earth (e.g., farming, mining, fishing).', NULL, 'NECO_Geography_2024.json', 'fd5912ed42e1dc0f15e5dfd81bba0dd256dfd3485316df52d54d00f4108f3bf4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The leading producer of cocoa in West Africa is _____.', '["Nigeria","Ghana","Ivory Coast","Sierra Leone"]', 2, 'Ivory Coast (Côte d''Ivoire) is the world''s largest producer and exporter of cocoa beans.', NULL, 'NECO_Geography_2024.json', '49182f13ed3149f02de8a813cbb7a329fcfca4edc5fee83efd3efe6d767bf16a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Environmental pollution caused by the release of toxic substances into water bodies is _____.', '["Air pollution","Water pollution","Noise pollution","Land pollution"]', 1, 'Water pollution occurs when harmful substances like chemicals or microorganisms contaminate a stream, river, or lake.', NULL, 'NECO_Geography_2024.json', '4971352e4fce815c6899126a8b13d863ac8d4375eed4fdcca235e775005d7abc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The highest mountain peak in Nigeria is _____.', '["Zuma Rock","Chappal Waddi","Olumo Rock","Idanre Hill"]', 1, 'Chappal Waddi, located in the Mambilla Plateau, is the highest point in Nigeria at approximately 2,419 meters.', NULL, 'NECO_Geography_2024.json', 'a9a5ec20589a9f4c1bed9d92b2c6abf5e4b16d0ab8f3852f4019e84ea55908c1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Which of the following states in Nigeria is known for the commercial production of Tin and Columbite?', '["Kano","Plateau","Enugu","Oyo"]', 1, 'The Jos Plateau in Plateau State is the primary region for tin and columbite mining in Nigeria.', NULL, 'NECO_Geography_2024.json', '2c84bb4dbfc6a059413c6fb7945a5377fecb1a703f303c182fa9d5ad6e7163a6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The confluence of the River Niger and River Benue is located at _____.', '["Lagos","Kano","Lokoja","Onitsha"]', 2, 'Lokoja, the capital of Kogi State, is situated at the meeting point of Africa''s two great rivers, the Niger and the Benue.', NULL, 'NECO_Geography_2024.json', '7db90af681ec86f8debfda87507d91a9e46c089ce024515475af423f9b0c1d1c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'In a GIS, ''Attribute Data'' refers to _____.', '["Coordinates","Descriptive information","Pixel values","Shapefiles"]', 1, 'Attribute data in Geographic Information Systems provides non-spatial descriptive information about geographic features (e.g., the name of a city).', NULL, 'NECO_Geography_2024.json', '00e265171e84c121545e4202b8aaf2ad9ce140c7f9b7adf3f4955bc49b0f7e7f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The movement of people from rural areas to urban centers is called _____.', '["Emigration","Immigration","Urbanization","Rural-urban migration"]', 3, 'Rural-urban migration specifically describes the internal movement of people from the countryside to the cities.', NULL, 'NECO_Geography_2024.json', '59331f5b910e9fc05d78b4fba6b9b11234e9f07c4b52f66eef38f127f650325d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Which of the following is a non-renewable resource?', '["Solar energy","Natural gas","Wind energy","Water"]', 1, 'Natural gas is a fossil fuel that takes millions of years to form; once it is used up, it cannot be replaced in a human timeframe.', NULL, 'NECO_Geography_2024.json', '4c1e754b1d644ea1023f001d32ccfb8c482d790ab0ec12c610dd984f10515ccd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The line on a map joining places of equal rainfall is an _____.', '["Isotherm","Isobar","Isohyet","Isohel"]', 2, 'Isohyets are lines on a map connecting points that receive the same amount of rainfall.', NULL, 'NECO_Geography_2024.json', 'cfdc1b28a1fb726705ff593b3ec6e40e194da45b3a6400b3c11b68f8934e5ea2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The ''Ring of Fire'' is a region of high volcanic and seismic activity located around the _____.', '["Atlantic Ocean","Indian Ocean","Pacific Ocean","Arctic Ocean"]', 2, 'The Pacific Ring of Fire is a major area in the basin of the Pacific Ocean where many earthquakes and volcanic eruptions occur.', NULL, 'NECO_Geography_2024.json', 'c9ff8f2fe67f8f4db3643f000f81d175ca72c9c37516cd926fa188d6a20d8228');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'A map with a scale of 1:250,000 is a _____ scale map compared to 1:50,000.', '["Small","Large","Medium","Topographical"]', 0, 'A smaller scale map covers a larger area with less detail. 1:250,000 is smaller than 1:50,000 because the denominator is larger.', NULL, 'NECO_Geography_2024.json', '445f80591bc5b202816c26bd6e0b73fe69daf108bb83c7b6a7176ffcfcccaea0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Which of the following factors most influences the climate of West Africa?', '["Altitude","Latitude","The Inter-Tropical Convergence Zone (ITCZ)","Ocean currents"]', 2, 'The movement of the ITCZ determines the seasonal patterns of rainfall and the dry Harmattan winds in West Africa.', NULL, 'NECO_Geography_2024.json', 'fc4bd5f625b36cc827acd5ce3186f53a9502c235a9d39aa142259c295c644e55');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The study of human population statistics is known as _____.', '["Demography","Cartography","Geology","Anthropology"]', 0, 'Demography is the statistical study of human populations, including their size, structure, and distribution.', NULL, 'NECO_Geography_2024.json', 'a10b6361fa78971460e36cb839960041682286e8b3ca02e82ade4508213e689b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'An example of a block mountain in Africa is the _____.', '["Atlas Mountains","Drakensberg Mountains","Ruwenzoiri Mountains","Mount Kilimanjaro"]', 2, 'The Ruwenzori Mountains (Mountains of the Moon) are an example of a block mountain (horst) formed by tectonic uplifting.', NULL, 'NECO_Geography_2024.json', '960f2e9b4ead7125c3278224c84ddff996240e8a7b47885fc41824e4ea3eb01b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Which of the following is a major challenge for the ECOWAS region?', '["Too much rainfall","Political instability","Lack of labor","Excessive gold"]', 1, 'Political instability, including coups and civil unrest, has historically hindered economic integration in the West African sub-region.', NULL, 'NECO_Geography_2024.json', '19ec070ecdcc4db3a83d46e8848c53f60fe2cf7665be94fcf54ae3949be2b068');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The boundary between the Earth''s crust and the mantle is the _____.', '["Gutenberg Discontinuity","Mohorovicic Discontinuity","Asthenosphere","Lithosphere"]', 1, 'The Mohorovicic Discontinuity (Moho) is the boundary separating the crust from the underlying mantle.', NULL, 'NECO_Geography_2024.json', '3c5ee6c0e3cc6ceb7fd4e9ea7a4fa15b5cd5948c1fbdb1adc4382e5d7f2e6d22');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Steep-sided, U-shaped valleys are formed by _____.', '["Wind erosion","Glacial erosion","River erosion","Marine erosion"]', 1, 'Glaciers carve out deep, steep-sided U-shaped valleys, whereas rivers typically create V-shaped valleys.', NULL, 'NECO_Geography_2024.json', 'b873596948ab1363a695a3ca6300c0beb4f7e793ca63e4b151fa74f23615db8f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The world''s largest hot desert is the _____.', '["Kalahari","Gobi","Sahara","Atacama"]', 2, 'The Sahara in North Africa is the largest hot desert in the world, covering over 9 million square kilometers.', NULL, 'NECO_Geography_2024.json', '147374e701d19bdaefca9d9ca092437135c07cb7a8ab29d6cab1c8f29aaadd11');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Which ocean current is a warm current?', '["Benguela Current","Canaries Current","Gulf Stream","California Current"]', 2, 'The Gulf Stream is a powerful, warm Atlantic ocean current that originates in the Gulf of Mexico.', NULL, 'NECO_Geography_2024.json', '24bac1c9909fcfdfaca3fba58d7aa8f1a51c321ac4d3306138eaa23a4113efed');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The ''Greenhouse Effect'' is primarily caused by an increase in _____.', '["Oxygen","Nitrogen","Carbon dioxide","Argon"]', 2, 'Carbon dioxide (
