INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The state in Nigeria with the smallest land area is _____.', '["Lagos","Kano","Rivers","Anambra"]', 0, 'Lagos State is the smallest state in Nigeria by landmass, despite having one of the highest populations.', NULL, 'NECO_Geography_2024.json', '78f8428196e0c16f3af92cad0f030b355905491119033e2808190e0a727fcb3e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'An example of a fold mountain in the world is the _____.', '["Himalayas","Vosges","Black Forest","Jos Plateau"]', 0, 'The Himalayas were formed by the collision of tectonic plates, which folded the earth''s crust.', NULL, 'NECO_Geography_2024.json', 'e904b23c77e415a983c59b4558856b8b1d53044f4d80d881a06581c152a5e8ca');
