INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The mapping of the ocean floor is called _____.', '["Topography","Bathymetry","Cartography","Demography"]', 1, 'Bathymetry is the study of the ''beds'' or ''floors'' of water bodies, including the ocean.', NULL, 'NECO_Geography_2024.json', '9262c90bda8db443c258971ae544e5ec9bb4dc63bf6a41531cd06ffe80065187');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Which of the following is a push factor in migration?', '["Better jobs","Quality education","Drought and famine","Safety"]', 2, 'Push factors are negative conditions that force people to leave their current location, such as drought.', NULL, 'NECO_Geography_2024.json', 'e4e3ade03d95a8f38199a8fa090783ffe9046a271d9199cb1157d06c79db4486');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The deepest lake in the world is Lake _____.', '["Victoria","Superior","Baikal","Chad"]', 2, 'Lake Baikal in Russia is the world''s deepest and oldest freshwater lake.', NULL, 'NECO_Geography_2024.json', 'a23103a5d951a2edd580a611c27026993fa335d0c7848b0026adf3cb74608018');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The leading producer of coal in Nigeria is _____.', '["Enugu","Kogi","Delta","Akwa Ibom"]', 0, 'Enugu is famously known as the ''Coal City'' due to its history of coal mining.', NULL, 'NECO_Geography_2024.json', '7e6f76024c179205a896c2b868741881a8d3861aec30e08d36f8d6ee6d918836');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'A compass direction of 225° represents _____.', '["North-East","South-East","South-West","North-West"]', 2, 'On a 360° compass, 0/360 is North, 90 is East, 180 is South, and 270 is West. 225 is midway between South (180) and West (270).', NULL, 'NECO_Geography_2024.json', 'd7c3516e63b09ccffc36e6d360770353e2f1fd2419b22706e8851ccf226478c3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Which of the following is a renewable energy source?', '["Coal","Petroleum","Solar","Nuclear"]', 2, 'Solar energy is derived from the sun and is naturally replenished, unlike fossil fuels.', NULL, 'NECO_Geography_2024.json', '20fd3b69ee94cc1e13a61ef570b39ad145809a29fa2e2209f38a970e6a08d237');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The imaginary line that divides the Earth into the Northern and Southern Hemispheres is the _____.', '["Prime Meridian","Equator","Tropic of Cancer","International Date Line"]', 1, 'The Equator is the 0° latitude line that bisects the Earth into North and South.', NULL, 'NECO_Geography_2024.json', 'c3abbccf27dfa6ccc88305657d32cbd61a7d9c041c119cf68ba2b23343d3f1ca');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Which of the following is a secondary economic activity?', '["Farming","Mining","Textile production","Banking"]', 2, 'Secondary activities involve the processing of raw materials into finished goods (manufacturing).', NULL, 'NECO_Geography_2024.json', '2ff1940bfe816d7194ec27459fb9c9299c184acef1802392444ee30a3223cfc2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The scale of a map expressed as 1cm to 2km is a _____ scale.', '["Statement","Linear","Representative Fraction","Diagonal"]', 0, 'A statement scale expresses the scale in words, such as ''1 centimeter represents 2 kilometers''.', NULL, 'NECO_Geography_2024.json', '65a6658f254fef7ee6fdf18c4cd9bec4c29319ec6b609758041f157003a7a3c7');
