INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'The process by which water changes from a liquid to a gas is _____.', '["Condensation","Evaporation","Sublimation","Freezing"]', 1, 'Evaporation occurs when liquid water is heated and turns into water vapor.', NULL, 'NECO_Geography_2024.json', '8847831bef89096b571869756a3fbf1124be6d72536155a897755ff69c7855d4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Geography', 2024, NULL, 'Which of the following is a biotic component of an ecosystem?', '["Soil","Water","Bacteria","Sunlight"]', 2, 'Biotic components are the living parts of an ecosystem, such as plants, animals, and bacteria.', NULL, 'NECO_Geography_2024.json', '2d1a5365ca2e2ac80880820bc88e4fb6d8ff73c02d9ac7c5bbe3e9824d34007f');
