INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The supreme power of a state to make and enforce laws within its territory without external interference is known as _____.', '["Authority","Sovereignty","Legitimacy","Power"]', 1, 'Sovereignty is the ultimate, absolute power of a state to govern itself and its people without being subject to any other authority.', NULL, 'NECO_Government_2024.json', 'daf88a3e2ce553a69178621eec62d4334bc915ef4b66930619ecae1d0d742ec6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Which of the following is an essential element of a state?', '["Common language","Defined territory","A large army","A single religion"]', 1, 'A state must have four essential elements: population, defined territory, government, and sovereignty.', NULL, 'NECO_Government_2024.json', '58ba674d133333ce351dd9297e7a9f7bed822b93663ab7d09a19291f6c3f97ba');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'A system of government where power is shared between the central government and the component units is called _____.', '["Unitary system","Confederal system","Federal system","Monarchical system"]', 2, 'Federalism is a system where constitutional power is divided between a central authority and constituent political units like states or regions.', NULL, 'NECO_Government_2024.json', '33f2a844eacd17eb1a68963f8b50bedbc61a047aa3e65c0007e016f000342b6a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The process of depriving a person of their citizenship is known as _____.', '["Deportation","Denaturalization","Expatriation","Disenfranchisement"]', 1, 'Denaturalization is the legal act of stripping a person of citizenship, usually for those who acquired it through naturalization.', NULL, 'NECO_Government_2024.json', '072919d00f5cdda6ebcef4e270e5e4d9948e6dd0b1f4935ab2a87490df3b7e7b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The primary function of the legislature is to _____.', '["Execute laws","Interpret laws","Make laws","Adjudicate disputes"]', 2, 'The legislature is the organ of government responsible for debating, amending, and passing laws.', NULL, 'NECO_Government_2024.json', '1a034a5bb300e56c8acca0351abd4b0d2f71f0c3c393e7e466f90ec140ced776');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The concept of ''Rule of Law'' was popularized by _____.', '["A.V. Dicey","Baron de Montesquieu","Thomas Hobbes","Jean Bodin"]', 0, 'Albert Venn Dicey, a British jurist, popularized the three principles of the Rule of Law in his book ''Introduction to the Study of the Law of the Constitution''.', NULL, 'NECO_Government_2024.json', 'e68edf2ac850c326c6edc07df6808b14bf847f03bc49034527c657e4f0331f70');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Which pre-colonial Nigerian political system was described as acephalous?', '["Hausa/Fulani","Yoruba","Igbo","Benin"]', 2, '''Acephalous'' means headless. The Igbo traditional political system was decentralized and lacked a single central authority or king.', NULL, 'NECO_Government_2024.json', 'ede6d71c48508dd35c6ef07b4377ab9028c97bf251cfefc2407de216ba1dac8e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The highest court of appeal in Nigeria under the 1999 Constitution is the _____.', '["Federal High Court","Court of Appeal","Supreme Court","Customary Court of Appeal"]', 2, 'The Supreme Court of Nigeria is the final appellate court and the highest judicial body in the country.', NULL, 'NECO_Government_2024.json', '4e4d8f086d6ede9e8fb6e4d19c8088bd840fae4a27ef47b3ea4c1ffbb4a17931');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The ''Elective Principle'' was first introduced in Nigeria by the _____ Constitution.', '["Richards","Clifford","Macpherson","Lyttleton"]', 1, 'The 1922 Clifford Constitution introduced the elective principle, allowing for the first time the election of representatives into the Legislative Council.', NULL, 'NECO_Government_2024.json', '6bca1fc1a64d656ad844109259e4717e7576251b8fa44854db4bb0712f863732');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'A major feature of a unitary system of government is that _____.', '["Power is decentralized","Constitutional power is concentrated at the center","It has a rigid constitution","Component units are sovereign"]', 1, 'In a unitary system, the central government is supreme and any administrative divisions exercise only powers that the central government chooses to delegate.', NULL, 'NECO_Government_2024.json', '39d241c83b8145016f9d872bc1c532bd8b98e674ffba8e81060e1ffd176b7081');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The administrative headquarters of the United Nations is located in _____.', '["London","Geneva","Paris","New York"]', 3, 'The UN Secretariat and headquarters are located in New York City, USA.', NULL, 'NECO_Government_2024.json', '118138268996f81ca89bdaa3dd32cb880e270f6468ea9ad27032de3f08062225');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Delegated legislation is made by _____.', '["The Judiciary","The Legislature","Administrative bodies","Political parties"]', 2, 'Delegated (subordinate) legislation is law made by the executive or administrative agencies under authority granted by an Act of the legislature.', NULL, 'NECO_Government_2024.json', '92a8ef70262e35d95bd491202c899405993889f9c2f93b5c5c2c1d8e1fe1269b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'In the pre-colonial Hausa/Fulani system, the Emir''s adviser on Islamic law was the _____.', '["Waziri","Galadima","Madawaki","Sarkin Pada"]', 0, 'The Waziri acted as the Prime Minister and the chief legal and administrative adviser to the Emir.', NULL, 'NECO_Government_2024.json', '63dee7a5bae24ef94158da7280f08c526395a31591a2cc4690f37fc5ceacafcf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The 1976 Local Government Reforms in Nigeria aimed at _____.', '["Abolishing local governments","Making local government a third tier of government","Giving states more power over councils","Introducing a single-party system"]', 1, 'The 1976 reforms established local government as a distinct, uniform third tier of government with specific functions and funding.', NULL, 'NECO_Government_2024.json', '6c606814292a0c4144a4faff9e41b2ae3f7d11d95d21d6ee388705e07dbc105b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The principle of ''Separation of Powers'' was proposed to prevent _____.', '["Democracy","Dictatorship","Bureaucracy","Federalism"]', 1, 'Separation of powers ensures that no single organ of government (Executive, Legislature, Judiciary) possesses absolute power, thereby preventing tyranny.', NULL, 'NECO_Government_2024.json', 'e2525ee2b74d2a48654eba9123b24e87c6ed92e77295b23321c5b0b6e37d35b6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Which of the following is a permanent feature of the Civil Service?', '["Partisanship","Anonymity","Inconsistency","Political headship"]', 1, 'Anonymity means civil servants are neither praised nor blamed publicly for government policies; they work behind the scenes while their political heads take the credit/blame.', NULL, 'NECO_Government_2024.json', '251dcfefb1d9a6f64077ec6e3d999f508ec54b489882d5c02c2ea0e4e31ebf1b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The main objective of the Commonwealth of Nations is _____.', '["Military alliance","Economic integration","Promoting cooperation among former British colonies","Replacing the United Nations"]', 2, 'The Commonwealth is a voluntary association of independent states, mostly former British colonies, collaborating on social, economic, and political goals.', NULL, 'NECO_Government_2024.json', 'e19b257b35873cc72675cee65982cb74cdbf63673e31a9339602ae30e27be4a2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The first military coup in Nigeria occurred on _____.', '["January 15, 1966","July 29, 1966","July 29, 1975","December 31, 1983"]', 0, 'The first military coup, led by Major Chukwuma Kaduna Nzeogwu, took place on January 15, 1966, ending the First Republic.', NULL, 'NECO_Government_2024.json', '41c6be5605499993a59e60d6751962568271031e918e69ea9a7d0af976a29fa5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The 1963 Constitution of Nigeria replaced the _____.', '["Governor-General with a President","Prime Minister with a President","Senate with a House of Chiefs","Unitary system with a Federal one"]', 0, 'The 1963 Republican Constitution abolished the monarchy, replacing the Queen as Head of State with a ceremonial President.', NULL, 'NECO_Government_2024.json', '5ec451cf3ca371b641b17c21e599fab1fd8181f75438ae868516b0b30fbda9ed');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Pressure groups differ from political parties in that they _____.', '["Aims at winning elections","Nominate candidates for office","Seek to influence government policy","Control state power"]', 2, 'While political parties aim to win elections and control government, pressure groups only seek to influence government decisions in favor of their members.', NULL, 'NECO_Government_2024.json', '11033c8dd73e401e52106d42265f47e68959c9ab9387314a6834de2696b10376');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The term of office for the Secretary-General of the United Nations is _____ years.', '["4","5","6","10"]', 1, 'The UN Secretary-General is appointed for a 5-year term, which is renewable.', NULL, 'NECO_Government_2024.json', 'cf3aac4bba0393c771a8cbbd87ee37a2308ff83aafff51b803e1defc78cbbcd5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'In a parliamentary system of government, the Head of Government is the _____.', '["President","Monarch","Prime Minister","Chief Justice"]', 2, 'In a parliamentary system (Westminster model), the Head of Government is the Prime Minister, while the Head of State is usually a ceremonial President or Monarch.', NULL, 'NECO_Government_2024.json', 'cab87a5eb1ed840a943c550950179ef6cc0e23d11e57eff5c55552ce7ce19627');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The pre-colonial Oyo Empire utilized a system of _____ to limit the power of the Alaafin.', '["Direct rule","Checks and balances","Totalitarianism","Military decree"]', 1, 'The Oyo Mesi (Kingmakers) and the Ogboni cult acted as institutional checks on the power of the Alaafin.', NULL, 'NECO_Government_2024.json', '3c0fc8dd530e155af820949a3a35cdefce66fffc904ad7ad9874ec3deb755533');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Public opinion is important in a democracy because it _____.', '["Enables the government to suppress critics","Serves as a guide for government action","Replaces the need for elections","Is always uniform"]', 1, 'Public opinion reflects the collective views of the people, helping democratic governments understand and respond to the needs of the citizens.', NULL, 'NECO_Government_2024.json', '3cecee06cdef0a8320adf967cde751e2ed55019450250a545ddce803f87b005b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The Richards Constitution of 1946 was significant because it _____.', '["Introduced the ministerial system","Divided Nigeria into three administrative regions","Granted total independence","Abolished the indirect rule system"]', 1, 'The Richards Constitution formally divided Nigeria into the Northern, Western, and Eastern regions, laying the foundation for regionalism.', NULL, 'NECO_Government_2024.json', '08050c96efa8ffc2a7cf79f755723a469d9f8882e8f24fdb027c13879c7dcb15');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Universal Adult Suffrage refers to the _____.', '["Right of all adults to bear arms","Right of all adults to vote","Right of all adults to free education","Right of all adults to travel"]', 1, 'Suffrage is the right to vote. Universal adult suffrage means all qualified adults can vote regardless of property, gender, or social status.', NULL, 'NECO_Government_2024.json', '247025087f7767a11f96b942ca734c208d09abe900a92d150e7aff0f89868972');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The first political party in Nigeria was the _____.', '["NCNC","NNDP","NPC","AG"]', 1, 'The Nigerian National Democratic Party (NNDP), founded by Herbert Macaulay in 1923, was the first formal political party in Nigeria.', NULL, 'NECO_Government_2024.json', '144d2a015055576c1c6cc28499d4a3b38eab0b20a167af77ee62aa2ef963c1e0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The organ of the United Nations responsible for maintaining global peace and security is the _____.', '["General Assembly","Secretariat","Security Council","International Court of Justice"]', 2, 'The Security Council has the primary responsibility for the maintenance of international peace and security.', NULL, 'NECO_Government_2024.json', 'a0a6f5df6a2ddcad17e19cd87cb051f1b24e3034e661ea2b36ca5380342a1a1b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Which of the following is a feature of a rigid constitution?', '["It can be amended by a simple majority","It is usually unwritten","It requires a special and difficult amendment process","It is found in a unitary state"]', 2, 'A rigid constitution (like Nigeria''s or the USA''s) requires a complex legal procedure, such as a two-thirds majority in the legislature, to be amended.', NULL, 'NECO_Government_2024.json', 'cfb5d5732aada9eff987bb66e64cf39d1f39459ad1d3c58da478d3957136ca17');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The ''Power of the Purse'' belongs to the _____.', '["Executive","Judiciary","Legislature","Civil Service"]', 2, 'The legislature has the power of the purse, meaning it controls government spending and must approve the national budget.', NULL, 'NECO_Government_2024.json', 'c76aa957fed77f6e2c252ea08108472aca5415b793c271bef73e125916643c81');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'In the pre-colonial Hausa/Fulani system, the head of a district was the _____.', '["Hakimi","Alkili","Galadima","Dogari"]', 0, 'The Hakimi was the district head appointed by the Emir to manage sub-divisions of the emirate.', NULL, 'NECO_Government_2024.json', '648027ac673554bf2cac82621c4ca8f2f13c1aba6bdc0f7097c85c62e611c2d8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The Macpherson Constitution of 1951 was criticized for being _____.', '["Strictly unitary","Strictly federal","A ''compromise'' constitution","Military-inspired"]', 2, 'It was described as a compromise because it attempted to balance the demands for central authority and regional autonomy.', NULL, 'NECO_Government_2024.json', '35e1d64f3c3f4b1124b373f12f4e1919cca356bbbb76fb678d2c18e181a678ce');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The African Union (AU) was established in 2002 to replace the _____.', '["ECA","OAU","ECOWAS","SADC"]', 1, 'The Organization of African Unity (OAU) was disbanded and replaced by the African Union to better address integration and economic development.', NULL, 'NECO_Government_2024.json', '90ef7fcf596bfdfcb3bbb55598e77f204a130a50c0c94e92b824347f325df3ca');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The process by which an individual is integrated into the political system and acquires political values is _____.', '["Political socialization","Political participation","Political culture","Political apathy"]', 0, 'Political socialization is the lifelong process by which people form their political ideas and acquire political values.', NULL, 'NECO_Government_2024.json', '1f848d55ffa7b4649536552375b8a83de8b29384194e9e737ca8ca54333ccb30');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'A major advantage of a bicameral legislature is that it _____.', '["Is cheaper to run","Hastens the law-making process","Prevents the passage of hasty legislation","Concentrates power in one house"]', 2, 'Having two houses allows the second chamber to act as a check on the first, ensuring that bills are more thoroughly debated.', NULL, 'NECO_Government_2024.json', 'b9ca2bc6a9d231bea3ecdcd3900ac179b74267c70302fd2e3589879122cc1344');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The first indigenous Governor-General of Nigeria was _____.', '["Sir Abubakar Tafawa Balewa","Sir Ahmadu Bello","Dr. Nnamdi Azikiwe","Chief Obafemi Awolowo"]', 2, 'Dr. Nnamdi Azikiwe became the first indigenous Governor-General in 1960 and later the first President in 1963.', NULL, 'NECO_Government_2024.json', '217e774edb51b90e2ee7066593668ee62c6c1b439fdb43f615f71b8e15feb5d9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Gerrymandering refers to the _____.', '["Rigging of elections","Manipulation of electoral boundaries","Payment of voters","Censorship of the press"]', 1, 'Gerrymandering is the practice of redrawing the borders of an electoral district to favor one political party over another.', NULL, 'NECO_Government_2024.json', 'a0478f57fc448f01aaa406ea070881b4774e77eee0c84f0b64ba918cb2ebb57f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The 1979 Constitution of Nigeria introduced the _____ system of government.', '["Parliamentary","Presidential","Confederal","Unitary"]', 1, 'The 1979 Constitution marked Nigeria''s shift from the British parliamentary system to the American-style presidential system.', NULL, 'NECO_Government_2024.json', '2c3bdbc10c12ff49817a22d12b91abc6d20ff2c722ed96674aa128d53323dde8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The ''Oyo Mesi'' were _____ in the pre-colonial Oyo Empire.', '["Warriors","Palace guards","King makers","Tax collectors"]', 2, 'The Oyo Mesi was a council of seven hereditary chiefs responsible for selecting the Alaafin and advising him.', NULL, 'NECO_Government_2024.json', '0ccef48f9261f2e4da9df1af78cb477e2492d16be40dfa67f55709c698eb22ea');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'A system of government where the state is ruled by the wealthy is called _____.', '["Aristocracy","Theocracy","Plutocracy","Oligarchy"]', 2, 'Plutocracy is a society or system ruled and dominated by the small minority of its wealthiest citizens.', NULL, 'NECO_Government_2024.json', 'db0ae3dd7685ed5dc12f8e7085d5dda03813dd5aeeb9839a43e68926e7afe896');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The headquarters of the Economic Community of West African States (ECOWAS) is in _____.', '["Lagos","Accra","Abuja","Lome"]', 2, 'Abuja, Nigeria, serves as the administrative headquarters for the ECOWAS commission.', NULL, 'NECO_Government_2024.json', 'af400a1f0c3fd5f7a1864e953e1a52c14edd58a732552712ad86e518058b6b4b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The power of the courts to declare an act of the legislature unconstitutional is called _____.', '["Judicial independence","Judicial Review","Prerogative writ","Subpoena"]', 1, 'Judicial review allows the judiciary to examine the constitutionality of the actions of the other branches of government.', NULL, 'NECO_Government_2024.json', 'a9ba409b4ed376dd6782cf567acbfab222644cbc9907f18d0ddc32302b61f608');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Which of the following is a source of a constitution?', '["Manifestos","Judicial precedents","Party symbols","Electoral results"]', 1, 'Judicial precedents (past court rulings) are a significant source of constitutional law, alongside statutes and conventions.', NULL, 'NECO_Government_2024.json', '215b65838fa37de7bcea61e891ff83f3de8469cbd2855311d3d0ccdcc2a0623f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The main reason for the failure of the 1922 Clifford Constitution was that _____.', '["It introduced elections","It excluded Northern Nigeria from the Legislative Council","It was too expensive","It gave too much power to Nigerians"]', 1, 'The Clifford Constitution only legislated for the Southern Protectorate, while the North was ruled by proclamations of the Governor.', NULL, 'NECO_Government_2024.json', '157c34a3ba2c0b7e39f33ebf5499bb5529c53aa072e8ea3957301246d3a11590');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Non-alignment as a foreign policy principle means _____.', '["Not trading with other nations","Not taking sides in the Cold War","Isolationism","Supporting only African countries"]', 1, 'Non-alignment was a policy where developing nations chose not to be formally aligned with either the USA-led or USSR-led blocs during the Cold War.', NULL, 'NECO_Government_2024.json', 'cc026fd247a725e55c598937dde31b6885d8b2097756f21037ec71f08d2fd340');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The 1999 Constitution of Nigeria provides for _____ states.', '["12","19","30","36"]', 3, 'Nigeria currently has 36 states and a Federal Capital Territory (Abuja) as established in the 1999 Constitution.', NULL, 'NECO_Government_2024.json', '43070874ca9d5885d95e76a5751faab4c163f76420694473b3883b9bdc41251d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The administrative structure of a political party is usually headed by the _____.', '["Chairman","President","Secretary-General","Patron"]', 0, 'The National Chairman is typically the head of the party''s executive committee and its administrative leader.', NULL, 'NECO_Government_2024.json', '4b0dd5a6d124d5968be19e7a0b7545f979fda0fcbb1f32596041ec73282e8760');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Fascism originated in _____.', '["Germany","Italy","Russia","Spain"]', 1, 'Fascism was founded by Benito Mussolini in Italy after World War I.', NULL, 'NECO_Government_2024.json', '4a9427ff6c5600ed7858d5ea21b8b9d8aee1b311b4a85da8d592e1212a9385ef');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Which of the following is a function of the Civil Service Commission?', '["Making laws","Recruitment and promotion of civil servants","Interpreting the constitution","Campaigning for elections"]', 1, 'The Commission is an independent body that ensures merit-based recruitment, promotion, and discipline of government employees.', NULL, 'NECO_Government_2024.json', '68d6c4e1658103eed71ee6b55e9fb1f87ee8e15f61085021a5f765dad52dd90b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'In a confederal system of government, sovereignty resides in the _____.', '["Central government","Component units","Legislature","Judiciary"]', 1, 'In a confederation, independent states unite for common purposes but retain their individual sovereignty, making the center weak.', NULL, 'NECO_Government_2024.json', 'ac93c04500785e341ee41e11bd256da729b7e8d278afcbbaced429ad070199a8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The first Nigerian Prime Minister was _____.', '["Nnamdi Azikiwe","Abubakar Tafawa Balewa","Obafemi Awolowo","Ahmadu Bello"]', 1, 'Sir Abubakar Tafawa Balewa was the Prime Minister of Nigeria from 1957 until his assassination in 1966.', NULL, 'NECO_Government_2024.json', 'c3ffcc5736c630de4484b1912eb0ed4d4b72bd927edfb80ff48d5b737859d849');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Which organ of government is responsible for interpreting the law?', '["The Executive","The Legislature","The Judiciary","The Police"]', 2, 'The Judiciary interprets laws and adjudicates disputes according to the constitution and statutes.', NULL, 'NECO_Government_2024.json', '9026e07f702310ddadc8c7f188cddb1b142b50150940dfcf5143194fc15e798d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Rule by the best and most talented people is called _____.', '["Democracy","Aristocracy","Meritocracy","Oligarchy"]', 2, 'Meritocracy is a system where power and positions are assigned based on ability and achievement rather than wealth or class.', NULL, 'NECO_Government_2024.json', '8baed2bb7ad250197fa24594dc05f255a4ccbcbff49b3f0284c8eb6321fed15a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The ''Willink Commission'' of 1957 was set up to _____.', '["Draft the independence constitution","Investigate the fears of minorities","Abolish the regions","Conduct a census"]', 1, 'The commission was established to investigate the fears of minority groups in Nigeria and suggest safeguards for their rights.', NULL, 'NECO_Government_2024.json', '6cf7e81b9924480fb8812652ac85f02dd3c34d5f37b3b9b60e2874f829479198');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Which of the following defines a ''Nation''?', '["A geographical area","A group of people with a shared culture and history","A sovereign government","A collection of political parties"]', 1, 'A nation is a cultural and psychological entity; a group of people who feel they belong together based on shared history, language, or values.', NULL, 'NECO_Government_2024.json', '9e7855656be44e98e882749d8d1c67bcaae153e02e5f565731974847944fcc8d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The Lyttleton Constitution of 1954 made Nigeria a _____.', '["Unitary state","Confederation","Federation","Monarchy"]', 2, 'The Lyttleton Constitution formally established the federal principle by dividing powers between the center and the regions.', NULL, 'NECO_Government_2024.json', '68ba0eb2d196d587c69b613266a29b455a1451f5bcce78a2cdff77bf90874b93');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The term of office for a member of the Nigerian Senate is _____ years.', '["2","4","5","6"]', 1, 'Members of both the Senate and the House of Representatives in Nigeria serve 4-year terms.', NULL, 'NECO_Government_2024.json', '4047a9d4058a0cfda6aac13df5d6c1a3b08f3e54de8604bd40dd6859e31b399a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Socialism is an ideology that emphasizes _____.', '["Private ownership of means of production","State ownership and distribution of resources","Military rule","Individualism"]', 1, 'Socialism advocates that the means of production, distribution, and exchange should be owned or regulated by the community as a whole.', NULL, 'NECO_Government_2024.json', '6df9530f47658a3325a1f41c8cf4d2f8fa5461b4991d9453099a6bf2b4d75bd0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The first President of the Organization of African Unity (OAU) was _____.', '["Kwame Nkrumah","Haile Selassie","Julius Nyerere","Jomo Kenyatta"]', 1, 'Emperor Haile Selassie of Ethiopia served as the first chairperson of the OAU in 1963.', NULL, 'NECO_Government_2024.json', '7cee7000b74c65da3c50e4974015ecc5df395f4c1c3afde6cbaa706a2b49b68f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Which of the following is a limitation to the Rule of Law?', '["Independent Judiciary","State of Emergency","Public opinion","Free press"]', 1, 'During a state of emergency, the government may legally suspend certain laws and rights to maintain public order.', NULL, 'NECO_Government_2024.json', 'f7dec4ab391750f093010a2a319cfeb08173c2044dbe8d58004390d09ec1f0ea');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Public corporations are managed by _____.', '["Ministers","Board of Directors","Civil servants","Traditional rulers"]', 1, 'Public corporations (like NNPC) are typically governed by a Board of Directors appointed by the government to oversee operations.', NULL, 'NECO_Government_2024.json', '112e4417ee6958e6e39335649bc52355a28920a9631ecd203b85f814913d1c57');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Sovereignty belongs to the _____.', '["Legislature","Executive","Judiciary","State"]', 3, 'As a legal concept, sovereignty is a characteristic of the State itself, representing its supreme power.', NULL, 'NECO_Government_2024.json', 'f82bf005bf3d9e62db189e54be65f838afd742aafbe480a40e39414517cd47f6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The main objective of pressure groups is to _____.', '["Organize protests","Contest elections","Protect the interest of their members","Overthrow the government"]', 2, 'Pressure groups (like ASUU or NLC) exist primarily to advocate for and protect the specific interests of their members.', NULL, 'NECO_Government_2024.json', 'a35df107059af9c82da8bd5824571e99fa54d9b63a22f70be6fdfa2df564e6e6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Who was the Chairman of the 1976 Constitution Drafting Committee?', '["Dr. Nnamdi Azikiwe","Chief Rotimi Williams","Justice Udo Udoma","Chief Obafemi Awolowo"]', 1, 'Chief Rotimi Williams headed the ''49 Wise Men'' committee that drafted the 1979 Constitution.', NULL, 'NECO_Government_2024.json', '22652139afc603f13a28e3110d6ba1ac75e780ba4c8f269bbc2de82b54bb517f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Indirect Rule was a colonial policy introduced by _____.', '["Lord Milverton","Sir Hugh Clifford","Lord Lugard","Sir Arthur Richards"]', 2, 'Lord Frederick Lugard implemented the policy of Indirect Rule, using traditional institutions to govern colonized people.', NULL, 'NECO_Government_2024.json', '0e8fdf0566f821577ca030f32e9955c249c705704cb58d87c2393df67355abdd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The process of withdrawing a lawmaker from the legislature by their constituents is _____.', '["Impeachment","Recall","Resignation","Dissolution"]', 1, 'Recall is a democratic procedure that allows voters to remove an elected official from office before their term expires.', NULL, 'NECO_Government_2024.json', '9c31e4600936fa98b8b85a6d801761ca3b1e39fcb8adb3800a0e2aaa144d9a7a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'Which organization replaced the League of Nations?', '["OAU","AU","United Nations","Commonwealth"]', 2, 'The United Nations was established in 1945 to replace the League of Nations which had failed to prevent World War II.', NULL, 'NECO_Government_2024.json', '5cf4345b76a193c1a071336f806095f43964bab4806641a1d1f289fad8261861');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The ''Age Grade'' system was a significant feature of pre-colonial _____ politics.', '["Hausa","Igbo","Oyo","Kanem-Borno"]', 1, 'In decentralized Igbo societies, age grades performed various social, executive, and military duties.', NULL, 'NECO_Government_2024.json', 'f1c359efdfaa2fecf83eff8c567438df48781a87e18468a54cbf03a2cb1bfb1d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'A written constitution is often _____, making it hard to change.', '["Flexible","Rigid","Unwritten","Unitary"]', 1, 'Most written constitutions are rigid because they require specific, difficult procedures for amendment.', NULL, 'NECO_Government_2024.json', '3c57b1a5c5ec35aa6f06e0a89df09985606f994b0ea0d829a44d6fb6689e9981');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Government', 2024, NULL, 'The 1989 Constitution of Nigeria was intended for the _____.', '["First Republic","Second Republic","Third Republic","Fourth Republic"]', 2, 'The 1989 Constitution was designed for the transition to the Third Republic, which was aborted following the annulment of the June 12, 1993 election.', NULL, 'NECO_Government_2024.json', 'c0ad532e97e05081331b7c7672c98db754d53d4b90756698c54b5eb22fa6da99');
