INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wasulan Hausa guda nawa ne a tsaye (Standard vowels)?', '["Biyar","Bakwai","Goma","Sha biyu"]', 0, 'Standard Hausa has five basic vowels: a, e, i, o, u.', NULL, 'NECO_Hausa_2024.json', '9684b7144f134f2ccd96c5af24a46ee5b00fee4927ed49a9001460a3d287f1cf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanne ne cikin wadannan bakari (consonant) ne mai daka (glottalized)?', '["B''","K","S","T"]', 0, 'B'' is a glottalized (recursive) consonant in Hausa phonology, distinct from the plain ''B''.', NULL, 'NECO_Hausa_2024.json', '7404428481cb3618f5b0d10e4b172f5b2eff4783efd47393c4af3015afab0929');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Kalmar ''Guda'' a cikin lissafi tana nufin _____.', '["Kwaya daya","Goma","Duhu","Gudu"]', 0, '''Guda'' acts as a counter for individual units or items.', NULL, 'NECO_Hausa_2024.json', '84401884974b834f7ef531755ecfe8ac08dd181c2d95deeebb9545073b791b47');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanne ne ''wakilin suna'' (pronoun) na nuni na kusa?', '["Wannan","Wancan","Su","Mu"]', 0, '''Wannan'' (this) is used to point at items that are close to the speaker.', NULL, 'NECO_Hausa_2024.json', '1778e50d67fae665bfd1a16f8136b4554ca4abc9961836d7183b71656a7788ec');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Kammala karin maganar nan: ''Kowa ya bar gida, _____.''', '["gida ya bar shi","zai sha wuya","ya tafi yawo","ba ya dawowa"]', 0, 'This is a common proverb meaning if you abandon your origins, they will eventually abandon you.', NULL, 'NECO_Hausa_2024.json', '5e4effc7999adb69ce3d60507c938b591cbac884ff9a977eec3d9a9d9f76e403');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wacce sana''a ce ake kiran mai yin ta ''Makiri''?', '["Kira (Blacksmithing)","Noma","Saka","Fatuwa"]', 0, 'A ''Makiri'' is a blacksmith who works with iron and fire.', NULL, 'NECO_Hausa_2024.json', 'da434745c1127f1597d4d6ac341dbdc92cf34765d04cfbf4a16f83b2d3cc618b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Menene ma''anar kalmar ''Alhamis''?', '["Thursday","Tuesday","Wednesday","Friday"]', 0, 'In the Hausa calendar, Alhamis corresponds to Thursday.', NULL, 'NECO_Hausa_2024.json', 'aae927f30459774806e3d946502c102d1cad0f7df81c58d77461c09f34311b42');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanne ne ''fi''ili'' (verb) a cikin wannan jimlar: ''Yarinya tana gudu''?', '["Gudu","Yarinya","Tana","Babu"]', 0, '''Gudu'' (running) is the action word in the sentence.', NULL, 'NECO_Hausa_2024.json', 'd62e68ff8c2436049d2175e1eeb5e3229178ed0dbdee530b6a4d88e3f151f758');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'A wanne bangare na ''Adabin Baka'' ake samun Gizo da Kura?', '["Tatsuniya","Karin Magana","Kirari","Waka"]', 0, 'Gizo (spider) and Kura (hyena) are central characters in Hausa folktales (Tatsuniya).', NULL, 'NECO_Hausa_2024.json', '4034ea8a045979cbc511e07d4f92b6455f90eac03304255942b67d6d11e82644');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Littafin ''Magana Jari Ce'' wane ne ya rubuta shi?', '["Abubakar Imam","Bello Kagara","Sa''adu Zungur","Aminu Kano"]', 0, 'Dr. Abubakar Imam is the author of this famous Hausa literary classic.', NULL, 'NECO_Hausa_2024.json', '198486d5d5c903f9cb0abd0d81e0e5fc5e52c3e03f6add22c23211cf1a14a475');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Mene ne babban jigon wannan bayani?', '["Cutar Coronavirus","Tattalin arziki","Wanke hannu","Sanya takunkumi"]', 0, 'The entire passage focuses on the history and impact of the Coronavirus pandemic.', 'Kimanin shekaru biyu da suka gabata, duniya ta fuskanci wani babban kalubale na rashin lafiya wanda ya samo asali daga kwayar cutar Coronavirus. Wannan cuta ta yi sanadiyyar mutuwar miliyoyin mutane tare da durkusar da tattalin arzikin kasashe da dama. Gwamnatoci sun sanya dokar kulle domin rage yaduwar cutar. An kuma bukaci jama''a da su rika wanke hannu da sabulu da kuma sanya takunkumin fuska. A yanzu, an samar da rigakafi wanda ya taimaka wajen daidaita lamura.', 'NECO_Hausa_2024.json', 'eb6180f0a4d272341cbd63f301023d8452cb515548934a85722087d74321f109');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Menene babban tasirin cutar ga kasashen duniya?', '["Durkusar da tattalin arziki","Kara yawan abinci","Samar da aiki","Gyara hanyoyin mota"]', 0, 'The passage mentions it caused the economy to collapse (''durkusar da tattalin arziki'').', 'Kimanin shekaru biyu da suka gabata, duniya ta fuskanci wani babban kalubale na rashin lafiya wanda ya samo asali daga kwayar cutar Coronavirus. Wannan cuta ta yi sanadiyyar mutuwar miliyoyin mutane tare da durkusar da tattalin arzikin kasashe da dama. Gwamnatoci sun sanya dokar kulle domin rage yaduwar cutar. An kuma bukaci jama''a da su rika wanke hannu da sabulu da kuma sanya takunkumin fuska. A yanzu, an samar da rigakafi wanda ya taimaka wajen daidaita lamura.', 'NECO_Hausa_2024.json', 'dd878d87a01cd415b591b145bc3921f36de417ae4f6ea804a84b14b872d8c84a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wace hanya ce aka ambata domin kariya daga cutar?', '["Wanke hannu da sabulu","Yin gudu","Shan zuma","Barci da rana"]', 0, 'The passage lists handwashing (''wanke hannu da sabulu'') as a safety measure.', 'Kimanin shekaru biyu da suka gabata, duniya ta fuskanci wani babban kalubale na rashin lafiya wanda ya samo asali daga kwayar cutar Coronavirus. Wannan cuta ta yi sanadiyyar mutuwar miliyoyin mutane tare da durkusar da tattalin arzikin kasashe da dama. Gwamnatoci sun sanya dokar kulle domin rage yaduwar cutar. An kuma bukaci jama''a da su rika wanke hannu da sabulu da kuma sanya takunkumin fuska. A yanzu, an samar da rigakafi wanda ya taimaka wajen daidaita lamura.', 'NECO_Hausa_2024.json', '813ac6d957ed6b81a55cbddeca50c50462a2bae5689db12151941ac808814475');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Mene ne ya taimaka wajen daidaita lamura a yanzu?', '["Samar da rigakafi","Dokar kulle","Kuka","Zama a gida"]', 0, 'It states that vaccination (''rigakafi'') helped stabilize the situation.', 'Kimanin shekaru biyu da suka gabata, duniya ta fuskanci wani babban kalubale na rashin lafiya wanda ya samo asali daga kwayar cutar Coronavirus. Wannan cuta ta yi sanadiyyar mutuwar miliyoyin mutane tare da durkusar da tattalin arzikin kasashe da dama. Gwamnatoci sun sanya dokar kulle domin rage yaduwar cutar. An kuma bukaci jama''a da su rika wanke hannu da sabulu da kuma sanya takunkumin fuska. A yanzu, an samar da rigakafi wanda ya taimaka wajen daidaita lamura.', 'NECO_Hausa_2024.json', 'f834f19917552bc38c416234362d0064577c0d60bc8f0a6d5025193402dedb1e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Kalmar ''Dokar Kulle'' tana nufin _____.', '["Lockdown","Election","Market","Farming"]', 0, '''Dokar kulle'' is the Hausa translation for Lockdown/Stay-at-home order.', 'Kimanin shekaru biyu da suka gabata, duniya ta fuskanci wani babban kalubale na rashin lafiya wanda ya samo asali daga kwayar cutar Coronavirus. Wannan cuta ta yi sanadiyyar mutuwar miliyoyin mutane tare da durkusar da tattalin arzikin kasashe da dama. Gwamnatoci sun sanya dokar kulle domin rage yaduwar cutar. An kuma bukaci jama''a da su rika wanke hannu da sabulu da kuma sanya takunkumin fuska. A yanzu, an samar da rigakafi wanda ya taimaka wajen daidaita lamura.', 'NECO_Hausa_2024.json', 'c0e24a8d8b4ec256ae71c60853d86d3817341da1994a9ff28928f0ec8c52e855');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanne ne ''jinsin mace'' (feminine) na ''Yaro''?', '["Yarinya","Mata","Inna","Kulu"]', 0, 'The feminine equivalent of ''Yaro'' (boy) is ''Yarinya'' (girl).', NULL, 'NECO_Hausa_2024.json', 'aeef13d89e38fea844064966ff158387cd7a70ec1ca2b679a2a333fe9bff2bc3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Mene ne jam''i (plural) na kalmar ''Littafi''?', '["Littattafai","Littafan","Littafi-littafi","Litta"]', 0, '''Littattafai'' is the grammatically correct plural form of ''Littafi''.', NULL, 'NECO_Hausa_2024.json', '279794760c4c52f68a925c8b39df5496b0d527910fb0841822ab5c1d56730738');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wasalin ''i'' wasali ne mai .', '["Dunkule","Fadi","Tsaye","Dunkulalle"]', 1, 'In phonology, ''i'' is classified as ''Wasali mai fadi''.', NULL, 'NECO_Hausa_2024.json', '74fc89454bce43005120752ecfab13dd06409c4c16d85b652e18715cd5544e3e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'A cikin kalmar ''Makarantu'', guda nawa ne ''gaba'' (syllables)?', '["Hudu","Biyu","Uku","Biyar"]', 0, 'Ma-ka-ran-tu consists of four syllables.', NULL, 'NECO_Hausa_2024.json', 'd057d39b9b60b59ab9777b8ccd0efb74566a884cc0ee333c2d6dcfb6c50020fc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wacce dabba ce ake kira ''Sarkin dawa''?', '["Zaki","Giwa","Zomo","Biri"]', 0, '''Sarkin dawa'' means King of the Forest/Wild, referring to the Lion (Zaki).', NULL, 'NECO_Hausa_2024.json', '1c4a7e26177c464b721c2ef75f23a44c346556b8dd6db8775f8e2c21b817ebce');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Cika wannan: '' muna son karatun Hausa.''', '["Mu","Ku","Su","Ni"]', 0, 'The subject marker ''muna'' agrees with the first-person plural pronoun ''Mu'' (We).', NULL, 'NECO_Hausa_2024.json', '62e4351ab5c0478b0d3b05406b8617ae9cfe172eae544d90d39a786812c138eb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Mene ne kalmar ''Bayanau'' (Adverb)?', '["Kalmar da take siffanta fi''ili","Sunan mutum","Abin nuni","Kalmar tambaya"]', 0, 'An adverb (Bayanau) is a word that modifies or describes a verb (fi''ili).', NULL, 'NECO_Hausa_2024.json', '1ccac532b33746ca0e18dfc48040c6626bccd495f28863a03acedc1ad3aaa77f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanene ya kera wannan: ''Ina son riga _____.'' (White)?', '["fara","baki","ja","kore"]', 0, '''Fara'' is the feminine adjective for white, agreeing with the feminine noun ''riga''.', NULL, 'NECO_Hausa_2024.json', 'd266c00e703a3557e9083e91ffbf2b06bfcd0f84270839b5e3236ab6ad31f6a0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'A tsarin sarautar Hausawa, wanene yake biye da Sarki?', '["Waziri","Dogari","Talakawa","Sarkin Noma"]', 0, 'The Waziri is the Prime Minister or the king''s most senior advisor.', NULL, 'NECO_Hausa_2024.json', '28f6c6dc2c64890a566ff6eb7443f38dd247b5909897fe4432ad5b4cce51696b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wane asali ne Hausawa suke da shi na ''Banza Bakwai''?', '["Kasashen da Hausa ya bazu gare su","Kasashen yaki","Kasashen Larabawa","Kasashen Turawa"]', 0, 'Banza Bakwai refers to those states that adopted Hausa culture/language but were not of the original seven.', NULL, 'NECO_Hausa_2024.json', 'ed223c19b4c357dfa827f7bc055a27a84daefe554df60e9bf345816b30fdac57');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'A wanne lokaci ne ake yin ''Tuwon Suna''?', '["Lokacin radin suna","Lokacin biki","Lokacin mutuwa","Lokacin noma"]', 0, 'Tuwon Suna is a traditional meal prepared during the naming ceremony of a newborn.', NULL, 'NECO_Hausa_2024.json', '842519e2dc4fbf042489c064c153f2b74a6abf2ec6083a384d21f8bc0bbdb50e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Menene ''Ami'' (Tone) a Hausa?', '["Hawawa ko faduwar murya","Wasali","Bakari","Harafi"]', 0, 'Hausa is a tonal language; ''Ami'' represents the rising or falling pitch in speech.', NULL, 'NECO_Hausa_2024.json', '2b60b3e8b48e3f0883e880d6d0a893cacda957caefa3956d516e0a1913821b7d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanne littafi ne Sir Abubakar Tafawa Balewa ya rubuta?', '["Shaihu Umar","Ruwan Bagaja","Gandoki","Idon Matambayi"]', 0, 'Sir Abubakar Tafawa Balewa is the author of ''Shaihu Umar''.', NULL, 'NECO_Hausa_2024.json', '980fdbf36866913611a0c2ce871ec6e815ffdbc27434f8fec23aa29b0864749d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wace sana''a ce ''Fatuwa''?', '["Kasuwancin nesa","Kiwo","Farauta","Gini"]', 0, '''Fatuwa'' is the traditional practice of long-distance trading.', NULL, 'NECO_Hausa_2024.json', 'a7005e30d0873bd000a57fba1b4c49a83af78e6ed079d4be9b561215a238b78f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Mene ne ''Karin harshe'' (Dialect)?', '["Bambancin lafazi na yanki","Karin magana","Adabi","Turanci"]', 0, 'Dialect refers to variations in pronunciation or vocabulary based on geographic regions.', NULL, 'NECO_Hausa_2024.json', 'a7975097212318a2d30aa4c966677e5ab379f962127946662c130e2079542290');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanne ne sunan dabba mai wuya (neck) mai tsayi?', '["Rakumin dawa","Kura","Biri","Zaki"]', 0, '''Rakumin dawa'' is the Hausa name for a Giraffe.', NULL, 'NECO_Hausa_2024.json', '3af7a7a4c8c09d1f09923054859855122975ebc829c5275bd29f909390c0ef80');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Menene ''Jinsin miji'' (masculine) na ''Uwa''?', '["Uba","Yarinya","Kanwa","Mace"]', 0, 'The masculine equivalent of ''Uwa'' (mother) is ''Uba'' (father).', NULL, 'NECO_Hausa_2024.json', '74a44353070441b4a5cf1fa378e378f781920b3a614fac9603e9fd0c46e238b8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanne bangare ne na Sauti ake kira ''Diftong'' (Diphthong)?', '["Gamasauti","Bakari","Harafi","Sauti"]', 0, 'Diphthongs are known as ''Gamasauti'' in Hausa phonetics.', NULL, 'NECO_Hausa_2024.json', '66e97af25f4390b710bf3d36cca5d77a0692aac166e5bee1df85764bf6f9f98f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Mene ne ma''anar ''K''ungiyar asiri''?', '["Secret society","Political party","Youth club","Farmers union"]', 0, '''K''ungiyar asiri'' refers to secret cults or societies.', NULL, 'NECO_Hausa_2024.json', '34d5c0793d6fa2ae194ce5cfb9e74a373d95db4f13c489ffb98d78ddf1cbc2e7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wace rana ce ''Friday'' a Hausa?', '["Jumma''a","Alhamis","Asabar","Lahadi"]', 0, 'Friday is Jumma''a, considered a holy day in Islamic/Hausa culture.', NULL, 'NECO_Hausa_2024.json', 'ead92ac5369f53bc5608bb358c4c062325e64aea79d2170926df4bda5883dcdf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Cika wannan: ''Ina _____ zuwa makaranta.''', '["son","so","sun","sa"]', 0, '''Ina son'' (I want/like) followed by a verb phrase.', NULL, 'NECO_Hausa_2024.json', '2db11efa768279227eed408102b842bc3619fe5c36973a63e4274f28cd54543e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Menene ''Tatsuniya''?', '["Labarin gangan","Labarin gaskiya","Labari ne na nishadi da tarbiyya","Wakokin yabo"]', 2, 'Tatsuniya are fictional stories meant for entertainment and moral instruction.', NULL, 'NECO_Hausa_2024.json', 'e6dcdfe3a169e9d8a7252b67ee7eb12335873e8bef2675b264badcecf9373c11');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanne ne cikin wadannan wasali ne mai tsawo (long vowel)?', '["aa","a","e","o"]', 0, 'In standard orthography, double vowels indicate length.', NULL, 'NECO_Hausa_2024.json', '5500e0b45cd1a49abc553f9dfa4156d0e01da06ee4076174f9f6845181588fd0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanene ya kera wannan: ''Ina son mota _____.'' (Black)?', '["baka","fara","jaja","koriya"]', 0, '''Baka'' is the feminine adjective for black, agreeing with the feminine noun ''mota''.', NULL, 'NECO_Hausa_2024.json', 'e6f01c2880ab20fa27d1d8fd94bf8cdd620b898b29278ec579068252c65da0fc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Menene ''Gishirin jimla''?', '["Ga","Da","A","Ba"]', 1, '''Da'' is often called the salt of the sentence as it links many components.', NULL, 'NECO_Hausa_2024.json', '7e325431405e8607f2f0f479de2019c9941a90abf6e4e76b3b807ce5faaad3f7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'A ina ake yin sana''ar ''Kira''?', '["Makera","Gona","Rafi","Daji"]', 0, 'The blacksmith''s workshop is called ''Makera''.', NULL, 'NECO_Hausa_2024.json', '3fb8032a73661173873b31520e11c010ca20983b5b40680d4f4c870448507bf3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Menene ''Surutu''?', '["Yawan magana marar amfani","Barci","Karantawa","Kallo"]', 0, '''Surutu'' refers to excessive, often useless chatter.', NULL, 'NECO_Hausa_2024.json', '8a3ece09e44d8a07f0087c2b92540d413d932312039803b485d7b49eeeea92ff');
