INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Menene ''Wakilin suna na mallaka'' (possessive pronoun)?', '["Nawa","Kai","Su","Mu"]', 0, '''Nawa'' (mine) indicates possession.', NULL, 'NECO_Hausa_2024.json', 'eb78fcffa7c05cee15782654210fc3c79fa2b2f9a053ec168edc4884271fef87');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wace dabba ce ''Kura''?', '["Hyena","Lion","Wolf","Tiger"]', 0, '''Kura'' is the Hausa word for Hyena.', NULL, 'NECO_Hausa_2024.json', 'fa649180f1ea9c64d4b364f2a322e8517cdfdabe2932254d897fbf92bd1225fb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Mene ne ''Aure''?', '["Zama halas tsakanin mace da miji","Zama abokai","Zama yan uwa","Fada"]', 0, 'Aure (Marriage) is the lawful union between a man and a woman.', NULL, 'NECO_Hausa_2024.json', '9e0f7f03bb4835ae02dbf0503342197d20e490af3c296c46b991da7f62e9ef00');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Menene ''Sana''o''i''?', '["Hanyoyin neman abinci","Wakoki","Barci","Wasa"]', 0, '''Sana''o''i'' refers to occupations or trades used to earn a living.', NULL, 'NECO_Hausa_2024.json', 'fd3d88f85b8a77cfed0fcfc5deb717f2691f91b97f0f10c93769fd4d5b44bde9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanene yake jan ragamar fada (King''s palace)?', '["Sarkin Pada","Waziri","Galadima","Madawaki"]', 0, 'The ''Sarkin Pada'' is the head of the palace administration.', NULL, 'NECO_Hausa_2024.json', '9d0844b373cf9c1f5dfdeeeafb942befa5e4509623b0dc1b13278c29606969ed');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Menene ''Labarin zuciya''?', '["Karin magana mai nufin sirri","Ciwon zuciya","Farinciki","Barci"]', 0, '''Labarin zuciya'' is an idiom for one''s private thoughts or secrets.', NULL, 'NECO_Hausa_2024.json', '39707184d87466fdc96e7a13490639fa39132ddb4e64ca032afde9cb22acdec8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanne ne sunan azuzuwan Hausa (standard)?', '["Daidaitacciyar Hausa","Hausar gida","Hausar kasuwa","Hausar baka"]', 0, 'Standard Hausa used in writing and formal settings is called ''Daidaitacciyar Hausa''.', NULL, 'NECO_Hausa_2024.json', 'b8d033be93d6b184a170c99a045dcae7c73f6490bf51be1a1d69e970bc4c5488');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Menene ''Amshi'' a cikin waka?', '["Amsawar da ake yi wa mawaki","Sunan mawaki","Kayan kadi","Barci"]', 0, '''Amshi'' is the chorus or refrain responding to the lead singer.', NULL, 'NECO_Hausa_2024.json', 'd2882b7088e0d82d18c0b49bb63b02629c913cfe323e84c724fbfe08012f3e72');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Cika wannan: ''Ina _____ Hausa.''', '["jin","shan","cin","ganin"]', 0, 'To understand a language, the verb ''ji'' (hear/feel/understand) is used.', NULL, 'NECO_Hausa_2024.json', '7113b2e2162611fd30a5941ad4c89e1ca2fc58421ef9a25b8f6e906d42326ebe');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Kammala wannan: ''Hankali _____.''', '["maganin komai","shima dadi ne","kadararmu ce","baya nan"]', 0, 'The proverb ''Hankali maganin komai'' means intelligence is the cure for everything.', NULL, 'NECO_Hausa_2024.json', 'b8ef9f1120d5b934e1077894c084f039f628475cf631635ef8e005c67c25cff8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanne ne ''Bakarin hanci'' (Nasal consonant)?', '["M","B","D","G"]', 0, '''M'' and ''N'' are nasal consonants produced through the nose.', NULL, 'NECO_Hausa_2024.json', 'fa322d81546eacbe55c4eda86797a5d7fdc7988f3a59960b34c9b2bedbe80bd6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Mene ne ''Siffa'' (Adjective)?', '["Kalmar da take bayyana siffar suna","Sunan wuri","Kalmar aiki","Abin nuni"]', 0, 'Siffa (Adjective) describes or qualifies a noun (suna).', NULL, 'NECO_Hausa_2024.json', '017794747a99e488f009d9f929d0a01e8804fdda9e1403fedc98f63be4e6ee10');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wasali nawa ne a cikin kalmar ''Yarinya''?', '["Uku","Biyu","Hudu","Biyar"]', 0, 'Y-a-r-i-ny-a has three vowels: a, i, a.', NULL, 'NECO_Hausa_2024.json', '686e9d7d65208385d1db3f1f4727136634fc0c6b2fc5991d1530d01e2f57191e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wace rana ce ''Tuesday'' a Hausa?', '["Talata","Litinin","Laraba","Alhamis"]', 0, 'Tuesday is called ''Talata''.', NULL, 'NECO_Hausa_2024.json', '42177208335b9c8c104941021498d96af74783e4389aa4a1d73f334876d12163');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Menene ma''anar ''Dan-koli''?', '["Dan kasuwa mai yawo","Manomi","Sarki","Malam"]', 0, 'A ''Dan-koli'' is a petty trader who travels with goods.', NULL, 'NECO_Hausa_2024.json', '7605bcc26abca11d0967f05044ecde2c3bb3cc309eb6b7fe4c743bea0728ab81');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanne ne babban birnin jihar Kaduna?', '["Kaduna","Zaria","Kafanchan","Saminaka"]', 0, 'The capital city of Kaduna State is Kaduna.', NULL, 'NECO_Hausa_2024.json', 'd6519015aca3b599517932c646accbe3bfea44ebfe8aa57c933d6f3623757a0a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Cika karin maganar nan: ''Hannu daya, _____.''', '["ba ya daukar daki","baya wanke kansa","yana da yawa","baya aiki"]', 0, 'Meaning cooperation is needed for big tasks (''One hand cannot carry a roof'').', NULL, 'NECO_Hausa_2024.json', '5441b7d6aec976df3e0fc39df3d9d3ad1d001f4c9c29d24e3693eff615309a17');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Mene ne ''Kirari''?', '["Wakar yabo ta gajeren lokaci","Kuka","Barci","Noma"]', 0, 'Kirari is an epithet or praise-chant used to identify or exalt someone.', NULL, 'NECO_Hausa_2024.json', '6e41e5e1d3b2befe063b8195163603b2d87d06a383b43a39ce88c45668e27d6b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanene ya rubuta littafin ''Ruwan Bagaja''?', '["Abubakar Imam","Bello Kagara","Umaru Dembo","Gambo Sawaba"]', 0, 'Dr. Abubakar Imam is the author of ''Ruwan Bagaja''.', NULL, 'NECO_Hausa_2024.json', '72a282eb10bed5cc05ab6c873fe51b91d3373d62ae4bc98351c5338c2f9d5ff6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'A cikin tsarin lissafi, ''Dubu daya'' nawa ne?', '["1000","100","500","10"]', 0, '''Dubu daya'' represents one thousand.', NULL, 'NECO_Hausa_2024.json', '2fa68c56ed48bf6186d8269c6983dd0997c62ecb36c05504af86e54126fa4e0a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wacce dabba ce ''Zomo''?', '["Rabbit","Tiger","Monkey","Elephant"]', 0, '''Zomo'' is the Hausa word for Rabbit.', NULL, 'NECO_Hausa_2024.json', 'fdf9cf9aaab965268ac53a766039c3abb4b86a6b0b9566ec2a429bb16baad4a3');
