INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanne harafi ne ''H''?', '["Bakari marar sauti","Wasali","Ami","Gaba"]', 0, 'In phonology, ''H'' is a voiceless glottal fricative (bakari marar sauti).', NULL, 'NECO_Hausa_2024.json', 'b8895a5368ddde24261ca6ea0ca6fab427dbf09ad172089f2643caf66b0fa0db');
