INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanene ''Malam''?', '["Teacher/Scholar","Trader","Soldier","Driver"]', 0, '''Malam'' is used for an educated person or teacher.', NULL, 'NECO_Hausa_2024.json', '4f709afa9ce6a61084235121c043002366f9300047859420b6369db6b2c07caf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Me ya sa harshen Hausa ya bazu ko''ina?', '["Saboda kasuwanci","Saboda yaki","Saboda barci","Saboda ruwa"]', 0, 'The passage says the language spread because of trade (''saboda kasuwanci'').', 'Kasar Hausa tana da dadadden tarihi na al''adu da sana''o''i. Kafin zuwan Turawa, Hausawa sun kware a fannin noma da kira da fatauci. Harshen Hausa ya bazu ko''ina a yammacin Afirka saboda kasuwanci. A yau, an inganta harshen ta hanyar rubutu da amfani da shi a kafafen yada labarai na duniya irin su BBC da VOA da China Radio International.', 'NECO_Hausa_2024.json', '090e5f6356547623e3059d31077f7156a0ab6039190900d197800ddef1bae0b8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Wanne ne cikin kafafen yada labarai aka ambata?', '["BBC","CNN","NTA","Channels"]', 0, 'The passage explicitly mentions the BBC.', 'Kasar Hausa tana da dadadden tarihi na al''adu da sana''o''i. Kafin zuwan Turawa, Hausawa sun kware a fannin noma da kira da fatauci. Harshen Hausa ya bazu ko''ina a yammacin Afirka saboda kasuwanci. A yau, an inganta harshen ta hanyar rubutu da amfani da shi a kafafen yada labarai na duniya irin su BBC da VOA da China Radio International.', 'NECO_Hausa_2024.json', '09f16088720ba4ddb29bd31c0784c84a3fd7d2938bbcbf8f342d37b750c6889d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Sana''o''i nawa aka ambata a farkon passage din?', '["Uku","Biyu","Hudu","Biyar"]', 0, 'The passage mentions Noma (farming), Kira (blacksmithing), and Fatauci (trading) - three trades.', 'Kasar Hausa tana da dadadden tarihi na al''adu da sana''o''i. Kafin zuwan Turawa, Hausawa sun kware a fannin noma da kira da fatauci. Harshen Hausa ya bazu ko''ina a yammacin Afirka saboda kasuwanci. A yau, an inganta harshen ta hanyar rubutu da amfani da shi a kafafen yada labarai na duniya irin su BBC da VOA da China Radio International.', 'NECO_Hausa_2024.json', '1311bb780cca7757acd42acc1ad035ebe1062972b58b66595b44e402207b4ae5');
