INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Hausa', 2024, NULL, 'Me aka yi wa harshen a yau?', '["An inganta shi","An manta shi","An sayar da shi","An sace shi"]', 0, 'The passage states it has been improved (''an inganta shi'') through writing and media.', 'Kasar Hausa tana da dadadden tarihi na al''adu da sana''o''i. Kafin zuwan Turawa, Hausawa sun kware a fannin noma da kira da fatauci. Harshen Hausa ya bazu ko''ina a yammacin Afirka saboda kasuwanci. A yau, an inganta harshen ta hanyar rubutu da amfani da shi a kafafen yada labarai na duniya irin su BBC da VOA da China Radio International.', 'NECO_Hausa_2024.json', '35b019cd8bc4012ef9b16c5d4b38067db220073cb6f33011b0190343711c88ea');
