INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The Nok culture, discovered in Central Nigeria, is famous for its early mastery of _____.', '["bronze casting","iron smelting","weaving","gold mining"]', 1, 'Nok culture is recognized as the earliest iron-smelting civilization in sub-Saharan Africa, dating back to 1000 BC.', NULL, 'NECO_History_2024.json', 'bc904363a1038b3eb1e148f19829aff58627021aaaefd9efb915900f56cebe5f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'In the pre-colonial Oyo Empire, the council of seven kingmakers was known as the _____.', '["Ogboni","Oyomesi","Esho","Ilari"]', 1, 'The Oyomesi was a powerful aristocratic council that selected the Alaafin and acted as a check on his powers.', NULL, 'NECO_History_2024.json', 'f5ad72a995d3404d81bffcb02591d118a12a1f21f2ad356cb948621659fe4c4f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The legendary founder of the Hausa states according to oral tradition is _____.', '["Usman dan Fodio","Bayajidda","Mai Dunama","Oranmiyan"]', 1, 'The Bayajidda legend describes a hero from Baghdad who killed a snake in Daura and fathered the founders of the Hausa Bakwai.', NULL, 'NECO_History_2024.json', 'b0dff48cdbf9874ab24065b48dddaa3f9d0e728564e4cda30a9b3beb3a18d591');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The Benin Empire became world-famous for its artistic works made of _____.', '["Marble","Terra-cotta","Bronze and Brass","Wood"]', 2, 'The Benin Bronzes (actually made of brass and bronze) are world-renowned examples of sophisticated pre-colonial African art.', NULL, 'NECO_History_2024.json', 'ae9b00614eb3c4172b40799750ddc20f553a206a13b4b689e9e2b2481c56df12');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The primary commodity of the Trans-Saharan trade from the Sudanic region to North Africa was _____.', '["Salt","Gold","Pepper","Rubber"]', 1, 'Gold was the most sought-after commodity from West Africa, traded for Saharan salt and Mediterranean goods.', NULL, 'NECO_History_2024.json', '3b720115bf294a41259f30e5927a0a3e6f556b44af1006e48c3c52c44617ac04');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The leader of the 1804 Jihad in Hausaland was _____.', '["Shehu El-Kanemi","Usman dan Fodio","Nana Asma''u","Sultan Bello"]', 1, 'Usman dan Fodio, a Fulani scholar, led the reformist movement that established the Sokoto Caliphate.', NULL, 'NECO_History_2024.json', '870b3399d6ee8f0e9840113f1259341def30939b26eb1390513932a6d6c1cfcd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The pre-colonial Igbo political system was described as _____ because it lacked a central ruler.', '["Monarchical","Acephalous","Totalitarian","Theocratic"]', 1, '''Acephalous'' means ''headless''; the Igbo system was decentralized, based on village assemblies and age grades.', NULL, 'NECO_History_2024.json', 'c836c4bf4d64617517532dd5d115f6c5477b0bb8f48cb9cc4ff35888cf619beb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The British annexed Lagos in 1861 primarily to _____.', '["spread Christianity","suppress the slave trade and protect commerce","build a railway","fight the French"]', 1, 'Lagos was annexed to ensure the end of the trans-Atlantic slave trade and to secure British interests in the palm oil trade.', NULL, 'NECO_History_2024.json', 'e4bea98abf8ffa7fd8826ac43876ef24448d9137577506d300966b03e38b6ca8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The Berlin Conference of 1884-1885 was significant because it _____.', '["ended the slave trade","formally partitioned Africa among European powers","declared war on Ethiopia","freed South Africa"]', 1, 'The conference established the rules for the ''Scramble for Africa,'' leading to the formal colonization of the continent.', NULL, 'NECO_History_2024.json', '90e29e53e8c13925270b38edcf5274cce826e57a656cd6e27c2699605094887f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The Amalgamation of Northern and Southern Nigeria in 1914 was performed by _____.', '["Sir Hugh Clifford","Lord Frederick Lugard","Sir Arthur Richards","John Macpherson"]', 1, 'Lord Lugard merged the two protectorates into one country, mainly for administrative convenience and fiscal reasons.', NULL, 'NECO_History_2024.json', '3461158431f2f937d7a603806972c5449888eed510caeaa3cb5ff0344e45c750');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The 1929 Aba Women''s Riot was a protest against _____.', '["poor education","the arrest of King Jaja","direct taxation of women","colonial boundaries"]', 2, 'Igbo and Ibibio women revolted because they feared the colonial government intended to impose taxes on them.', NULL, 'NECO_History_2024.json', '4e51f8ba64e00ae5956141444629e06cfc9be6d97875831f1cf44876961ba70b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The first Nigerian political party, the NNDP, was founded in 1923 by _____.', '["Nnamdi Azikiwe","Obafemi Awolowo","Herbert Macaulay","Ahmadu Bello"]', 2, 'Herbert Macaulay, often called the father of Nigerian nationalism, founded the NNDP to contest elections in Lagos.', NULL, 'NECO_History_2024.json', 'be61e0002ec443d2b4f3ae1bc42ecb612f99a4adaa70464c49a5af04ca9f3323');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The Richards Constitution of 1946 was significant for introducing _____ into Nigeria.', '["Direct taxation","Federalism","Regionalism","Universal Suffrage"]', 2, 'The Richards Constitution divided Nigeria into three regions (North, West, and East), laying the path for regional politics.', NULL, 'NECO_History_2024.json', '5a4b077db3c1a9d227c1ca1e72530c9283db51e4fc731fe738a7acad9e68de08');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The Sardauna of Sokoto, Sir Ahmadu Bello, was the leader of the _____ party.', '["NCNC","AG","NPC","NEPU"]', 2, 'The Northern People''s Congress (NPC) was the dominant party in the Northern Region under Ahmadu Bello.', NULL, 'NECO_History_2024.json', '25af8a2db68f2314c0b3a59a68695e6319810488857b8a6abef3016e3a2b05d7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'Nigeria became a Republic in the year _____.', '["1960","1963","1966","1970"]', 1, 'In 1963, Nigeria broke the remaining link with the British monarchy and replaced the Queen with an indigenous President.', NULL, 'NECO_History_2024.json', '2842fd24f836036a1462baac0aec411e7bb14fcf8a678e89b2b63ec88889b79f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The conference described in the passage is the _____.', '["London Conference","Berlin Conference","Paris Peace Conference","Accra Conference"]', 1, 'The 1884-85 Berlin Conference, hosted by Bismarck, formalized the partitioning of Africa.', 'The conference was held in Germany. No African leader was invited. The map of Africa was spread on the table, and lines were drawn using rulers to create new boundaries, often cutting through ethnic groups and ancient kingdoms.', 'NECO_History_2024.json', 'd171d406f71aa2b19e0acd56d895918f2e0f9d7ed7c89f27e84aa9f8aee31213');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The result of this conference was the _____.', '["Decline of Europe","Scramble for Africa","Industrial Revolution","End of Imperialism"]', 1, 'The conference provided the legal framework for European powers to ''scramble'' for and effectively occupy African territories.', 'The conference was held in Germany. No African leader was invited. The map of Africa was spread on the table, and lines were drawn using rulers to create new boundaries, often cutting through ethnic groups and ancient kingdoms.', 'NECO_History_2024.json', '00b715ba4d650c88c19e29bf79fdd65ac784d18e8a30f1cc6fc1aebc7d076e34');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The first indigenous Governor-General and later the first President of Nigeria was _____.', '["Abubakar Tafawa Balewa","Obafemi Awolowo","Nnamdi Azikiwe","Yakubu Gowon"]', 2, 'Dr. Nnamdi Azikiwe served as Governor-General in 1960 and became President in 1963.', NULL, 'NECO_History_2024.json', '9bff080cd66cc4df09c8295150101d1215b4c0d501e497fb87b228da5c630e9e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The Indirect Rule system was most successful in the _____ part of Nigeria.', '["Eastern","Western","Northern","Delta"]', 2, 'Indirect Rule worked well in the North because of the pre-existing centralized emirate system of the Sokoto Caliphate.', NULL, 'NECO_History_2024.json', '05d0174b28530114606d6e05310486b5f2d23cd1849ea4a97c6b6a7daf2f4ef1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The Sagrenti War of 1874 was fought between the British and the _____.', '["Oyo Empire","Asante Kingdom","Sokoto Caliphate","Benin"]', 1, 'The Sagrenti War (Anglo-Asante War) resulted in the British capturing Kumasi in present-day Ghana.', NULL, 'NECO_History_2024.json', '9fa445efa6c652417bb636ea8dc9153de0f097d7317790e735a6e61ff17abfe2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The first military coup in Nigeria occurred on _____.', '["January 15, 1966","July 29, 1966","July 29, 1975","December 31, 1983"]', 0, 'The January 1966 coup, led by Major Nzeogwu and others, ended the First Republic.', NULL, 'NECO_History_2024.json', 'a2def04ff198c7d7de87600805396d69f3b1bb9729d6d2554716c51961da574a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The Nigerian Civil War (1967-1970) began with the secession of the _____ Region.', '["Northern","Western","Eastern","Mid-Western"]', 2, 'The Eastern Region, led by Lt. Col. Odumegwu Ojukwu, declared itself the Republic of Biafra.', NULL, 'NECO_History_2024.json', 'fb4bffe1d3b108f9ea360ceeddd5166f7f3c7c6c2aa060f63b358b81ee230091');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The policy of ''No Victor, No Vanquished'' was announced at the end of the Civil War by _____.', '["Murtala Muhammed","Yakubu Gowon","Olusegun Obasanjo","Shehu Shagari"]', 1, 'General Gowon used this policy to promote national reconciliation and reintegration after the war.', NULL, 'NECO_History_2024.json', 'd90cfd541201b772feadd7c0c4c513f94ba97b2760b9c6207b0466b669e0498b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The Economic Community of West African States (ECOWAS) was formed in 1975 under the leadership of Nigeria and _____.', '["Ghana","Togo","Senegal","Ivory Coast"]', 1, 'Nigeria (Gowon) and Togo (Eyadema) were the primary architects of ECOWAS.', NULL, 'NECO_History_2024.json', '468b495b40aafa2eab271e83030cddec7ded996ef4c4681e49a940d80b97284e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'Which of the following pre-colonial empires was famous for its ''Female Warriors'' or Amazons?', '["Oyo","Benin","Dahomey","Kanem-Borno"]', 2, 'The Kingdom of Dahomey maintained an elite all-female military unit known as the Mino (Amazons).', NULL, 'NECO_History_2024.json', 'a6ca8c4292ae6a076e3d90ab48dbd27b5c7bd42d8ecec9dbdb79703af44b82ab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The Clifford Constitution of 1922 was notable for introducing the _____ in Nigeria.', '["Federal system","Elective principle","Unicameralism","Judicial review"]', 1, 'It allowed for the first time the election of four representatives to the Legislative Council.', NULL, 'NECO_History_2024.json', '7a955448a092ea15878ef07ee6d54fa3a8cbc4942c39c468b1c55f0b60a680e4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ancient city-state of Kano became a major commercial hub primarily due to the _____ trade.', '["Maritime","Trans-Saharan","Spice","Silk"]', 1, 'Kano was the southern terminal for many Saharan trade routes, famous for its leather and textile industries.', NULL, 'NECO_History_2024.json', '78a6690eae6f8f7dc22ee48eca1808dc670b71481aea044e8db9ab94fd5ef34c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'King Jaja of Opobo was exiled by the British because he _____.', '["refused to pay taxes","interfered with British palm oil trade in the hinterland","murdered a British consul","was a slave trader"]', 1, 'Jaja insisted on his right to act as a middleman and block British merchants from trading directly with the interior.', NULL, 'NECO_History_2024.json', 'a660fb9e4535093a903fba253349d175637c518f1a92f7b8d9444bffb7be994a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The 1851 bombardment of Lagos was carried out to remove Oba _____.', '["Akintoye","Kosoko","Dosunmu","Ewuare"]', 1, 'Oba Kosoko was ousted by the British because he supported the slave trade; he was replaced by Akintoye.', NULL, 'NECO_History_2024.json', '6b631c80ad93771156cf27576356c5a68154c2b56687739db0bc7454b52084ef');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The legendary priest who helped Osei Tutu found the Asante Empire was _____.', '["Okomfo Anokye","Mensah Sarbah","Yaa Asantewaa","Prempeh"]', 0, 'Okomfo Anokye is credited with summoning the Golden Stool from heaven as a symbol of unity for the Asante clans.', NULL, 'NECO_History_2024.json', '1212c04c106e793794a93eef19b746a13c1ffe18f1e7367919eb1e12a6917c76');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The first capital of colonial Nigeria was _____.', '["Lagos","Calabar","Lokoja","Zungeru"]', 1, 'Calabar served as the headquarters of the Oil Rivers Protectorate and the early Southern Nigeria Protectorate.', NULL, 'NECO_History_2024.json', '34cd395f2b6ddd47d673682058601b19666278b6c0cd41ec601f9e6da97e304b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The Lyttleton Constitution of 1954 is significant because it formally established _____.', '["Unitary government","Independence","Federalism","Diarchy"]', 2, 'It shared powers between the center and the regions and provided for regional autonomy.', NULL, 'NECO_History_2024.json', '2978d34644d29a217c9527939fd4284d8ca68b545982d075939698aa17709f61');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ''Warrant Chief'' system failed in Southeastern Nigeria because _____.', '["the chiefs were too poor","it lacked traditional legitimacy in an acephalous society","the British didn''t pay them","the people were Christians"]', 1, 'The Igbo had no kings; the British creation of Warrant Chiefs was seen as artificial and oppressive.', NULL, 'NECO_History_2024.json', '1a3e52e42caa71b37be753a40eb56045ccc6f40e3ac21fbcb6480495e40ee1a4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The 19th-century Jihad of Usman dan Fodio was primarily a _____ movement.', '["military","social and religious reform","tribal","commercial"]', 1, 'The Jihad aimed to cleanse Islamic practice and address the social injustices of the Hausa kings.', NULL, 'NECO_History_2024.json', 'b0301576282eedc4bd1037df62b925d28504cbd0fce4c1130d1a041aad1fc7d1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The principal architect of the Nigerian Action Group (AG) party was _____.', '["Nnamdi Azikiwe","Ahmadu Bello","Obafemi Awolowo","Samuel Akintola"]', 2, 'Chief Obafemi Awolowo founded the AG as a regional party for the Western Region.', NULL, 'NECO_History_2024.json', '9c0d55058e74162033b4469968c5a4e694ca0716689b95625a9f4f170617d589');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ''Willink Commission'' of 1957 was set up to _____.', '["investigate corruption","study the fears of minority groups","draft the independence date","split the North"]', 1, 'The commission concluded that while minorities had genuine fears of majority domination, new states should not be created.', NULL, 'NECO_History_2024.json', '66a07dc94965909cd527e591692f7a4249f12269737052460d4bb6dcab33d4e7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'Which of the following was a major consequence of the abolition of the Slave Trade?', '["End of all wars in Africa","Rise of ''Legitimate Commerce'' like palm oil","The industrial revolution","The discovery of gold"]', 1, 'The end of human trafficking led to the export of raw materials required by European industries.', NULL, 'NECO_History_2024.json', '517641228c4577236abb289782358b834b36980b93fe8955c2ccc4729dafd4d9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ''Satiru Rebellion'' of 1906 was a challenge to British rule in _____.', '["Sokoto","Benin","Oyo","Enugu"]', 0, 'The Satiru uprising near Sokoto was a Mahdist movement against British occupation and their local allies.', NULL, 'NECO_History_2024.json', '4bde5e241f30da2a7b87635e9fccbb3b3e6a168013f6ff3735ac94ec3cda218b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ''Nationalism'' in Nigeria after World War II was intensified by _____.', '["The fall of the Berlin Wall","The return of educated veterans and global anti-colonial sentiment","The discovery of oil","The Cold War"]', 1, 'Soldiers returning from the war and the Atlantic Charter''s promise of self-determination inspired the push for freedom.', NULL, 'NECO_History_2024.json', '36fb3343bce17690578dc8ca7afb5cb31dcd64904b6e12e1658757c69c6695e0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The 1962/63 census crisis was one of the factors that led to the collapse of the _____.', '["First Republic","Second Republic","Third Republic","Military Rule"]', 0, 'Disputes over population figures (used for revenue and seats) weakened the coalition between the NPC and NCNC.', NULL, 'NECO_History_2024.json', 'b91bc54d007835000235f4c9d15d6c1e98272a6fb71a08ed88fc25140e0fadd4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The first University College in Nigeria was established in 1948 at _____.', '["Nsukka","Ibadan","Lagos","Zaria"]', 1, 'The University College, Ibadan (initially affiliated with London) was the premier higher education institution in Nigeria.', NULL, 'NECO_History_2024.json', '6aa0122c03561a41dd1ab643dd6e45386bd66eb7ca8b35a76e32f5c9b32e4a3f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'Which Nigerian leader was assassinated in the February 13, 1976, abortive coup?', '["Aguiyi Ironsi","Murtala Muhammed","Sani Abacha","MKO Abiola"]', 1, 'General Murtala Muhammed was killed in an ambush led by Lt. Col. Bukar Suka Dimka.', NULL, 'NECO_History_2024.json', '9afbb226a2dc3ff935370c1e051ccbd0d5e84fe9b2b250a274e52d2400ccfd3e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The policy of ''Assimilation'' was used in Africa by _____.', '["Britain","France","Portugal","Germany"]', 1, 'France aimed to turn Africans into ''Black Frenchmen'' through their culture and education system.', NULL, 'NECO_History_2024.json', '2bd8462bb568212939e71957de745e345af37bc14bfb6846d022f8287a659f25');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The first African country to gain independence from colonial rule in sub-Saharan Africa was _____.', '["Nigeria","Kenya","Ghana","Sudan"]', 2, 'Under Kwame Nkrumah, Ghana became independent from Britain in 1957.', NULL, 'NECO_History_2024.json', 'b26844b4de62443b6cd7b027240b8435bc69fd13d994f1d92d6ff488d8ff017b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The primary aim of the ''Apartheid'' system in South Africa was _____.', '["Economic progress","Racial segregation and white minority rule","Spread of religion","Ending tribalism"]', 1, 'Apartheid was a legal system of discrimination maintained by the National Party until 1994.', NULL, 'NECO_History_2024.json', '6fb28007e1cb8cc0d452f51961a8cf2832bce97f3895ee275bc95fe826884ca6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The headquarters of the African Union (AU) is located in _____.', '["Lagos","Cairo","Addis Ababa","Nairobi"]', 2, 'Ethiopia''s capital, Addis Ababa, has been the seat of the OAU (and later the AU) since 1963.', NULL, 'NECO_History_2024.json', 'b50163cf965c6b97bfab5b7fd30b65e026f627374b151e1f9f333c78913f5bd9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ''Second Republic'' (1979-1983) was led by President _____.', '["Nnamdi Azikiwe","Olusegun Obasanjo","Shehu Shagari","Ibrahim Babangida"]', 2, 'Alhaji Shehu Shagari was the first executive President of Nigeria under the NPN.', NULL, 'NECO_History_2024.json', '04e342556ac50f328f2a2151cc3bf039318a282522bce4dad53fa420bf3e229c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ''Manilla'' was a form of _____ used in pre-colonial trade.', '["clothing","currency","weapon","ship"]', 1, 'Manillas were C-shaped metal bracelets (usually brass/copper) used as money in West Africa.', NULL, 'NECO_History_2024.json', 'aea8434658c51e3ed32caa2b7a00441c8b059d9094d58c7fe786d429f0a5850e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ''Aro'' people dominated the trade in Eastern Nigeria through the influence of the _____ oracle.', '["Agbala","Ibini Ukpabi (Long Juju)","Amadioha","Idemili"]', 1, 'The Long Juju oracle at Arochukwu gave the Aro the judicial and spiritual authority to control trade routes.', NULL, 'NECO_History_2024.json', 'a555b6599cec3a1c446e42235e4db635b086bb82cb91189a1db86f353bd8773b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The trans-Atlantic slave trade is also known as the _____ trade.', '["Circular","Triangular","Bilateral","Linear"]', 1, 'It involved a three-legged journey between Europe (manufactured goods), Africa (slaves), and the Americas (raw materials).', NULL, 'NECO_History_2024.json', 'c32db77d2276987040e4cb38a077fb0be8bc5c4c418702e7b2b31434aad05739');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The 1914 Amalgamation was primarily funded by revenue from _____.', '["the North","the South","Britain","Germany"]', 1, 'The Southern Protectorate was financially self-sufficient, while the North had a deficit; amalgamation allowed the use of Southern funds for Northern administration.', NULL, 'NECO_History_2024.json', 'ea946fbeb3713095d84593cc5c5ce056ca236233322938e549a15f2fd74e8545');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'Which empire was destroyed by the British Punitive Expedition of 1897?', '["Sokoto","Benin","Oyo","Kanem-Borno"]', 1, 'The expedition led to the capture of Oba Ovonramwen and the looting of the Benin bronzes.', NULL, 'NECO_History_2024.json', 'f3bcac1267a37655d3bbf9805e54dd2bef6ebfe79f0d148fb1ba9241ad580a56');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The first Nigerian Prime Minister was _____.', '["Nnamdi Azikiwe","Ahmadu Bello","Abubakar Tafawa Balewa","Obafemi Awolowo"]', 2, 'Balewa led the federal government from 1957 until his death in 1966.', NULL, 'NECO_History_2024.json', 'b03060e86a76d743648697e32215af204c47190760b52b1baeea25afcfad9687');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The Nigerian leader who introduced the ''Indigenization Decree'' of 1972 was _____.', '["Murtala Muhammed","Yakubu Gowon","Olusegun Obasanjo","Sani Abacha"]', 1, 'The decree aimed to give Nigerians greater control over the economy by restricting foreign ownership in certain sectors.', NULL, 'NECO_History_2024.json', '709ec90e169003328cfdde7df5b777811fb92a99d7b8f01e5ec6d2fcc05817cb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The first capital of the Nigeria Colony after the 1914 amalgamation was _____.', '["Lokoja","Lagos","Calabar","Kaduna"]', 1, 'Lagos remained the capital of amalgamated Nigeria until the move to Abuja in 1991.', NULL, 'NECO_History_2024.json', '0c563f0f0eb8abd495583fe6937eb44bb9eb116066b73684031c09738842a9aa');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ''Oyo Mesi'' were _____ in the pre-colonial Oyo Empire.', '["tax collectors","palace guards","king makers","religious leaders"]', 2, 'They were the hereditary council of seven chiefs responsible for choosing the next Alafin.', NULL, 'NECO_History_2024.json', '1092e71e6ad5874e9b7c0724db41b42cdfd78cf64f740e3added1668f5f62d97');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The legendary founder of Ile-Ife and the Yoruba race is _____.', '["Oranmiyan","Oduduwa","Sango","Ogun"]', 1, 'Oduduwa is regarded in Yoruba mythology as the progenitor of the Yoruba people and their kings.', NULL, 'NECO_History_2024.json', '4794908a6692c30c50640b1bae153704350d8382b3d2dc554d6d7b0d5b28f669');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ancient Kanem-Borno Empire was located in the basin of Lake _____.', '["Victoria","Tanganyika","Chad","Nyasa"]', 2, 'Lake Chad was the strategic center for the Kanem-Borno Empire''s power and trade.', NULL, 'NECO_History_2024.json', 'b26a232bdf777340db0a6d0087ca3c52e2df15a11f11ce0ecda7b1bba47b829b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ''Macpherson Constitution'' of 1951 was criticized for being a _____ constitution.', '["Unitary","Compromise","Federal","Military"]', 1, 'It was called a compromise because it attempted to balance the centralist and regionalist demands of Nigerian politicians.', NULL, 'NECO_History_2024.json', 'c1a9a8d9cd126cf8c604edbde93f1eaec38211a84142d8a5bbd3eedc99716fea');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The 1922 Clifford Constitution applied only to _____.', '["The North","The South","Lagos and Calabar","Nigeria as a whole"]', 1, 'The North was excluded from the Legislative Council under Clifford; the Governor ruled the North by proclamation.', NULL, 'NECO_History_2024.json', '818a9ce9d31963b35a0391849cc700bd4774aeefb8ed9a4df19c046eb85366d1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ''Zikist Movement'' was an auxiliary of the _____ party.', '["NPC","AG","NCNC","NEPU"]', 2, 'The Zikist Movement was a radical youth wing supporting the ideals of Nnamdi Azikiwe.', NULL, 'NECO_History_2024.json', '902bd18ae91c9671caefb40e2f72c8e53d5a2c209fccb547becdb1aaa707179b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ''National Youth Service Corps'' (NYSC) was established in _____.', '["1960","1970","1973","1979"]', 2, 'It was created to foster national unity and reconciliation after the Civil War.', NULL, 'NECO_History_2024.json', '8c5e0b02cfc80bf6dd3ea9702fe5a1dc4696e8ca77af76a2dbc2eb3ad70cb145');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ''Apartheid'' system in South Africa was officially dismantled in _____.', '["1960","1976","1990-1994","2000"]', 2, 'Negotiations between the ANC and the National Party led to the first multi-racial elections in 1994.', NULL, 'NECO_History_2024.json', 'c08ce95363d878b1fb7b0128084acea3395ef23d1edc192abdb3d6cf9fa7f2c6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The primary cause of the 19th-century ''Yoruba Civil Wars'' was the _____.', '["fall of the Oyo Empire","arrival of the British","spread of Islam","shortage of land"]', 0, 'The collapse of the central Oyo authority led to power struggles between city-states like Ibadan, Ijaye, and Abeokuta.', NULL, 'NECO_History_2024.json', '5d22b3a2e52fa9320eba427c4846755a89aa05903e5cf8c76a74319f328ec762');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'Who was the ''Black Prophet'' of the Niger Delta who resisted the Royal Niger Company?', '["King Jaja","Nana of Itsekiri","King Koko of Nembe","Oba Overami"]', 2, 'King Koko led the 1895 attack on Akassa to protest the trade monopoly of the Royal Niger Company.', NULL, 'NECO_History_2024.json', 'e71bd3221b2c48d94c3697670d5c546ccdcadbff937d2308530b82bbb3602576');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ''Sefuwa Dynasty'' is associated with the history of _____.', '["Sokoto","Benin","Kanem-Borno","Oyo"]', 2, 'The Sayfawa (Sefuwa) dynasty ruled Kanem-Borno for over a thousand years, one of the longest in history.', NULL, 'NECO_History_2024.json', '193374a8708e6e70b05d6355e9a6e8c88e07291a9ecc15a1f19e8be1392cc688');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The first Nigerian to be appointed a Bishop of the Anglican Church was _____.', '["Samuel Ajayi Crowther","Henry Townsend","Hope Waddell","Thomas Bowen"]', 0, 'Crowther, a former slave, was consecrated as Bishop in 1864.', NULL, 'NECO_History_2024.json', '31680bd543abd4fedfeb475cbc657d66d2102cdb47981a0b20433774f2f8ef6f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ''Bula Matari'' (Breaker of Rocks) was the nickname given to _____.', '["Frederick Lugard","Henry Morton Stanley","Cecil Rhodes","King Leopold"]', 1, 'Stanley earned this name in the Congo for his forceful methods and road-building.', NULL, 'NECO_History_2024.json', '619eb3dfbefb96582625e1b1e234a50d88d0825a88d50e177a71623bf72b9915');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The ''Great Trek'' in South Africa was undertaken by the _____.', '["Zulu","Xhosa","Boers (Afrikaners)","British"]', 2, 'The Boers migrated inland in the 1830s to escape British colonial administration in the Cape.', NULL, 'NECO_History_2024.json', 'b868e5f9649f6153f6d559f3e172101d4df29a7164c8fa36912484c93d8872dd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'The 1953 ''Kano Riot'' was triggered by the visit of _____ to the North.', '["Nnamdi Azikiwe","Obafemi Awolowo","Samuel Akintola","Anthony Enahoro"]', 2, 'Action Group leaders visited Kano to campaign for ''Self-government in 1956,'' leading to clashes with the NPC supporters.', NULL, 'NECO_History_2024.json', '088427429417aa0b5e76415fa81457efd824366049e39a70ec9daf82aebeef8f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2024, NULL, 'Nigeria''s return to civil rule on May 29, 1999, ended the military regime of _____.', '["Ibrahim Babangida","Sani Abacha","Abdulsalami Abubakar","Murtala Muhammed"]', 2, 'General Abubakar oversaw the transition to the Fourth Republic after Abacha''s death.', NULL, 'NECO_History_2024.json', '2c0aecaabba0c6cfcbdd46e6907add3a61562b6f9678a7783b3a247593191249');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The Nok culture is unique in West African history because it represents the earliest known evidence of _____.', '["terracotta and iron smelting","written language","stone architecture","gold mining"]', 0, 'Dating back to 1000 BC, the Nok culture is the oldest known civilization in Nigeria to produce terracotta sculptures and utilize iron-smelting technology.', NULL, 'NECO_History_2025.json', '1fb942675043d00b4f8f887fcc16ca816054da569ec5ef28e021864c145b3d7c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'In the pre-colonial Oyo Empire, the Bashorun was the leader of the _____.', '["Ogboni","Oyomesi","Esho","Ilari"]', 1, 'The Oyomesi was a council of seven kingmakers led by the Bashorun, who acted as a powerful check on the Alaafin''s authority.', NULL, 'NECO_History_2025.json', '17cae9b9d7f21dcd225ed4dbc3727daad14261d7281effd3927dddb8a2d9a6f1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The legend of Bayajidda is traditionally used to explain the origin of the _____.', '["Yoruba people","Igbo people","Hausa states","Kanuri people"]', 2, 'The Bayajidda legend describes a hero from Baghdad who arrived in Daura, killed a sacred snake, and founded the Hausa Bakwai (seven original states).', NULL, 'NECO_History_2025.json', 'd20b9285c67926712e3bb5a070ac2e48e86cd1538171cd994d03dc5460ea6c71');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'Which of the following pre-colonial systems was described as ''headless'' or decentralized?', '["Oyo","Benin","Igbo","Sokoto"]', 2, 'The Igbo political system was ''acephalous'' (headless), meaning power was decentralized and distributed among village assemblies and age grades.', NULL, 'NECO_History_2025.json', '54f16b1d1320c3241f305db9680908d1845c493aac7e71ede14f73022f9795ab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The Kanem-Borno Empire achieved its highest level of military and administrative efficiency under _____.', '["Idris Alooma","Mai Dunama","El-Kanemi","Sayf ibn Dhi Yazan"]', 0, 'Mai Idris Alooma introduced firearms and Turkish musketeers, and established Islam as the state religion, marking the empire''s golden age.', NULL, 'NECO_History_2025.json', '4e1d1231c6fdae791cc43dbc73c1e541bbc09fe180e8592d8902b3f73071ea97');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''Long Juju'' of Arochukwu facilitated the dominance of the _____ in the slave trade.', '["British","Portuguese","Aro","Fante"]', 2, 'The Aro people leveraged the judicial and spiritual authority of the Ibini Ukpabi (Long Juju) oracle to control trade routes and supply slaves to the coast.', NULL, 'NECO_History_2025.json', '535fefcef6cac39f71cf76d60f212bf0bcc04fdef41dffbd383d35872fe173b9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'Which commodity was most significant in the Trans-Saharan trade from West Africa to the Mediterranean?', '["Salt","Gold","Petroleum","Silk"]', 1, 'West African gold was the primary attraction for North African and European traders across the Sahara.', NULL, 'NECO_History_2025.json', 'b4f318ccf10d2c147eb3f48242cf673587729ee63e2d40c399ea5b12c37bb29f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The 1804 Jihad led by Usman dan Fodio began in which Hausa state?', '["Kano","Katsina","Gobir","Zaria"]', 2, 'The conflict began in Gobir after tensions between the reformist Fulani scholar Usman dan Fodio and the local king, Yunfa.', NULL, 'NECO_History_2025.json', '09ae6d86ecd98c5aa9ab33da9aa876336110343e8be8b3787334c96a8eb27d31');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The primary motive for the British annexation of Lagos in 1861 was to _____.', '["promote Christianity","abolish the slave trade and protect palm oil trade","build a new airport","educate the citizens"]', 1, 'Britain annexed Lagos to effectively enforce the anti-slave trade treaties and secure legitimate commerce, particularly in palm oil.', NULL, 'NECO_History_2025.json', 'aa88cda155aec340518f0cd3f5c261723f5cf203bb502e13f235ee0ac2458982');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The 1884-1885 Berlin Conference was hosted by _____.', '["Queen Victoria","Napoleon Bonaparte","Otto von Bismarck","King Leopold II"]', 2, 'The German Chancellor Otto von Bismarck convened the conference to regulate European colonization and trade in Africa.', NULL, 'NECO_History_2025.json', '8c8f308cc4be9385f9a577dee8f05ce49a2b104593cd85db0bf58ee4f6326628');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''Manilla'' was a dominant form of _____ in the pre-colonial Niger Delta.', '["weapon","currency","religious idol","clothing"]', 1, 'Manillas were C-shaped metal bracelets (brass or copper) used as money for several centuries in West African trade.', NULL, 'NECO_History_2025.json', '1e85a785bb4df618eab65f069c60735f74bdb0bdbd84467df76732967f13a7ca');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The Amalgamation of Northern and Southern Nigeria in 1914 was performed by _____.', '["Sir Hugh Clifford","Lord Frederick Lugard","Sir John Macpherson","Sir Arthur Richards"]', 1, 'Lord Lugard merged the two protectorates into one political unit to facilitate administrative convenience and share revenue.', NULL, 'NECO_History_2025.json', '566e8a53292aaffb3df3ebe1bb43ec67a2d64614fa1aa7b303f1252745c04ccb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The first formal political party in Nigeria was the _____.', '["Action Group","NCNC","NNDP","NPC"]', 2, 'Herbert Macaulay founded the Nigerian National Democratic Party (NNDP) in 1923 to contest elections in Lagos.', NULL, 'NECO_History_2025.json', 'a829433205372239cd7cd3bcb8a0f46b96b88376bd8fe95b52b8d798a519f347');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The Richards Constitution of 1946 was noted for dividing Nigeria into _____.', '["States","Divisions","Regions","Prefectures"]', 2, 'The constitution created the Northern, Western, and Eastern regions, establishing the path toward regionalism.', NULL, 'NECO_History_2025.json', 'e81c40a4dba8bb22b492618e362d7d51b37ef581e7a9b7a316646eec6d93c49f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The 1929 Aba Women''s Riot was primarily sparked by the _____.', '["killing of a chief","introduction of direct taxation on women","burning of a market","fall of the price of oil"]', 1, 'Igbo and Ibibio women revolted because they feared the colonial census would lead to the direct taxation of women.', NULL, 'NECO_History_2025.json', '9d613df35088c9297318116797a9f457f40dbe5cb7bc53d9c3d1f01e456804cf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The quote above reflects the nationalist ideology of _____.', '["Nnamdi Azikiwe","Murtala Muhammed","Sani Abacha","Odumegwu Ojukwu"]', 0, 'Dr. Nnamdi Azikiwe (Zik) was a pioneer nationalist known for his emphasis on unity, pan-Africanism, and ending oppression.', '"The history of our country is a history of unity in diversity. From the ancient bronzes of Benin to the Jihad of the North, we have been a people of character. Our task today is to build a nation where no man is oppressed."', 'NECO_History_2025.json', 'c33a8df05fd24ad691840d403e90a359181a2bd546bb62028c0420d862d22f7d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''ancient bronzes'' mentioned in the passage were mostly looted during the _____.', '["Aba Riot","British Punitive Expedition of 1897","Amalgamation","1966 Coup"]', 1, 'British forces looted the famous Benin Bronzes (brass plaques) after destroying the city of Benin in 1897.', '"The history of our country is a history of unity in diversity. From the ancient bronzes of Benin to the Jihad of the North, we have been a people of character. Our task today is to build a nation where no man is oppressed."', 'NECO_History_2025.json', '6817dd7a34a7b1e390aee4ccd79a0a9d360755b0a42cc533ee5dda8dda0af1f8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The system of Indirect Rule failed in Southeastern Nigeria because _____.', '["the Igbo were too poor","it lacked traditional centralized authorities (Kings)","the climate was too harsh","the British were afraid"]', 1, 'Indirect Rule relied on kings; because the Igbo had village-based democracy, the British creation of ''Warrant Chiefs'' was seen as illegitimate.', NULL, 'NECO_History_2025.json', '44ad37634d9c5183ed460c55b71835f59ad49a56f73a61aee050089100c4a5ba');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The Macpherson Constitution of 1951 was criticized for being a _____ constitution.', '["Unitary","Military","Compromise","Strictly Federal"]', 2, 'It was described as a compromise because it attempted to balance the centralist and regionalist demands of different Nigerian groups.', NULL, 'NECO_History_2025.json', 'f66110ddb99f02c54239a90e6b2971e98bd4ba181f631ea9e19d41780419ced3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'Nigeria''s independence in 1960 was granted under the _____ Constitution.', '["Independence","Republican","Clifford","Lyttleton"]', 0, 'The 1960 Independence Constitution made Nigeria a sovereign state but retained the British Queen as the ceremonial Head of State.', NULL, 'NECO_History_2025.json', '906d5b1db5909958f19ee174eab40fe7184182f0f07ec0d47f98669c783a2274');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The first indigenous Governor-General of Nigeria was _____.', '["Ahmadu Bello","Nnamdi Azikiwe","Abubakar Tafawa Balewa","Obafemi Awolowo"]', 1, 'Zik took over from Sir James Robertson in 1960 as the representative of the Crown before becoming President in 1963.', NULL, 'NECO_History_2025.json', 'b49a8052068cdec6c6dc82ce265de825f18af18c389b48c58779bfa289c57fc9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The first military coup d''état in Nigeria occurred on _____.', '["July 29, 1966","January 15, 1966","December 31, 1983","January 15, 1970"]', 1, 'Led by Major Chukwuma Nzeogwu and others, the January 1966 coup ended the First Republic.', NULL, 'NECO_History_2025.json', 'ef880b892fbc763d466f059c300c4383fbc97b88f5aee7579cacfde4b211302f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The Nigerian Civil War (1967-1970) began when _____ declared the secession of the Eastern Region.', '["Yakubu Gowon","Murtala Muhammed","Odumegwu Ojukwu","Aguiyi Ironsi"]', 2, 'Lt. Col. Chukwuemeka Odumegwu Ojukwu declared the sovereign Republic of Biafra in May 1967.', NULL, 'NECO_History_2025.json', '84a9089fc3dc6d6b1ca23a7750f0dfd871e71924ab2cfca495ca4adfdb86e6d6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The policy of ''No Victor, No Vanquished'' was used to promote _____ after the Civil War.', '["Reconciliation","Retribution","Capitalism","Regionalism"]', 0, 'General Gowon implemented this policy to heal the wounds of the war and reintegrate the former secessionists into Nigeria.', NULL, 'NECO_History_2025.json', 'e05139dcd8d43b3cc78f7c28d0db3d5725f2f9024b6c44c0a199b947e24b957a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The Economic Community of West African States (ECOWAS) was founded in _____.', '["1960","1963","1975","1980"]', 2, 'Nigeria and Togo led the effort to create ECOWAS in Lagos on May 28, 1975.', NULL, 'NECO_History_2025.json', '84e9159d3f75b440b7ff3149b3b4a48de4b70dd65bfd9b8cfd6aa9059e0bd342');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The Lyttleton Constitution of 1954 is significant because it formally established _____ in Nigeria.', '["Unitary government","Independence","Federalism","Diarchy"]', 2, 'It provided for regional autonomy and shared power between the center and the regions, marking the start of a true federal system.', NULL, 'NECO_History_2025.json', 'a334b9dd6edd1fb3b7efa3edb07780cb8f7418f3abd5a2875fe01d5f0a9d3a82');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'King Jaja of Opobo was exiled by the British to _____.', '["London","The West Indies","Ghana","Sierra Leone"]', 1, 'British officials exiled him to St. Vincent in the West Indies in 1887 to stop him from controlling the palm oil trade.', NULL, 'NECO_History_2025.json', '771281f36f78705893f8dc67eb6e82c4449cb04874f927948639b5e0f5b9263d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The Sardauna of Sokoto, Sir Ahmadu Bello, was the leader of which party?', '["NCNC","AG","NPC","NEPU"]', 2, 'Ahmadu Bello led the Northern People''s Congress (NPC), which dominated Northern politics in the First Republic.', NULL, 'NECO_History_2025.json', 'ff9502c253efb593e07fda6ad70527d53a2ddf7fe67e4612e5fed5e01b7fbece');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''Golden Stool'' is a sacred symbol of the _____ people.', '["Yoruba","Asante","Ewe","Fante"]', 1, 'In present-day Ghana, the Golden Stool represents the soul and unity of the Asante nation.', NULL, 'NECO_History_2025.json', '6e2b647278ff243d34bea34469def033e0445bcf3135a547183c9f18c008aedc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The legendary priest who summoned the Golden Stool from heaven was _____.', '["Okomfo Anokye","Osei Tutu","Yaa Asantewaa","Prempeh I"]', 0, 'Okomfo Anokye was the chief priest and co-founder of the Asante Empire alongside Osei Tutu.', NULL, 'NECO_History_2025.json', '199347d5d0a29bdcfd9d7795cca7975e76833ac6546f995513e52fed4e2bea4b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'Which of the following was the capital of Nigeria from 1914 to 1991?', '["Calabar","Abuja","Lagos","Lokoja"]', 2, 'Lagos was the seat of government from the amalgamation until the capital was officially moved to Abuja on Dec 12, 1991.', NULL, 'NECO_History_2025.json', '4e76ecaeafe693ceff2ffcc89a65da9d212367099a465106a3544394c2a91e7a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The Sagrenti War of 1874 was an expedition against _____.', '["The Zulu","The Asante","The Benin Empire","The Sokoto Caliphate"]', 1, 'The British expedition led by Garnet Wolseley (Sagrenti) resulted in the burning of Kumasi.', NULL, 'NECO_History_2025.json', '83348d089752e50b3ed671a4cb9b30435dae91683fc8f69d08c483067a3613ca');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''Apartheid'' system was a policy of institutionalized racial segregation in _____.', '["Kenya","Zimbabwe","South Africa","Angola"]', 2, 'Apartheid was enforced by the National Party in South Africa from 1948 until the early 1990s.', NULL, 'NECO_History_2025.json', '29dcab4ca8e6cd4393942a0e03e23337fccc141aff593ba18bf770608317e9b1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The primary aim of the Organization of African Unity (OAU) formed in 1963 was to _____.', '["start a new currency","eradicate all forms of colonialism from Africa","fight the USA","build a continental highway"]', 1, 'The OAU aimed to promote unity and help African territories still under European rule to achieve independence.', NULL, 'NECO_History_2025.json', 'eb74411cf6b630fc958429bdcbf513d81fb6c9b4ec6bd44701cd9a10b7ee52b5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The first Nigerian Prime Minister was _____.', '["Nnamdi Azikiwe","Ahmadu Bello","Abubakar Tafawa Balewa","Obafemi Awolowo"]', 2, 'Sir Abubakar Tafawa Balewa led the federal government from 1957 until the 1966 coup.', NULL, 'NECO_History_2025.json', '3117548419b3ca71c506aaabba7bd4ca33b015adef9b4bd199ec1265c2b738d0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The African Union (AU) replaced the OAU in _____.', '["1994","2000","2002","2010"]', 2, 'The AU was launched in Durban, South Africa, in 2002 to better address economic and social challenges.', NULL, 'NECO_History_2025.json', 'aa2e78fb19b72befed6d6fee8eccb2f3513341559e94562f1107ebde2b62c0fd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The pre-colonial Dahomey kingdom was famous for its elite female military unit known as the _____.', '["Esho","Amazons","Mino","Ilari"]', 2, 'The ''Mino'' (Our Mothers), often called the Dahomey Amazons by Europeans, were a unique female-only regiment.', NULL, 'NECO_History_2025.json', 'cd60acb0711824e9d96fdf2c2893f818bd7f49a76d4fc3c96c2ef3a17c443207');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'Who was the ''Black Prophet'' of the Niger Delta who declared the ''Niger Delta Volunteer Force'' in 1966?', '["Isaac Adaka Boro","Ken Saro-Wiwa","Jaja of Opobo","Nana Olomu"]', 0, 'Isaac Boro led the ''Twelve Day Revolution'' to declare a Niger Delta Republic, citing the marginalization of the Ijaw.', NULL, 'NECO_History_2025.json', '35e8707b1e56d0f141f1462615846f52ece7f3baf6f5db2367224bbf51aa53a0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The 1957 Willink Commission was set up to _____.', '["fix the price of cocoa","address the fears of minority groups in Nigeria","draft the criminal code","conduct a census"]', 1, 'Minority groups feared domination by the majority tribes (Igbo, Yoruba, Hausa) as independence approached.', NULL, 'NECO_History_2025.json', 'bf2b6f5048a12b2b2654f3122ef75afb2bee4a8d733623c7058bc9cd614fdf10');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''Sefuwa Dynasty'' is associated with the history of _____.', '["Sokoto","Benin","Kanem-Borno","Oyo"]', 2, 'The Sefuwa (or Sayfawa) dynasty ruled Kanem-Borno for over a millennium, making it one of the longest in world history.', NULL, 'NECO_History_2025.json', '23ec92ac2330ae91693438509d66505257e398bcbf73c8cde9886904a52ff02a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'Idris Alooma introduced the use of _____ from the Ottoman Empire to expand Borno.', '["Turkish musketeers","war elephants","ships","submarines"]', 0, 'He brought in muskets and trained marksmen from Turkey, giving him a huge advantage over rivals.', NULL, 'NECO_History_2025.json', '1bfce0dcd2820c3403c8a2ca01e4462a64fe2b6687ab9c35799f10a2d5f100ce');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The first indigenous Bishop of the Anglican Church in West Africa was _____.', '["Samuel Ajayi Crowther","Henry Townsend","Hope Waddell","Thomas Freeman"]', 0, 'A former slave from Osoogun, Crowther was consecrated as Bishop of the Niger Territory in 1864.', NULL, 'NECO_History_2025.json', 'df4e847cc383097db64e882e546135214d247b7f493e06ad4e536ff871245be6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''Scramble for Africa'' began in earnest following the _____.', '["Industrial Revolution","Discovery of Oil","French Revolution","Berlin Conference"]', 3, 'While the Industrial Revolution provided the motive, the Berlin Conference provided the ''legal'' framework for the partition.', NULL, 'NECO_History_2025.json', 'fa138f3bb6c61502709e745e7d3b0c89a0e3223ca00d5b767974211256cf4173');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'Which empire was destroyed by the British during the ''Punitive Expedition'' of 1897?', '["Sokoto","Benin","Oyo","Mali"]', 1, 'The British destroyed Benin City and looted its palace in retaliation for the killing of a British delegation.', NULL, 'NECO_History_2025.json', 'f48a7851ae1a67da23e5f5aa53fe185efeedabb982be9baf626a87af82e396e3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The first capital of Northern Nigeria under British rule was _____.', '["Kaduna","Kano","Lokoja","Zungeru"]', 2, 'Lokoja served as the early headquarters of the Royal Niger Company and the early administration before moving to Zungeru and then Kaduna.', NULL, 'NECO_History_2025.json', 'da1d4988552f12d4fcfe672498d50c533ac58539294f6035a975dd73a8d99c4b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''Warrant Chief'' system was an artificial creation in _____.', '["The North","The West","The East","Lagos"]', 2, 'In Igboland, the British appointed chiefs to collect taxes and run courts, a role that had no traditional basis in their society.', NULL, 'NECO_History_2025.json', 'e8e1a1705650695b6ea72c7675f4971fac6f19bb92583cf8246d120486e6b532');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The return of educated veterans after World War II fueled the growth of _____.', '["Tribalism","Nationalism","Communism","Fascism"]', 1, 'Soldiers returned with a new perspective on world affairs and a refusal to remain subjects of a colonial empire.', NULL, 'NECO_History_2025.json', '116f360b1a71c784b47108fa87fbae289c724396f8d67eb631532dc4b3fd18c2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The first University in Nigeria, established in 1948, was an affiliate of the University of _____.', '["Oxford","Cambridge","London","Harvard"]', 2, 'The University College, Ibadan was an affiliate of the University of London until 1962.', NULL, 'NECO_History_2025.json', '6c55bcf095c67420249900c7ae8cc3409d0f2e517556db0663af4f9555252f71');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The policy of ''Assimilation'' was used by which colonial power in Africa?', '["Britain","France","Portugal","Germany"]', 1, 'France aimed to turn Africans into ''Black Frenchmen'' by making them adopt French language, laws, and culture.', NULL, 'NECO_History_2025.json', 'c84b32af7e23f5ac7aec65a57a4c93dcbdaa4f7a66211d73f20e96f3129a4a1b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''National Youth Service Corps'' (NYSC) was established in 1973 by _____.', '["Murtala Muhammed","Yakubu Gowon","Shehu Shagari","Olusegun Obasanjo"]', 1, 'General Gowon established the scheme to promote national integration after the Civil War.', NULL, 'NECO_History_2025.json', 'f1d7c7854a809797e2f7b3cc0b5436044358617ff8798f2cd6f69c2ffdae9dea');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The headquarters of the African Union (AU) is in _____.', '["Lagos","Accra","Addis Ababa","Cairo"]', 2, 'Addis Ababa, Ethiopia, serves as the diplomatic and administrative hub for the AU.', NULL, 'NECO_History_2025.json', '2434fcdcd7af1f28444fae90cbdc4c31be449eda2dff98f60bb7dc84189d2440');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'Which Nigerian leader was killed in the July 1966 ''Counter-Coup''?', '["Aguiyi Ironsi","Tafawa Balewa","Ahmadu Bello","Samuel Akintola"]', 0, 'Major General Johnson Aguiyi-Ironsi, the first military Head of State, was killed during a revolt by Northern officers.', NULL, 'NECO_History_2025.json', '7498dc590035165f1850c16ce5f2a541bad94a4b54a48f5d49d931153e470e48');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The Second Republic (1979-1983) was led by President _____.', '["Nnamdi Azikiwe","Olusegun Obasanjo","Shehu Shagari","Ibrahim Babangida"]', 2, 'Alhaji Shehu Shagari of the NPN was the first executive President under the American-style presidential system.', NULL, 'NECO_History_2025.json', '3535bf6a90a574c06fcba50bfcbf40c489291dea3a299ef9ed246bc48defeb02');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''Indigenization Decree'' of 1972 aimed at _____.', '["nationalizing all farms","giving Nigerians ownership of the economy","banning all imports","abolishing the Naira"]', 1, 'The decree sought to transfer control of key sectors from foreign firms to indigenous Nigerian entrepreneurs.', NULL, 'NECO_History_2025.json', '2f2f8f0a63192a0d752450a225c76eceff74e2b2954f6eef807ad646448e8c69');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The leader of the ''Zikist Movement'' was _____.', '["Nnamdi Azikiwe","M.C.K. Ajuluchukwu","Obafemi Awolowo","Herbert Macaulay"]', 1, 'While named after Azikiwe, the militant youth wing was led by radicals like M.C.K. Ajuluchukwu and Raji Abdallah.', NULL, 'NECO_History_2025.json', '2e56e56deb260d7b489ab35ea3f6b8c9cc7cebed41661907363fb190a0244aec');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''Clifford Constitution'' of 1922 was significant because it introduced the _____.', '["Regions","Elective Principle","Presidency","Supreme Court"]', 1, 'It allowed for the first time in British West Africa the election of representatives into the Legislative Council.', NULL, 'NECO_History_2025.json', '6aaaf81262cdaad60d370249605ceb30e91aa190b0ab38c541d8b2d96f4b5491');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The legendary founder of Ile-Ife and the Yoruba race is _____.', '["Oduduwa","Oranmiyan","Sango","Ogun"]', 0, 'In Yoruba mythology, Oduduwa is the progenitor of the people and the ancestor of all crowned Yoruba kings.', NULL, 'NECO_History_2025.json', 'a113219907f08625457b93be21d3f93aa61e0daaf110f8c0195cf4ce289b790b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The historical city-state of Kano became the leading commercial center in Hausaland because of its _____.', '["gold mines","leather and textile industries","naval power","coal mines"]', 1, 'Kano was famous for its indigo pits and the manufacture of high-quality leather and woven cloth.', NULL, 'NECO_History_2025.json', '8f80f51f05ce486cf1506fdcaf8630e4fef37b6c61a4a2e22a038feb546a60ed');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''Royal Niger Company'' was granted a charter in 1886 to _____.', '["preach the Gospel","administer and trade in the Niger basin","build schools","fight the French in Dahomey"]', 1, 'The charter gave George Goldie’s company the power to act as a government on behalf of Britain in the Niger territories.', NULL, 'NECO_History_2025.json', '6f4c2df8ad7bab0cfd2e2c824ae6a0aaef72688a3e1ece57e9be1e96e031e6d1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The 1953 ''Kano Riot'' was triggered by the visit of _____ to the North.', '["Azikiwe","Akintola","Awo","Enahoro"]', 1, 'Action Group leaders visited Kano to campaign for self-government, leading to clashes with Northern NPC supporters.', NULL, 'NECO_History_2025.json', '6c0be51d2ceca17a8c53441afe7962a8f9183778f2cf33e1a577262a75c24f19');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The 19th-century Yoruba Civil Wars were largely a result of the collapse of the _____.', '["Benin Empire","Old Oyo Empire","Sokoto Caliphate","Asante Empire"]', 1, 'The fall of Oyo created a power vacuum, leading to decades of war between Ibadan, Abeokuta, Ijaye, and others.', NULL, 'NECO_History_2025.json', 'a700c2eece3578e58cbd1716c7ba05c23c72c5709bb7915ed3c3c19745d51ef7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''Bula Matari'' (Breaker of Rocks) was the nickname given to _____.', '["Lord Lugard","Henry Morton Stanley","Cecil Rhodes","King Leopold"]', 1, 'Stanley earned this name in the Congo for his use of force and his road-building projects during exploration.', NULL, 'NECO_History_2025.json', '50acf4ebb6d337eb086ca96c09cb6c2c38382f4b4b8f9b9877bd05909aab33cd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The Jukun kingdom of Kwararafa was most noted for its frequent military raids against _____.', '["The Oyo Empire","The Hausa States","Benin","The Igbo"]', 1, 'Kwararafa was a formidable power that frequently attacked Kano, Katsina, and Zaria in the 17th century.', NULL, 'NECO_History_2025.json', 'cfb29e131fdfc107194a27d580e16c10cbeb60d163ce63d164004a0fb25c06b7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''Unity Fountain'' and the shift of the capital to Abuja occurred during the regime of _____.', '["Buhari","Babangida","Abacha","Abdulsalami"]', 1, 'General Ibrahim Babangida moved the capital from Lagos to Abuja on December 12, 1991.', NULL, 'NECO_History_2025.json', '846d74804a7c1b82d85b56d80e559a54659ec48cbd257d4fcd4a76d553a4f1de');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''Apartheid'' system in South Africa was officially dismantled following the first multi-racial elections in _____.', '["1990","1992","1994","1996"]', 2, 'In 1994, Nelson Mandela was elected as the first Black president, ending decades of institutionalized racism.', NULL, 'NECO_History_2025.json', 'ad3e0e652fbcaeafe573bd9274375a60e51bb51b07f7587a9eb04ac9b067e2b6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The Trans-Saharan trade route connected West Africa primarily with _____.', '["North Africa and Europe","The Americas","India","China"]', 0, 'The routes linked the Western Sudan with North African cities like Fez and Tunis, and through them, to the Mediterranean.', NULL, 'NECO_History_2025.json', '68436363c005f828b437c2b9a40894aedb0fc99e8c6da97fe5b5f0bc9eb93a64');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The principal architect of the Fulani Empire was _____.', '["Usman dan Fodio","Mohammed Bello","Abdullahi dan Fodio","Sultan Abubakar"]', 0, 'Usman dan Fodio led the religious and political movement that replaced Hausa kings with Fulani Emirs.', NULL, 'NECO_History_2025.json', 'd9963995c1eecdefcb84a4d98ced7396a713091b3e543bb8769be561cccbca05');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The first Nigerian to be appointed a judge of the International Court of Justice was _____.', '["Taslim Elias","Justice Udo Udoma","Fatai Williams","Charles Onyeama"]', 3, 'Justice Charles Onyeama was elected to the ICJ in 1967. (Note: Taslim Elias later became President of the ICJ).', NULL, 'NECO_History_2025.json', '29e2ab219d353d1ffcc1ad28018717352b282014d613fd6ad018cf601806e800');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The Sagrenti War ended with the signing of the Treaty of _____.', '["Kumasi","Fomena","Accra","Lagos"]', 1, 'After the defeat of the Asante in 1874, they signed the Treaty of Fomena with the British.', NULL, 'NECO_History_2025.json', 'd10f5e742cffba2125bf66bd3573de4cb87945cc3cc6dfb84d617f853789b96c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'The ''Egba Uprising'' of 1918 was a protest against _____.', '["Christianity","Warrant Chiefs and taxes","The King of Dahomey","Slave trade"]', 1, 'Also known as the Adubi War, it was caused by the introduction of direct taxation and administrative reforms in Egbaland.', NULL, 'NECO_History_2025.json', 'e8399b8a1dddb34b68addec3a021ebe5f6fd9fd1272f129bcc3d155c0a0266f2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'History', 2025, NULL, 'Which of the following describes the ''Legitimate Commerce'' that replaced the slave trade?', '["Trade in gold and ivory","Trade in vegetable oils and raw materials","Trade in guns and rum","Trade in cars"]', 1, 'Legitimate commerce refers to the export of palm oil, cotton, and groundnuts which replaced the trade in human beings.', NULL, 'NECO_History_2025.json', '54f0bc5a08e83971226a43ee90d909f67bb1b21c1c4d8fe6ee6b60f8dcc14141');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The first Surah of the Glorious Qur''an is known as _____.', '["Al-Baqarah","Al-Nas","Al-Fatihah","Al-Ikhlas"]', 2, 'Suratul-Fatihah is the opening chapter of the Qur''an and is recited in every unit of the Muslim prayer.', NULL, 'NECO_IRS_2024.json', '44a142b8e751a81d164d015b5dbb28685b0573d97322f31408f942fb02c235b3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The Qur''an was revealed to Prophet Muhammad (SAW) over a period of approximately _____ years.', '["10","13","23","40"]', 2, 'The revelation began when the Prophet was 40 years old and ended shortly before his death at 63, totaling 23 years.', NULL, 'NECO_IRS_2024.json', '37af59acf0b69df7f622e3b8679f60eec358ffb9861155536ea21bb75045a9d1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The primary source of Islamic Law (Shari''ah) is the _____.', '["Hadith","Qur''an","Ijma","Qiyas"]', 1, 'The Qur''an is the ultimate and most authoritative source of guidance in Islam, providing the foundational principles of faith and law.', NULL, 'NECO_IRS_2024.json', '2414824e15fdb8849bad4c376c5fab2bd97780b5add1b563e43db67273047d85');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Year of Elephant'' (Amul-Fil) is significant because it was the year _____.', '["the Prophet migrated","the Ka''bah was built","the Prophet was born","the first battle occurred"]', 2, 'Prophet Muhammad (SAW) was born in 570 CE, the year Abrahah Al-Ashram attempted to destroy the Ka''bah with an army of elephants.', NULL, 'NECO_IRS_2024.json', '64b1a4aebde82a568cefd10ebb24450ffdbcf2baddaaea09dcba126932e39cd6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The term ''Tawhid'' in Islam refers to the _____.', '["Prophethood","Oneness of Allah","Day of Judgment","Belief in Angels"]', 1, 'Tawhid is the core concept of monotheism in Islam, asserting that Allah is one and unique in His essence and attributes.', NULL, 'NECO_IRS_2024.json', 'a51eabeeb9cb3826b75c1b3b01d785ed4e55b611782caaccd475cef190426ddb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'Which of the following is NOT among the ''As-Sihah as-Sittah'' (The Six Authentic Books of Hadith)?', '["Sahih Bukhari","Sahih Muslim","Muwatta Malik","Sunan Abu Dawood"]', 2, 'Muwatta Malik is a highly respected legal and Hadith collection but is not traditionally numbered among the ''Six Books''.', NULL, 'NECO_IRS_2024.json', '121b00f443ebd7d1c45ace6d3553b8d24705b5151797a3ef5e4cacd11492efb9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The first Caliph in Islam was _____.', '["Umar b. Khattab","Ali b. Abi Talib","Uthman b. Affan","Abu Bakr As-Siddiq"]', 3, 'Abu Bakr As-Siddiq was the first of the four Rightly Guided Caliphs, serving from 632 to 634 CE.', NULL, 'NECO_IRS_2024.json', 'c49fd59d69e4b557c458f7b14ac9dab4c277994dc0bbe5507d802c68aa129f1b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ritual of ''Sa''y'' during Hajj involves walking between the hills of _____.', '["Arafat and Muzdalifah","Safa and Marwa","Mina and Makkah","Uhud and Hira"]', 1, 'Sa''y commemorates Hajar''s (AS) search for water for her son Ismail (AS) between the hills of Safa and Marwa.', NULL, 'NECO_IRS_2024.json', '71fa8db359a1ad87d1fe0e21b9e48c32455354832c32a0c4f52f3cafa7fc724a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The amount of Zakat payable on wealth (gold/cash) that has reached the Nisab is _____.', '["10%","5%","2.5%","1%"]', 2, 'Zakat on liquid assets is calculated at 2.5% (one-fortieth) of the total savings held for a full lunar year.', NULL, 'NECO_IRS_2024.json', 'a93a5596183ec8d431049d8a525c815c2d0d6dbbc9f759be4efb613d67c5507e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The Surah that is equivalent to one-third of the Qur''an in terms of reward is _____.', '["Suratul-Falaq","Suratul-Ikhlas","Suratul-Nas","Suratul-Kafirun"]', 1, 'Suratul-Ikhlas summarizes the concept of Tawhid, which represents one-third of the message of the Qur''an.', NULL, 'NECO_IRS_2024.json', '73c12654293fcf1704c8aea4630de84c904b3e108e99d1d950d25c452e35f806');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'In Islamic Inheritance (Mirath), a daughter''s share when she is the only child is _____.', '["One-third","One-half","One-quarter","One-eighth"]', 1, 'According to Suratan-Nisa (Q4:11), if there is only one daughter and no son, she receives half of the estate.', NULL, 'NECO_IRS_2024.json', 'bfb98d816886c3b1e003a1a523501a1a033bfdba87678b37f2598af76d1bede3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The companion known as ''Dhul-Nurayn'' (The possessor of two lights) was _____.', '["Abu Bakr","Umar","Uthman","Ali"]', 2, 'Uthman b. Affan was given this title because he married two of the Prophet''s daughters, Ruqayyah and Umm Kulthum.', NULL, 'NECO_IRS_2024.json', 'ebd2da1cadee8795e3afa0e60b889800406b78ffce82186ba333e480771d2f2c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The battle in which the Muslims suffered a setback due to the disobedience of the archers was the Battle of _____.', '["Badr","Uhud","Khandaq","Hunayn"]', 1, 'At Uhud, the archers left their positions on the hill against the Prophet''s orders, allowing the enemy to launch a counter-attack.', NULL, 'NECO_IRS_2024.json', 'd3445aeee1a7ee59bbed418375e1fb4f66b5ab5b8db210add5227e3e00e3bfc0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The science of the rules governing the correct pronunciation of the Qur''an is called _____.', '["Tafsir","Tajwid","Fiqh","Hadith"]', 1, 'Tajwid is the science of reciting the Qur''an according to the established rules of articulation and phonetics.', NULL, 'NECO_IRS_2024.json', 'a8f42a9b46e0476008be636dee9b80df22028be1760f381fefe76f5be5383216');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The angel responsible for blowing the trumpet (Sur) to signal the Day of Judgment is _____.', '["Jibril","Mika''il","Israfil","Izra''il"]', 2, 'Israfil is the angel tasked with blowing the trumpet twice: once to end life and once to initiate the resurrection.', NULL, 'NECO_IRS_2024.json', 'e23f541bde900efc84cd51a0e90806241a12cf6077c99bcdff921331659d0a2e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The collection and compilation of the Qur''an into a single volume was initiated during the Caliphate of _____.', '["Abu Bakr","Umar","Uthman","Ali"]', 0, 'Following the Battle of Yamamah, Abu Bakr ordered Zaid b. Thabit to compile the Qur''an into a single Mushaf.', NULL, 'NECO_IRS_2024.json', 'd5397a680507b1c02d0599c16d2d695231f2e734f9ea60b8c15eebedd8431adc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'A ''Mahr'' in an Islamic marriage is the _____.', '["wedding feast","marriage contract","obligatory gift to the bride","divorce settlement"]', 2, 'Mahr is the mandatory dowry or gift paid by the groom to the bride at the time of marriage as a sign of respect and security.', NULL, 'NECO_IRS_2024.json', '76b1b902238fdd0ee80648a7e8eabfcc7677031136f8acd5e5391eac16c3250e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The act of ''Tayammum'' is performed when _____ is unavailable.', '["food","water","a prayer mat","a mosque"]', 1, 'Tayammum is dry ablution using clean earth/sand when water is not available or its use is harmful.', NULL, 'NECO_IRS_2024.json', '538aa11ba010f7076d0a3264a9583886989e3a98efd2adaf8a9b8f79224be408');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The central theme of this Hadith is _____.', '["Prayer","Altruism and Love","Business Ethics","Hajj"]', 1, 'The Hadith emphasizes that true faith involves selfless love and wishing good for others.', 'Prophet Muhammad (SAW) said: ''None of you truly believes until he wishes for his brother what he wishes for himself.'' (Narrated by Al-Bukhari and Muslim)', 'NECO_IRS_2024.json', '2bdd52d25d9a935a6e87f8b4844c7f6125ac78c2f0cc8fcc2098c744d8a15f4f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'In this context, ''brother'' refers to _____.', '["biological siblings only","Muslims only","fellow human beings","neighbors only"]', 2, 'While it refers primarily to brothers in faith, Islamic ethics extend this spirit of kindness to all humanity.', 'Prophet Muhammad (SAW) said: ''None of you truly believes until he wishes for his brother what he wishes for himself.'' (Narrated by Al-Bukhari and Muslim)', 'NECO_IRS_2024.json', '9887ef98ad17e08e509d879b2bcd7f99b44db534a507a4c4789ac19e0347ef0a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Nisab'' of cattle (cows) for Zakat starts at _____ animals.', '["5","30","40","10"]', 1, 'Zakat is not due on cows until the owner possesses 30, at which point one one-year-old calf (Tabi'') must be given.', NULL, 'NECO_IRS_2024.json', 'b4b32f53787956eb3f7897788a5c921d9e51de70e722dce3d9091fde8bb93a2a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The term ''Shirk'' means _____.', '["Belief in Allah","Associating partners with Allah","Performing Salat","Fasting in Ramadan"]', 1, 'Shirk is the opposite of Tawhid and is considered the gravest sin in Islam as it denies the absolute Oneness of God.', NULL, 'NECO_IRS_2024.json', '1bc4a81f51123a1c9b5ce6cc6cff039e3cfd809684a4971bbecc452c45d295b6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Hijrah'' calendar begins from the year the Prophet (SAW) migrated from _____ to _____.', '["Makkah to Abyssinia","Madinah to Makkah","Makkah to Madinah","Madinah to Ta''if"]', 2, 'The Islamic era (Hijri) marks the migration to Madinah in 622 CE, which led to the establishment of the first Islamic state.', NULL, 'NECO_IRS_2024.json', '69fb138176f75660f6a6e02b735b07e39ba1047de11929f6650d009a399887d3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Khulafah ar-Rashidun'' refers to the _____.', '["Umayyad Caliphs","Abbasid Caliphs","Rightly Guided Caliphs","Ottoman Sultans"]', 2, 'This title is given to the first four Caliphs: Abu Bakr, Umar, Uthman, and Ali, who followed the Sunnah of the Prophet closely.', NULL, 'NECO_IRS_2024.json', '4045d1265d7f828c696023476096a3380974f99ec36de55cd0c1a64b46adb21c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The pre-Islamic period of ignorance in Arabia is known as _____.', '["Jahiliyyah","Fitnah","Riddah","Asabiyyah"]', 0, 'Jahiliyyah refers to the state of affairs in Arabia before the mission of Prophet Muhammad (SAW).', NULL, 'NECO_IRS_2024.json', '002ff3de02683267881dd95fa7721386682fce66e7fac0dc28fd912d04024978');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Iddah'' period for a divorced woman who is not pregnant is _____.', '["4 months and 10 days","3 menstrual cycles","1 year","40 days"]', 1, 'The Qur''an specifies three monthly cycles (Quru'') for a divorced woman to ensure the womb is clear before remarriage.', NULL, 'NECO_IRS_2024.json', 'f87ad040ab56b2a5fb564bb29bc962209856b0554333ae4f46c46b14813f8c19');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The first Mu''adhin (caller to prayer) in Islam was _____.', '["Zaid b. Harithah","Bilal b. Rabah","Abdullah b. Mas''ud","Salman al-Farisi"]', 1, 'Bilal b. Rabah, an Abyssinian companion, was chosen by the Prophet for his strong and beautiful voice.', NULL, 'NECO_IRS_2024.json', '68866d378d426f170f3579b4dd03e456f05909dd0b078d59ac62e5035a69bae9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Night of Power'' (Laylatul-Qadr) is better than _____ months.', '["100","500","1,000","10,000"]', 2, 'Suratul-Qadr states that worship on this night in Ramadan is better than a thousand months of worship.', NULL, 'NECO_IRS_2024.json', 'f984eee3190cee8f861d43e2e6f1a4379776d3fa03901226b676540427186607');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The legal ruling that is ''highly recommended'' but not strictly obligatory is called _____.', '["Fard","Mustahabb","Makruh","Haram"]', 1, 'Mustahabb actions are rewarded if performed but do not incur punishment if omitted.', NULL, 'NECO_IRS_2024.json', '8880552ebe5d60e99fe6460207024da66450549887da5550500e3b683eea0b55');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The Islamic concept of ''Ihsan'' means _____.', '["to pay Zakat","to worship Allah as if you see Him","to fast in the heat","to go for Hajj twice"]', 1, 'Defined in the Hadith of Jibril, Ihsan is the perfection of faith where one acts with constant awareness of Allah''s presence.', NULL, 'NECO_IRS_2024.json', '647d8d032db7c01551840e1ac0f1819bbf95902522abd3f0d2dbeaa3f3bdbdda');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'Which Caliph oversaw the expansion of Islam into Persia and Egypt?', '["Abu Bakr","Umar b. Khattab","Uthman b. Affan","Ali b. Abi Talib"]', 1, 'Umar (RA) was the great administrator and conqueror under whose rule the Islamic empire expanded most rapidly.', NULL, 'NECO_IRS_2024.json', '7dff41cfac71ea203eedede3c1e048ba85bb20ee8bcc0ec2f78be08b6ab6c3ef');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Sunnah'' refers to the _____ of the Prophet Muhammad (SAW).', '["writings","physical appearance","sayings, actions, and approvals","family tree"]', 2, 'Sunnah encompasses everything the Prophet said, did, or tacitly approved (Taqrir).', NULL, 'NECO_IRS_2024.json', 'eaebcfcaa4ff854cc814a19f2f355ee2303c7ca5556473e1c22345d32bcf4819');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The major theme of the ''Makkan'' Surahs is usually _____.', '["Social legislation","Tawhid and the Hereafter","War and Peace","Rules of Inheritance"]', 1, 'Makkan Surahs focus on establishing faith and the oneness of Allah, while Madinan Surahs focus on law and community.', NULL, 'NECO_IRS_2024.json', 'c9852f1d9cb438ae546e7f6f20b57c08a0d9f787db8fda295e13c9e41ccf56ec');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Battle of the Trench'' is also known as the Battle of _____.', '["Al-Ahzab","Tabuk","Mu''tah","Khaybar"]', 0, 'It is called Al-Ahzab (The Confederates) because multiple tribes joined the Quraysh to attack Madinah.', NULL, 'NECO_IRS_2024.json', '3ec21ea82407a9121ec3c0504b077eda5930324c082f521b14876063960b66b9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The prophet mentioned most frequently by name in the Qur''an is _____.', '["Muhammad (SAW)","Ibrahim (AS)","Musa (AS)","Isa (AS)"]', 2, 'Prophet Musa (AS) is mentioned 136 times in the Qur''an.', NULL, 'NECO_IRS_2024.json', 'e2a2e3681c54075f47b815201ba12430b1e3ad8b3b6cda9b3ebed85d1dec386f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The direction (Qiblah) Muslims face during prayer was changed from _____ to Makkah.', '["Cairo","Jerusalem","Madinah","Damascus"]', 1, 'Initially, Muslims faced Masjid al-Aqsa in Jerusalem before the revelation changed it to the Ka''bah.', NULL, 'NECO_IRS_2024.json', '38df6c8ea1dcf61d255221d087dd07224f37c96c840057531e9e915b874aadeb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Haram'' months in which fighting is prohibited are _____.', '["Ramadan and Shawwal","Dhul-Qi''dah, Dhul-Hijjah, Muharram, and Rajab","Muharram and Safar","Rabi'' al-Awwal and Rabi'' al-Thani"]', 1, 'These four months are sacred in Islam, and starting warfare during them is forbidden.', NULL, 'NECO_IRS_2024.json', '435b17ed33627f24707f4791c3c6ad2bbab7c4ab1db68c61f077c0e1c2c8f47a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The act of ''Istighfar'' means _____.', '["praising Allah","seeking forgiveness","declaring Allah''s greatness","fasting"]', 1, 'Istighfar is the act of saying ''Astaghfirullah'' (I seek forgiveness from Allah).', NULL, 'NECO_IRS_2024.json', '1cd016228f745d9f5510d14774228440ec64a8e7c31c019522a01c87695a139e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'A person who memorizes the entire Qur''an is called a _____.', '["Hafiz","Qari","Mufassir","Faqih"]', 0, 'Hafiz (Guardian) is the title for someone who has committed the 6,236 verses of the Qur''an to memory.', NULL, 'NECO_IRS_2024.json', 'f8436c35c48456036df41143de0af49df4d6beb7713d055c5805b54e3eedd1ae');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Riddah'' wars were fought during the Caliphate of Abu Bakr against _____.', '["the Romans","the Persians","apostates and false prophets","the Quraysh"]', 2, 'After the Prophet''s death, some tribes rebelled or followed false prophets; Abu Bakr fought to maintain Islamic unity.', NULL, 'NECO_IRS_2024.json', '00871e254ef792030cb9a0d1d621fcf3d3dfdf70ca26a31150124504bdfb49ef');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Al-Faruq'' was the title of which Caliph?', '["Abu Bakr","Umar b. Khattab","Uthman","Ali"]', 1, 'Umar was called Al-Faruq (The one who distinguishes between truth and falsehood) for his strict justice.', NULL, 'NECO_IRS_2024.json', 'a2e25c9a9fb9fe2e2d49c3e24c7d53f5f9a54810873a5e9416ad0dddd5ac89f2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'Islamic monotheism is divided into categories: Tawhid ar-Rububiyyah, Tawhid al-Uluhiyyah, and _____.', '["Tawhid al-Iman","Tawhid al-Asma was-Sifat","Tawhid al-Qadr","Tawhid al-Ihsan"]', 1, 'The third category involves the belief in Allah''s unique Names and Attributes.', NULL, 'NECO_IRS_2024.json', 'dd115ad67b76d58a01cc2169e307f978d2d6f6936ef3089c6d2a6989be55c8dc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Sujud as-Sahw'' is performed when a person _____.', '["finishes the Qur''an","makes a mistake in prayer","receives good news","enters a mosque"]', 1, 'Two extra prostrations are performed at the end of Salat to compensate for forgetfulness or errors.', NULL, 'NECO_IRS_2024.json', 'a71a464997c9bf0a7605fcfd554731fcfab4b17250b8fda8074a17875a17d8ad');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The primary objective of ''Sawm'' (fasting) as stated in the Qur''an is _____.', '["weight loss","poverty awareness","Taqwa","patience"]', 2, 'Qur''an 2:183 states that fasting is prescribed so that you may achieve Taqwa (God-consciousness).', NULL, 'NECO_IRS_2024.json', '8526f6122d11f6726642e65fa76967badb04b23d807b1d4877b585169d80df73');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'In Shari''ah, the prohibited acts are known as _____.', '["Halal","Haram","Mubah","Wajib"]', 1, 'Haram refers to anything explicitly forbidden by Allah and His Messenger.', NULL, 'NECO_IRS_2024.json', 'd3a65f0337f5bb678bdaae31af59947cd13d842ffea8aaa7f733e063d8fdc55e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The first revelation came to the Prophet in the Cave of _____.', '["Thawr","Hira","Uhud","Safa"]', 1, 'The Archangel Jibril first appeared to the Prophet in the Cave of Hira on Mount Nur.', NULL, 'NECO_IRS_2024.json', '6ee4c87bf73db67c85a100397c71a2dc1a9f5afd74c34683302593657b143f94');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'Which Caliph was known for compiling the standard version of the Qur''an?', '["Abu Bakr","Umar","Uthman","Ali"]', 2, 'Uthman (RA) ordered the standardization of the Qur''anic text to ensure uniformity across the expanding empire.', NULL, 'NECO_IRS_2024.json', 'ddf339b5a56c9843760ac7c67f44ddee499d609d1a118633f49c0bc7f851544e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Asadullah'' (Lion of Allah) was a title of _____.', '["Khalid b. Walid","Umar b. Khattab","Hamzah b. Abdul-Muttalib","Ali b. Abi Talib"]', 2, 'Hamzah, the Prophet''s uncle, was given this title for his extraordinary bravery in battle.', NULL, 'NECO_IRS_2024.json', '11c1cf1b106551d66f3405f0599c53e441f3261760acad2d0eab6b9848718e75');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'A ''Mushrik'' is a person who _____.', '["denies Allah''s existence","associates partners with Allah","fasts without praying","commits murder"]', 1, 'The term comes from Shirk, meaning the act of attributing Allah''s powers or divinity to others.', NULL, 'NECO_IRS_2024.json', '8ff090d305e81c17da5ec0e1dff75d5d163a9c71633c0adda328029bb43cf6e1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The five daily prayers are: Fajr, Zuhr, Asr, Maghrib, and _____.', '["Tahajjud","Witr","Isha","Duha"]', 2, 'Isha is the night prayer, the last of the five obligatory daily prayers.', NULL, 'NECO_IRS_2024.json', '83f43878ac78d2a7fefc701bd9e2547d98c153a039de0f1bcfc456863e503369');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The term ''Tafsir'' refers to _____.', '["recitation","exegesis/explanation","memorization","handwriting"]', 1, 'Tafsir is the academic study and commentary used to explain the meanings of the Qur''anic verses.', NULL, 'NECO_IRS_2024.json', '65cf70aad83f66b07877926d80b3c6b0eb4e4f7f2dc87b7d37a0a225ed68b12b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'A Hadith narrated by only one person at every stage of the chain is called _____.', '["Gharib","Aziz","Mashhur","Mutawatir"]', 0, 'Gharib means ''solitary'' or ''strange'' in the science of Hadith terminology.', NULL, 'NECO_IRS_2024.json', 'b849c6507c1c6d26a34697bfc4c70c99361f4c7e39f4d6d0ddc0397bf1dd959c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The Prophet Muhammad (SAW) belonged to the tribe of _____.', '["Aus","Khazraj","Quraysh","Thaqif"]', 2, 'He was from the Banu Hashim clan of the noble Quraysh tribe in Makkah.', NULL, 'NECO_IRS_2024.json', 'a9eaf832b45c771fedc920b5ed0968fd1549422527dee6512c6b47786c886fec');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Kharaj'' in Islamic taxation refers to _____.', '["tax on trade","land tax","poll tax on non-Muslims","war booty"]', 1, 'Kharaj is a tax levied on agricultural land in territory conquered by Muslims.', NULL, 'NECO_IRS_2024.json', '229418f24c428c72f530f3899f81cc15d879096233dcea237611e04db9c4bd83');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The Surah that describes the short duration of time and importance of faith is _____.', '["Suratul-Nas","Suratul-Ikhlas","Suratul-Asr","Suratul-Falaq"]', 2, 'Suratul-Asr declares that all mankind is in loss except those with faith, good deeds, and who encourage truth and patience.', NULL, 'NECO_IRS_2024.json', 'bc63dd03dbd7dfa761d13be540647c2d830935cc32d19f7d6b584c00e6ac031b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'Which of the following is the ''Prophet of Allah'' who was swallowed by a whale?', '["Musa","Yusuf","Yunus","Lut"]', 2, 'Prophet Yunus (AS) was swallowed by a whale and remained in its belly until he was released through prayer and repentance.', NULL, 'NECO_IRS_2024.json', 'bf222c0362a7fdf501792d2845b827263b09b83e90f1987a163793d953a0c448');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Nisab'' for sheep and goats for Zakat starts at _____ animals.', '["5","30","40","10"]', 2, 'One must own at least 40 sheep or goats for one full lunar year before Zakat becomes due on them.', NULL, 'NECO_IRS_2024.json', '459843bda232f5319280334235a695096e32708b9a527554b3451ec2b6228b79');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Takbirat al-Ihram'' is the _____.', '["final greeting","opening ''Allahu Akbar''","prostration","call to prayer"]', 1, 'This Takbir signals the formal entry into the state of prayer, during which ordinary talk and eating are forbidden.', NULL, 'NECO_IRS_2024.json', '4303e55cb8c5ff05c677cd6dcc9731bb21e85141d9e05f8594a99200d9c808ab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The treaty signed between the Muslims and the Quraysh in 628 CE was the Treaty of _____.', '["Madinah","Ta''if","Hudaibiyyah","Aqabah"]', 2, 'Hudaibiyyah was a peace treaty that led to a period of stability and eventually the peaceful conquest of Makkah.', NULL, 'NECO_IRS_2024.json', '1feadd957083f4487c2bf38926247aa9c147aa321041686e0c3e435d0614b210');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'A Hadith that has a broken chain of narrators is classified as _____.', '["Sahih","Hasan","Munqati''","Maudu''"]', 2, 'Munqati'' (broken) refers to a Hadith where one or more narrators are missing from the chain of transmission.', NULL, 'NECO_IRS_2024.json', '868bfa4dba25857b228dd336835968eeb256bc52c0cb5b4a42bd068fb7ba8927');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The Islamic term for the ''oneness of God'' is _____.', '["Iman","Tawhid","Ihsan","Salat"]', 1, 'Tawhid is the defining doctrine of Islam''s strict monotheism.', NULL, 'NECO_IRS_2024.json', 'a80012118e92946db168ffbb1cf9e167d3cc7f648e38e07f64409d99934e3e11');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''As-Sab'' al-Mathani'' mentioned in the Qur''an refers to _____.', '["The 7 Heavens","The 7 Verses of Al-Fatihah","The 7 major sins","The 7 gates of Hell"]', 1, 'Suratul-Fatihah is referred to as the seven oft-repeated verses because it is mandatory in every rak''ah of prayer.', NULL, 'NECO_IRS_2024.json', 'df85c180bf7338ad4d3c5d4000f5011cf9fe22b3afcf51bd3d69b47cdca34933');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The companion who was the father of Aishah (RA) was _____.', '["Umar","Uthman","Abu Bakr","Ali"]', 2, 'Abu Bakr As-Siddiq was the Prophet''s closest friend and father of his wife Aishah.', NULL, 'NECO_IRS_2024.json', '5e4428743048e85693c12e4690b0f62485b53b2b1c8b5da306097d61ea40bb6f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Hijab'' became mandatory for Muslim women in the _____ year after Hijrah.', '["2nd","5th","8th","10th"]', 1, 'Most historical accounts state that the verses regarding Hijab were revealed in the 5th year of AH.', NULL, 'NECO_IRS_2024.json', '5866c2fb9220a0c39fe63d5702d9604c1747389d56c79fe92658a0873a18c23a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Fara''id'' refers to _____ in Islam.', '["Voluntary prayers","Obligatory duties","Islamic art","Travel rules"]', 1, 'Fara''id (singular: Fard) are the mandatory acts commanded by Allah, such as the Five Pillars.', NULL, 'NECO_IRS_2024.json', '3cc061bc426eb7801ea610abd9565dcb290b817d635dbb9a7ab2b689a3a862f8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ruler of Abyssinia who protected the early Muslim migrants was _____.', '["Heraclius","Negus","Chosroes","Muqawqis"]', 1, 'The Negus (Najashi) was the Christian King of Abyssinia who provided refuge to Muslims fleeing Makkan persecution.', NULL, 'NECO_IRS_2024.json', 'dd55f63d2248f55fcc860a49c3f92fba63532ada77b2f0f157171b40e59d9b33');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The science of judging the character of Hadith narrators is _____.', '["Ilm al-Tafsir","Ilm al-Rijal","Ilm al-Tajwid","Ilm al-Fiqh"]', 1, 'Ilm al-Rijal (Science of Men) involves investigating the biographies and credibility of Hadith narrators.', NULL, 'NECO_IRS_2024.json', 'd0a2f7666733e8830174316644240b0d00adcf0fc2dca181351c4be53c3ee86d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Dower'' or Mahr belongs to _____.', '["The bride''s father","The bride only","The groom''s family","The mosque"]', 1, 'Mahr is the exclusive property of the bride, and neither her husband nor her parents can take it without her consent.', NULL, 'NECO_IRS_2024.json', '1fdaebbe6d02158be5cf3b388ef37b3d4504934686e0c5d952e585641a5d9058');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The ''Qiblatayn'' Mosque is significant because _____.', '["it is where the Prophet died","it is where the prayer direction changed","it is the first mosque built","it contains the Prophet''s grave"]', 1, 'Masjid al-Qiblatayn (Mosque of the Two Qiblahs) is where the revelation came to change the prayer direction from Jerusalem to Makkah.', NULL, 'NECO_IRS_2024.json', 'ca577f2125637f7b0d0a3e32c66ad3bb9bbe6792ba188f8578c0b4a82a45053d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The specific Zakat given before the Eid al-Fitr prayer is _____.', '["Zakat al-Mal","Zakat al-Fitr","Sadaqah","Ushr"]', 1, 'Zakat al-Fitr is a charitable obligation for every Muslim at the end of Ramadan to ensure the poor can celebrate Eid.', NULL, 'NECO_IRS_2024.json', '1e165664826353b382a00ee4957ab823042b1b551456f5c9a9027f87e5f9ebe8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'IRS', 2024, NULL, 'The companion who narrated the highest number of Hadiths was _____.', '["Abu Bakr","Abu Hurayrah","Ibn Umar","Aishah"]', 1, 'Abu Hurayrah (RA) spent years in close company with the Prophet specifically to learn and memorize his teachings.', NULL, 'NECO_IRS_2024.json', '5c50a8f867c7f6926764a1b66531be60547f94df53a9f8c4a58e56ee559d07aa');
