INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị bụ ọrụ kacha mkpa n’ala Igbo n’oge gboo dị ka passage si kwuo?', '["Ịzụ ahịa","Ọrụ ubi","Ịkụ azụ","Ịkpụ ígwè"]', 1, 'The first sentence of the passage states that farming (ọrụ ubi) was the most important work in Igboland in the past.', 'Ọrụ ubi bụ ọrụ kacha mkpa n’ala Igbo n’oge gboo. Onye anaghị arụ ọrụ ubi ka a na-ele anya ka onye umengwụ. Ihe e ji mara ndị nna anyị hà bụ ịkọ ji, n’ihi na ji bụ eze nri. E nwere ụdị ubi abụọ: ubi dị nso n’ụlọ na ubi dị n’ime ọhịa. Ndị mmadụ na-agba mbọ kọọ ọtụtụ nri ha ga-eri n’afọ niile. Taa, ụmụ ntorobịa anaghị enwe mmasị n’ọrụ ubi. Ha chere na ọ bụ ọrụ ndị ogbenye. Ma n’eziokwu, onye kọrọ nri agaghị enwe agụụ.', 'NECO_Igbo_2024.json', '05c4f101307536121948b68bcb3f0ea1269c17b437ba1b1bd26b77c38823f7ed');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee nri a na-akpọ ''eze nri'' n''ala Igbo?', '["Akpụ","Ọka","Ji","Raysi"]', 2, 'The passage identifies yam (ji) as the ''king of crops'' (eze nri).', 'Ọrụ ubi bụ ọrụ kacha mkpa n’ala Igbo n’oge gboo. Onye anaghị arụ ọrụ ubi ka a na-ele anya ka onye umengwụ. Ihe e ji mara ndị nna anyị hà bụ ịkọ ji, n’ihi na ji bụ eze nri. E nwere ụdị ubi abụọ: ubi dị nso n’ụlọ na ubi dị n’ime ọhịa. Ndị mmadụ na-agba mbọ kọọ ọtụtụ nri ha ga-eri n’afọ niile. Taa, ụmụ ntorobịa anaghị enwe mmasị n’ọrụ ubi. Ha chere na ọ bụ ọrụ ndị ogbenye. Ma n’eziokwu, onye kọrọ nri agaghị enwe agụụ.', 'NECO_Igbo_2024.json', 'c2e741e52e53ee1b9765e8c1874f2beb4bd7c05662261980446a2137167033a9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Kedu aha a na-akpọ onye anaghị arụ ọrụ ubi n''oge ahụ?', '["Onye ogbenye","Onye umengwụ","Onye amamihe","Onye kpuru ìsì"]', 1, 'The passage mentions that someone who doesn''t farm is looked upon as a lazy person (onye umengwụ).', 'Ọrụ ubi bụ ọrụ kacha mkpa n’ala Igbo n’oge gboo. Onye anaghị arụ ọrụ ubi ka a na-ele anya ka onye umengwụ. Ihe e ji mara ndị nna anyị hà bụ ịkọ ji, n’ihi na ji bụ eze nri. E nwere ụdị ubi abụọ: ubi dị nso n’ụlọ na ubi dị n’ime ọhịa. Ndị mmadụ na-agba mbọ kọọ ọtụtụ nri ha ga-eri n’afọ niile. Taa, ụmụ ntorobịa anaghị enwe mmasị n’ọrụ ubi. Ha chere na ọ bụ ọrụ ndị ogbenye. Ma n’eziokwu, onye kọrọ nri agaghị enwe agụụ.', 'NECO_Igbo_2024.json', '9ce99df7d8f25e843c0f83450100c51b3d4a109f59f4a117a281d1a5814aa8c0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị ka ụmụ ntorobịa nke oge a chere banyere ọrụ ubi?', '["Na ọ bụ ọrụ ndị ọgaranya","Na ọ bụ ọrụ ndị ogbenye","Na ọ bụ ọrụ kacha mma","Na ọ bụ ọrụ mmụọ"]', 1, 'The text states that modern youth think farming is a job for poor people.', 'Ọrụ ubi bụ ọrụ kacha mkpa n’ala Igbo n’oge gboo. Onye anaghị arụ ọrụ ubi ka a na-ele anya ka onye umengwụ. Ihe e ji mara ndị nna anyị hà bụ ịkọ ji, n’ihi na ji bụ eze nri. E nwere ụdị ubi abụọ: ubi dị nso n’ụlọ na ubi dị n’ime ọhịa. Ndị mmadụ na-agba mbọ kọọ ọtụtụ nri ha ga-eri n’afọ niile. Taa, ụmụ ntorobịa anaghị enwe mmasị n’ọrụ ubi. Ha chere na ọ bụ ọrụ ndị ogbenye. Ma n’eziokwu, onye kọrọ nri agaghị enwe agụụ.', 'NECO_Igbo_2024.json', '9a1087127b61c3ff4fffde92dee4185dd98828f04a16c5ac0ea6ff79a67c139c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee uru ịkọ nri bara dị ka passage si kọwaa?', '["Ịga mba ofesi","Agụụ agaghị agụ onye kọrọ nri","Ịzụta mọ́tò","Ịlụ nwaanyị"]', 1, 'The concluding sentence says that someone who grows food will not go hungry.', 'Ọrụ ubi bụ ọrụ kacha mkpa n’ala Igbo n’oge gboo. Onye anaghị arụ ọrụ ubi ka a na-ele anya ka onye umengwụ. Ihe e ji mara ndị nna anyị hà bụ ịkọ ji, n’ihi na ji bụ eze nri. E nwere ụdị ubi abụọ: ubi dị nso n’ụlọ na ubi dị n’ime ọhịa. Ndị mmadụ na-agba mbọ kọọ ọtụtụ nri ha ga-eri n’afọ niile. Taa, ụmụ ntorobịa anaghị enwe mmasị n’ọrụ ubi. Ha chere na ọ bụ ọrụ ndị ogbenye. Ma n’eziokwu, onye kọrọ nri agaghị enwe agụụ.', 'NECO_Igbo_2024.json', '59d5a855416ddb58b8bf95485d5397b54d5815cfb7f23c2992d8109fbf4236e8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Mkpụrụedemede asụsụ Igbo dị ole n''ọnụọgụ?', '["26","36","38","30"]', 1, 'The Standard Igbo alphabet (Abidịị) consists of 36 letters.', NULL, 'NECO_Igbo_2024.json', '736156292161f92d70d96f2142800ba0239e8d4e9960706484f273b9d9e2642b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee n''ime ndị a bụ udaume mfe (Light vowels)?', '["a, ị, ọ, ụ","e, i, o, u","a, e, i, o","ọ, ụ, i, u"]', 0, 'The light vowels in Igbo (Udaume mfe) are a, ị, ọ, and ụ.', NULL, 'NECO_Igbo_2024.json', '17d5f4d90eb1ccf0d4fa42daf7522b0bad1854cca3ddaf873f86f53ef55441e7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Udaume ole dị n''asụsụ Igbo?', '["Ise","Isii","Asatọ","Iri"]', 2, 'Igbo language has 8 vowels (udaume).', NULL, 'NECO_Igbo_2024.json', '5ffff5c97d81cfbb2f28e203662f05ce7585108e6a36c8a8e2e9ad2f669e5d7d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Mgbochiume ole dị n''asụsụ Igbo?', '["28","26","30","24"]', 0, 'Out of the 36 letters, 8 are vowels and 28 are consonants (mgbochiume).', NULL, 'NECO_Igbo_2024.json', 'e595667b6fa8f6c58359a9ef6925d029144dbf1f85977d150ad15efa33e9b03d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee mkpụrụedemede bụ myiriụda (Nasal consonant acting as a syllable)?', '["b, d","m, n","p, k","r, s"]', 1, '''m'' and ''n'' are nasal sounds that can function as syllables in Igbo words like ''mma'' or ''nna''.', NULL, 'NECO_Igbo_2024.json', 'fccbbce1cd2712d8d4ddfba05acde83bda05c8dde15156177b70cfccfc7758cd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Ahịrịokwu a ''Obi tiri mkpu'' nwere ụdị ngwaa wo?', '["Ngwaa nnyemaka","Ngwaa mbufe","Ngwaa amamihe","Ngwaa nkwadobe"]', 1, '''Tiri'' is a transitive verb (Ngwaa mbufe) because the action passes to the object ''mkpu''.', NULL, 'NECO_Igbo_2024.json', 'ce1d39c4449d4253fb251f3df55722022659e103012431820666f26b8f556238');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee akaraolu a na-eji egosi ''Low Tone'' n''asụsụ Igbo?', '["Akaraolu elu","Akaraolu ala","Akaraolu nsu","Akaraolu etiti"]', 1, 'The low tone is indicated by the grave accent mark (`) on the vowel.', NULL, 'NECO_Igbo_2024.json', '12e3e7bd3c4eec55f5f956fc56add502735c3c2085e695f59c641220715d6540');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Aha nkejiasụsụ na-akọwa aha bụ _____.', '["Ngwaa","Mgbakwunye","Nkọwa","Njikọ"]', 2, 'An adjective (Nkọwa) is a word that describes or qualifies a noun.', NULL, 'NECO_Igbo_2024.json', 'b06471df69c9735c50229433b413b44db2ec101739f0f8ac92ec20d9a899fbdb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Mgbakwunye na-abịa n''ihu ngwaa bụ _____.', '["Nsonazụ","Nsuru-ihu","Mbuụzọ","Ntinye"]', 2, 'A prefix is called ''Mbuụzọ'' because it comes at the beginning (ihu) of a word root.', NULL, 'NECO_Igbo_2024.json', '129a1db4bf7603a25812fb62c10aae212fef5d619b4ec3dec286729d9f0afd72');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Mkpụrụokwu ''Akwụkwọ'' nwere sillebu ole?', '["Abụọ","Anọ","Atọ","Ise"]', 2, 'A-kwụ-kwọ has three syllables.', NULL, 'NECO_Igbo_2024.json', '4f4c5feb9aaba692ed6616a1f19400cbe8c11314758a0e6a4dd2ab0fa533f9c9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'N''ahịrịokwu bụ ''Ada na-eri nri'', gịnị bụ ''na-''?', '["Ngwaa nnyemaka","Mbuụzọ","Isi ngwaa","Njikọ"]', 0, '''Na'' functions as an auxiliary/helping verb (Ngwaa nnyemaka) to show progressive action.', NULL, 'NECO_Igbo_2024.json', '53ddd089bb86d7a7633ea7e2e2d9e8c7058aea7e9cd971cd9bf139362119126b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee akara edemede a na-eji egosi nkwụsị oge na mkparịtaụka?', '["Kọma","Kọlọn","Ihuami","Akara ajụjụ"]', 0, 'A comma (kọma) indicates a short pause in a sentence.', NULL, 'NECO_Igbo_2024.json', '3d33eff02663b62ae0e925a0dc41f3e469b070653e94ba03f1a58bd4eeed5184');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Aha obodo bụ ''Enugwu'' dabara n''ụdị aha wo?', '["Aha nkịtị","Aha pụrụ iche","Aha mkpokọta","Aha njirimara"]', 1, 'Enugwu is a specific name of a place, so it is a proper noun (Aha pụrụ iche).', NULL, 'NECO_Igbo_2024.json', '1d89799f76a161f6bc4342aff5357944cff418d6ec13ba7e2cdfa00df231c884');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee mkpụrụasụsụ a kpọrọ ''Uda-anụ'' (Voiced Consonants)?', '["b, d, g","p, t, k","s, f, h","sh, c, x"]', 0, 'Voiced consonants like b, d, g cause vibration in the vocal cords when pronounced.', NULL, 'NECO_Igbo_2024.json', '0704f51914115b246ef90db579ec5a36ef5a77011fff532c74956d67a5e3dde1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Kpọọ aha nkejiasụsụ na-ejikọ mkpụrụokwu abụọ ọnụ.', '["Ngwaa","Njikọ","Nkọwa","Mbuụzọ"]', 1, 'A conjunction (Njikọ) links words or phrases together.', NULL, 'NECO_Igbo_2024.json', '1ca726c95f13543f8af1527d247a47625831f069003d38fce28fab65aa7ccaaf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'N''asụsụ Igbo, ''High tone'' anaghị enwe akara ọ bụla n''elu vowel. Eziokwu ka ọ bụ asị?', '["Asị","Eziokwu","O nweghị nke ọ bụ","Ụgha"]', 1, 'In Standard Igbo orthography, the high tone (Udaelu) is typically left unmarked.', NULL, 'NECO_Igbo_2024.json', '0f4d06c018852ee09afb844b6d9d5bbb40f626701d7a842974dfe71889a8bb5d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee nke bụ nnọchiaha (Pronoun) n''ime ndị a?', '["Rie","Ụlọ","Ha","Ọcha"]', 2, '''Ha'' (They) stands in for a noun, making it a pronoun.', NULL, 'NECO_Igbo_2024.json', '65e54f890e6ba16f5a9f4b4c3431bb2023a8889ff32eb06402f27c7b5973e52f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị bụ ''ụdaume mkpuchi'' (Heavy vowels)?', '["e, i, o, u","a, ị, ọ, ụ","b, d, f, g","m, n, p, k"]', 0, 'The heavy vowels (udaume mkpuchi/arọ) are e, i, o, and u.', NULL, 'NECO_Igbo_2024.json', '4658a21cd9a194d895f564b6405d9c62f11b2c3ca39d1209de1902913e2f2234');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Ahịrịokwu a ''Bịa ebe a!'' bụ ụdị wo?', '["Nkwupụta","Iwu","Ajụjụ","Mkpu"]', 1, 'This is an imperative/command sentence (Ahịrịokwu iwu).', NULL, 'NECO_Igbo_2024.json', '0aef3372fcb42d532f2efc0c8be431bd582e6063a37e27a5692a321749ff7aa6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Onye na-akpụ isi bụ onye _____.', '["Ọkụ azụ","Onye isi","Onye na-akpụ isi","Onye ọrụ ubi"]', 2, 'In Igbo grammar, the person who cuts hair is simply ''onye na-akpụ isi''.', NULL, 'NECO_Igbo_2024.json', '951aeb15a5c45c2f5b1e892ef8d177a4031a1e22194580050d6425dce0a437a1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị ka a na-akpọ nwa mụrụ n''ụbọchị ''Eke''?', '["Mgbeke","Mgborie","Mgbafor","Mgbeafọ"]', 0, 'A female child born on Eke market day is named Mgbeke.', NULL, 'NECO_Igbo_2024.json', 'e5c203035e83beb2c8e966efa86cc8b92f108dd4b95b30b340d64fdd5c2d2d93');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Udaolu ole dị n''asụsụ Igbo?', '["Abụọ","Atọ","Anọ","Ise"]', 1, 'Igbo has three tones: High (Elu), Low (Ala), and Mid/Downstep (Nsu).', NULL, 'NECO_Igbo_2024.json', '2d3f9d48a225443df7d00a0cea7381e76e22d8ed3c7f9f8e6dcd2e365c94a1b2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Mkpụrụokwu ''Mmanwụ'' nwere mkpụrụedemede ole?', '["Isii","Ise","Asaa","Anọ"]', 0, 'M-m-a-n-w-ụ consists of 6 letters in the Igbo alphabet (note: double letters like ''nw'' are one letter).', NULL, 'NECO_Igbo_2024.json', 'fe71237ac76ceebbdf32a2e85ff0939be3edf5bf35cc5310967591f0cc3eaf18');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Kpọọ ngwaa dị n''ahịrịokwu a: ''Nne siri nri''.', '["Nne","Siri","Nri","Ọ nweghị"]', 1, '''Siri'' (cooked) is the verb or action word.', NULL, 'NECO_Igbo_2024.json', '356d6bd0345e2aede9538a6ed2a4c88619d99a92b1b9d39c21dde3368fa58ffc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị bụ nsonazụ n''ime mkpụrụokwu ''Rie''?', '["R","i","e","ri"]', 2, '''e'' is the suffix (nsonazụ) added to the root ''ri''.', NULL, 'NECO_Igbo_2024.json', '00e94d6dade2392a1eaab2abfa865b28c57692b38704465263e02874b3322aab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee nke bụ ''mgbochiume kpachịrị akpachị'' (Digraph)?', '["b","gb","d","f"]', 1, '''gb'' consists of two characters representing one sound, which is a digraph.', NULL, 'NECO_Igbo_2024.json', 'cdd352c9dea81944972a5ba03292656af9c0b60a6afd31ef6164f32361969a5c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Ụdị aha ''Nwa'' bụ _____.', '["Aha nkịtị","Aha pụrụ iche","Aha mkpokọta","Aha amamihe"]', 0, '''Nwa'' (child) is a common noun (aha nkịtị).', NULL, 'NECO_Igbo_2024.json', '8de9a1efc0e415834a03723be102a96829fb71f7e29d67eef07fb22c0048c989');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Ihe na-abịa n''ihu ngwaa iji mepụta ajụjụ bụ _____.', '["Njikọ","Njirimara","Mbuụzọ ''ọ̀'' ma ọ bụ ''ì''","Nsonazụ"]', 2, 'Prefixes like ''ọ̀'' (e.g., ọ̀ riri?) are used to create questions.', NULL, 'NECO_Igbo_2024.json', 'f5fa38da260ddade7c9aa7eb12937a7fd6d2c7b69eaba816c220e0da7913753a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Asụsụ Igbo gụnyere ''Udamkpọ'' (Vowel Harmony). Gịnị ka ọ pụtara?', '["Ịgụ egwu","Udaume ịbịa n''ìgwè abụọ dị iche","Mkpọtụ","Ịgba mgba"]', 1, 'Vowel harmony means that vowels in a word are usually from the same group (Light or Heavy).', NULL, 'NECO_Igbo_2024.json', 'bae2ff534efe4d1d9faeb075756645567e01c9c5b36c08a3968ad2f77f6c86e6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee onye dere akwụkwọ ''Omenụkọ''?', '["Tony Ubesie","F.C. Ogbalu","Pita Nwana","Chinua Achebe"]', 2, 'Pita Nwana wrote the first Igbo novel, ''Omenụkọ''.', NULL, 'NECO_Igbo_2024.json', 'e34e3ff7cdb0d6e1a603885b2f89d9fdc6480bc48609bddf1461c460fb14ec4a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị bụ ''Mbem''?', '["Abụ","Akụkọ","Egwuregwu","Ilu"]', 0, 'Mbem is a form of oral poetry or chant.', NULL, 'NECO_Igbo_2024.json', 'a234003ee40f40f2fdd9a504a2ff724527ef47f76337e90a23a2c1602d30e8d5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee anụmanụ a maara dị ka onye aghụghọ n''akụkọ ifo Igbo?', '["Agu","Atụrụ","Mbe","Enyi"]', 2, 'The Tortoise (Mbe) is the archetypal trickster in Igbo folktales.', NULL, 'NECO_Igbo_2024.json', '5a4523b47760832726991e6487a2a8e83623a0cf3a0ccf46b755dade2b3323ac');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Kammala ilu a: ''Gidi gidi bụ _____.''', '["Mma nwaanyị","Ugwu eze","Ike nwoke","Agụmakwụkwọ"]', 1, 'The proverb is ''Gidi gidi bụ ugwu eze'', meaning unity/strenuous effort brings honor.', NULL, 'NECO_Igbo_2024.json', 'd74f7460706dd36577f09272fd780b9ee8b7e8233d799838dbd6193252a4bdad');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị ka a na-akpọ ''Agụmagụ a kpara akpa''?', '["Mbem","Ilu","Agụmagụ edere ede","Akụkọ ifo"]', 2, '''Agụmagụ a kpara akpa'' refers to creative written literature.', NULL, 'NECO_Igbo_2024.json', '257b604b2f6026615cf44d4b66eef21b441ff86604e9f5b66417300c4df0bb83');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee onye dere akwụkwọ ''Isi Akwu Dara n''Ala''?', '["Tony Ubesie","Chinedu Ofomata","Tagbo Nzeako","F.C. Ogbalu"]', 0, 'Tony Ubesie is the author of this classic novel set during the Biafran war.', NULL, 'NECO_Igbo_2024.json', 'cb6d34663043a14ad6d88077ab3aad63b8f27a09a42f557813c53061cf38c4d9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị bụ ''Figure of Speech'' maka ''Personification'' n''Igbo?', '["Mburu","Nnyemmadụ","Nkwuaha","Myiri"]', 1, 'Nnyemmadụ (Personification) gives human qualities to non-human entities.', NULL, 'NECO_Igbo_2024.json', 'd207aa19d01d70daef5dc3de13ef41d499b42ff06fc45113cb14a479353abc44');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Onye bụ nna asụsụ Igbo nke oge a?', '["Chinua Achebe","F.C. Ogbalu","Cyprian Ekwensi","Olaudah Equiano"]', 1, 'F.C. Ogbalu is widely regarded as the promoter/father of modern Igbo studies.', NULL, 'NECO_Igbo_2024.json', '43f9e072889dadf83cc138295fa7ff05314a6766e5a3440cde8cd9631fd8f068');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Kedu nke bụ ''Agụmagụ ọnụ''?', '["Novel","Drama","Ilu na Akụkọ ifo","Edemede"]', 2, 'Proverbs and folktales are transmitted orally, hence ''Agụmagụ ọnụ''.', NULL, 'NECO_Igbo_2024.json', 'addcfb9d25f49bff0291446fdb1e313a592274a61cfc63f9d676dec9d35d7c44');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị bụ isiokwu ''Mbem''?', '["Ndọrọndọrọ","Otito na Ọ̀fọ̀","Ego","Njem"]', 1, 'Mbem usually focuses on praise (Otito), history, or prayers/incantations (Ọfọ).', NULL, 'NECO_Igbo_2024.json', '54b77f2da8dcf44a78ab3fd7f29cf66c0f96f93eab50c33d089556474e8cd233');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị bụ ''Ilu''?', '["Abụ","Mmanụ e ji eri okwu","Egwuregwu","Nri"]', 1, 'According to Chinua Achebe, proverbs (ilu) are the palm oil with which words are eaten.', NULL, 'NECO_Igbo_2024.json', '1eb411a410ea03d7446838d06fefdfbaa15a96a934e40696b6c7644aaae80a7b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee ụdị akụkọ na-ezi ezigbo omume ma jiri anụmanụ kọwaa ya?', '["Akụkọ ifo","Akụkọ ihe mere eme","Akụkọ amamihe","Novel"]', 0, 'Folktales (Akụkọ ifo) use personified animals to teach moral lessons.', NULL, 'NECO_Igbo_2024.json', 'b292e5c3e2b4272307ec0bab5d651fd6df1b255521df8c812a943be671a43c0f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Kammala ilu a: ''Onye kwe, _____.''', '["Chi ya ekwe","Mmadụ ekwe","Ego ekwe","Agụ ekwe"]', 0, 'The proverb is ''Onye kwe, Chi ya ekwe'', meaning if you believe, your personal god will support you.', NULL, 'NECO_Igbo_2024.json', 'a06b18486815e230025f4b26a3a8dc76a19639daf58a40c57f93acd1b0fb66d1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị bụ ''Metaphor'' n''asụsụ Igbo?', '["Nnyemmadụ","Mburu","Myiri","Nkwuaha"]', 1, 'Mburu is a direct comparison (metaphor) in Igbo literature.', NULL, 'NECO_Igbo_2024.json', '9ab064e532da463c2370ddecd91573601d821640966ae47dfdd6b12962a23b4e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee akwụkwọ e ji amata ụdị agụmagụ ''Novel''?', '["Omenụkọ","Obi nwaanyị","Isi akwu","Ha niile"]', 3, 'All listed are examples of Igbo novels.', NULL, 'NECO_Igbo_2024.json', 'c693a4fac42b9572630d22a6e60a65dc18c2d21274bb5e8b7f64a47ad68f2198');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị bụ ''Irony'' n''asụsụ Igbo?', '["Nkwuọtọ","Mburu","Nnyemmadụ","Myiri"]', 0, 'Nkwuọtọ is the literary term for irony.', NULL, 'NECO_Igbo_2024.json', '1be3f198f26f5640ab1cef296166d0953cce8a140e6fcbe8cbd25beadf5a5618');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Agụmagụ ''Egwuregwu'' bụ _____.', '["Poetry","Drama","Prose","Mbem"]', 1, '''Egwuregwu'' refers to plays or drama meant for performance.', NULL, 'NECO_Igbo_2024.json', '8b9a665aeaffd6f4188a218c391981c4ba17ca50aca572b0e2e57b2a6c400a7f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee onye dere akwụkwọ ''Juọ Obinna''?', '["Tony Ubesie","J.U.T Nzeako","Tony Nduka","F.C. Ogbalu"]', 0, 'Tony Ubesie wrote ''Juọ Obinna'', another famous novel about the civil war.', NULL, 'NECO_Igbo_2024.json', 'f11e328c4c8996d4f169f5f6b05c28af1d76b6ddab4f5f7f7bb83009b53ded57');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee nke kacha mkpa n''ịlụ nwaanyị n''ala Igbo?', '["Ịzụta mọ́tò","Ịjụ ajụjụ","Ịgba egwu","Ịnọ na Lagos"]', 1, 'The inquiry/knocking (''Ịjụ ajụjụ'') is the essential first step in Igbo marriage.', NULL, 'NECO_Igbo_2024.json', '4ce2997f4ae89ca39a70a45d2167b37630701cc4593651e90964fc1404cbc415');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị bụ ''Ọmụgwọ''?', '["Ịgba mgba","Nleta onye mụrụ nwa ọhụrụ","Ịkpụ ígwè","Ịzụ ahịa"]', 1, 'Ọmụgwọ is the traditional postpartum care given to a new mother by her mother or a relative.', NULL, 'NECO_Igbo_2024.json', '028e7b8eb4d0202b62cbd144cbed56a51236c460d7e30527ac08b274a8864da0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Mmadụ ole na-alụ di na nwunye n''ala Igbo n''oge gboo?', '["Otu nwoke na otu nwanyị nani","Ịlụ karịa otu nwanyị","Ịlụ karịa otu nwoke","O nweghị"]', 1, 'Historically, polygamy (ịlụ karịa otu nwaanyị) was common and often a sign of wealth/status.', NULL, 'NECO_Igbo_2024.json', 'ba984684f2a4de215bd48d60a9a83ef0a76d02a0e39487a7a299a5d60adefeaf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị bụ ''Ego nwaanyị''?', '["Ego e ji azụta ya","Ihe nnọchiteanya njikọ ezinụlọ","Ego ohi","O nweghị uru"]', 1, 'Bride price is a symbolic token establishing the legal bond between families.', NULL, 'NECO_Igbo_2024.json', '5d325def3d162ff0174de1da479cf2b955246db103dff3384ff1aee4338a3442');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Kedu onye bụ onyeisi n''ezinụlọ n''ala Igbo?', '["Nne","Nwa mbụ","Nna","Onye agbata obi"]', 2, 'The father (nna) is the traditional head of the household.', NULL, 'NECO_Igbo_2024.json', '738a06d8b6331314cdc12943db72981a62ff84b5037fd1d7d11771215cb9061f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Mkpụrụ ji ole a tọrọ n''ụdọ ka a na-akpọ _____?', '["Oba","Ji","Ekwe","Ubi"]', 0, 'A barn where yams are tied is called ''Oba''.', NULL, 'NECO_Igbo_2024.json', 'a3934c859807428d13014bcb66aa1fdf92db38828157c8a4f22a9dd7aac8f157');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee ememme a na-eme tupu e rie ji ọhụrụ?', '["Ịwa ji","Ịma mmanwu","Ịgba mgba","Iru mgbede"]', 0, 'New Yam Festival (Ịwa ji/Iri ji) is done to thank the gods for a successful harvest.', NULL, 'NECO_Igbo_2024.json', '2d36a2b7658abc25a11e20433cdd655de5c9f265f53cee2b1fc9b4b0aaf336c8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị ka a na-eji amata onye nwere echichi ''Ozo''?', '["Ego","Okpu mme mme na mpị nzu","Mọ́tò","Uwe ọcha"]', 1, 'Ozo titled men are known by their red caps and elephant tusks.', NULL, 'NECO_Igbo_2024.json', '61208ffcdc4c5bb6c4a2ab025c8b92bcd9005c869bfb2650863c45bea69ca6f5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Asụsụ Igbo nwere ụbọchị ahịa ole?', '["Ise","Isii","Anọ","Asaa"]', 2, 'The Igbo calendar revolves around four market days: Eke, Orie, Afo, and Nkwo.', NULL, 'NECO_Igbo_2024.json', '8761fd05c51eac18147927e832a235e1ace4349a67541e14ef16c2b27b56ae67');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Onye na-ele anya n''ọdịnihu site n''ịgba afa bụ _____.', '["Dibia afa","Dibia ogwu","Onye uwe ojii","Onye nkụzi"]', 0, 'A diviner is known as ''Dibia afa''.', NULL, 'NECO_Igbo_2024.json', 'bba6e4c6bab1a0d58277d0b574221e627b7e985880a985049fef3b1aed9c00ef');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị bụ ''Ikwa ozu''?', '["Ịkwa akwa","Ememme olili onye nwụrụ anwụ","Ịkpụ isi","Ịzụta ozu"]', 1, '''Ikwa ozu'' refers to funeral rites performed to honor the deceased.', NULL, 'NECO_Igbo_2024.json', '4d854e67ac3ebe7243b25a2d63405b8139aac457343a29d99afef411a1369536');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Onye bụ ''Diọpara''?', '["Nwa mbụ nwoke","Nwa ikpeazụ","Nna","Eze"]', 0, 'The first-born son is called Diọpara (or Opwara).', NULL, 'NECO_Igbo_2024.json', 'e75a26521e239090c45174f6858b2925cac44ef36a6467eda6e83a2b7104816a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Olee aha a na-akpọ nwa mbụ nwaanyị mụrụ n''ezinụlọ?', '["Ada","Nwa","Mgbeke","Diọkpa"]', 0, 'The first-born daughter is known as ''Ada''.', NULL, 'NECO_Igbo_2024.json', '750fc8d8768be108c53a1759db794a747a4edfb898888cb6b549df13686213f4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Ịlụ nwanyị n''ala Igbo na-amalite site n''ikụ aka n''ọnụ ụzọ nke a kpọrọ _____.', '["Ịjụ ajụjụ","Ịda ogo","Ịgba nnụkwụ","Ịkpụ isi"]', 0, 'The formal introduction/inquiry is called ''Ịjụ ajụjụ''.', NULL, 'NECO_Igbo_2024.json', '7128348ec00ee79878a796815ff1f2044002be503e8b49b81a935c7c9bda8597');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị ka ''Oji'' na-anọchite anya ya n''ala Igbo?', '["Nnabata na udo","Ịda ogbenye","Ịnwụ anwụ","Ịrụ ọrụ"]', 0, 'Kola nut (Oji) is the ultimate symbol of welcome and peace.', NULL, 'NECO_Igbo_2024.json', 'b1f0f5cfc3c3e5d6b2078f7a496db32467fefba976f4325e6322e4df069a4a59');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Onye na-akpụ ígwè bụ _____.', '["Onye isi","Onye ubi","Onye òkpụ","Onye ọkụ azụ"]', 2, 'A blacksmith is called ''Onye òkpụ ígwè''.', NULL, 'NECO_Igbo_2024.json', '497a0c582297d74a161db3fb50de5a4b06900752b6197ee9128267272e69ae58');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Ịgba mgba n''ala Igbo bụ _____.', '["Iji egbe alụ ọgụ","Egwuregwu ike n''etiti ndị nwoke","Ịzụ ahịa","Ịkpa nkata"]', 1, 'Traditional wrestling (Ịgba mgba) is a sport used to test strength.', NULL, 'NECO_Igbo_2024.json', 'b005aa51f339002bb016ec9dcada00210c0a25807fccfb89860d34f32fa26e26');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Gịnị bụ uru ''Ịmụ ọrụ'' (Apprenticeship)?', '["Ịbụ onye ohi","Ịmụta aka ọrụ na inwe onwe","Ịmụ nwa","Ịga ụlọ akwụkwọ nani"]', 1, 'The apprenticeship system helps youth learn trades and become independent.', NULL, 'NECO_Igbo_2024.json', 'c16bd5d739b4071038eed9c7852dfe87e3f97b3c43f1a5262cc052791d150cbc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'N''ala Igbo, ''Iru mgbede'' bụ ememme a na-emere _____.', '["Ndị agadi","Ụmụ agbọghọ na-akwado ịlụ di","Ndị agha","Ndị ohi"]', 1, '''Iru mgbede'' was a rite of passage for young women entering adulthood/marriage.', NULL, 'NECO_Igbo_2024.json', '6ba4ff251fe643be9dc99a4de2d7de7d1613d965a598626089b0efe69e489b53');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Igbo', 2024, NULL, 'Kedu onye n''obodo na-ahụ maka ikpe ikpe na idozi okwu?', '["Ndị ntorobịa","Ndị Nze na Ọzo na ndị okenye","Ụmụaka","Onye ọbịa"]', 1, 'Titled men and elders (Oha na Eze/Ndi Ichie) handle conflict resolution.', NULL, 'NECO_Igbo_2024.json', 'eeed9f41815777c8576ff77e5d2f9ad1f8cf4404e21419164979208cd603a1d1');
