INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The use of an exaggeration for emphasis or heightened effect is known as _____.', '["Hyperbole","Litotes","Metaphor","Euphemism"]', 0, 'Hyperbole is a figure of speech that uses extreme exaggeration to make a point or show emphasis, such as ''I''ve told you a million times''.', NULL, 'NECO_Literature_2024.json', '5d2abe741e36629f733bfa4144c06a36c21ea321d239cd71870a102705bc202a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'A speech directed to the audience which the other characters on stage are not supposed to hear is a/an _____.', '["Soliloquy","Monologue","Aside","Epilogue"]', 2, 'An aside is a short comment or speech that a character delivers directly to the audience, or to himself, while other actors on the stage appear unable to hear it.', NULL, 'NECO_Literature_2024.json', 'd137242fb8c6e790eab869ccd80e550e45385c44b8dea3e0566c9d7539b51ebc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The continuation of a sentence without a pause beyond the end of a line, couplet, or stanza in poetry is called _____.', '["Caesura","Enjambment","Assonance","Alliteration"]', 1, 'Enjambment (or run-on line) is when a sentence continues into the next line of poetry without a terminal punctuation mark.', NULL, 'NECO_Literature_2024.json', '30daaf8c12d1e61e37eda833e641c888919762ae62b74a02bc4ecafc009ee7cb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'A literary work that ridicules human folly or vice with the aim of correcting it is a _____.', '["Comedy","Farce","Satire","Tragedy"]', 2, 'Satire uses humor, irony, and ridicule to expose and criticize people''s stupidity or vices, particularly in the context of contemporary politics and other topical issues.', NULL, 'NECO_Literature_2024.json', '08df0b087d33906b00706cd244ae2a22bfddd57c0df9f60ec769e3f3db1777df');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Buchi Emecheta''s Second Class Citizen, the protagonist Adah is determined to travel to _____.', '["The United States","The United Kingdom","Canada","Germany"]', 1, 'The novel follows Adah''s journey from Nigeria to London, United Kingdom, in search of better opportunities and education.', NULL, 'NECO_Literature_2024.json', '3058a4d6e3553126091f036d7211309c7caa6d96d5582b1c122a030c13ce21df');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Unexpected Joy at Dawn, Nii Tackie is a citizen of _____.', '["Nigeria","Ghana","Sierra Leone","Liberia"]', 1, 'Nii Tackie is a Ghanaian who faces identity issues and displacement during the era of the Alien Compliance Order in Nigeria and the subsequent expulsion of Nigerians from Ghana.', NULL, 'NECO_Literature_2024.json', 'aa7268711989f0130340e9c873d26ebbf89bb8179280b2189ef3a1c3eaeb7add');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The ''Jewel'' in Wole Soyinka''s The Lion and the Jewel refers to _____.', '["Sadiku","Sidi","The Bale''s wife","The Photographer''s camera"]', 1, 'Sidi is the village belle and the ''Jewel'' of Ilujinle, whose beauty attracts both the modern teacher Lakunle and the traditional ruler Baroka.', NULL, 'NECO_Literature_2024.json', '8855ee3dc286a33e39e819071f3955a259f883e7b02d0b7641d3edf0d1639e4f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Look Back in Anger, Jimmy Porter plays the _____ to express his frustration.', '["Piano","Guitar","Trumpet","Violin"]', 2, 'Jimmy Porter''s trumpet playing is an auditory symbol of his noisy, disruptive, and rebellious nature against the middle-class establishment.', NULL, 'NECO_Literature_2024.json', 'c2073dd65930a6ce79038c934aaf4f55ed469eb432ddbf52564717df49aa4f22');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'Identify the figure of speech in: ''The waves danced on the shore''.', '["Simile","Metaphor","Personification","Oxymoron"]', 2, 'Personification attributes human qualities (dancing) to non-human things (waves).', NULL, 'NECO_Literature_2024.json', '04362b5a01bb8bd75f44f4cef9b7dec70aa2c44f9caa99f7600b62ca94214c96');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'A poem that laments the death of a particular person is a/an _____.', '["Ode","Elegy","Ballad","Limerick"]', 1, 'An elegy is a mournful, melancholic, or plaintive poem, especially a funeral song or a lament for the dead.', NULL, 'NECO_Literature_2024.json', '0219f74c5f0a734d4a332acda8ef86c6338067c54d4b948a41de6b99e2602bf5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Emily Brontë''s Wuthering Heights, Heathcliff''s primary motivation for his actions is _____.', '["Greed","Ambition","Revenge","Patriotism"]', 2, 'Heathcliff spends much of the novel seeking revenge against Hindley Earnshaw and Edgar Linton for the humiliations he suffered and for his separation from Catherine.', NULL, 'NECO_Literature_2024.json', 'fdf7430cc17f5faae67b548dc3548863a471dd7177c3cc912a02f9878e95f27d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Fences, Troy Maxson is a former _____ player who feels cheated by the system.', '["Basketball","Football","Baseball","Boxing"]', 2, 'Troy Maxson was a talented baseball player in the Negro Leagues but was too old to join Major League Baseball when it finally integrated.', NULL, 'NECO_Literature_2024.json', '755e65b698580323ca8b96dd274a22b0f0c4a93d116053222b39a2a4155af89b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The substitution of an offensive term with a mild or indirect one is _____.', '["Irony","Paradox","Euphemism","Sarcasm"]', 2, 'Euphemism is used to make a harsh reality seem more pleasant, such as saying ''passed away'' instead of ''died''.', NULL, 'NECO_Literature_2024.json', '1bb861f5820403e644971622db632d02f6dc36a09f4a750befe121073e9dee72');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In The Lion and the Jewel, Lakunle represents _____.', '["Traditional Yoruba values","A bridge between old and new","Superficial Western modernization","Military authority"]', 2, 'Lakunle is a schoolteacher who clumsily adopts Western ideas and speech, often appearing ridiculous to the villagers.', NULL, 'NECO_Literature_2024.json', 'fc39b71501b1dffb7b98fcd49f7baaeb320b5b28357c6d6e399a2c9d08ee4efe');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'A fourteen-line poem written in iambic pentameter is a _____.', '["Sestina","Sonnet","Villanelle","Haiku"]', 1, 'A sonnet is a fixed verse form of 14 lines, following a specific rhyme scheme and meter (usually iambic pentameter).', NULL, 'NECO_Literature_2024.json', '2f36ba90a1ad250f79d06fec10e27c826c5eb3fc9bd964ddc0a3ee9e9b57949f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Second Class Citizen, Francis is Adah''s _____.', '["Brother","Father","Husband","Employer"]', 2, 'Francis is Adah''s husband in London, who often behaves abusively and tries to suppress her ambitions.', NULL, 'NECO_Literature_2024.json', 'aaa6d3554599eb501fb166dae21ff732d9e8e1b098a5afc5ff5b794ecae824da');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The character who provides a contrast to the protagonist is known as a _____.', '["Hero","Foil","Villain","Confidant"]', 1, 'A foil is a character whose qualities or actions serve to emphasize those of the protagonist (the main character) by providing a strong contrast.', NULL, 'NECO_Literature_2024.json', '1527f0ec7b63b6d48ec769d948a991cf027d85c11fbb113082dfe305eb100e4b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Unexpected Joy at Dawn, the ''Alien Compliance Order'' led to the expulsion of _____ from Ghana.', '["Europeans","Nigerians","Indians","Americans"]', 1, 'The novel centers on the forced mass exodus of Nigerians from Ghana and vice-versa due to government policies.', NULL, 'NECO_Literature_2024.json', '50638728df100b8919c39ee2a2f19ef8cb7f65e6db46e44df4a6af2a3c887e6f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The resolution of the plot in a story or play is called the _____.', '["Climax","Exposition","Denouement","Conflict"]', 2, 'Denouement is the final part of a narrative in which the strands of the plot are drawn together and matters are explained or resolved.', NULL, 'NECO_Literature_2024.json', 'fb3c74658737ee26bfb2947221521e7021fea9fe2c6b6fbc83032952483df222');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The passage is from Ralph Ellison''s _____.', '["Wuthering Heights","Invisible Man","Fences","Second Class Citizen"]', 1, 'This is the iconic opening passage of Ralph Ellison''s novel Invisible Man.', 'He was an invisible man. No, he was not a spook like those who haunted Edgar Allan Poe; nor was he one of your Hollywood-movie ectoplasms. He was a man of substance, of flesh and bone, fiber and liquids - and he might even be said to possess a mind. He was invisible, understand, simply because people refused to see him.', 'NECO_Literature_2024.json', '2b618ff66df7cc5cec526e0d85861ca23832a0af668d8afce0f8756b252377b8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'According to the passage, the narrator''s ''invisibility'' is _____.', '["Biological","Supernatural","Social and psychological","Scientific"]', 2, 'The text states he is invisible ''because people refused to see him'', implying that racial prejudice makes him socially invisible despite his physical presence.', 'He was an invisible man. No, he was not a spook like those who haunted Edgar Allan Poe; nor was he one of your Hollywood-movie ectoplasms. He was a man of substance, of flesh and bone, fiber and liquids - and he might even be said to possess a mind. He was invisible, understand, simply because people refused to see him.', 'NECO_Literature_2024.json', 'be8555c1955df7a91c368edd528f38d873fe54dfd2c4d6d1dbe1cbfa1bf8f366');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The repetition of consonant sounds at the beginning of words is _____.', '["Assonance","Onomatopoeia","Alliteration","Pun"]', 2, 'Alliteration is the occurrence of the same letter or sound at the beginning of adjacent or closely connected words.', NULL, 'NECO_Literature_2024.json', 'e959a8e2bd0590975f4355ec13604aae22d2bed504e7ee005330637dc0d79b20');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Look Back in Anger, Alison''s father, Colonel Redfern, represents _____.', '["The working class","The ''Angry Young Men''","The fading British Empire","The industrial revolution"]', 2, 'Colonel Redfern represents the Edwardian era and the nostalgia for the prestige of the British Empire, which contrasts with Jimmy''s disillusionment.', NULL, 'NECO_Literature_2024.json', '51936c1e82f8b23cb148d99c842f514d55f4b5203da44c83af4f15b342aeb0be');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'A story in which animals are used as characters to teach a moral lesson is a _____.', '["Legend","Myth","Fable","Epic"]', 2, 'A fable (like Aesop''s Fables) is a short story that features animals, plants, or forces of nature which are anthropomorphized to deliver a moral truth.', NULL, 'NECO_Literature_2024.json', '08ae9967d24cccfd82140f1bf1e93693ade5725b3aa3825f0072ff3f212cadef');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Let Me Die Alone, Queen Yoko is the ruler of the _____ people.', '["Mende","Yoruba","Asante","Zulu"]', 0, 'Queen Yoko was a historical and literary figure who ruled the Senehun of the Mende people in Sierra Leone.', NULL, 'NECO_Literature_2024.json', '186dcf1752353f1a9940b5752303aa0704d329e8f777d69e9b91c545fef8047e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The term ''In Media Res'' means starting a story _____.', '["At the beginning","At the end","In the middle of the action","With a flashback"]', 2, 'Latin for ''in the midst of things'', this technique opens a narrative in the middle of the plot rather than at the chronological beginning.', NULL, 'NECO_Literature_2024.json', '6c34acabfb7efcd73469ff22e1222863684ef707dc7e23766e79fb638a3394c9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Fences, Rose Maxson''s primary role in the family is that of a _____.', '["Breadwinner","Nurturer and stabilizer","Rebel","Teacher"]', 1, 'Rose is the glue that holds the Maxson family together, providing emotional support and trying to mediate between Troy and their son Cory.', NULL, 'NECO_Literature_2024.json', '5a7814db4381a33a38e9dd09e7bf4448fb053592ebf7778d7298088214cff942');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'A play that is light and humorous and usually has a happy ending is a _____.', '["Melodrama","Comedy","Tragedy","Farce"]', 1, 'Comedy, in the classical sense, is a genre of drama that is intended to amuse and usually ends in a positive resolution (like a marriage).', NULL, 'NECO_Literature_2024.json', '22ae8e14a8361f32ba45ef5ee3871bf618a8833e388e7ff7bfee06aa4870498a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In ''The Leader and the Led'' by Niyi Osundare, the animals represent _____.', '["Nature","Human political leaders and followers","The circle of life","Religious deities"]', 1, 'The poem uses various animals (Lion, Antelope, Hyena) as a satire to explore the qualities required for leadership in a human society.', NULL, 'NECO_Literature_2024.json', 'ddb1b842e7aaaa63992de3f4c6de9e37b814109f055d0d0b904812f09784ca19');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The main theme of John Donne''s ''The Good-Morrow'' is _____.', '["Death","The spiritual and physical awakening of love","War","Loneliness"]', 1, 'This metaphysical poem celebrates the transition from the ''childish'' pleasures of the world to the mature, all-encompassing love shared by two people.', NULL, 'NECO_Literature_2024.json', 'b757f6a0819494c1f7417983a0f766107ab5ba23359128874abfc61d6692272d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The part of a play that introduces the characters and the setting is the _____.', '["Climax","Rising action","Exposition","Falling action"]', 2, 'Exposition is the introductory part of a story where the author provides background information about the characters, setting, and basic situation.', NULL, 'NECO_Literature_2024.json', 'c515ba919f6aaae9a1b08c506249242af6f30f5f5190db2b197139f78ce4e0d0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Wuthering Heights, the contrast between the two houses represents _____.', '["Wealth and poverty","Nature vs. Culture (Passion vs. Civilized restraint)","North and South","Old and Young"]', 1, 'Wuthering Heights represents wild passion and nature, while Thrushcross Grange represents social order, civilization, and restraint.', NULL, 'NECO_Literature_2024.json', 'dd410c8f209fc96ed947b25eecec2ded39b17f942bc88fa6595cd3a34b7b05ca');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'Identify the device in: ''Parting is such sweet sorrow''.', '["Hyperbole","Oxymoron","Litotes","Simile"]', 1, 'An oxymoron combines two contradictory terms (''sweet'' and ''sorrow'') to create a paradoxical effect.', NULL, 'NECO_Literature_2024.json', '22881659e8edb6a42cf5c3b431c015900266ea1a7f9c4ff612d6c6fe24fa3a1c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Let Me Die Alone, Yoko''s decision to commit suicide is a result of _____.', '["Fear of the enemy","Betrayal and the loss of her honor","Economic hardship","Lack of children"]', 1, 'Queen Yoko chooses death after being falsely accused of a crime and realizing the deep treachery of those around her, including her own relatives.', NULL, 'NECO_Literature_2024.json', 'cc632903eff8c260d1e1edd70916177295102ea9c2a0f543cea1490e657bfb4c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The ''persona'' in a poem refers to the _____.', '["Author","Speaker","Audience","Antagonist"]', 1, 'The persona is the character or ''voice'' assumed by the poet to speak the poem, which may or may not be the poet''s own voice.', NULL, 'NECO_Literature_2024.json', '99623845605a3d4b89ec79bc7b4134523b08494d8be578e3f26a13c15f56aa80');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Invisible Man, the ''Battle Royal'' symbolizes _____.', '["A sports competition","The dehumanization of Black men for white entertainment","A family feud","A religious war"]', 1, 'The blindfolded fight is a powerful metaphor for how the white establishment forces Black men to fight each other while they are kept ''blind'' to their true common enemy.', NULL, 'NECO_Literature_2024.json', 'd410adb88230e9b408f21e10f9db9abc9ce06b90b7485b47d44422f56df839a0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'An address to an absent person or a personified object is a/an _____.', '["Apostrophe","Hyperbole","Metonymy","Synecdoche"]', 0, 'Apostrophe is a figure of speech in which the speaker addresses an imaginary character, an inanimate object, or a person who is not present.', NULL, 'NECO_Literature_2024.json', 'aef201d32ae135372e72c06d9cc47889dd43a66603d792093f0da3f6e7c1edea');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The central idea or underlying message of a literary work is its _____.', '["Plot","Theme","Setting","Diction"]', 1, 'A theme is a universal idea, lesson, or message that an author explores through a story.', NULL, 'NECO_Literature_2024.json', '2c026abf3a6dbbe1ecf18bb656964b35f8b588070d11eeded2e7893c96d4880e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In The Lion and the Jewel, Baroka wins Sidi''s hand through _____.', '["Force","Money","Cunning and trickery","Modern education"]', 2, 'Baroka feigns impotence to lure Sidi into his palace, where he eventually seduces her, proving that traditional cunning can outwit ''modern'' logic.', NULL, 'NECO_Literature_2024.json', '3ff61aefc9e4ed2f5c6f834fe72c4fd9c305d22202398cfbd427725236306794');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'Identify the device in: ''The pen is mightier than the sword''.', '["Synecdoche","Metonymy","Simile","Irony"]', 1, 'Metonymy replaces the name of an object with the name of something else with which it is closely connected (the ''pen'' for writing/diplomacy and the ''sword'' for violence/war).', NULL, 'NECO_Literature_2024.json', '4142d979ad0bb26faf5a4a93dcfa67e31d65f782919e587fe7d039622bafbea8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The use of a word whose sound suggests its meaning is _____.', '["Onomatopoeia","Assonance","Consonance","Alliteration"]', 0, 'Onomatopoeia involves words like ''buzz'', ''hiss'', or ''bang'' that mimic the natural sounds of a thing.', NULL, 'NECO_Literature_2024.json', '5fce82ff7bdd5c0059074e25076261d3ccff606b3332f339604744eeb9dc9b58');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Maya Angelou''s ''Caged Bird'', the bird sings of _____.', '["Food","Freedom","Death","The sun"]', 1, 'The caged bird sings of freedom because it is a thing unknown but longed for, representing the African American struggle for civil rights.', NULL, 'NECO_Literature_2024.json', '892dd963844647553a64756f09768a0318a78796843d1739e110ff618d31a84a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'A poem of three lines with a 5-7-5 syllable structure is a _____.', '["Sonnet","Haiku","Limerick","Epic"]', 1, 'A Haiku is a traditional form of Japanese poetry consisting of three lines with a syllable count of 5, 7, 5.', NULL, 'NECO_Literature_2024.json', 'c52d21cbb3582536085181e7434ea643ac97d3fbd4625a5bf1b10b0d8db5eb1b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Look Back in Anger, Helena Charles is _____.', '["Jimmy''s sister","Alison''s friend and Jimmy''s eventual lover","A maid","A landlady"]', 1, 'Helena initially despises Jimmy but after Alison leaves, she begins an affair with him, showing the complexity and volatility of the characters.', NULL, 'NECO_Literature_2024.json', '7224613c77b5a1f36bd915f6a5d4ff25688158bac2c5070b5fdbdf694e653346');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The error in judgment or character flaw of a tragic hero is known as _____.', '["Catharsis","Anagnorisis","Hamartia","Hubris"]', 2, 'Hamartia is the Greek term for ''fatal flaw'' that leads to the downfall of a tragic hero.', NULL, 'NECO_Literature_2024.json', '741d8562f330a61e4aa6743896702e7bc558acd49cecc4f02e09ce369b6c4edc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'Identify the device in: ''He is as brave as a lion''.', '["Metaphor","Personification","Simile","Hyperbole"]', 2, 'A simile is a direct comparison between two things using ''as'' or ''like''.', NULL, 'NECO_Literature_2024.json', '22a0d2b7a16ec25d59357bd51eb554424a99f6c35050244a2d2f4b67eaf22915');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Fences, the ''fence'' symbolizes _____.', '["A construction project","Protection and exclusion","Wealth","The border of the country"]', 1, 'The fence represents Rose''s desire to keep her loved ones in and protected, and Troy''s attempts to keep death and the changing world out.', NULL, 'NECO_Literature_2024.json', '5c43ed49b25185d347f3bb10880aaa73a15292a57f3b6e2b3896231f43bb2436');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'A play that is characterized by slapstick humor and improbable situations is a _____.', '["Tragedy","Farce","Opera","History play"]', 1, 'A farce is a lighthearted comedy that centers on ridiculous and highly exaggerated situations to provoke laughter.', NULL, 'NECO_Literature_2024.json', 'c0bf5f5b98df9eca087bc20c714271e801b15180a1fe2c08a3992ece49b8cfb2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In ''Journey of the Magi'' by T.S. Eliot, the birth of Christ is seen as _____.', '["Pure joy","A hard and bitter agony for the old world","A military conquest","An insignificant event"]', 1, 'Eliot portrays the journey as a spiritual struggle where the birth of the new religion signifies the death of the Magi''s old pagan world.', NULL, 'NECO_Literature_2024.json', '9cd2727328063e68c0b073199fb7c1d8658bcab50db04dd350e834c0643aa36f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The recurrence of similar vowel sounds in a line of poetry is _____.', '["Assonance","Consonance","Alliteration","Rhyme"]', 0, 'Assonance is the repetition of vowel sounds within nearby words, such as ''the light of the fire is a sight''.', NULL, 'NECO_Literature_2024.json', 'd2583f52db9174bc3d1771f080543387e5ae17ab2a60a177d1eea3fb595ddc7e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Unexpected Joy at Dawn, the motif of the ''black skin'' represents _____.', '["Beauty","A source of pride","A target for discrimination and xenophobia","Wealth"]', 2, 'The novel explores how skin color and nationality become markers for identifying ''aliens'' and subjecting them to mistreatment during the expulsion eras.', NULL, 'NECO_Literature_2024.json', '95da6cd463ed3a52b2e5fda6f0386ebe57b05b8032d231d157c66c3c1f61087c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'A statement that seems self-contradictory but contains a hidden truth is a _____.', '["Paradox","Oxymoron","Irony","Euphemism"]', 0, 'A paradox is a seemingly absurd statement that, when investigated, may prove to be well-founded or true.', NULL, 'NECO_Literature_2024.json', '4573597329579e22dbdd7fff7c11e58c5e8e1fdc555a9b5fca164e929aad0df1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Let Me Die Alone, the antagonist who plots against Queen Yoko is _____.', '["Lamboi","Jeneba","Ndapi","Gbanya"]', 0, 'Lamboi, Yoko''s brother, is the primary villain who conspires with Musa to frame Yoko for the murder of Jeneba.', NULL, 'NECO_Literature_2024.json', '67b45e83ac7ce19bc81a47133b8322a9056d1d0dbe3907193991cb76291c4a2f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The choice of words and style of expression used by an author is _____.', '["Theme","Diction","Plot","Syntax"]', 1, 'Diction refers to the linguistic choices a writer makes to convey an idea or point of view, or tell a story, in a particular way.', NULL, 'NECO_Literature_2024.json', '668ca7d8f3c51285f2682ae51352c2a458a7c10fac7b7234aa910c6af8415067');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Invisible Man, the ''Golden Day'' is _____.', '["A holiday","A saloon/asylum where the narrator takes Mr. Norton","A graduation day","A bank"]', 1, 'The Golden Day is a chaotic tavern where Black veterans (some suffering from trauma/mental illness) congregate, exposing the cracks in the narrator''s ordered world.', NULL, 'NECO_Literature_2024.json', '4c030c78da35fdd783f3955ddc9612d4ff11e7e835916daac9403b4afa6a0f1a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'A long narrative poem celebrating the deeds of a hero is a/an _____.', '["Ballad","Lyric","Epic","Ode"]', 2, 'An epic is a lengthy narrative poem that usually details the extraordinary feats and adventures of characters from a distant past.', NULL, 'NECO_Literature_2024.json', 'd6a6d8712b24149e9a690fca6d6c87ff4213b4d5f0eac149fab4ec24b55ee8d4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Second Class Citizen, ''Ghetto'' refers to _____.', '["Adah''s rich neighborhood","The impoverished housing for immigrants in London","A school","A church"]', 1, 'Emecheta uses the term to describe the substandard, overcrowded, and racially segregated living conditions faced by West Indians and Africans in 1960s Britain.', NULL, 'NECO_Literature_2024.json', 'f9a2179243ff12fbeb30c12e3c8774b531705d65e014b9553196ca1a65431041');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'Identify the device in: ''The world is a stage''.', '["Simile","Metaphor","Personification","Irony"]', 1, 'A metaphor is an implicit comparison between two unlike things (world and stage) without using ''like'' or ''as''.', NULL, 'NECO_Literature_2024.json', '4d2480603cddf3aff891cbbb998cc93109930f17aef21bf8a402d81174e2483f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Look Back in Anger, the ''bears and squirrels'' game is _____.', '["A children''s board game","An escape for Jimmy and Alison into a world of pure affection","A gambling game","A political strategy"]', 1, 'The bear and squirrel game is a form of ''childlike'' play that allows Jimmy and Alison to momentarily retreat from their harsh social reality and emotional conflict.', NULL, 'NECO_Literature_2024.json', 'f176b183e0773301bfdde316841cc3523e2900f3d6c7ca9d6c95ba2ae92f0a98');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The use of a part of something to represent the whole is _____.', '["Metonymy","Synecdoche","Oxymoron","Paradox"]', 1, 'Synecdoche is a figure of speech in which a part is made to represent the whole or vice versa, such as ''all hands on deck'' (where ''hands'' represents the sailors).', NULL, 'NECO_Literature_2024.json', 'f6aa2325c27dd6a2a7931154b27681c1640129010486e8a9c12f1fef4bcb9e94');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In ''The Panic of Growing Older'' by Lenrie Peters, the ''panic'' is caused by _____.', '["War","The realization of unfulfilled dreams and the passage of time","A disease","Fear of heights"]', 1, 'The poem explores the anxiety individuals feel as they age and realize they may not achieve the grand expectations they had in youth.', NULL, 'NECO_Literature_2024.json', '6500d5932f5c6abc7f5ae81e6905f7024c4e3c2abe7a9473a5390c8ec61cc549');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The purging of emotions, especially pity and fear, through art is _____.', '["Catharsis","Hamartia","Peripeteia","Anagnorisis"]', 0, 'Catharsis is the emotional release experienced by the audience at the conclusion of a successful tragedy.', NULL, 'NECO_Literature_2024.json', '436e96428447ef3fa8e41423aabc2751361375b6442e3a6e84ba528cc4ed56f2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Fences, Troy''s brother Gabriel believes he is _____.', '["A soldier","The Archangel Gabriel","The President","A doctor"]', 1, 'Gabriel suffered a head injury in WWII and now believes he is the Archangel Gabriel, carrying a trumpet to blow on Judgment Day.', NULL, 'NECO_Literature_2024.json', '1063bbb44bfe87b92d174ffda93ca2e1535eb9d05265b2c48648172d1994860a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'A humorous play on words that sound similar but have different meanings is a _____.', '["Satire","Pun","Sarcasm","Irony"]', 1, 'A pun (or paronomasia) is a form of wordplay that exploits multiple meanings of a term, or of similar-sounding words, for an intended humorous or rhetorical effect.', NULL, 'NECO_Literature_2024.json', 'c72ee46c512f4f2db45ca19cd99e72471153a35b88d4f47efbf91ab04e46510a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Unexpected Joy at Dawn, Mama Orojo travels to Ghana to _____.', '["Buy gold","Find her long-lost brother Nii Tackie","Attend a wedding","Escape a war"]', 1, 'The emotional core of the novel is Mama Orojo''s quest to reconnect with her brother after their family was split by decades of expulsion orders.', NULL, 'NECO_Literature_2024.json', '4f60435e04cf9a104924b17ca065493face9ba16b00cc99cf888157a8c7adfb1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The ''falling action'' occurs _____.', '["Before the climax","At the very beginning","Immediately after the climax","In the middle of the exposition"]', 2, 'Falling action is the part of a literary plot that occurs after the climax has been reached and the conflict has been resolved.', NULL, 'NECO_Literature_2024.json', 'cabbe83a2f8da80345095f2c3f053c1734b965190109b57238213284b9c8e516');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In The Lion and the Jewel, the Bale''s impotence turns out to be _____.', '["A medical fact","A curse","A strategic lie","Old age"]', 2, 'Baroka lies about his impotence to test Sadiku''s discretion and to trick Sidi into visiting him, ultimately leading to his victory.', NULL, 'NECO_Literature_2024.json', '635944c84c0fca0b59cdbda9c278e3f276ee2b52fef9189cb443d1ba32758684');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'A lyric poem with a complex stanzaic structure, typically addressing a serious subject, is a/an _____.', '["Ballad","Ode","Epic","Limerick"]', 1, 'An ode is a formal, often ceremonial lyric poem that addresses and often celebrates a person, place, thing, or idea.', NULL, 'NECO_Literature_2024.json', '666b7801531929f3584f85b5f3846076cf38e0cc63c798f4de88642d1255e7cb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'In Wuthering Heights, Catherine Earnshaw dies shortly after _____.', '["A fight with Heathcliff","Giving birth to young Catherine","Moving to London","Heathcliff returns from abroad"]', 1, 'Catherine''s death occurs after she gives birth to her daughter, Catherine Linton, marking a turning point for the novel''s second half.', NULL, 'NECO_Literature_2024.json', '9c171c87658742b11098338aad23379b3004cc27a1381eff7c215576d9ea7c4c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2024, NULL, 'The atmosphere or emotional aura of a work is its _____.', '["Mood","Plot","Diction","Structure"]', 0, 'Mood refers to the overall feeling or emotional weight created in the reader by a literary work, through setting, tone, and theme.', NULL, 'NECO_Literature_2024.json', '91d3f6d86cb1ab13f0635e55b11d553a5609d529806f5e4e53fe100d8bf44021');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('NECO', 'Literature', 2025, NULL, 'The expression ''cacophony of sounds'' appeals to the sense of:', '["Sight","Hearing","Smell","Touch"]', 1, NULL, '<b>The Marketplace</b><br><br>The market was a cacophony of sounds and a riot of colors. Market women shouted their wares at the top of their lungs, competing with the blaring horns of impatience buses. Chike navigated the labyrinth of stalls, holding his wallet tight against his chest. He saw a woman haggling fiercely over a basket of tomatoes, her hands cutting the air for emphasis. The smell of roasted corn battled with the stench of the open gutters. It was chaotic, dirty, and loud, yet it possessed a vibrant pulse that Chike found strangely intoxicating.', 'NECO_Literature_2025.json', '977e2a1baa3d88325b681368c83bf528978e5f04eb529b70ead231bd8cc72f4d');
