INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('PRI', 'Pri_Vocational', 2026, NULL, 'Who serves food in a restaurant?', '["Waiter","Chef","Manager","Cleaner"]', 0, NULL, NULL, 'PRI_Pri_Vocational_2026.json', '4c34ccfb4432e0de6edc65921a05cbc47561240a700b5313740e0dbbde37556b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('PRI', 'Pri_Vocational', 2026, NULL, 'A helmet protects the _______.', '["Head","Hand","Leg","Stomach"]', 0, NULL, NULL, 'PRI_Pri_Vocational_2026.json', '55c8071445a8272589cc57e6743f25202b586032dcace320ddac5b7d903843be');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('PRI', 'Pri_Vocational', 2026, NULL, 'Who acts in movies?', '["Actor","Artist","Author","Architect"]', 0, NULL, NULL, 'PRI_Pri_Vocational_2026.json', '8c9e218350fd71791e80031d91d2d48e53b73f68c177bf64a1e4cf4b48e17b23');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The accounting concept which states that for every debit entry, there must be a corresponding credit entry is the _____ concept.', '["Going concern","Dual aspect","Accrual","Money measurement"]', 1, 'The Dual Aspect concept is the foundation of the double-entry system, ensuring that the accounting equation (Assets = Liabilities + Equity) always balances.', NULL, 'WAEC_Accounting_2024.json', '553c8b7c0292ed0f6265a4814a96c2a9b90a2b0fdad2b5468379f97650c27837');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Which of the following is an example of a nominal account?', '["Plant and Machinery","Bank Account","Wages Account","Debtors Account"]', 2, 'Nominal accounts are accounts for expenses, incomes, losses, and gains. Wages is an expense account.', NULL, 'WAEC_Accounting_2024.json', 'fb94518a5b9e3ee5d88e236397ae0cd62ae47fe2cbdf127f8dc9a79410b9f5bf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The process of transferring entries from the journals to the ledger is known as _____.', '["Balancing","Totaling","Posting","Analyzing"]', 2, 'Posting is the technical term for transferring data from the books of original entry (journals) to the principal book (ledger).', NULL, 'WAEC_Accounting_2024.json', '45cf4adb4f4a9e01b88d41872b3523e6ec8988a11d77f39585010d295927d9bd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Which book of prime entry is used to record the purchase of a motor van on credit?', '["Purchases Journal","Cash Book","General Journal","Returns Outwards Journal"]', 2, 'The Purchases Journal is only for credit purchases of goods intended for resale (trading stock). Non-current assets bought on credit are recorded in the General Journal.', NULL, 'WAEC_Accounting_2024.json', '9fe87a844a5bb3e9826f07d7c7f231febc15d7509054d228c140d84f0ff880ea');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'A credit balance in the Cash Book (Bank column) indicates a/an _____.', '["Bank deposit","Bank overdraft","Available cash","Cash in hand"]', 1, 'In the bank account, a debit balance is an asset, while a credit balance represents a liability to the bank, known as an overdraft.', NULL, 'WAEC_Accounting_2024.json', '444cdffa0e6476f9bbf920bbeb753f91f2176842b4e9cb27bcd743b2c8b7327d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'What is the correct entry for recording a cash discount allowed to a customer?', '["Debit: Discount Received; Credit: Customer''s Account","Debit: Customer''s Account; Credit: Discount Allowed","Debit: Discount Allowed; Credit: Customer''s Account","Debit: Cash; Credit: Discount Allowed"]', 2, 'Discount Allowed is an expense. To record it, you debit the expense account (Discount Allowed) and credit the personal account of the customer.', NULL, 'WAEC_Accounting_2024.json', '6d14fabad350feecf9ad9a857fd70aa72c919365babe6f609d2c3df07f8252c6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Which of the following errors will NOT affect the Trial Balance agreement?', '["Addition error in a ledger account","Omission of an account from the Trial Balance","Complete omission of a transaction","Transposition error in one account"]', 2, 'An error of omission (forgetting to record a transaction entirely) means no debit or credit was made, so the Trial Balance will still agree despite the error.', NULL, 'WAEC_Accounting_2024.json', '18244218fb4f3368c14adc1559aa578b4c8a20f9e40567660b0be3172c435ade');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'A Bank Reconciliation Statement is prepared by the _____.', '["Bank manager","Accountant of the business","External auditor","Central Bank"]', 1, 'The business prepares the Bank Reconciliation Statement to identify discrepancies between its Cash Book (Bank column) and the Bank Statement provided by the bank.', NULL, 'WAEC_Accounting_2024.json', 'dca7bd98115eb83ceb5264598791bd7ac66c386211b339a79a2115019c6f091d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Calculate the Cost of Goods Sold.', '["#15,000","#18,000","#22,000","#25,000"]', 2, 'Cost of Goods Sold = Opening Stock + Purchases - Closing Stock = 5,000 + 20,000 - 3,000 = #22,000.', 'The following information relates to Tunde Enterprises for the month of January 2024: 
Opening Stock: #5,000
Purchases: #20,000
Closing Stock: #3,000
Sales: #40,000
Expenses: #8,000', 'WAEC_Accounting_2024.json', 'b2bf3e5466d2e037782439bfd45a50d2f75e3e57c3de0a6991314cc94a45d9c1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Calculate the Gross Profit.', '["#18,000","#15,000","#20,000","#10,000"]', 0, 'Gross Profit = Sales - Cost of Goods Sold = 40,000 - 22,000 = #18,000.', 'The following information relates to Tunde Enterprises for the month of January 2024: 
Opening Stock: #5,000
Purchases: #20,000
Closing Stock: #3,000
Sales: #40,000
Expenses: #8,000', 'WAEC_Accounting_2024.json', '553c608e46a88735be95923643ace9a954c6679039252f45dcff95db3a059238');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Calculate the Net Profit.', '["#10,000","#12,000","#18,000","#5,000"]', 0, 'Net Profit = Gross Profit - Expenses = 18,000 - 8,000 = #10,000.', 'The following information relates to Tunde Enterprises for the month of January 2024: 
Opening Stock: #5,000
Purchases: #20,000
Closing Stock: #3,000
Sales: #40,000
Expenses: #8,000', 'WAEC_Accounting_2024.json', '1c902ee3586f6a4c21d9574ea90ba8eb98d173888842bc07603d034ea8a53759');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The reward for a partner for providing capital to the firm is _____.', '["Interest on drawings","Share of profit","Interest on capital","Commission"]', 2, 'Interest on capital is an appropriation of profit designed to compensate partners for the amount of capital they have invested in the partnership.', NULL, 'WAEC_Accounting_2024.json', 'ee00dc317553854bfadb63769e8f61bb0fc7d0c265c0ce34059ca7195d0f4335');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The document sent by a supplier to a customer showing an overcharge on a previous invoice is a _____.', '["Credit note","Debit note","Payment voucher","Waybill"]', 0, 'A credit note is issued to reduce the amount the customer owes, used for returns or overcharges.', NULL, 'WAEC_Accounting_2024.json', 'bc5a76378652dc169a97a443dea649ef2194f8203f59fbf60d8417cb7c337723');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Which of the following is a capital expenditure?', '["Purchase of raw materials","Payment of electricity bills","Purchase of a new delivery truck","Painting of an old office"]', 2, 'Capital expenditure is spending on non-current assets that will benefit the business for more than one year.', NULL, 'WAEC_Accounting_2024.json', '4f28714e9c0bc06e693154f9fbacc8d2e917640347b54e43b2f79f919f85c102');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The accounting equation is expressed as _____.', '["Assets = Liabilities - Capital","Capital = Assets + Liabilities","Assets = Liabilities + Capital","Liabilities = Assets + Capital"]', 2, 'The fundamental equation of accounting states that everything the business owns (Assets) is funded by either creditors (Liabilities) or the owner (Capital).', NULL, 'WAEC_Accounting_2024.json', '09f8f40263b4222e013ff0ae8c90fd3fd148a99a05fd52ee899f68cebeebe0e8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'In a partnership, where there is no deed, the Profit and Loss sharing ratio is _____.', '["Based on capital contribution","2:1","Equal","Determined by the senior partner"]', 2, 'According to the Partnership Act of 1890, in the absence of a formal agreement, profits and losses must be shared equally among partners.', NULL, 'WAEC_Accounting_2024.json', '14e7bdd5f49f4d7f2790adef224eba57f8cbfa5381ebe8d230c7d83649df5ab3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The petty cash system where the petty cashier is given a fixed sum at the start of a period is the _____.', '["Floating system","Imprest system","Direct system","Reserve system"]', 1, 'The Imprest system involves providing a fixed amount (float) and replenishing exactly what was spent at the end of the period.', NULL, 'WAEC_Accounting_2024.json', '01733e677f971f1e68b24aeba23aa5bed7287b4562b0d9ee1d2b609e5b28c28c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The value of a non-current asset as shown in the books after deducting accumulated depreciation is its _____.', '["Market value","Scrap value","Net Book Value","Replacement value"]', 2, 'Net Book Value (NBV) is the historical cost less the total depreciation charged to date.', NULL, 'WAEC_Accounting_2024.json', '9a8719c5e5084e0d6b10f0c820a34164f629402c5a93645308b1c2a648dd68d8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'A firm purchased a machine for #10,000. It is estimated to last 4 years with a scrap value of #2,000. Using the straight-line method, calculate the annual depreciation.', '["#2,500","#2,000","#1,500","#3,000"]', 1, 'Annual Depreciation = (Cost - Scrap Value) / Life = (10,000 - 2,000) / 4 = 8,000 / 4 = #2,000.', NULL, 'WAEC_Accounting_2024.json', '45ebff2599ed564deb8d7fc4e80cd58a7efaef3880eaea28037aaf3f7130556b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'An entry made on both sides of a three-column cash book is a _____.', '["Double entry","Single entry","Contra entry","Reverse entry"]', 2, 'A contra entry occurs when cash is deposited into the bank or cash is withdrawn from the bank for office use, affecting both cash and bank columns.', NULL, 'WAEC_Accounting_2024.json', '99f9ba37abda59ace53bbcddb6073c25d896768cbf85e77e3534cc0b1113e203');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Which of the following is an intangible asset?', '["Inventory","Accounts Receivable","Goodwill","Cash at Bank"]', 2, 'Goodwill is an asset that lacks physical substance but provides long-term value to the business.', NULL, 'WAEC_Accounting_2024.json', '83de2ef8921e80870e88ece275b47809672290a3e6485c9b0c6ce92b577c6788');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Prime cost is the sum of _____.', '["Direct materials and direct labour","Direct materials, direct labour and direct expenses","Factory overheads and direct labour","Cost of goods sold and expenses"]', 1, 'Prime cost consists of all direct costs involved in the manufacturing of a product.', NULL, 'WAEC_Accounting_2024.json', '79cf8f967bb58b502d488adc8a775fb081a0a980fd9f0207e27a93bad4523e33');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The excess of a non-profit organization''s income over its expenditure is called _____.', '["Net Profit","Gross Profit","Surplus","Accumulated Fund"]', 2, 'Non-profit organizations use the term ''Surplus'' instead of profit and ''Deficit'' instead of loss.', NULL, 'WAEC_Accounting_2024.json', '26afb19503bcbe8e1b2073c8507e302f565822675984a69675a88918b4af1a55');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'In a limited liability company, the part of authorized capital that has been offered to the public for subscription is _____.', '["Paid-up capital","Issued capital","Called-up capital","Reserve capital"]', 1, 'Issued capital is the portion of authorized (nominal) capital that the company has actually sent out for investors to buy.', NULL, 'WAEC_Accounting_2024.json', '43546cfe707f11bdeff9bc6662495c39cca33d6f84c2f76926b0716c8f01ca33');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The document that regulates the internal rules of a company is the _____.', '["Memorandum of Association","Prospectus","Articles of Association","Certificate of Incorporation"]', 2, 'Articles of Association define the relationship between the company and its members and the internal conduct of the business.', NULL, 'WAEC_Accounting_2024.json', '1586980b7fbfd9438bba0fe319df83e2b10b9f78ed252bcc28822d3d748bc7ab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The list of balances extracted from the ledgers to test the arithmetical accuracy of the double-entry is the _____.', '["Balance Sheet","Income Statement","Trial Balance","Cash Book"]', 2, 'The Trial Balance is a diagnostic tool to ensure that total debits equal total credits before preparing final accounts.', NULL, 'WAEC_Accounting_2024.json', 'fe4bd39c9ec6e79e1a2666c75048130a5da2e7406bdb1f8759d52adfa1887345');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Which of the following is a current liability?', '["Bank Loan (5 years)","Accrued Wages","Furniture","Prepaid Insurance"]', 1, 'Accrued wages are expenses incurred but not yet paid, representing a short-term debt (current liability).', NULL, 'WAEC_Accounting_2024.json', '2628ffdc17046fb10b3a76fe2ad83f9616941f37a1c30b0028ca1f8216fcb153');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The systematic record of the cash and bank transactions of a business is the _____.', '["Petty Cash Book","Cash Book","Journal","Ledger"]', 1, 'The Cash Book serves as both a book of original entry and a ledger account for cash and bank balances.', NULL, 'WAEC_Accounting_2024.json', '75f56a472f8b1a71783f47b23180eaa65f3b97545f00de38135cc4f44472e6ff');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Bad debts are categorized as _____.', '["Current Assets","Operating Incomes","Operating Expenses","Intangible Assets"]', 2, 'Bad debts represent a loss resulting from uncollectible receivables and are treated as an expense in the profit and loss account.', NULL, 'WAEC_Accounting_2024.json', 'e2ea0c023d8d5b437d8eb68500e70d410d4efc92b004015a766a7fbfce568100');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Which of the following is recorded in the Trading Account?', '["Electricity bill","Discount allowed","Carriage inwards","Salaries"]', 2, 'Carriage inwards is the cost of transporting purchases to the business premises and is added to purchases in the Trading Account to find the cost of goods sold.', NULL, 'WAEC_Accounting_2024.json', '76dc78819a597f0a949aa2b25f30978f0bf6256fca6b76f384339a243a033110');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Shares that carry a fixed rate of dividend are _____.', '["Ordinary shares","Preference shares","Deferred shares","Equity shares"]', 1, 'Preference shares give the holder a right to a fixed dividend before any dividend is paid to ordinary shareholders.', NULL, 'WAEC_Accounting_2024.json', 'd5de5d0b83eb0686fe2b08c14f6dd73277d1c1cb63c09d096870e4857d504dd5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The matching concept requires that _____.', '["Assets must match liabilities","Expenses incurred must be matched against revenue earned in the same period","The debit side must match the credit side","Current assets must match current liabilities"]', 1, 'The matching principle ensures that profit is calculated by comparing the revenues of a period with the expenses used to generate that revenue.', NULL, 'WAEC_Accounting_2024.json', 'd7d4054e22a0aab57c4ceb9cbad16337eff6a4296bde678a3766be6a8c716133');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'A suspense account is used to _____.', '["Record bad debts","Temporarily balance the trial balance","Keep track of cash shortages","Record drawings by the owner"]', 1, 'When a Trial Balance fails to agree, the difference is temporarily placed in a Suspense Account until the errors are located and corrected.', NULL, 'WAEC_Accounting_2024.json', '03aad2c859f179b010f25d94a5bff33d89fe0a7be645657f1627f5283bcb5ea4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The value of a non-profit organization''s assets over its liabilities at the start of a period is the _____.', '["Working capital","Accumulated fund","Share capital","Net profit"]', 1, 'For clubs and societies, the equivalent of ''Capital'' is the Accumulated Fund, representing the net worth of the organization.', NULL, 'WAEC_Accounting_2024.json', 'f0454920762b28ece341b467f6c0797a40dfeccc3108f28c9ce45075c57c3ac8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Subscription received in advance for the next accounting period is a/an _____ in the current Balance Sheet.', '["Current Asset","Current Liability","Income","Expense"]', 1, 'Income received in advance is a liability because the organization still owes the service to the member for the coming period.', NULL, 'WAEC_Accounting_2024.json', '899ffdb62022d50e41adaafb53d4fa53a3770a65ecc1bc926d7f0c2f941fbdb1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The Purchases Ledger Control Account is used to check the accuracy of the _____.', '["Sales Ledger","General Ledger","Purchases Ledger","Private Ledger"]', 2, 'The Purchases Ledger Control Account (or Creditors Control) summarizes all transactions in the individual creditors'' accounts.', NULL, 'WAEC_Accounting_2024.json', '7ee1ec4d579c38282a4f844665a6918d162d16eccd460a6960602ce0bcb718f0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'When a partner retires, the profit on revaluation of assets is credited to _____.', '["Remaining partners only","Retiring partner only","All partners in their old profit sharing ratio","New partners only"]', 2, 'Revaluation gains belong to all partners who were in the firm when the asset value changed, shared according to their existing ratios.', NULL, 'WAEC_Accounting_2024.json', '1383f2414205f163d53e659b6857783299fa127f18a0c4c8e6eeb7bd8bdeaf7e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Which of the following is a book of prime entry AND a ledger?', '["Sales Journal","Cash Book","Purchases Journal","Returns Inwards Journal"]', 1, 'The Cash Book is unique because it serves both as the initial record of transactions and as the final T-account for cash and bank.', NULL, 'WAEC_Accounting_2024.json', '5a318b84512e6c49653b3408d55dbfc7cbb1102d9bad1ab6829ad22667563f54');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'If a Trial Balance has a total debit of #10,500 and a total credit of #10,000, what is the balance in the Suspense Account?', '["#500 Debit","#500 Credit","#1,000 Credit","#10,500 Credit"]', 1, 'To make the Trial Balance agree, the smaller side (Credit) must be increased by #500. Therefore, the Suspense Account will have a credit balance.', NULL, 'WAEC_Accounting_2024.json', '817afb75fce0f19d24bb718bc9c35faf315c06546f0cec1425354c3131a5888a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Sales of #2,000 to Mr. A was recorded in Mr. B''s account. This is an error of _____.', '["Principle","Commission","Original entry","Compensating"]', 1, 'An error of commission occurs when an entry is made in the correct class of account (Personal) but the wrong individual account (Mr. B instead of Mr. A).', NULL, 'WAEC_Accounting_2024.json', '14fc887876ef4ced95b5e460922f6c95e127f48da78f80d633e07a04f2041e2d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The document showing the financial position of a business at a specific date is the _____.', '["Income Statement","Balance Sheet","Cash Flow Statement","Trial Balance"]', 1, 'The Balance Sheet (Statement of Financial Position) lists assets, liabilities, and capital to show what a business is worth at a specific point in time.', NULL, 'WAEC_Accounting_2024.json', '8514ff106439c8798ac0c8ae45971961398034a3368b07b36c855967555ff289');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Cost of raw materials consumed is calculated as _____.', '["Opening stock of raw materials + Purchases - Closing stock of raw materials","Opening stock of finished goods + Purchases - Closing stock","Direct labour + Factory overheads","Sales - Gross profit"]', 0, 'This is the standard formula in a Manufacturing Account to determine the value of materials actually used in production.', NULL, 'WAEC_Accounting_2024.json', '2307e6bdecb0f6ae37517ca93fe78b604fc799ee648de728010dc1a85aa682b2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Which of the following is a source of revenue for the government?', '["Grants to local governments","Payment of civil servants'' salaries","Direct and indirect taxes","Construction of roads"]', 2, 'Taxes (CIT, PIT, VAT, etc.) are the primary means by which a government generates income to fund public expenditure.', NULL, 'WAEC_Accounting_2024.json', 'ef779476108bf3e1b3dd5ef7fc510c4df8f0e7ee9a99ab39ac7813d8c6a55201');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The method of depreciation where the percentage is applied to the declining balance of the asset is the _____.', '["Straight line method","Reducing balance method","Revaluation method","Sum of the years'' digits"]', 1, 'The reducing balance method results in higher depreciation charges in the earlier years of an asset''s life.', NULL, 'WAEC_Accounting_2024.json', '0450fcbd225c9c8af8fef2df24c026f24218a43ff094bfab53e1066c49227647');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Authorized capital is also known as _____.', '["Issued capital","Nominal capital","Paid-up capital","Working capital"]', 1, 'Nominal or registered capital is the maximum amount of share capital a company is legally allowed to issue.', NULL, 'WAEC_Accounting_2024.json', 'fa5f069ef1a9f56a1b9a5a996311cffd874413e4f3ceb581c673651b251f036e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Goodwill is usually brought into the books when _____.', '["A business is making losses","A business is purchased or a new partner is admitted","The owner decides to increase the asset value","Depreciation is too high"]', 1, 'Goodwill is generally only recognized in accounting when there is a change in the ownership structure or a purchase of a going concern.', NULL, 'WAEC_Accounting_2024.json', 'c3349c284b7fa9507cebe23aea65c28394c9bda18d9c4f7d0392633c849ca071');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Which of the following describes a ''Capital Reserve''?', '["Profit from normal trading activities","Profit set aside for dividends","Profit from the sale of a fixed asset","Money set aside for paying wages"]', 2, 'Capital reserves are created from non-trading activities, such as the profit on sale of non-current assets or revaluation of assets.', NULL, 'WAEC_Accounting_2024.json', '886c9da0b0466365940bb90beb4b86aaa5a48917d76988648fb31b4cda6c3c23');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Working Capital is defined as _____.', '["Total Assets - Total Liabilities","Fixed Assets - Current Liabilities","Current Assets - Current Liabilities","Capital + Long-term Loans"]', 2, 'Working capital measures the short-term liquidity of a business, indicating its ability to pay off debts due within a year.', NULL, 'WAEC_Accounting_2024.json', 'eff69c7be984bc59358666ab7c5c181fbb8e5fd443a1387623a1ce1327544d6a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The ledger containing the individual accounts of suppliers is the _____.', '["General Ledger","Sales Ledger","Purchases Ledger","Private Ledger"]', 2, 'The Purchases Ledger (or Creditors Ledger) houses the personal accounts of all credit suppliers.', NULL, 'WAEC_Accounting_2024.json', '6cf39172dfff14baf5341d8711e6c8f38b493cc39761ef3895a922e9aec69bc6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Which of the following appears on the credit side of the Trading Account?', '["Opening Stock","Purchases","Returns Inwards","Sales"]', 3, 'Sales and Closing Stock are credited to the Trading Account to calculate the gross profit.', NULL, 'WAEC_Accounting_2024.json', '452297a682b1bd9ce23edbd730668cd5170ac4892f6e45e92bed17a75bf10f39');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Provision for doubtful debts is based on the _____ concept.', '["Consistency","Prudence","Materiality","Entity"]', 1, 'The Prudence (Conservatism) concept dictates that a business should anticipate losses but not profits, leading to the creation of provisions.', NULL, 'WAEC_Accounting_2024.json', '7a8931ac6a6c13b47fe0b9d04bef49dd303d9ebc46985459b098e3d2a1daa4d4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'A debit note received from a supplier would be recorded in the _____.', '["Purchases Journal","Returns Outwards Journal","Sales Journal","Returns Inwards Journal"]', 1, 'If a supplier sends a debit note, it means they are increasing our debt, usually because we returned goods. We record this in the Returns Outwards Journal.', NULL, 'WAEC_Accounting_2024.json', '7ee2fb9428b383f704ebc309d2c01fbe0a392e60489f02a62dcddba6fcb7b394');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The person who prepares the Petty Cash Book is the _____.', '["Chief Accountant","External Auditor","Petty Cashier","Company Secretary"]', 2, 'The petty cashier is a junior staff member responsible for small, daily expenditures.', NULL, 'WAEC_Accounting_2024.json', '992058097faf99e7c1785c76e42e0d6f1d50cec06a2933fc2da61c4df3747163');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Unpresented cheques are cheques _____.', '["Drawn but not yet paid by the bank","Received but not yet deposited","Rejected by the bank due to errors","Lost in transit"]', 0, 'Unpresented cheques have been recorded in the Cash Book (credit side) but have not yet appeared on the Bank Statement.', NULL, 'WAEC_Accounting_2024.json', 'd5ddd7966e06e94052921bbc3adf5e675dfb6d33985ac47614475f9f2195f7c1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The Purchases Day Book is used to record _____.', '["Cash purchases","Credit sales","Credit purchases of goods for resale","All purchases"]', 2, 'The Purchases Day Book (or Journal) is specifically for the credit purchase of inventory.', NULL, 'WAEC_Accounting_2024.json', '1df67cc7a225ab7114fd6466214f1f2f4d507cb76ebfd45ff7b21a8b0ad7374c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Drawings by the owner of a business results in a/an _____.', '["Increase in Capital","Decrease in Capital","Increase in Liability","Increase in Net Profit"]', 1, 'Drawings reduce the owner''s stake (equity) in the business.', NULL, 'WAEC_Accounting_2024.json', 'cf01db09437cd5cd8a6183674fcedeabd7b983add22785a21434a007100e711e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Which of the following is a fictitious asset?', '["Preliminary expenses","Patents","Buildings","Stocks"]', 0, 'Fictitious assets are expenses or losses not yet written off, like preliminary expenses or discount on issue of shares.', NULL, 'WAEC_Accounting_2024.json', '91bc513ccf66c07c726fc92a915eee52bb55c8663c88d77f8abb927407735f33');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The double entry for ''Cash sales'' is _____.', '["Debit: Sales; Credit: Cash","Debit: Cash; Credit: Sales","Debit: Bank; Credit: Debtors","Debit: Sales; Credit: Debtors"]', 1, 'Cash is increasing (asset debit) and Sales is an income (credit).', NULL, 'WAEC_Accounting_2024.json', 'fdd8ca7b2979275a640bdd0e767fcbddb26b98a32d8299cf54c0c3517f3c348d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Stock valuation is usually at _____.', '["Cost price only","Market price only","Lower of cost and net realizable value","Higher of cost and net realizable value"]', 2, 'IAS 2 (and the Prudence concept) requires stock to be valued at the lower of cost and net realizable value (market value).', NULL, 'WAEC_Accounting_2024.json', '6d21f0ca3bb8e0fa5c57ff53d63ed0ae2714cc0ba584231945bf4906a0d633fd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'In Departmental Accounts, expenses that cannot be directly traced to a department are allocated _____.', '["To the department with highest sales","Equally to all departments","On a reasonable basis such as floor space or turnover","Ignored entirely"]', 2, 'Common expenses (like rent or electricity) are apportioned using logical bases (e.g., rent by floor area).', NULL, 'WAEC_Accounting_2024.json', '4e3b820434974a39aba7cf3bc644b29465caa80a4b371e1aa464ae62887a740f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'A Receipts and Payments Account is essentially a summary of the _____.', '["Income and Expenditure Account","Cash Book","Trading Account","Profit and Loss Account"]', 1, 'A Receipts and Payments account records all cash inflows and outflows of a non-profit organization for a period.', NULL, 'WAEC_Accounting_2024.json', 'd7919a4fb04172e672fb47c69179292b06e95928ceb02cf35498a29da11d5480');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Which of the following is NOT a purpose of a Trial Balance?', '["To check arithmetical accuracy","To facilitate the preparation of final accounts","To show the financial position of the business","To check that every debit has a credit"]', 2, 'The Trial Balance does not show financial position; that is the function of the Balance Sheet.', NULL, 'WAEC_Accounting_2024.json', '8a7074bfa532a498f120a015454b500762241e9b0127dde989ea57afc9992d38');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The ledger that contains all accounts except personal accounts is the _____.', '["Sales Ledger","Purchases Ledger","General Ledger","Nominal Ledger"]', 2, 'The General Ledger (or Impersonal Ledger) contains real and nominal accounts (Asset, Liability, Income, Expense).', NULL, 'WAEC_Accounting_2024.json', 'e3726f80a6f131ac67579787ec5a73d566d4ea76dba8231b6f031581c8e91ba5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Conversion of a partnership into a limited company involves the _____.', '["Revaluation of assets","Dissolution of the partnership","Appointment of an auditor","Reduction of capital"]', 1, 'Technically, the partnership is dissolved as the business entity changes to a corporate form.', NULL, 'WAEC_Accounting_2024.json', '10e63b69b5d7f609d76efc9cd6784a01e7cd4c198d410430785087a14fc56a4f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The account maintained for each head of expenditure in the Public Sector is the _____.', '["Capital Account","Revenue Account","Vote Account","Consolidated Revenue Fund"]', 2, 'In government accounting, a ''Vote'' is the authority to spend money on a specific head of expenditure.', NULL, 'WAEC_Accounting_2024.json', '88aa2caf91c0be40a87e41c40dc35f248b738477a50a5196b713116f0606157f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Which of the following will result in a higher Gross Profit?', '["Increase in Closing Stock","Increase in Opening Stock","Increase in Purchases","Decrease in Sales"]', 0, 'Closing stock is subtracted from the cost of goods available for sale. A higher closing stock reduces the COGS and thus increases Gross Profit.', NULL, 'WAEC_Accounting_2024.json', '80da1e286c4fdc495df1b5ff09f0d8554b8499960a38ccc6dbf90d86f6a3df60');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The ''Consistency'' concept means that _____.', '["The business must produce the same products","The same accounting methods must be used from year to year","The profits must be consistent","The owner must not change"]', 1, 'Consistency ensures that financial statements are comparable over different accounting periods.', NULL, 'WAEC_Accounting_2024.json', '9f0b6ff79a9f331b007c2877d18b7cff44fa1f2cadd756c493f2ccdae5737f3a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'Which of the following is an internal user of accounting information?', '["Shareholders","Bankers","Production Manager","Tax Authority"]', 2, 'The Production Manager is an employee within the organization who needs the data for decision-making.', NULL, 'WAEC_Accounting_2024.json', '0834a5583645aa4df39c3fe24d688c5a1667a3119c8282b81b32acef579d9f01');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'A debit balance brought down in the Insurance Account represents _____.', '["Insurance owed","Insurance prepaid","Insurance expense for the year","Insurance refund"]', 1, 'A debit balance at the start of a period for an expense account indicates that the business has an asset (prepayment).', NULL, 'WAEC_Accounting_2024.json', 'daf1ffe17ab1a938b9485fe36acdba9dff3c5a444a3b99ebe18f1156c15528d4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2024, NULL, 'The primary objective of financial accounting is to _____.', '["Determine the tax to be paid","Provide information for stakeholders to make decisions","Detect and prevent fraud","Ensure the business stays open"]', 1, 'Accounting is often called the ''language of business'' because its main goal is communicating information to users.', NULL, 'WAEC_Accounting_2024.json', '978a1ba49472e8cb8fc9009765c65a07d270b67800a1dd7c6402170777f29627');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2025, NULL, 'Accounting Equation:', '["$$ Assets = Capital + Liabilities $$","$$ A = C - L $$","$$ C = A + L $$","$$ L = A + C $$"]', 0, NULL, NULL, 'WAEC_Accounting_2025.json', 'ff28b52cf46b36b6d225483909dd78c467247ec2d7b03d7ee20f41e55c61c4d2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2025, NULL, 'Double entry for cash sales:', '["Dr Cash, Cr Sales","Dr Sales, Cr Cash","Dr Cash, Cr Stock","Dr Debtor, Cr Sales"]', 0, NULL, NULL, 'WAEC_Accounting_2025.json', '3d67aa138a92bbcefdc61563d661aeb1ba5d1607fa22c5a295d044e8767e2bec');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2025, NULL, 'Real Account example:', '["Land/Building","Salary","Rent","Debtor"]', 0, NULL, NULL, 'WAEC_Accounting_2025.json', 'd1c2d4192a1897659ceb1424d96a697fcfa87fadd414d36e6a3cb267b141a052');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2025, NULL, 'COGS Formula:', '["Opening + Purchases - Closing","Sales - Profit","Purchases - Returns","Sales - Stock"]', 0, NULL, NULL, 'WAEC_Accounting_2025.json', '0d2393b4d81159307218d7d6ca51c3c91d5d9bb3425c0545f64723420a3c510d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2025, NULL, 'Current Asset example:', '["Stock","Motor Vehicle","Building","Machine"]', 0, NULL, NULL, 'WAEC_Accounting_2025.json', '4e2742d7b0634defe5a2089b29aab0f69a9709946a7638884b92c983f5079122');
