INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2025, NULL, 'Bad Debt:', '["Irrecoverable debt","Late payment","Discount","Loan"]', 0, NULL, NULL, 'WAEC_Accounting_2025.json', '3c7b58a1fdad8695a80ed0847b00505114fe1afe171eaa016e10124df585d325');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2025, NULL, 'Trial Balance checks:', '["Arithmetic accuracy","Fraud","Profit","Balance"]', 0, NULL, NULL, 'WAEC_Accounting_2025.json', '7e423be339be2ac8b0ef82908e3069ba8bdfb88c9c22b163cff01591d60619da');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Accounting', 2025, NULL, 'Error of Principle:', '["Wrong class of account","Wrong side","Wrong amount","Omission"]', 0, NULL, NULL, 'WAEC_Accounting_2025.json', '57955e3229adf8858921d9a166660b1ae391e2c700efab9f2f0b05ddaf62115a');
