INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The Land Use Act of 1978 was enacted in Nigeria primarily to _____.', '["encourage traditional land tenure systems","vest ownership of land in the federal government","vest all land in the state in the Governor of that state","ensure land is sold at high prices to farmers"]', 2, 'The Land Use Act of 1978 vests all land in the territory of each state in the Governor of that state, who holds it in trust for the people and issues Certificates of Occupancy (C of O).', NULL, 'WAEC_Agric_2024.json', '7fb783fcec1e90cee87c6de11210258cc6bca83d2365b86700c123d951ada169');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following is a problem associated with the land tenure system of inheritance?', '["Improvement of soil fertility","Fragmentation of land","Large-scale commercial farming","Mechanization of the farm"]', 1, 'Inheritance leads to the division of land among many children, resulting in small, scattered plots (fragmentation) that are difficult to manage for commercial agriculture.', NULL, 'WAEC_Agric_2024.json', '1333d6d9502f5bee50983fa7e423f1f59e2fb5c6928d30203bccbbae16a84a07');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The primary role of agriculture in the economic development of Nigeria is the _____.', '["provision of industrial machinery","provision of food and raw materials","creation of urban slums","promotion of heavy metal mining"]', 1, 'Agriculture is the main source of food for the population and raw materials (like cocoa, rubber, and palm oil) for the industrial sector.', NULL, 'WAEC_Agric_2024.json', '2a6bc0bb8e580932789f64c51c9eb5d2ba4c709d69c3c0b37a1e14ea2a80bcc5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following is an example of an igneous rock?', '["Limestone","Sandstone","Granite","Marble"]', 2, 'Granite is formed from the cooling and solidification of molten magma, making it an igneous rock. Limestone and sandstone are sedimentary, while marble is metamorphic.', NULL, 'WAEC_Agric_2024.json', '6639bee9aaf0471b0d86bd301c95024a61bfa6c1ae80ad28c192ee8eb19a92c5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The process of rock weathering that involves the reaction of minerals with water to form new compounds is _____.', '["Hydration","Hydrolysis","Oxidation","Carbonation"]', 1, 'Hydrolysis is a chemical weathering process where water reacts with minerals to produce new substances, such as the change of feldspar into clay.', NULL, 'WAEC_Agric_2024.json', '63ec001156d78e11548151589de1934deb9f497b4ffe5bf762d256fa37e255f5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'A soil sample has a pH of 4.5. This soil is said to be _____.', '["Alkaline","Neutral","Acidic","Saline"]', 2, 'Soil with a pH below 7.0 is acidic. A pH of 4.5 is strongly acidic and may require liming for most crops to grow well.', NULL, 'WAEC_Agric_2024.json', '97952fe02f20f951bee553866a68390bdd2a49df14b20c66fdc9665a80f4e9c4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which soil component has the smallest particle size?', '["Gravel","Sand","Silt","Clay"]', 3, 'Clay particles are less than 0.002mm in diameter, making them the smallest soil mineral particles with high water-holding capacity.', NULL, 'WAEC_Agric_2024.json', 'b2925e3e592a47d19d5fc604e87f3b45ee3761e17eb05e5f923c4c307db8f04d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The most effective method of controlling soil erosion on a steep slope is _____.', '["Monocropping","Terracing","Overgrazing","Clean clearing"]', 1, 'Terracing involves creating ''steps'' on a slope to reduce the speed of runoff water, thereby preventing the washing away of topsoil.', NULL, 'WAEC_Agric_2024.json', '1d803a889e9afcaa2d948b5fd288b5b503f72ba394dd6b951e6fa81625bce20a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The symbiotic relationship between legumes and Rhizobium bacteria leads to _____.', '["phosphorus fixation","nitrogen fixation","potassium mobilization","denitrification"]', 1, 'Rhizobium bacteria live in the root nodules of legumes and convert atmospheric nitrogen into nitrates that the plant can use.', NULL, 'WAEC_Agric_2024.json', 'fd6910ed067a82ca6a758e098531595bf2c6879d14ab82850c261f7966d3ddab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following is a macronutrient required by plants?', '["Zinc","Copper","Boron","Potassium"]', 3, 'Potassium (K) is a primary macronutrient, along with Nitrogen (N) and Phosphorus (P). Zinc, Copper, and Boron are micronutrients.', NULL, 'WAEC_Agric_2024.json', 'ce89a2faccae011ba6ea1a3f0900e5db31c8e0faaa8be552d73aa9808a4a0c6c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The implement used for turning the soil and burying weeds is the _____.', '["Disc harrow","Ridger","Mouldboard plough","Planter"]', 2, 'The mouldboard plough is specifically designed to cut, lift, and flip the soil completely, which buries weeds and crop residues.', NULL, 'WAEC_Agric_2024.json', '91dfe4e939fb3762a065ba7fb18ad628d5ec60cc03815ee97dd72cca864617d9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following is a simple farm tool used for harvesting rice?', '["Spade","Sickle","Pick-axe","Rake"]', 1, 'A sickle is a hand-held tool with a curved blade used for cutting grasses or harvesting cereals like rice and wheat.', NULL, 'WAEC_Agric_2024.json', '6f99c6a3372a2df4d2711cad514143bfc87619a6979e534d64c651045978d914');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The purpose of a harvester is to _____.', '["apply fertilizer","cut and gather mature crops","shell maize grains","irrigate the field"]', 1, 'A harvester is a machine used to reap or cut and gather crops when they are ready.', NULL, 'WAEC_Agric_2024.json', 'f46188629b1b9ae900b82b46fbe6c18afe017c48fff89dbad528fbe0c8514d14');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which part of a tractor provides the power to drive stationary machinery like a thresher?', '["Steering wheel","Power Take-Off (PTO)","Hydraulic system","Drawbar"]', 1, 'The PTO is a shaft at the rear of a tractor that transfers engine power to drive implements or stationary machines.', NULL, 'WAEC_Agric_2024.json', '6e7915ef9192c442e3e7e43f96ebad4f89ec9e3e310c6a4deb56c52e5b79a5f4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The survey instrument used for measuring vertical angles is the _____.', '["Theodolite","Gunter''s chain","Prismatic compass","Measuring tape"]', 0, 'A theodolite is a precision instrument used for measuring both horizontal and vertical angles in farm surveying.', NULL, 'WAEC_Agric_2024.json', '1e19709e144e57567fec4a4401f30b1043e40ff4676c8d80fdc609412dcca788');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'In farm planning, the map that shows the layout of a farm, including buildings and plots, is the _____.', '["Topographical map","Farm layout","Soil map","Weather map"]', 1, 'A farm layout is a diagrammatic representation of the arrangement of all farm structures and enterprises on the land.', NULL, 'WAEC_Agric_2024.json', '14ab5f669c26d6892f2b72997b3cb1125b590bd82b94209e1d19294f07fbe960');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The application of water to the soil artificially to promote crop growth is _____.', '["Drainage","Mulching","Irrigation","Fertilization"]', 2, 'Irrigation is the artificial supply of water to land or crops to help growth, typically in dry areas or during periods of inadequate rainfall.', NULL, 'WAEC_Agric_2024.json', '380cef571e9309a00366a3ad14ee40a1c7d833c35e3babe53dffab5318511feb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following is a system of drainage?', '["Sprinkler","Drip","Cambered bed","Basin"]', 2, 'Cambered beds are raised areas that allow excess water to flow into side furrows, a form of surface drainage. Sprinkler and Drip are irrigation methods.', NULL, 'WAEC_Agric_2024.json', '0a895e1f2dd059b9199a29de42867ac2e3755f3c259ac5de80e8550c9cd66c8d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The type of irrigation where water is supplied to the base of each plant through pipes is _____.', '["Furrow irrigation","Overhead irrigation","Drip irrigation","Flood irrigation"]', 2, 'Drip (or trickle) irrigation is the most water-efficient method, delivering water directly to the root zone of plants.', NULL, 'WAEC_Agric_2024.json', '6acb5e529ef9bf021656c38ed5bef4da9062358e966705d69f989dd37c561caf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The removal of excess water from the farm land is known as _____.', '["Irrigation","Drainage","Evaporation","Transpiration"]', 1, 'Drainage is the process of removing excess water from the soil surface or sub-surface to prevent waterlogging.', NULL, 'WAEC_Agric_2024.json', '1804ae9de1370904621d65bddaeece1c6a716bec08e942578d8026d17dc491e3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The botanical name for maize is _____.', '["Oryza sativa","Zea mays","Vigna unguiculata","Manihot esculenta"]', 1, 'Zea mays is the scientific name for maize. Oryza sativa is rice, Vigna unguiculata is cowpea, and Manihot esculenta is cassava.', NULL, 'WAEC_Agric_2024.json', 'e3e8ee3bba07a158b6186d7734de0104fc6de1719ce00a2a556014c53a4a5cfb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following crops is a legume?', '["Sorghum","Groundnut","Yam","Millet"]', 1, 'Groundnut (peanut) belongs to the family Fabaceae, which are legumes known for their nitrogen-fixing capabilities.', NULL, 'WAEC_Agric_2024.json', '5410a6ad73a3cd360a9370638bf2faaffaa745728ccee73085e5e15b85cf91b2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The practice of growing only one type of crop on a piece of land at a time is _____.', '["Mixed cropping","Monocropping","Crop rotation","Intercropping"]', 1, 'Monocropping is the agricultural practice of growing a single crop year after year on the same land.', NULL, 'WAEC_Agric_2024.json', 'd3e0a67d7c459f99b6a11ef2c3f429222dc5456cae8c961fa976847f9f407c52');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'A nursery is essential for the production of _____.', '["Maize","Cocoa","Cowpea","Cassava"]', 1, 'Cocoa seeds are delicate and require controlled conditions in a nursery before being transplanted to the permanent field.', NULL, 'WAEC_Agric_2024.json', '599dca11932d80989366b8e0848446f272e2d35ad42aacf0739e0b9836f39a5c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The process of removing excess seedlings from a stand is known as _____.', '["Thinning","Supplying","Pruning","Mulching"]', 0, 'Thinning is the removal of some plants to give the remaining ones enough space and nutrients to grow properly.', NULL, 'WAEC_Agric_2024.json', '24c53adcd7cd8ecf581f7566444de9150a649d1b592dad442749f9c870c12332');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following is a storage pest of grains?', '["Aphid","Weevil","Grasshopper","Stem borer"]', 1, 'Weevils (e.g., maize weevil or bean weevil) are notorious for attacking and destroying stored grains and pulses.', NULL, 'WAEC_Agric_2024.json', 'c784bcb7ae4fcba51c4221bfff4ee4e06c46dbce1e3a7b523176e384909f88cc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The chemical used to kill weeds is called a/an _____.', '["Insecticide","Fungicide","Herbicide","Rodenticide"]', 2, 'Herbicides are chemical substances used to control or destroy unwanted plants (weeds).', NULL, 'WAEC_Agric_2024.json', '1fc466a356361b46a367371b46ded71d378003adccdde1bbb5920eb3af441dab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following crops is propagated by stem cuttings?', '["Yam","Maize","Cassava","Rice"]', 2, 'Cassava is typically propagated vegetatively using stem cuttings (stakes) about 20-25cm long.', NULL, 'WAEC_Agric_2024.json', 'ec5b11940187ddeef265043a10abbc1a062d47093af46d524a53043a101009d9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The ''Taungya system'' refers to the _____.', '["rearing of animals in the forest","integration of food crops with forest trees","burning of forests for hunting","use of chemicals to kill trees"]', 1, 'Taungya is an agroforestry system where farmers are allowed to plant food crops between young forest trees until the trees canopy closes.', NULL, 'WAEC_Agric_2024.json', 'c21b7168993ae2e7b4b7d97511ac4fa16e50b6475e6b2de62e9a02dead76bc67');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following is a fungal disease of crops?', '["Maize streak","Cassava mosaic","Rice blast","Citrus tristeza"]', 2, 'Rice blast, caused by Magnaporthe oryzae, is a devastating fungal disease. The others listed are viral diseases.', NULL, 'WAEC_Agric_2024.json', '372c46168d8b7b4729c868903258299e639c65c764f8cb612aff44496529da21');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The period between the mating of an animal and the birth of its young is _____.', '["Lactation period","Gestation period","Incubation period","Oestrus cycle"]', 1, 'Gestation is the time during which the embryo or fetus develops inside the mother''s womb.', NULL, 'WAEC_Agric_2024.json', '999c6496964a6c2b3b1f1b419d0220b70392734ba882bf7f4c2e8d3cb11a38a4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'A castrated male pig is called a _____.', '["Boar","Gilt","Sow","Barrow"]', 3, 'A boar is an intact male, a sow is a mature female, a gilt is a young female, and a barrow is a castrated male pig.', NULL, 'WAEC_Agric_2024.json', '7271245338842d1e8bd22641bdec261ee19a3c2ff235daf5ef17f503c9495173');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following animals is a ruminant?', '["Rabbit","Pig","Goat","Poultry"]', 2, 'Goats are ruminants because they have a four-compartment stomach (rumen, reticulum, omasum, abomasum) and chew the cud.', NULL, 'WAEC_Agric_2024.json', 'ad6a66aa514894a33206008cc8ea48ed03d6bac79d0cac119312b4b410d4bfbc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The first milk produced by a mother animal after parturition is called _____.', '["Whole milk","Skimmed milk","Colostrum","Pasteurized milk"]', 2, 'Colostrum is rich in antibodies (immunoglobulins) that provide passive immunity to the newborn animal.', NULL, 'WAEC_Agric_2024.json', '65a85a92f1bbaad884579bf8475eaf56e3114d9cdb607a20f13274ef126d8de0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following is an example of a concentrate feed?', '["Silage","Hay","Maize offal","Fresh grass"]', 2, 'Maize offal is a concentrate feed because it is low in fiber and high in energy/nutrients. Silage and hay are roughages.', NULL, 'WAEC_Agric_2024.json', 'edff922ebc7e59a1da7414126b664fbb30d2bcb15f3ef3b1bafd244c19ea664b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The part of the poultry digestive system where grinding of food occurs is the _____.', '["Crop","Proventriculus","Gizzard","Cloaca"]', 2, 'The gizzard (ventriculus) is a muscular organ that uses grit or small stones to grind food in birds.', NULL, 'WAEC_Agric_2024.json', '90ed160070353e0d8da5614e40eca788c287ca1fdcc240456a5d8cc38ae04a12');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Newcastle disease is a common viral disease affecting _____.', '["Cattle","Poultry","Pigs","Sheep"]', 1, 'Newcastle disease is a highly contagious and fatal viral disease of birds, especially domestic poultry.', NULL, 'WAEC_Agric_2024.json', 'da5640e6e2351ca54d5a9223437dedccbcc63e36f2d450219566342b9efbae59');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The process of removing the horns of an animal is known as _____.', '["Docking","Dehorning","Castration","Culling"]', 1, 'Dehorning (or disbudding in young animals) is done to prevent injury to other animals and handlers.', NULL, 'WAEC_Agric_2024.json', '62cccdf59245f9c028d70de36a6fea388ff718c835483b081813e10d60e97940');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Artificial insemination is the _____.', '["natural mating of animals","introduction of semen into the female reproductive tract by human intervention","killing of inferior male animals","feeding of animals with artificial hormones"]', 1, 'Artificial Insemination (AI) allows the use of high-quality semen from superior males to impregnate many females without physical contact.', NULL, 'WAEC_Agric_2024.json', '9116bc604ba699e2eb0164e7b490d54fe48de75884ea0eb869d363d328fd64e9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'An example of an ectoparasite of livestock is _____.', '["Tapeworm","Liver fluke","Tick","Roundworm"]', 2, 'Ticks live on the external surface (skin) of the host, making them ectoparasites. Tapeworms and flukes are endoparasites.', NULL, 'WAEC_Agric_2024.json', '33c6a45edf4e9d3975a9fdbbb73fe02b0d994ea974dcae221c2789fddf0a65d7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The law of diminishing marginal returns states that as more units of a variable input are added to a fixed input, the _____.', '["total product will decrease immediately","marginal product will eventually decrease","total product will remain constant","average product will always increase"]', 1, 'This fundamental economic law states that adding more of one factor of production while holding others constant will at some point yield lower per-unit returns.', NULL, 'WAEC_Agric_2024.json', '66fc72ebb7ca3df9e5137c4e253d0a02bbb1ace62618146650a7f732466dcb53');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'In agricultural marketing, the people who buy in bulk from farmers and sell to retailers are _____.', '["Consumers","Wholesalers","Producers","Processors"]', 1, 'Wholesalers act as middlemen who bridge the gap between large-scale production and small-scale retail.', NULL, 'WAEC_Agric_2024.json', 'e8263a30f03718fe456575175ad1ed4e75aebac6e2a85635d8fb1ac93091c148');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following is a fixed cost in a poultry enterprise?', '["Cost of feed","Cost of vaccines","Cost of poultry house construction","Wages of casual laborers"]', 2, 'Fixed costs do not change with the level of output. The building is a long-term investment (fixed), while feed and vaccines are variable costs.', NULL, 'WAEC_Agric_2024.json', '32fa8a701786823e04156f22a5239753d7c20ef82ecad5618d030fff122f83cb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'A farm record that shows the day-to-day activities on the farm is the _____.', '["Farm inventory","Cash book","Farm diary","Labour record"]', 2, 'A farm diary or logbook is used to record daily observations, operations, and events on the farm.', NULL, 'WAEC_Agric_2024.json', '2aad41c8bcb39b8bf1f7f30fc463fd6433002c1a859fde98ef8e1df1f3598b4a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Agricultural extension aims at _____.', '["distributing free tractors to all farmers","teaching farmers modern farming techniques","buying all farm produce at fixed prices","imposing taxes on rural dwellers"]', 1, 'Agricultural extension is an educational process that disseminates scientific information and new technologies to farmers to improve productivity.', NULL, 'WAEC_Agric_2024.json', '4a639fb45add63aeb1df74c7bfb296d38cc93b577e91d38b64a536470d699c97');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The use of posters and radio programs to reach farmers is an example of _____.', '["Individual contact method","Group contact method","Mass contact method","Result demonstration"]', 2, 'Mass contact methods are used to reach a large, diverse audience simultaneously.', NULL, 'WAEC_Agric_2024.json', '63cde9788102ae3d07a0b99831d74b941a613b680e0f605d539b815e6129719b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following is a source of farm credit?', '["Money lenders","Agricultural banks","Cooperative societies","All of the above"]', 3, 'Farmers can obtain credit from both formal sources (banks, cooperatives) and informal sources (money lenders).', NULL, 'WAEC_Agric_2024.json', '57409605b2e17b0fcb0816a1969f3bc5075b7738e3d4c8f9d5eff8ca5b478127');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The total value of assets minus the total value of liabilities of a farm is the _____.', '["Gross margin","Net worth","Net income","Variable cost"]', 1, 'Net worth (or Equity) represents the owner''s stake in the business after all debts have been settled.', NULL, 'WAEC_Agric_2024.json', 'd3048d5b6e2b1ff2b53c9d28144029176bb8a5b400da72288a96aa049e2a1b43');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'A market situation with only one seller is called _____.', '["Monopoly","Oligopoly","Monopsony","Perfect competition"]', 0, 'A monopoly exists when a single individual or organization is the sole supplier of a particular commodity or service.', NULL, 'WAEC_Agric_2024.json', '91a848b224fabfb7be0de8312c19bc7a5b1779d34f6677351884ef3af5262e29');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The function of a farm manager which involves looking into the future and setting goals is _____.', '["Organizing","Planning","Coordinating","Directing"]', 1, 'Planning is the primary management function that involves deciding in advance what to do, how to do it, and who is to do it.', NULL, 'WAEC_Agric_2024.json', 'f2ceae26f25cbb0bb6f0a8eccb523871685d7cd57c6b8932342b0e4de260e587');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The type of rock formed from the accumulation of sediments over time is _____.', '["Igneous rock","Sedimentary rock","Metamorphic rock","Volcanic rock"]', 1, 'Sedimentary rocks are formed by the deposition and subsequent cementation of mineral or organic particles.', NULL, 'WAEC_Agric_2024.json', '28f31e1c8de7a22bbf00c338dc4a2d046dc2dd6ed12a52d6fbdd8ec9cd083ada');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Soil texture refers to the _____.', '["arrangement of soil particles","relative proportion of sand, silt, and clay","ability of soil to support life","color of the soil"]', 1, 'Texture is an inherent property of soil determined by the size distribution of its mineral particles.', NULL, 'WAEC_Agric_2024.json', '70f7b2505abcefbbdd2d5b2a2b6db7dfade2f3fc82fe03f1808bf1e9e7e12ec5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following organisms is a soil macro-fauna?', '["Bacteria","Fungi","Earthworm","Protozoa"]', 2, 'Earthworms are large enough to be seen with the naked eye (macro-fauna), whereas bacteria and fungi are micro-organisms.', NULL, 'WAEC_Agric_2024.json', '8cbabb4093053ecee82161a288be2d03a4ce4a97e6b187cc3e9cee33457402f1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'In the nitrogen cycle, the conversion of ammonia to nitrates is called _____.', '["Nitrogen fixation","Nitrification","Denitrification","Ammonification"]', 1, 'Nitrification is a two-step biological process where ammonia is oxidized to nitrite and then to nitrate by specific bacteria (Nitrosomonas and Nitrobacter).', NULL, 'WAEC_Agric_2024.json', '8533ea23332fbe08edcd8bef07d3d47bb40cb8f670e7560c1ecdb09a711f2f77');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following is a physical property of soil?', '["Cation exchange capacity","Soil structure","Organic matter content","Mineral nutrient levels"]', 1, 'Soil structure refers to the way soil particles are grouped together into aggregates (peds).', NULL, 'WAEC_Agric_2024.json', '2ceacae70c3fe35f7af31bf8c77a46a947d5c981743c62c2c5cb37cd3ee972af');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The primary objective of soil conservation is to _____.', '["increase the depth of the soil","maintain soil fertility and prevent erosion","change the soil texture","remove all living organisms from the soil"]', 1, 'Soil conservation involves practices aimed at protecting soil from degradation and ensuring its long-term productivity.', NULL, 'WAEC_Agric_2024.json', '18080867509b0268503802fd7361dd44cc39fce018276b84bd1485cde9b2133b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Green manuring involves _____.', '["applying urea to the field","ploughing under green, succulent crops into the soil","using animal dung","painting the soil green"]', 1, 'Green manure crops (usually legumes) are grown and incorporated into the soil while still green to improve organic matter and nitrogen content.', NULL, 'WAEC_Agric_2024.json', 'd13c9eb3f5079b42dced7e3fa3df9342c86b6e18552f286711a0980109d3e466');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following irrigation methods is most wasteful of water?', '["Drip irrigation","Sprinkler irrigation","Flood irrigation","Canal irrigation"]', 2, 'Flood irrigation involves covering the entire field with water, leading to high losses through evaporation and deep percolation.', NULL, 'WAEC_Agric_2024.json', '2c22eff29777f0aa43a5ebf6c04bf5833ed57cc5cccc496ddb0091cf4d7d31b4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'A soil with high capillarity _____.', '["allows water to drain away very quickly","allows water to rise easily through small pores","cannot hold any water at all","is always sandy in nature"]', 1, 'Capillarity is the ability of water to move upwards against gravity in narrow spaces, which is highest in clayey soils due to small pore sizes.', NULL, 'WAEC_Agric_2024.json', '23fd97a92ca4abf0682eed5acfd0ecc29d0ecf33994036471f2445d35d21fd9d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Organic matter in the soil is primarily derived from _____.', '["weathered rocks","decomposed plants and animals","chemical fertilizers","rainfall"]', 1, 'Organic matter (humus) is formed from the biological decomposition of residues of plants and animals.', NULL, 'WAEC_Agric_2024.json', 'b80c113b4c2595599c3ed20b2d9265439cada44dd50e090f2cf6eacf9ea251c0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The term ''monandry'' in animal breeding refers to _____.', '["mating one male with many females","mating one female with only one male","mating many males with one female","preventing animals from mating"]', 1, 'Monandry is a mating system where a female has only one mate at a time.', NULL, 'WAEC_Agric_2024.json', '5cf5dadf97e290c69485b956d4371a389bc246dc46b31b23aa6a2f342bc2cca7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following is a symptom of vitamin A deficiency in livestock?', '["Scurvy","Night blindness","Rickets","Anemia"]', 1, 'Vitamin A is essential for vision; its deficiency leads to xerophthalmia or night blindness. Rickets is due to Vitamin D deficiency.', NULL, 'WAEC_Agric_2024.json', 'b206f82e7c4c755e9c62a6399a96c088687619ad9ca6e3b1f8337e994d365ce8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The process of egg-laying in poultry is called _____.', '["Parturition","Oviposition","Incubation","Hatching"]', 1, 'Oviposition is the technical term for the act of laying an egg.', NULL, 'WAEC_Agric_2024.json', '46b3903b769972303c5790ac98e5367439e6ea60447078cd1a422a6521875c6d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'In Mendelian inheritance, a cross between two heterozygous (Tt) tall plants will result in a phenotypic ratio of _____.', '["1:1","3:1","9:3:3:1","1:2:1"]', 1, 'The cross Tt x Tt results in offspring: TT (Tall), Tt (Tall), Tt (Tall), and tt (Dwarf). Phenotypically, that is 3 Tall to 1 Dwarf.', NULL, 'WAEC_Agric_2024.json', '50630b66d814631874f748fb6a679cec888ec4f0e1fb32fae21401b0b20bd414');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The study of the relationship between living organisms and their environment is _____.', '["Agronomy","Pathology","Ecology","Entomology"]', 2, 'Ecology focuses on how organisms interact with each other and their physical surroundings.', NULL, 'WAEC_Agric_2024.json', '068040929117401ea0df150ef7dd7c56a2c7ece799d27ac61e5a4023783cca71');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following is a function of the liver in animals?', '["Production of insulin","Storage of glycogen and vitamins","Pumping of blood","Gaseous exchange"]', 1, 'The liver plays a vital role in metabolism, including the storage of glucose as glycogen and the detoxification of chemicals.', NULL, 'WAEC_Agric_2024.json', 'bc9428499820ea67e8412072672ca3c5856b4da9764cf076ba44f570962f5710');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The method of selecting animals for breeding based on the performance of their ancestors is _____.', '["Pedigree selection","Progeny testing","Individual selection","Mass selection"]', 0, 'Pedigree selection relies on the records of the parents, grandparents, and other ancestors.', NULL, 'WAEC_Agric_2024.json', '6f79caf7c8f20a5c6567a408ab93acc7b4119efff460b8030388356aacbeed91');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The primary advantage of zero-grazing (stall feeding) is that it _____.', '["allows animals to exercise freely","reduces the risk of parasite infestation","is cheaper than ranching","requires no specialized equipment"]', 1, 'In zero-grazing, fodder is brought to the animals. This prevents them from picking up worms or ticks from the pasture.', NULL, 'WAEC_Agric_2024.json', '3c6666b0b215feb90164cf890378eae76379653b4607414d66fb9cf770a97693');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'Which of the following is an example of a bi-sexual (hermaphrodite) animal?', '["Snail","Chicken","Cattle","Sheep"]', 0, 'Many land snails are hermaphrodites, possessing both male and female reproductive organs.', NULL, 'WAEC_Agric_2024.json', '53c9bc107acbd173b378dd0e4bb5ba7074cdb25f40b22d85bc1fd70501cd772a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Agric', 2024, NULL, 'The act of giving birth in rabbits is called _____.', '["Farrowing","Kindling","Kidding","Lambing"]', 1, 'Kindling is parturition in rabbits. Farrowing is for pigs, kidding for goats, and lambing for sheep.', NULL, 'WAEC_Agric_2024.json', 'f01d48aeb2c88d7f1480a843115c3233512549b4e215166cf630cb1631e65a54');
