INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The basic unit of classification of living things is the _____.', '["Genus","Species","Phylum","Kingdom"]', 1, 'Species is the lowest and most basic unit of classification, consisting of organisms that can interbreed to produce fertile offspring.', NULL, 'WAEC_Biology_2024.json', 'b901dcd39a7db976a385a20d45476c59d56893e78cbc4ca2a42eaec4af6084c2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following organelles is known as the powerhouse of the cell?', '["Nucleus","Ribosome","Mitochondrion","Chloroplast"]', 2, 'The mitochondrion is where aerobic respiration occurs, generating ATP which provides energy for cellular activities.', NULL, 'WAEC_Biology_2024.json', '33b8833c0c7a9d07cf539f283735554f292914a20481f047cf1fd269398d8621');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The movement of water molecules from a region of higher concentration to a region of lower concentration through a semi-permeable membrane is _____.', '["Diffusion","Osmosis","Active transport","Plasmolysis"]', 1, 'Osmosis specifically refers to the movement of solvent (water) across a selectively permeable membrane.', NULL, 'WAEC_Biology_2024.json', 'e375203e432b1143ac3681234069396925dec2ff641b375381713ad13431500f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of these organisms exhibits holozoic nutrition?', '["Mushroom","Amoeba","Spirogyra","Tapeworm"]', 1, 'Amoeba engulfs solid food particles (phagocytosis), which is a characteristic of holozoic nutrition.', NULL, 'WAEC_Biology_2024.json', '21c9b644182f193e9fa4a3017bf27d314d3295ccb12c8ff11b8a8315351cd206');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The enzyme in the saliva that starts the digestion of starch is _____.', '["Pepsin","Rennin","Ptyalin","Lipase"]', 2, 'Ptyalin (salivary amylase) breaks down cooked starch into maltose in the mouth.', NULL, 'WAEC_Biology_2024.json', '2d8fa831be73aac98f09ce72f6fb2291e07a68db462330178d5de5cd451822ed');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following is a function of the liver?', '["Production of insulin","Storage of iron","Filtration of urea","Production of digestive enzymes"]', 1, 'The liver stores iron from the breakdown of old red blood cells. Insulin is produced by the pancreas.', NULL, 'WAEC_Biology_2024.json', '9fa92f5168e3d957f98d601782253fe0b51eb51fdb40624fdb2eb3d867382c8c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'In photosynthesis, the light-dependent reaction occurs in the _____.', '["Stroma","Grana","Cytoplasm","Nucleolus"]', 1, 'The chlorophyll needed to trap light energy is located in the thylakoid membranes which make up the grana.', NULL, 'WAEC_Biology_2024.json', '8352921e3e63986ab48fc415847963fd5cc9d26b17e6ac6b7ef8fd7a7e703c21');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The deficiency of Vitamin K leads to _____.', '["Night blindness","Beri-beri","Scurvy","Poor blood clotting"]', 3, 'Vitamin K is essential for the synthesis of prothrombin, a protein necessary for blood coagulation.', NULL, 'WAEC_Biology_2024.json', '6feeb116876c3690bd4f15727d40af6b0e30e258475621a4d1061e48d60efd44');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which part of the brain is responsible for the maintenance of posture and balance?', '["Cerebrum","Cerebellum","Medulla oblongata","Hypothalamus"]', 1, 'The cerebellum coordinates muscular activities and maintains body equilibrium and posture.', NULL, 'WAEC_Biology_2024.json', '2d14d61fc09ab566a2156acb2a417e83388228b4f7e0674df55993c75039de5e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The structural and functional unit of the nervous system is the _____.', '["Nephron","Neuron","Axon","Dendrite"]', 1, 'Neurons are the specialized cells that transmit nerve impulses throughout the body.', NULL, 'WAEC_Biology_2024.json', '46d8610d2507c85bb8ef13873856e963d0df13b0e3bfd08effa41139982481d7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The type of joint found at the shoulder and hip is the _____.', '["Hinge joint","Suture joint","Ball and socket joint","Gliding joint"]', 2, 'Ball and socket joints allow for rotational movement in many directions.', NULL, 'WAEC_Biology_2024.json', '4b0f27dee28e7714450a484f8126f420906f1f2bb5bda04cd79d052aae2f4ff3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following is an excretory organ in insects?', '["Flame cells","Nephridia","Malpighian tubules","Contractile vacuole"]', 2, 'Malpighian tubules remove nitrogenous wastes from the hemolymph of insects.', NULL, 'WAEC_Biology_2024.json', '57ff3cd874c1b8f1340e2cd1ca5910edc68d321260788c44c40856ebf94aa356');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The gaseous exchange in terrestrial insects occurs through the _____.', '["Gills","Lungs","Tracheal system","Cell membrane"]', 2, 'Insects use a system of tubes called tracheae that open to the outside via spiracles for gas exchange.', NULL, 'WAEC_Biology_2024.json', '6db8ffd6f11cb9d63c22337f9946a6533fbaace1967537c12e1b86bd391b042e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following blood cells is responsible for the transport of oxygen?', '["Leucocytes","Thrombocytes","Erythrocytes","Phagocytes"]', 2, 'Erythrocytes (red blood cells) contain hemoglobin which binds to and transports oxygen.', NULL, 'WAEC_Biology_2024.json', '8c53e7f671eac71af3d6a82b9c0e7de4e2f8f5e5846445a3646b770feac25883');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The process by which plants lose water in the form of vapor through the stomata is _____.', '["Guttation","Transpiration","Evaporation","Osmosis"]', 1, 'Transpiration is the loss of water vapor from the aerial parts of plants, mainly through the leaves.', NULL, 'WAEC_Biology_2024.json', '875510624ce112725c1eac17d3092a15a4964422e3763268463d3f58b5592cde');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'A person with blood group AB is called a universal recipient because _____.', '["They lack antigens A and B","They have both antibodies a and b","They lack antibodies in the plasma","They have Antigen O"]', 2, 'Blood group AB has no anti-A or anti-B antibodies in the plasma, so it can receive blood from any other group without agglutination.', NULL, 'WAEC_Biology_2024.json', 'eb61cc98854678fbd9b8a19ae14363670c5d013a2aead970c4ae5e68cb7c1e1f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The hormone that regulates the blood sugar level is _____.', '["Adrenaline","Thyroxine","Insulin","Auxin"]', 2, 'Insulin, produced by the Islets of Langerhans in the pancreas, lowers blood glucose levels.', NULL, 'WAEC_Biology_2024.json', '330f600fc111cea2f7b9742c2d9587d9d742a13bf65a63e45904637ff9cb0e82');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The phenotype of an individual is defined as the _____.', '["Genetic makeup","Physical appearance","Number of chromosomes","Allele frequency"]', 1, 'Phenotype refers to the observable characteristics resulting from the interaction of the genotype and the environment.', NULL, 'WAEC_Biology_2024.json', 'c7d0557e4e2a042777cea684d92476b45a7a097d799d67c2b83285fe4718fa2f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'In a cross between a homozygous tall plant (TT) and a homozygous dwarf plant (tt), the F1 generation will be _____.', '["All dwarf","All tall","50% tall, 50% dwarf","75% tall, 25% dwarf"]', 1, 'The cross TT x tt results in all offspring having the genotype Tt. Since Tall (T) is dominant, all will appear tall.', NULL, 'WAEC_Biology_2024.json', '43d7ec01def47ebbce7a07df9845ea55df23fd04ba5a0e28b87fae3ecbbef667');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of these is a vestigial organ in humans?', '["Appendix","Liver","Pancreas","Kidney"]', 0, 'The vermiform appendix is considered vestigial because it has lost its primary function in human digestion compared to ancestors.', NULL, 'WAEC_Biology_2024.json', 'b38b9970c2547140011125f50bcd2c48d9b4d2732bd0d616891d9238fc91e46a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The sequence of energy flow in an ecosystem is _____.', '["Producer -> Herbivore -> Carnivore","Producer -> Carnivore -> Herbivore","Herbivore -> Producer -> Carnivore","Carnivore -> Herbivore -> Producer"]', 0, 'Energy flows from primary producers (plants) to primary consumers (herbivores) and then to secondary consumers (carnivores).', NULL, 'WAEC_Biology_2024.json', 'd7b6b243cd2ff8de1dfe20c3cc5d9068071341563a3682e7ffaf073e2f2eacfe');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following is a biotic factor in an ecosystem?', '["Temperature","Soil pH","Predation","Rainfall"]', 2, 'Biotic factors are living components; predation involves interactions between living organisms.', NULL, 'WAEC_Biology_2024.json', 'd1e725f7cbd1043da868b37c8f9b808c8cd1ee45946b8f511928120f36796272');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The process by which nitrogen in the air is converted into nitrates by bacteria is _____.', '["Nitrification","Nitrogen fixation","Denitrification","Putrefaction"]', 1, 'Nitrogen fixation is the conversion of atmospheric nitrogen into compounds like ammonia or nitrates by bacteria like Rhizobium.', NULL, 'WAEC_Biology_2024.json', '1800d70ca27d4be3f196a13488b902eddaf086e48236d00c4d58e062a443d016');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following is a dry indehiscent fruit?', '["Legume","Capsule","Caryopsis","Schizocarp"]', 2, 'Caryopsis (e.g., maize grain) is a dry fruit that does not split open (indehiscent) when ripe.', NULL, 'WAEC_Biology_2024.json', '46da7d741a5199cbe0146433f18ab6c80c9ef48ba072237f71dfddb0d7605919');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The part of the flower that develops into a seed after fertilization is the _____.', '["Ovary","Ovule","Stigma","Style"]', 1, 'The ovule becomes the seed, while the ovary becomes the fruit.', NULL, 'WAEC_Biology_2024.json', '56a9105833fd596fd5c495f65db3a559b54d9db42056a22bdec70aa24502f2e7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Anaerobic respiration in yeast produces _____.', '["Lactic acid and Energy","Ethanol and Carbon dioxide","Water and Carbon dioxide","Glucose and Oxygen"]', 1, 'In yeast, fermentation (anaerobic respiration) yields ethanol (alcohol) and CO2.', NULL, 'WAEC_Biology_2024.json', 'c4aaa72a7a7dc6e759e8309a29d2e6791f161b5d9e8114bf9841dbc01b33475a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The instrument used to measure the rate of transpiration is the _____.', '["Photometer","Potometer","Hygrometer","Anemometer"]', 1, 'A potometer measures the rate of water uptake, which is almost equal to the rate of transpiration.', NULL, 'WAEC_Biology_2024.json', '755eccf9fa05ad1c4662c2a3dcebd0ef08307e59abddc02c92b5c9255fb72ad5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of these is a function of the skeleton?', '["Digestion","Protection of delicate organs","Excretion","Nerve impulse transmission"]', 1, 'The skeleton (e.g., skull, ribs) protects organs like the brain, heart, and lungs.', NULL, 'WAEC_Biology_2024.json', 'a39ae273b1782f5d8c9144ac31cce5d0b0743d64624fd716f338f9d2dd3c627a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The functional unit of the kidney is the _____.', '["Ureter","Nephron","Bladder","Cortex"]', 1, 'The nephron is the microscopic structure responsible for filtration, reabsorption, and urine formation.', NULL, 'WAEC_Biology_2024.json', '9453ef6d997a99a1d43d90986562e58ad9898b295cb4cf86fe0768bc225679a5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following is an example of continuous variation?', '["Blood groups","Tongue rolling","Height","Sex"]', 2, 'Height shows a range of values with no distinct categories, which is characteristic of continuous variation.', NULL, 'WAEC_Biology_2024.json', 'bc6ce2d6ca63b64e3dee3c80e87bd2f32f43f8ac7a1ffe5e1206473baccb2679');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The symbiotic relationship between a fungus and an alga is known as _____.', '["Mycorrhiza","Lichen","Commensalism","Parasitism"]', 1, 'Lichen is a mutualistic association where the alga provides food and the fungus provides shelter and water.', NULL, 'WAEC_Biology_2024.json', '8570d62d2bed2466891e69c6f61be32d5d8899ca95c77e33c87d1f0ac1a43f74');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'A group of similar cells performing a specific function is called a/an _____.', '["Organ","System","Tissue","Organism"]', 2, 'Tissues are collections of similar cells that work together to perform a specific task (e.g., muscle tissue).', NULL, 'WAEC_Biology_2024.json', '41cbcb482cdddef0a7fa887d5bac0c8014a0883ae4aa76029b93adf18d45bd95');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The site of lipid synthesis in the cell is the _____.', '["Rough Endoplasmic Reticulum","Smooth Endoplasmic Reticulum","Golgi apparatus","Lysosome"]', 1, 'The Smooth ER is primarily involved in the synthesis of lipids and steroids, unlike the Rough ER which has ribosomes for protein synthesis.', NULL, 'WAEC_Biology_2024.json', '1de5936116a26639f0aa567d088ebca23f938af1dc3b4ee6a9bbe7642550c92c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following is a characteristic of wind-pollinated flowers?', '["Large brightly colored petals","Sticky pollens","Long feathery stigmas","Presence of nectar"]', 2, 'Feathery stigmas provide a large surface area to catch pollen grains blowing in the wind.', NULL, 'WAEC_Biology_2024.json', 'dad0382e6504e3caee42912bdd0e1457736888b0843a9aecca561703660dc917');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The mammalian heart is described as myogenic because _____.', '["It is controlled by nerves","The contraction starts within the muscle itself","It requires oxygen","It has four chambers"]', 1, 'Myogenic means the heartbeat originates in the muscle tissue (SA node) rather than being initiated by external nerve impulses.', NULL, 'WAEC_Biology_2024.json', '851b703ef01f2ba71e3d461ad18989f9dac6ea2ea5dd10b5e1c18ae368444744');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following is a polysaccharide?', '["Glucose","Sucrose","Cellulose","Fructose"]', 2, 'Cellulose is a complex carbohydrate made of many glucose units. Glucose and fructose are monosaccharides; sucrose is a disaccharide.', NULL, 'WAEC_Biology_2024.json', '0b8ac0b11bcbee14bfbaa843cceaefdb1e24ac15a1e752f0a2696bc788543a88');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The process of maintaining a constant internal environment is _____.', '["Metabolism","Homeostasis","Osmoregulation","Thermoregulation"]', 1, 'Homeostasis involves various mechanisms that keep the body''s internal conditions (temperature, pH, water) stable.', NULL, 'WAEC_Biology_2024.json', '5af7442a115d00498ef85c9fdf0f0fe249f09a4c06fc97ff783c1da689dc0a98');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The hormone that stimulates the ''fight or flight'' response is _____.', '["Thyroxine","Adrenaline","Estrogen","Prolactin"]', 1, 'Adrenaline (epinephrine) is released by the adrenal glands during stress to prepare the body for immediate action.', NULL, 'WAEC_Biology_2024.json', '9ea86a8136a3c64d2031e7eaec6c66ca10072e17a5f3b9e7cb8bc1270043dfa4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following is a function of the amniotic fluid?', '["Exchange of gases","Protection against shock","Supply of nutrients","Removal of waste"]', 1, 'Amniotic fluid acts as a cushion/shock absorber for the developing fetus.', NULL, 'WAEC_Biology_2024.json', 'ea552a3754d080c3b948e7ca20e69aa291255f3d9688022b5e2d92d658df9bd2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The part of the eye that contains light-sensitive cells is the _____.', '["Sclera","Choroid","Retina","Iris"]', 2, 'The retina contains photoreceptors (rods and cones) that convert light into nerve impulses.', NULL, 'WAEC_Biology_2024.json', '3bd74a4b5712eb7778c99e26d0ad33424d58161f8917974eb8194b3193f98303');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Plants that are adapted to live in dry habitats are called _____.', '["Hydrophytes","Mesophytes","Xerophytes","Halophytes"]', 2, 'Xerophytes have adaptations like thick cuticles and sunken stomata to conserve water in arid conditions.', NULL, 'WAEC_Biology_2024.json', '6d1946ae5a02c5933c39832f58417a283336bfdff2581f7d57ed93cd1b5f8b35');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The theory of use and disuse was proposed by _____.', '["Charles Darwin","Jean Lamarck","Gregor Mendel","Alfred Wallace"]', 1, 'Lamarck suggested that organs used frequently become more developed, while those not used degenerate.', NULL, 'WAEC_Biology_2024.json', 'a23c1b9fb6eba1aa05bcb9eb56e14c79686866c8e49238b384fce19eef94f8e1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following is a social insect?', '["Housefly","Mosquito","Termite","Cockroach"]', 2, 'Termites live in colonies with a division of labor (queen, king, soldiers, workers).', NULL, 'WAEC_Biology_2024.json', '263794d311a483c2d646724ba761f300ff5734b2e1d3fa72202f795899bbde80');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The dental formula of an adult human is _____.', '["2:1:2:3 / 2:1:2:3","2:1:0:2 / 2:1:0:2","3:1:4:3 / 3:1:4:3","2:1:3:3 / 2:1:3:3"]', 0, 'The human adult dental formula (half of each jaw) is 2 Incisors, 1 Canine, 2 Premolars, and 3 Molars.', NULL, 'WAEC_Biology_2024.json', '0e17b450d3a54f4262218cd55a2568f98f9a82413572ab59dbbcb9726ca0d3d4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The type of placentation found in a tomato fruit is _____.', '["Marginal","Parietal","Axile","Free-central"]', 2, 'In axile placentation, the carpels are fused and the ovules are attached to the central axis of a multi-locular ovary.', NULL, 'WAEC_Biology_2024.json', 'c4d5ed509ef3116af23a0781cf76b71ad1b8892192c40b608af6617c905fdadf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following is NOT a characteristic of a respiratory surface?', '["Thin membrane","Moist surface","Small surface area","Rich blood supply"]', 2, 'A large surface area is required for efficient gas exchange, not a small one.', NULL, 'WAEC_Biology_2024.json', '21ffdb8ae212895fde66e066dde8165ec2ae5cb7f2827faf78f1df7ab1f7307c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The movement of plant parts in response to the direction of a light stimulus is _____.', '["Phototropism","Phototaxis","Photonasty","Hydrotropism"]', 0, 'Phototropism is a growth movement where the direction is determined by the direction of light.', NULL, 'WAEC_Biology_2024.json', 'da74946aaaada25d686dc33edc25a02c79f922e0062fc09febd16099cd5fef7a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The primary structure for hearing in the mammalian ear is the _____.', '["Pinna","Ossicles","Cochlea","Semicircular canals"]', 2, 'The cochlea contains the Organ of Corti, which converts sound vibrations into nerve impulses.', NULL, 'WAEC_Biology_2024.json', '753f90591234a884be0203bcfc723d8e09f0fb421d46f3c9028e6d43a7fe809e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'In the process of succession, the first organisms to colonize a bare rock are called _____.', '["Climax community","Pioneer species","Secondary consumers","Seral stages"]', 1, 'Pioneer species (like lichens) are the first to inhabit a previously uncolonized area.', NULL, 'WAEC_Biology_2024.json', '3956c6e11c806defbefda8c9c115b7f87232509e9ff4b7db80bcd0a4a4e73289');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'A lack of iodine in the diet leads to the swelling of the neck known as _____.', '["Rickets","Scurvy","Goiter","Anemia"]', 2, 'Iodine is needed for thyroxine production; without it, the thyroid gland enlarges (goiter).', NULL, 'WAEC_Biology_2024.json', 'd427f9ed6300bb9a3e11d715a75187d682238654ef90bc13f9d501665e417898');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The stage of mitosis where chromosomes align at the equator of the cell is _____.', '["Prophase","Metaphase","Anaphase","Telophase"]', 1, 'During metaphase, spindle fibers pull chromosomes to the center (equatorial plate).', NULL, 'WAEC_Biology_2024.json', '621a6caf64a2b8dd43ad39aeb8ee3daba83548e623188a82f9b08bd0c5212fb9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following is a product of excretion in plants?', '["Oxygen","Carbon dioxide","Tannins","All of the above"]', 3, 'Plants excrete oxygen (from photosynthesis), CO2 (from respiration), and secondary metabolites like tannins and resins.', NULL, 'WAEC_Biology_2024.json', '75aee59a517bf3f141997a2c38d2a392dd2c898b23f88da43504521aeaaefc3d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The part of the flower that receives pollen grains during pollination is the _____.', '["Anther","Filament","Stigma","Style"]', 2, 'The stigma is the sticky/feathery top of the carpel designed to catch pollen.', NULL, 'WAEC_Biology_2024.json', 'f1f069ef3731439d0693fa0936b1021121ab5e1972706d4cf624d972db1f44f0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The vector for the parasite Plasmodium is the _____.', '["Female Anopheles mosquito","Male Anopheles mosquito","Tsetse fly","Housefly"]', 0, 'Only the female Anopheles mosquito sucks blood and transmits the malaria parasite.', NULL, 'WAEC_Biology_2024.json', 'a497e088bdf5c77c61ca91076302f6856232bb64482e6437e08d6cba3e1caa61');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'A cell that is placed in a hypertonic solution will become _____.', '["Turgid","Flaccid","Plasmolysed","Swollen"]', 2, 'In a hypertonic solution (higher concentration), water leaves the cell, causing the cytoplasm to shrink away from the cell wall (plasmolysis).', NULL, 'WAEC_Biology_2024.json', '154a8c64426f54d39524a9ee8fc27e13cdb221401a4469f55679f5017b4df910');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The study of the relationship between a single species and its environment is _____.', '["Synecology","Autecology","Ecology","Ethology"]', 1, 'Autecology focuses on individual species, while synecology focuses on communities.', NULL, 'WAEC_Biology_2024.json', '66b885ae5af95004c74ec91eef5595ca5f0160be20f15d4eb30b9d9d46ae1725');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following is a sex-linked character?', '["Albinism","Color blindness","Sickle cell anemia","Polydactyly"]', 1, 'Color blindness is carried on the X-chromosome and is more common in males.', NULL, 'WAEC_Biology_2024.json', 'adc73de4ff49e54b55b43adc29b2dbeee19d0df95bd31dc94043ab217989b168');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The process by which complex food substances are broken down into simpler soluble forms is _____.', '["Absorption","Assimilation","Digestion","Egestion"]', 2, 'Digestion is the mechanical and chemical breakdown of food.', NULL, 'WAEC_Biology_2024.json', '6bbb9f1e9023c08f878533ac56b875822bb8bb5592c20d790cdd4ea783bd5627');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The blood vessel that carries deoxygenated blood from the heart to the lungs is the _____.', '["Aorta","Pulmonary vein","Pulmonary artery","Vena cava"]', 2, 'The pulmonary artery is the only artery that carries deoxygenated blood.', NULL, 'WAEC_Biology_2024.json', '502d7ab72e65751b27aa25636bf1f55f11c27e356f3c2b95ede10b6654d0d4a5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The small gap between two neurons where neurotransmitters are released is the _____.', '["Axon","Myelin sheath","Synapse","Node of Ranvier"]', 2, 'Impulses cross the synaptic cleft via chemical messengers called neurotransmitters.', NULL, 'WAEC_Biology_2024.json', '4cda7a0f6cfa8c6efb1d399a8aef791d98b46b4d8112b03af5a07a0f36f67853');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The vitamin that helps in the absorption of calcium in the body is _____.', '["Vitamin A","Vitamin B","Vitamin C","Vitamin D"]', 3, 'Vitamin D is essential for bone health as it facilitates calcium absorption from the gut.', NULL, 'WAEC_Biology_2024.json', '94646126377ebe428dada2391dd68c34726a3f3e78dd3a42728373edaf204606');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following is a kidney disease?', '["Hepatitis","Nephritis","Asthma","Diabetes insipidus"]', 1, 'Nephritis is the inflammation of the nephrons in the kidney.', NULL, 'WAEC_Biology_2024.json', 'c1f8ee51928b619350a4765217929ba4ed62d2c63616658e3a5b39d2a1ce797b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The enzyme pepsin acts on proteins in the _____.', '["Mouth","Stomach","Duodenum","Ileum"]', 1, 'Pepsin is secreted by gastric glands in the stomach and works best in acidic pH.', NULL, 'WAEC_Biology_2024.json', '9afd7183c09ab8b1722770eed9f5ba12b4726ab116c295d52a37b71977f79ef2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The green pigment found in plants that traps solar energy is _____.', '["Carotene","Xanthophyll","Chlorophyll","Anthocyanin"]', 2, 'Chlorophyll is the primary pigment responsible for photosynthesis.', NULL, 'WAEC_Biology_2024.json', '6dd4fc69737da62404a6c39eb68b28eb5a20966c063b2e8b77442dbe8dd70f1e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following is a function of the placenta?', '["Protection from mechanical injury","Exchange of materials between mother and fetus","Production of red blood cells","Movement of the fetus"]', 1, 'The placenta allows nutrients and oxygen to pass to the fetus and waste products to pass to the mother.', NULL, 'WAEC_Biology_2024.json', 'a86045a946e29ca23727f536b9d542c3562d5fccdad1abcfc87f8dac618455a1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The type of evolution where different species develop similar traits due to similar environments is _____.', '["Divergent evolution","Convergent evolution","Adaptive radiation","Parallel evolution"]', 1, 'Convergent evolution leads to analogous structures, like wings in birds and insects.', NULL, 'WAEC_Biology_2024.json', '76088dd853d8a6db9434f9f21fe7760a63301055973477e5fbe0954ce53e2906');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The maintenance of the osmotic pressure of blood is primarily the work of the _____.', '["Liver","Lungs","Kidney","Skin"]', 2, 'Kidneys regulate the amount of water and salts in the blood (osmoregulation).', NULL, 'WAEC_Biology_2024.json', '687867e0d2f8e42015b2d388e141721961a6ef135f4d37cc7bba8cda2e58c9ae');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'A food chain always begins with a/an _____.', '["Decomposer","Consumer","Producer","Omnivore"]', 2, 'Producers (autotrophs) are the foundation of any food chain as they capture energy from the sun.', NULL, 'WAEC_Biology_2024.json', 'f726c60175a968d161ee3179b490c32111c951c66c47f44d55e18a72da7d82f4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'The structure in the mammalian ear that is responsible for balance is the _____.', '["Cochlea","Eustachian tube","Semicircular canals","Ear drum"]', 2, 'The semicircular canals detect changes in head position and maintain equilibrium.', NULL, 'WAEC_Biology_2024.json', 'dc064271a41f819b125b5691e2e097b5c9927d2dba5ffbcd4a5477e44766c983');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2024, NULL, 'Which of the following describes the genotype of a female with Turner syndrome?', '["XXY","XYY","XO","XXX"]', 2, 'Turner syndrome is a chromosomal abnormality where a female has only one X chromosome (XO).', NULL, 'WAEC_Biology_2024.json', 'cf896ac78945c6a3475dd716c3d719183dd1989e91dc5aa47f106afafb8ba3cf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2025, NULL, 'The functional unit of life is:', '["Tissue","Organ","Cell","System"]', 2, NULL, NULL, 'WAEC_Biology_2025.json', '85f5cf662ffa48f9fea42aad0cd9ebd8df7137d8c5d3367230a8d0cd14b41835');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Biology', 2025, NULL, 'Which organelle produces energy?', '["Ribosome","Mitochondria","Nucleus","Vacuole"]', 1, NULL, NULL, 'WAEC_Biology_2025.json', 'fd53c3bc38079bc4285807188175d208a371a4b795f832d90890827574ab9f8d');
