INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'God''s sovereignty is best demonstrated in the creation story by His ability to _____.', '["use tools for creation","consult with angels","create by spoken word","rely on pre-existing matter"]', 2, 'God''s sovereignty is shown through ''Ex Nihilo'' creation—bringing things into existence simply by commanding them to be.', NULL, 'WAEC_CRS_2024.json', '5ccc722afaece69c206596372d9c801f304e9e96fabdd08b080ba73718971f26');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The primary reason why Joseph''s brothers hated him was because _____.', '["he was a dreamer","he was a shepherd","he was his father''s favorite","he was born in old age"]', 2, 'Genesis 37:3-4 states that because Israel loved Joseph more than all his other sons, the brothers hated him and could not speak peaceably to him.', NULL, 'WAEC_CRS_2024.json', 'f67595d8f38b689fde8277f876cc35050190e11d911636aa24ff52b5b7408b5b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'In the call of Abraham, God''s command to ''Go from your country...'' was a test of his _____.', '["patience","strength","faith","wealth"]', 2, 'Abraham''s departure for an unknown land demonstrated absolute trust and faith in God''s promise.', NULL, 'WAEC_CRS_2024.json', '5d7ad48abfee8000d3f550251bf7f032cf546443521bef3155b6e2e7dbf5e5f7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Moses was reluctant to lead the Israelites out of Egypt because he _____.', '["feared Pharaoh","was a slow speaker","loved Egypt","was too old"]', 1, 'In Exodus 4:10, Moses complained to God that he was ''slow of speech and of tongue''.', NULL, 'WAEC_CRS_2024.json', '18b9a3f762be657cb8df98fd5b0a88775d444e1dfd7461c063bb19a1c4fd76fb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The Egyptian king who ''did not know Joseph'' oppressed the Israelites because _____.', '["they were too poor","they were multiplying too fast","they worshipped a different God","they were planning a rebellion"]', 1, 'The King feared that the Israelites were becoming more numerous and powerful than the Egyptians (Exodus 1:9-10).', NULL, 'WAEC_CRS_2024.json', 'e65c5612a314eac43d05214e333bee9af91fa98f81ebe0e3d9fecab08cc7f3d8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The Tenth Plague that finally broke Pharaoh''s heart was the _____.', '["darkness","hail and fire","death of the first-born","locusts"]', 2, 'The death of every first-born in Egypt, including Pharaoh''s son, forced the King to release the Israelites.', NULL, 'WAEC_CRS_2024.json', 'd71334b58b420e974f25bc2293cea521577ef9b3210d59f44dd82c058625acb2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The Ten Commandments were given to Moses on Mount _____.', '["Nebo","Carmel","Sinai","Hermon"]', 2, 'Exodus 19-20 records the giving of the Decalogue (Ten Commandments) on Mount Sinai.', NULL, 'WAEC_CRS_2024.json', '0e01a0024fee236c7eb2433033206a9bf379302716ea459f0327b46dd29a1072');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The Ark of the Covenant was a symbol of God''s _____ among the Israelites.', '["judgment","presence","wealth","anger"]', 1, 'The Ark represented the dwelling place and the constant presence of God with His people.', NULL, 'WAEC_CRS_2024.json', '90914cde0b1542bde6e81afbfb2b930ef64e47025a3b4367611877c5e2dd4a2a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The first king of Israel was _____.', '["David","Saul","Solomon","Samuel"]', 1, 'Saul, the son of Kish, was anointed by Samuel as the first king following the people''s demand.', NULL, 'WAEC_CRS_2024.json', 'd39f6dfe8cb19e68f6d5c03f72a560fc69f4357badbc42832da7236485fe9a2a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'David''s refusal to kill Saul in the cave showed his _____.', '["fear of Saul","cowardice","respect for the Lord''s anointed","pity for an old man"]', 2, 'David believed that it was wrong to touch the ''Lord''s anointed'', regardless of Saul''s behavior.', NULL, 'WAEC_CRS_2024.json', '5046e4805e09a13a965c67d2ff445cc2e4549b439a258818b69c29e8250b7e7b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Solomon asked God for _____ to rule his people effectively.', '["wealth","long life","wisdom","victory over enemies"]', 2, 'At Gibeon, Solomon asked for a ''discerning heart'' (wisdom) to govern the vast people of Israel.', NULL, 'WAEC_CRS_2024.json', '444caaa1d4f255a1fcfadb677a07089d3b3ab835b7254daa1ec13356fd5c1411');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The prophet who challenged the 450 prophets of Baal on Mount Carmel was _____.', '["Elisha","Elijah","Amos","Hosea"]', 1, 'Elijah sought to prove that Yahweh is the only true God by calling down fire on the altar.', NULL, 'WAEC_CRS_2024.json', '3796d20d6c18ad304793abebe785d769bd90dbe81627bcea4d6cfa50a6d5f532');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Amos emphasized that true worship must be accompanied by _____.', '["many sacrifices","loud singing","justice and righteousness","strict fasting"]', 2, 'Amos 5:24 says, ''But let justice roll down like waters, and righteousness like an ever-flowing stream''.', NULL, 'WAEC_CRS_2024.json', 'a3cde417adab8bba17a6ffaa8acef57934f22e8d2ac278c88b05fe466d33d8d2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The message of Prophet Hosea focused primarily on the _____ of God.', '["judgment","unconditional love","holiness","wrath"]', 1, 'Hosea''s marriage to Gomer served as a metaphor for God''s steadfast love for unfaithful Israel.', NULL, 'WAEC_CRS_2024.json', '238405bc08d9bf5a1b4695c985a89cb31a90361893f0a0fbdcb1a039cb519cdc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Nebuchadnezzar was the king of _____ who destroyed Jerusalem.', '["Assyria","Persia","Babylon","Egypt"]', 2, 'Babylon, under Nebuchadnezzar, captured Jerusalem and took the Jews into exile.', NULL, 'WAEC_CRS_2024.json', '3c0366e474b2c4ee7dc648ae1812c7c679d498d3a381f8ef0f63856d07ad0343');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The wall of Jerusalem was rebuilt after the exile under the leadership of _____.', '["Ezra","Nehemiah","Zerubbabel","Daniel"]', 1, 'Nehemiah was the cupbearer who returned to Jerusalem specifically to lead the reconstruction of the walls.', NULL, 'WAEC_CRS_2024.json', '729592b9a6f78382c97f1e9ae3ca90ce511c0e9ebe8610e82df9e53d9003dad9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Daniel and his three friends refused to eat the King''s meat because it _____.', '["was too expensive","would make them fat","was defiled","tasted bad"]', 2, 'The food was likely offered to idols or was not prepared according to Jewish dietary laws (kosher).', NULL, 'WAEC_CRS_2024.json', '8df0ce4b480accee06fdece9fef492e50dcb00fc508c22571f7b0581978f140d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Jesus was born in Bethlehem during the reign of King _____.', '["Agrippa","Herod the Great","Philip","Antipas"]', 1, 'Herod the Great was the King of Judea at the time of Jesus'' birth and ordered the massacre of the innocents.', NULL, 'WAEC_CRS_2024.json', '3b33ee38c96e46133246f1e067b2d539f0add55226e5182fae78369933bfd4c5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The forerunner of Jesus was _____.', '["James","Peter","John the Baptist","Andrew"]', 2, 'John the Baptist was sent to ''prepare the way of the Lord'' and preach repentance.', NULL, 'WAEC_CRS_2024.json', '1cad954663db7f33159e95359938dd143a5397bf40503f7c088eb19e6e409edf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Jesus was baptized in River _____.', '["Nile","Jordan","Tigris","Euphrates"]', 1, 'John the Baptist baptized Jesus in the Jordan River to ''fulfill all righteousness''.', NULL, 'WAEC_CRS_2024.json', '33ad0e2745155d6dc59af9fe2ba255b1786cd093e7b0a76f332b8f9de0b7dc87');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'In the temptation of Jesus, the devil asked Him to turn stones into bread to test His _____.', '["patience","humanity/sonship","miraculous powers","holiness"]', 1, 'The temptation ''If you are the Son of God...'' was an attempt to make Jesus use His divine power for selfish physical needs.', NULL, 'WAEC_CRS_2024.json', '771135203b4d973660d9c41239333f02315c9d3a27f23b6c6c8454d91aae4268');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The first four disciples called by Jesus were _____.', '["tax collectors","soldiers","fishermen","shepherds"]', 2, 'Peter, Andrew, James, and John were all fishermen at the Sea of Galilee.', NULL, 'WAEC_CRS_2024.json', '4675363e4761ca1db94a456b8842c5c137ef862080aa21e92b9decd5e66bb29a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The miracle of the feeding of the five thousand demonstrated Jesus as the _____.', '["Bread of Life","Light of the World","Good Shepherd","True Vine"]', 0, 'This miracle is often linked to Jesus'' discourse on being the Bread that came down from heaven.', NULL, 'WAEC_CRS_2024.json', '340796696d4ba13a96154f1205b6a140c29b574d916d06b18ce76e6a790eafab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The parable of the Good Samaritan was told to explain the meaning of _____.', '["wealth","neighbor","salvation","prayer"]', 1, 'Jesus told it in response to a lawyer''s question: ''And who is my neighbor?''', NULL, 'WAEC_CRS_2024.json', '853cb42202b35209145a1af206a9ba6591683b3df0df49f863bc207f650b3537');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'In the parable of the Prodigal Son, the father''s reaction shows God''s _____.', '["sternness","forgiveness","indifference","unfairness"]', 1, 'The father running to meet the son illustrates God''s eagerness to forgive and restore repentant sinners.', NULL, 'WAEC_CRS_2024.json', 'dda0a9b0eef4c4d61ea5352bcc1fe3b1818847466db92dfb752c64eab41f0b9a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Jesus'' triumphal entry into Jerusalem was on a _____.', '["horse","chariot","donkey","camel"]', 2, 'Riding a donkey fulfilled the prophecy of Zechariah 9:9 and symbolized Jesus as a Prince of Peace, not a war-lord.', NULL, 'WAEC_CRS_2024.json', '7803a702dc2d2bc60e8f36a203c9be18f2cbbaed0e35f6e6784003ed507f3df5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The disciple who betrayed Jesus was _____.', '["Peter","Thomas","Judas Iscariot","Bartholomew"]', 2, 'Judas Iscariot betrayed Jesus to the chief priests for thirty pieces of silver.', NULL, 'WAEC_CRS_2024.json', '4f703dd5f4a01bd5ec8cfa9e9c94e1587f015e5ae740422c1f90956a91cbc019');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'At the Last Supper, the wine symbolized Jesus'' _____.', '["strength","suffering","blood of the new covenant","joy"]', 2, 'Jesus stated that the cup represented His blood, which was to be shed for the remission of sins.', NULL, 'WAEC_CRS_2024.json', '594a8ed89ef2ed2522d4b5364822c9f9ad93e9bc87485eaf3011da0abb1210d3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The Roman Governor who sentenced Jesus to death was _____.', '["Felix","Festus","Pontius Pilate","Gallio"]', 2, 'Pilate found no guilt in Jesus but succumbed to the pressure of the crowd to have Him crucified.', NULL, 'WAEC_CRS_2024.json', 'f9ae312f4b58ee3333067cc712ed10d8dd912b1986922e5ed5883ce0ea1d08d7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Jesus was crucified at a place called Golgotha, which means _____.', '["House of Bread","Place of the Skull","Garden of Sorrow","City of David"]', 1, 'Golgotha is an Aramaic word meaning ''Skull'', referring to the shape of the hill or its use as a site for executions.', NULL, 'WAEC_CRS_2024.json', 'aa9126d3b6804d35179f852a4ae7c6e8ccf5658beb3d1186331d9b1cc2f97258');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The first person to see the risen Christ according to Mark was _____.', '["Peter","John","Mary Magdalene","Martha"]', 2, 'Mark 16:9 records that Jesus appeared first to Mary Magdalene, out of whom He had cast seven demons.', NULL, 'WAEC_CRS_2024.json', '6b8f49fe0685a245f75df6695b0f9cd400a23bdbbef6be5c07546750053e07c6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The Great Commission instructs disciples to go and make disciples of _____.', '["Jews only","their families","all nations","their friends"]', 2, 'In Matthew 28:19, Jesus commanded the disciples to go and teach ''all nations''.', NULL, 'WAEC_CRS_2024.json', '3b66f4d332a8fb0c04ed0ac43588690f541adfad518f6ed565abf405e4a8995f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The Holy Spirit descended on the disciples on the day of _____.', '["Passover","Tabernacles","Pentecost","Purim"]', 2, 'Acts 2 describes the arrival of the Holy Spirit on the Day of Pentecost, 50 days after Easter.', NULL, 'WAEC_CRS_2024.json', '829d131664d51f4792132e59e8904c5768d1e2293c088da53bd38e0683d242d6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The first Christian martyr was _____.', '["James","Stephen","Paul","Barnabas"]', 1, 'Stephen was stoned to death for his witness to Christ, as recorded in Acts 7.', NULL, 'WAEC_CRS_2024.json', 'f2c0706eed11c0527d744fb5e6859e8e89b1527f0436f0f5287439b5e8d839bb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Saul of Tarsus was converted on the road to _____.', '["Jerusalem","Antioch","Damascus","Rome"]', 2, 'Saul was blinded by a great light and heard the voice of Jesus while traveling to Damascus to persecute Christians.', NULL, 'WAEC_CRS_2024.json', '4cf2e602589cb1671d556a2cb3d7092338f5b857bd5605984c3ed37183d5ee37');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The first place where believers were called Christians was _____.', '["Jerusalem","Antioch","Ephesus","Philippi"]', 1, 'Acts 11:26 notes that it was in Antioch that the name ''Christian'' first came into use.', NULL, 'WAEC_CRS_2024.json', '33bd8713f4f198bd7db6992573768cc21d285f0020a1296ee5bf9682304c89cc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The Jerusalem Council was held primarily to discuss _____.', '["poverty","circumcision of Gentiles","baptism","Paul''s authority"]', 1, 'Acts 15 records the debate over whether Gentile converts needed to be circumcised and follow the Law of Moses.', NULL, 'WAEC_CRS_2024.json', '224b89200870190fb08da2adddc137c49d4e8f40accb395cf7aad3c587ed15bb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'According to Paul in Galatians, the fruit of the Spirit includes the following EXCEPT _____.', '["love","joy","wisdom","patience"]', 2, 'Wisdom is listed as a ''gift'' of the Spirit in 1 Corinthians 12, while the others are listed as ''fruit'' in Galatians 5.', NULL, 'WAEC_CRS_2024.json', '35c669832f9b2266b41f6c28d5dd0be5f87bf2ed7e5cba8cca2888854466f59b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Paul''s letter to Philemon was an appeal for the pardon of _____.', '["Timothy","Onesimus","Titus","Silas"]', 1, 'Onesimus was a runaway slave who had become a Christian under Paul''s ministry.', NULL, 'WAEC_CRS_2024.json', '0968bb646ad9311c9deccf548a38cf9ba3c3c4b52dd80cdbc138722362f760a6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'James teaches that ''Faith without _____ is dead''.', '["prayers","works","fasting","preaching"]', 1, 'James 2:26 emphasizes that true faith must be reflected in practical actions.', NULL, 'WAEC_CRS_2024.json', '83323871d4a20b44a749b05ea40e19b8115da1a2dae1967c984d41f49d7d4049');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'In the Sermon on the Mount, Jesus called his followers the _____ of the earth.', '["salt","gold","water","kings"]', 0, 'Jesus used ''salt'' and ''light'' to describe the transformative influence Christians should have on society.', NULL, 'WAEC_CRS_2024.json', 'c30bfd13bd647ea6f5d71ae8755ba0570fb27400fb97835bc421297483da2e28');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The specific sin of Ananias and Sapphira was _____.', '["murder","theft","lying to the Holy Spirit","adultery"]', 2, 'They kept back part of the proceeds of a land sale while pretending to give the full amount to the church.', NULL, 'WAEC_CRS_2024.json', '13b8f1b4098a6814f81d3618e8f46c2292c439c4e811bd4c3c1e9b8ed7fd1d12');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Paul was a citizen of _____ by birth.', '["Greece","Rome","Egypt","Syria"]', 1, 'Paul often used his Roman citizenship to appeal to higher courts and protect himself from arbitrary punishment.', NULL, 'WAEC_CRS_2024.json', '5ff82de0405b86a5b3ca78c5d573cc9a12f3fb02d04a496af706172e5dd39c31');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The theme of the book of Amos is God''s _____.', '["mercy","justice","power","grace"]', 1, 'Amos was a prophet of social justice who condemned the oppression of the poor by the wealthy in Israel.', NULL, 'WAEC_CRS_2024.json', 'ea52cdb753229f69aa83bb27b4d559200589d78ee549f03c7f3098b0e581f73e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The ''Great Commandment'' according to Jesus is to love _____.', '["our enemies","ourselves","God","our parents"]', 2, 'Jesus taught that loving God with all one''s heart, soul, and mind is the first and greatest commandment.', NULL, 'WAEC_CRS_2024.json', '7517d6079cf54f7648fac26738a83e72933854d6543d3baaf8d80129663149a0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Who was the queen that visited Solomon to test his wisdom?', '["Jezebel","Esther","Queen of Sheba","Athaliah"]', 2, 'The Queen of Sheba came with hard questions and was overwhelmed by Solomon''s wisdom and wealth.', NULL, 'WAEC_CRS_2024.json', 'de590975756668534d3900ee9d28a9458cb16396757f63b88c6d2f6c51bf9ee7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The name ''Peter'' given to Simon by Jesus means _____.', '["leader","rock","believer","strong"]', 1, 'Jesus called him ''Petros'' (rock) and said upon this rock He would build His church.', NULL, 'WAEC_CRS_2024.json', '36f3c73d67e5bf0e72c679bcb4ce227f4b5da7ae722a730351b81cf3ac3bbfbe');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Elijah was taken up to heaven in a _____.', '["chariot of fire","cloud","vision","dream"]', 0, '2 Kings 2:11 records that a chariot and horses of fire appeared, and Elijah went up in a whirlwind.', NULL, 'WAEC_CRS_2024.json', '79b0a246b9e910c574a80c4ea5072ec45070cc508ef70b0791c18260e9ec2135');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The person who helped Jesus carry the cross was _____.', '["Joseph of Arimathea","Simon of Cyrene","Nicodemus","John"]', 1, 'Simon of Cyrene, an African, was compelled by Roman soldiers to carry the cross.', NULL, 'WAEC_CRS_2024.json', 'cb4e698c44590c9a9e9f84739beb306c051ab61b0f1c1cd8b83e3a8b88dc315e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'God''s promise to Noah was sealed with a _____.', '["sacrifice","rainbow","stone","star"]', 1, 'The rainbow was the sign of the covenant that God would never again destroy the earth with a flood.', NULL, 'WAEC_CRS_2024.json', '659efc0ab25e6e3b982bf0f991ae700c94ee2dc6085c361e5818d8d5e6557bcc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The first murder in the Bible was committed by _____.', '["Adam","Cain","Abel","Seth"]', 1, 'Cain killed his brother Abel out of jealousy because God accepted Abel''s offering and not his.', NULL, 'WAEC_CRS_2024.json', '03b3f01e5ed6e2e702a7c27095db68a01d350360884bea778a54d95053e50d0e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Hagar was the handmaid of _____.', '["Sarah","Rebekah","Leah","Rachel"]', 0, 'Sarah gave her Egyptian maid Hagar to Abraham to bear a child on her behalf.', NULL, 'WAEC_CRS_2024.json', 'bef58c72a696b4edb1707f68e5472fb775493db9d4122e694a70f8d25fb14c64');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The son of Abraham through Hagar was _____.', '["Isaac","Ishmael","Jacob","Esau"]', 1, 'Ishmael was Abraham''s first son, though Isaac was the son of the promise through Sarah.', NULL, 'WAEC_CRS_2024.json', '7ed49511215688048e1bc0e3f4bc3fff263367edabcfe1d2e6741998c57e6a57');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The city of Jericho was captured by _____.', '["Moses","Joshua","Caleb","Gideon"]', 1, 'Joshua led the Israelites in the miraculous conquest of Jericho where the walls fell down.', NULL, 'WAEC_CRS_2024.json', '1e75b938e10e0f94d5a59eecd099c8d13a52deca7e6c813b6fbcdf5873bf2233');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Samson''s strength was in his _____.', '["arms","hair","feet","eyes"]', 1, 'As a Nazirite, Samson''s strength was tied to his vow, symbolized by his uncut hair.', NULL, 'WAEC_CRS_2024.json', 'd487ba1171407624cf929c6422cb387404eb0fd1a9e6e4f0022abfe0f3642c68');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Gideon defeated the Midianites with only _____ men.', '["300","3000","30,000","30"]', 0, 'God reduced Gideon''s army to 300 to show that the victory belonged to the Lord and not human strength.', NULL, 'WAEC_CRS_2024.json', '2ecf9b937b23d7662c1eede822777dd41f2b478f31db73455a0c79e1ca6ff89c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The mother of Samuel was _____.', '["Peninnah","Hannah","Eli","Deborah"]', 1, 'Hannah was barren but prayed fervently at Shiloh, promising to dedicate her son to the Lord.', NULL, 'WAEC_CRS_2024.json', 'e75567689356bc4b1ea400b48a65f15b9d887abb806e35438c8d182729e73cbf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Solomon''s temple was built in the city of _____.', '["Samaria","Bethlehem","Jerusalem","Hebron"]', 2, 'Jerusalem was the political and religious capital where the temple was situated.', NULL, 'WAEC_CRS_2024.json', 'afe145939501f45b5166fc87ec25aa6f8591a16f549b059160ea789515160a93');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'The ''Valley of dry bones'' vision was seen by Prophet _____.', '["Isaiah","Jeremiah","Ezekiel","Daniel"]', 2, 'Ezekiel saw the vision of dry bones coming to life, symbolizing the restoration of Israel.', NULL, 'WAEC_CRS_2024.json', 'd2727d4bb79abf3cee55c1331538f18808ac25657d228e3d34874bd41bf65ca7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'CRS', 2024, NULL, 'Jesus healed a man born blind by using _____.', '["prayer only","spittle and clay","water from a well","oil"]', 1, 'John 9 records that Jesus spat on the ground, made mud with the saliva, and put it on the man''s eyes.', NULL, 'WAEC_CRS_2024.json', 'e5e79684774c96f0bc196e453c159f3f882abfba703c5d130c9332f238c16ab5');
