INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Chemistry', 2024, NULL, 'Which of the following separation techniques is best suited for obtaining pure water from sea water?', '["Filtration","Decantation","Distillation","Evaporation to dryness"]', 2, 'Distillation involves boiling the sea water to create steam (leaving salts behind) and then condensing the steam back into liquid pure water. Evaporation would leave the salt but not recover the water.', NULL, 'WAEC_Chemistry_2024.json', '8e7669c36250bff67438fc65dedf9f0cc2b4c6363c1e0645179e6b48eebeb966');
