INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Chemistry', 2024, NULL, 'The hardest known substance is _____.', '["Graphite","Quartz","Diamond","Iron"]', 2, 'Diamond is an allotrope of carbon where each atom is tetrahedrally bonded to four others by strong covalent bonds, making it extremely hard.', NULL, 'WAEC_Chemistry_2024.json', '33c3e5f63a2291ec9b11e31c8cf14ef203d2055f7ba34a3b840575ef6138b027');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Chemistry', 2024, NULL, 'Which of the following is a primary cell?', '["Lead-acid accumulator","Leclanché cell","Nickel-iron cell","Lithium-ion battery"]', 1, 'A primary cell is one that cannot be recharged once the chemicals are exhausted. The dry Leclanché cell is a common example.', NULL, 'WAEC_Chemistry_2024.json', 'e75118b42ac056da46f6730110e0fc61d2499b81dd2902430cb0f7de0cbec9af');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Chemistry', 2024, NULL, 'The electronic configuration of an element is 
2
,
8
,
6
2,8,6
. This element belongs to group _____.', '["2","4","6","8"]', 2, 'The number of electrons in the outermost shell determines the group number in the periodic table (for main group elements).', NULL, 'WAEC_Chemistry_2024.json', '9b350fa1daf5c1c0625252fef2d9cdc9942c380603677d9db5e938199e987636');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Chemistry', 2024, NULL, 'Which of the following is a common property of acids?', '["They have a bitter taste","They feel soapy","They turn red litmus paper blue","They react with carbonates to liberate \r\n𝐶\r\n𝑂\r\n2\r\nCO\r\n2\r\n\t​\r\n\r\n"]', 3, 'Acids react with carbonates and hydrogen carbonates to produce a salt, water, and carbon (IV) oxide gas.', NULL, 'WAEC_Chemistry_2024.json', '9c6a6c02589142b4f9089f1b9b271a12ea2880120a134fdfc83110556686a40a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Chemistry', 2024, NULL, 'The main constituent of natural gas is _____.', '["Ethane","Methane","Propane","Butane"]', 1, 'Natural gas consists primarily of methane (usually over 90%), with smaller amounts of other hydrocarbons.', NULL, 'WAEC_Chemistry_2024.json', 'adfc2044ef19b598c3794405cf1c02c7f1f11d442d8edc17e94ac69c30d73a03');
