INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Chemistry', 2024, NULL, 'Which of the following processes is used to separate a mixture of iodine and sand?', '["Filtration","Evaporation","Sublimation","Crystallization"]', 2, 'Iodine sublimes (changes from solid to gas) when heated, while sand does not. The iodine vapor can be collected and cooled.', NULL, 'WAEC_Chemistry_2024.json', '60cf9f0f09a26216885e0dd1ef028b5322a26100e5a8e438734f4d320c0c73e9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Chemistry', 2024, NULL, 'The partial pressure of a gas in a mixture is equal to its _____.', '["Mole fraction \r\n𝑡\r\n𝑖\r\n𝑚\r\n𝑒\r\n𝑠\r\ntimes\r\n Total pressure","Mass fraction \r\n𝑡\r\n𝑖\r\n𝑚\r\n𝑒\r\n𝑠\r\ntimes\r\n Total pressure","Density \r\n𝑡\r\n𝑖\r\n𝑚\r\n𝑒\r\n𝑠\r\ntimes\r\n Total pressure","Volume \r\n𝑡\r\n𝑖\r\n𝑚\r\n𝑒\r\n𝑠\r\ntimes\r\n Total pressure"]', 0, 'Dalton''s Law of Partial Pressures states that the pressure of an individual gas in a mixture is the product of its mole fraction and the total pressure.', NULL, 'WAEC_Chemistry_2024.json', '7c13d34b384f460933c6bfe6d1b5a0accdeda25fffe0c941696c83d2fbe887de');
