INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Chemistry', 2024, NULL, 'A catalyst increases the rate of a chemical reaction by _____.', '["Increasing the temperature","Lowering the activation energy","Increasing the concentration of reactants","Increasing the enthalpy change"]', 1, 'A catalyst provides an alternative reaction pathway with a lower activation energy, allowing more reactant particles to have enough energy to react.', NULL, 'WAEC_Chemistry_2024.json', '395550d2c1c0cd0d64d5c9f3ac33f722172cf7cd23f13ec6e9a5939e3f457933');
