INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The totality of the beliefs and ideas that a society or person considers important and useful is known as _____.', '["Apathy","Values","Norms","Culture"]', 1, 'Values represent the principles or standards of behavior; one''s judgment of what is important in life. They are the shared beliefs of a society.', NULL, 'WAEC_Civic_2024.json', '7aab186c6e8e440da3df35ff77537421ad7d7f9ea6e35e96ad37163b48aec32a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Which of the following is a core attribute of honesty?', '["Deceit","Integrity","Selfishness","Cunningness"]', 1, 'Integrity involves being honest and having strong moral principles. An honest person is characterized by integrity and truthfulness.', NULL, 'WAEC_Civic_2024.json', 'b30ce3d095a38a91fac095b60c3a71c229c111a4ff4bee8fab8003353f1c8de7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The ability to depend on one''s own efforts and abilities to satisfy needs is _____.', '["Self-esteem","Self-reliance","Self-centeredness","Self-glory"]', 1, 'Self-reliance is the quality of depending on yourself rather than on others for things. It is a key value in civic education aimed at reducing unemployment.', NULL, 'WAEC_Civic_2024.json', '71e499e02364828e020e2e513b436d2b02e8d934653f069aec684abfb07d1586');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'In Nigeria, a citizen by _____ is a person whose parents were both members of indigenous communities in Nigeria before independence.', '["Naturalization","Registration","Birth","Conferment"]', 2, 'According to the Nigerian Constitution, anyone born in Nigeria before the date of independence, either of whose parents or any of whose grandparents belongs or belonged to a community indigenous to Nigeria, is a citizen by birth.', NULL, 'WAEC_Civic_2024.json', '4e17dd6eb5841dba3673acf2fed3b2f2a1fdced15937ff20f9d5a45bbf9babbb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The process of losing one''s citizenship by formally giving it up is called _____.', '["Renunciation","Deprivation","Deportation","Expatriation"]', 0, 'Renunciation is the formal act of giving up one''s citizenship of a country. Deprivation is when the state takes it away.', NULL, 'WAEC_Civic_2024.json', 'b91b5387ab4a41f46366e944e30c9e45bd25439280d4dd71d2a471c7b98c522b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The Universal Declaration of Human Rights (UDHR) was adopted by the United Nations on _____.', '["October 24, 1945","December 10, 1948","January 1, 1960","May 29, 1999"]', 1, 'The United Nations General Assembly adopted the UDHR on December 10, 1948, at the Palais de Chaillot in Paris.', NULL, 'WAEC_Civic_2024.json', '385ee8b02fa9ce26becb5c44204d99be2610189af277ee64beac6ddcdef4b98a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Human rights are said to be ''inalienable'' because _____.', '["They can be sold","They are only for the rich","They cannot be taken away from an individual","They are given by the government"]', 2, 'Inalienable rights are rights that cannot be surrendered, transferred, or taken away. They are inherent to all human beings.', NULL, 'WAEC_Civic_2024.json', '72a61a3811eba76dcf7d96ba6e30538e36691eb4e5de628cce6c14cb9f8d498e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Which article of the UDHR states that ''All human beings are born free and equal in dignity and rights''?', '["Article 1","Article 5","Article 10","Article 30"]', 0, 'Article 1 is the foundational principle of the UDHR, asserting the freedom and equality of all humans from birth.', NULL, 'WAEC_Civic_2024.json', 'd63842cb0287d79c648bcdf72180daf61a2248b2f2a1983825307bf515a8d60d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The government agency responsible for the prevention of drug abuse and trafficking in Nigeria is the _____.', '["EFCC","NAFDAC","NDLEA","ICPC"]', 2, 'The National Drug Law Enforcement Agency (NDLEA) is a Nigerian federal agency established to eliminate the growing, processing, manufacturing, selling, exporting, and trafficking of hard drugs.', NULL, 'WAEC_Civic_2024.json', 'a9a436531195a5516f288f0a6fcb1511fb6c12b176a8311378bb5307238b517b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Cultism was first introduced in Nigerian universities in 1952 by a group known as the _____.', '["Black Axe","Vikings","Pyrates Confraternity","Eiye Confraternity"]', 2, 'The Pyrates Confraternity (also known as the Seadogs) was the first secret cult in Nigeria, founded by Wole Soyinka and six others at the University of Ibadan to fight for human rights and justice.', NULL, 'WAEC_Civic_2024.json', '2aeee45fb61d5f3a8104ce3df2584442b05ed7cb0c99ffba47f268b971bde62c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'One of the major consequences of cultism on campus is _____.', '["High academic performance","Peace and harmony","Rustication of students","Financial stability"]', 2, 'Students caught participating in cult activities face severe disciplinary actions, including expulsion or rustication from the university.', NULL, 'WAEC_Civic_2024.json', '3399e7271a9c3594a8b2faa8ef02bced71954f78e911b830cc8af32b9855e22b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'A system of government where the law is supreme over everyone, including the rulers, is the _____.', '["Rule of Force","Rule of Law","Military Rule","Aristocracy"]', 1, 'The Rule of Law, as popularized by A.V. Dicey, implies that no one is above the law and everyone is subject to it equally.', NULL, 'WAEC_Civic_2024.json', 'a041c54ca822d8e66a4baf1d09b190a4b3d3c7acb98ab98214dc2a16c7fe3ac5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The three pillars of the Rule of Law according to A.V. Dicey include the following EXCEPT _____.', '["Supremacy of the law","Equality before the law","Right to bear arms","Fundamental human rights"]', 2, 'Dicey''s three pillars are Supremacy of the law, Equality before the law, and the Constitution as a result of the ordinary law of the land (protection of rights).', NULL, 'WAEC_Civic_2024.json', '2bfac78826b6916e1e9040680f4c2a4ab5dd3a9663de314f710230061b1578ab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Representative democracy is also known as _____.', '["Direct democracy","Indirect democracy","Monarchy","Totalitarianism"]', 1, 'In indirect or representative democracy, citizens elect officials to make decisions and pass laws on their behalf.', NULL, 'WAEC_Civic_2024.json', '7e1f581161b98da7b7b16bfe7bbae7c214cc74c2eee0fb4943513a3c015b4bcb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Which of these is a major pillar of democracy?', '["Single-party system","Independent Judiciary","Military dominance","Censorship of the press"]', 1, 'An independent judiciary is essential for a democracy to ensure that the executive and legislature act within the law and that citizens'' rights are protected.', NULL, 'WAEC_Civic_2024.json', '6b61804c5a70dda1db583e07281ce3b376be1d289f617fdfa9a95a581f63a236');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Voter apathy refers to _____.', '["The right to vote","Enthusiasm during elections","Lack of interest in participating in elections","Voting twice in an election"]', 2, 'Voter apathy is a lack of interest among citizens in participating in the electoral process, often shown by low voter turnout.', NULL, 'WAEC_Civic_2024.json', '7d4289ac0cfa58deed72fe7d5f28de3978be6ba6e4c43559545a76737e21db15');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The green light on a traffic signal means _____.', '["Stop","Ready to go","Go","Warning"]', 2, 'Standard international traffic light sequence: Red (Stop), Yellow/Amber (Ready/Caution), Green (Go).', NULL, 'WAEC_Civic_2024.json', '8ad2d0693b613ac29d9f4896ca31075dde3bb03a181f656b5ff203f60f67f264');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The body responsible for maintaining safety on Nigerian roads is the _____.', '["LASTMA","FRSC","NEMA","NSCDC"]', 1, 'The Federal Road Safety Corps (FRSC) is the government agency with statutory responsibilities for road safety administration in Nigeria.', NULL, 'WAEC_Civic_2024.json', '1537cd26d30f2a9b2f76edab9fe72627d29d5772fce6c5fc5435b3be8dad2bd7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The administrative machinery used by the government to implement its policies is the _____.', '["Private sector","Public service","Armed forces","Judiciary"]', 1, 'The public service (or civil service) consists of employees who carry out the day-to-day functions of the government and implement its policies.', NULL, 'WAEC_Civic_2024.json', '1660f41657b71c583923e455ce3d26a375ce0399a595cc09d2a61cef70276d27');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'A major characteristic of the civil service is ''Anonymity'', which means _____.', '["Civil servants must be famous","Civil servants are not to be blamed or praised for government policies","Civil servants must hide their faces","Civil servants can join any political party"]', 1, 'Anonymity means that civil servants work behind the scenes; the political head (Minister/Commissioner) takes the credit or blame for policy outcomes.', NULL, 'WAEC_Civic_2024.json', 'd3e7ea9feb580b8ece2a6836c01e06497496485f7745a6613435856f22a14679');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Which of the following is a symptom of HIV/AIDS?', '["Instant weight gain","Persistent cough and fever","Improved immune system","Quick recovery from injuries"]', 1, 'HIV/AIDS weakens the immune system, leading to opportunistic infections characterized by persistent fever, cough, and weight loss.', NULL, 'WAEC_Civic_2024.json', '4c615a7a9a0980606ec6f0e4e00180ec4d0ac68b651c1e1b556ec7e896ea6f6d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The act of treating someone unfairly because they have a certain disease or condition is called _____.', '["Rehabilitation","Counseling","Stigmatization","Sensitization"]', 2, 'Stigmatization involves social disapproval and discrimination against individuals based on perceived characteristics, such as being HIV positive.', NULL, 'WAEC_Civic_2024.json', '0b2b149f71a9a60c986cb9fdc952dae48872f884f8e10125a7054f481005f336');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The agency that fights against the distribution of fake and substandard drugs in Nigeria is _____.', '["ICPC","NAFDAC","SON","NEMA"]', 1, 'The National Agency for Food and Drug Administration and Control (NAFDAC) regulates and controls the manufacture, importation, exportation, advertisement, distribution, sale and use of food, drugs, and chemicals.', NULL, 'WAEC_Civic_2024.json', '63bcdd53336c91c0e82e2882f8dd06da47cc8bdc01969badf504971e8e23f5ac');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'A society that is independent of government control and consists of NGOs and community groups is _____.', '["Military society","Civil society","Political society","Traditional society"]', 1, 'Civil society refers to the ''third sector'' of society, distinct from government and business, and including the family and the private sphere.', NULL, 'WAEC_Civic_2024.json', 'f21eadac76b5caf76f6ed34ec6ac98e3a17c26122d58a593bdb3f9fbe1f17d59');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Popular participation can be encouraged through _____.', '["Rigging of elections","Political education and enlightenment","Use of thugs","Banning of opposition parties"]', 1, 'Enlightening the public on their rights and the importance of voting increases the willingness of citizens to participate in politics.', NULL, 'WAEC_Civic_2024.json', '59c3183faddea338e3e99c48cf15c0123f31fb2a88e62aa09e09902b212f1812');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Constitutionalism means that the government should be _____.', '["Run by the military","Ruled by the rich","Subject to the provisions of the constitution","Without any laws"]', 2, 'Constitutionalism is the principle that government power should be limited by a constitution to prevent arbitrary rule.', NULL, 'WAEC_Civic_2024.json', '0a2718ff9553137d27168d235bc6ac6cf111b9e6d7c3ed245f1b232ba595946c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The highest law-making body in Nigeria at the federal level is the _____.', '["Supreme Court","National Assembly","State House of Assembly","Federal Executive Council"]', 1, 'The National Assembly, consisting of the Senate and the House of Representatives, is the federal legislature of Nigeria.', NULL, 'WAEC_Civic_2024.json', 'b265b750e4392c0b4bd7855b33cea60cbc893cc5040150af54a589452365645b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The display of a high level of moral uprightness and honesty is _____.', '["Humility","Integrity","Kindness","Courage"]', 1, 'Integrity is the practice of being honest and showing a consistent and uncompromising adherence to strong moral and ethical principles.', NULL, 'WAEC_Civic_2024.json', '991292d172edc94a7b014b210f1a970dca3a44b809feb618911443457981330b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The behavior that follows the laid down rules and regulations of a society is _____.', '["Chaos","Orderliness","Apathy","Corruption"]', 1, 'Orderliness is the quality of being well-organized or behaving according to the set rules of a community.', NULL, 'WAEC_Civic_2024.json', '6575365b1108840edd07ffc1fb059cf3e4e8922de7847902fc3032c0577ce7ad');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Which of the following can lead to inter-communal conflict?', '["Tolerance","Resource control and land disputes","Dialogue","Equality"]', 1, 'Conflicts between communities often arise over ownership of land, boundary disputes, or control of natural resources.', NULL, 'WAEC_Civic_2024.json', 'f5082a9e465004198d01ca7684239c38c0e3a66c1833b87c075b0c67fea5502d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'A situation where there is no war, disturbance, or fear in a society is _____.', '["Conflict","Peace","Anarchy","Crisis"]', 1, 'Peace is a state of harmony characterized by the lack of violent conflict and the freedom from fear of violence.', NULL, 'WAEC_Civic_2024.json', 'fca0e7442cd69cd0faaa39a278549f335f29845a209696a1e3a32c1e75bbc873');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The principle where the three organs of government operate separately to prevent tyranny is _____.', '["Checks and Balances","Separation of Powers","Delegated Legislation","Judicial Review"]', 1, 'Separation of powers ensures that the Legislature, Executive, and Judiciary have distinct functions and powers to prevent the concentration of power.', NULL, 'WAEC_Civic_2024.json', '9cf3ac9267d36274ebf7e0db4c78847ac1824a9753232ed909851a324ab1695a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'A written constitution is a document that _____.', '["Is stored in the memory of the elders","Is found in a single legal document","Cannot be seen by the public","Is only for the president"]', 1, 'A written constitution is a formal document defining the nature of the constitutional settlement, the rules that govern the political system, and the rights of citizens.', NULL, 'WAEC_Civic_2024.json', '3729b33a3636fcff70b4462cb3f7503933c787c7cb10ebc241b70e0288f3c451');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The Nigerian flag was designed in 1959 by _____.', '["Herbert Macaulay","Taiwo Akinkunmi","Nnamdi Azikiwe","Ahmadu Bello"]', 1, 'Michael Taiwo Akinkunmi, a student in London at the time, designed the Green-White-Green flag.', NULL, 'WAEC_Civic_2024.json', '80d9491f69b7b70eaa6036ce6bd9f33a07fda5b29dc6b96cc465d82a0788637c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'On the Nigerian Coat of Arms, the two white horses represent _____.', '["Strength","Dignity","Agriculture","Unity"]', 1, 'The two horses on the Nigerian Coat of Arms represent the dignity and pride of Nigeria.', NULL, 'WAEC_Civic_2024.json', 'f1cc5e811926bab3d96ea31fd6bf5b0a1cedfc5e9d017fefe806e0bc435b86a9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Which of the following is a duty of a Nigerian citizen?', '["Right to life","Payment of taxes","Right to fair hearing","Freedom of movement"]', 1, 'Payment of taxes is an obligatory duty of every citizen to enable the government to provide infrastructure and services.', NULL, 'WAEC_Civic_2024.json', 'fd04d7ffdc9a2ea305427debb5525762e36050a460541b570558847a8b2ddde8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The use of ''Zebra Crossing'' on roads is to _____.', '["Allow cars to speed","Protect pedestrians while crossing","Decorate the road","Indicate a U-turn"]', 1, 'A zebra crossing is a type of pedestrian crossing where motorists are required to stop for pedestrians who have stepped onto the crossing.', NULL, 'WAEC_Civic_2024.json', '2e8efdc15fde2f6ae9a25398584e77cd6c054157086224976d741d37b544a2fa');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Skills acquired by an individual to become productive and self-reliant are called _____ skills.', '["Literary","Empowerment","Gambling","Political"]', 1, 'Empowerment skills are practical abilities that allow individuals to create wealth and be self-sufficient.', NULL, 'WAEC_Civic_2024.json', '0f72ebbc9442a4b54e5780d2aee2b0c729486a4256d7d49c4660d54a18b0a023');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The primary motive for drug trafficking is _____.', '["Saving lives","Greed for quick money","Medical research","Promoting sports"]', 1, 'Drug trafficking is an illegal trade driven by the high profit margins associated with the sale of illicit substances.', NULL, 'WAEC_Civic_2024.json', '42278bee10a4dc80af4705d838a07675e3bd957ee9f4fa53f4a5532bca0fc017');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Which of these is a way of preventing HIV/AIDS?', '["Sharing needles","Unprotected sex","Abstinence","Using the same toothbrush as an infected person"]', 2, 'Abstinence from sexual intercourse is the most effective way to prevent the sexual transmission of HIV.', NULL, 'WAEC_Civic_2024.json', '141fe74df6241f6159f3047b74cf7db12d0ea42f66433129968199b9204965d7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The rule of law ensures that every citizen has a ''Right to Fair Hearing'', which means _____.', '["The judge must be the person''s friend","The person must be heard before a competent court before judgment","Everyone must be found guilty","Wealthy people can buy the judge"]', 1, 'Fair hearing is a fundamental right ensuring that a person is given the opportunity to present their case before an impartial court.', NULL, 'WAEC_Civic_2024.json', 'd0488a6632308e4934073a3302010aed86f1b7594d46c5d6e629f3476eb0f4dd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'A major cause of voter apathy in Nigeria is _____.', '["Too many political parties","Election violence and rigging","Public holidays on election days","Free food at polling units"]', 1, 'When elections are characterized by violence or the results are perceived as manipulated, citizens lose interest in voting.', NULL, 'WAEC_Civic_2024.json', '76a8a15a89c486b29164915732d18a1445779e51d1bf8eeb69445a8cad0c7e3b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Public service refers to services provided by _____.', '["The government to the citizens","Individual families to themselves","Private companies for profit","Children to parents"]', 0, 'Public services are those provided by the government or its agencies for the benefit of the entire community.', NULL, 'WAEC_Civic_2024.json', 'd8d5ca4cc80d05f75829870f6c58e3dd325dc5e0fea298e4e578101334a388a9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The ''Ombudsman'' in Nigeria is known as the _____.', '["Economic and Financial Crimes Commission","Public Complaints Commission","National Human Rights Commission","Code of Conduct Bureau"]', 1, 'The Public Complaints Commission acts as an ombudsman, investigating complaints by citizens against administrative injustice by the government or private companies.', NULL, 'WAEC_Civic_2024.json', 'cdc8b1b666a094680e43253b618fd5d73689029d9680e11c184eca3fc408f6aa');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The motto of Nigeria is _____.', '["Unity and Faith","Peace and Progress","Unity and Faith, Peace and Progress","Justice and Service"]', 2, 'The national motto of Nigeria is ''Unity and Faith, Peace and Progress''.', NULL, 'WAEC_Civic_2024.json', '6654a934414acf7017b4ceb959d86a1f34b45b3c8382689835a56c8f0a0df077');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The black shield on the Nigerian Coat of Arms represents _____.', '["The fertile soil of Nigeria","The strength of the nation","The rivers Niger and Benue","The peace of the land"]', 0, 'The black shield represents Nigeria''s fertile soil, which is a major agricultural asset.', NULL, 'WAEC_Civic_2024.json', 'f60e5f4d401bc8ce5ff5f27e7241768dd59e93dae5aa942740c904b02d391131');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'A person who is not a citizen of a country but resides there is a/an _____.', '["Indigene","Alien","Refugee","Diplomat"]', 1, 'An alien is a resident of a country who is not a citizen of that country.', NULL, 'WAEC_Civic_2024.json', 'f95b59714f314d623c94a404e3fc2198cb863164c6db113eec5360548add6f1f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'One of the following is a limitation to human rights _____.', '["Wealth","State of emergency","Education","Gender"]', 1, 'During a state of emergency, the government may legally suspend certain human rights to maintain public order.', NULL, 'WAEC_Civic_2024.json', 'd132c7746825b09a2a849c512401958ebef722e2f0aee6251358d9fd1651177a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The acronym NYSC stands for _____.', '["National Youth Security Council","National Youth Service Corps","Nigerian Youth Service Company","National Young Soldiers Club"]', 1, 'The National Youth Service Corps (NYSC) was established in 1973 to involve Nigerian graduates in nation-building and the development of the country.', NULL, 'WAEC_Civic_2024.json', '34e58f3fa2bdc2b8f52f61df165404411b4238357e13385be1d55f92296b4d39');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Responsible followership involves _____.', '["Blindly following leaders","Constructive criticism and obeying laws","Disrupting government programs","Taking bribes"]', 1, 'Responsible followers contribute to the success of a leader by being law-abiding and offering honest feedback.', NULL, 'WAEC_Civic_2024.json', 'c6a4f33c449ee36480e9e0a009c477d5972c35f04df9a61f9b8e951bd484b60c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The red light on a traffic signal indicates that the motorist should _____.', '["Slow down","Go","Stop","Park"]', 2, 'Red always signifies ''Stop'' in traffic regulations to prevent accidents.', NULL, 'WAEC_Civic_2024.json', 'dbf59f5ba84c23dbe73f40e92bb2c3c5ba10060efcc27ba1d2ff9e46f09f5c9c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Public service in Nigeria is often hampered by ''Red-tapism'', which means _____.', '["Using red ink for writing","Excessive adherence to formal rules and procedures","High speed of work","Painting offices red"]', 1, 'Red tape refers to excessive bureaucracy that delays action or decision-making.', NULL, 'WAEC_Civic_2024.json', 'e0661ee0b5a5a59600107d8f580462ad5a8b980cd1ee8974f4cd5d99923796d5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Which of the following is a way of promoting national unity?', '["Tribalism","Inter-ethnic marriages","Nepotism","Religious intolerance"]', 1, 'When people from different ethnic groups marry, it builds social ties that cut across tribal lines, fostering unity.', NULL, 'WAEC_Civic_2024.json', '2bbb17eabc84f305479b8fca91daa067d38123f5e920e5f6156d5241f2b24d04');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Civil society organizations (CSOs) help in _____.', '["Conducting elections","Holding the government accountable","Making laws","Judging criminals"]', 1, 'CSOs act as watchdogs, ensuring that the government remains transparent and respects the rights of citizens.', NULL, 'WAEC_Civic_2024.json', '47470cb62ab21049dfa76b45b99ba891ff3d4934298df76531c05efd47ba0e5f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Conflict resolution through a neutral third party whose decision is binding is _____.', '["Mediation","Arbitration","Negotiation","Litigation"]', 1, 'In arbitration, an independent person (the arbitrator) makes a final, legally binding decision on a dispute.', NULL, 'WAEC_Civic_2024.json', 'e944d183482eb654a65aa709b7ca79e4dcf3dad317e9692c390d98f67a17f6ad');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The eagle on the Nigerian Coat of Arms represents _____.', '["Peace","Dignity","Strength","Agriculture"]', 2, 'The red eagle represents the strength and pride of Nigeria.', NULL, 'WAEC_Civic_2024.json', 'a2a9b4199e102ab7b76d1fe228a76909e976823373e7ad6c15a4e38f1ee9ce9b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'A core value that helps in preventing corruption is _____.', '["Greed","Integrity","Selfishness","Nepotism"]', 1, 'Integrity involves being honest and having strong moral principles, making an individual resistant to corrupt practices.', NULL, 'WAEC_Civic_2024.json', 'eb124a8a66729e9f150d1783d3769f41f20307f591fde4d62db795e9349a5c83');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Which body is responsible for registering voters and conducting elections in Nigeria?', '["ICPC","INEC","EFCC","NPC"]', 1, 'The Independent National Electoral Commission (INEC) is the body established by the 1999 Constitution to organize elections in Nigeria.', NULL, 'WAEC_Civic_2024.json', '61554897daa8fa524efbf585ed1a06d973d9ab727fbad1cf81d12416a7082aa9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'Nationalism is defined as _____.', '["Hatred for other countries","Deep love and devotion to one''s own country","Fighting in a war","Traveling abroad"]', 1, 'Nationalism is a sense of belonging and loyalty to one''s nation and the desire to see it independent and prosperous.', NULL, 'WAEC_Civic_2024.json', '3bdba518f988c1aad4a0fc72f08d60beb788d5190db99109b51d0ed8feb6052a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'The Child Rights Act was passed in Nigeria in _____.', '["1960","1999","2003","2015"]', 2, 'The Child Rights Act (2003) is the law that guarantees the rights of all children in Nigeria and provides for their protection.', NULL, 'WAEC_Civic_2024.json', 'a0d97f986ab48a9f1aa45c3d85cbb1013c8ab02c29032131e1efdc630a70e3b6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2024, NULL, 'An example of a drug that is frequently abused is _____.', '["Paracetamol","Cocaine","Vitamin C","Antacids"]', 1, 'Cocaine is an illegal stimulant that is highly addictive and commonly abused, leading to severe health and social consequences.', NULL, 'WAEC_Civic_2024.json', '842f1fdbbb469694de8f43d3d01078f58abadc3beb0492cb10ec1662534d131b');
