INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2025, NULL, 'Youth empowerment reduces:', '["Unemployment and crime","Education","Health","Wealth"]', 0, NULL, NULL, 'WAEC_Civic_2025.json', '0880d7fbec583d4ebb8a2712810c2c73ec8ab4c6af6b938389e5ec355f23d697');
