INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2025, NULL, 'Which is a civic responsibility?', '["Payment of tax","Evading tax","Rioting","Looting"]', 0, NULL, NULL, 'WAEC_Civic_2025.json', 'e6e4e6920a74ff068ddc123673097bd55938657f5b3d0cf6c970391e6b72affb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Civic', 2025, NULL, 'Universal Adult Suffrage allows:', '["All qualified adults to vote","Only men to vote","Only rich to vote","Aliens to vote"]', 0, NULL, NULL, 'WAEC_Civic_2025.json', '9b7ad87ae1f0bf57a37734ddfa03973593256cc707f7de99846cb568a7ddf9a6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Commerce is defined as the study of _____.', '["how to build factories","trade and auxiliaries to trade","farming and animal husbandry","the extraction of raw materials"]', 1, 'Commerce encompasses trade (buying and selling) and all activities that facilitate it, such as banking, insurance, and transport.', NULL, 'WAEC_Commerce_2024.json', '58e44d93dfcd4bf215df17d4a18a66fd4d0fd40dbe60ccde17292eccfdb4798f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is an example of an extractive occupation?', '["Plumbing","Banking","Fishing","Bricklaying"]', 2, 'Extractive occupations involve taking raw materials or resources directly from nature (earth or water).', NULL, 'WAEC_Commerce_2024.json', '121af89a92d09ebfa9a3a088efa057553ca8593a2a14e6adbe088db82394691c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A credit note is issued by a seller to a buyer when _____.', '["there is an undercharge on the invoice","goods are sold on credit","goods are returned by the buyer","cash is received immediately"]', 2, 'A credit note is sent by a seller to a buyer to acknowledge that the buyer''s account has been credited due to returned or damaged goods.', NULL, 'WAEC_Commerce_2024.json', '0098c8eaa4f690944e0973295bacbbc325321c20a3eb031aebfdb1a7ceea52b2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The main function of a wholesaler to the manufacturer is _____.', '["selling in small bits to consumers","giving technical advice to users","breaking bulk","providing warehouse facilities"]', 3, 'Wholesalers store large quantities of goods for the manufacturer, reducing the manufacturer''s need for storage space.', NULL, 'WAEC_Commerce_2024.json', '2990b16da85cbb96c5680b6ddb84a03212becf96346db2dbca6f9a215712fd66');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'In which of the following business units is the liability of members limited to their investment?', '["Sole Proprietorship","General Partnership","Private Limited Company","Club or Society"]', 2, 'In a limited liability company, the personal assets of shareholders are protected; they only lose what they invested if the business fails.', NULL, 'WAEC_Commerce_2024.json', '6ade16e24c7b3c3379a6ad3715a07150df6b93015a891cf3c12004b786afe240');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The principle of insurance which ensures that the insured is only restored to his former financial position is _____.', '["Proximate Cause","Indemnity","Utmost Good Faith","Subrogation"]', 1, 'Indemnity means to compensate for loss; it prevents the insured from making a profit from a claim.', NULL, 'WAEC_Commerce_2024.json', 'a387096a9e1b7b0579b5c0e92074d76d54c8defb2b269548b188a5fbc4db467a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which document gives the holder title to goods being exported by sea?', '["Shipping Note","Bill of Lading","Indent","Consular Invoice"]', 1, 'A Bill of Lading is a document of title, a contract of carriage, and a receipt for goods shipped by sea.', NULL, 'WAEC_Commerce_2024.json', '1d71f56a3ecd078c7741ef03552c50dc4ce5e49e7f9f65d9257989bfc61b8050');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The person who buys and sells shares on behalf of the public on the Stock Exchange is a _____.', '["Jobber","Broker","Stag","Bull"]', 1, 'A stockbroker acts as an agent for the public, executing buy and sell orders for a commission.', NULL, 'WAEC_Commerce_2024.json', 'affceaba6b2eb509d3e48bb53537415c508a17b4ade5aa2110f867a0e8c63d48');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A ''Crossing'' on a cheque is intended to _____.', '["make the cheque invalid","ensure the money is paid into a bank account","allow the cheque to be cashed over the counter","indicate that the cheque is a gift"]', 1, 'A crossed cheque cannot be cashed over the counter; it must be paid into a bank account, which provides security against theft.', NULL, 'WAEC_Commerce_2024.json', '57f3cef08eb2131a813ee5a84acc28e8db50c10be7e041672003a9d6a06c2c6d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The abbreviation ''PLC'' after a company''s name in Nigeria stands for _____.', '["Private Limited Company","Public Liability Company","Public Limited Company","Partnership Limited Company"]', 2, 'PLC denotes a Public Limited Company, whose shares can be bought and sold by the general public on the stock exchange.', NULL, 'WAEC_Commerce_2024.json', 'b871dcb154549c14adea6a231ff9165678d4fa31f5eb891f6f189895cf75301d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The most appropriate means of transporting crude oil from a production site to a refinery is by _____.', '["Road","Rail","Pipeline","Air"]', 2, 'Pipelines are the most cost-effective and continuous means of transporting large volumes of liquid or gas over long distances.', NULL, 'WAEC_Commerce_2024.json', '429dde0fcaeb4ab11897503859ed4050d4c3c1508d1aa8d4dc26ef32e3edfd5d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following describes ''invisible trade''?', '["Trade in stolen goods","Trade in services such as tourism","Internal trade only","Smuggling across borders"]', 1, 'Invisible trade refers to the import and export of services, where no physical goods are moved across borders.', NULL, 'WAEC_Commerce_2024.json', '93b944f1fbb8d37104b390eb9cafa476482f75a5f1bbf5f4f63a4b6d4044272e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A specialized retailer that sells only one line of goods is a _____.', '["Department store","Supermarket","Specialty shop","Hypermarket"]', 2, 'A specialty shop focuses on a specific category of products, such as a pharmacy or a boutique.', NULL, 'WAEC_Commerce_2024.json', '9b907fe3bd804e3bc13f578da19a9e7ac1455457fea8f69ce4fcd08bf556d169');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The document that contains the internal rules and regulations of a limited liability company is the _____.', '["Memorandum of Association","Articles of Association","Prospectus","Certificate of Incorporation"]', 1, 'Articles of Association outline the internal management, including directors'' powers and shareholders'' voting rights.', NULL, 'WAEC_Commerce_2024.json', '6825e19a0d3b40208628d0d213c051d9c55806f0d0758e1078479f89804da290');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The act of selling goods in foreign markets at prices lower than those in the home market is _____.', '["Hedging","Dumping","Arbitrage","Exporting"]', 1, 'Dumping is a predatory pricing strategy used to gain market share in another country, often resulting in unfair competition.', NULL, 'WAEC_Commerce_2024.json', 'b664c0b7b5a5f27d882c78ba0c9b7750cd1c4549afb6f7871e427c9ca8f45f02');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A bank draft is safer than a personal cheque because _____.', '["it can be cashed anywhere","it is signed by the President","payment is guaranteed by the bank","it does not expire"]', 2, 'A bank draft is drawn by the bank on its own funds, so there is no risk of it ''bouncing'' due to insufficient funds.', NULL, 'WAEC_Commerce_2024.json', '7f52346ca576fa4f3feba43c284e46e8f07040d1025e3877c6e06ae1243dc407');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The process of a manufacturer selling directly to the consumer is an example of _____.', '["indirect distribution","direct distribution","wholesale trade","retail trade"]', 1, 'Direct distribution eliminates middlemen like wholesalers and retailers, allowing the producer to sell directly to the end user.', NULL, 'WAEC_Commerce_2024.json', '76173cbc3b3f7a4a3e12bb304964edd8c76d7f4c62f8af74ff64233e69486ac6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is a function of the Nigerian Export Promotion Council (NEPC)?', '["Importing luxury goods","Regulating local market prices","Promoting non-oil exports","Controlling the flow of traffic"]', 2, 'The NEPC is the government agency responsible for promoting and diversifying Nigeria''s export trade away from oil.', NULL, 'WAEC_Commerce_2024.json', '4ac448e813b8bae3fb1c283d6dbe7460d4ae71b11683a1e048b416fe51decdbf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'An insurance policy that covers a ship and its cargo against risks on a specific journey is a _____.', '["Time policy","Voyage policy","Floating policy","Mixed policy"]', 1, 'A voyage policy provides cover for a specific route or journey rather than a specific period of time.', NULL, 'WAEC_Commerce_2024.json', '160d865e098c3a23f48d2cf99a451f509c270633addf86c82d33e764ae1316e6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which type of capital is used for the day-to-day running of a business?', '["Fixed capital","Working capital","Authorized capital","Nominal capital"]', 1, 'Working capital (Current Assets minus Current Liabilities) is used to pay for short-term operations like wages and raw materials.', NULL, 'WAEC_Commerce_2024.json', '36ef22da5ff34e2f0ac959ef3d56fe40f6be63fdb3dcbb8b15276ec4a150b5a4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A warehouse owned and operated by the government to store goods until duties are paid is a _____.', '["Private warehouse","Public warehouse","Bonded warehouse","State warehouse"]', 2, 'Bonded warehouses are used to secure dutiable goods; importers cannot remove them until the customs duties are settled.', NULL, 'WAEC_Commerce_2024.json', '851e31ffecff6b8f09bc0e927b9e2fa5d7dbd3ad8e1146d4d42846719b2b3429');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is a disadvantage of a partnership?', '["Shared decision making","Privacy of accounts","Unlimited liability for general partners","More capital than sole proprietorship"]', 2, 'In a general partnership, partners are personally responsible for all the debts of the business, which can put their private assets at risk.', NULL, 'WAEC_Commerce_2024.json', '8807003ac71674840708de112c1970ff5e3cfacf59fe5452898fe182a82f99a1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The ''Bull'' in the stock exchange is an investor who _____.', '["expects share prices to fall","expects share prices to rise","buys only government bonds","refuses to sell his shares"]', 1, 'A Bull is an optimistic investor who buys shares now, hoping to sell them later at a higher price.', NULL, 'WAEC_Commerce_2024.json', 'b26defab5b0af82ea8146051f1a8012f50c535fd0094f8d4822362aa0f18cf10');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'In computer technology, the physical components of the system are called _____.', '["Software","Hardware","Malware","Firmware"]', 1, 'Hardware refers to the tangible parts of a computer, such as the monitor, keyboard, and CPU.', NULL, 'WAEC_Commerce_2024.json', '608cbf4222013ca21b666d333ad3af65444b0eff1fe288e2b71ea1ba6fb4a186');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is a form of oral communication?', '["Telex","Teleconferencing","Memorandum","Letter"]', 1, 'Teleconferencing involves spoken interaction between people in different locations, making it a form of oral communication.', NULL, 'WAEC_Commerce_2024.json', 'fdf89a43848d96414ae1377df9a5830043258c8c8e4390749dcb6ca83b47e9aa');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A market where only government bonds and industrial shares are traded is the _____.', '["Commodity market","Capital market","Money market","Labour market"]', 1, 'The capital market deals with long-term finance, including stocks, shares, and bonds.', NULL, 'WAEC_Commerce_2024.json', '4d2d1f221f553c32b78c79a9f5aaa18306b1b73d547176f37cf61639695c950a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is an example of sales promotion?', '["Television advertisement","Radio jingle","Buy-one-get-one-free offer","Billboard"]', 2, 'Sales promotion involves short-term incentives to encourage the purchase of a product, such as discounts or free gifts.', NULL, 'WAEC_Commerce_2024.json', '946e5ed23ca673d839f0d433d3808fd74af7ea22b080cfdce725dcffd853ad39');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A document sent by a seller to a buyer when goods are delivered as a summary of the transaction is a/an _____.', '["Invoice","Consignment note","Pro-forma invoice","Order"]', 0, 'The invoice is a bill that gives details of the goods sold, their prices, and the total amount due.', NULL, 'WAEC_Commerce_2024.json', '9535734ffe7c18bdd16481c40c42d234fc902008b971b0422bb483de4dc44d88');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The primary aim of a consumer cooperative society is to _____.', '["make as much profit as possible","provide goods at reasonable prices to members","control the government","prevent non-members from buying goods"]', 1, 'Consumer cooperatives are formed by individuals to pool resources and purchase goods in bulk, passing the savings to members.', NULL, 'WAEC_Commerce_2024.json', 'ac63cb3bb0b2001ce1442f120cb1f8e1337c9f5548da23e031425a3974aa183d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The process of setting up a business in a way that minimizes tax liability within the law is _____.', '["Tax evasion","Tax avoidance","Tax refund","Tax holiday"]', 1, 'Tax avoidance is the legal use of the tax regime to one''s advantage, unlike tax evasion which is illegal.', NULL, 'WAEC_Commerce_2024.json', '306e5c2eea341203faee95daa3ce150be9f710d63f879cd3e255664905502e17');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is a function of NAFDAC in Nigeria?', '["Regulating the transport industry","Providing insurance for businesses","Ensuring the quality of food and drugs","Managing the stock exchange"]', 2, 'NAFDAC (National Agency for Food and Drug Administration and Control) regulates and controls the manufacture and sale of food, drugs, and chemicals.', NULL, 'WAEC_Commerce_2024.json', '0901e86f6a5bfa6a5c0879bd49d86b416b1cc3d99e0aae4607af119a91f0fc9a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The ''Bear'' in the stock exchange is an investor who _____.', '["expects share prices to fall","expects share prices to rise","is a newcomer to the market","only buys gold"]', 0, 'A Bear is a pessimistic investor who sells shares expecting the price to drop so they can buy them back cheaper.', NULL, 'WAEC_Commerce_2024.json', '465b751ac8565bc6e02c8f66e70bd6f73f19745c3802c771d60a112aaf65fd91');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A contract that is binding on only one party is described as _____.', '["Valid","Void","Voidable","Unenforceable"]', 2, 'A voidable contract is one that can be affirmed or rejected by one of the parties, often due to misrepresentation or duress.', NULL, 'WAEC_Commerce_2024.json', 'e7f972a3b2e0a294137b2283cdc1ad6bcd96b46e305823864967f9c98cf92887');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The document showing the evidence of a contract of insurance is the _____.', '["Premium","Policy","Proposal form","Cover note"]', 1, 'The insurance policy is the formal document containing all the terms and conditions of the insurance contract.', NULL, 'WAEC_Commerce_2024.json', 'c8119c39b8347fd4a910a0912e4b177926447c9a2d5b4193ab9528859da19781');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is a type of internal trade?', '["Export trade","Import trade","Wholesale trade","Entrepôt trade"]', 2, 'Wholesale trade happens within the boundaries of a single country, making it a form of home/internal trade.', NULL, 'WAEC_Commerce_2024.json', 'd12954f1c1973dc4253852c4e3710b2d8bfa81778a24bdf3476365ec7afc4352');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A person who is authorized to act on behalf of another person (the principal) is a/an _____.', '["Employee","Partner","Agent","Contractor"]', 2, 'Agency is a relationship where the agent is empowered to create legal relations between the principal and third parties.', NULL, 'WAEC_Commerce_2024.json', 'd68e11e56c43d90baa795d9cb6a4603bcaabe4d88673742ab2f435ec44204779');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The ''Standard Organization of Nigeria'' (SON) is primarily concerned with _____.', '["labor disputes","quality control of manufactured goods","issuing international passports","controlling the price of fuel"]', 1, 'SON ensures that products manufactured or sold in Nigeria meet certain quality and safety standards.', NULL, 'WAEC_Commerce_2024.json', 'dd34badfddbb0f3542e3bbedff0dadb13921b20de0928c4ca4b7300ceb1a533d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The practice of using a brand name that is well known to sell a new product is _____.', '["Personal selling","Branding","Packaging","Market research"]', 1, 'Branding helps to differentiate products and build customer loyalty based on the reputation of the name.', NULL, 'WAEC_Commerce_2024.json', 'b18665c35cce55d869f44d65217570cc7617fbbe6ace5d5d5df6ceea4b0027b0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is a function of the retailer?', '["Providing bulk storage for manufacturers","Selling in small quantities to consumers","Producing raw materials","Transporting goods across borders"]', 1, 'Retailers buy from wholesalers or manufacturers and sell in small units to the final consumers.', NULL, 'WAEC_Commerce_2024.json', '31145965cbd7f2ebe352c17488dd45956aab8ab2084f97527af6d92dc7c03af5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A cheque that is not presented for payment within six months of its issue is a _____.', '["Stale cheque","Post-dated cheque","Ante-dated cheque","Open cheque"]', 0, 'A stale cheque is one that is too old to be honored by the bank, usually after six months.', NULL, 'WAEC_Commerce_2024.json', '399148aff00d42828bdc0e00cb7099c4366853c1780e5b74f6de93a280f7c3e1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following means ''let the buyer beware''?', '["Caveat Emptor","Uberrimae Fidei","Res ipsa loquitur","Nemo dat quod non habet"]', 0, 'Caveat Emptor is a legal principle placing the responsibility on the buyer to examine goods before purchasing.', NULL, 'WAEC_Commerce_2024.json', 'd15905163b378d401190685a2b29741f39a137bc3bea1f03f6e2fe6928e401b1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The cost of transporting goods to the buyer''s premises is known as _____.', '["Carriage inward","Carriage outward","Freight","Demurrage"]', 1, 'Carriage outward is the shipping cost paid by the seller to deliver goods to a customer.', NULL, 'WAEC_Commerce_2024.json', 'eaaabae202b06fb93e4138298c445e3e7b4dbaa09700d0ef893ac5447ea6fb12');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A trade where goods are imported and then re-exported to another country is _____.', '["Retail trade","Entrepôt trade","Bilateral trade","Home trade"]', 1, 'Entrepôt trade involves importing goods from one country for the purpose of exporting them to another.', NULL, 'WAEC_Commerce_2024.json', '5bf281b35aa92690dacc9a02980581a982910f7e2ce0e706be74145e16dc1d61');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is a source of short-term finance for a business?', '["Issue of shares","Debentures","Bank overdraft","Mortgage"]', 2, 'A bank overdraft is a facility that allows a customer to withdraw more than they have in their account for a short period.', NULL, 'WAEC_Commerce_2024.json', '6aef627640a7f8906646ab6f68d56a7ff33a578aa5c25bee5861aba0c67df83a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The first step in the formation of a company is the _____.', '["Issuing of prospectus","Obtaining a trading license","Preparation of constitutional documents","Appointing an auditor"]', 2, 'Before a company can be registered, the promoters must prepare the Memorandum and Articles of Association.', NULL, 'WAEC_Commerce_2024.json', '549372524c7b96c9583ac6adacea0c2098a7f549192b5d1bda34f0cbc15c33e7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'An advertisement that aims at creating a favorable image for a company rather than selling a specific product is _____.', '["Informative advertising","Persuasive advertising","Institutional advertising","Competitive advertising"]', 2, 'Institutional advertising builds the brand''s reputation and corporate identity in the eyes of the public.', NULL, 'WAEC_Commerce_2024.json', 'c6f39adea95328b701464fb5bf5347bcda5084b01c414afd57b3dcfc3d289894');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is an example of a public corporation in Nigeria?', '["Dangote Group","MTN Nigeria","Nigerian National Petroleum Company Limited","Guaranty Trust Bank"]', 2, 'Public corporations are organizations owned and controlled by the government to provide essential services.', NULL, 'WAEC_Commerce_2024.json', '4a01c7eb056fb5555d14f057197a3d0b56afebf6a76160b75bc48a6e9fa5267d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The person who starts and manages a business, taking on financial risks, is a/an _____.', '["Manager","Director","Entrepreneur","Shareholder"]', 2, 'An entrepreneur is the visionary who organizes the factors of production and bears the risk of profit or loss.', NULL, 'WAEC_Commerce_2024.json', '2f56427fb7d3cbbb07d1f6047f0f17af4ba72fb242565f73d6a1b33fb031987a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following allows a person to withdraw money from their bank account at any time using a machine?', '["Credit card","Automated Teller Machine (ATM)","Voucher","Pay slip"]', 1, 'ATMs provide 24/7 access to banking services like withdrawals and transfers.', NULL, 'WAEC_Commerce_2024.json', 'e2b17d8579757bba7341c59d086f2dd1faf74e18b80e0d37c98aa313cb0d24b9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The term ''f.o.b'' in international trade stands for _____.', '["Forward on board","Free on board","Freight on board","Fixed on board"]', 1, 'Free on board means the seller''s responsibility ends once the goods are loaded onto the ship.', NULL, 'WAEC_Commerce_2024.json', '31900ad1c580c5fb0771bb68c0be30c3ff021796711878d72eea790d2cf2a0f1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A warehouse built near a port to store goods for a short time before they are loaded onto a ship is a _____.', '["State warehouse","Transit shed","Cold store","Bonded warehouse"]', 1, 'Transit sheds are temporary storage facilities at ports for goods awaiting shipment or collection.', NULL, 'WAEC_Commerce_2024.json', 'a9b5700368b9114562461db7bc63fb1926317608cf9200efa9e8016cbf0f027c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is a characteristic of a sole proprietorship?', '["Easy to form","Continuity of existence","Limited liability","Separation of ownership and control"]', 0, 'Sole proprietorships are the simplest businesses to start as they require few legal formalities.', NULL, 'WAEC_Commerce_2024.json', '0d527e057941a304e121cfffc4397992320fbe9455d6628968360365b6198c8e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A person who buys goods from a manufacturer in large quantities is a _____.', '["Consumer","Retailer","Wholesaler","Broker"]', 2, 'Wholesalers are the middlemen who bridge the gap between large-scale producers and small-scale retailers.', NULL, 'WAEC_Commerce_2024.json', '735c7c4f4a09b9718489266ba62d6d380a9c16b2398e39cce4ba277bb3beb3ca');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The document that provides a description of the company and invites the public to buy shares is the _____.', '["Articles of Association","Certificate of Trading","Prospectus","Dividend warrant"]', 2, 'A prospectus is a legal notice issued by a public company to attract investors to its shares or debentures.', NULL, 'WAEC_Commerce_2024.json', '6199553262785e2d269afb7dfccc7d4cb1364ef02987de7d49d3b53d8c65acf2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The fee paid to an insurance company for cover against a risk is the _____.', '["Commission","Dividend","Premium","Interest"]', 2, 'The premium is the periodic payment made by the insured to the insurer in exchange for the promise of compensation.', NULL, 'WAEC_Commerce_2024.json', '7d59ffef2740e0121eae312e49d80a856e7bff734a71896adc42ee85f2bbcac4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is a function of the Stock Exchange?', '["Providing loans to small businesses","Regulating the insurance industry","Providing a market for old securities","Selling consumer goods"]', 2, 'The stock exchange provides a secondary market where investors can trade existing shares and bonds.', NULL, 'WAEC_Commerce_2024.json', 'd75290a61a2ea1e5d43a6466266ad295508f95bcbe0616cd4d11b70af7e149f3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The systematic record of all economic transactions between a country and the rest of the world is the _____.', '["Terms of trade","Balance of payments","Balance of trade","Gross National Product"]', 1, 'The Balance of Payments (BOP) accounts for all visible and invisible trade, as well as capital movements.', NULL, 'WAEC_Commerce_2024.json', '86fa471c4e1ab943c082deae23ded9faba935b599934b9981a69797c014d891e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A specialized bank that provides long-term credit for industrial and agricultural projects is a _____.', '["Commercial bank","Savings bank","Development bank","Merchant bank"]', 2, 'Development banks (like the Bank of Industry in Nigeria) focus on financing specific sectors of the economy for growth.', NULL, 'WAEC_Commerce_2024.json', '2fd2c76bd766fe223695d0aa9a67b53beec1e23d0b07b1bfd0ba08913cf91b0e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The use of the internet to buy and sell goods and services is _____.', '["E-mail","E-commerce","E-government","E-learning"]', 1, 'Electronic commerce includes online shopping, digital payments, and internet banking.', NULL, 'WAEC_Commerce_2024.json', 'c8c346741524c42a103be28f7fda45cb6359aebbc2513ade3bf17a4cfa05926a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is an example of a service-providing occupation?', '["Lumbering","Teaching","Mining","Carpentry"]', 1, 'Teaching is a tertiary activity where skills and knowledge are provided rather than a physical product.', NULL, 'WAEC_Commerce_2024.json', 'a8065e8b74956e8cd175463b2debe106a82c028ba6950be5a216ece6a122584d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A document used to transfer the ownership of a motor vehicle is a/an _____.', '["Invoice","Log book","Waybill","Debit note"]', 1, 'The log book or vehicle registration document serves as proof of ownership for motor vehicles.', NULL, 'WAEC_Commerce_2024.json', 'f4cdaf215f0545d5a783b745aaca9595bfbef94467e53cacbc25dd87ed49c7d2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The ''Law of Contract'' requires that for an agreement to be valid, there must be _____.', '["at least ten parties","an offer and an acceptance","a lawyer present","payment in foreign currency"]', 1, 'Offer and acceptance are the two most fundamental elements of a valid contract.', NULL, 'WAEC_Commerce_2024.json', '9f7deb4f4963efae791a7f24ac36943659c4fadc41922a84d7bfc8d2bd2fa1f5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The compensation paid to a stockbroker for his services is _____.', '["Profit","Salary","Commission","Interest"]', 2, 'Stockbrokers earn ''brokerage'' or commission based on the value of the shares they trade for their clients.', NULL, 'WAEC_Commerce_2024.json', '098b9f8985107b4367f2fd09bf2c893a53f403e7d3e7d1a8a4db4c3bd039177d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is a characteristic of a public limited company?', '["Maximum of 50 members","Shares are not transferable","Minimum of seven members","Accounts are kept secret"]', 2, 'Under the Nigerian CAMA, a public company must have at least seven members, and there is no upper limit on the number of shareholders.', NULL, 'WAEC_Commerce_2024.json', 'b978baf7ac8b86bcb205a6089ff971cd840ad3cd19a516ed540e2619c884f201');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'A market where commodities are bought and sold for immediate delivery is the _____.', '["Future market","Spot market","Black market","Open market"]', 1, 'In a spot market, transactions are settled ''on the spot'' with immediate physical delivery of the commodity.', NULL, 'WAEC_Commerce_2024.json', 'af2dff19590d9b756be9679c897b9f9a36bb13aed000576f9190d08605ef5242');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is a barrier to international trade?', '["Language differences","Use of the internet","Efficient transport","Standardization of products"]', 0, 'Language barriers can make communication and negotiations difficult between traders from different countries.', NULL, 'WAEC_Commerce_2024.json', 'c266fd836d77a126eb7e4b70c84c9bc88154d71fae055ae59b7e8ec76b5c6981');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The ''Money Market'' is a market for _____.', '["long-term loans","short-term loans","buying and selling foreign currency","illegal money"]', 1, 'The money market deals with financial assets that have a maturity period of one year or less, such as treasury bills.', NULL, 'WAEC_Commerce_2024.json', '2a872598129d7183cee272b4a272a10b2fc7af964a796c74e2d3faea86aee7c1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The practice of protecting local industries by placing high taxes on imported goods is _____.', '["Free trade","Devaluation","Protectionism","Globalization"]', 2, 'Protectionism uses tariffs and quotas to make foreign goods more expensive, encouraging people to buy local products.', NULL, 'WAEC_Commerce_2024.json', '4adb89c2b2da7d7ef55be88829954c45aff426c5f79d2bf02fe70485d5babc5f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'Which of the following is a function of advertising?', '["To increase the cost of production","To inform the public about new products","To create a shortage of goods","To discourage competition"]', 1, 'Advertising serves to create awareness and provide information to potential customers about the features and benefits of a product.', NULL, 'WAEC_Commerce_2024.json', '7f8189ed9917e5504f3b4872dc32f5cc7b202bc48b1f9122655678aa6a171aae');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2024, NULL, 'The profit shared among the members of a cooperative society is based on _____.', '["the amount of capital contributed","their level of education","the volume of their patronage","their age"]', 2, 'In many cooperatives, the ''dividend'' or surplus is distributed according to how much a member used the society''s services during the year.', NULL, 'WAEC_Commerce_2024.json', '9be4d17e566664e01a8d12fba5a3ccbd236cd91d8964a0e1a8d9336fdaea4b04');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2025, NULL, 'Commerce is defined as:', '["Trade and Aids to Trade","Buying and Selling","Production","Marketing"]', 0, NULL, NULL, 'WAEC_Commerce_2025.json', '6248ddabf71ae77ee3720ce0ecc1699f31d6f8a44f425e76e6c68cf2745bbad7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2025, NULL, 'Which is an aid to trade?', '["Banking","Farming","Mining","Fishing"]', 0, NULL, NULL, 'WAEC_Commerce_2025.json', 'ec2c4602a586397ca2436eadfeb901466923ed39502558d5fafe8caea277dc4d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2025, NULL, 'Production is complete when goods reach the:', '["Consumer","Retailer","Wholesaler","Factory"]', 0, NULL, NULL, 'WAEC_Commerce_2025.json', '76dd1afd526ec2ca290b5f93cba910dfc893a32061452a9430044e6ea6572fd1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2025, NULL, 'Sole proprietorship has:', '["Unlimited liability","Limited liability","Joint liability","No liability"]', 0, NULL, NULL, 'WAEC_Commerce_2025.json', 'bfaa6a4c086e3d270638be4d53edd91a407d9d0daa485f121dc3447a7b7e9787');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2025, NULL, 'Partnership is formed by:', '["Deed","Prospectus","Certificate","Memo"]', 0, NULL, NULL, 'WAEC_Commerce_2025.json', 'e65b541d444a05afb4186aae781e36a2f518518462497bf9a6393b0967bf4ace');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2025, NULL, 'Capital of a PLC is in:', '["Shares","Debentures","Bonds","Loans"]', 0, NULL, NULL, 'WAEC_Commerce_2025.json', '51670e16bd631f45376e950d64227a95e1049b5943fe07c56624a2eac3eeecc3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Commerce', 2025, NULL, 'Wholesaler breaks bulk for:', '["Retailer","Consumer","Producer","Agent"]', 0, NULL, NULL, 'WAEC_Commerce_2025.json', 'd93e3e2af2cc4eb6b64e6e48f8e6d7edd09216c843fba03cacaa53cabe347c0c');
