INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The first generation of computers used _____ as their primary electronic component.', '["Vacuum Tubes","Transistors","Integrated Circuits","Microprocessors"]', 0, 'First-generation computers (1940-1956) relied on vacuum tubes for circuitry and magnetic drums for memory, making them bulky and expensive.', NULL, 'WAEC_Computer_2024.json', 'fc2a648b21d68c0955a8a40dd6f41f03958794afd8b6fc9f92efe8217c17b1b6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which of the following is an example of an Operating System?', '["Microsoft Word","Linux","Google Chrome","Oracle"]', 1, 'Linux is a system software (Operating System) that manages computer hardware and software resources. The others are application softwares.', NULL, 'WAEC_Computer_2024.json', '63dcd6049bda00927188a7a45b6a976c32c2e0ffa872274b32950754787787d6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The binary equivalent of the decimal number 10 is _____.', '["1001","1010","1100","1111"]', 1, 'To convert 10 to binary: 10/2 = 5 R 0; 5/2 = 2 R 1; 2/2 = 1 R 0; 1/2 = 0 R 1. Reading remainders from bottom to top gives 1010.', NULL, 'WAEC_Computer_2024.json', '0cac70f8cdf0a58d6ba5c1a929b4479f0abd5d02f2949ef693f80271ab44fb2d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which part of the CPU is responsible for performing mathematical calculations?', '["Control Unit","Registers","Arithmetic and Logic Unit","Cache Memory"]', 2, 'The Arithmetic and Logic Unit (ALU) performs all arithmetic (addition, subtraction) and logical (comparisons) operations.', NULL, 'WAEC_Computer_2024.json', '84cf1ed958411360b308fd57fec8e546c1f82d1485671631943336c7aee29175');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'A collection of 8 bits is known as a _____.', '["Nibble","Byte","Word","Kilobyte"]', 1, 'A byte is a unit of data that is eight binary digits long. A nibble is 4 bits.', NULL, 'WAEC_Computer_2024.json', 'b06e258df32f3ad7f43d2efb3c078df0eb1954ece89af8540c42010dbd10ba83');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which logic gate produces an output of 1 only when all its inputs are 1?', '["OR gate","AND gate","NOT gate","NAND gate"]', 1, 'In an AND gate, the output is high (1) if and only if all the input signals are high (1).', NULL, 'WAEC_Computer_2024.json', 'c74133f2519ec7f3219538c5318d0f6347fcf372b1d1ea3f30ab677e51bf23ce');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The primary purpose of a modem is to _____.', '["Store data","Convert signals between analog and digital","Speed up the CPU","Clean the computer of viruses"]', 1, 'A modem (modulator-demodulator) converts digital signals from a computer into analog signals for transmission over telephone lines and vice versa.', NULL, 'WAEC_Computer_2024.json', '3f7a5160e2eebbdff45a5e9e7dcc1b7a678883da14625195cab027558d598415');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'In Microsoft Excel, the intersection of a row and a column is called a _____.', '["Box","Table","Cell","Range"]', 2, 'A cell is the basic unit of a spreadsheet where data is entered, identified by a column letter and row number (e.g., A1).', NULL, 'WAEC_Computer_2024.json', 'b1f7fe800cc42173ab1999847d469f01826bf2e73710642d2cd800c62e63e3cc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which of the following is a permanent storage device?', '["RAM","Cache","Hard Disk Drive","Registers"]', 2, 'Hard Disk Drives are non-volatile storage, meaning they retain data even when the power is turned off. RAM and Cache are volatile.', NULL, 'WAEC_Computer_2024.json', 'e99a59cab8b37b130e2294cdd30a49331ea31bab0eb49b585bba6a99f83d9b05');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The process of starting or restarting a computer is known as _____.', '["Loading","Booting","Processing","Executing"]', 1, 'Booting is the initial set of operations that a computer system performs when electrical power is switched on.', NULL, 'WAEC_Computer_2024.json', '9586e52770858ced3f376d8f20c22fd2af751258838437463f8665e22d5a0544');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which networking topology connects all devices to a single central cable?', '["Star","Bus","Ring","Mesh"]', 1, 'In a bus topology, all nodes are connected to a main transmission line (backbone).', NULL, 'WAEC_Computer_2024.json', '069b506dc8e9433f42e7e951d8e754f6e249f1d1977a87f8918d6be0538a26f5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'HTTP stands for _____.', '["Hypertext Transfer Protocol","Hyperlink Text Technical Program","High Tech Transfer Protocol","Hypertext Total Process"]', 0, 'HTTP is the standard protocol used to transfer data over the World Wide Web.', NULL, 'WAEC_Computer_2024.json', 'cab394aa759bdd5888b94f9f33385219e82da64ccbf1a9b4eb9d67fb9becc6fb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'A unique field in a database table that identifies each record is called a _____.', '["Foreign Key","Primary Key","Composite Key","Candidate Key"]', 1, 'The Primary Key is a column or set of columns that uniquely identifies every row in a table.', NULL, 'WAEC_Computer_2024.json', 'c254d7d6849e185de4be139c77ef4c4a8026ed8f2a4390b9acde16dc416b2e8d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which of the following is an input device?', '["Monitor","Printer","Scanner","Speaker"]', 2, 'A scanner is an input device that captures images from photographic prints, posters, and similar sources for computer editing.', NULL, 'WAEC_Computer_2024.json', '83ab960237df571ff35589e6f2eaf97e47b2b8505792f69c3359c8bd51e55940');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The high-level programming language developed for business data processing is _____.', '["FORTRAN","COBOL","BASIC","Pascal"]', 1, 'COBOL (Common Business-Oriented Language) was designed specifically for business, finance, and administrative systems.', NULL, 'WAEC_Computer_2024.json', '73cd24c54a7c28674d060bb72fb097f711cd4da402cb4f3478a6d24c473672f6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'What is the result of the binary addition 1 + 1?', '["2","10","11","0"]', 1, 'In binary, 1+1 equals 0 with a carry of 1, represented as 10 (which is the binary for decimal 2).', NULL, 'WAEC_Computer_2024.json', '0be89d132417b544c40b6d37b7101b37cc059c1a035a7f45a12abc12bbb2eef8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Malicious software designed to infiltrate or damage a computer system is called _____.', '["Firmware","Shareware","Malware","Freeware"]', 2, 'Malware is a broad term that includes viruses, worms, trojans, and spyware.', NULL, 'WAEC_Computer_2024.json', 'bab54bfb253bdb528b30cf84d0ba9f5f1158028f46e1a6b0ae08a7e46640045b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'In a database, a row is also referred to as a _____.', '["Field","Record","Table","Data type"]', 1, 'A record (or row) contains a complete set of data for a single entity in a database table.', NULL, 'WAEC_Computer_2024.json', '95e0f8aba096e57d64e07fa0d7e2ca0a494b589d8e2a6f0a04c1a7a4584a4883');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which of the following units is used to measure CPU speed?', '["Gigabytes","Hertz","Pixels","Bps"]', 1, 'CPU speed is measured in cycles per second, known as Hertz (typically MHz or GHz).', NULL, 'WAEC_Computer_2024.json', '80a75ea79ff0210983b33867ad46a9f0b27b417c79ec1f31c26618b53f321a1b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The software that translates high-level code into machine code line by line is a/an _____.', '["Compiler","Interpreter","Assembler","Linker"]', 1, 'An interpreter translates and executes code one statement at a time, whereas a compiler translates the whole program at once.', NULL, 'WAEC_Computer_2024.json', '772a2ca9ebca04c60c8cbd9f88c9b56197bca8d51a4db8485cb633f7b23cf6e4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which layer of the OSI model is responsible for routing data packets?', '["Data Link Layer","Network Layer","Transport Layer","Physical Layer"]', 1, 'The Network Layer handles the addressing and routing of data packets across different networks.', NULL, 'WAEC_Computer_2024.json', '072adcded1f62451530cf940f3fe4e7e407c534e878fb4fdf6e4a29f2c2e54f8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'A network that covers a small geographical area like a single office is a _____.', '["WAN","MAN","LAN","PAN"]', 2, 'Local Area Network (LAN) is used to connect computers within a small area like a room or a building.', NULL, 'WAEC_Computer_2024.json', '6c9d03a96047d27d9bebf52ee0e64f702d7014e100017a396cb06bdef3621277');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The hexadecimal number system uses base _____.', '["2","8","10","16"]', 3, 'Hexadecimal uses sixteen distinct symbols: 0–9 and A–F.', NULL, 'WAEC_Computer_2024.json', '96e0d411bea4cdf8139e7b168568dac0432e5e148ace0c80cd5baff5838f3350');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which of the following is used to uniquely identify a computer on the internet?', '["MAC Address","IP Address","URL","HTML"]', 1, 'An IP Address is a numerical label assigned to each device participating in a computer network that uses the Internet Protocol.', NULL, 'WAEC_Computer_2024.json', 'a08535b691045852a7ba00198f17eee317708e06e6ab192ad3e749c9e12becf5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'In HTML, which tag is used to create a hyperlink?', '["<link>","<a>","<href>","<u>"]', 1, 'The <a> (anchor) tag is used to define a hyperlink, which links one page to another.', NULL, 'WAEC_Computer_2024.json', 'e134838cc64e2ded14a480a30e61101aede7b557e8efd52a85264442e59a8ca0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which memory type must be constantly refreshed to retain data?', '["SRAM","DRAM","ROM","Flash Memory"]', 1, 'Dynamic RAM (DRAM) uses capacitors that leak charge and thus must be refreshed periodically.', NULL, 'WAEC_Computer_2024.json', 'e0b0696dd739a47608ab3f8d4ec29eed2ab097c7d57ebdc29e6a62eec0830062');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The shortcut key to ''Paste'' a copied item in Windows is _____.', '["Ctrl + C","Ctrl + X","Ctrl + V","Ctrl + P"]', 2, 'Ctrl + V is the standard Windows keyboard shortcut for pasting data from the clipboard.', NULL, 'WAEC_Computer_2024.json', '6abd34deb2c027b78c352bcb3bd3cb2829924444bc1805a278675fe5e28eb17b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'A pre-defined formula in Excel is known as a _____.', '["Variable","Function","Argument","Operator"]', 1, 'Functions (like SUM, AVERAGE) are built-in formulas in Excel that perform specific calculations.', NULL, 'WAEC_Computer_2024.json', '17fa08587cef1e0252ebcbaac8f041828e6e8b353c9e4267232330ed266115d2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The act of pretending to be a trustworthy entity to steal sensitive information online is called _____.', '["Spamming","Phishing","Hacking","Cracking"]', 1, 'Phishing involves sending fraudulent communications (like emails) that appear to come from a reputable source.', NULL, 'WAEC_Computer_2024.json', '5f7a38d2f1e5bea46fbf17eb8788ba64193e3bc70589ac27c40154f0478de8ed');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which computer generation introduced the use of Integrated Circuits (ICs)?', '["Second","Third","Fourth","Fifth"]', 1, 'The third generation (1964-1971) replaced transistors with Integrated Circuits, which increased speed and efficiency.', NULL, 'WAEC_Computer_2024.json', '864030624fd97f44f5f3a64dcc6ffc5453c4d096c0387fa44516856e8c0b36c9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The main circuit board of a computer is the _____.', '["Hard drive","Microprocessor","Motherboard","Power Supply"]', 2, 'The motherboard is the primary printed circuit board that connects all components of a computer system.', NULL, 'WAEC_Computer_2024.json', 'd67ef5d4683f34b1c2d9114fd6f6806533845f7ee2aa5617fa27b3513c90d464');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'What does PDF stand for?', '["Personal Data File","Portable Document Format","Printable Digital File","Public Document Folder"]', 1, 'PDF is a file format developed by Adobe to present documents in a manner independent of application software, hardware, and operating systems.', NULL, 'WAEC_Computer_2024.json', 'a514562c0040329c52a55187223424b12d955a36c9ee9165c1d134bfd1978c6f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The binary system uses only the digits _____.', '["1 and 2","0 and 1","0 to 9","A and B"]', 1, 'Binary is a base-2 number system representing values using only 0 (off) and 1 (on).', NULL, 'WAEC_Computer_2024.json', '516f37a3d012fdcecb51e29c5da02e18bcd2a475f767c15cf8411c7a4b6f2afa');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which of the following is a cloud storage service?', '["VLC Media Player","Google Drive","WinZip","Adobe Reader"]', 1, 'Google Drive is a file storage and synchronization service developed by Google.', NULL, 'WAEC_Computer_2024.json', '425da5be018e5324a38473fe63bb4cd1f0310c802256cf6186e503b1736e3af1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The first phase of the System Development Life Cycle (SDLC) is _____.', '["System Design","Feasibility Study","System Implementation","System Analysis"]', 1, 'SDLC typically begins with Preliminary Investigation or Feasibility Study to determine if the project is worth pursuing.', NULL, 'WAEC_Computer_2024.json', '21e6e408ca888215287dadc0cf0d15729824124d2cf3a85c3575385df934adbb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Convert the binary number 111 to decimal.', '["3","5","7","9"]', 2, '(1 * 2^2) + (1 * 2^1) + (1 * 2^0) = 4 + 2 + 1 = 7.', NULL, 'WAEC_Computer_2024.json', '06e85047e512ceb227970070b0d44af020a6d9bc555a78dbb2baea774e50bd9e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'A pixel is _____.', '["A computer program","The smallest unit of a digital image","A type of storage device","An internet protocol"]', 1, 'Pixels are the small dots that make up the images on computer displays.', NULL, 'WAEC_Computer_2024.json', 'b9d0b738d2274e2158534dab70c366a85a1b6b66e4758c2d6335d6f841eeb37a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which of the following is a high-level language?', '["Assembly","Machine code","Python","Mnemonics"]', 2, 'Python is a high-level, interpreted, general-purpose programming language. Assembly and Machine code are low-level.', NULL, 'WAEC_Computer_2024.json', 'f8c479b44388ded2eff132cf3f316e4e649520efe5709e20f83ce8d5323969f1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The most widely used input device on a laptop is a _____.', '["Joystick","Touchpad","Light pen","Trackball"]', 1, 'A touchpad is a pointing device featuring a tactile sensor that translates the motion and position of a user''s fingers.', NULL, 'WAEC_Computer_2024.json', '82b96be234b054d602088bf923eca1337624106e6e80ad1cd669dacab87fdd41');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'A website''s main page is called the _____.', '["First page","Home page","Index","Browser"]', 1, 'The home page is the introductory page of a website, typically serving as a table of contents.', NULL, 'WAEC_Computer_2024.json', 'f11e1ec6e24c13014c971ebd3a151b30cfe67c35857d48a406f7bc8ec2c9abb8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which device is used to protect a computer system from power surges?', '["Inverter","UPS","CPU","VGA"]', 1, 'An Uninterruptible Power Supply (UPS) provides battery backup when the electrical power fails or drops to an unacceptable voltage level.', NULL, 'WAEC_Computer_2024.json', '8ac50827b4a2be0686b85441dde645ed3bfb470707c8d36dfa9b9eadb0bd8f4d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which protocol is used for sending emails?', '["HTTP","SMTP","FTP","IP"]', 1, 'Simple Mail Transfer Protocol (SMTP) is the standard protocol for sending emails across the Internet.', NULL, 'WAEC_Computer_2024.json', 'b85300b260c4372622344394199975f03aa87293744db88ff7a769dbec506015');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'An 8-bit byte can represent _____ different values.', '["8","64","128","256"]', 3, '2 raised to the power of 8 (2^8) equals 256.', NULL, 'WAEC_Computer_2024.json', '31f7360a21ffedd62c3dca88d24c1caa0c32bb057d6e2c90483cd755cf01d72f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The file extension for a PowerPoint presentation is usually _____.', '[".docx",".xlsx",".pptx",".txt"]', 2, '.pptx is the standard file extension for Microsoft PowerPoint presentations created in versions 2007 and later.', NULL, 'WAEC_Computer_2024.json', '6d1052e946b8a122b900826bd04244e0cea5eb6a1b7fc3ed74531c19968bed89');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which of the following is an example of an output device?', '["Keyboard","Mouse","Plotter","Microphone"]', 2, 'A plotter is a printer that uses a pen to draw images, commonly used for technical drawings.', NULL, 'WAEC_Computer_2024.json', 'cc7e95138359e3c5c5002882ca018b5f465ee65c164b69fc389168f971522e3c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The brain of the computer system is the _____.', '["ALU","Memory","CPU","Control Unit"]', 2, 'The Central Processing Unit (CPU) is often referred to as the brain because it executes instructions and coordinates all activities.', NULL, 'WAEC_Computer_2024.json', 'aa3be9c9378b84f198efd7f7cb536fbdb835b2419d96f8929628e310df1f763e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'What is the function of the ''Undo'' command?', '["Delete a file","Reverse the last action","Save a document","Open a new window"]', 1, 'Undo (Ctrl+Z) allows a user to cancel the most recent command or action performed.', NULL, 'WAEC_Computer_2024.json', 'f40a3d8bed90beb0e06fbc9158a85729ae48db2908671bdf9aaf9b75d6f314fc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which of the following is a database management system (DBMS)?', '["MS Word","MS Access","MS PowerPoint","MS Publisher"]', 1, 'Microsoft Access is a pseudo-relational database management system.', NULL, 'WAEC_Computer_2024.json', '6cd645d717728e0324b387ca430ab8c36b437b1f635585743e9ccdffd524faef');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The physical path over which a message travels is called the _____.', '["Protocol","Medium","Signal","Topology"]', 1, 'The transmission medium (e.g., fiber optic cable, wireless) is the physical link between sender and receiver.', NULL, 'WAEC_Computer_2024.json', '7b8cce05c5940055c396d20971c477f2af0c451d17af19317478cb886a5aad4c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The base of the Octal number system is _____.', '["2","8","10","16"]', 1, 'Octal uses eight digits: 0, 1, 2, 3, 4, 5, 6, and 7.', NULL, 'WAEC_Computer_2024.json', '9ce8ab7e30aa9650b67a09acc107af9d05026b68652da5bed3551746eb88c3f8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'A program that manages all the other programs in a computer is the _____.', '["Utility Software","Operating System","Compiler","Application Software"]', 1, 'The OS acts as an intermediary between the user and the computer hardware.', NULL, 'WAEC_Computer_2024.json', '4353ed7378bf285122edf39c6f4bfb963541f32d73ea39f50fd1a72093717b19');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which of the following is used for video output?', '["VGA","USB","PS/2","RJ-45"]', 0, 'Video Graphics Array (VGA) is a standard connector for computer video output.', NULL, 'WAEC_Computer_2024.json', 'd7debd5a8ab9e5403fa9f04fac2e9d844e1791e8c1754fa76a8165dda10b9d3d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The ''logical'' part of a computer that you cannot touch is _____.', '["Hardware","Software","Peripheral","Memory"]', 1, 'Software consists of instructions and data that tell the hardware how to work.', NULL, 'WAEC_Computer_2024.json', 'ad3bc2568e1769216c3f4aa6f116d5f721d2a5540b0589e5bc61fbe3d5d46fe3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'WWW stands for _____.', '["World Wide Web","Web Wide World","Work Wide Web","Word Wide Web"]', 0, 'The World Wide Web is an information system where documents are identified by URLs.', NULL, 'WAEC_Computer_2024.json', '15adb4c9115189dfe0e660651555ff31a71990e4f872568d1af231943be7e16d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'A small image representing a program or file is a/an _____.', '["Folder","Icon","Window","Menu"]', 1, 'Icons are used in Graphical User Interfaces to represent applications, objects, or functions.', NULL, 'WAEC_Computer_2024.json', '1b6aced36865b7e39f88bfe229190f0b40f5ab049a8d6cb853eea33a4c4c46f7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which logic gate is also known as an ''Inverter''?', '["AND gate","OR gate","NOT gate","XOR gate"]', 2, 'A NOT gate is called an inverter because it reverses the input signal (1 becomes 0 and vice versa).', NULL, 'WAEC_Computer_2024.json', '6080f9d2e4d307b381fb2bae3102ebca6b6473e6c33b2fb9d048eff044bec779');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'What is the maximum data capacity of a standard CD-ROM?', '["700 MB","4.7 GB","25 GB","1.44 MB"]', 0, 'A standard Compact Disc (CD) typically holds 700 MB of data. 4.7 GB is the standard for a DVD.', NULL, 'WAEC_Computer_2024.json', '124a031fa276de3b5fbcbb39dd0588c7be7fb1f2877ee19a7e1b6bb461138ad5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The primary language used to create web pages is _____.', '["Python","C++","HTML","Java"]', 2, 'Hypertext Markup Language (HTML) is the standard markup language for documents designed to be displayed in a web browser.', NULL, 'WAEC_Computer_2024.json', '662db856c3de505d1280637f04bd0b40a2f13302464373a8c4b409269dfc0462');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which of the following is a portable computer?', '["Mainframe","Supercomputer","Desktop","Tablet"]', 3, 'Tablets and laptops are designed to be easily carried and used in various locations.', NULL, 'WAEC_Computer_2024.json', 'bf51acc98008f8135563c10beffbc5fe06760f323c3833876163fa3644cb03e0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'A computer on a network that requests resources is called a _____.', '["Server","Client","Router","Hub"]', 1, 'In a client-server model, the client requests services and the server fulfills them.', NULL, 'WAEC_Computer_2024.json', 'dbb3fdb81e293d3f3ef91f7d23b0e1f8cca47b4464afcda7ed0972598ddb6b8c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'The decimal equivalent of hexadecimal ''A'' is _____.', '["10","11","12","15"]', 0, 'In Hexadecimal, A=10, B=11, C=12, D=13, E=14, and F=15.', NULL, 'WAEC_Computer_2024.json', '7f2a7cc6329734f7b3db96b3bab4aaad3273a76d8962f0b3c3c0e059ee9eadd9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Computer', 2024, NULL, 'Which utility is used to reduce the size of files to save disk space?', '["Antivirus","Defragmenter","Compression","Backup"]', 2, 'File compression (like ZIP) reduces the file size by encoding data more efficiently.', NULL, 'WAEC_Computer_2024.json', 'cdc6a1799072f9a3fd6210e288cfeea9e6df2c1fc1a5243e30cfb323908e79e4');
