INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Economics is often defined as the study of scarcity and _____.', '["poverty","choice","wealth","money"]', 1, 'Because resources are limited (scarcity), individuals and societies must make choices about how to allocate them to satisfy unlimited wants.', NULL, 'WAEC_Economics_2024.json', '3a32325dd164f50cd1609ed6e5e47053abb3885da73507916c657047c34a537f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The fundamental economic problem facing every society is _____.', '["unemployment","inflation","scarcity","poverty"]', 2, 'Scarcity is the basic economic problem because resources are finite whereas human wants are infinite.', NULL, 'WAEC_Economics_2024.json', 'b3b9a83c47c710734d483a5f6d0bad3f100c92f22c9877f2548c314bf53324a9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The opportunity cost of a measure is the _____.', '["money cost of the measure","alternative forgone","sacrifice made by the consumer","total cost of production"]', 1, 'Opportunity cost refers to the next best alternative that is sacrificed when a choice is made.', NULL, 'WAEC_Economics_2024.json', '7174b788a5a82378c0ae3c785efffa79e5508fa2a517965359f23ce7a48cb9c8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'A production possibility curve (PPC) shows the _____.', '["rate of inflation in an economy","distribution of income","maximum combinations of two goods an economy can produce","total amount of money in circulation"]', 2, 'The PPC illustrates the trade-offs and limits of production for two goods given fixed resources and technology.', NULL, 'WAEC_Economics_2024.json', '251c49c272fbfa4ed0f5e957358eac19e206544abe5905d6b993eae01b669738');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'If the price of a commodity increases from #10 to #15 and the quantity demanded falls from 100 units to 50 units, the price elasticity of demand is _____.', '["0.5","1.0","1.5","1.0"]', 3, 'Percentage change in quantity = (50/100)*100 = 50%. Percentage change in price = (5/10)*100 = 50%. Elasticity = 50/50 = 1 (Unitary).', NULL, 'WAEC_Economics_2024.json', 'e5319068789432b01756a44913f4e52c54832c9f2b78bc0c7672e82a645c4322');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Which of the following is a characteristic of a free market economy?', '["Price fixing by the government","Public ownership of means of production","Consumer sovereignty","Central planning"]', 2, 'In a free market, consumers determine what is produced through their spending patterns, a concept known as consumer sovereignty.', NULL, 'WAEC_Economics_2024.json', '634d509e1adebacdf753e5958d34f9b9b4c00a22bb3f4d245e7e4e2ddc731f97');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The law of diminishing marginal utility states that as more of a product is consumed, the _____.', '["total utility increases at an increasing rate","marginal utility eventually decreases","total utility decreases","marginal utility remains constant"]', 1, 'The law posits that the additional satisfaction gained from consuming one extra unit of a good diminishes as the total quantity consumed increases.', NULL, 'WAEC_Economics_2024.json', '3a8664050c06f320a6fe60c42b2b160f247956cda712367bb9e7d0c915a3adcb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'A shift in the demand curve to the right indicates a/an _____.', '["decrease in demand","increase in quantity demanded","increase in demand","decrease in quantity demanded"]', 2, 'A rightward shift of the entire demand curve represents an ''increase in demand'' caused by factors other than price (e.g., rise in income).', NULL, 'WAEC_Economics_2024.json', '0121439a657a226823bab08a4ec4319fdaa78c0eb8d2ae6608001ef4d3b52bc1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'In a perfectly competitive market, the firm is a _____.', '["price maker","price taker","price discriminator","monopolist"]', 1, 'Individual firms in perfect competition are too small to influence market price; they must accept the prevailing equilibrium price.', NULL, 'WAEC_Economics_2024.json', 'bdac490642982173fe9f6532eebd07b02cf6d0dd08fe0db2806303ad48ac90e5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Which of the following is a factor of production?', '["Money","Enterprise","Shares","Interest"]', 1, 'The four factors of production are Land, Labour, Capital, and Enterprise (or Entrepreneurship).', NULL, 'WAEC_Economics_2024.json', 'ebac789aaa2815d5605743c2fafea58766494215e71a6a7d5187fbf92b5eec3e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Division of labour leads to _____.', '["decreased productivity","increased cost of production","specialization","waste of time"]', 2, 'Division of labour involves breaking down a production process into tasks, which allows workers to specialize and become more efficient.', NULL, 'WAEC_Economics_2024.json', '757a84ffc2c1aa4e72b40f1a41779bec7cd312c8669350a22b219cb558538866');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The S.I. unit of economic value in Nigeria is the _____.', '["Dollar","Pound","Naira","Cedi"]', 2, 'The Naira is the legal tender and unit of account used for economic transactions in Nigeria.', NULL, 'WAEC_Economics_2024.json', '038c95a3d89a48b1e25376a88ecee6ce6d242278a4c4ec1f97d93fb5dd1080ee');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'When Marginal Product (MP) is zero, Total Product (TP) is _____.', '["zero","at its minimum","at its maximum","equal to Average Product"]', 2, 'Total Product reaches its peak at the exact point where the additional unit of input adds nothing further to output (MP = 0).', NULL, 'WAEC_Economics_2024.json', '9548c8aaa551cca2b169212bbbc511c07e400641c703074bc61728e951d9c0e0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'An example of a fixed cost is _____.', '["raw materials","electricity bill","wages of casual workers","rent on factory building"]', 3, 'Fixed costs do not change with the level of output in the short run. Rent must be paid regardless of how much is produced.', NULL, 'WAEC_Economics_2024.json', '50c6a0a2332059eff16df497ac1dc51f2eb16bb4399425041882635da7030621');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'In economics, a market is defined as _____.', '["a place where people buy food","any arrangement for buyers and sellers to exchange goods","a physical building for trade","a government-controlled trading zone"]', 1, 'A market is not necessarily a physical location; it is any mechanism that facilitates the exchange of goods and services between buyers and sellers.', NULL, 'WAEC_Economics_2024.json', 'cf1ad3906d7d4f1032a47f30a79fc5536b8c18629ef61b45c36f1c19e519bd8e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'If demand is perfectly inelastic, the demand curve will be _____.', '["horizontal","vertical","downward sloping","upward sloping"]', 1, 'A vertical demand curve shows that the quantity demanded remains the same regardless of changes in price.', NULL, 'WAEC_Economics_2024.json', 'e0a95b9a74bbc92cba2e65c4c848c4a2c641f3700c039e9c0c110ed844ad9e65');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The primary function of the Central Bank of Nigeria is to _____.', '["accept deposits from the public","lend money for house construction","issue currency and control monetary policy","engage in retail banking"]', 2, 'The Central Bank acts as the issuing authority for legal tender and manages the country''s money supply and exchange rate.', NULL, 'WAEC_Economics_2024.json', '1fce3d5deeff07c1d1cf712e4d4a78b6f1ce5eaa4cc4355079edc53d4fd1142d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Inflation caused by an increase in the cost of raw materials is known as _____.', '["demand-pull inflation","cost-push inflation","hyperinflation","creeping inflation"]', 1, 'Cost-push inflation occurs when production costs (wages, raw materials) rise, forcing producers to increase prices.', NULL, 'WAEC_Economics_2024.json', '3097e4718efa9e73cf8d9c24a49ea20e36b532e0f765749c176e01f054479b03');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Which of the following is an example of an indirect tax?', '["Personal income tax","Company profit tax","Value Added Tax (VAT)","Capital gains tax"]', 2, 'Indirect taxes are levied on goods and services rather than individuals. The burden is passed to the consumer.', NULL, 'WAEC_Economics_2024.json', 'ddc569d3607ff6f298fac7c92c0851ab0cd21c203daa81574a51f8d5cb890310');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Gross Domestic Product (GDP) measures the value of goods and services produced _____.', '["by citizens of a country living anywhere","within the geographical boundaries of a country","by the government only","for export only"]', 1, 'GDP focuses on the location of production (within the country''s borders), regardless of the nationality of the producers.', NULL, 'WAEC_Economics_2024.json', '6ad1165890bdf305765ce8a11f4f5cc14f0c5a8cc55547a0f8619d0980c941ab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'A budget deficit occurs when _____.', '["revenue exceeds expenditure","expenditure exceeds revenue","exports exceed imports","imports exceed exports"]', 1, 'A deficit occurs when the government spends more money than it generates through taxes and other revenue sources.', NULL, 'WAEC_Economics_2024.json', 'd7230bd6b37fa6fbd2ae41c6d80f026173534d6eecf0d7e7b86fe86444148732');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The Malthusian theory of population suggests that population grows _____.', '["arithmetically","geometrically","linearly","slowly"]', 1, 'Thomas Malthus argued that population increases in a geometric progression (1, 2, 4, 8...) while food supply increases arithmetically (1, 2, 3, 4...).', NULL, 'WAEC_Economics_2024.json', '7ef9b246e1f097f3a43ef265ff9e5d5c3fbeb05432318677df0475b25930c4ab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Comparative advantage theory was developed by _____.', '["Adam Smith","David Ricardo","John Maynard Keynes","Alfred Marshall"]', 1, 'David Ricardo introduced the law of comparative advantage, explaining how countries benefit from specializing in goods they produce at a lower relative cost.', NULL, 'WAEC_Economics_2024.json', '63c47f1381ebbee4760e25260c8fce00e68f0d32e9102b708a72452bbc7a265a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The ''terms of trade'' is the ratio of _____.', '["export volume to import volume","export price index to import price index","national income to population","money supply to inflation"]', 1, 'Terms of trade measure the relative prices of a country''s exports compared to its imports (Index of Export Prices / Index of Import Prices x 100).', NULL, 'WAEC_Economics_2024.json', 'e27e29ae5fa11fc11bc31a21cb4aea55e0021611c9fd9e541378c410d0af0a40');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Which of the following is a barrier to international trade?', '["Free trade zones","Tariffs","Bilateral agreements","Globalization"]', 1, 'Tariffs are taxes on imported goods designed to protect domestic industries by making imports more expensive.', NULL, 'WAEC_Economics_2024.json', '9f96e72b0e5978c4ae336b7b8fb103684f04e906dc35c1d4fc634936848dfe0d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The main objective of the Economic Community of West African States (ECOWAS) is _____.', '["political unification","economic integration","military defense","religious harmony"]', 1, 'ECOWAS was formed to promote cooperation and integration, leading to the establishment of an economic union in West Africa.', NULL, 'WAEC_Economics_2024.json', '024167f2ec5c328ba01e2e478937766e855b492c57862aeb824d75f63984a704');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'In the circular flow of income, the households provide _____ to the firms.', '["goods and services","factors of production","subsidies","taxes"]', 1, 'Households own the factors of production (land, labour, capital) and provide them to firms in exchange for rent, wages, interest, and profit.', NULL, 'WAEC_Economics_2024.json', 'c448173a955ac5cc367eb902f01e27bff3517deb06a0ffa0f3e4e34ae0f55b8a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'A ''monopsony'' is a market situation with _____.', '["one seller","one buyer","few sellers","many buyers"]', 1, 'Monopsony occurs when there is only one buyer in the market, giving that buyer significant power over sellers.', NULL, 'WAEC_Economics_2024.json', '37db99a56af1e0c86d90f5e784c4e25c9757f11c973e7ff29c26cd3b6c62bee6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The demand for labour is described as ''derived demand'' because it _____.', '["is demanded for its own sake","depends on the demand for the product it produces","is determined by the government","is fixed in the short run"]', 1, 'Labour is not demanded because people want workers for fun; it is demanded because there is a demand for the goods those workers produce.', NULL, 'WAEC_Economics_2024.json', '71a2c90fd338b2ac9af0e20ba129d367d82dff3a392005aefa23a6849130b802');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'To control inflation, the Central Bank may _____.', '["reduce interest rates","lower the reserve requirement","sell government securities","increase government spending"]', 2, 'Selling securities (Open Market Operations) mops up excess liquidity from the banking system, reducing the money supply and curbing inflation.', NULL, 'WAEC_Economics_2024.json', '08da43eeff14e467cb2b77f457ba30ecf400910c299fc6fdd58d14304d24ec81');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Which of the following is a component of the ''current account'' in the Balance of Payments?', '["Foreign direct investment","Portfolio investment","Visible trade (exports and imports of goods)","Foreign exchange reserves"]', 2, 'The current account records the trade in goods (visible) and services (invisible), as well as primary and secondary income.', NULL, 'WAEC_Economics_2024.json', '275f15fcb9571f896b9368e6366bbbea7f60144ae86aeae6ad963e95fb2181e2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Elasticity of supply measures the responsiveness of quantity supplied to a change in _____.', '["income","technology","price","tastes"]', 2, 'Price elasticity of supply measures how much the quantity supplied changes in response to a change in the product''s own price.', NULL, 'WAEC_Economics_2024.json', '01b0a7141ea30da44297fdb3ba0af80a767b82aa25669d5d6df2ca0303afc6ea');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The ''infant industry'' argument is used to justify _____.', '["free trade","privatization","protectionism","devaluation"]', 2, 'This argument suggests that new domestic industries need protection from foreign competition until they are mature enough to compete.', NULL, 'WAEC_Economics_2024.json', '97dd894311326074129730b44aa45467ff9370e96641878cb6196bf8ec971d23');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Which of the following is a function of money?', '["Standard for deferred payment","Source of inflation","Barrier to trade","Factor of production"]', 0, 'Money allows for credit transactions where payment is made in the future (deferred).', NULL, 'WAEC_Economics_2024.json', 'eb37b5d40ab050a67ea162304982037e6403bd60f3cc25a918cb7ae68ccea806');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'A normal good is one where demand increases as _____.', '["price increases","income increases","price of substitutes falls","population decreases"]', 1, 'For normal goods, there is a positive relationship between a consumer''s income and the quantity demanded.', NULL, 'WAEC_Economics_2024.json', 'c0f0d7e87f1aefc16a82f295037f4850ad4e487edbc7cc903325ab9a1eb1a79e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The point where the supply and demand curves intersect is called _____.', '["surplus point","shortage point","equilibrium point","inflection point"]', 2, 'Equilibrium occurs where quantity demanded equals quantity supplied; there is no tendency for the price to change.', NULL, 'WAEC_Economics_2024.json', 'c67bcfc5c7c1e2c2bb5f7d04663c5aa3e7ffdff33a6930594da049c11fe63f24');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'When Total Utility is increasing, Marginal Utility must be _____.', '["negative","zero","positive","decreasing at an increasing rate"]', 2, 'As long as you are still getting some extra satisfaction (positive MU), your total satisfaction (TU) will continue to rise.', NULL, 'WAEC_Economics_2024.json', 'e84a34d551739062b4656d641b4ec8d4b29e3887db6a697bade048a94e7ab4ed');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'In the short run, a firm should shut down if price is less than _____.', '["Average Total Cost","Average Variable Cost","Marginal Cost","Fixed Cost"]', 1, 'If the price cannot even cover the variable costs (AVC), the firm loses more by staying open than by closing.', NULL, 'WAEC_Economics_2024.json', '9321d9d69edeb54de5b15940bb17416436665c5d53845cb65d692dda478eed07');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Which of the following is a characteristic of an oligopoly?', '["Many small firms","A single seller","Interdependence between firms","No barriers to entry"]', 2, 'In an oligopoly, few large firms dominate the market, and the actions of one firm (e.g., price change) significantly affect the others.', NULL, 'WAEC_Economics_2024.json', '3828f85bce0a0792e10305f3537f2346d47fa326434fb32fb3c5d4e512f93aff');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The value of money varies _____.', '["directly with the price level","inversely with the price level","directly with the interest rate","inversely with the interest rate"]', 1, 'When prices rise (inflation), the purchasing power of money falls. Thus, value of money = 1/Price level.', NULL, 'WAEC_Economics_2024.json', '43fa4d053e05fe3be2d670b0b7958577385acf318a0c6c12b7f5739ca8090e3a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Devaluation of a currency is intended to _____.', '["make imports cheaper","make exports cheaper and imports dearer","increase the value of the currency","reduce the balance of payments deficit"]', 1, 'Devaluation makes a country''s goods cheaper for foreigners and foreign goods more expensive for locals, aiming to improve the trade balance.', NULL, 'WAEC_Economics_2024.json', 'd58079a36b1ededf16b625c09157dc4ba16738465d68c5dd8de9530339c8cdf0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Public goods are characterized by _____.', '["excludability and rivalry","non-excludability and non-rivalry","high prices","government ownership only"]', 1, 'Non-excludable means you can''t stop people from using it; non-rivalry means one person''s use doesn''t reduce availability for others (e.g., street lights).', NULL, 'WAEC_Economics_2024.json', 'c4c2fda21ffec95f9ac8f2faf33762cc91ab014efcb12eb22bda8c4f67c002a7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The ''Golden Age'' of agriculture in Nigeria was characterized by the dominance of _____.', '["Petroleum","Cash crops (Cocoa, Groundnut, Palm oil)","Solid minerals","Manufacturing"]', 1, 'Before the oil boom of the 1970s, Nigeria''s economy relied heavily on the export of various agricultural cash crops.', NULL, 'WAEC_Economics_2024.json', 'c4cea63588e034297e7a446bcddf065ba72833056a09e1d4016414078d05e864');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'An ''inferior good'' is one for which demand falls when _____.', '["price falls","income rises","income falls","supply increases"]', 1, 'As consumers get wealthier, they stop buying inferior goods (like low-quality starchy foods) and switch to better alternatives.', NULL, 'WAEC_Economics_2024.json', 'f3975d26fa7915003616769cd88a1662776573ddb11fb1dee8f0a67b4b9839c0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Which of the following is a direct tax?', '["Excise duty","Customs duty","Personal Income Tax","Sales tax"]', 2, 'Direct taxes are paid directly by the person or organization on whom they are levied, such as income or profit taxes.', NULL, 'WAEC_Economics_2024.json', 'c9fd4cf6fae4a8aac95d9016dd52ee25b2b4780c461edd66f53ef63d553f9e07');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The reward for Land as a factor of production is _____.', '["Wages","Interest","Profit","Rent"]', 3, 'Economically, rent is the payment made for the use of land and other natural resources.', NULL, 'WAEC_Economics_2024.json', '51307b2e1528e71ab848352111ae6a599daaa65fd5eb62a06470c0924ad56f6e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'A production process where the output increases more than proportionately to the increase in inputs is called _____.', '["constant returns to scale","decreasing returns to scale","increasing returns to scale","diminishing returns"]', 2, 'If you double all inputs and output more than doubles, you are experiencing increasing returns to scale.', NULL, 'WAEC_Economics_2024.json', '7e61e51f6171da11c22033ff63770735c5ce0e6efa5f38b974d7154a19d7324a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The dependency ratio is the ratio of _____.', '["children to adults","men to women","non-working population to the working population","urban dwellers to rural dwellers"]', 2, 'It measures the pressure on the productive part of the population to support the young and the elderly.', NULL, 'WAEC_Economics_2024.json', 'e93a06a13028c7afef375abad5330ce6987e9c02869c1393a62769bbc0f8f51e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Which of the following is a drawback of a barter system?', '["It promotes trade","Double coincidence of wants","It uses money","It is very simple"]', 1, 'In barter, you must find someone who has what you want and wants exactly what you have, which is difficult and inefficient.', NULL, 'WAEC_Economics_2024.json', '552c8e3cfa0d54fb6cfced0660c22a09f7364d381264a0f5e840257bff9a8e36');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The primary aim of a private limited company is to _____.', '["provide social services","maximize profit","create employment only","reduce competition"]', 1, 'Like most private businesses, the fundamental goal is to generate profit for its shareholders.', NULL, 'WAEC_Economics_2024.json', '5db1a47c49c2559c7e4c9e133f932a662ac0e9a0a92688367beb04afb5c8b485');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Economic growth is best measured by an increase in _____.', '["nominal GDP","real GDP","population","money supply"]', 1, 'Real GDP accounts for inflation, providing a more accurate measure of the actual increase in the production of goods and services.', NULL, 'WAEC_Economics_2024.json', '554cbe45c075120eff485588eb4a48c9e4fe6ccb449993378d424c21bb9e5aaa');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Which of the following is a function of the commercial banks?', '["Issuing currency","Acting as the government''s bank","Advancing loans to customers","Formulating monetary policy"]', 2, 'Commercial banks (like First Bank or GTB) focus on accepting deposits and lending money to individuals and businesses.', NULL, 'WAEC_Economics_2024.json', '1ea5d308aa40bb066ddcd604f23d402af4b5d0c5a990225b2c02472d4acf80aa');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'A ''price floor'' is a _____.', '["maximum legal price","minimum legal price","equilibrium price","subsidized price"]', 1, 'A price floor (like minimum wage) is a government-imposed minimum limit below which the price is not allowed to fall.', NULL, 'WAEC_Economics_2024.json', 'a5ac59c2bd3a94f8ab2b603e64d0c6e01f4a10f45cda01edd0c34ff1ac8bae29');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The range of a set of data is the _____.', '["sum of the data","middle value","difference between the highest and lowest values","most frequent value"]', 2, 'In statistics, range measures the spread of data by subtracting the minimum value from the maximum value.', NULL, 'WAEC_Economics_2024.json', '8293fbf4e07aed323dcae7bf120b5b430db7f0916c09c21960ef91fadeff696c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Which of the following describes a ''mixed economy''?', '["Economy with both agriculture and industry","Economy with both private and public sectors","Economy that trades with other countries","Economy using both barter and money"]', 1, 'In a mixed economy, both the government (public sector) and private individuals/firms (private sector) play roles in resource allocation.', NULL, 'WAEC_Economics_2024.json', '7d7afa1f28321e2f3431f9635476fcc1c93a72ce9d231fdcd93fa150c37c79cc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The coefficient of price elasticity of demand for a necessity is usually _____.', '["greater than 1","less than 1","equal to 1","equal to infinity"]', 1, 'Necessities have inelastic demand because consumers will still buy them even if the price rises significantly.', NULL, 'WAEC_Economics_2024.json', '7dd7d1053851f979382788d070d5f70f456e00f2c7068b691390d05c1f719d62');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'An increase in the price of a complement good will cause the demand for the main good to _____.', '["increase","decrease","remain constant","become perfectly elastic"]', 1, 'Complements are used together (e.g., Car and Petrol). If petrol gets very expensive, the demand for cars will likely fall.', NULL, 'WAEC_Economics_2024.json', '0a9e29b2253029367d6f83f88a51605b194d88b379050e731ab21006783b8a7e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Which of the following is a ''near money'' asset?', '["Currency notes","Savings account balance","Commodity money","Credit cards"]', 1, 'Near money refers to assets that are highly liquid and can be easily converted into cash, but are not immediately used as a medium of exchange.', NULL, 'WAEC_Economics_2024.json', 'e39cc4be3c1676b2fdb907fe1aee56b3c6dcca8e3c9a97f810cf1a70668612b7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The ''Laffer Curve'' shows the relationship between _____.', '["inflation and unemployment","tax rates and tax revenue","income and consumption","price and quantity supplied"]', 1, 'It suggests that there is an optimal tax rate that maximizes revenue; too high a rate can actually decrease revenue by discouraging work.', NULL, 'WAEC_Economics_2024.json', '4785c501bdfb25c27acf160af51fc72a7980e45d35a66e03536469a012f55236');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Economic development differs from economic growth because development involves _____.', '["only an increase in GDP","structural and qualitative changes in the economy","an increase in the money supply","a decrease in international trade"]', 1, 'Growth is purely quantitative (more output), while development includes improvements in literacy, healthcare, and living standards.', NULL, 'WAEC_Economics_2024.json', 'e09aac533a0818c9eddcb9f6f532eb910779adbed223f9427afb42a3cc65b3b0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Privatization is the policy of _____.', '["selling government-owned enterprises to private individuals","government taking over private businesses","reducing taxes on private firms","increasing government control over the economy"]', 0, 'It is the transfer of ownership, property, or business from the public sector to the private sector.', NULL, 'WAEC_Economics_2024.json', '050001b237f3069a6b1735b006c15ce361fd22b9d9a02451753836780f38a759');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The World Bank is primarily concerned with _____.', '["short-term balance of payment loans","long-term loans for developmental projects","controlling global inflation","regulating international trade"]', 1, 'While the IMF handles short-term currency crises, the World Bank provides financial and technical assistance for capital projects in developing countries.', NULL, 'WAEC_Economics_2024.json', 'cbbc4bd10f934ad1a5445d6b46e11ef2b9573b79b96779560533e14b5659b28e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'A ''Giffen good'' is an exception to the law of _____.', '["Supply","Demand","Diminishing returns","Comparative advantage"]', 1, 'For Giffen goods, demand increases as the price increases, which violates the standard Law of Demand.', NULL, 'WAEC_Economics_2024.json', '9e84f760acf514ac30a986a186cff7d446b169dee0c96687f73cea6c188af7fd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'What is the median of the following scores: 12, 15, 10, 20, 18?', '["10","15","12","18"]', 1, 'First, arrange in order: 10, 12, 15, 18, 20. The middle value is 15.', NULL, 'WAEC_Economics_2024.json', '4326650c64700887b688d35b940b9b4f7927a6eb5c0c0a35494255833dec9932');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Tax evasion is _____.', '["reducing tax liability through legal means","illegal non-payment or underpayment of taxes","paying taxes ahead of time","a type of indirect tax"]', 1, 'Tax evasion is a criminal act, whereas tax avoidance is the legal use of the tax regime to your advantage.', NULL, 'WAEC_Economics_2024.json', '28afcf28642b26c0d60a6fee0ea4b60d25165a4753f1ac83ff272e4484525baf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The labour force of a country consists of _____.', '["the total population","everyone who wants to work","the population aged 15-64 who are willing and able to work","only those who are currently employed"]', 2, 'The labour force includes both the employed and the unemployed who are actively seeking work within the productive age bracket.', NULL, 'WAEC_Economics_2024.json', 'e1b15c438539533367b4b15b035a6cbd0cb598f4aa4ef752df19a4efad4b9a88');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'Which of the following is a cause of rural-urban migration in Nigeria?', '["Better agricultural land in cities","Search for better social amenities and jobs","Lower cost of living in cities","Higher air pollution in rural areas"]', 1, 'The concentration of infrastructure, healthcare, education, and industries in cities ''pulls'' people from rural areas.', NULL, 'WAEC_Economics_2024.json', '01dff15985b5288f793ecf47788cb6b9f45d4001a1bda58361c13d4771262620');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The ''liquidity ratio'' is the percentage of _____.', '["deposits a bank must keep in cash or liquid assets","profits a bank must pay as tax","loans a bank must give to farmers","interest a bank must pay to savers"]', 0, 'It is a requirement set by the Central Bank to ensure that commercial banks have enough cash to meet their customers'' withdrawal demands.', NULL, 'WAEC_Economics_2024.json', '4ebe32511aa656b01ef4b9a2558754088ae3a7888bf6b8c822ad9cfed48fee7e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'The ''petro-dollar'' refers to _____.', '["currency used only in oil-producing countries","US dollars earned from the export of petroleum","a new currency for OPEC nations","the cost of refining oil in Nigeria"]', 1, 'Because oil is priced and traded globally in US dollars, the revenue earned by oil exporters is called petro-dollars.', NULL, 'WAEC_Economics_2024.json', 'a2f0b443dfec0bcaaa485e72bf0e8fe63b4ca25dab6889df3b41d0cc15d22d35');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2024, NULL, 'In a capitalist economy, resources are allocated by _____.', '["the central planning committee","the price mechanism","religious leaders","the military"]', 1, 'The price mechanism (the interaction of supply and demand) determines what is produced, how, and for whom.', NULL, 'WAEC_Economics_2024.json', 'f700a04926fc78126cf571f8733a4ac05928e53499b6c7f649f3e7eda5b5d3e3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2025, NULL, 'Economics is defined as a science of:', '["Wealth","Scarcity and Choice","Production","Money"]', 1, NULL, NULL, 'WAEC_Economics_2025.json', '2216e19ab8e056fdff0efea6b902c747c930ae5a57ff7afb5eb2ae9840a883c0');
