INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2025, NULL, 'Inelastic demand means elasticity is:', '["Less than 1","Greater than 1","Equal to 1","Zero"]', 0, NULL, NULL, 'WAEC_Economics_2025.json', 'e5a06c1223f51621b71545366eeb0fd827417d57354211eef5d93dd4f38aee92');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Economics', 2025, NULL, 'Scale of preference helps to:', '["Make rational choices","Make money","Produce goods","Save time"]', 0, NULL, NULL, 'WAEC_Economics_2025.json', '90e0f9f50239e1e9db6c7244570ea27bbb9db7b51ea13ae0f785d4ec2a8efbf6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The committee members were advised to _____ their differences and work for the common good.', '["sink","wash","hide","bury"]', 0, 'To ''sink'' differences is an idiomatic expression meaning to forget or disregard disagreements in order to achieve a common goal.', NULL, 'WAEC_English_2024.json', '52f7ac4db203b459c3a2bf1ab074aed8c670f244fb0cb8a6592bb9cfd22abf0d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Neither the teacher nor the students _____ present at the seminar yesterday.', '["is","was","were","are"]', 2, 'According to the rule of proximity, when ''neither/nor'' joins two subjects, the verb agrees with the subject closer to it (''students''), which is plural.', NULL, 'WAEC_English_2024.json', '1d594013fe40fb4abf31f5d32e8e41c79e90aff35dc84486daf451528f4475e8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The principal was so angry that he _____ his words.', '["mumbled","minced","choked","ate"]', 1, 'To ''not mince words'' means to speak directly. Conversely, to ''mince words'' is to use polite or vague language. In this context, it describes the manner of speaking.', NULL, 'WAEC_English_2024.json', 'c58270662650fde3f39939c7dc4fb824401c970363b32fd9c42af2d06623627f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'It is high time we _____ the truth about the matter.', '["tell","told","are telling","have told"]', 1, 'The expression ''It is high time'' is followed by a subject and a verb in the past tense (subjunctive) to indicate that something should have happened already.', NULL, 'WAEC_English_2024.json', 'f61da8ee4fce01592f26fa34ec8b30ed5e661acd7713f8c5d2009b40c9c9af4a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The witness gave a _____ account of the accident, making it easy for the judge to understand.', '["vague","lucid","detailed","clear"]', 1, 'A ''lucid'' account is clear and easy to understand. While ''clear'' is similar, ''lucid'' is more formal and specific to descriptions in English Lexis.', NULL, 'WAEC_English_2024.json', '3d923a78afbb2fdd3e454d3c9c392b50741c0a52f42cd16e43dc2eed3d5babe8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Choose the word most nearly opposite in meaning to the underlined word: The manager is known for being <u>extravagant</u>.', '["generous","frugal","careless","wealthy"]', 1, '''Extravagant'' means spending money excessively; ''frugal'' means being economical or cautious with spending.', NULL, 'WAEC_English_2024.json', 'a13b757e5828082692dddf6b722b2dd4601aa518bb8e2167a39bf698b6974b31');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Ade _____ the examination before the results were announced.', '["has written","had written","writes","wrote"]', 1, 'The past perfect ''had written'' is used to describe an action completed before another action in the past (the announcement of results).', NULL, 'WAEC_English_2024.json', 'bca093327f1042199d156a517671313e9d7a78a660d58ecb3d2f0b8dcaa6947c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The meeting was _____ until next week due to the chairman''s absence.', '["put off","put out","put away","put down"]', 0, 'The phrasal verb ''put off'' means to postpone or delay an event.', NULL, 'WAEC_English_2024.json', '6c9577d4f791f446e8bb365a7ebd7a57ccd56843e84588ee8be1094d63fab736');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The manager told the staff that they must abide _____ the new rules.', '["with","to","by","at"]', 2, 'The verb ''abide'' is idiomatically followed by the preposition ''by'' to mean obeying a rule.', NULL, 'WAEC_English_2024.json', 'd1b9eada331ff2aa9ccad8d5827e42f7f1cbbe55bd2d42099b9a88f1ee85e6c5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'He was found guilty _____ manslaughter.', '["with","of","for","at"]', 1, 'In legal English, the adjective ''guilty'' is followed by the preposition ''of''.', NULL, 'WAEC_English_2024.json', 'b68d43b2446063a57da42f6dd8b3786b37d638e0e8c1691070dfd43c9afd8724');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The car is _____ expensive for me to buy.', '["so","very","too","much"]', 2, '''Too'' is used before an adjective to indicate an excessive amount that prevents an action (the ''too...to'' structure).', NULL, 'WAEC_English_2024.json', '1a596235c1663aac4f884f025f1de4289a8846addaf823f4e0d818c16485ee5d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'She is the _____ of the two girls.', '["tallest","taller","most tall","more tall"]', 1, 'When comparing exactly two people or things, the comparative degree (''taller'') is used.', NULL, 'WAEC_English_2024.json', 'ca8aeb49ae79c23efe541e5c205c55e2f71930d90789be698a9ff61304dc2ae5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Identify the word that has a different stress pattern from the others:', '["Understand","Introduce","Calculate","Recommend"]', 2, '''Calculate'' is stressed on the first syllable (CAL-cu-late), while the others are stressed on the third syllable.', NULL, 'WAEC_English_2024.json', '432ba4c28b58083661440cd68e7fb1fea9c6ab9df4f585c6e1a01f927330c4d2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The scent of the perfume is very .', '["strong","loud","heavy","deep"]', 0, 'Smells or scents are typically described as ''strong'' or ''faint'' in standard English collocations.', NULL, 'WAEC_English_2024.json', '02772d03164e9a8c0ef67f149631256026b817c95dcfb1511619f80b103481bd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'He didn''t pass the test, ?', '["did he","didn''t he","has he","is it"]', 0, 'A negative statement requires a positive question tag using the same auxiliary verb.', NULL, 'WAEC_English_2024.json', '9ea225f32fb74e3348ea4e40f2e34de871bf9ea40a30e2772fb25cc143f6ea73');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The building was _____ by the fire.', '["razed","raised","roused","raced"]', 0, '''Razed'' means to completely destroy a building or town to the ground.', NULL, 'WAEC_English_2024.json', 'b05aa9918257fc45f6c2cc7748f36dc6c09b47e6f5c0f87789f1c95a2ce09308');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Identify the correctly spelled word:', '["Maintenance","Maintainance","Maintennance","Maintainence"]', 0, '''Maintenance'' is the correct spelling; the ''ai'' in ''maintain'' changes to ''e'' in the noun form.', NULL, 'WAEC_English_2024.json', 'c9c63723f9002e61030b3bceb1ee9221dffd51dd2ab7907037e2fe01a2193bd3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The phrase ''to kick the bucket'' means:', '["To start a fight","To die","To play football","To be angry"]', 1, 'This is a common English idiom used as a euphemism for death.', NULL, 'WAEC_English_2024.json', '409bac83ed1f3a33bfa4e912127eacc0d5ab19466512c2f75f4f9ccc77b79084');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'He is very good _____ Mathematics.', '["in","at","with","for"]', 1, 'The adjective ''good'' is followed by ''at'' when referring to skills or subjects.', NULL, 'WAEC_English_2024.json', '4d9fc8e818ce0a6f705039426b0290c363def684491cfc4cea353c4e168abc0e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The information provided was .', '["many","plenty","a lot","invaluable"]', 3, '''Information'' is uncountable, so ''many'' is wrong. ''Invaluable'' means extremely useful.', NULL, 'WAEC_English_2024.json', '58b6215181d8bbc63f5ecfea0b2e6405f7b3ea537d7c2c46ff4eee2ad1b6e1f3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'According to the passage, the democratization of information was caused by .', '["Physical libraries","Internet and mobile devices","Government intervention","Rural infrastructure"]', 1, 'The passage states that the advent of high-speed internet and mobile devices democratized access.', 'The digital revolution has transformed the Nigerian educational landscape. In the past, students relied solely on physical libraries and printed textbooks. However, the advent of high-speed internet and affordable mobile devices has democratized access to information. While urban centers enjoy seamless connectivity, rural areas still grapple with infrastructure deficits. This digital divide threatens to leave behind talented youths in remote villages. Experts argue that government intervention is crucial to ensure that fiber optic cables reach the ''last mile'' of the country.', 'WAEC_English_2024.json', '9ea0e976ee5ec61c9c3a9b59ecee15ca7d5b991cf80b8ee773f4919e8289b2c7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The phrase ''digital divide'' refers to the gap between .', '["Computers and books","Urban and rural technology access","Talented and untalented youths","Government and experts"]', 1, 'The context describes the difference between urban connectivity and rural infrastructure deficits.', 'The digital revolution has transformed the Nigerian educational landscape. In the past, students relied solely on physical libraries and printed textbooks. However, the advent of high-speed internet and affordable mobile devices has democratized access to information. While urban centers enjoy seamless connectivity, rural areas still grapple with infrastructure deficits. This digital divide threatens to leave behind talented youths in remote villages. Experts argue that government intervention is crucial to ensure that fiber optic cables reach the ''last mile'' of the country.', 'WAEC_English_2024.json', '1132f63f6f38648d3c249c45e69aa12c8320645ea528a9abd095b698ab469e04');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Talented youths in remote areas are at risk because of .', '["Lack of interest","Democratic access","Infrastructure deficits","Fiber optic cables"]', 2, 'The passage notes that deficits in infrastructure threathen to leave them behind.', 'The digital revolution has transformed the Nigerian educational landscape. In the past, students relied solely on physical libraries and printed textbooks. However, the advent of high-speed internet and affordable mobile devices has democratized access to information. While urban centers enjoy seamless connectivity, rural areas still grapple with infrastructure deficits. This digital divide threatens to leave behind talented youths in remote villages. Experts argue that government intervention is crucial to ensure that fiber optic cables reach the ''last mile'' of the country.', 'WAEC_English_2024.json', '9d68016166896a436c1fd2cdbed2e227304a3a54ef4c729886fc9801c2b7499f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Which word can best replace ''democratized'' as used in the passage?', '["Restricted","Equalized","Political","Simplified"]', 1, 'In this context, to democratize means to make something available to everyone equally.', 'The digital revolution has transformed the Nigerian educational landscape. In the past, students relied solely on physical libraries and printed textbooks. However, the advent of high-speed internet and affordable mobile devices has democratized access to information. While urban centers enjoy seamless connectivity, rural areas still grapple with infrastructure deficits. This digital divide threatens to leave behind talented youths in remote villages. Experts argue that government intervention is crucial to ensure that fiber optic cables reach the ''last mile'' of the country.', 'WAEC_English_2024.json', 'ed7424d6017608fd4db5c2fd1b55e27ac3213664b9160e58cb0e2d7db468196b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'What is the recommended solution mentioned by experts?', '["Building more physical libraries","Encouraging students to move to cities","Government intervention in fiber optics","Reducing the cost of textbooks"]', 2, 'The last sentence mentions that experts believe government intervention is crucial for fiber optic expansion.', 'The digital revolution has transformed the Nigerian educational landscape. In the past, students relied solely on physical libraries and printed textbooks. However, the advent of high-speed internet and affordable mobile devices has democratized access to information. While urban centers enjoy seamless connectivity, rural areas still grapple with infrastructure deficits. This digital divide threatens to leave behind talented youths in remote villages. Experts argue that government intervention is crucial to ensure that fiber optic cables reach the ''last mile'' of the country.', 'WAEC_English_2024.json', 'ef3399b0af4776c7d35b19460ab773d39efbbda098f3f84644fa2a1c83beeb31');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The soldiers were ordered to _____ from the area to avoid civilian casualties.', '["evacuate","vacate","exit","leave"]', 0, 'In a military or emergency context, ''evacuate'' is the most precise term for moving people out of a dangerous zone.', NULL, 'WAEC_English_2024.json', 'cdec2b674921c425e66cd9048e71c58423f6744e8096f93f6c7d992459320097');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The book belongs to the girl; it is .', '["hers","her''s","hers''","she''s"]', 0, '''Hers'' is a possessive pronoun and never takes an apostrophe.', NULL, 'WAEC_English_2024.json', '1d32a1ae7178f838c8279629c5816f69e15fae693f04582f999965db5b22f656');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'I _____ a lot of progress in my studies lately.', '["am making","have been making","was making","make"]', 1, 'The present perfect continuous ''have been making'' is used for an action that started in the past and continues into the present, especially with ''lately''.', NULL, 'WAEC_English_2024.json', '5cccb10225fa67d52602286a5c23fcb154b3e339dda3a4abd804f0373d43719e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Choose the word most nearly opposite in meaning to the underlined word: Despite the evidence, the suspect remained <u>obdurate</u>.', '["repentant","stubborn","submissive","docile"]', 0, '''Obdurate'' means stubbornly refusing to change one''s opinion. ''Repentant'' (feeling regret) is the most suitable opposite in a criminal context.', NULL, 'WAEC_English_2024.json', '22392982f60074c3a4055b4dff1d09b80670e0fb36be02f2ad0d22ef2fded10a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The manager _____ the strike action by addressing the workers'' concerns immediately.', '["averted","avoided","stopped","prevented"]', 0, 'To ''avert'' is to turn away or prevent an undesirable occurrence from happening through action.', NULL, 'WAEC_English_2024.json', '133128115ea54b415239ce30725ae1ffbdbbcab0d740935284afd94b997121cc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Identify the word with the same consonant sound as the one represented by the underlined letter: <u>Th</u>ere', '["Think","Thin","Father","Theatre"]', 2, 'The ''th'' in ''There'' and ''Father'' is the voiced dental fricative /ð/. In the other options, it is the voiceless /θ/.', NULL, 'WAEC_English_2024.json', '98a6b01c0a8c602de329793a4b0c504bad780fb1cde29d6d2ee8e9f641b3b946');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Choose the word with the same vowel sound as the one represented by the underlined letter: B<u>oa</u>rd', '["Road","Port","Load","Boat"]', 1, 'The ''oa'' in ''Board'' and the ''o'' in ''Port'' both represent the /ɔː/ sound.', NULL, 'WAEC_English_2024.json', '236c51c980c31cd567c60660c14daba7f594ca7ebb95bfacfec51e930ec5d22c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Select the word that rhymes with: ''Great''', '["Meet","Light","Wait","Height"]', 2, '''Great'' /ɡreɪt/ rhymes with ''Wait'' /weɪt/. ''Height'' rhymes with ''Light''.', NULL, 'WAEC_English_2024.json', 'c6c2ce8b30a523f91f3e4024043cb37e9f83102f5e0ab2e75faa09fc7b2ef6ef');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The boy as well as his parents _____ coming to the party.', '["is","are","were","have"]', 0, 'When ''as well as'' is used, the verb agrees with the first subject (''the boy''), which is singular.', NULL, 'WAEC_English_2024.json', 'fb8ba583c185b2cbc0bb4ed06457acddb8eb058b5cb0005e615cc938f2fa9632');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Question 26', '["doctor","pharmacist","nurse","porter"]', 0, 'A doctor is the primary professional who sees a patient first for diagnosis.', 'Medicine is the science of healing. When a patient visiting a hospital is first seen by a 26, they undergo a series of 27. The 28 of the ailment is often done after 29 tests have been conducted in the 30. If the condition is severe, the patient might be admitted to a 31 for close monitoring. In cases of surgery, the 32 leads the team in the 33_____. After the procedure, the patient is moved to a 34_____ to 35_____ before being discharged.', 'WAEC_English_2024.json', '90c5ce70b7c8d4afa8f89390c82e1e48510bf919feb6b75a3bde04429a28c794');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Question 27', '["discussions","examinations","interviews","trials"]', 1, 'Medical examinations are standard procedures for assessing health.', 'Medicine is the science of healing. When a patient visiting a hospital is first seen by a 26, they undergo a series of 27. The 28 of the ailment is often done after 29 tests have been conducted in the 30. If the condition is severe, the patient might be admitted to a 31 for close monitoring. In cases of surgery, the 32 leads the team in the 33_____. After the procedure, the patient is moved to a 34_____ to 35_____ before being discharged.', 'WAEC_English_2024.json', '22708a6492d1fe7d7ca26444667f71ffab060e988af14cc9e2faeebfa3f7a3c1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Question 28', '["forecast","prognosis","diagnosis","analysis"]', 2, 'Diagnosis is the specific term for identifying a disease.', 'Medicine is the science of healing. When a patient visiting a hospital is first seen by a 26, they undergo a series of 27. The 28 of the ailment is often done after 29 tests have been conducted in the 30. If the condition is severe, the patient might be admitted to a 31 for close monitoring. In cases of surgery, the 32 leads the team in the 33_____. After the procedure, the patient is moved to a 34_____ to 35_____ before being discharged.', 'WAEC_English_2024.json', 'debba882e60fd9b44d1fd3c0b05dbdcdd4f1763b3a6a3c065ab23f77aa42f598');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Question 29', '["clinical","physical","mental","manual"]', 0, 'Clinical tests are those performed based on medical observation.', 'Medicine is the science of healing. When a patient visiting a hospital is first seen by a 26, they undergo a series of 27. The 28 of the ailment is often done after 29 tests have been conducted in the 30. If the condition is severe, the patient might be admitted to a 31 for close monitoring. In cases of surgery, the 32 leads the team in the 33_____. After the procedure, the patient is moved to a 34_____ to 35_____ before being discharged.', 'WAEC_English_2024.json', 'e0e5dcd1e5ef69882b51e4d965729ae0deecbb6e35e319e62f4c14e2f16042cf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Question 30', '["theatre","ward","laboratory","morgue"]', 2, 'Tests are conducted in a laboratory.', 'Medicine is the science of healing. When a patient visiting a hospital is first seen by a 26, they undergo a series of 27. The 28 of the ailment is often done after 29 tests have been conducted in the 30. If the condition is severe, the patient might be admitted to a 31 for close monitoring. In cases of surgery, the 32 leads the team in the 33_____. After the procedure, the patient is moved to a 34_____ to 35_____ before being discharged.', 'WAEC_English_2024.json', 'ee74112ac2f75130e88cc0e686d3df1552f41bd284916b5da08efeca98b94f19');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Question 31', '["clinic","ward","pharmacy","office"]', 1, 'Patients are admitted into a ward.', 'Medicine is the science of healing. When a patient visiting a hospital is first seen by a 26, they undergo a series of 27. The 28 of the ailment is often done after 29 tests have been conducted in the 30. If the condition is severe, the patient might be admitted to a 31 for close monitoring. In cases of surgery, the 32 leads the team in the 33_____. After the procedure, the patient is moved to a 34_____ to 35_____ before being discharged.', 'WAEC_English_2024.json', 'b63bebcdd608115c2b45049ed5fad86f724487ca21c821353b6156b12d159806');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Question 32', '["physician","surgeon","matron","optician"]', 1, 'A surgeon is a doctor qualified to perform operations.', 'Medicine is the science of healing. When a patient visiting a hospital is first seen by a 26, they undergo a series of 27. The 28 of the ailment is often done after 29 tests have been conducted in the 30. If the condition is severe, the patient might be admitted to a 31 for close monitoring. In cases of surgery, the 32 leads the team in the 33_____. After the procedure, the patient is moved to a 34_____ to 35_____ before being discharged.', 'WAEC_English_2024.json', 'dbf69296972fc4f1b01c9dca5833042a2db688352fa693070c5db83fb2c0873a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Question 33', '["operating theatre","intensive care","emergency room","consulting room"]', 0, 'Surgeries take place in an operating theatre.', 'Medicine is the science of healing. When a patient visiting a hospital is first seen by a 26, they undergo a series of 27. The 28 of the ailment is often done after 29 tests have been conducted in the 30. If the condition is severe, the patient might be admitted to a 31 for close monitoring. In cases of surgery, the 32 leads the team in the 33_____. After the procedure, the patient is moved to a 34_____ to 35_____ before being discharged.', 'WAEC_English_2024.json', '136c6ecf563c97b65939573010157836fa74b41683c33a85463512ef88732011');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Question 34', '["playground","reception","recovery room","waiting room"]', 2, 'Post-surgery, patients go to a recovery room.', 'Medicine is the science of healing. When a patient visiting a hospital is first seen by a 26, they undergo a series of 27. The 28 of the ailment is often done after 29 tests have been conducted in the 30. If the condition is severe, the patient might be admitted to a 31 for close monitoring. In cases of surgery, the 32 leads the team in the 33_____. After the procedure, the patient is moved to a 34_____ to 35_____ before being discharged.', 'WAEC_English_2024.json', '3eb6781e514d467f2fc9466c97af9fe07d3d16b0717ac6af78617085f3f1588e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Question 35', '["recuperate","relax","rejoice","relapse"]', 0, 'To recuperate means to recover health and strength.', 'Medicine is the science of healing. When a patient visiting a hospital is first seen by a 26, they undergo a series of 27. The 28 of the ailment is often done after 29 tests have been conducted in the 30. If the condition is severe, the patient might be admitted to a 31 for close monitoring. In cases of surgery, the 32 leads the team in the 33_____. After the procedure, the patient is moved to a 34_____ to 35_____ before being discharged.', 'WAEC_English_2024.json', 'ea9ef971a4239bd1e8960dfdeb3f0d83e887787fd1fb68c34c13fdb721133709');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The rain _____ for three hours before it finally stopped.', '["falls","fell","had been falling","has fallen"]', 2, 'The past perfect continuous ''had been falling'' is used to show the duration of an action before another past point.', NULL, 'WAEC_English_2024.json', '94eb0950e04e104b5d1f2efa3df1e920e53a64bd605fa4fee801cf307b324d87');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The more you study, _____ you become.', '["the more wise","the wiser","most wise","wiser"]', 1, 'This follows the double comparative structure: ''the + comparative, the + comparative''.', NULL, 'WAEC_English_2024.json', '415bc3db9bdb0d9f15750b1d48d370ad2a37c3212b0fc638123d274a105e2b67');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The news of the accident _____ spread quickly.', '["has","have","were","are"]', 0, '''News'' is a singular uncountable noun and takes a singular verb.', NULL, 'WAEC_English_2024.json', '9e0cecac89b3ea10e053f18c66670d7d3b7dc4ebc4883596a3b0493661ac837d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'He acted _____ the instructions of his lawyer.', '["with","to","on","at"]', 2, 'To ''act on'' instructions means to follow them.', NULL, 'WAEC_English_2024.json', 'b082ffe100535c11d3500d6ffe8d28d6f5b2f7a227df4860413e127c39cfae93');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The students were <u>at loggerheads</u> over the choice of a class captain.', '["in agreement","in disagreement","confused","happy"]', 1, 'To be ''at loggerheads'' means to be in strong disagreement or at a deadlock.', NULL, 'WAEC_English_2024.json', '1df266d09abcb517bd3a1277ce8b2133f75443b60c59eb8816711cd79f5380c8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'I _____ you if you had asked me.', '["will help","would help","would have helped","helped"]', 2, 'This is a third conditional sentence (unreal past), requiring ''would have + past participle''.', NULL, 'WAEC_English_2024.json', '43cd39f8d8693c385b255541e61e6cfaebc84e8a127e225ae9860feb650ab013');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The principal''s speech was <u>brevity</u> itself.', '["shortness","long","clear","inspiring"]', 0, '''Brevity'' is the noun form of ''brief'', meaning concise or short.', NULL, 'WAEC_English_2024.json', 'ac60bbaa7091c30a46330e7241765cad263b5041b62230619c287f6a0c1c07ff');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Which of the following contains the sound /v/?', '["Off","Of","Ferry","Phase"]', 1, 'In the word ''Of'', the letter ''f'' is pronounced as /v/.', NULL, 'WAEC_English_2024.json', '5b829138af41a2d9f777c922d79c9df353f5b0f263547a181ed30417398eb57c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Choose the word that has the same vowel sound as: ''Cat''', '["Father","Plait","Want","Palm"]', 1, '''Cat'' and ''Plait'' both contain the short front vowel sound /æ/.', NULL, 'WAEC_English_2024.json', 'f7c6dad194f81583199ccd821f09bff6093e3a27c80c38076919eb9bc5d35bed');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Identify the silent letter in ''Psychology'':', '["P","s","h","y"]', 0, 'The ''P'' is silent at the beginning of ''Psychology''.', NULL, 'WAEC_English_2024.json', 'b6b1cf9b7ac0f41be84a44b2fb61efd2a9373af196c7ab5fb66d69bfab1c0900');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Choose the word with the primary stress on the second syllable:', '["Education","Importance","Market","Calculator"]', 1, 'im-POR-tance (2nd), ed-u-CA-tion (3rd), MAR-ket (1st), CAL-cu-la-tor (1st).', NULL, 'WAEC_English_2024.json', 'e1f23b4c909eaef36857e196a9249969e92cd145ffd7d37694989b21ea127d9b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Identify the word that has a different stress pattern:', '["Refuse (verb)","Present (noun)","Object (noun)","Export (noun)"]', 0, 'Most two-syllable nouns are stressed on the 1st syllable, while verbs are stressed on the 2nd. ''Refuse'' (verb) is re-FUSE, while ''Present'' (noun) is PRE-sent.', NULL, 'WAEC_English_2024.json', '493d82895074d44fad8fbf73173d943cb6c632ff9fc1a2c2f9c33313a412a843');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The phrase ''beat around the bush'' means:', '["To cut grass","To avoid the main topic","To hunt animals","To be straightforward"]', 1, 'This idiom means to avoid talking about what is important.', NULL, 'WAEC_English_2024.json', '7cfcc936b78578573e0aafb684f3d8c07b7ac0380c6599b959499f784c4302d9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The man <u>bore the brunt</u> of the disaster alone.', '["escaped","suffered the worst part","caused","ignored"]', 1, 'To ''bear the brunt'' of something means to suffer the main force or worst part of it.', NULL, 'WAEC_English_2024.json', 'd750b1b3903765534ab01462449b59d1a7af7b1c731c08f8ec730c4cb268cd38');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Select the option that is most nearly opposite in meaning to ''<u>vague</u>'':', '["clear","shadowy","unclear","doubtful"]', 0, '''Vague'' means not clear or distinct; ''clear'' is its direct antonym.', NULL, 'WAEC_English_2024.json', 'c99790e880c29db319d035b2542e164af468d2b7c0cc9f870b2c9e0d0b2c7428');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The smell of the rotten eggs was _____.', '["scented","repulsive","fragrant","aromatic"]', 1, '''Repulsive'' means causing intense distaste or disgust, appropriate for rotten eggs.', NULL, 'WAEC_English_2024.json', '0b3852aed12aeab0771b9a1eace3f56853f697da5822fa161db6ada5c441b55b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'She prefers dancing _____ singing.', '["than","more than","to","for"]', 2, 'The verb ''prefer'' is idiomatically followed by ''to''.', NULL, 'WAEC_English_2024.json', '2ea50a0a20d1ac9068c5fd7f45aac0700ff74eed685451030628d27829fac04f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The audience was _____ by the magician''s tricks.', '["enthralled","threatened","enveloped","rejected"]', 0, '''Enthralled'' means captured by fascination or attention.', NULL, 'WAEC_English_2024.json', 'b8b296af94093c0f0c7f86e4c059f6c9af851144e461239555ea1162ef672a8e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'If I _____ a bird, I would fly to you.', '["am","was","were","be"]', 2, 'In conditional sentences expressing an imaginary situation, ''were'' is used for all subjects (subjunctive mood).', NULL, 'WAEC_English_2024.json', '5db50413f66b79805c01dec8b44caff92bab629d1746b84edcef0b9d7a683544');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'They haven''t finished the work, _____?', '["did they","have they","haven''t they","aren''t they"]', 1, 'A negative statement takes a positive question tag.', NULL, 'WAEC_English_2024.json', '035092842b5923f17e606683a8bca6e0250d8fcf551f7f61bd693e6bcc148203');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The driver was _____ for breaking the traffic rules.', '["penalized","charged","rewarded","cautioned"]', 0, 'To be ''penalized'' is to be punished for breaking a rule.', NULL, 'WAEC_English_2024.json', '3ff88f269f9262fbac2c82c8aaa94b7f508338dad6416e075f3c7f8fabfdb3e8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The manager''s decision was <u>unilateral</u>.', '["made by one side only","fair to all","delayed","voted on"]', 0, 'Unilateral means performed by or affecting only one person, group, or country involved in a situation.', NULL, 'WAEC_English_2024.json', '47118a72a0284fd10b51b83df98c010c2bca54d35c4ca21a1c24f9f3354e39e9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The players were in <u>high spirits</u> after the match.', '["drunk","cheerful","angry","tired"]', 1, '''High spirits'' is an idiom meaning to be very happy and lively.', NULL, 'WAEC_English_2024.json', '6805043ea41845d6f5e03e869b4a6fd74c966c75b682f92cc509254ef498909b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Which of the following has the same vowel sound as ''<u>u</u>nit''?', '["Under","Us","Use","Until"]', 2, '''Unit'' and ''Use'' both begin with the /ju:/ sound.', NULL, 'WAEC_English_2024.json', 'f689d71139334373c3f17f226b00dd4b1abfc917366a1306ac426828514ad089');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Identify the word that contains the sound /dʒ/:', '["Judge","Guess","Gear","Great"]', 0, '''Judge'' contains the /dʒ/ affricate sound twice.', NULL, 'WAEC_English_2024.json', '47e569f545ce083db5365d8819fd7e810783aeb4e2c71113a6ad54565c81bea1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Choose the word that has a different stress pattern:', '["Teacher","Doctor","Pencil","Report"]', 3, 'Re-PORT is stressed on the 2nd syllable, while the others are on the 1st.', NULL, 'WAEC_English_2024.json', '5fc291e8a8c278258525c2de7c6b963951087ff7a31a82c49a35b2d4c92e105d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The sound represented by ''ch'' in ''Machine'' is _____.', '["/tʃ/","/ʃ/","/k/","/h/"]', 1, 'In ''Machine'', the ''ch'' is pronounced as the /ʃ/ (sh) sound.', NULL, 'WAEC_English_2024.json', 'eefbe406569b9a36cd83931c86a88c239c69a44e09b4bb853ef4997d8351ef5c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'He <u>passed away</u> peacefully in his sleep.', '["left","walked","died","dreamed"]', 2, '''Passed away'' is a common euphemism for death.', NULL, 'WAEC_English_2024.json', 'c33fc4656a64c61ad2c8b88c103c7985332de19b124d64cbf22ea7d26a7ab142');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The results will be released _____ time.', '["in","on","at","by"]', 0, 'Collocation: ''In time'' (eventually/within the time limit) or ''on time'' (at the scheduled moment). Usually, results are expected ''in due time''.', NULL, 'WAEC_English_2024.json', 'a177dff3b9fc98232ca4787ee0750bbfc348f450bd4a56f501c0830b2ed621ee');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'One should be careful of _____ reputation.', '["his","their","one''s","her"]', 2, 'The pronoun ''one'' must be followed by its possessive form ''one''s''.', NULL, 'WAEC_English_2024.json', '24fc06740ce6f48e1469b51d8a288ca4b943ded9c01faf62337f7f3f2b44d18a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The workers are _____ strike for better pay.', '["at","in","on","with"]', 2, 'The correct preposition for strike is ''on''.', NULL, 'WAEC_English_2024.json', 'a6df4935ca7c88ad90639616953de055fba97d82e1db6af87635860c1ea588a8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The <u>scarcity</u> of fuel caused many commuters to trek.', '["abundance","shortage","price","smelling"]', 1, 'Scarcity refers to a state of being in short supply.', NULL, 'WAEC_English_2024.json', 'de62cbf37f7f5c46fe7262aaa8e5d06aa03f4c7d894e218f298cf88934db1ede');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Emphatic Stress: He DID the work. (The stress implies:)', '["He planned the work","He didn''t just talk about it","Someone else did it","He did something else"]', 1, 'Stress on the auxiliary ''did'' emphasizes the completion or reality of the action against a doubt.', NULL, 'WAEC_English_2024.json', '779644281257e463cb3974ba0599c0f2a06fdef50f710e8723b11e89f0342c82');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Which word has the same consonant sound as the one in ''<u>Ph</u>one''?', '["Phase","Pone","Pan","Page"]', 0, 'Both ''Phone'' and ''Phase'' represent the /f/ sound.', NULL, 'WAEC_English_2024.json', '65d55ef130025b90bab789d9d7b147b32ce19644289f6ff887bc25ca9e90fe42');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'Choose the word that rhymes with ''Bread'':', '["Bead","Said","Blade","Seed"]', 1, '''Bread'' /bred/ and ''Said'' /sed/ share the same vowel sound and final consonant.', NULL, 'WAEC_English_2024.json', '5ebaad0e7b53aa06e49dd95bf974258e457cd4a118c8f62f5ca0b746fdd1511f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The boy _____ I gave the book to has left.', '["who","whom","which","whose"]', 1, '''Whom'' is the objective relative pronoun, used here as the object of the preposition ''to''.', NULL, 'WAEC_English_2024.json', '035ca8138cd83616e1178298362ead20d5c528884a6b34a465f458cc4f022d6c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'He is the _____ man I have ever met.', '["most kind","kindest","most kindest","kinder"]', 1, 'For one-syllable adjectives, the superlative is formed with ''-est''.', NULL, 'WAEC_English_2024.json', '1b7ac12267857fc72823afd5daf74b0f599fa257038db06d242b04f825192f8f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2024, NULL, 'The acronym NIMC stands for National _____ Management Commission.', '["Identity","Information","Internal","Intelligence"]', 0, 'NIMC is the National Identity Management Commission in Nigeria.', NULL, 'WAEC_English_2024.json', 'd2ff95a18353bdbb9aeed45da5e3d35baac56381b09dc9bc891fdba38e904939');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2025, NULL, 'The expression ''joined his ancestors'' is a euphemism for:', '["Went to a meeting","Died","Travelled abroad","Became sick"]', 1, NULL, '<b>The Burden of Leadership</b><br><br>Chief Adeolu had always coveted the throne. For years, he had plotted and schemed, forming alliances with the most unsavory characters in the village. When the old king finally joined his ancestors, Adeolu’s path seemed clear. However, the crown was heavier than he anticipated. The village was plagued by drought, the youths were restless, and the treasury was empty. The very people who had cheered his ascension now grumbled in market squares. Adeolu realized too late that power was not just about wearing royal robes and eating from silver platters; it was a burden that demanded wisdom, sacrifice, and the ability to listen—virtues he had never cultivated. His nights became sleepless, haunted by the realization that he was a king in title but a pauper in leadership.', 'WAEC_English_2025.json', 'a8320d10469670a8022148b561ef717e8fca0d0f7b1963507e832fdb816f1235');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2025, NULL, 'Adeolu’s initial attitude towards the throne was one of:', '["Indifference","Fear","Ambition","Reluctance"]', 2, NULL, '<b>The Burden of Leadership</b><br><br>Chief Adeolu had always coveted the throne. For years, he had plotted and schemed, forming alliances with the most unsavory characters in the village. When the old king finally joined his ancestors, Adeolu’s path seemed clear. However, the crown was heavier than he anticipated. The village was plagued by drought, the youths were restless, and the treasury was empty. The very people who had cheered his ascension now grumbled in market squares. Adeolu realized too late that power was not just about wearing royal robes and eating from silver platters; it was a burden that demanded wisdom, sacrifice, and the ability to listen—virtues he had never cultivated. His nights became sleepless, haunted by the realization that he was a king in title but a pauper in leadership.', 'WAEC_English_2025.json', '5c430f228a7bdcfe837dac8ddaf56f87df2af7e19cf7d4931c874cfc710946b6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2025, NULL, 'The villagers'' reaction to Adeolu’s reign changed from:', '["Anger to joy","Approval to dissatisfaction","Indifference to love","Hate to fear"]', 1, NULL, '<b>The Burden of Leadership</b><br><br>Chief Adeolu had always coveted the throne. For years, he had plotted and schemed, forming alliances with the most unsavory characters in the village. When the old king finally joined his ancestors, Adeolu’s path seemed clear. However, the crown was heavier than he anticipated. The village was plagued by drought, the youths were restless, and the treasury was empty. The very people who had cheered his ascension now grumbled in market squares. Adeolu realized too late that power was not just about wearing royal robes and eating from silver platters; it was a burden that demanded wisdom, sacrifice, and the ability to listen—virtues he had never cultivated. His nights became sleepless, haunted by the realization that he was a king in title but a pauper in leadership.', 'WAEC_English_2025.json', '32045b643575b75c0c82352609a8b78a504e94821e37f8960a564d963048df4c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2025, NULL, 'The phrase ''king in title but a pauper in leadership'' implies Adeolu:', '["Was poor financially","Lacked leadership qualities","Lost his title","Was a servant"]', 1, NULL, '<b>The Burden of Leadership</b><br><br>Chief Adeolu had always coveted the throne. For years, he had plotted and schemed, forming alliances with the most unsavory characters in the village. When the old king finally joined his ancestors, Adeolu’s path seemed clear. However, the crown was heavier than he anticipated. The village was plagued by drought, the youths were restless, and the treasury was empty. The very people who had cheered his ascension now grumbled in market squares. Adeolu realized too late that power was not just about wearing royal robes and eating from silver platters; it was a burden that demanded wisdom, sacrifice, and the ability to listen—virtues he had never cultivated. His nights became sleepless, haunted by the realization that he was a king in title but a pauper in leadership.', 'WAEC_English_2025.json', '126146ec95274a0cb79f23ee7318db4d28142dd7ab3ca53d52f59acd258297a3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2025, NULL, 'A suitable title for this passage is:', '["The Evil Plot","<b>The Reality of Power</b>","The Drought","The Market Square"]', 1, NULL, '<b>The Burden of Leadership</b><br><br>Chief Adeolu had always coveted the throne. For years, he had plotted and schemed, forming alliances with the most unsavory characters in the village. When the old king finally joined his ancestors, Adeolu’s path seemed clear. However, the crown was heavier than he anticipated. The village was plagued by drought, the youths were restless, and the treasury was empty. The very people who had cheered his ascension now grumbled in market squares. Adeolu realized too late that power was not just about wearing royal robes and eating from silver platters; it was a burden that demanded wisdom, sacrifice, and the ability to listen—virtues he had never cultivated. His nights became sleepless, haunted by the realization that he was a king in title but a pauper in leadership.', 'WAEC_English_2025.json', '936615959268e39107fe8e1d98c994a3e549c9ff2c5600d37d79b098d58435ef');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2025, NULL, 'According to the passage, AI is now:', '["A future possibility","Present everywhere","Only in hospitals","Illegal"]', 1, NULL, '<b>The Impact of Artificial Intelligence</b><br><br>Artificial Intelligence (AI) is no longer the stuff of science fiction; it is weaving itself into the fabric of daily life. From recommendation algorithms on streaming services to sophisticated diagnostic tools in healthcare, AI is ubiquitous. Proponents argue that it increases efficiency and solves complex problems faster than the human brain. However, critics raise ethical concerns regarding privacy, bias in algorithms, and the potential displacement of jobs. As machines become smarter, the line between human intuition and machine logic blurs. The challenge for the 21st century is not just developing AI, but governing it to ensure it serves humanity rather than enslaving it.', 'WAEC_English_2025.json', 'fb1c63609dc6fc45945f492063c5499406025c0c35996c1915891a58fa88543c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'English', 2025, NULL, 'One major concern raised by critics is:', '["Speed of computers","Job displacement","Cost of electricity","Lack of internet"]', 1, NULL, '<b>The Impact of Artificial Intelligence</b><br><br>Artificial Intelligence (AI) is no longer the stuff of science fiction; it is weaving itself into the fabric of daily life. From recommendation algorithms on streaming services to sophisticated diagnostic tools in healthcare, AI is ubiquitous. Proponents argue that it increases efficiency and solves complex problems faster than the human brain. However, critics raise ethical concerns regarding privacy, bias in algorithms, and the potential displacement of jobs. As machines become smarter, the line between human intuition and machine logic blurs. The challenge for the 21st century is not just developing AI, but governing it to ensure it serves humanity rather than enslaving it.', 'WAEC_English_2025.json', '2922ee4a50cdf404a60da22c8b6b4f7164e91eacee4c94fe9d5f334cf3784caf');
