INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following planets is the closest to the Sun?', '["Venus","Mars","Mercury","Earth"]', 2, 'Mercury is the first planet from the Sun in our solar system, followed by Venus, Earth, and Mars.', NULL, 'WAEC_Geography_2024.json', 'b0426a3b261171a9c89cbd67bd2570b828cab3fc9089803ea5cb26e273833cb3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The movement of the earth on its axis is called _____.', '["Revolution","Rotation","Precision","Inclination"]', 1, 'Rotation is the spinning of the Earth on its imaginary axis from West to East, which takes approximately 24 hours and causes day and night.', NULL, 'WAEC_Geography_2024.json', 'd4b7fe3910ff2aa65d54759e26f73ab07663596be7676f43c59577487c5d5dfe');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'If the time at the Greenwich Meridian (
) is 12:00 noon, what is the time at 
?', '["9:00 am","3:00 pm","2:00 pm","10:00 am"]', 1, 'The Earth rotates 
 in 1 hour. 
 hours. Since the location is East, we add the time: 12:00 + 3 hours = 3:00 pm.', NULL, 'WAEC_Geography_2024.json', '8917f2f84717d89a2451cc352412b63aafa0db76759ebcb280a6ebadbea0b318');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following is an example of a metamorphic rock?', '["Granite","Limestone","Marble","Sandstone"]', 2, 'Marble is a metamorphic rock formed from the transformation of limestone under great heat and pressure.', NULL, 'WAEC_Geography_2024.json', 'acc76b1a2c75189af207305c9b5e5a32661de2c1cdeae597ae60600fa7540d4c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The point within the earth''s crust where an earthquake originates is called the _____.', '["Epicentre","Focus","Fault line","Crater"]', 1, 'The focus (or hypocenter) is the exact point inside the Earth where the earthquake starts. The epicentre is the point directly above it on the surface.', NULL, 'WAEC_Geography_2024.json', '6ecf6e010fe634066cb838558b4ef73dbd206d0bcc70a0cd4ef3d6ae360b1efa');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'An example of a volcanic mountain in Africa is _____.', '["Mount Kilimanjaro","The Atlas Mountains","The Drakensberg Mountains","The Jos Plateau"]', 0, 'Mount Kilimanjaro in Tanzania is a dormant volcano and the highest peak in Africa.', NULL, 'WAEC_Geography_2024.json', '53469ea23ddf8cb4560dcbfe8badfcd95e253f431e5d7d1513f8370fe70d8da7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The process of physical weathering caused by the repeated freezing and thawing of water in rock crevices is _____.', '["Exfoliation","Hydration","Frost action","Oxidation"]', 2, 'Frost action (or frost wedging) occurs in cold climates where water expands when frozen, exerting pressure that eventually breaks the rock apart.', NULL, 'WAEC_Geography_2024.json', '39250c6deaa82653f005abe41fd662e32a4eb42497fe80743f22885b7ee12f4d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'A rejuvenated river is one that has _____.', '["dried up completely","developed a wide flood plain","gained new erosive power","entered its old stage"]', 2, 'River rejuvenation occurs when there is a fall in sea level or a rise in land, giving the river more vertical energy to erode its bed again.', NULL, 'WAEC_Geography_2024.json', '020625323719569948d7f9f155d8aebdb860d3398a6168c8afb71eda68325f85');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following features is produced by wind erosion in deserts?', '["Barchan","Zeugen","Wadi","Inselberg"]', 1, 'A Zeugen is a table-shaped area of rock found in arid regions, formed by the wind eroding softer layers of rock underneath harder ones.', NULL, 'WAEC_Geography_2024.json', 'f639ca03eeaac9267166d54e74787f42b7a312f8bd44a1e1b53cce58af7a347e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The instrument used to measure wind speed is the _____.', '["Anemometer","Wind vane","Hygrometer","Barometer"]', 0, 'An anemometer measures the speed of the wind, while a wind vane determines its direction.', NULL, 'WAEC_Geography_2024.json', '271e4196bf70ccaeeafad208090197818449c2e2c815e2a052575c05dc1a7e89');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which layer of the atmosphere contains the ozone layer?', '["Troposphere","Stratosphere","Mesosphere","Thermosphere"]', 1, 'The ozone layer is located within the stratosphere and is responsible for absorbing most of the sun''s harmful ultraviolet radiation.', NULL, 'WAEC_Geography_2024.json', '357afa0fc2a6e7aeb2df957e0043c6dc6b20f6f2a8ed29d223b0cef4e0301e41');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Lines on a map joining places with equal atmospheric pressure are called _____.', '["Isohyets","Isotherms","Isobars","Isohels"]', 2, 'Isobars connect areas of equal pressure. Isohyets are for rainfall, Isotherms for temperature, and Isohels for sunshine.', NULL, 'WAEC_Geography_2024.json', '7fb7f879ba6be44569b63f6b7b5ab240ece78709e856b813ddfcb4dce1402547');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The ''Inter-Tropical Convergence Zone'' (ITCZ) is a region where _____.', '["Polar air masses meet","Tropical maritime and Tropical continental air masses meet","Warm and cold ocean currents meet","High-pressure belts are formed"]', 1, 'The ITCZ is the zone where the North-East Trades and the South-West Trades (air masses) converge, influencing rainfall patterns in West Africa.', NULL, 'WAEC_Geography_2024.json', '7c5cb200712745b2ba3642b5d6a53771bdc2c5e72615e9359de423a908be9b60');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The most important factor influencing the climate of West Africa is the _____.', '["Latitude","Altitude","Distance from the sea","Seasonal migration of the ITCZ"]', 3, 'The movement of the ITCZ determines the onset and duration of the rainy and dry seasons in West Africa.', NULL, 'WAEC_Geography_2024.json', 'f51699c1b8ed79669b2f5baf4f54216beb3a623059b608db6cc8068aa0f2937c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which type of vegetation is characterized by broad-leaved evergreen trees and multiple layers of canopy?', '["Tropical Grassland","Coniferous Forest","Tropical Rainforest","Mediterranean Vegetation"]', 2, 'Tropical Rainforests have high rainfall and temperatures year-round, supporting dense, layered, evergreen vegetation.', NULL, 'WAEC_Geography_2024.json', '3819289f391606b1c568f3ddb5858bc9788c72687c9f51c7f9e6f8c4f0bd69d4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The ''Sapped'' or ''Leached'' soils found in the tropical rainforest regions are known as _____.', '["Chernozems","Laterites","Podzols","Chestnut soils"]', 1, 'Laterite soils are formed in hot and wet tropical areas where heavy rain leaches out silica, leaving behind aluminum and iron oxides.', NULL, 'WAEC_Geography_2024.json', '2daec9e66c49cd196cbaed5f540061da96f8cb00e9432fdce60c01e2b6d6b458');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'A linear settlement pattern is most likely to develop _____.', '["at a crossroad","around a circular market","along a major road or railway","on a defensive hilltop"]', 2, 'Linear settlements form in a line, usually following the route of a communication line like a road, river, or railway.', NULL, 'WAEC_Geography_2024.json', '34bf900beaaac54f0c94d69dc8f82127394b38e4d5027758415a2826ccb47924');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following is a pull factor in rural-urban migration?', '["Soil exhaustion","Lack of social amenities","Better job opportunities","Natural disasters"]', 2, 'Pull factors are positive attributes of a destination (the city) that attract migrants, such as better employment and infrastructure.', NULL, 'WAEC_Geography_2024.json', '0a2de823af9e55ebfb614b75abacc0938f5ad86aab012da5ccdcb0834c11e79a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The primary objective of the ''Green Revolution'' is to _____.', '["increase agricultural productivity","plant more trees in urban areas","stop the use of chemicals on farms","protect wildlife"]', 0, 'The Green Revolution refers to the set of research and technology transfer initiatives that increased agricultural production through high-yielding varieties of seeds.', NULL, 'WAEC_Geography_2024.json', '86c2a22268c0e878cb9442690114b4dd8324ba2423075f7129b464287e79f187');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following is an example of a secondary economic activity?', '["Mining","Fishing","Textile manufacturing","Banking"]', 2, 'Secondary activities involve the processing or manufacturing of raw materials into finished goods. Mining and fishing are primary, while banking is tertiary.', NULL, 'WAEC_Geography_2024.json', 'a11bcefd2c09150817757574c1a7b51c335cf01555fca0918ec222f0bd961c6b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The main reason for the location of the Iron and Steel industry at Ajaokuta is _____.', '["availability of cheap labor","nearness to the market","proximity to raw materials","government policy only"]', 2, 'Ajaokuta was chosen due to its proximity to iron ore deposits (Itakpe) and coal, which are essential raw materials for steel production.', NULL, 'WAEC_Geography_2024.json', 'b0350d315f156c561165a8f64c609e4410411cc5100efdb273243105ca22b79c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Environmental pollution caused by the release of sulfur dioxide into the atmosphere leads to _____.', '["Global warming","Acid rain","Ozone layer depletion","The greenhouse effect"]', 1, 'Sulfur dioxide reacts with water vapor in the atmosphere to form sulfuric acid, which falls as acid rain, damaging crops and buildings.', NULL, 'WAEC_Geography_2024.json', '0d2a0234c32b0db35753be326ea69ce90ca59b3e61f9faebfeb229acb9ad7392');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The highest mountain peak in Nigeria is _____.', '["Chappal Waddi","Zuma Rock","Olumo Rock","Idanre Hill"]', 0, 'Chappal Waddi (Gangirwal), located in the Mambilla Plateau of Taraba State, is the highest point in Nigeria.', NULL, 'WAEC_Geography_2024.json', '3e453ec54348d01be814bab3c9965b90133813d37b6f6cab47d880e37bd46e96');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The River Niger enters the Atlantic Ocean through a _____.', '["Delta","Estuary","Lagoon","Canyon"]', 0, 'The Niger Delta is a vast fan-shaped deposit of silt at the mouth of the River Niger, where it splits into numerous distributaries.', NULL, 'WAEC_Geography_2024.json', 'cacabf7b2e2074382e3c4bdbdd87129bd7657d0f73500e2a5b83e06db227ad51');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following mineral resources is found in commercial quantities in Enugu?', '["Petroleum","Tin","Coal","Gold"]', 2, 'Enugu is nicknamed the ''Coal City'' because it was the center of coal mining in Nigeria.', NULL, 'WAEC_Geography_2024.json', '60e727df8147add0c5624ad55cf773d821e7f2ee677f5fb74aaa767d7515c95c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The ''Harmattan'' wind in Nigeria blows from the _____.', '["South-West","North-East","South-East","North-West"]', 1, 'The Harmattan is a dry and dusty North-East trade wind that blows from the Sahara Desert across West Africa.', NULL, 'WAEC_Geography_2024.json', '9aba1d985131ffb84895a550a3e83f1c22907f1858b044dc49c905b789197fc7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The most densely populated area in Nigeria is the _____.', '["Middle Belt","South-West","North-East","Lake Chad Basin"]', 1, 'The South-West, particularly around Lagos and Ibadan, has very high population densities due to industrialization and commercial activity.', NULL, 'WAEC_Geography_2024.json', '0386a81a0e460f2f52537255c594f283ead57c24444b02f1f1676e87c2762332');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'A map with a scale of 1:50,000 is _____ than a map with a scale of 1:250,000.', '["smaller","larger","the same","less detailed"]', 1, 'A larger-scale map (smaller denominator) shows a smaller area but in much greater detail.', NULL, 'WAEC_Geography_2024.json', '671e893b7c7463b509de857ccf3b752c5f7bd9c807b18580b4afe694c45dcb4f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The core of the earth consists mainly of _____.', '["Silica and Aluminum","Silica and Magnesium","Iron and Nickel","Calcium and Sodium"]', 2, 'The core (Barysphere) is primarily composed of Iron (Fe) and Nickel (Ni), often referred to as ''Nife''.', NULL, 'WAEC_Geography_2024.json', '6f451c36617cb9adcc50f3506aeb3a1d467dbf5d467ba2ce6a19e02a5579f8a8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The steep slope of a fold mountain is called a/an _____.', '["Anticline","Syncline","Limb","Axis"]', 2, 'The limbs are the sloping sides of a fold. The anticline is the up-fold, and the syncline is the down-fold.', NULL, 'WAEC_Geography_2024.json', 'abe057d1bf1295c317e6defb7671ea6037558556185933079e22fc9074fc7453');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following is a depositional feature of a river?', '["Waterfall","V-shaped valley","Ox-bow lake","Pothole"]', 2, 'An ox-bow lake is formed in the lower course of a river when a meander is cut off through deposition and erosion.', NULL, 'WAEC_Geography_2024.json', 'e43313c25800703451f55ceea24f938599880c78c818483f6ad4585a1c500ae4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The main source of irrigation water in Northern Nigeria is _____.', '["Direct rainfall","Underground wells","Dams and Rivers","Desalinated seawater"]', 2, 'Dams like the Kainji and Tiga dams provide water for irrigation in the drier northern regions.', NULL, 'WAEC_Geography_2024.json', 'c0c9e808124669127331365f7ef606aa9f2423a30820fa512453640de2521b17');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following is a major export of Nigeria besides crude oil?', '["Automobiles","Cocoa","Wheat","Electronics"]', 1, 'Cocoa remains one of Nigeria''s most significant non-oil agricultural exports.', NULL, 'WAEC_Geography_2024.json', 'eaa49c2a631f0eabcdd0172bad67ded52c6c8297a5c192cc14bbc18ae29f6a90');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The concept of ''Central Place Theory'' was proposed by _____.', '["Wegener","Davis","Christaller","Malthus"]', 2, 'Walter Christaller developed the Central Place Theory to explain the size, spacing, and distribution of settlements.', NULL, 'WAEC_Geography_2024.json', '894289df630f75607abfe41b4f52f48b1b1d21963b76c49faab2b06bbae1cd4e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The process of urban sprawl leads to the _____.', '["concentration of people in the city center","expansion of cities into surrounding rural areas","reduction of pollution","reforestation of the city"]', 1, 'Urban sprawl is the unrestricted growth in many urban areas of housing, commercial development, and roads over large expanses of land.', NULL, 'WAEC_Geography_2024.json', '5a348d92af22571dc03451be57cd4d2bc669a4f421a6251b1bcbc426cade581d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'In a GIS (Geographical Information System), ''raster data'' represents information using _____.', '["Points and Lines","Polygons","A grid of cells or pixels","Text descriptions only"]', 2, 'Raster data represents features as a matrix of cells (pixels), common in satellite imagery.', NULL, 'WAEC_Geography_2024.json', 'b5b459b871a813abe82712285ccf3a60e8edff7110b1b3b484a11674871fd516');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following ocean currents is a cold current?', '["Gulf Stream","Benguela Current","Kuroshio Current","North Atlantic Drift"]', 1, 'The Benguela current off the coast of South-Western Africa is a cold current.', NULL, 'WAEC_Geography_2024.json', '63ddca431f9d00d557e02f2a742a80e2a38a37c5b0822ca57729986a20cb8f77');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The deep, narrow, steep-sided valley formed by a river is a _____.', '["Gorge","Floodplain","Delta","Meander"]', 0, 'A gorge is a narrow valley with very steep, rocky walls, often formed by a river cutting through hard rock.', NULL, 'WAEC_Geography_2024.json', 'efa370707d29f2a0a79189cfd6103f7f3e2638f689b9b70bbf35763296352711');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The world''s highest waterfalls, Angel Falls, are located in _____.', '["Brazil","Venezuela","USA","Zambia"]', 1, 'Angel Falls is located in the Canaima National Park, Venezuela.', NULL, 'WAEC_Geography_2024.json', '1bfc13448ec8fbd3de4b0b4193b441c7ee8ed3c9645bb2f6737c2637ab61d31b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The Mediterranean type of climate is characterized by _____.', '["Hot, wet summers and cold, dry winters","Hot, dry summers and mild, wet winters","Constant high temperatures and rainfall","Very low temperatures year-round"]', 1, 'Mediterranean climates have distinct dry summers and rainy winters.', NULL, 'WAEC_Geography_2024.json', '59db1c5f97cecceae14b8aba6c763c318126d10f2cc5868b411ec8e0d9bec8e4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The study of the relationship between organisms and their environment is _____.', '["Ecology","Geology","Anthropology","Meteorology"]', 0, 'Ecology deals with the interactions of living organisms with their physical environment.', NULL, 'WAEC_Geography_2024.json', '6cdcdd747003f2ad6b899701b68542dda488326897ec7cc30b2f20568fdb452c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The primary cause of deforestation in Nigeria is _____.', '["Wildfires","Agricultural expansion and logging","Acid rain","Volcanic eruptions"]', 1, 'In Nigeria, clearing land for farming and the timber industry are the leading drivers of forest loss.', NULL, 'WAEC_Geography_2024.json', 'd1f35bc12e2bd211caeb3526f2360d44269f3669955fb2609e82f2faa2258bcf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following is a non-renewable resource?', '["Solar energy","Wind","Natural Gas","Water"]', 2, 'Natural gas is a fossil fuel and takes millions of years to form; once consumed, it cannot be replaced in a human timeframe.', NULL, 'WAEC_Geography_2024.json', '470fc9c0a521f5aee5f5d056d44eaa579f1944cd4dfc15675dff7591f018aed4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The term ''Albedo'' refers to the _____.', '["heat absorbed by the earth","reflectivity of a surface","total energy emitted by the sun","temperature of the ocean"]', 1, 'Albedo is the fraction of solar energy (shortwave radiation) reflected from the Earth back into space.', NULL, 'WAEC_Geography_2024.json', '1b4bfab600966695979b39bfc13b76db497c7cf5194eddac0f347b8d0af5bb2b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The largest desert in the world is the _____.', '["Kalahari","Sahara","Gobi","Atacama"]', 1, 'The Sahara Desert in North Africa is the largest hot desert in the world.', NULL, 'WAEC_Geography_2024.json', 'ccb90d9173bbc5b09eedf6cbc8afbca61e0f08d067b81cd3b6c12312ecd54361');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The transition zone between the Sahara desert and the Savannah is the _____.', '["Sahel","Veld","Prairies","Pampas"]', 0, 'The Sahel is the semiarid region of Western and North-Central Africa forming a transition between the Sahara and the Sudanian Savanna.', NULL, 'WAEC_Geography_2024.json', '61e7f617d43fbaa71aee615939e29dbfcd20af6fb1b0387d7381611311deb76e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following is a block mountain?', '["Himalayas","Andes","Vosges","Rockies"]', 2, 'The Vosges in France and the Black Forest in Germany are classic examples of block mountains (Horsts).', NULL, 'WAEC_Geography_2024.json', 'e2ff77426714c224c12b04c452aeb6134c9e767f0590e64912407111ce61bf20');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The scale of a map expressed as 1cm to 2km is a _____ scale.', '["Representative Fraction","Linear","Statement","Diagonal"]', 2, 'A statement scale expresses the relationship in words (e.g., ''one centimeter represents two kilometers'').', NULL, 'WAEC_Geography_2024.json', 'b9373462f528f2fad7c9a384c4e49f1effedf2afbd360f3ae7fb81f38e5900d1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The leading producer of Petroleum in Africa is _____.', '["Ghana","Egypt","Nigeria","South Africa"]', 2, 'Nigeria is historically the largest producer of oil in Africa, significantly impacting its economy.', NULL, 'WAEC_Geography_2024.json', '2ea58a508aa0efb61985b6592418242aec25ee64fccc9ae755217b5f74118d61');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following is a landlocked country in West Africa?', '["Senegal","Mali","Liberia","Nigeria"]', 1, 'Mali is surrounded by land and has no direct access to the sea.', NULL, 'WAEC_Geography_2024.json', '8749ba6b6454cc4e732765485340a54312203f082506cb6b68e88595f2da95f7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The ''Great Barrier Reef'' is located off the coast of _____.', '["Africa","Australia","South America","Asia"]', 1, 'The Great Barrier Reef is the world''s largest coral reef system, located in the Coral Sea off the coast of Queensland, Australia.', NULL, 'WAEC_Geography_2024.json', '911196790b5a501ea2377f5b443cf59149dc78771c659edeb61161f27829c10b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'A plateau that is surrounded by mountains is called a/an _____.', '["Intermontane plateau","Volcanic plateau","Piedmont plateau","Continental plateau"]', 0, 'Intermontane plateaus are the highest and most extensive plateaus in the world, enclosed by fold mountains.', NULL, 'WAEC_Geography_2024.json', '387475f65cc02739a3e78d2b47e0d06a991bf26f179b82ba99b931a183756060');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The process by which plants release water vapor into the atmosphere is _____.', '["Evaporation","Condensation","Transpiration","Precipitation"]', 2, 'Transpiration is the biological process where water is taken up by roots and released as vapor through leaves.', NULL, 'WAEC_Geography_2024.json', '2629291e666774484bd5c42b10ca92038b1e520f4385e7670a1aefbb8dcaa9fd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following cloud types is associated with thunderstorms?', '["Cirrus","Stratus","Cumulonimbus","Altocumulus"]', 2, 'Cumulonimbus clouds are dense, towering vertical clouds associated with heavy rain, lightning, and thunder.', NULL, 'WAEC_Geography_2024.json', '1916d5618ff0b61c35869201bc6b9efbb0bb2c03fe0aec521e6f0df1c199718e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The ''Dead Sea'' is famous because _____.', '["it has no salt","it is the lowest point on the earth''s surface","it is the deepest ocean","it has many fish"]', 1, 'The shore of the Dead Sea is the lowest land point on Earth, and it is highly saline.', NULL, 'WAEC_Geography_2024.json', '4be46c80d9341ab7cb304190e22aedc3d9bde987e4ca856ef4738712d6b5232c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The main cause of the tides in the ocean is the _____.', '["Wind","Earth''s rotation","Gravitational pull of the moon and sun","Earthquakes"]', 2, 'Tides are the periodic rise and fall of sea levels caused by the gravitational forces exerted by the Moon and the Sun.', NULL, 'WAEC_Geography_2024.json', '1b694cd0087a31f19fbff1980a885e6e20bb9168d60409c77b72bb74b49f5230');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following is a renewable energy source?', '["Coal","Petroleum","Geothermal energy","Nuclear energy"]', 2, 'Geothermal energy is heat from the earth''s interior and is considered a sustainable and renewable resource.', NULL, 'WAEC_Geography_2024.json', '2ff5d094f037480cedbab647952e2ffaa440494eb82929bd12718ac918aa824e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The ''Great Rift Valley'' is located in _____.', '["West Africa","East Africa","North Africa","Southern Africa"]', 1, 'The Great Rift Valley is a continuous geographic trench running through Ethiopia, Kenya, Tanzania, and beyond.', NULL, 'WAEC_Geography_2024.json', 'e16b4e4f0e800f930f019fbaaed67b54303b3eeca8b5523e9c08c2bffacc5c2c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The mapping of the ocean floor is called _____.', '["Topography","Bathymetry","Cartography","Demography"]', 1, 'Bathymetry is the study and mapping of the underwater depths of lake or ocean floors.', NULL, 'WAEC_Geography_2024.json', 'c822ef35e92ba9ce8821a1c6ce1317435eb24f7ded15a8d10b13947421b50815');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following is a primary factor in soil formation?', '["Parent material","Traffic","Irrigation","Crop rotation"]', 0, 'Parent material (rocks) provides the mineral base for soil formation through the process of weathering.', NULL, 'WAEC_Geography_2024.json', 'e88a091364054cd8de2ffaa8aff612919d6d5ebd3859b296215a1d5cbfe2d8a0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The imaginary line that divides the earth into Northern and Southern hemispheres is the _____.', '["Prime Meridian","Tropic of Cancer","Equator","Arctic Circle"]', 2, 'The Equator is the zero-degree latitude line that bisects the Earth into North and South.', NULL, 'WAEC_Geography_2024.json', 'ffc14fb1e8b720605a3c1c0442bcd28cd0115c05415faf3f79abfb0f339834a3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The study of human population statistics is known as _____.', '["Demography","Geography","Sociology","Statistics"]', 0, 'Demography involves the statistical study of populations, including births, deaths, and migration.', NULL, 'WAEC_Geography_2024.json', 'f0b07d39235c7dc8f6713298549b50e24bc9f53c5e7918c32f468ea90e7f1fc3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'Which of the following is a major challenge for the ECOWAS sub-region?', '["Too much gold","Political instability and insecurity","Lack of land","Extremely cold weather"]', 1, 'Conflicts, coups, and terrorism are major hurdles to economic integration in West Africa.', NULL, 'WAEC_Geography_2024.json', '25d09085b219e3f24e8340c87bcfffcb4461371f6c4d8e89cf7e531ded2b8aa9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The most important crop in the ''Rice-Wheat'' belt of the world is _____.', '["Rubber","Cereal","Tobacco","Cotton"]', 1, 'Cereals (Rice and Wheat) are the staple foods for the majority of the world''s population.', NULL, 'WAEC_Geography_2024.json', 'e3661e71f4c1c117a798dd7c23bd37a56608b1593208d1c4c76529aa94daf37f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The process by which solar energy reaches the earth is _____.', '["Conduction","Convection","Radiation","Advection"]', 2, 'Heat from the sun travels through the vacuum of space to the Earth via electromagnetic waves (radiation).', NULL, 'WAEC_Geography_2024.json', '12a3d03edb0d5ef2d95fe5dedd93cf62033ca1fb334a4ac04967ece29a7347f5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The layer of the earth upon which the crust ''floats'' is the _____.', '["Inner core","Asthenosphere","Lithosphere","Exosphere"]', 1, 'The asthenosphere is the highly viscous, mechanically weak, and ductile region of the upper mantle of the Earth.', NULL, 'WAEC_Geography_2024.json', '5d82c1be300f3e87b4006c928c1767b60d4177d63ae77d7485749a0c6d6191b3');
