INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The most common type of rainfall in the tropics is _____.', '["Orographic","Cyclonic","Convectional","Frontal"]', 2, 'Convectional rainfall occurs when the intense sun heats the ground, causing air to rise, cool, and condense into heavy rain, often in the afternoon.', NULL, 'WAEC_Geography_2024.json', 'dca28fddbfba433cb1a81146b977ce1d9f6d86db56891f889070899b80be3ebc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Geography', 2024, NULL, 'The ''Primacy'' of a city refers to _____.', '["its age","its dominance in size and influence over other cities in the country","its location at the center of the map","its proximity to a river"]', 1, 'A primate city is much larger than any other city in the country and dominates the economic and political life of the nation (e.g., Lagos in Nigeria).', NULL, 'WAEC_Geography_2024.json', '11929c8acd72ea41516b9ed1053a14a413730f756f864ad1db4a05ed19f4d314');
