INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The process of depriving a person of his citizenship is known as _____.', '["expatriation","denaturalization","deportation","disenfranchisement"]', 1, 'Denaturalization is the official act of depriving a person of citizenship, especially one acquired through naturalization, often due to criminal activity or fraud.', NULL, 'WAEC_Government_2024.json', 'c140d084d8d7701b561ab86784ccf08f934cc60e7950bc52d4b50f181e749958');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'A major feature of a unitary system of government is that _____.', '["power is shared between the center and components","it has a rigid constitution","the central government is supreme","it is most suitable for large countries"]', 2, 'In a unitary system, all constitutional powers are vested in the central government, which may delegate tasks to sub-national levels at its own discretion.', NULL, 'WAEC_Government_2024.json', 'c6c0108335e71f08e980ee146d72371a890213e3cf80e35c4f96161afcf3dc01');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The primary function of the legislature is to _____.', '["execute laws","interpret laws","make laws","adjudicate disputes"]', 2, 'The legislature is the organ of government constitutionally empowered to debate, amend, and pass laws for the peace and good governance of the state.', NULL, 'WAEC_Government_2024.json', '8722240dab09aff94286adc1ba01275b1581458d9168c73126032e27bc01403a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The concept of ''Rule of Law'' was popularized by _____.', '["A.V. Dicey","Baron de Montesquieu","Jean Bodin","Thomas Hobbes"]', 0, 'A.V. Dicey, in his book ''Introduction to the Study of the Law of the Constitution'', outlined the three pillars of the rule of law: supremacy of the law, equality before the law, and protection of individual rights.', NULL, 'WAEC_Government_2024.json', 'aa456a2a350f5419aa1ae8c480f08beb9fca4ec366218222a457999c84c45ac7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The Yoruba pre-colonial political system was based on the principle of _____.', '["checks and balances","divine right of kings","acephalous structure","military autocracy"]', 0, 'The Old Oyo Empire utilized a system of checks and balances where the Oyomesi (King makers) could check the powers of the Alaafin (the King).', NULL, 'WAEC_Government_2024.json', 'd42c393a2f81116928037a0957a795ae66ed330f117f2d579ed8edcdefe3f6a1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Which of the following is a permanent feature of the Civil Service?', '["Partisanship","Political headship","Anonymity","Inconsistency"]', 2, 'Anonymity means civil servants are neither praised nor blamed publicly for government policies; they work behind the scenes and remain invisible to the public.', NULL, 'WAEC_Government_2024.json', 'ec678f74096a6eb830de30d83e1db5ea61459e705bc14b2b34f8de9cc9786884');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The Lyttleton Constitution of 1954 was significant because it _____.', '["introduced the elective principle","made Nigeria a federation","created the second chamber","introduced the office of the Prime Minister"]', 1, 'The 1954 Lyttleton Constitution formally established Nigeria as a federation by sharing powers between the central government and the regional governments.', NULL, 'WAEC_Government_2024.json', 'dca0aaa116cf91ef4263242a80a46f00c5175f04705d33f23a226b11167df300');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The administrative headquarters of the United Nations is located in _____.', '["Geneva","London","New York","Washington D.C."]', 2, 'The UN headquarters is in New York City, USA, where the General Assembly and Security Council primarily meet.', NULL, 'WAEC_Government_2024.json', '4d48ba7be6489ca61372c6b311d401209e76ca4a087538ba4b074bf04ec16115');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'A major advantage of a bicameral legislature is that it _____.', '["is less expensive to maintain","hastens the law-making process","prevents the passage of hasty legislation","concentrates power in one house"]', 2, 'Bicameralism (having two houses) allows the second chamber to act as a check on the first, ensuring that bills are thoroughly debated and not passed in a hurry.', NULL, 'WAEC_Government_2024.json', '74128ae722ca69357ebb26e88012f43b21c302f783b995511369953a916d1b2d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The highest court of appeal in Nigeria during the colonial era was the _____.', '["Supreme Court","Federal High Court","Judicial Committee of the Privy Council","West African Court of Appeal"]', 2, 'Before Nigeria became a republic in 1963, the final appellate body was the Judicial Committee of the Privy Council in London.', NULL, 'WAEC_Government_2024.json', '5fbc9e21ac2a60d87b32ec3686499ebeb4943da6ddf23785ff358d9fe9065de0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Pressure groups differ from political parties in that they _____.', '["aim at winning elections","interest themselves in governance","seek to influence government policies","have wide manifestoes"]', 2, 'Unlike political parties that seek to control state power by winning elections, pressure groups only seek to influence government decisions in favor of their members.', NULL, 'WAEC_Government_2024.json', '1cb6c16f9c4592de8e452bdd30d000bca3eb8ab7e84f9531343d8155714cd925');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The 1979 Constitution of Nigeria introduced the _____.', '["Parliamentary system","Presidential system","Unitary system","Confederal system"]', 1, 'The 1979 Constitution marked a shift from the British-style parliamentary system to the American-style presidential system, with an executive President.', NULL, 'WAEC_Government_2024.json', 'c71f89028d1526b3e8ce8171d6f643f190ac3454f0ca97a8511ed705ef2903c0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The first indigenous Governor-General of Nigeria was _____.', '["Sir Abubakar Tafawa Balewa","Sir Ahmadu Bello","Dr. Nnamdi Azikiwe","Chief Obafemi Awolowo"]', 2, 'Dr. Nnamdi Azikiwe became the first indigenous Governor-General in 1960 and later the first President when Nigeria became a Republic in 1963.', NULL, 'WAEC_Government_2024.json', 'f6e6ff11ac0d745a22d1587a314514251bf110244e0281c0530ead5a7fb52bf2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The ''Elective Principle'' was first introduced in Nigeria by the _____.', '["Richards Constitution","Clifford Constitution","Macpherson Constitution","Lyttleton Constitution"]', 1, 'The 1922 Clifford Constitution introduced the elective principle, which allowed for the first time the election of four representatives to the Legislative Council (3 for Lagos, 1 for Calabar).', NULL, 'WAEC_Government_2024.json', '96c2448af50933610a515b882983bceedce3f4160c09a8ef6e2fe7ce1149257e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Which organ of the United Nations has the power to veto decisions?', '["The General Assembly","The Secretariat","The Security Council","The Economic and Social Council"]', 2, 'The five permanent members of the UN Security Council (USA, UK, France, Russia, and China) possess veto power over substantive resolutions.', NULL, 'WAEC_Government_2024.json', '933803d5c28ab17e987698a990413fad8d7bb470072e1ba4391da5729f2be91b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The term of office for the Secretary-General of the Commonwealth is _____.', '["three years","four years","five years","six years"]', 1, 'The Commonwealth Secretary-General serves a four-year term and is eligible for re-election only once.', NULL, 'WAEC_Government_2024.json', '962e68e42aea561ef693aba48b9f5f43f9e7ff4c5d056345745d362d7978a73a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'A system of government where power is held by a few wealthy people is called _____.', '["Oligarchy","Aristocracy","Plutocracy","Monarchy"]', 2, 'Plutocracy is a society or system ruled and dominated by the small minority of the wealthiest citizens.', NULL, 'WAEC_Government_2024.json', 'faf257136369c143c8271ade40d067931c13901e485ecb842fe16183093229bc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'In the pre-colonial Hausa/Fulani system, the Emir''s adviser on Islamic law was the _____.', '["Waziri","Madawaki","Galadima","Sarkin Pada"]', 0, 'The Waziri acted as the Prime Minister and the chief legal adviser to the Emir on administrative and Islamic matters.', NULL, 'WAEC_Government_2024.json', 'cb8d5e3cfcb4350c93ab834786bed20f3461f062d81543e3504f50ab0c18a1f5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The primary aim of the Economic Community of West African States (ECOWAS) is _____.', '["military defense","economic integration","cultural exchange","political unification"]', 1, 'ECOWAS was established in 1975 primarily to promote cooperation and integration in economic, social, and cultural activity in West Africa.', NULL, 'WAEC_Government_2024.json', 'ae16e491d77008231274676516a53524e80fc4ce8ca69ee615f7a5203c329633');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The power of a court to declare a law unconstitutional is known as _____.', '["Judicial independence","Judicial Review","Prerogative writ","Injunction"]', 1, 'Judicial Review is the power of the judiciary to examine the actions of the legislative and executive branches and determine their constitutionality.', NULL, 'WAEC_Government_2024.json', 'a9e6051798a7f3774cf62215c1915cba3b66eb2f2f003a946b781e266b3dbc34');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'An unwritten constitution is one that is _____.', '["not based on any documents","based on customs and conventions","totally in the memory of the elders","incapable of being amended"]', 1, 'An unwritten constitution, like that of the UK, is not found in a single document but consists of a collection of laws, judicial precedents, customs, and conventions.', NULL, 'WAEC_Government_2024.json', '014afd4510ff5a9cc5292704be485a4dc62cae409ed657c7169702525a93e893');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The 1963 Constitution of Nigeria replaced the _____.', '["Queen of England as Head of State","Prime Minister as Head of Government","Senate as the upper house","Federal system with a unitary one"]', 0, 'The 1963 Republican Constitution abolished the monarchy in Nigeria, replacing the Queen with an indigenous President as the Head of State.', NULL, 'WAEC_Government_2024.json', '66fd9f0d841ffac7ff10b48fb781c855b8a762b21e6c58594cbab666ec8be5ea');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'A major feature of the Macpherson Constitution of 1951 was the _____.', '["introduction of the ministerial system","granting of total independence","abolition of the regions","introduction of a single legislature"]', 0, 'The 1951 Macpherson Constitution introduced a semi-responsible government by creating central and regional legislatures with appointed ministers.', NULL, 'WAEC_Government_2024.json', 'd07a7964467e3f255090de812fd707f67ddf97605caeb90b51b7535b129bdc0b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Delegated legislation is made by _____.', '["the Judiciary","the Legislature","administrative bodies","political parties"]', 2, 'Delegated legislation (also known as subordinate legislation) is law made by an executive authority under powers given to them by an Act of the Legislature.', NULL, 'WAEC_Government_2024.json', '49816b02cbdbce61c1dc209ce37df24af034d943d70be96f14f701f585a2bd68');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The African Union (AU) was established in 2002 to replace the _____.', '["ECA","OAU","ECOWAS","SADC"]', 1, 'The AU replaced the Organization of African Unity (OAU) to better address the challenges of integration and development on the continent.', NULL, 'WAEC_Government_2024.json', '7629307a3b3b5ddd669a656b1b5c0e9ae1afd62cf203c56a3d47fed6c847d73a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Which of the following is an obligation of a citizen?', '["Right to life","Freedom of speech","Payment of taxes","Right to fair hearing"]', 2, 'Citizens have duties or obligations to the state, such as paying taxes, obeying laws, and voting, which are different from their rights/claims.', NULL, 'WAEC_Government_2024.json', '26e3d73098cace960f323555ea00aee53e68322e3a17e72f4a9a8599453c93d8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The method used to remove a President in a presidential system of government is _____.', '["Vote of no confidence","Recall","Impeachment","Resignation"]', 2, 'Impeachment is the formal process by which a legislative body levels charges against a government official for misconduct, which can lead to removal from office.', NULL, 'WAEC_Government_2024.json', 'a319b699f5b1b10a9cb095e3f51b88260b20eb34af23014d1f4182e275b4aa8a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'In a parliamentary system of government, the Head of Government is the _____.', '["President","Monarch","Prime Minister","Chief Justice"]', 2, 'In a parliamentary system (e.g., Britain), the Prime Minister is the Head of Government and exercises executive power, while the Monarch or President is the Head of State.', NULL, 'WAEC_Government_2024.json', '777cf24f771275b8e6c709f1b057fda2b1d87060fadc615d50a3831d93d7b654');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The principle of separation of powers is intended to prevent _____.', '["the rule of law","tyranny","democracy","federalism"]', 1, 'Separation of powers ensures that no single organ of government becomes too powerful, thereby protecting the liberty of citizens and preventing autocracy.', NULL, 'WAEC_Government_2024.json', '85b7dec18172a1388f53f90e6609109fcc5f25ac824de1a53e3af80702c1ad36');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The first military coup d''état in Nigeria occurred on _____.', '["January 15, 1966","July 29, 1966","July 29, 1975","December 31, 1983"]', 0, 'The first coup was led by Major Chukwuma Kaduna Nzeogwu on January 15, 1966, bringing an end to the First Republic.', NULL, 'WAEC_Government_2024.json', 'b0361a2c8c4ddd1f493df0c20f729e63587988d207d8a60d52022d59afbd4f5f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The head of a local government council in Nigeria is the _____.', '["Councilor","Chairman","Governor","Secretary"]', 1, 'The Chairman is the executive head of a Local Government Area (LGA) in Nigeria.', NULL, 'WAEC_Government_2024.json', '0487b80869949bebd3df839d9e58880d9ea3e42be826d77c2fa4bd6bb639a8ac');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Sovereignty belongs to the _____.', '["Legislature","Executive","Judiciary","State"]', 3, 'Sovereignty is the supreme and absolute power of a state to make and enforce laws within its territory without external interference.', NULL, 'WAEC_Government_2024.json', '140c9da2e266f910a10900d86f26ab174125080109fe757a3e6ac87e1a02c76d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Which of the following defines a ''State''?', '["A group of people with common language","A defined territory with a government and sovereignty","A geographical area with many resources","A collection of political parties"]', 1, 'A state must have four essential elements: population, territory, government, and sovereignty.', NULL, 'WAEC_Government_2024.json', 'dc9ff92f5358ed01b4c03bd7153f56b954ae307382183b26448b74e00278bb16');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The pre-colonial Igbo political system was described as acephalous because _____.', '["it was highly centralized","it was led by powerful kings","it lacked a central authority","it was governed by the military"]', 2, '''Acephalous'' means ''headless''. The Igbo system was decentralized, based on village assemblies and age grades rather than a single monarch.', NULL, 'WAEC_Government_2024.json', 'c3657e3505372d82267cc37e71e942f9809b6d027551fe5964dab7b6efd89016');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Public opinion is important in a democracy because it _____.', '["enables the government to suppress critics","serves as a guide for government policies","replaces the need for elections","is always uniform"]', 1, 'Public opinion reflects the views of the citizenry, helping the government understand the needs and reactions of the people to its programs.', NULL, 'WAEC_Government_2024.json', 'b81dda01f9ca72b95dcae4ff47985c2db7f22fd4f8c19a8662899d543099935d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The Richard''s Constitution of 1946 was noted for dividing Nigeria into _____.', '["two regions","three regions","four regions","twelve states"]', 1, 'The Richard''s Constitution divided Nigeria into three administrative regions: Northern, Western, and Eastern regions.', NULL, 'WAEC_Government_2024.json', 'd46da0550d6aafcd5f7c3f52ea156a1c8c9bbb989b51565c1895ccbf3bd2a44a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The ''Oyo Mesi'' were _____ in the pre-colonial Oyo Empire.', '["tax collectors","palace guards","king makers","religious leaders"]', 2, 'The Oyo Mesi was a council of seven chiefs who acted as king-makers and provided checks on the Alaafin''s power.', NULL, 'WAEC_Government_2024.json', '82d4a437551737c3d090efacb28b475ef7bf72600be6e1a9f3c81f9576bfe648');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Universal Adult Suffrage means the right of _____.', '["all adults to vote","only men to vote","only taxpayers to vote","only educated people to vote"]', 0, 'Suffrage refers to the right to vote. Universal adult suffrage ensures that all qualified adults can vote regardless of property or gender.', NULL, 'WAEC_Government_2024.json', '282627748c7dea14e8d32bc0643077fb7bb5cdb282a1849521940e82679698e7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The main objective of the Commonwealth of Nations is _____.', '["to establish a global government","to foster cooperation among former British colonies","to promote a single currency","to replace the United Nations"]', 1, 'The Commonwealth is a voluntary association of independent states, most of which were formerly under British rule, collaborating on social and economic goals.', NULL, 'WAEC_Government_2024.json', 'd6dca852f07cdd989f896c48593ce5f805d8ce3565f113fb9e53cc38ffac2eee');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The 1999 Constitution of Nigeria is _____.', '["flexible","unwritten","rigid","confederal"]', 2, 'A rigid constitution requires a special, difficult procedure for amendment. The 1999 Nigerian Constitution requires 2/3 majority of both chambers and 2/3 of State Assemblies.', NULL, 'WAEC_Government_2024.json', '77e160a89ffe82b0c8ad7ddf1f83df847968bc874068d9b29f9209fb151f314f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Who was the Chairman of the 1976 Constitution Drafting Committee in Nigeria?', '["Chief Rotimi Williams","Dr. Nnamdi Azikiwe","Justice Udo Udoma","Chief Obafemi Awolowo"]', 0, 'Chief Rotimi Williams headed the ''49 Wise Men'' committee that drafted the 1979 Constitution.', NULL, 'WAEC_Government_2024.json', 'df931093817785d8328e3b75cd3d4c3a1b8dacb34c1756daa15f51a0cfb8ac33');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'A disadvantage of a one-party system is that it _____.', '["is very expensive","leads to political instability","promotes dictatorship","causes frequent elections"]', 2, 'Because there is no legal opposition, a one-party system often leads to the suppression of dissenting voices and the rise of authoritarianism.', NULL, 'WAEC_Government_2024.json', '7ea79f4f65ce10ce36accf36dd54775447efc8ff46236f74ee389a8bd1a63cf1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The administrative structure of Nigeria''s foreign policy is headed by the _____.', '["Ministry of Finance","Ministry of Foreign Affairs","National Intelligence Agency","Ministry of Interior"]', 1, 'The Ministry of Foreign Affairs is the government body responsible for the day-to-day management of Nigeria''s external relations.', NULL, 'WAEC_Government_2024.json', '2182996fc31b91038193ddf231ed1d41f0d5d46faf64fae4aef48ecea34d9d41');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'In the pre-colonial Hausa/Fulani system, the head of a district was the _____.', '["Hakimi","Alkili","Galadima","Dogari"]', 0, 'The Hakimi was the district head appointed by the Emir to oversee a specific area within the Emirate.', NULL, 'WAEC_Government_2024.json', '2a1b5a3c1c5c0de8d15e7cec6677b6409be9fc761fabc8d9a3bb31d18bfc6df0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'A major criticism of the 1922 Clifford Constitution was that _____.', '["it introduced the elective principle","it excluded the North from the Legislative Council","it created regions","it gave too much power to Nigerians"]', 1, 'The Legislative Council under Clifford only made laws for the Southern Province, while the Governor continued to rule the North by proclamation.', NULL, 'WAEC_Government_2024.json', '6b95d914020dc890e475ba96c8744ddaa9c05f906f270b5d7cb5a329439aa118');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Non-alignment as a foreign policy means _____.', '["joining all military alliances","not taking sides in the Cold War between East and West","complete isolation from world affairs","supporting only African nations"]', 1, 'The Non-Aligned Movement (NAM) was formed by countries that did not want to be formally aligned with either the USA-led or the Soviet-led blocs.', NULL, 'WAEC_Government_2024.json', '10ff54a2c3813dacfdc419c990e1b80b1df78daad022362b33f20529a3568c1a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The primary purpose of the Civil Service Commission is to _____.', '["make laws for the country","recruit and manage civil servants","campaign for the ruling party","adjudicate criminal cases"]', 1, 'The Commission is an independent body that ensures merit-based recruitment, promotion, and discipline of workers in the civil service.', NULL, 'WAEC_Government_2024.json', '9e779d316b71945898476b4d4401570c8a73eb130a5be13a2beaa179e3890597');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Bicameralism refers to _____.', '["government by two political parties","a legislature with two houses","separation of powers between two organs","a federation with two regions"]', 1, 'Bicameralism is the practice of having two legislative or parliamentary chambers (e.g., the Senate and House of Representatives).', NULL, 'WAEC_Government_2024.json', '890393bf313fd46092302ed92af5ec85b5873a55bc76dfd883558a2a79a974b7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Which of the following is a source of a constitution?', '["Manifestoes","Party symbols","Judicial precedents","Police reports"]', 2, 'Judicial precedents (past court rulings) are a vital source of constitutional law, especially in common law systems.', NULL, 'WAEC_Government_2024.json', 'b9f6738e6e6286b95320305a4cdb9d9c9c9289fa50541878aa24033328395029');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'An advantage of a flexible constitution is that _____.', '["it is difficult to amend","it prevents dictatorship","it can be easily adapted to emergencies","it is always in a single document"]', 2, 'A flexible constitution (like the UK''s) can be amended by a simple majority in parliament, making it easier to change in response to urgent national needs.', NULL, 'WAEC_Government_2024.json', '1dad459502a8767b9e486963b116d6ab2fd4a37b6af517b230e13616d3fd7c3a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The organ of government that protects the citizens from arbitrary use of power is the _____.', '["Executive","Judiciary","Legislature","Police"]', 1, 'Through the power of judicial review and the issuance of writs like Habeas Corpus, the Judiciary protects citizens'' rights against executive excesses.', NULL, 'WAEC_Government_2024.json', '38baabf267683bfa2d87714c542244ceadf9898ced8bcaaaec29f7b110897782');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'In the pre-colonial Igbo system, the ''Ofo'' was a symbol of _____.', '["military strength","wealth","authority and justice","youthful energy"]', 2, 'The Ofo was a sacred staff representing the authority of the ancestors and the principle of truth and justice in Igbo traditional society.', NULL, 'WAEC_Government_2024.json', '00aaef626bcdfb939909c03230cd912f85ed69cf6209e65f8a7b692f9865fe13');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The 1989 Constitution of Nigeria was never fully implemented because _____.', '["it was rejected by the people","the Third Republic was aborted","it was too expensive","it was poorly written"]', 1, 'The 1989 Constitution was designed for the Third Republic, which was cut short by the annulment of the June 12, 1993, presidential election.', NULL, 'WAEC_Government_2024.json', '61353b708b9b2842435a77e0eb7faa12c1b22ccc0bb5b8f6769a19591ee795fb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The process by which people are moved from a centralized government to local units is _____.', '["Centralization","Decentralization","Nationalization","Socialization"]', 1, 'Decentralization involves the transfer of powers and responsibilities from the central government to local or regional authorities.', NULL, 'WAEC_Government_2024.json', '04c705582bab156093963c9481edd7d6067433b039e843996a21681df2f53ec8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The main reason for the 1976 Local Government Reforms in Nigeria was to _____.', '["abolish local governments","make them uniform and effective","reduce their powers","allow the military to rule them"]', 1, 'The 1976 reforms aimed to create a uniform structure for local governments across Nigeria and make them a third tier of government.', NULL, 'WAEC_Government_2024.json', '0be3ea63a44d4e58b78a56eab971b75bba0bdecb35a56f4df9c65cbd0f9f242d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Fascism as a system of government originated in _____.', '["Germany","Italy","Russia","Spain"]', 1, 'Fascism was founded by Benito Mussolini in Italy after World War I, characterized by dictatorial power and strong regimentation.', NULL, 'WAEC_Government_2024.json', '7dd0f4544221b412010c6d6ba92c2d5173a991cf4a1e7d69ca9cf19e93b33cae');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'A ''Confederation'' is a system where _____.', '["the center is very strong","component units are more powerful than the center","power is shared equally","there is only one level of government"]', 1, 'In a confederation, independent states unite for common purposes but retain their individual sovereignty, making the central authority weak.', NULL, 'WAEC_Government_2024.json', '7545a9e6da35d0cd212875700bb218c36c8140eed1d1d4aa058628ed097c2830');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The ''Power of the Purse'' is exercised by the _____.', '["Executive","Judiciary","Legislature","Civil Service"]', 2, 'The legislature has the constitutional power to approve the budget (income and expenditure) of the state.', NULL, 'WAEC_Government_2024.json', '1eb8f192782d408cc3f3950d19c6d101a2215f87c5c97aea38ab46cb9684a4b7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Who was the first Nigerian to be appointed as a Minister in the colonial era?', '["Sir Ahmadu Bello","Chief Festus Okotie-Eboh","Sir Louis Mbanefo","None of the above"]', 3, 'Ministerial appointments for Nigerians only began under the 1951 Macpherson Constitution. Note: Question difficulty is High; early ministers included various regional leaders.', NULL, 'WAEC_Government_2024.json', '2ee42286d58f7ff50f114aa7e5c1bfeba9120d1eedbaeb63852131afa26dccc5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The headquarters of the African Union (AU) is in _____.', '["Lagos","Cairo","Addis Ababa","Nairobi"]', 2, 'Addis Ababa, Ethiopia, is the capital of the AU, inherited from the OAU.', NULL, 'WAEC_Government_2024.json', 'cb443a0ec2f2a61d70d3c52901211fc8d4bfb33d603b1106428bc9662cda853a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Gerrymandering is a term used in _____.', '["Judicial proceedings","Electoral practice","Legislative debate","Budgeting"]', 1, 'Gerrymandering is the manipulation of electoral boundaries to favor one political party over another.', NULL, 'WAEC_Government_2024.json', 'b81d587dbb6b12967500dc2d37f0742da030c5b292ffd0f4239eb17ae4c06025');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The first President of the OAU was _____.', '["Kwame Nkrumah","Haile Selassie","Julius Nyerere","Jomo Kenyatta"]', 1, 'Emperor Haile Selassie of Ethiopia served as the first chairperson of the OAU in 1963.', NULL, 'WAEC_Government_2024.json', 'a8185eb203d896e3e0ab3b6868122e797248ffdb98569a22b4675f55b20d4d29');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The system of ''Indirect Rule'' was introduced in Nigeria by _____.', '["Lord Milverton","Sir Bernard Bourdillon","Lord Frederick Lugard","Sir Hugh Clifford"]', 2, 'Lord Lugard implemented the policy of using traditional rulers to govern the people under British supervision.', NULL, 'WAEC_Government_2024.json', 'fd7b640f60b878e4a22d1ac505591be4b423d67d0c3a48223ddfb3d59cd90409');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The 1951 Macpherson Constitution was criticized for being _____.', '["too rigid","a ''compromise'' constitution","strictly unitary","purely indigenous"]', 1, 'It was described as a compromise because it tried to satisfy both the centralist and regionalist demands of Nigerian politicians.', NULL, 'WAEC_Government_2024.json', '6630a5e92a4078c11fbf06495f46a2424ec704c3fc84d39a3c195f26d4448399');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'A bureaucratic organization is characterized by _____.', '["informality","hierarchy of authority","partisan recruitment","flexible rules"]', 1, 'Bureaucracy is defined by a clear hierarchy, division of labor, and adherence to formal rules and procedures.', NULL, 'WAEC_Government_2024.json', '9f458b5f8ddb4918830d2c897a7742d7f3b54cb70c1e274f72bf2bb37a8e38f3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The permanent members of the UN Security Council are _____.', '["3","5","10","15"]', 1, 'There are 5 permanent members and 10 non-permanent members elected for two-year terms.', NULL, 'WAEC_Government_2024.json', '76e756c0ab66a18c0590a4240dc9c0b5127c94aed7dbd44b132a6f94b46c9a19');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'Socialism is an economic and political system based on _____.', '["private ownership of means of production","state ownership of means of production","rule by the military","religious laws"]', 1, 'Socialism advocates that the means of production, distribution, and exchange should be owned or regulated by the community as a whole.', NULL, 'WAEC_Government_2024.json', '3fbda0ca30d5e1096caffe8035e07ff5d9df513a95ebd300c99254d02dafc0b6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The official in charge of the records of a local government is the _____.', '["Chairman","Treasurer","Secretary","Councilor"]', 2, 'The Secretary to the Local Government manages the administrative records and correspondence of the council.', NULL, 'WAEC_Government_2024.json', 'e1c76338829fbce19242089e32a649e62f9e377ed8fd671f973cd3c3a412232d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'In a democracy, sovereignty resides in the _____.', '["Electorate","Government","Monarch","Military"]', 0, 'Popular sovereignty means that the ultimate power of the state belongs to the people, who exercise it through voting.', NULL, 'WAEC_Government_2024.json', '1a1539568dac44af5bd3dd0e16f2a6360a353c21e8e85d6328868a0cd4e1ee10');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Government', 2024, NULL, 'The document that contains the rules of a political party is the _____.', '["Constitution","Manifesto","Hansard","Gazette"]', 0, 'While the manifesto contains the party''s plans/promises, the party''s constitution contains the internal rules and structure.', NULL, 'WAEC_Government_2024.json', '7bb78d8312ad903048d51cf585e30727c323c0867683f03368d7959beb8eb6dc');
