INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne ne cikin wadannan wakilin suna ne na nuni (Demonstrative Pronoun)?', '["Wannan","Su","Mu","Kai"]', 0, '''Wannan'' (this) is used for pointing or indicating a specific noun, making it a demonstrative pronoun.', NULL, 'WAEC_Hausa_2024.json', '5ad6067704c9df24a7d1e6d45323648328374d641a9497cd2f1dc1bb54dea272');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wasulan Hausa guda nawa ne a tsaye (Standard vowels)?', '["Biyar","Bakwai","Goma","Sha biyu"]', 0, 'Standard Hausa has five basic vowels: a, e, i, o, u.', NULL, 'WAEC_Hausa_2024.json', '46623d2439f207b15b7ee5be130c6c280655913cb740ff041b42f755352e7d24');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Kammala karin maganar nan: ''Kowa ya ci zomo, _____.''', '["ya ci gudu","ya sha romo","ya san dadinsa","ya tafi gida"]', 0, 'The complete proverb is ''Kowa ya ci zomo, ya ci gudu'', which translates to ''Whoever eats a rabbit must run like one'' (consequences follow actions).', NULL, 'WAEC_Hausa_2024.json', 'ff80058adb4159476b0bd86aa55b9b21c2a2437511fe48c79212024a1225920f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Kalmar ''Yarinya'' tana nuna jinsi na _____.', '["Mace","Miji","Gami","Babu"]', 0, '''Yarinya'' means ''girl'', which falls under the feminine (mace) gender category.', NULL, 'WAEC_Hausa_2024.json', '39e5cb365954a6741152be11382c50525d221b0d6c4ca2e4c17725f55ce5884f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'A wanne bangare na sauti ake samun ''Gamasauti'' (Diphthongs)?', '["Bakari","Wasali","Gaba","Amshi"]', 1, 'Diphthongs are a combination of two vowel sounds within the same syllable, hence they belong to the ''Wasali'' (Vowel) category.', NULL, 'WAEC_Hausa_2024.json', 'ddddc12bf28e9b48ec424c9cb7482b78d43db5b1487805b38bc1bb8ca354ae7b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wane littafi ne Dr. Abubakar Imam ya rubuta?', '["Magana Jari Ce","Ruwan Bagaja","Iliya Dan Maikarfi","Gambo Sawaba"]', 0, 'Dr. Abubakar Imam is the renowned author of the Hausa classic ''Magana Jari Ce''.', NULL, 'WAEC_Hausa_2024.json', '923c361f8ebe9b56e58a194e724a154f6bc68e637c7f7f40234cfd96d9e652a1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wacce sana''a ce ake amfani da ''Kira'' a cikinta?', '["Noma","Kira (Blacksmithing)","Saka","Fatawa"]', 1, 'The term ''Kira'' refers specifically to blacksmithing, where metal tools are produced.', NULL, 'WAEC_Hausa_2024.json', 'a69480b050c7d3e5438a2fedf14c80d850b91ec12cca3af8fd196a61fcb7ef6b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ma''anar kalmar ''Alhamis''?', '["Monday","Tuesday","Wednesday","Thursday"]', 3, 'In the Hausa calendar, ''Alhamis'' corresponds to Thursday.', NULL, 'WAEC_Hausa_2024.json', 'a43ff0d1d793727774a197f02d6251c18d5604b6e1e81015ecbc863bf6de3e30');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'A cikin ''Tatsuniya'', wanene ya fi kowa wayo (cleverness)?', '["Gizo","Kura","Zaki","Biri"]', 0, 'In Hausa folklore (tatsuniya), Gizo (the spider) is the archetypal trickster known for his cunning.', NULL, 'WAEC_Hausa_2024.json', '17e1b2cd9b3750a1410dba07f87d06ffaa8541c0ae8e60262fb4c7304c7ff2bd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Cika gibin: ''Bello _____ Kano jiya.''', '["ya tafi","sun tafi","za ya tafi","ta tafi"]', 0, 'Since ''Bello'' is a singular male subject and the time is past (jiya), the correct marker is ''ya tafi''.', NULL, 'WAEC_Hausa_2024.json', '7cd28f69b74a4f62e04703da5e3c18873a8c66bf79f80b842bdeae7ced5a95ba');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Mene ne babban jigon wannan bayani?', '["Sana''ar Noma","Zuwan Turawa","Kayan Abinci","Ban-ruwa"]', 0, 'The entire passage focuses on the traditional and economic importance of farming (Noma).', 'Noma na daya daga cikin muhimman sana''o''in gargajiya na Hausawa. Tun kafin zuwan Turawa, Hausawa sun kasance suna dogara da noma domin samun abinci da kuma tufafi. Ana yin noma a lokacin damina da kuma lokacin rani ta hanyar ban-ruwa wanda ake kira ''noman fadamu''. Manyan kayan amfanin gona da ake nomawa sun hada da hatsi, wake, gyada, da auduga. Noma ba wai kawai abinci yake samarwa ba, har ma da kudin shiga ga kasar mu.', 'WAEC_Hausa_2024.json', '0ff75d50d9d43c7a477c536078e2987adfb62fb5444401d76cc2e5169f937a72');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Yaya ake kiran noman da ake yi a lokacin rani?', '["Noman Rani","Noman Fadamu","Noman Damina","Noman Dutse"]', 1, 'The passage explicitly states that dry-season farming using irrigation is called ''noman fadamu''.', 'Noma na daya daga cikin muhimman sana''o''in gargajiya na Hausawa. Tun kafin zuwan Turawa, Hausawa sun kasance suna dogara da noma domin samun abinci da kuma tufafi. Ana yin noma a lokacin damina da kuma lokacin rani ta hanyar ban-ruwa wanda ake kira ''noman fadamu''. Manyan kayan amfanin gona da ake nomawa sun hada da hatsi, wake, gyada, da auduga. Noma ba wai kawai abinci yake samarwa ba, har ma da kudin shiga ga kasar mu.', 'WAEC_Hausa_2024.json', '1ed36582fc61ffc2041a050775cf0ddc50e48140bf7f085cab1084442ab000c8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Mene ne amfanin auduga ga mutanen daka bayyana a passage din?', '["Don abinci","Don kera mota","Don samar da tufafi","Don magani"]', 2, 'The passage mentions that Hausa people depended on farming for food and ''tufafi'' (clothing), which auduga (cotton) provides.', 'Noma na daya daga cikin muhimman sana''o''in gargajiya na Hausawa. Tun kafin zuwan Turawa, Hausawa sun kasance suna dogara da noma domin samun abinci da kuma tufafi. Ana yin noma a lokacin damina da kuma lokacin rani ta hanyar ban-ruwa wanda ake kira ''noman fadamu''. Manyan kayan amfanin gona da ake nomawa sun hada da hatsi, wake, gyada, da auduga. Noma ba wai kawai abinci yake samarwa ba, har ma da kudin shiga ga kasar mu.', 'WAEC_Hausa_2024.json', '946f66e504bc98a545d4b43f1cb33d095cc99ff89ae4bda60dba1680d73ced14');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne amfanin gona ne ba a ambata a cikin passage din ba?', '["Wake","Gyada","Doya","Auduga"]', 2, 'The passage mentions hatsi, wake, gyada, and auduga, but does not mention ''Doya'' (Yam).', 'Noma na daya daga cikin muhimman sana''o''in gargajiya na Hausawa. Tun kafin zuwan Turawa, Hausawa sun kasance suna dogara da noma domin samun abinci da kuma tufafi. Ana yin noma a lokacin damina da kuma lokacin rani ta hanyar ban-ruwa wanda ake kira ''noman fadamu''. Manyan kayan amfanin gona da ake nomawa sun hada da hatsi, wake, gyada, da auduga. Noma ba wai kawai abinci yake samarwa ba, har ma da kudin shiga ga kasar mu.', 'WAEC_Hausa_2024.json', '4dde2e6489b976a365d5e9cc49e38937398ad6dd02a57b182436ed5fa03c1778');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanene babban jagoran sarautar gargajiya a masarautar Kano?', '["Sultan","Oba","Emir","Ooni"]', 2, 'Traditional rulers in Northern Nigeria, specifically Kano, hold the title of ''Emir'' (Sarki).', NULL, 'WAEC_Hausa_2024.json', 'b2ae6e909119b00369017ad745065b8f98124a09cdd8838dd5437f7e33b0f094');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne ne ''Bakari'' (Consonant) mai fashewa (Ejective)?', '["K''","B","D","S"]', 0, 'In Hausa phonology, K'' (k tare da lamba) is an ejective consonant, produced with high pressure.', NULL, 'WAEC_Hausa_2024.json', '0ed4362e80a70618d376ba7bb50efa6a79675b4720e0e7f4d4de88a0b7614880');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Kalmar ''Littattafai'' jam''i ne na _____.', '["Litta","Littafi","Littan","Littafe"]', 1, '''Littattafai'' is the plural form of the singular noun ''Littafi'' (Book).', NULL, 'WAEC_Hausa_2024.json', '95551e913651d9fc493a98065f71a62f152b318bfffa4672d7cf845acb2e8fd9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'A ina ake samun ''Karin Magana''?', '["Adabin Baka","Adabin Rubuce","Zane","Wasan kwaikwayo"]', 0, 'Proverbs (Karin Magana) are transmitted orally, making them part of ''Adabin Baka'' (Oral Literature).', NULL, 'WAEC_Hausa_2024.json', '63c897e32836c4d6c512fafe539bd175bac6b8c34927bc0892523957557cae20');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Mene ne ''Daidaitacciyar Hausa'' (Standard Hausa)?', '["Hausar Kano","Hausar Sakkwato","Hausar Zazzau","Hausar Katsina"]', 0, 'The Kano dialect is generally accepted as the basis for Standard Written Hausa.', NULL, 'WAEC_Hausa_2024.json', 'f0e7e042e5175dfc433f7570a939cae7de0d5ee15f81ca954410e2f12fa75274');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'A cikin lissafi, ''Dari biyar'' nawa ne?', '["100","500","1000","50"]', 1, '''Dari'' means hundred and ''Biyar'' means five, totaling 500.', NULL, 'WAEC_Hausa_2024.json', '4166516a56796617b3bbe2fb8dc3fc81636ef23aca34c9a988c6428de448ed79');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne ne sifa (Adjective) a cikin wannan jimlar: ''Ina son riga fara''?', '["Ina","Son","Riga","Fara"]', 3, '''Fara'' (white) describes the noun ''riga'', making it an adjective (sifa).', NULL, 'WAEC_Hausa_2024.json', 'f597bd79a6bb62ea6725a3e321a9d3b76c0b9e826f91dfbef41c11c1b582fa82');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Mene ne kalmar nan ''Guda'' take nufi a cikin jimlar ''Na ga guda uku''?', '["Person","Unit/Item","Group","Place"]', 1, '''Guda'' acts as a counter or unit, referring to the quantity of items.', NULL, 'WAEC_Hausa_2024.json', 'a01402e58561e876423ebafd78a122d9c6bf2001ad9647f8a54646170fcf604a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Idan mace ta haifi ''Tagwaye'', mene ne ma''anar hakan?', '["She had a girl","She had a boy","She had twins","She had triplets"]', 2, '''Tagwaye'' is the Hausa word for twins.', NULL, 'WAEC_Hausa_2024.json', 'd302b8a8ecf87d827efe62b382c76e07388110b94db69f06e13cb76dd6900539');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne ne cikin wadannan ba Fi''ili (Verb) ba ne?', '["Gudu","Cin abinci","Kyakkyawa","Kwana"]', 2, 'Gudu (run), Cin abinci (eat), and Kwana (sleep) are actions, while Kyakkyawa (beautiful) is an adjective.', NULL, 'WAEC_Hausa_2024.json', '5d6522d50e7a1ad329e7210981417bbe501d951650799e2bcb8c742b115a21aa');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ''Karin Magana''?', '["Language used by kings","Wisdom expressed in brief sentences","Long stories","Songs"]', 1, 'Karin Magana are proverbs used to convey wisdom or hidden meanings succinctly.', NULL, 'WAEC_Hausa_2024.json', '3f2ca2a370fac0486e83496590908a94dc0b884c217df958d43b69bb0791f7b2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wace rana ce take biyo bayan Lahadi?', '["Litinin","Talata","Laraba","Asabar"]', 0, 'Lahadi is Sunday; the day following it is ''Litinin'' (Monday).', NULL, 'WAEC_Hausa_2024.json', '0ad577aee940e76f53217982655048a2019442dea647f854181547901774eeab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanene ''Malam'' a cikin al''ummar Hausawa?', '["King","Teacher/Scholar","Farmer","Soldier"]', 1, '''Malam'' refers to an educated person, teacher, or religious scholar.', NULL, 'WAEC_Hausa_2024.json', '5a937f81f74bebab81dbaadcccc271ec54fe4035711f76af2653eda0c77f4021');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ma''anar ''Kayan daki'' a wurin biki?', '["Kitchen equipment","Room decorations","Bridal gifts for house setup","Food items"]', 2, 'In Hausa wedding culture, ''Kayan daki'' refers to the household furniture and utilities provided for the bride''s new home.', NULL, 'WAEC_Hausa_2024.json', '9dff409e87d523c585ad24813925401e5632c87504af59f595b182a5e313b365');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne ne wasalin nan ''i''?', '["Wasali mai fadi","Wasali mai tsayi","Wasali dunkule","Wasali na gaba"]', 3, 'The vowel ''i'' is classified as a front vowel (wasali na gaba) in Hausa phonology.', NULL, 'WAEC_Hausa_2024.json', 'c19a12ec72858375051469525e25def41441d78003cc248b75f6fe00962cd9b0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wacce dabba ce ake kira ''Sarkin dawa''?', '["Zaki","Giwa","Kura","Doki"]', 0, '''Sarkin dawa'' means ''King of the forest/bush'', which refers to the Lion (Zaki).', NULL, 'WAEC_Hausa_2024.json', 'ff846948fb30fa618054c40d63ef0307a753aa92701a12d837b90e3aa2f31c7f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene sunan mahaifin mutum a Hausa?', '["Baba","Kawu","Gwaggo","Inna"]', 0, '''Baba'' or ''Uba'' is the term for father.', NULL, 'WAEC_Hausa_2024.json', 'a66e7ad3ed9761c4f666bad53750ae5e07998b80ce892dc8a8b619da64fe79c8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne sashi na gaba (Syllable) ne ''Ma-ran-ta-wa''?', '["Biyu","Uku","Hudu","Biyar"]', 2, 'Ma-ran-ta-wa has four syllables.', NULL, 'WAEC_Hausa_2024.json', '8be5da96704f455c36574ee979e2476879921f4fb66f60642d70eb5924e0c04b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ''Inkiya''?', '["Real name","Nickname","Surname","Father''s name"]', 1, '''Inkiya'' refers to a nickname or an alias.', NULL, 'WAEC_Hausa_2024.json', '8bbe624c6d3da78bc0c73139fc86f4e4c2ba20e271daa7b4ffe4de32cd1a3726');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne ne sunan babban birnin jihar Kano?', '["Zaria","Kaduna","Kano","Gusau"]', 2, 'The capital of Kano State is Kano city.', NULL, 'WAEC_Hausa_2024.json', 'acc76596f227ffaf938671c47efcfcb7c81cea3729e0c280a42efdf440254d17');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Kammala karin maganar nan: ''Hankali .''', '["shima dadi ne","maganin dadi","dukiyarmu ce","maganin komai"]', 3, 'The proverb ''Hankali maganin komai'' means wisdom/intelligence is the cure/solution to everything.', NULL, 'WAEC_Hausa_2024.json', 'df964af1dd1e2a178cae25eb2851d98132ee17a5b0b8ab6937b5f2087768b24e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wane littafi ne Bello Kagara ya rubuta?', '["Gandoki","Shaihu Umar","Jiki Magayi","Idon Matambayi"]', 0, 'Bello Kagara is the author of the epic novel ''Gandoki''.', NULL, 'WAEC_Hausa_2024.json', 'd46813ee7e7202682fc25e33a28a9a2843df129eb0de2ed22b9a9e5746f5ce11');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Mene ne ''Wakar Gargajiya''?', '["Modern songs","Traditional songs","Political songs","School songs"]', 1, '''Wakar Gargajiya'' refers to indigenous traditional songs often accompanied by local instruments.', NULL, 'WAEC_Hausa_2024.json', '15062b0e558e006fb0f0b192ad74c0858b1744cd04cd7e89fc1e20a545b148c3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne bakari (consonant) ne ake kiran sa ''K'' dake tare da ''y''?', '["Ky","Kw","Ts","Ch"]', 0, '''Ky'' is a labialized/palatalized consonant in Hausa phonology.', NULL, 'WAEC_Hausa_2024.json', '13a69ca74838642bd34c9d19f464806018064e2710cd8e24bf56f5f9d3c4df1b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ma''anar ''Sadarwa''?', '["Transportation","Communication","Education","Health"]', 1, '''Sadarwa'' is the Hausa term for Communication.', NULL, 'WAEC_Hausa_2024.json', 'f21c0b4af3b3d0dd86d02ebaa8523ad007fdf34b3146e5171c3b8cefe75760a0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'A fannin sarauta, wanene yake biye da Sarki?', '["Waziri","Dogari","Talakawa","Sarkin Noma"]', 0, 'The ''Waziri'' acts as the Prime Minister or the highest advisor to the King (Sarki).', NULL, 'WAEC_Hausa_2024.json', 'de6679417c16ac89cfb4e3f0d86a93272a01a2ca4dd07a0ab5ecd2169504e7d7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ''Bayanau'' (Adverb)?', '["Modifier of a noun","Modifier of a verb","Connector of sentences","Action word"]', 1, '''Bayanau'' is a word that modifies a verb (Fi''ili), describing how an action is performed.', NULL, 'WAEC_Hausa_2024.json', 'c53b9b3728167a00fc56f2771f6b46ef78668fa6a5913496aeed4bbff3d61f9c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Cika wannan: '' muke nufi.''', '["Ku","Mu","Su","Ni"]', 1, 'The plural verb marker ''muke'' corresponds to the first-person plural pronoun ''Mu'' (We).', NULL, 'WAEC_Hausa_2024.json', 'ebd82bbb69ce4a5e091645a2d64c22f040e69ec3560ad61418b7b21f85765a37');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wane asali ne Hausawa suke da shi na farko?', '["Banza Bakwai","Hausa Bakwai","Fula","Tuareg"]', 1, 'The ''Hausa Bakwai'' represents the seven original Hausa city-states.', NULL, 'WAEC_Hausa_2024.json', '646a5abcb34cd695248e58cf4b28ea3bd29ab6f3c98e7866e15a2abe86d127af');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'A wanne lokaci ne ake cin ''Tuwon Suna''?', '["Marriage","Funeral","Naming Ceremony","Harvest"]', 2, '''Tuwon Suna'' is the special meal prepared during a naming ceremony.', NULL, 'WAEC_Hausa_2024.json', '68bd885fe74b9a0257132219e535b6eb57dbcb3ab97fa5215d28e0dc0f3b44cc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Mene ne ''Ami'' (Tones) a cikin Hausa?', '["Vowels","Consonants","Pitch variations (High/Low)","Numbers"]', 2, 'Hausa is a tonal language where ''Ami'' indicates the high, low, or falling pitch of a syllable.', NULL, 'WAEC_Hausa_2024.json', 'ca668bef858810862e89d0e28c881dcc2efc1a1195bdbc4c04a7ecac4e51f4ec');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne littafi ne Sir Abubakar Tafawa Balewa ya rubuta?', '["Shaihu Umar","Ruwan Bagaja","Magana Jari Ce","Gandoki"]', 0, 'The first Prime Minister of Nigeria, Sir Abubakar Tafawa Balewa, wrote ''Shaihu Umar''.', NULL, 'WAEC_Hausa_2024.json', '5c0c678a45d0e90b9a040b7ae94026a6483ca1f0bdb2c47b6208eb1c6bbc93c7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wace sana''a ce ''Saka''?', '["Fishing","Weaving","Hunting","Pottery"]', 1, '''Saka'' refers to the traditional craft of weaving clothes.', NULL, 'WAEC_Hausa_2024.json', 'e159623080829eeb82631a54a963872e4b15ba1dbaf66ad3b72f98dcca0bca06');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ma''anar ''Dan-koli''?', '["Farmer","Petty trader","Prince","Student"]', 1, 'A ''Dan-koli'' is a traditional petty trader who travels to sell small household wares.', NULL, 'WAEC_Hausa_2024.json', 'a72b570303b4e05aa62e3017a31e0dc99951f6cd9ba678ac848a28d704bfda06');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne ne sunan dabba mai wuya mai tsayi?', '["Rakumi","Rakumin Dawa (Giraffe)","Zaki","Biri"]', 1, '''Rakumin Dawa'' is the Hausa name for a Giraffe, characterized by its long neck.', NULL, 'WAEC_Hausa_2024.json', 'a0898caf3604df01dc2dad0c2762fa44e7241bf924abb646f4eb77b572374b0c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ''Jinsin miji'' (Masculine)?', '["Uwa","Kanwa","Yaya (male)","Yarinya"]', 2, 'In most contexts, ''Yaya'' (older brother) is masculine, while the others are feminine.', NULL, 'WAEC_Hausa_2024.json', 'bdb4e154c4b98a32bf22cbabf13db4737db8779a3173874abc068c6913af8e0b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne bangare ne na Sauti ake kira ''Amshi''?', '["Stress","Tone","Pause","Rhyme"]', 1, '''Amshi'' is often used interchangeably with Tone or the musical response in poetry.', NULL, 'WAEC_Hausa_2024.json', '376ebc422f9332085594e191a038a0008b886f3cc9e408a0f13b6eedce3e587e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Mene ne ma''anar ''K''ungiyar asiri''?', '["Cooperative society","Secret cult/society","Youth club","Political party"]', 1, '''K''ungiyar asiri'' refers to a secret society or cult.', NULL, 'WAEC_Hausa_2024.json', '24a666e72e800d0b64d1710dc63832cd3ce0d58de00a5a86bdbf2e700ec66ffd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wace rana ce ''Friday'' a Hausa?', '["Alhamis","Jumma''a","Asabar","Litinin"]', 1, 'Friday is called ''Jumma''a'', the holy day for Muslims.', NULL, 'WAEC_Hausa_2024.json', 'a79855d5f8574f6b50758f11fa296d20c3873a60b3eaca2120dd55617c958785');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Cika wannan: ''Ina _____ zuwa gida.''', '["so","son","se","sun"]', 1, 'The correct construction for ''I want'' is ''Ina son'' before a verb phrase.', NULL, 'WAEC_Hausa_2024.json', '55726179fc96b608c25d0daae3ebb16aa973b96e1d29bb9be68b41c8aeec8509');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ''Tatsuniya''?', '["History","Fiction/Folktale","Poetry","Law"]', 1, 'Tatsuniya refers to fictional folktales often told to children at night.', NULL, 'WAEC_Hausa_2024.json', '2c4f991d984353ed295399c475a38cbb380119fcc177b42d1210a0a211259ac1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne ne cikin wadannan wasali ne mai tsawo?', '["aa","a","u","i"]', 0, 'In Hausa orthography, doubling a vowel (e.g., ''aa'') represents a long vowel sound.', NULL, 'WAEC_Hausa_2024.json', '013b8a23d6461e030a918054850dcaef81531674d9c8c7bdd07cd335aa92aaa2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ''Karin harshe''?', '["Dialect","Grammar","Proverb","Tongue twister"]', 0, '''Karin harshe'' refers to the different dialects or variations of a language.', NULL, 'WAEC_Hausa_2024.json', 'd53f038488c0ac55ccf8590f030bcef7ed05096be43ea031023e427741e13edd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne ne siffa (Adjective) na launi (color)?', '["Dogon","Baki","Gudu","Biyar"]', 1, '''Baki'' means black, which is a color adjective.', NULL, 'WAEC_Hausa_2024.json', 'c585b0724a49839427a7fc8b08f5481c916cafff8c22e75ee1fc5eb143afa61e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ''Gishirin jimla''?', '["Noun","Verb","Particles/Conjunctions","Adverb"]', 2, 'Particles and small functional words like ''da'', ''ko'', ''ma'' are often called the ''salt'' (gishiri) of a sentence.', NULL, 'WAEC_Hausa_2024.json', 'cb232b5252b2968266bb2af816f35acb11fd2e5b1d813b1495585a2136fe56a8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'A ina ake yin sana''ar ''Fatuwa''?', '["River","Market/Long distance trade","Farm","Workshop"]', 1, '''Fatuwa'' is the traditional long-distance trading system.', NULL, 'WAEC_Hausa_2024.json', '38a8b332808637a7501a3203da30f534cec2b9f6a895237e88f85726df21962c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ''Surutu''?', '["Silence","Noise/Chatter","Song","Prayer"]', 1, '''Surutu'' refers to excessive talking or noise.', NULL, 'WAEC_Hausa_2024.json', 'c78cecc1c74b37e73f68a658de11e032158b344ce36826496b9589da65fdd25a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne ne kalmar nuni na nesa (Far demonstrative)?', '["Wannan","Wancan","Nan","Can"]', 1, '''Wancan'' means ''that one over there'', used for distant objects.', NULL, 'WAEC_Hausa_2024.json', '8cb96eb607bd86a48da7f5d5f4c903959a2719cb69cf0253dd59f4fe4117bc8b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ''Wakilin suna na mallaka'' (Possessive Pronoun)?', '["Nawa","Kai","Su","Mu"]', 0, '''Nawa'' means ''mine'', indicating possession.', NULL, 'WAEC_Hausa_2024.json', '0934f49f01ca71dd1c9bd555cfb9d8ee0db5a535a72ed2cd803ed9557ec98e0b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wace dabba ce ''Kura''?', '["Lion","Hyena","Elephant","Monkey"]', 1, '''Kura'' is the Hausa name for a Hyena.', NULL, 'WAEC_Hausa_2024.json', '46f7157a9a09e6167b8b0983329ca57e7f1efff7bb744fa11bea08b98edd6d56');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Mene ne ''Aure''?', '["Death","Marriage","Birth","Naming"]', 1, 'Aure is the legal union between a man and a woman.', NULL, 'WAEC_Hausa_2024.json', '0184ff27cb889173bf64d5bb79cc1adc5f27bc065f2dc19b5325b002a9c815ad');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ''Sana''o''i''?', '["Hobbies","Occupations/Trades","Schools","Diseases"]', 1, 'Sana''o''i refers to the various ways people earn a living (Trades/Crafts).', NULL, 'WAEC_Hausa_2024.json', 'b45919b3e2042d1af5ccb0cdc83bc637ee0785b00253c4f1bf71501b1eb1d570');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanene ya kera wannan: ''Sarkin ruwa''?', '["Head of farmers","Head of fishers","Head of smiths","Head of weavers"]', 1, 'The title ''Sarkin Ruwa'' is given to the head of the fishermen community.', NULL, 'WAEC_Hausa_2024.json', '9a7743d98e175ec2639f3fdb24a18ced6a9617de1149a828feb8a38866764972');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ''Labarin zuciya''?', '["A secret","An open news","A physical illness","A type of food"]', 0, 'In metaphorical Hausa, ''Labarin zuciya'' refers to one''s inner secrets or true feelings.', NULL, 'WAEC_Hausa_2024.json', '468311b26af438ca2fef1e4738b4bf08bf266e48de23095c3a5a37046e4a9f08');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Wanne ne sunan azuzuwan Hausa?', '["A, B, C","Bakandamiya","Lamba","Daidaitacciya"]', 3, 'Daidaitacciyar Hausa refers to the standard academic form of the language.', NULL, 'WAEC_Hausa_2024.json', 'd525348d4a488f4cae93c33f0db672ae362445b2a4c507d9d86cd7bb3b91d250');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2024, NULL, 'Menene ''Amshi'' a cikin waka?', '["Title","The ending of a line/refrain","The melody","The singer''s name"]', 1, 'Amshi refers to the refrain or the response provided by the backup singers.', NULL, 'WAEC_Hausa_2024.json', '28198cf6958a1fe69b77646cc3334965b7878c83ad4098d21926e290e1e34ee9');
