INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2025, NULL, 'Menene ''One''?', '["Daya","Biyu","Uku","Hudu"]', 0, NULL, NULL, 'WAEC_Hausa_2025.json', 'a3a4215ffd3ba50f4539defa8b4c74e72c3112401d7b1199d1b2e7eb67d0b6af');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2025, NULL, 'Menene ''Two''?', '["Biyu","Daya","Uku","Hudu"]', 0, NULL, NULL, 'WAEC_Hausa_2025.json', '2260ad47c1e4deca3c92c742524a1114be723f899b95a126a04b2f1510a10698');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2025, NULL, 'Menene ''Three''?', '["Uku","Biyu","Daya","Hudu"]', 0, NULL, NULL, 'WAEC_Hausa_2025.json', '23c2d9404909a44f4c16edf3a3673e5f64e4083c3d8113035f9c497ee427311d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Hausa', 2025, NULL, 'Menene ''Four''?', '["Hudu","Uku","Biyar","Shida"]', 0, NULL, NULL, 'WAEC_Hausa_2025.json', '0c24b416debad1e77387b8a50504d4f5b76a22264b3189ee4905fd4611208a3e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Nok culture, discovered in central Nigeria, is famous for its early mastery of _____.', '["bronze casting","iron smelting","weaving","gold mining"]', 1, 'Nok culture is globally recognized for being one of the earliest West African societies to develop iron-smelting technology and terracotta sculptures around 1000 BC.', NULL, 'WAEC_History_2024.json', 'c311dba1b107c9def3b2cbf01b1f6611030e2e33499133d1d72a4eb60fa1d981');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'In the pre-colonial Oyo Empire, the council of seven kingmakers was known as the _____.', '["Uzama","Oyomesi","Ogboni","Ilari"]', 1, 'The Oyomesi was a powerful council of seven chiefs led by the Bashorun, responsible for selecting the Alaafin and checking his powers.', NULL, 'WAEC_History_2024.json', '05d549508a19aeb39071ce4c1abb73ca3bc95c88b7b695ca1855ac5fa2fbc3b6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'Which of the following was the primary commodity of the Trans-Saharan trade in the Sudanic region?', '["Pepper","Salt","Ivory","Rubber"]', 1, 'Salt was a crucial commodity brought from the Sahara (like Bilma and Taodeni) to the Sudan in exchange for gold.', NULL, 'WAEC_History_2024.json', 'ab79ba5e25e6d2ec5c3ac7c41c292e3e8abb6a44494a4c0065cb136c5c7179fa');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The leader of the 1804 Jihad in Hausaland was _____.', '["Shehu El-Kanemi","Usman dan Fodio","Nana Asma''u","Sultan Bello"]', 1, 'Usman dan Fodio, a Fulani scholar, launched the Jihad in 1804 to reform Islamic practice and overthrow the corrupt Hausa kings.', NULL, 'WAEC_History_2024.json', '4c15c8e3bcc7f4cf1c7dd24e2f19b0d5c50ad9e6c93e0aeece2c3997da0dc329');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Benin Empire became world-famous for its artistic works made of _____.', '["Marble","Terra-cotta","Bronze","Wood"]', 2, 'The Benin bronzes (actually brass) were created using the ''lost-wax'' casting method and represent high levels of pre-colonial craftsmanship.', NULL, 'WAEC_History_2024.json', '1f845fefaeaac53a2a7b46fda548f4e44d2d40925451ec8d82686cca117f8967');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The first European power to establish a permanent presence on the Nigerian coast was _____.', '["Britain","France","The Netherlands","Portugal"]', 3, 'The Portuguese were the first Europeans to reach the Bights of Benin and Biafra in the late 15th century, establishing trade in ivory and slaves.', NULL, 'WAEC_History_2024.json', 'e21272221cd8e9a1a9da8a9b2b52ffbfc570afb6a29f2c9855ed0fb0a8dd0ce1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The city of Timbuktu became a major center of Islamic learning under the _____ Empire.', '["Ghana","Mali","Asante","Dahomey"]', 1, 'During the reign of Mansa Musa in the Mali Empire, Timbuktu flourished as a center of scholarship, attracting students from across the Muslim world.', NULL, 'WAEC_History_2024.json', 'e76eebb9df20568b0c5ee00450507546ea6206446e4fa444f814aa8647f84b20');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The main reason for the British annexation of Lagos in 1861 was to _____.', '["promote Christianity","establish a colony for freed slaves","suppress the slave trade and protect palm oil trade","fight the French"]', 2, 'Britain annexed Lagos to effectively stop the trans-atlantic slave trade and secure the route for ''legitimate commerce'' like palm oil.', NULL, 'WAEC_History_2024.json', '249f62bdb212ed45c33e5f4dcc98bb5dd9f381ac890b3db897b7537f7fb52e41');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Jukun kingdom of Kwararafa was most noted for its frequent military raids against _____.', '["The Oyo Empire","The Hausa States","Benin","The Igbo"]', 1, 'In the 16th and 17th centuries, the Kwararafa kingdom (Jukun) was a formidable power that frequently raided Hausa states like Kano and Katsina.', NULL, 'WAEC_History_2024.json', '373da811c15c1537d21890cd98a75fff09ecd8d7ff47523045f659769211a06a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ''Long Juju'' of Arochukwu served as _____ in the pre-colonial Eastern Nigeria.', '["a military fort","a supreme judicial oracle","a market square","a training school for chiefs"]', 1, 'The Long Juju (Ibini Ukpabi) oracle allowed the Aro people to dominate trade and settle disputes across Igboland and beyond.', NULL, 'WAEC_History_2024.json', '148781c97aa84d279e23e8bd230a879faa50bac7d0351438ea5f35c9e62bb804');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Berlin Conference of 1884-1885 was significant because it _____.', '["ended the slave trade","formally partitioned Africa among European powers","declared war on Ethiopia","granted independence to Liberia"]', 1, 'The Berlin Conference, hosted by Bismarck, established the ''effective occupation'' principle for the European scramble and partition of Africa.', NULL, 'WAEC_History_2024.json', '1c42be73e49483d3b95f9c0bbee61e1473c936d79aecc8694623a679c90bbd4e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Amalgamation of Northern and Southern Nigeria in 1914 was performed by _____.', '["Sir Hugh Clifford","Lord Frederick Lugard","Sir Arthur Richards","John Macpherson"]', 1, 'Lord Lugard merged the two protectorates into a single entity primarily for administrative convenience and financial reasons.', NULL, 'WAEC_History_2024.json', '69760ea0ddc61f77f778742f2b9b56d1d7bca71a21d67fb60e1312772f15456a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The strategy of ''Indirect Rule'' was most successful in the _____ of Nigeria.', '["Western Region","Eastern Region","Northern Region","Delta Region"]', 2, 'Indirect Rule worked best in the North because of the existing centralized political structure of the Sokoto Caliphate and the Emirate system.', NULL, 'WAEC_History_2024.json', '2ec0041ebf41a1d175fa4d31a6aeeef79083fc401ad087603f0c360492f6c981');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The first Nigerian political party, the NNDP, was founded in 1923 by _____.', '["Herbert Macaulay","Nnamdi Azikiwe","Obafemi Awolowo","Ahmadu Bello"]', 0, 'Herbert Macaulay, often called the ''Father of Nigerian Nationalism,'' founded the Nigerian National Democratic Party to contest elections in Lagos.', NULL, 'WAEC_History_2024.json', '4f3ba6484e77221630aebc4efb0808ba5db527f3bc16cdbf0627efa037e0477c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The 1929 Aba Women’s Riot was primarily caused by the _____.', '["arrest of King Jaja","introduction of direct taxation on women","abolition of slavery","lack of schools"]', 1, 'The riot (Ogu Umunwanyi) was a protest by Igbo women against the rumor that the colonial government intended to tax women.', NULL, 'WAEC_History_2024.json', '88c51ff27015ea905757e1582fa4a09053c578f6e9dd3a2d2b15b0b8383696e2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Clifford Constitution of 1922 was notable for introducing the _____ in Nigeria.', '["federal system","elective principle","ministerial system","unicameral legislature"]', 1, 'For the first time in British West Africa, the Clifford Constitution allowed for the election of representatives into the Legislative Council.', NULL, 'WAEC_History_2024.json', 'f9a80399aa2a62353bc5de96cc6fe965a277760935101b172b48a34227fe4a52');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Richards Constitution of 1946 was criticized by nationalists because it _____.', '["gave too much power to Azikiwe","divided Nigeria into three regions without consultation","abolished the office of the Governor","moved the capital to Abuja"]', 1, 'Nationalists felt the constitution was ''arbitrary'' as it was drafted without consulting Nigerian leaders, although it introduced regionalism.', NULL, 'WAEC_History_2024.json', 'ede7f2a6eba891f350406dbd3799d00cf679728e1242868fa0e7921cf3b06311');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The primary cause of the collapse of the Old Oyo Empire was _____.', '["the lack of a standing army","internal power struggles and the revolt of Afonja","the invasion by the British","the lack of trade routes"]', 1, 'Internal friction between the Alafin and the Oyomesi, coupled with the rebellion of Afonja in Ilorin, weakened the empire and led to its fall.', NULL, 'WAEC_History_2024.json', 'a5e3b65dcc37a0ac8e8a37480a7d38c04cb3bb3e7499a4282a4e7088c3ed08f7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'King Jaja of Opobo was exiled to the West Indies in 1887 because he _____.', '["refused to pay taxes","interfered with British trade in the hinterland","murdered a British consul","was a slave trader"]', 1, 'Jaja was a threat to British economic interests in the Niger Delta as he insisted on his right to trade directly with European firms without middlemen.', NULL, 'WAEC_History_2024.json', '155a479e660756df8dce890d762ebfa242c157d559d1da8ae5eae686a3e94f4f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Macpherson Constitution of 1951 is often described as _____.', '["unitary","quasi-federal","republican","military-led"]', 1, 'It was called quasi-federal because it provided for a central legislature and regional houses, but the center still held significant power over the regions.', NULL, 'WAEC_History_2024.json', 'c17e26d98ad8b0fb8b2ec2d4c7c36ea7a085530c6b15c03e8a1790ef02a29154');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'Nigeria became a Republic in the year _____.', '["1960","1963","1966","1970"]', 1, 'While independence was gained in 1960, Nigeria became a Federal Republic in 1963, replacing the Queen as Head of State with a President.', NULL, 'WAEC_History_2024.json', '67d09ab7c20c3ccea90f26889bf8742750429ab7463dd627a8bf3b444b02ace5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The first military coup d''état in Nigeria occurred on _____.', '["January 15, 1966","July 29, 1966","July 29, 1975","December 31, 1983"]', 0, 'The January 1966 coup, led by Major Nzeogwu and others, ended the First Republic and resulted in the deaths of several top politicians.', NULL, 'WAEC_History_2024.json', '4ebb39cdd897aa0a926e78a7d66bc5e960026040e5a1c5f52975b38e9e306301');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'Which of the following bodies was formed in 1975 to promote economic integration in West Africa?', '["OAU","ECOWAS","NEPAD","SADC"]', 1, 'The Economic Community of West African States (ECOWAS) was established via the Treaty of Lagos to foster economic cooperation among member nations.', NULL, 'WAEC_History_2024.json', '5ec91c5d8af92bc3c058142feb518163fae8300f5936c66bdda5b083dd35fb8e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ''Warrant Chief'' system was introduced by the British in _____.', '["The North","The South-West","The South-East","Lagos Colony"]', 2, 'Since the Igbo had an acephalous (decentralized) society, the British created ''Warrant Chiefs'' to facilitate indirect rule, which led to significant local resentment.', NULL, 'WAEC_History_2024.json', '46c2081fd1fedc1170e2a55c475edca6931655ab10a9dc9097fb8f2453b4e7c7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The legendary founder of the Kanem-Borno Empire was _____.', '["Idris Alooma","Mai Dunama","Sayf ibn Dhi Yazan","El-Kanemi"]', 2, 'Historical traditions attribute the founding of the Sefuwa dynasty in Kanem-Borno to the Yemeni hero Sayf ibn Dhi Yazan.', NULL, 'WAEC_History_2024.json', '83863eeb6f6acc010d38d2b2ae2f9b5630a8594ec56e7e800a4833439dd186ca');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'Idris Alooma of Borno is remembered for his military reforms, which included the use of _____.', '["chariots","Turkish musketeers","war elephants","naval ships"]', 1, 'Idris Alooma imported firearms and trained musketeers from the Ottoman Empire, giving his army a superior advantage in the 16th century.', NULL, 'WAEC_History_2024.json', '4292dccc047074a0d67164ffc738fb4242226c74e378b4e9103756eb38e087fb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Sagrenti War of 1874 was fought between the British and the _____.', '["Oyo Empire","Asante Kingdom","Sokoto Caliphate","Zulu Kingdom"]', 1, 'The Sagrenti War (named after Garnet Wolseley) was one of the Anglo-Asante wars in present-day Ghana, resulting in the burning of Kumasi.', NULL, 'WAEC_History_2024.json', '954518a5b63a2a61311087dda73c9eea969902936c69dde8a8d8078c72ef8034');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The first indigenous Governor-General of Nigeria was _____.', '["Ahmadu Bello","Nnamdi Azikiwe","Obafemi Awolowo","Abubakar Tafawa Balewa"]', 1, 'Dr. Nnamdi Azikiwe took over from Sir James Robertson in 1960 as Governor-General, representing the Queen.', NULL, 'WAEC_History_2024.json', '9b6634c6edf6a72d40384d3b38b9084949111ef7378818daa9c047b88171afba');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'Which conference finalizes the path to Nigeria''s independence?', '["The Berlin Conference","The London Constitutional Conferences","The Casablanca Conference","The Bandung Conference"]', 1, 'The London conferences (1953, 1957, 1958) settled the issues of regionalism, the minority question, and the date for independence.', NULL, 'WAEC_History_2024.json', '22def7c5036ff9a75789b3e54e471c328317b0a03939d4d918cc0ce03bee609e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The primary role of the ''Ogboni'' society in many Yoruba kingdoms was _____.', '["military training","trading and commerce","checking the powers of the Alaafin and Oyomesi","farming"]', 2, 'The Ogboni was a secret cult of elders that played a judicial role and balanced the power between the Alafin and the executive chiefs.', NULL, 'WAEC_History_2024.json', '42044171c0212ee1f05e9d3a302f82de7de14655498cd6b78454e10fb0b04260');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ''Manila'' was a form of _____ used in pre-colonial West African trade.', '["clothing","currency","weapon","food"]', 1, 'Manillas were C-shaped metal bracelets (usually copper or brass) that served as a dominant currency in the Bight of Benin and Biafra.', NULL, 'WAEC_History_2024.json', '07c80f87422b0dfb9d0df6f0a00c65c35e8dfaf2e6f4f19db6f86ceb321bbdfb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The most significant consequence of the abolition of the Trans-Atlantic Slave Trade was the _____.', '["industrial revolution","rise of ''legitimate'' trade in palm oil","end of wars in Africa","colonization of Ethiopia"]', 1, 'As the slave trade ended, West African economies shifted to exporting raw materials like palm oil, cocoa, and groundnuts to meet European industrial needs.', NULL, 'WAEC_History_2024.json', '6ae41d7b3a1732b601ac6531fa32f648ae5c800f64e3dd1ba744ba34cf34cd8c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The leader of the National Congress of British West Africa (NCBWA) was _____.', '["Casely Hayford","Herbert Macaulay","Blaise Diagne","Edward Blyden"]', 0, 'Casely Hayford of Ghana led the NCBWA, which pushed for reforms and greater participation of educated Africans in colonial government.', NULL, 'WAEC_History_2024.json', 'cd8dbf6fd7378cd855a97d758c77b051d30df26c225c7d747f66d9f9f6e77c2d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Lyttleton Constitution of 1954 is significant because it _____.', '["introduced the first prime minister","formally established a federal system of government","annexed Lagos to the West","abolished the regions"]', 1, 'The Lyttleton Constitution is regarded as the ''Federal Constitution'' because it gave substantial autonomy to the regions and created a federal structure.', NULL, 'WAEC_History_2024.json', 'd9b28f83eb0de55e2728a4dcc4d30cfa90beff0c3bc6c6f80b2ea06a05a7501f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Royal Niger Company was granted a charter in 1886 to _____.', '["spread Christianity","administer and trade in the Niger territories","build railways","stop the French in Dahomey"]', 1, 'The charter gave George Goldie’s company the power to govern the Niger basin on behalf of Britain until it was revoked in 1900.', NULL, 'WAEC_History_2024.json', 'bb29710ffb54df13df171eaa99c9dadfaf98c72f9b6a28d03ce1b7e4f22ae556');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The main objective of the 19th-century Christian missions in Nigeria was _____.', '["to support British military","to evangelize and introduce ''civilization'' through education","to hunt for gold","to build factories"]', 1, 'Missionaries like the CMS and Hope Waddell aimed to convert Africans and promote western education as part of the ''Bible and Plough'' policy.', NULL, 'WAEC_History_2024.json', 'b5463426fc64cf5b7b2d7a593d767889989d3bfda39ca2eac751054b04e49b32');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'Who was the ''Black Prophet'' that led the Sokoto Jihad against the Hausa rulers?', '["Usman dan Fodio","Mohammed Bello","Abdullahi dan Fodio","Nana Asma''u"]', 0, 'Usman dan Fodio is the central figure of the 1804 Jihad, though he was a scholar/reformer rather than a ''prophet'' in the Islamic sense.', NULL, 'WAEC_History_2024.json', 'da2e580510d7cadeb5573df65bb7ecb08734c0390ec26313d9f3f55e60629ff3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ancient city-state of Kano became the leading commercial center in Hausaland because of its _____.', '["gold mines","leather and textile industries","naval power","ivory trade"]', 1, 'Kano was famous for its ''Kano Cloth'' and leather works, making it the ''metropolis of the Sudan'' in the Trans-Saharan trade.', NULL, 'WAEC_History_2024.json', 'eca61b732e3a46d107a4ac403c27462e431dbf3d08bc04fd5bd8e07b08b6356a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Fulani Empire was divided into two administrative sectors with headquarters at _____.', '["Kano and Katsina","Sokoto and Gwandu","Zaria and Bauchi","Ilorin and Bida"]', 1, 'Usman dan Fodio divided the administration between his son Mohammed Bello (Sokoto) and his brother Abdullahi (Gwandu).', NULL, 'WAEC_History_2024.json', 'c9de3739bae4c98c7dacc1c133a29d1e382b1aa84c169ac2c634b79824f51021');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The first Nigerian to be appointed a Bishop of the Anglican Church was _____.', '["Samuel Ajayi Crowther","Henry Townsend","Hope Waddell","Thomas Bowen"]', 0, 'Crowther, a former slave, was consecrated in 1864 as the first African Bishop of the Niger Territory.', NULL, 'WAEC_History_2024.json', 'add9f7cda4863b7294a63369aa5bb7ae9ac509d4c4a0096eb0e437df9e3612e0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The major reason for the ''Scramble for Africa'' by European powers was _____.', '["overpopulation in Europe","economic need for markets and raw materials","the desire to end tribal wars","curiosity about African geography"]', 1, 'The Industrial Revolution in Europe created a desperate need for secure sources of raw materials and markets for finished goods.', NULL, 'WAEC_History_2024.json', '248fce6e99eba5e1ba5dff7d47b1d3a4967ad2894fc938f5f40bf716770eb070');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Indirect Rule system failed in Southeastern Nigeria primarily because _____.', '["the Igbo were too rebellious","there were no centralized traditional rulers like Emirs","the people were Christians","the soil was poor"]', 1, 'The decentralized nature of Igbo society (acephalous) meant that the British creation of ''Warrant Chiefs'' was artificial and lacked traditional legitimacy.', NULL, 'WAEC_History_2024.json', 'f1102886000174f61af98c5e079881427d1133359305ce1afd6b74acf6b0bc8c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ''Satiru Rebellion'' of 1906 was a challenge against _____.', '["The Sokoto Caliphate","British colonial rule in Northern Nigeria","The French in Niger","Usman dan Fodio"]', 1, 'The Satiru uprising near Sokoto was a Mahdist-inspired revolt against the British occupation and their Fulani allies.', NULL, 'WAEC_History_2024.json', 'fe486b506e7ababea165327d5238ff55a493e64f6d6ba0a3e8296d00afd86f78');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ''Willink Commission'' of 1957 was set up to _____.', '["investigate the cause of the Aba riot","address the fears of minority groups in Nigeria","draft the independence constitution","split the Northern region"]', 1, 'The commission concluded that while minorities had genuine fears of domination by the majority tribes, new states should not be created before independence.', NULL, 'WAEC_History_2024.json', 'c210f662e969d80d32a90b36f54d197ac27f179635689688fe19f54931f441cb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'Nigeria''s first Prime Minister was _____.', '["Nnamdi Azikiwe","Ahmadu Bello","Abubakar Tafawa Balewa","Obafemi Awolowo"]', 2, 'Balewa, from the NPC, led the government at the center from 1957 until the 1966 coup.', NULL, 'WAEC_History_2024.json', '38b7dfa48b98ab4511a1a7a7b8b0128ee5c347759440f79bd8ca22ae292379b9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ''Operation Wetie'' in Western Nigeria (1965) was a period of _____.', '["agricultural boom","political violence and arson","massive rainfall","religious revival"]', 1, 'Following the rigged Western Region elections of 1965, widespread violence broke out where political opponents were doused in petrol and set ablaze.', NULL, 'WAEC_History_2024.json', 'f6a24293da8d627d842b658ef8e73afd421a2f9a772178fb7738f804de505105');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Nigerian Civil War (1967–1970) was triggered by _____.', '["the discovery of oil","the secession of the Eastern Region as ''Biafra''","a religious dispute","the invasion by Cameroon"]', 1, 'General Odumegwu Ojukwu declared the Republic of Biafra in May 1967 following massacres of Igbos in the North and political instability.', NULL, 'WAEC_History_2024.json', '11cbb6909679a991cf04ff0fe3f593bdb1ab30815e69c6cf161acefb63f965a9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The OAU (Organization of African Unity) was founded in 1963 in _____.', '["Lagos","Accra","Addis Ababa","Cairo"]', 2, 'Ethiopia''s capital became the permanent home of the OAU, which aimed to promote unity and end colonialism in Africa.', NULL, 'WAEC_History_2024.json', '6823884f335cde7e2ec94598f71d37236743c68feb4c192c3b67f1e305139ddd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ''Apartheid'' system in South Africa was officially dismantled in _____.', '["1960","1976","1990-1994","2000"]', 2, 'Following the release of Nelson Mandela and negotiations, the first multi-racial elections were held in 1994.', NULL, 'WAEC_History_2024.json', 'e31bd672a325ed591bf64c18776122da297df3943f3dd2b0bd49a9b06e30376c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Trans-Saharan trade route connected West Africa primarily with _____.', '["North Africa and the Mediterranean","The Americas","India","Western Europe"]', 0, 'The routes across the desert linked West African kingdoms with North African cities like Fez, Tunis, and Cairo.', NULL, 'WAEC_History_2024.json', '85316f89cd819afb1d84c8e136921dbe361f99a85419fb90ca181fc50ad58545');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ''Golden Stool'' is a sacred symbol of the _____.', '["Benin Empire","Asante Kingdom","Wolof Empire","Oyo Empire"]', 1, 'Legend says the Stool descended from the sky into the lap of Osei Tutu, symbolizing the unity and soul of the Asante nation.', NULL, 'WAEC_History_2024.json', '60050121cf13881ad7259f071ba8379447ca3d7f80534e76be587b676709dc4f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The principal architect of the Asante Empire was _____.', '["Osei Tutu","Opoku Ware","Prempeh I","Yaa Asantewaa"]', 0, 'Supported by the priest Okomfo Anokye, Osei Tutu unified the Asante clans into a powerful empire.', NULL, 'WAEC_History_2024.json', 'f0f9a223838b21dc78fafedf22d26f7ab5b996eb628b9c05095bae87c52614ac');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The kingdom of Dahomey was known for its unique military unit of _____.', '["heavy cavalry","female warriors (Amazons)","mercenaries from Europe","camels"]', 1, 'Dahomey’s ''Mino'' (our mothers) were an elite female military regiment that played a major role in its 18th and 19th-century wars.', NULL, 'WAEC_History_2024.json', 'ad2d601dedfd1964fd966b8ae6dae3120f49772c2f7c280e69405302bdebd03a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The 1851 bombardment of Lagos was carried out by the British to remove _____.', '["King Jaja","Oba Kosoko","Oba Akintoye","Oba Overami"]', 1, 'Kosoko supported the slave trade; the British ousted him and installed the pro-British Akintoye.', NULL, 'WAEC_History_2024.json', '894be948a780098d2f714d4f65ab238b1c0447a17a669516dffb7780e1cbd8a2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ''Nationalism'' in Nigeria after World War II was intensified by _____.', '["the return of educated veterans and the Atlantic Charter","the fall of the Berlin Wall","the spread of Communism","the discovery of iron ore"]', 0, 'West African soldiers returned with global awareness, and the Atlantic Charter''s promise of self-determination inspired the push for independence.', NULL, 'WAEC_History_2024.json', 'f4da5202ceb3af553ce5638572e1319f582c306c287b9214d90b00d590301751');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ''Aro'' people dominated the slave trade in Eastern Nigeria by using the _____.', '["Royal Niger Company","Ekpe Society and the Long Juju","Hausa cavalry","steamships"]', 1, 'The Aro network leveraged their oracle and secret societies to control trade routes and supply slaves to the coast.', NULL, 'WAEC_History_2024.json', '30c0aa0b6fe022037aa00107445f31bf9f4d2a48c5d2dfd7c50d4a22b98abdd7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The head of the government in the 1963 Constitution was the _____.', '["President","Prime Minister","Queen","Supreme Court Justice"]', 1, 'Although Nigeria became a republic, it retained the Westminster system where the President (Azikiwe) was a ceremonial head and the PM (Balewa) held executive power.', NULL, 'WAEC_History_2024.json', '1b9401195ff349e7a3e5d333b5197d3734458072767ae23cfd24bced9704dfc2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The first capital of Nigeria was _____.', '["Abuja","Calabar","Lagos","Lokoja"]', 2, 'Lagos served as the seat of government from the colonial era until the capital was moved to Abuja in 1991.', NULL, 'WAEC_History_2024.json', 'bd82e381ef8f529b517a2ce0e6c1a7c6f0d918c8cafcf2c0af3e9457a3e1a1cc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ''Zikist Movement'' was an auxiliary of the _____ party.', '["NPC","AG","NCNC","NEPU"]', 2, 'The Zikist Movement was the radical youth wing of the NCNC, advocating for ''militant'' nationalism and the ideals of Nnamdi Azikiwe.', NULL, 'WAEC_History_2024.json', '408dff0794b475b47fd417f401e7204a786678d82bdaaffc1b6cc3aa4866c45a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'Which empire was destroyed by the British Punitive Expedition of 1897?', '["Sokoto","Benin","Oyo","Kanem-Borno"]', 1, 'The expedition led to the capture of Oba Ovonramwen and the looting of the famous Benin Bronzes.', NULL, 'WAEC_History_2024.json', '41506955f00dd180ea21661f640cdcb4bd16f0a27c000c3c897676b9a19ca975');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ''Bula Matari'' (Breaker of Rocks) was the nickname given to _____.', '["Frederick Lugard","Henry Morton Stanley","Cecil Rhodes","George Goldie"]', 1, 'Stanley earned this name in the Congo for his use of force and road-building techniques during colonial exploration.', NULL, 'WAEC_History_2024.json', 'c939cc31af3b4b347e45f141f7ada931a2b7e461c105c2e1a5fc5b3d179c4a11');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Jukun people established their capital at _____.', '["Wukari","Ngazargamu","Ile-Ife","Kumbi Saleh"]', 0, 'Wukari remains the spiritual and traditional headquarters of the Jukun (Kwararafa) kingdom.', NULL, 'WAEC_History_2024.json', '218624542581608e899f2021546129e8501d4122ee66d58f3fda078118392d73');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ''Dahomey Gap'' is a geographical feature that influenced _____.', '["the spread of Islam","the isolation of the forest kingdoms","the ease of movement for savannah armies","the flow of the Nile"]', 2, 'The gap in the West African forest allowed savannah states like Oyo to use cavalry closer to the coast than in other regions.', NULL, 'WAEC_History_2024.json', '55a53e0b78e6d638d5fec10904669686cd94f867235a3d8040df45ae33b48880');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The 19th-century Yoruba Civil Wars were largely caused by _____.', '["the collapse of Old Oyo and the struggle for power","the invasion by the Portuguese","the fight against Christianity","boundary disputes with Benin"]', 0, 'Following the fall of Oyo, city-states like Ibadan, Abeokuta, and Ijaye fought for over 50 years for dominance (e.g., the Kiriji War).', NULL, 'WAEC_History_2024.json', 'b31c6b84cfc25b8eeda71f8b5cefc8c6fce61d32c403a9b9267f8aacf810cfbf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The Nigerian leader who introduced the ''Indigenization Decree'' (1972) was _____.', '["Murtala Muhammed","Yakubu Gowon","Olusegun Obasanjo","Shehu Shagari"]', 1, 'General Gowon''s decree aimed to give Nigerians greater control of the economy by restricting certain businesses to indigenous owners.', NULL, 'WAEC_History_2024.json', '3d11af9bd621752002a02d9c51c727495ff3112324fd3bb11116ee35e16d3ffc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'Which country was the first in Sub-Saharan Africa to gain independence from colonial rule?', '["Nigeria","Ghana","Kenya","Senegal"]', 1, 'Under Kwame Nkrumah, Ghana (formerly the Gold Coast) gained independence from Britain in 1957.', NULL, 'WAEC_History_2024.json', 'bb62d617c68f933a08a8af249ab85d8121bcdc4ee483a425ed99a01c49fccd69');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ''Mancala'' game and the decimal system in West Africa are often cited as evidence of _____.', '["European influence","Indigenous mathematical and social complexity","Arab conquest","Alien intervention"]', 1, 'Such cultural developments demonstrate that African societies had advanced social and mathematical systems long before outside contact.', NULL, 'WAEC_History_2024.json', '6be8a25aeaaa3c69c936f43b8d98c83ce4399e382d2cad6ca38e72751cb9000f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The first University College in Nigeria was established in 1948 at _____.', '["Lagos","Nsukka","Ibadan","Zaria"]', 2, 'The University College, Ibadan (initially affiliated with the University of London) was the premier higher education institution in Nigeria.', NULL, 'WAEC_History_2024.json', '50366c6e0dfe6ad761845b848514e75b6080b0801e0cba63249ba3bb82952349');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The policy of ''Assimilation'' was used in Africa by _____.', '["Britain","France","Portugal","Germany"]', 1, 'France initially sought to turn their African subjects into ''Black Frenchmen'' by teaching them French language, culture, and law.', NULL, 'WAEC_History_2024.json', 'bd6088fc3cec6ac709c4deaa9c08508694b323601106050941bdfe369ed6ef81');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2024, NULL, 'The ''Treaty of Union'' (1961) involving Nigeria, Ghana, and Guinea was an early attempt at _____.', '["Pan-Africanism","Colonial defense","Economic slavery","Religious alliance"]', 0, 'Leaders like Nkrumah and Azikiwe were strong proponents of Pan-Africanism, seeking to unite newly independent African states.', NULL, 'WAEC_History_2024.json', '653181b1f9c5e87c50015b96e7c75b7723a4b9a91b4687eb6641edcd107dc160');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2025, NULL, 'The Amalgamation of Northern and Southern Nigeria took place in:', '["1914","1900","1960","1963"]', 0, NULL, NULL, 'WAEC_History_2025.json', '67d8d65ef88532be641833daed8790f1495b8a295c98ea1190c038134bf3da52');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2025, NULL, 'The first Prime Minister of Nigeria was:', '["Tafawa Balewa","Nnamdi Azikiwe","Ahmadu Bello","Obafemi Awolowo"]', 0, NULL, NULL, 'WAEC_History_2025.json', 'ee34510bf1090582f3c8aead46e9234fdeeb1deb0dd879dbcea0e3326f16805f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2025, NULL, 'Nigeria became a Republic in:', '["1963","1960","1979","1999"]', 0, NULL, NULL, 'WAEC_History_2025.json', '300679e57af28cc971b6a17aee4032440ac2a694979fe1c0d899c9bee536f88b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2025, NULL, 'The Sokoto Caliphate was founded by:', '["Usman Dan Fodio","El-Kanemi","Queen Amina","Jaja of Opobo"]', 0, NULL, NULL, 'WAEC_History_2025.json', '88c212c2cbe455a3c47dfd3bb592a2fbcb4b01b3eca656704d2355ab7e066a0c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2025, NULL, 'The ancient Benin Kingdom is famous for:', '["Bronze casting","Gold mining","Iron smelting","Pyramids"]', 0, NULL, NULL, 'WAEC_History_2025.json', '213878301c22491bc8c54858aa5d759a9c33ecaee2d2a69176ade0bba1770cf6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2025, NULL, 'Who was the first Governor-General of Nigeria?', '["Lord Lugard","Sir Hugh Clifford","Arthur Richards","John Macpherson"]', 0, NULL, NULL, 'WAEC_History_2025.json', '3c0bd70f5f64b414fb6e6316597a496c3644d613f3b28ae375bff112c2429eb2');
