INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'History', 2025, NULL, 'Kanem-Borno empire was located around:', '["Lake Chad","River Niger","Atlantic Ocean","Sahara"]', 0, NULL, NULL, 'WAEC_History_2025.json', '68f1b2ec0f1763969736a5fe017a9a8fd6e8cf803f46225cfe3fc0510fe36bee');
