INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The first Surah of the Glorious Qur''an is known as _____.', '["Al-Baqarah","Al-Ikhlas","Al-Fatihah","Al-Nasr"]', 2, 'Surat Al-Fatihah is the opening chapter of the Qur''an and is essential in every unit of the Muslim prayer (Salat).', NULL, 'WAEC_IRS_2024.json', 'f06cb7a2a351dab97ff0ffe2cd871babfdb95b0cc2adee30531d0178322c08b4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The Qur''an was revealed to Prophet Muhammad (SAW) over a period of approximately _____ years.', '["10","13","23","40"]', 2, 'The revelation began when the Prophet was 40 and ended shortly before his death at 63, totaling 23 years (13 in Makkah and 10 in Madinah).', NULL, 'WAEC_IRS_2024.json', '01178e141351bf6b2cf67cca483ec2b047fbd8bce85612a2464d951ed289fc6f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The primary source of Islamic Law (Shari''ah) is the _____.', '["Hadith","Qur''an","Ijma","Qiyas"]', 1, 'The Qur''an is the ultimate and most authoritative source of guidance in Islam, followed by the Sunnah/Hadith.', NULL, 'WAEC_IRS_2024.json', '1faa22dff82334e35f8b60b744d035c40a035f50dfed6fe7566481656caceb8a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'A Hadith that is attributed directly to Allah but phrased by the Prophet (SAW) is called _____.', '["Hadith Sahih","Hadith Qudsi","Hadith Mutawatir","Hadith Da''if"]', 1, 'Hadith Qudsi (Sacred Hadith) contains meanings from Allah expressed in the Prophet''s words, distinguished from the Qur''an which is Allah''s literal word.', NULL, 'WAEC_IRS_2024.json', 'b2298aac40b0b7b614e27c2e6c8ca5a26e9f9404e37c094f113945477943a52d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ''Year of Elephant'' (Amul-Fil) is significant in Islamic history because it was the year _____.', '["the Prophet migrated to Madinah","the Prophet was born","the Ka''bah was built","the first battle of Islam occurred"]', 1, 'Prophet Muhammad (SAW) was born in Makkah in 570 CE, the same year Abrahah attempted to destroy the Ka''bah with an army of elephants.', NULL, 'WAEC_IRS_2024.json', '266f12b4ac8446af1d569bc07be1ec4161706acdcd9ba09cd70051761f7754ef');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The term ''Tawhid'' in Islam refers to the _____.', '["Prophethood of Muhammad","Belief in the Angels","Oneness of Allah","Day of Judgment"]', 2, 'Tawhid is the core concept of monotheism in Islam, asserting that Allah is One and Unique in His essence and attributes.', NULL, 'WAEC_IRS_2024.json', '1c85742881a3b62f07b97d56e372e4aabfca579a92d756ca8b35fadb2555f3fc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'Which of the following is NOT among the ''As-Sihah as-Sittah'' (The Six Authentic Books of Hadith)?', '["Sahih Bukhari","Sahih Muslim","Muwatta Malik","Sunan Abu Dawood"]', 2, 'Muwatta Malik is a highly respected collection but is not traditionally numbered among the ''Six Books'' (Bukhari, Muslim, Abu Dawood, Tirmidhi, Nasa''i, and Ibn Majah).', NULL, 'WAEC_IRS_2024.json', '4cd551fb7d3afb95b35c1d3159dbf48448b348b89f36b423d9c8e099b7be26a2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The first Caliph in Islam was _____.', '["Umar b. Khattab","Ali b. Abi Talib","Uthman b. Affan","Abu Bakr As-Siddiq"]', 3, 'Abu Bakr was elected as the leader of the Muslim community immediately after the death of the Prophet (SAW).', NULL, 'WAEC_IRS_2024.json', '8bda7a9faba3c977a538dca6a22342e1cce230ce9e32ef4200a08a8ef8d1f3fe');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The migration of the early Muslims from Makkah to Abyssinia (Ethiopia) was to escape the persecution of the _____.', '["Romans","Persians","Quraysh","Jews"]', 2, 'The Quraysh polytheists persecuted early converts, prompting the Prophet to advise some to seek refuge with the Christian King Negus (Najashi).', NULL, 'WAEC_IRS_2024.json', '6370722550c01ef7c76db97d9975771a7c2a24e6267af2a0ac7ff926aa69c57b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ritual of ''Sa''y'' during Hajj involves walking between the hills of _____.', '["Arafat and Muzdalifah","Safa and Marwa","Mina and Makkah","Uhud and Hira"]', 1, 'Sa''y commemorates Hajar''s (AS) search for water for her son Ismail (AS) between the hills of Safa and Marwa.', NULL, 'WAEC_IRS_2024.json', 'bbce9f95d4fd895e45620ca2d85fdac712e8a2cb9ef2bf241030db4010d6fd03');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The amount of Zakat payable on wealth (gold/silver/cash) that has reached the Nisab is _____.', '["10%","5%","2.5%","1%"]', 2, 'Zakat on liquid assets is calculated at 2.5% (one-fortieth) of the total value once held for a full lunar year.', NULL, 'WAEC_IRS_2024.json', '2fd3389d9e71445ba57b209b67e1ff6746da4c4a7b01e999dbec738c3a77f434');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The Surah that is equivalent to one-third of the Qur''an in terms of reward and meaning is _____.', '["Surat al-Falaq","Surat al-Ikhlas","Surat al-Nas","Surat al-Kafirun"]', 1, 'Surat al-Ikhlas summarizes the concept of Tawhid, which is the foundation of one-third of the Qur''anic message.', NULL, 'WAEC_IRS_2024.json', 'e5807e09e42d66298ed4846e6968ee2ff3191ac84fcad3635e6e653c36650b7c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'In Islamic Inheritance (Mirath), a daughter''s share when she is the only child is _____.', '["One-third","One-half","One-quarter","One-eighth"]', 1, 'According to the Qur''an (Surat an-Nisa), if there is only one daughter and no son, she receives half of the estate.', NULL, 'WAEC_IRS_2024.json', 'af0017e1324638afd10e48fdb1e3c965169828137fc3d9f1ade3c89967bc4d41');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The companion who was known as ''Dhul-Nurayn'' (The possessor of two lights) was _____.', '["Abu Bakr","Umar","Uthman","Ali"]', 2, 'Uthman b. Affan was given this title because he married two of the Prophet''s daughters, Ruqayyah and Umm Kulthum.', NULL, 'WAEC_IRS_2024.json', '122e271268e8f652e15bbb4cbb8a5d24eb7ec9807556474a5552ccafdd405862');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The battle in which the Muslims suffered a setback due to the disobedience of the archers was the Battle of _____.', '["Badr","Uhud","Khandaq (Trench)","Hunayn"]', 1, 'At Uhud, the archers left their positions on the hill against the Prophet''s orders, allowing Khalid b. Walid to lead a counter-attack.', NULL, 'WAEC_IRS_2024.json', 'ca43fd1d43dc031c7506c3f26ee943a393abfb9aecb5d1b0865328be9f53d33c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The science of the rules governing the correct pronunciation of the Qur''an is called _____.', '["Tafsir","Tajwid","Fiqh","Hadith"]', 1, 'Tajwid ensures that every letter of the Qur''an is pronounced correctly from its point of articulation with its proper characteristics.', NULL, 'WAEC_IRS_2024.json', '185b1cb0f3214e4fa54bdef2682701ff9df470ce9076e162bedff1276c18c6d8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The angel responsible for blowing the trumpet (Sur) to signal the Day of Judgment is _____.', '["Jibril","Mika''il","Israfil","Izra''il"]', 2, 'Israfil is the angel tasked with blowing the trumpet twice: once to end life and once to initiate the resurrection.', NULL, 'WAEC_IRS_2024.json', '9d70bfe39af5552262f4d5d6e121eb9167f85f058ca3b8870ea201a2bab56ae6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The collection and compilation of the Qur''an into a single volume was initiated during the Caliphate of _____.', '["Abu Bakr","Umar","Uthman","Ali"]', 0, 'Following the Battle of Yamamah where many huffaz died, Abu Bakr ordered Zaid b. Thabit to compile the Qur''an into a single book (Mushaf).', NULL, 'WAEC_IRS_2024.json', '5f1144eed51c5d54196574ecedc7014837848248de449c643ef309f19fd0cb84');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'A ''Mahr'' in an Islamic marriage is the _____.', '["wedding feast","marriage contract","obligatory gift from husband to wife","divorce settlement"]', 2, 'Mahr is the mandatory dowry or gift paid by the groom to the bride at the time of marriage as a token of respect and security.', NULL, 'WAEC_IRS_2024.json', '508e9ad4be35f9f7728cd72f87fd88ffed7142caaa424d21a17c408b58c1c41e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The act of ''Tayammum'' is performed when _____ is unavailable.', '["food","water","a prayer mat","a mosque"]', 1, 'Tayammum is dry ablution using clean earth/sand when water is not available or its use is harmful to health.', NULL, 'WAEC_IRS_2024.json', '6b8c64292dd69884a46730026e8d6bf89e3c2d04a27fa49d953f836025ef0571');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The central theme of this Hadith is _____.', '["Prayer","Altruism and Love","Business Ethics","Hajj"]', 1, 'The Hadith emphasizes that true faith involves selfless love and wishing good for others as much as for oneself.', 'Prophet Muhammad (SAW) said: ''None of you truly believes until he wishes for his brother what he wishes for himself.'' (Narrated by Al-Bukhari and Muslim)', 'WAEC_IRS_2024.json', '1764465fea2c4042e987d0892271b3b455e284506d6a1d1faa9a8d1cfd3f5865');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'In this context, ''brother'' refers to _____.', '["biological siblings only","Muslims only","fellow human beings","neighbors only"]', 2, 'While it primarily addresses the brotherhood in faith, scholars interpret the spirit of the Hadith as universal kindness toward all fellow humans.', 'Prophet Muhammad (SAW) said: ''None of you truly believes until he wishes for his brother what he wishes for himself.'' (Narrated by Al-Bukhari and Muslim)', 'WAEC_IRS_2024.json', '0fece44ea55e3133b1964bbd3e61eb54ef190446bbccc68e62485b7b53d7cc04');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ''Nisab'' of cattle (cows) for Zakat starts at _____ animals.', '["5","30","40","10"]', 1, 'Zakat is not due on cows until the owner has at least 30, at which point one one-year-old calf (Tabi'') is due.', NULL, 'WAEC_IRS_2024.json', 'dc8499936c0b007887fc9d940a834ba2c04c07d633d6740dbfa311fbb8c71334');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The term ''Shirk'' means _____.', '["Belief in Allah","Associating partners with Allah","Performing Salat","Fasting in Ramadan"]', 1, 'Shirk is the opposite of Tawhid and is considered the gravest sin in Islam, as it compromises the absolute oneness of God.', NULL, 'WAEC_IRS_2024.json', '14d506dc034fe1f5d51aada564e6067451cfea19589f1ee4c54f015b39402ffe');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ''Hijrah'' calendar begins from the year the Prophet (SAW) migrated from _____ to _____.', '["Makkah to Abyssinia","Madinah to Makkah","Makkah to Madinah","Madinah to Ta''if"]', 2, 'The Islamic (Hijri) era marks the migration to Madinah in 622 CE, which established the first Islamic state.', NULL, 'WAEC_IRS_2024.json', '95f9c731e9309ff2c55c2d181795e8ac3bb6ef19d8f1a2ae01d86a118c2a18d3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The Surah that protects a person from the trials of the Dajjal (Anti-Christ) if the first ten verses are memorized is _____.', '["Al-Baqarah","Al-Kahf","Yasin","Al-Mulk"]', 1, 'Prophet Muhammad (SAW) recommended reciting Surat al-Kahf on Fridays and memorizing its opening for protection against the Dajjal.', NULL, 'WAEC_IRS_2024.json', '86d37da1b02bff31864d8a082d564133630f4fd9ffde5a4d2700e5799726a7c7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ''Khulafah ar-Rashidun'' refers to the _____.', '["Umayyad Caliphs","Abbasid Caliphs","Rightly Guided Caliphs","Ottoman Sultans"]', 2, 'This title is given to the first four Caliphs: Abu Bakr, Umar, Uthman, and Ali, who followed the Sunnah of the Prophet closely.', NULL, 'WAEC_IRS_2024.json', '8013cfc5af68d369e8aa205dac5a9f2f619c813bcf7cb3acf218eb38f74d4c1b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The pre-Islamic period of ignorance in Arabia is known as _____.', '["Jahiliyyah","Fitnah","Riddah","Asabiyyah"]', 0, 'Jahiliyyah refers to the state of affairs in Arabia before the mission of Prophet Muhammad (SAW), characterized by idolatry and tribal warfare.', NULL, 'WAEC_IRS_2024.json', 'c207037450b16577ac93b1b0afd5c7b028a22f8f049c9ec69c1f80f65e1dbd73');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The Prophet''s wife who was the daughter of Abu Bakr and a great scholar of Hadith was _____.', '["Khadijah","Sawdah","Aishah","Hafsah"]', 2, 'Aishah (RA) was known for her intelligence and contributed significantly to the preservation and teaching of Islamic knowledge.', NULL, 'WAEC_IRS_2024.json', 'b6c8da37ea27661e0fe2f2c8eeeb9209674409f3a46de498a33f478ba78577b2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ''Iddah'' period for a divorced woman who is not pregnant is _____.', '["4 months and 10 days","3 menstrual cycles","1 year","40 days"]', 1, 'The Qur''an specifies three monthly cycles (Quru'') for a divorced woman to ensure there is no pregnancy before she remarries.', NULL, 'WAEC_IRS_2024.json', 'f3b579df3f75f7115f5efc774acc7eeee05e68524e780aa269acbdd27097d779');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The treaty signed between the Muslims and the Quraysh in 628 CE was the Treaty of _____.', '["Madinah","Ta''if","Hudaibiyyah","Aqabah"]', 2, 'Hudaibiyyah was a 10-year peace treaty that, although initially seeming disadvantageous to Muslims, led to the peaceful conquest of Makkah.', NULL, 'WAEC_IRS_2024.json', '624c8c3fc762a306035f6d96a5e5e071e06e1a4c89ce276f2f85dc83b5355f99');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The first Mu''adhin (caller to prayer) in Islam was _____.', '["Zaid b. Harithah","Bilal b. Rabah","Abdullah b. Mas''ud","Salman al-Farisi"]', 1, 'Bilal, a former slave from Ethiopia, was chosen for his beautiful and strong voice to call Muslims to prayer.', NULL, 'WAEC_IRS_2024.json', 'b02d93ceb94471b46129aff013623b7fd6491d695b315508364f9b5cd83400a4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'A prayer offered for a deceased Muslim before burial is called _____.', '["Salat al-Istisqa","Salat al-Janazah","Salat al-Kusuf","Salat al-Witr"]', 1, 'Salat al-Janazah is a funeral prayer consisting of four Takbirs, performed in congregation standing up (without Ruku'' or Sujud).', NULL, 'WAEC_IRS_2024.json', '1d369ee1cb6074280321833bd4d44db1434725e764fedecda9234aad0dd7a54a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ''Night of Power'' (Laylatul-Qadr) is better than _____ months.', '["100","500","1,000","10,000"]', 2, 'Surat al-Qadr states that worship on this night in Ramadan is better than a thousand months of worship.', NULL, 'WAEC_IRS_2024.json', '931f0eda9f71bc239cd010fc88bba5f15b5a5c2a637b892f8ba3864d831ca0de');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The legal ruling that is ''highly recommended'' but not strictly obligatory is called _____.', '["Fard","Mustahabb (Mandub)","Makruh","Haram"]', 1, 'Mustahabb actions are those for which a person is rewarded if performed, but not punished if omitted.', NULL, 'WAEC_IRS_2024.json', 'ab23fedee8872ef8d45781c927316d43dc2ac41f16770668c58506c989e0dc6c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The Surah that warns against backbiting and slandering is _____.', '["Surat al-Humazah","Surat al-Fil","Surat al-Ma''un","Surat al-Kawthar"]', 0, 'Surat al-Humazah begins by condemning ''every slanderer and backbiter''.', NULL, 'WAEC_IRS_2024.json', '7092acc7e114e79bbe03b0839a7ae98105e8b0974ce4083c6923dc062b95d0ea');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The Islamic concept of ''Ihsan'' means _____.', '["to pay Zakat","to worship Allah as if you see Him","to fast in the heat","to go for Hajj twice"]', 1, 'In the Hadith of Jibril, Ihsan is defined as ''to worship Allah as if you see Him, and if you cannot see Him, you know He sees you''.', NULL, 'WAEC_IRS_2024.json', '9fe106cdb9eaedf56250f0a99b950195c2bd6e4edc68bff68716c8dbaf22db3d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'Which Caliph oversaw the expansion of Islam into Persia, Egypt, and the Levant?', '["Abu Bakr","Umar b. Khattab","Uthman b. Affan","Ali b. Abi Talib"]', 1, 'Umar (RA) was the great administrator and conqueror under whose rule the Islamic empire expanded most rapidly.', NULL, 'WAEC_IRS_2024.json', 'ff0b24942cf5e1748afbb63ec928f6a93d6464c6c77277d00bb05ee805525ff3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ''Sunnah'' refers to the _____ of the Prophet Muhammad (SAW).', '["writings","physical appearance","sayings, actions, and approvals","family tree"]', 2, 'Sunnah encompasses everything the Prophet said (Qawl), did (Fi''l), or tacitly approved (Taqrir).', NULL, 'WAEC_IRS_2024.json', '43d408986a0d3051d348b7da760fa02af2989c41e8ca72bf27c1e364dff5cdbf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The major theme of the ''Makkan'' Surahs is usually _____.', '["Social legislation","Tawhid and the Hereafter","War and Peace","Rules of Inheritance"]', 1, 'Makkan Surahs focus on establishing faith, the oneness of Allah, and the reality of life after death, while Madinan Surahs focus on law and community building.', NULL, 'WAEC_IRS_2024.json', '9e634915c1175c7a6035c043da3fcae131892f8a81bcd527a42e2bd37b79caa4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The number of Sajdah (prostration) marks found in the Qur''an is _____.', '["10","14","20","30"]', 1, 'Most scholars agree on 14 specific verses in the Qur''an where it is Sunnah to perform a prostration (Sajdah at-Tilawah) upon recitation.', NULL, 'WAEC_IRS_2024.json', '7edb8ac903822a05c97343369cd1bffd6285c61e96763c2868672164ce7f62dc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ''Battle of the Trench'' is also known as the Battle of _____.', '["Al-Ahzab (The Confederates)","Tabuk","Mu''tah","Khaybar"]', 0, 'It is called ''Al-Ahzab'' because various tribes formed a confederacy to attack the Muslims in Madinah.', NULL, 'WAEC_IRS_2024.json', '278c133139921e25ccfc01e96cbe4fe765cb5248667de5b867c715859e48b146');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'A Hadith that has a broken chain of narrators is classified as _____.', '["Sahih","Hasan","Munqati''","Maudu''"]', 2, 'Munqati'' refers to a Hadith where a narrator is missing from the chain of transmission.', NULL, 'WAEC_IRS_2024.json', '5f9fe1e6e79a34de99bacb55b98d3b22d42e27b4d954bec2a1089d415d24d418');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The prophet mentioned most frequently by name in the Qur''an is _____.', '["Muhammad (SAW)","Ibrahim (AS)","Musa (AS)","Isa (AS)"]', 2, 'Prophet Musa (AS) is mentioned 136 times in the Qur''an across many Surahs.', NULL, 'WAEC_IRS_2024.json', '4b620be79946e4de4b637ebdbdaef376bb6356a8429994f7e9a66481f43e2395');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The direction (Qiblah) Muslims face during prayer was changed from _____ to Makkah.', '["Cairo","Jerusalem (Al-Quds)","Madinah","Damascus"]', 1, 'Early in Madinah, the Qiblah was toward Masjid al-Aqsa in Jerusalem before the revelation of Surat al-Baqarah verse 144.', NULL, 'WAEC_IRS_2024.json', '230189c0a05642d8a450622583ca4db94682e23147269e6a583f40d26df52f3f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The term ''Sadaqah'' generally refers to _____.', '["Obligatory tax","Voluntary charity","Loans","Interest"]', 1, 'While Zakat is obligatory, Sadaqah refers to any act of voluntary kindness or financial help given for the sake of Allah.', NULL, 'WAEC_IRS_2024.json', '29526938db1c75def7f7ee6fd7d834575e2e3d8a0f1fb21b3f2ecb2d3ea2e28e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ''Haram'' months in which fighting is prohibited are _____.', '["Ramadan and Shawwal","Dhul-Qi''dah, Dhul-Hijjah, Muharram, and Rajab","Muharram and Safar","Rabi'' al-Awwal and Rabi'' al-Thani"]', 1, 'These four months are sacred, and the Qur''an forbids initiating warfare during them.', NULL, 'WAEC_IRS_2024.json', '264e11d684774258e7a01ebc8c0ddc5166925bc352e9712363afb76eb1a22b4e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The compiler of the most authentic book of Hadith, Sahih Al-Bukhari, was from _____.', '["Saudi Arabia","Egypt","Uzbekistan (Bukhara)","Iran"]', 2, 'Imam Muhammad b. Ismail al-Bukhari was born in Bukhara, in present-day Uzbekistan.', NULL, 'WAEC_IRS_2024.json', '8b52ae52a661a277efaf8c344da2b6f839e0392ee1d3ec98fbf633ca63da8a1d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The act of ''Istighfar'' means _____.', '["praising Allah","seeking forgiveness from Allah","declaring Allah''s greatness","fasting"]', 1, 'Istighfar is the act of saying ''Astaghfirullah'' (I seek Allah''s forgiveness).', NULL, 'WAEC_IRS_2024.json', '1914eb289a3de06d1f8b9ed2d78ad6bff511f4fe082393e89036c38c887f3efb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'A person who memorizes the entire Qur''an is called a _____.', '["Hafiz","Qari","Mufassir","Faqih"]', 0, 'Hafiz (Guardian) is the title for someone who has committed the 6,236 verses of the Qur''an to memory.', NULL, 'WAEC_IRS_2024.json', 'f8bae54f43614f78a5e17acb4bf8970b8df2ccd75f484bdb72f1187fdb851ecd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ''Riddah'' wars were fought during the Caliphate of Abu Bakr against _____.', '["the Romans","the Persians","apostates and false prophets","the Quraysh"]', 2, 'After the Prophet''s death, some tribes rebelled or followed false prophets like Musaylimah; Abu Bakr fought to maintain the unity of Islam.', NULL, 'WAEC_IRS_2024.json', 'fe667aac0bd35a0e57070ab50f9d08546dba6323d763eb1b8cb4a9b81b8cad60');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ''Takbirat al-Ihram'' is the _____.', '["final greeting in prayer","opening ''Allahu Akbar'' to start prayer","prostration","call to prayer"]', 1, 'This Takbir signals the entry into the sacred state of prayer, during which ordinary actions like eating or talking become forbidden.', NULL, 'WAEC_IRS_2024.json', '37e68b5695d35ca323eb3270905e6ebfc9a24b55db3f0b85b4ccf60774875eab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ''Al-Faruq'' was the title of which Caliph?', '["Abu Bakr","Umar b. Khattab","Uthman","Ali"]', 1, 'Umar was called Al-Faruq (The one who distinguishes between truth and falsehood) for his strict justice.', NULL, 'WAEC_IRS_2024.json', 'a39cdf6658ede5565be278a1bce66d413d191b99ad4ce2b8b6b26330fc654b2e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The main focus of Surat al-Ma''un is _____.', '["Warfare","Hypocrisy and neglecting the needy","Inheritance","The creation of man"]', 1, 'The Surah criticizes those who pray for show but refuse to help the orphans and the poor.', NULL, 'WAEC_IRS_2024.json', 'cd73eade3af24a3844076c36eeffd9d32f060a344d6e70e2b2baf9cd725e949c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'Islamic monotheism is divided into three categories: Tawhid ar-Rububiyyah, Tawhid al-Uluhiyyah, and _____.', '["Tawhid al-Iman","Tawhid al-Asma was-Sifat","Tawhid al-Qadr","Tawhid al-Ihsan"]', 1, 'The third category involves the belief in Allah''s unique Names and Attributes as mentioned in the Qur''an and Sunnah.', NULL, 'WAEC_IRS_2024.json', '640a43b55d68d8d798bfc72fb926531dc636a9f8a4428a8fd235a37795c13d56');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ''Sujud as-Sahw'' is performed when a person _____.', '["finishes the Qur''an","makes a mistake or forgetfulness in prayer","receives good news","enters a mosque"]', 1, 'Two extra prostrations are performed at the end of Salat to compensate for unintentional omissions or additions.', NULL, 'WAEC_IRS_2024.json', '9f6285dfbe8c83d025f0e410f05f6fe749c80a04a6b0acac84327207b87e8c15');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The primary objective of ''Sawm'' (fasting) as stated in the Qur''an is to achieve _____.', '["weight loss","poverty awareness","Taqwa (God-consciousness)","patience"]', 2, 'Surat al-Baqarah 183 states: ''...so that you may become God-fearing/righteous (Taqwa)''.', NULL, 'WAEC_IRS_2024.json', '61a053cd2c8f0bc2c9f3a450ab14c20d20ef0c8837f1186ea9d83a238741a141');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The collection of sayings and deeds of the Prophet Muhammad (SAW) is called _____.', '["Qur''an","Hadith","Shari''ah","Sira"]', 1, 'Hadith is the record of the Sunnah.', NULL, 'WAEC_IRS_2024.json', '73788685db4a85fb7efe4497fd9eacd709baa712224f37c65fbee2619af8ee37');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'In Shari''ah, the prohibited acts are known as _____.', '["Halal","Haram","Mubah","Wajib"]', 1, 'Haram refers to anything explicitly forbidden by Allah and His Messenger.', NULL, 'WAEC_IRS_2024.json', 'a4ae388027836b8f52a43d73f811cf8b95061ca2242061d0d03885bfcf87380b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The first revelation came to the Prophet in the Cave of _____.', '["Thawr","Hira","Uhud","Safa"]', 1, 'Mount Nur houses the Cave of Hira, where Angel Jibril first commanded the Prophet to ''Read!'' (Iqra).', NULL, 'WAEC_IRS_2024.json', '9a91f326195fbfadd04adcf9a1f7385f4c3d3bce37e45c5d87432075b722a7c4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'Which Caliph was known for his extreme modesty and for compiling the standard version of the Qur''an used today?', '["Abu Bakr","Umar","Uthman","Ali"]', 2, 'Uthman (RA) ordered the standardized ''Uthmanic Codex'' to be sent to all major Islamic cities to ensure uniformity.', NULL, 'WAEC_IRS_2024.json', '755425a933671d777bcfdf665cbabd1c420553105b698a07b17606982707ef77');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ''Asadullah'' (Lion of Allah) was a title of _____.', '["Khalid b. Walid","Umar b. Khattab","Hamzah b. Abdul-Muttalib","Ali b. Abi Talib"]', 2, 'The Prophet''s uncle, Hamzah, was given this title for his bravery, though Ali (RA) was also famously brave.', NULL, 'WAEC_IRS_2024.json', '20e1d5d4efc8862a5109f41dd0e1107d5bbbffec4812c786e0189774989ede5f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The Surah that must be recited in every Rak''ah of prayer is _____.', '["Al-Nas","Al-Fatihah","Al-Ikhlas","Al-Asr"]', 1, 'Prayer is invalid without the recitation of Al-Fatihah, known as ''Umm al-Kitab''.', NULL, 'WAEC_IRS_2024.json', '025db52364e31f873f19e58db771eeb8e1d26133b7749cd85d60af153313afff');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'A ''Mushrik'' is a person who _____.', '["denies Allah''s existence","associates partners with Allah","fasts without praying","commits murder"]', 1, 'The term comes from ''Shirk'', meaning polytheism or idolatry.', NULL, 'WAEC_IRS_2024.json', '594e08229d243e530c7f33530365c7e9f3e26ed5880cdfc8ecf8ea4a8e37a683');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The Islamic term for the ''oneness of God'' is _____.', '["Iman","Tawhid","Ihsan","Salat"]', 1, 'Tawhid is the defining doctrine of Islam.', NULL, 'WAEC_IRS_2024.json', '4ada1b02826ae41f1748cb8554eda5d60206d999c650f7927b2aebd6ed9e7817');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The five daily prayers are: Fajr, Zuhr, Asr, Maghrib, and _____.', '["Tahajjud","Witr","Isha","Duha"]', 2, 'Isha is the night prayer, the last of the five obligatory daily prayers.', NULL, 'WAEC_IRS_2024.json', 'f433eb5dcc8f347e6186b8c80b5f9bf3d674de4bf25d446a6e1e23540a41aef1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The term ''Tafsir'' refers to _____.', '["recitation of the Qur''an","exegesis/explanation of the Qur''an","memorization","handwriting"]', 1, 'Mufassirun (commentators) use linguistics, history, and Hadith to explain the meanings of Qur''anic verses.', NULL, 'WAEC_IRS_2024.json', '047044ba8a266e8a5e2c9950c2e034bfc38af63b92e48eb0e9cb7fd69e58079a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'A Hadith narrated by only one person at every stage of the chain is called _____.', '["Gharib","Aziz","Mashhur","Mutawatir"]', 0, 'Gharib means ''strange'' or ''solitary'' in Hadith terminology.', NULL, 'WAEC_IRS_2024.json', '488f269a91fe237cea43e82e25eb527d092ccb81516733edcd9e93bfa13b6825');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The Prophet Muhammad (SAW) belonged to the tribe of _____.', '["Aus","Khazraj","Quraysh","Thaqif"]', 2, 'He was from the Banu Hashim clan of the Quraysh tribe in Makkah.', NULL, 'WAEC_IRS_2024.json', 'e041cdf59e697522a8e3805f57c82ce9531a24449fe581e54f3e992d3c6132e2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The ''Kharaj'' in Islamic taxation refers to _____.', '["tax on trade","land tax","poll tax on non-Muslims","war booty"]', 1, 'Kharaj is a tax on agricultural land, typically applied to lands conquered by Muslims.', NULL, 'WAEC_IRS_2024.json', '398050c0100bf4cbab1c97f3a263f75f972c8a86504eab710dcccbb3e81cbc3e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'IRS', 2024, NULL, 'The Surah that describes the short duration of time and the importance of faith and good deeds is _____.', '["Surat al-Nas","Surat al-Ikhlas","Surat al-Asr","Surat al-Falaq"]', 2, 'Surat al-Asr emphasizes that all mankind is in a state of loss except those who have faith, do good, and encourage truth and patience.', NULL, 'WAEC_IRS_2024.json', '2a757eb8e4321e99bb4cfe2b8eb1ac387355154d8b622ffd0ce5fbdaacb77ed7');
