INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ uru ịgụ akwụkwọ dị ka passage si kọwaa?', '["Ịnweta ego ngwa ngwa","Inwe nghọta banyere ihe na-eme n''ụwa","Ịlụ di n''oge","Ịga njem ná mba ofesi"]', 1, 'The passage explicitly states that an educated person understands world events (''Onye gụrụ akwụkwọ na-enwe nghọta banyere ihe na-eme n''ụwa niile'').', 'Ịgụ akwụkwọ bụ ihe dị ezigbo mkpa ná ndụ mmadụ. Onye gụrụ akwụkwọ na-enwe nghọta banyere ihe na-eme n''ụwa niile. N''oge gboo, a naghị eji agụmakwụkwọ ụmụ nwaanyị egwu egwu n''ala Igbo. Ndị mmadụ chere na ọ bụrụ na nwa nwaanyị agụọ akwụkwọ, ọ gaghị anọ n''ụlọ di ya. Ma taa, ihe agbanweela. Agụmakwụkwọ atụleela anya ndị mmadụ ma mepee obodo. Ọ bụ ya mere e ji asị na ịzụ nwa nwaanyị bụ ịzụ mba niile.', 'WAEC_Igbo_2024.json', '5b8bc39be431699d24a6b2ddc295b79f6325a49b9db6035b2f99acf8d9e3b6a3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị ka ndị mmadụ chere banyere ụmụ nwaanyị na agụmakwụkwọ n''oge gboo?', '["Na ha ga-aka ndị nwoke amamihe","Na ha agaghị anọ n''ụlọ di ha","Na ha ga-abụ ndị eze","Na ha ga-amụ nani ụmụ nwoke"]', 1, 'The text mentions that people used to fear that educated women wouldn''t stay in their husbands'' houses (''Ndị mmadụ chere na ọ bụrụ na nwa nwaanyị agụọ akwụkwọ, ọ gaghị anọ n''ụlọ di ya'').', 'Ịgụ akwụkwọ bụ ihe dị ezigbo mkpa ná ndụ mmadụ. Onye gụrụ akwụkwọ na-enwe nghọta banyere ihe na-eme n''ụwa niile. N''oge gboo, a naghị eji agụmakwụkwọ ụmụ nwaanyị egwu egwu n''ala Igbo. Ndị mmadụ chere na ọ bụrụ na nwa nwaanyị agụọ akwụkwọ, ọ gaghị anọ n''ụlọ di ya. Ma taa, ihe agbanweela. Agụmakwụkwọ atụleela anya ndị mmadụ ma mepee obodo. Ọ bụ ya mere e ji asị na ịzụ nwa nwaanyị bụ ịzụ mba niile.', 'WAEC_Igbo_2024.json', '4a9c9e6cb2b450e92221d81d2c185a6f7bb881bb94c5b249c2c3c8959f0404db');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ isiokwu kacha mma maka akụkọ a?', '["Ịlụ di n''ala Igbo","Mkpa agụmakwụkwọ dị","Akụkọ banyere ego","Ịzụ ahịa ná mba ofesi"]', 1, 'The main theme of the text is the importance of education for individuals and society.', 'Ịgụ akwụkwọ bụ ihe dị ezigbo mkpa ná ndụ mmadụ. Onye gụrụ akwụkwọ na-enwe nghọta banyere ihe na-eme n''ụwa niile. N''oge gboo, a naghị eji agụmakwụkwọ ụmụ nwaanyị egwu egwu n''ala Igbo. Ndị mmadụ chere na ọ bụrụ na nwa nwaanyị agụọ akwụkwọ, ọ gaghị anọ n''ụlọ di ya. Ma taa, ihe agbanweela. Agụmakwụkwọ atụleela anya ndị mmadụ ma mepee obodo. Ọ bụ ya mere e ji asị na ịzụ nwa nwaanyị bụ ịzụ mba niile.', 'WAEC_Igbo_2024.json', '842e924a81b4d843164c5d4a164e131a89d7b0d1bc389909aabafcb8c8eae125');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Kedu ihe ''ihe agbanweela'' pụtara n''ahịrịokwu ahụ?', '["Na oge ejirila","Na ndụ agwụla","Na e nweela mgbanwe n''echiche ndị mmadụ","Na mmiri na-ezo"]', 2, '''Ihe agbanweela'' (things have changed) refers to the shift in social perception regarding female education.', 'Ịgụ akwụkwọ bụ ihe dị ezigbo mkpa ná ndụ mmadụ. Onye gụrụ akwụkwọ na-enwe nghọta banyere ihe na-eme n''ụwa niile. N''oge gboo, a naghị eji agụmakwụkwọ ụmụ nwaanyị egwu egwu n''ala Igbo. Ndị mmadụ chere na ọ bụrụ na nwa nwaanyị agụọ akwụkwọ, ọ gaghị anọ n''ụlọ di ya. Ma taa, ihe agbanweela. Agụmakwụkwọ atụleela anya ndị mmadụ ma mepee obodo. Ọ bụ ya mere e ji asị na ịzụ nwa nwaanyị bụ ịzụ mba niile.', 'WAEC_Igbo_2024.json', 'e7356471ec679ce43dc9e3f6fc9b6135c9e81833fd3b95f45d86a1f8e2ef0bf6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Olee ilu a pụrụ iji mechie akụkọ a?', '["Gidi gidi bụ ugwu eze","Ịzụ nwa nwaanyị bụ ịzụ mba niile","Nwa bụ ihe ụtọ","Onye kwe, chi ya ekwe"]', 1, 'The passage concludes with this specific popular proverb emphasizing the collective impact of female education.', 'Ịgụ akwụkwọ bụ ihe dị ezigbo mkpa ná ndụ mmadụ. Onye gụrụ akwụkwọ na-enwe nghọta banyere ihe na-eme n''ụwa niile. N''oge gboo, a naghị eji agụmakwụkwọ ụmụ nwaanyị egwu egwu n''ala Igbo. Ndị mmadụ chere na ọ bụrụ na nwa nwaanyị agụọ akwụkwọ, ọ gaghị anọ n''ụlọ di ya. Ma taa, ihe agbanweela. Agụmakwụkwọ atụleela anya ndị mmadụ ma mepee obodo. Ọ bụ ya mere e ji asị na ịzụ nwa nwaanyị bụ ịzụ mba niile.', 'WAEC_Igbo_2024.json', '9b8eecbe3e39096889a9978b3cd0d1e7c96a4e8bdb26e154d4fbbc721ed30943');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Mkpụrụedemede asụsụ Igbo dị ole?', '["Iri abụọ na isii","Iri atọ na isii","Iri atọ na asatọ","Iri abụọ na asatọ"]', 1, 'The Standard Igbo alphabet (Abidịị) consists of 36 letters.', NULL, 'WAEC_Igbo_2024.json', 'be2ab8c8a4a7ab9491c390c531e065f285d7db4cd9eebcb21a5c8911f6e92e14');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Olee n''ime ndị a bụ udaume mfe (Light vowels)?', '["a, ị, ọ, ụ","e, i, o, u","a, e, i, o","ọ, ụ, i, u"]', 0, 'The light vowels in Igbo (udaume mfe) are a, ị, ọ, and ụ, which follow the vowel harmony rule.', NULL, 'WAEC_Igbo_2024.json', '6dbebf5a8fd676e394a791192703e85cc057c893d040251ebf2e46e527bfbc3c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Udaume ole dị n''asụsụ Igbo?', '["Ise","Isii","Asatọ","Iri"]', 2, 'Igbo language has 8 vowels divided into two groups of four (Light and Heavy).', NULL, 'WAEC_Igbo_2024.json', '3b6dd3dd204670c216dec8f58e8af0330cdd41ce8838836445f8443dc278ea15');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Mkpụrụedemede Igbo ole bụ mgbochiume (Consonants)?', '["Iri abụọ na asatọ","Iri abụọ na isii","Iri atọ","Iri abụọ na anọ"]', 0, 'Out of 36 letters, 28 are consonants (mgbochiume).', NULL, 'WAEC_Igbo_2024.json', '1fa636c9a2325ec6e665bd5fff3f5a8266395ec2a2feb317370b6e9ba83edd87');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Olee n''ime mkpụrụedemede ndị a bụ mgbochiume kpachịrị akpachị (Digraphs)?', '["b, d, f","gb, ch, gh","m, n, l","r, s, t"]', 1, 'Digraphs are sounds represented by two letters but producing a single sound, such as ''gb'', ''ch'', ''gh'', ''kw'', ''nw'', ''ny'', ''sh''.', NULL, 'WAEC_Igbo_2024.json', '1413de78ef3bf698f2102fa6eb1b0552f58e566ce0e71c261e4553b7f32d0883');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Kedu nke bụ myiriụda (Nasal consonant acting as a syllable)?', '["m, n","b, d","a, e","p, k"]', 0, '''m'' and ''n'' are nasal sounds that can sometimes carry a tone and form a syllable on their own in Igbo.', NULL, 'WAEC_Igbo_2024.json', '182c65979b0e8217d9c585d58b4dd8d9aa5b67813e07b57ca07e624601f7f136');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Ahịrịokwu a ''Obi tiri mkpu'' nwere ụdị ngwaa (verb) wo?', '["Ngwaa nnyemaka","Ngwaa mbufe","Ngwaa amamihe","Ngwaa nkwadobe"]', 1, '''Tiri'' functions as a transitive verb (ngwaa mbufe) because the action passes to the object ''mkpu''.', NULL, 'WAEC_Igbo_2024.json', 'f4c50d071afc64122f6183ca31943cb44f817532d13da16633c03e8b3930ba52');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Olee akaraolu (Tone mark) a na-asụpe ''à''?', '["Akaraolu elu","Akaraolu ala","Akaraolu nsu","Akaraolu etiti"]', 1, 'The grave accent (`) represents the low tone (akaraolu ala) in Igbo.', NULL, 'WAEC_Igbo_2024.json', '999e51a9dec97d8fa8ac1942d23975f72f19f0f657c6c95f831de0c024318b32');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Kpọọ aha nkejiasụsụ na-akọwa aha ma ọ bụ nnọchiaha _____.', '["Ngwaa","Mgbakwunye","Nkọwa","Njikọ"]', 2, 'An adjective (nkọwa) is a word that describes or qualifies a noun (aha) or pronoun (nnọchiaha).', NULL, 'WAEC_Igbo_2024.json', '6e902cd94553a88d41c076c725dac0efbb9020f60d94fed113edfe3d1779978f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Ahịrịokwu ''Nwa ahụ bụ ozu'' nwere ụdị nnyemaka wo?', '["Mmekpọ","Nnyemaka","Esemokwu","Inyeaka"]', 0, '''Bụ'' is a stative or copular verb (ngwaa mmekpọ) that links the subject to a complement.', NULL, 'WAEC_Igbo_2024.json', 'b8df85acb4645964b315621471961c8895848e1b79cef6ebd1c324e8dcc5441f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Mgbakwunye (Affix) na-abịa n''ihu ngwaa bụ _____.', '["Nsonazụ","Nsuru-ihu","Mbuụzọ","Ntinye"]', 2, 'A prefix (mbuụzọ) is an affix added to the beginning of a verb root.', NULL, 'WAEC_Igbo_2024.json', 'b3ea43d017038d5743646c96f2c01cf6f46d6891b45244d602b03597d9bc4505');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Olee n''ime ndị a bụ nnọchiaha (Pronoun)?', '["Ụlọ","Anyị","Rie","Ọcha"]', 1, '''Anyị'' (We/Us) is a first-person plural pronoun.', NULL, 'WAEC_Igbo_2024.json', 'a9b77e474edbef5827a759c79d2f8c54d88995352b6a0a02f295e184ca212eb1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Olee akara edemede a na-eji egosi nkwụsị oge na mkparịtaụka?', '["Kọma","Kọlọn","Ihuami","Akara ajụjụ"]', 0, 'A comma (kọma) is used to indicate a brief pause in a sentence or dialogue.', NULL, 'WAEC_Igbo_2024.json', '0b60e7776be5f61faba64cd4c38b73a408c06f45378984c33349605744093a61');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Chọpụta aha pụrụ iche (Proper noun) n''ime ndị a:', '["Osisi","Enugwu","Akwụkwọ","Mmadụ"]', 1, 'Enugwu is a specific name of a place, making it a proper noun.', NULL, 'WAEC_Igbo_2024.json', '0aec33aaea686038a333680cae21abfb6cb7d447e46759c1527cbc28a101da9b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'N''ahịrịokwu bụ ''Ada na-eri nri'', gịnị bụ ''na-''?', '["Ngwaa nnyemaka","Mbuụzọ","Isi ngwaa","Njikọ"]', 0, '''Na'' acts as an auxiliary verb (ngwaa nnyemaka) indicating continuous tense.', NULL, 'WAEC_Igbo_2024.json', '569664ad347054f124cc215aab2f228839b1f890dc80d444b1aab26d5f6ecd45');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ mkpụrụasụsụ a kpọrọ ''Udaelu'' (High tone syllable)?', '["Mkpụrụasụsụ nwere akara ala","Mkpụrụasụsụ nwere akara elu","Mkpụrụasụsụ na-enweghị akara ọ bụla","Mkpụrụasụsụ nwere kọma"]', 2, 'In standard Igbo orthography, high tones are typically left unmarked.', NULL, 'WAEC_Igbo_2024.json', '4c8220aa176eae01c5724337c26fa16585a9f457def3bee54821d5fc164a67f5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Ole bụ ụdị aha (Types of Nouns) dị n''asụsụ Igbo?', '["Iri","Anọ","Abụọ","Isii"]', 3, 'Commonly, Igbo nouns are categorized into six types: Aha pụrụ iche, aha nkịtị, aha nnọchite, aha mkpokọta, aha njirimara, na aha agbatara n''aka.', NULL, 'WAEC_Igbo_2024.json', 'ca5c34455b0b837df17c9b11c251496933d4cbc6a0d3458a9eb4f24bda26790e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Ịlụ nwanyị n''ala Igbo na-amalite site n''ikụ aka n''ọnụ ụzọ nke a kpọrọ _____.', '["Ịghọ mmanwu","Ịjụ ajụjụ","Ịgba nnụkwụ","Ịda ogo"]', 1, 'The first formal step in Igbo marriage is ''Ịjụ ajụjụ'' (inquiry/knocking), where the groom''s family visits to state their intentions.', NULL, 'WAEC_Igbo_2024.json', '027004fdb2619afbeeabdcf184659457d1d2e70610d428eee279df5bdfcf5a99');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ uru ''Ego nwaanyị'' (Bride price) baara n''ala Igbo?', '["Ọ bụ ego e ji azụ nwaanyị","Ọ bụ ihe e ji egosi na nwaanyị ahụ adịghị mma","Ọ bụ ihe nkịtị na-enweghị uru","Ọ na-egosi nkwekọrịta na njikọ dị n''etiti ezinụlọ abụọ"]', 3, 'Bride price is a symbolic token that legalizes the marriage and binds the two families together.', NULL, 'WAEC_Igbo_2024.json', 'e9ead8b7557df8d1428851a9a6cac2124ebc9858b520af954c86e10c8342a340');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị ka a na-akpọ ememme a na-eme tupu e rie ji ọhụrụ?', '["Ịwa ji","Ịma mmanwụ","Ememme ofala","Iru mgbede"]', 0, '''Ịwa ji'' or ''Iri ji'' is the festival celebrating the harvest of new yams.', NULL, 'WAEC_Igbo_2024.json', '967937243a4c2bb2b8f02dc519568d9c58fc656ec9a53fbb51e8c1aed884b790');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Kedu onye n''ala Igbo na-arụ ọrụ ikpe ikpe na idozi okwu n''obodo n''oge gboo?', '["Ndị ntorobịa","Ndị Nze na Ọzo","Ụmụaka","Ndị nche obodo"]', 1, 'The titled elders (Nze na Ọzọ) and the council of elders were the primary judicial authorities in traditional Igbo society.', NULL, 'WAEC_Igbo_2024.json', '3ca85001720d30155b494659f83e8c713af36745e849c7b5b173ffc722ae0f44');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Ịmụ nwa n''ala Igbo na-eweta ọṅụ. Gịnị ka a na-akpọ nleta a na-aleta onye mụrụ nwa ọhụrụ?', '["Ịgba egwu","Ọmụgwọ","Ikpo nku","Iru uju"]', 1, '''Ọmụgwọ'' is the traditional postpartum care where a relative (usually the mother or mother-in-law) stays with the new mother.', NULL, 'WAEC_Igbo_2024.json', '2f34ceccee33d4c11e67b5c6708721e28ff8194fd2b2e148643be8203b6445f9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ ''Ikwa ozu'' n''ala Igbo?', '["Ịkwa akwa onye nwụrụ anwụ","Ememme olili na ncheta onye nwụrụ anwụ","Ịgba mgba n''ebe ozu dị","Iri nri n''ụlọ onye nwụrụ anwụ"]', 1, '''Ikwa ozu'' refers to the second burial rites or the elaborate funeral ceremonies performed to honor the deceased.', NULL, 'WAEC_Igbo_2024.json', 'fdd3df8e45222a06f45cf57053c22c0626f7877eeb1ea9676628a0e51d57a856');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Onye na-akpụ ihe site n''ụrọ n''ala Igbo bụ _____.', '["Onye na-akpụ isi","Onye na-akpụ ite","Onye na-akpụ ígwè","Onye na-akpụ nkwụ"]', 1, '''Onye na-akpụ ite'' (Potter) works with clay (ụrọ) to create pots and other utensils.', NULL, 'WAEC_Igbo_2024.json', '2cf167476786eba416132a84cff766e531fe8650d3eb73ddf43bf53cd469867b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Kedu dọkịta na-agwọ ọrịa site n''ịgwọ mkpọrọgwụ osisi n''omenala Igbo?', '["Dibia afa","Dibia mmiri","Dibia ogwu","Nọọsụ"]', 2, 'A ''Dibia ogwu'' is a traditional herbalist who uses roots and herbs for healing.', NULL, 'WAEC_Igbo_2024.json', '1ea263902e6750f400aeae484ea6fa76c7d034da5e7f41440a8535e80e60fbec');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Olee dọkịta na-agba afa iji mara ihe na-eme n''ụwa ndị mmụọ?', '["Dibia ogwu","Dibia afa","Dibia nkwụ","Onye ọrụ ubi"]', 1, 'A ''Dibia afa'' is a diviner who communicates with the spiritual realm to find causes of problems.', NULL, 'WAEC_Igbo_2024.json', '856c5dc5ac8aafea15c3bdd4324a053e27761a833a767c4f224a7dc4bdfad749');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Olee aha nwa a mụrụ n''ụbọchị ''Eke''?', '["Mgbeke","Mgborie","Mgbafor","Mgbeafọ"]', 0, 'Children are often named after the market day they were born. A girl born on Eke is ''Mgbeke''; a boy is ''Okeke''.', NULL, 'WAEC_Igbo_2024.json', '4b8462f31dcc24a559f34abfcbb0c0b8d41883939cace361d71e6817746ff6b8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Kedu aha a na-akpọ nwa mbụ nwoke mụrụ n''ezinụlọ?', '["Ada","Diọpara","Nwaọbi","Ọdụ nwa"]', 1, '''Diọpara'' (or Opwara) is the title for the first-born son in an Igbo family.', NULL, 'WAEC_Igbo_2024.json', '5100609d4105ec6c788b50983a0e9e73968ccddcfe94b5b7313876190598c857');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ ''Ada'' n''ala Igbo?', '["Nwa mbụ nwaanyị mụrụ n''ezinụlọ","Nwa ikpeazụ","Nwunye eze","Nne nna"]', 0, '''Ada'' is the title for the first-born daughter in an Igbo family.', NULL, 'WAEC_Igbo_2024.json', 'd31a764490a6951bbc782792518ed7cdd1c29ab311e70a11e1ad5599a52f665f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'N''ala Igbo, ''Iru mgbede'' bụ ememme a na-emere _____.', '["Ndị agadi nwoke","Ụmụ nwaanyị na-amaghị nwoke","Ndị agha obodo","Ndị kpuru ìsì"]', 1, '''Iru mgbede'' or ''Fatting room'' was a rite of passage for young women preparing for marriage/womanhood.', NULL, 'WAEC_Igbo_2024.json', 'f268b44a47a2f87d564ed8d43b1e18cf0833cf8c9c6a8774b0fee3381c0d2d92');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị ka a na-eji amata onye nwere echichi ''Ozo'' n''obodo?', '["Ego","Okpu mme mme na mpị nzu","Ncha","Akwụkwọ nri"]', 1, 'Symbols like the red cap (okpu mme mme), elephant tusk (mpị nzu), and ankle threads identify an Ozo titled man.', NULL, 'WAEC_Igbo_2024.json', 'f00713c07d6ad0c53adca8c0047759f9c89843ea989e71bd897b98f054f385a8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ ''Ilu'' n''asụsụ Igbo?', '["Abụ na-atọ ụtọ","Mmanwụ na-agba egwu","Mmanụ e ji eri okwu","Ihe e ji esi nri"]', 2, 'Based on Chinua Achebe''s definition, proverbs (ilu) are the palm oil with which words are eaten.', NULL, 'WAEC_Igbo_2024.json', 'cf3eb899a7b1d6314990f3b9c5021172a3a243a6f330d8904c8fef255f8d06e6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Kammala ilu a: ''Atụrụ mma n''atụ nwanne, ọ rụọ nwanne, _____.''', '["O rụọ di ya","O rụọ nwa","O rụọ onye ọzọ","O rụọ onye tiri ya"]', 2, 'The proverb ''Atụrụ mma n''atụ nwanne, ọ rụọ nwanne, o rụọ onye ọzọ'' warns that whatever harm you wish for your brother will eventually reach you/others.', NULL, 'WAEC_Igbo_2024.json', '7754c00ba5374cc59d513121b9df75acf5a1d6b4f845264269093aff3e5542cf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị ka ilu a pụtara: ''Ụjụjụ riri nne ya ka ọ ga-ata nwa ya ụta?''', '["Na nne dị mkpa","Na mmadụ agaghị ata onye meruru ya ahụ ụta ma ọ bụrụ na ọ dị n''ọbara ha","Na mmadụ agaghị eri nne ya","Na ụjụjụ bụ dinta"]', 1, 'This proverb emphasizes accountability or lack thereof when dealing with inherent traits or internal family issues.', NULL, 'WAEC_Igbo_2024.json', '03cecfac35c8e62a1eaf11dac036f64c922dba4f74b4467d87c346d71979abe9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ ''Akpalaokwu'' (Idiom)?', '["Okwu nkịtị anyị na-ekwu","Okwu nwere nghọta miri emi dị iche na mkpụrụasụsụ ndị ahụ","Abụ","Akụkọ ifo"]', 1, 'Idioms are expressions where the meaning is not deducible from the literal words.', NULL, 'WAEC_Igbo_2024.json', 'e7d48e9261f058f5a52f14d7117c89f482eb9e7eca117be39714515319b9da17');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ nghọta akpalaokwu a: ''Ịta nchara''?', '["Ịta ihe siri ike","Ịta ahụhụ/Ịda ogbenye","Ịta nri ụtọ","Ịta onye ọzọ ụta"]', 1, '''Ịta nchara'' means to suffer or live in extreme poverty.', NULL, 'WAEC_Igbo_2024.json', 'c0baac86c5382de088731d87c754acfa07c5da5a07a2931495637ee4cf554d36');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ ''Akụkọ ifo''?', '["Akụkọ mere eme","Akụkọ efere n''aka na-ezi ihe","Akụkọ banyere ego","Akụkọ banyere agha"]', 1, 'Folktales (Akụkọ ifo) are fictional stories passed down orally, usually involving animals and intended to teach morals.', NULL, 'WAEC_Igbo_2024.json', 'edbe566ab50c8efb4cdc46fd376deb46fe4ac7c0d2aeeed8b31475147e222cc8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Onye bụ onyeisi n''akụkọ ifo Igbo niile?', '["Zaki","Mbe","Atụrụ","Agu"]', 1, '''Mbe'' (Tortoise) is the protagonist and trickster in most Igbo folktales.', NULL, 'WAEC_Igbo_2024.json', 'cc448b6b9d780a19261ee492286e3f23123e35d3752dbb585e9d1d71d358f481');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ ''Mbem''?', '["Abụ na-atọ ụtọ nke nwere udaolu pụrụ iche","Akụkọ banyere di","Ihe e ji ese foto","Ụdị nri"]', 0, 'Mbem is oral poetry or chants often performed by minstrels or elders at events.', NULL, 'WAEC_Igbo_2024.json', '1d9c9a41fb2b999f8a467b6351348253b2d910f88c6acbc071d876d617c3a5f1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Olee onye kacha ama ama n''ide edemede egwuregwu (Drama) n''asụsụ Igbo?', '["Tony Ubesie","Chinedu Ofomata","F.C. Ogbalu","Goddy Onyekaonwu"]', 3, 'Goddy Onyekaonwu is a notable Igbo playwright (writer of drama).', NULL, 'WAEC_Igbo_2024.json', '0bb7489e055271c30e5ce39d0ecd3a94a505dd33a954f5855802e14c0773d68b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ aha mbụ onye malitere idepụta asụsụ Igbo?', '["F.C. Ogbalu","S.A. Ahamba","Chidi Achebe","Flora Nwapa"]', 0, 'F.C. Ogbalu is considered the father of modern Igbo language studies and promotion.', NULL, 'WAEC_Igbo_2024.json', '1655c6263d794622d8d53319064b403018ee1d8fce97e9c392448af50d3cdf43');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Kedu nke bụ ''Agụmagụ a kpara akpa'' (Written literature)?', '["Mbem","Ilu","Akwụkwọ akụkọ (Novel)","Akụkọ ifo"]', 2, 'Written literature (Agụmagụ a kpara akpa) consists of texts recorded in writing, unlike oral literature.', NULL, 'WAEC_Igbo_2024.json', '6c28489b440c9c4e641a26cb090cd845c3c3360874e3609aa093c29d29987ad9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Kedu nke bụ ''Agụmagụ ọnụ'' (Oral literature)?', '["Akwụkwọ akụkọ","Egwuregwu onye dere ede","Ilu na Akụkọ ifo","Edemede ule"]', 2, 'Oral literature is transmitted by word of mouth, including proverbs and folktales.', NULL, 'WAEC_Igbo_2024.json', 'bb92b252458de93a520c20b53104f77870e0ceba9e0c645864bf1ecd511b3993');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Kedu onye dere akwụkwọ ''Isi Akwu Dara n''Ala''?', '["Tony Ubesie","P.N. Itanyi","C.N. Adichie","J.U. Tagbo Nzeako"]', 0, 'Tony Ubesie is the author of this classic Igbo novel.', NULL, 'WAEC_Igbo_2024.json', 'e067b50a8247e3a9a91ef772cee5b388dc581227fa82293c8eacc4854dbae4b4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ ''Mmanwụ'' n''ala Igbo?', '["Nwoke kpuru ihe n''ihu na-anọchite anya ndị mmụọ","Nwa nwaanyị na-agba egwu","Osisi na-eto n''ọhịa","Ihe e ji ebu ozu"]', 0, 'Masquerades (mmanwụ) are believed to be the spirits of ancestors returning to the physical world.', NULL, 'WAEC_Igbo_2024.json', '61600efd3187dce78201b382a300955e6cefe518fed2c13e19b9d0d15959918d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ ''Oji'' n''omenala Igbo?', '["Ihe e ji achụ àjà nani","Ihe nnọchiteanya nnabata na udo","Ihe e ji eri nri abalị","Aha eze"]', 1, 'Kola nut (Oji) is the ultimate symbol of hospitality and peace in Igboland; ''He who brings kola brings life''.', NULL, 'WAEC_Igbo_2024.json', '6d92b77cb1b04f8bbebae254c1dc10e28e261df38a31151266b959383cc93f02');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Ọrụ dinta bụ _____.', '["Ịkụ azụ","Ịgba nta ma ọ bụ igbu anụ ọhịa","Ịkpa ite","Ịrụ ụlọ"]', 1, 'A hunter (dinta) is responsible for hunting animals in the forest.', NULL, 'WAEC_Igbo_2024.json', 'fbd994497f14cc587dc6d8b02397a4b529bfdec01448cd1baf3e3744934ca891');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị ka a na-akpọ nwa mụrụ n''ụbọchị ''Afọ''?', '["Nwafor","Okafor","Mgbafor","Gbogbo ha bụ eziokwu"]', 3, 'Depending on gender and dialect, names like Nwafor, Okafor, or Mgbafor all identify children born on Afọ day.', NULL, 'WAEC_Igbo_2024.json', '0a5cb4a14e0130ae679c50a865f6181ab5cc15eab8b0790ba98894dde13f4b12');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Ịgba mgba n''ala Igbo bụ _____.', '["Iji egbe alụ ọgụ","Egwuregwu ike n''etiti ndị nwoke","Ihe ụmụ nwaanyị na-eme","Ịzụ ahịa"]', 1, 'Wrestling (Ịgba mgba) is a traditional sport used to determine strength and bring honor to one''s community.', NULL, 'WAEC_Igbo_2024.json', '09233e4ec175eb2dcbad9bf4db22e51badce90431036d7d0bccc59dcd2499b12');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ uru ''Ịmụ ọrụ'' (Apprenticeship) baara ndị Igbo?', '["Ọ na-eweta umengwụ","Ọ na-enyere ndị ntorobịa aka ịmụta aka ọrụ na inwe onwe ha","Ọ na-eme ka mmadụ bụrụ onye ohi","Ọ bụ maka ndị na-agaghị ụlọ akwụkwọ nani"]', 1, 'The Igbo apprenticeship system (Igba boi) is globally recognized for fostering entrepreneurship and job creation.', NULL, 'WAEC_Igbo_2024.json', '5a1630cce90cd830af5cc5cf6a982df28f2f43b6b848b7f903a599d3de0a1709');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Kedu otu a na-esi asị mmadụ ''Nnọọ'' n''Igbo Izugbe?', '["I meela","Nnọọ","Daalụ","Ị biela"]', 1, '''Nnọọ'' is the formal welcome or greeting in Standard Igbo.', NULL, 'WAEC_Igbo_2024.json', '1f0fde1381b053e0ca68db405004ffb6799a9cd0ef267cc966684bc13f8658af');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Asụsụ Igbo nwere ụdị mgbochiume wo a kpọrọ ''Uda-anụ'' (Voiced consonants)?', '["b, d, g, v","p, t, k, f","s, sh, h","ọ, ụ, a"]', 0, 'Voiced consonants (uda-anụ) involve the vibration of vocal cords, such as b, d, g, and v.', NULL, 'WAEC_Igbo_2024.json', '2534436c76cbf3fd46e691de5722631f60da46abe37115932be30ff3758bd85d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Kedu mkpụrụasụsụ a kpọrọ ''mgbochiume imi'' (Nasalized consonants)?', '["b, p","m, n, nw, ny","l, r","s, z"]', 1, 'These sounds are produced through the nasal cavity (imi).', NULL, 'WAEC_Igbo_2024.json', '23d3447555208b1e81d065f569c6e96518e451a0276f67927326ff23cfd5aab6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Ahịrịokwu a ''Bịa ebe a!'' bụ ụdị wo?', '["Ahịrịokwu nkwupụta","Ahịrịokwu iwu","Ahịrịokwu ajụjụ","Ahịrịokwu mkpu"]', 1, 'This is an imperative sentence (ahịrịokwu iwu), which issues a command.', NULL, 'WAEC_Igbo_2024.json', 'f44a5aaf068c6861f4c6e0b85b18d0e3596fc1f437aea06183336ac0d760de76');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Ahịrịokwu ''O riri nri?'' bụ ụdị wo?', '["Ahịrịokwu ajụjụ","Ahịrịokwu iwu","Ahịrịokwu nkwupụta","Ahịrịokwu njirimara"]', 0, 'An interrogative sentence (ahịrịokwu ajụjụ) ends with a question mark and asks for information.', NULL, 'WAEC_Igbo_2024.json', 'cfb9d7c0475ac3c50d875931fe97d1cc355d83d1628167affbe298b405ed8576');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Mkpụrụokwu ''Akwụkwọ'' nwere sillebu ole?', '["Abụọ","Anọ","Atọ","Ise"]', 2, 'A-kwụ-kwọ has three syllables.', NULL, 'WAEC_Igbo_2024.json', '1214eee79dfb3094cfac2069734e68991cdbbaf83cfcffc6e7743ba2c411f459');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Olee mgbe a na-asị mmadụ ''Ka chi fo''?', '["N''ụtụtụ","N''ehihie","N''anyasị tupu a lakpuo ụra","N''oge udu mmiri"]', 2, '''Ka chi fo'' is ''Good night'', used when parting in the evening.', NULL, 'WAEC_Igbo_2024.json', '14761ef233809b04cb5a97077e96a4508f83b6483418263474f4cbf84c74deed');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'N''ala Igbo, gịnị bụ ''Chi''?', '["Mmụọ nche onye ọ bụla nwere","Nri e ji eri nri","Aha osisi","Ego"]', 0, 'In Igbo cosmology, ''Chi'' is an individual''s personal guardian spirit or divine spark.', NULL, 'WAEC_Igbo_2024.json', 'a282ce156d15e678e5c29503f33b92b6e25d375918f7b78daf31b9900e1c70a2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Kedu onye n''ezinụlọ na-elekọta ezinụlọ na inye iwu?', '["Nne","Nna","Nwa ikpeazụ","Onye agbata obi"]', 1, 'The father (nna) is traditionally the head and authority figure of the Igbo household.', NULL, 'WAEC_Igbo_2024.json', '4577a660d9bca0e8d9d369ebfb52ddacf8f7f1e2234791c622e4709c515373ec');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Asụsụ Igbo gụnyere ''Udamkpọ'' (Vowel harmony). Gịnị ka ọ pụtara?', '["Ịgụ egwu","Udaume ịbịa n''ìgwè abụọ dị iche n''otu mkpụrụokwu","Ịgba mgba","Iri nri"]', 1, 'Vowel harmony (udamkpọ) dictates that vowels from one set (Light/Heavy) do not usually mix with the other set in a word root.', NULL, 'WAEC_Igbo_2024.json', '958459f918c342fb99c1fdbb8b5207c931ef29618e1a4f4716b958e7accfe4c4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ ''Abụ''?', '["Edemede gbasara akụkọ","Okwu a kpara akpa nwere nhazi na udaolu","Egwuregwu na-atọ ọchị","Aha dinta"]', 1, 'Poetry (Abụ) consists of rhythmic, well-organized speech often using figurative language.', NULL, 'WAEC_Igbo_2024.json', 'e7041605d88274881963311cf90e7c3b24ae7fb5ba66bb4f3f094203aa6c3cd4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Gịnị bụ ''Nsonazụ'' (Suffix)?', '["Mgbakwunye na-abịa n''azụ mkpụrụokwu","Mgbakwunye na-abịa n''ihu","Ngwaa","Aha"]', 0, 'A suffix (nsonazụ) is added to the end of a word root to modify its meaning or function.', NULL, 'WAEC_Igbo_2024.json', 'e77a9cded5d8c3eabe4e463f1636dc3897e5c34f79729b7c1488813264bfc380');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Kammala ilu a: ''Atụrụ mma n''atụ nwanne, ọ rụọ nwanne, _____.''', '["O rụọ di ya","O rụọ onye ọzọ","O rụọ mgbeke","O rụọ mmiri"]', 1, 'Repeating this common proverb for reinforcement: what affects a brother affects another.', NULL, 'WAEC_Igbo_2024.json', '04283e23c3f1b1ae56816048edc5af1720270bae25e0383c5ea08817952a2054');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Olee asụsụ e ji dee akwụkwọ ''Omenụkọ''?', '["Bekee","Igbo","Hausa","Yoruba"]', 1, 'Omenụkọ, by Pita Nwana, was the first novel written in the Igbo language.', NULL, 'WAEC_Igbo_2024.json', 'ac840b910d769920d86f108d7b57bbf5bbd6a4ec30079eab7bbfcb4f6e672962');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2024, NULL, 'Ịmụta asụsụ Igbo dị mkpa maka _____.', '["Inwe ọrụ","Inwe nghọta banyere omenala na njirimara ndị Igbo","Ịnweta ego","Ịbụ onye amamihe"]', 1, 'Learning the language is vital for cultural identity and preservation of Igbo heritage.', NULL, 'WAEC_Igbo_2024.json', '3515bf86bab4c23083c35c72f9794ffacc10d4f4a08e9ee18f9476a67627c72c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Gịnị bụ ''Noun''?', '["Nkeaha","Ngwaa","Nkọwa","Nnọchiaha"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', '0b26ce7a4dd26e4fe5f3361c65550e054af3b06e53cc7874f8851ae94eb8343a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Ònye dere ''Omenuko''?', '["Pita Nwana","Chinua Achebe","F.C. Ogbalu","Tony Ubesie"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', '142f90d63e27371967d931ed699ac262ef4ef1bbeb881a537ae94f29f2680c66');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Gịnị bụ ''Verb''?', '["Ngwaa","Nkeaha","Nkọwa","Mbukumba"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', 'cb815821e789c75e34c26d6a59996f1d8e308e92e490754acc73b10eb25762cc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Eze n''ala Igbo:', '["Igwe/Eze","Oba","Emir","Obong"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', 'aab07eb9fb3d69ac0191bd10f8e784a041dea2a1233d05b8a483f2714df71bd1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, '''Ije Odumodu Jere'' bụ maka:', '["Njem","Agha","Ịhụnanya","Azụmahịa"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', '1b51e9831d0ba6c11b3db961ed1353f1f44f854ae9a96422beccc042f04ba07f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Gịnị bụ ''Market''?', '["Ahịa","Ụlọ","Ụlọ akwụkwọ","Ụlọ ụka"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', '14f2eff7ea71fc7213c4d5957a1ce53a6cdfa7ef231680203ab9995bc4a8bc8a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Gịnị bụ ''Plural''?', '["Ọtụtụ","Otu","Abụọ","Ole"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', '8a671224c104ab809c9c603eb8c9e703be5ac808f136f0a2d79b9b56a9e2d1e9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Nna nna ndị Igbo:', '["Eri","Oduduwa","Bayajidda","Nri"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', 'a5ee896c63ab2b559e3fb0f34daaa82e94c736a6af9193894d902995fec9730c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Gịnị bụ ''Money''?', '["Ego","Akwa","Nri","Mmiri"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', '71c4f2882e03264ec51ea37499ef303c6ec81a7ad734473a4ed15da281054cd8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Gịnị bụ ''Father''?', '["Nna","Nne","Nwanne","Nwunye"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', 'e2fb4c0dd5eb495caa6a808bb11c96e68f349183f450b6268613a00ed77f7a85');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Gịnị bụ ''Welcome''?', '["Nnọọ","Ka chi fo","Gaa nke ọma","Daalụ"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', 'ea6ac33beec0daf93626ac2b6b9959e3a5184065b54470da6699a79bfe4b77a5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Nri ndị Igbo:', '["Akpụ/Fufu","Tuwo","Amala","Starch"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', 'd3ac4456677a3e4c70ba81037a45d0ec5c147e3abab136670c3cda6f017bd32a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Gịnị bụ ''Pronoun''?', '["Nnọchiaha","Nkeaha","Ngwaa","Nkọwa"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', '85abf9c1df2d48f2ae3c68d0d26baeeefd489cb81f9548b058b89b426d5536cf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Obodo ''Iri Ji'' na-ewu:', '["Ala Igbo","Ala Yoruba","Ala Hausa","Ala Edo"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', 'b9b848364d82c9ff960ef651e15c0ae94bf6eab8647e5b71ccfee4180ec7be90');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Mkpụrụokwu ụdaolu:', '["8","5","6","10"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', '22e7e7727e260e3a12f6c82b08ca775110a304f967ba49ae4860b089fa685376');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Gịnị bụ ''Water''?', '["Mmiri","Ọkụ","Ikuku","Ala"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', 'a72b8c78eeb08881728352c5803234cd93b2c304045fec1e8d90cfbc87ee032f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Gịnị bụ ''Sun''?', '["Anyanwụ","Ọnwa","Kpakpando","Igwe"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', 'e5806080a8cf499d139e0f1b8e9cca091eb4d1a48741cba57d87278fba0e80f8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Igbo', 2025, NULL, 'Ilu: ''Chọọ ewu ojii...''', '["Mgbe chi ka dị","N''abalị","Mgbe o riri nri","N''ụtụtụ"]', 0, NULL, NULL, 'WAEC_Igbo_2025.json', 'af531eb7a400e5346f4a1b943ad1071be661710fc8770001c95a15ed4780f5c5');
