INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The use of a word whose sound suggests its meaning is known as _____.', '["Onomatopoeia","Oxymoron","Alliteration","Assonance"]', 0, 'Onomatopoeia is a literary device where the word itself mimics the natural sounds of a thing, such as ''buzz'' or ''hiss''.', NULL, 'WAEC_Literature_2024.json', 'a6dd8b0a4b63b1c6fc706eb3a376d106af50798d4495e407bde9c2669b66337a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A speech made by a character alone on stage to reveal their inner thoughts is a/an _____.', '["Aside","Prologue","Soliloquy","Epilogue"]', 2, 'A soliloquy is a dramatic convention where a character speaks to themselves, revealing thoughts that the audience hears but other characters do not.', NULL, 'WAEC_Literature_2024.json', 'a43139d35b4d61f84e6ae8070e0054b84555a8410a3c9fbada6b70e3476eed5b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The struggle between two opposing forces in a literary work is called _____.', '["Climax","Conflict","Denouement","Exposition"]', 1, 'Conflict is the essence of plot; it can be internal (man vs self) or external (man vs man/nature/society).', NULL, 'WAEC_Literature_2024.json', 'b7b40ccfb6ebbff8810a6bc6c0a770dfa1cacdb44cd8b80dc5d005dfce833141');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'Identify the figure of speech in: ''The sun peeped over the mountain''.', '["Simile","Metaphor","Personification","Hyperbole"]', 2, 'Personification gives human qualities (peeping) to inanimate objects (the sun).', NULL, 'WAEC_Literature_2024.json', 'c957371865d9caeac98262b79db5f0f067516bad81972dcaf48d8e9e0bdc2efc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A poem of fourteen lines with a strict rhyme scheme is a _____.', '["Ode","Elegy","Ballad","Sonnet"]', 3, 'A sonnet is a fixed verse form of 14 lines, typically in iambic pentameter, common in Shakespearean or Petrarchan styles.', NULL, 'WAEC_Literature_2024.json', 'a3b00b30157c8f48f3f5f1beabce6352b69b8c949f8450c63cb5197fb56528ac');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The passage above is set in _____.', '["Lagos","London","New York","Accra"]', 1, 'The excerpt explicitly mentions ''The cold of London'' and refers to the experiences of Adah, the protagonist of Emecheta''s ''Second Class Citizen''.', 'Adah was a ''second-class citizen'' in a country that was supposed to be her haven. The cold of London was not just in the weather, but in the eyes of the landlords who posted signs saying ''No Blacks, No Dogs, No Irish''.', 'WAEC_Literature_2024.json', '77a90a09cf2cc3f9cfcd54fe987a47d167452b8df1d807dcd5a21deab413fd7d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The landlord''s signs mentioned in the passage illustrate _____.', '["Hospitality","Racial discrimination","Environmental policy","Religious intolerance"]', 1, 'The exclusion of ''Blacks'' alongside ''Dogs'' highlights the systemic racism and dehumanization faced by immigrants in post-war Britain.', 'Adah was a ''second-class citizen'' in a country that was supposed to be her haven. The cold of London was not just in the weather, but in the eyes of the landlords who posted signs saying ''No Blacks, No Dogs, No Irish''.', 'WAEC_Literature_2024.json', 'df4d2819b7bcf281e44ba446723a503e772d9ee7e33bf14cd312071dd8f90b77');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The phrase ''second-class citizen'' suggests _____.', '["Diplomatic status","Inferior social standing","Aristocratic background","Illegal residency"]', 1, 'It refers to a person who is systematically discriminated against within a state or other political jurisdiction, despite their nominal status as a citizen or resident.', 'Adah was a ''second-class citizen'' in a country that was supposed to be her haven. The cold of London was not just in the weather, but in the eyes of the landlords who posted signs saying ''No Blacks, No Dogs, No Irish''.', 'WAEC_Literature_2024.json', '1b51a44b0a98daa837c1d2b785f21c63191abb71d8e7060de0d1cc35fce1e61c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A light or humorous play that ends happily is a _____.', '["Tragedy","Comedy","Melodrama","Farce"]', 1, 'In classical literary terms, a comedy is defined by its lighthearted tone and a resolution that involves the triumph of the protagonist, often ending in marriage.', NULL, 'WAEC_Literature_2024.json', '90af43987b7ae41d92e5978f1ba6ac1c36faf84c9d996bdf94f2157d86d53f3e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The error in judgment or character flaw that leads to the downfall of a tragic hero is _____.', '["Hamartia","Catharsis","Hubris","Peripeteia"]', 0, 'Hamartia is the Greek term for ''tragic flaw''. While Hubris (excessive pride) is a type of hamartia, hamartia is the general term for the error.', NULL, 'WAEC_Literature_2024.json', '2dabec28fe3220048b0483d59e9ffd5bfed023d0d38c689f6958d57ed36215cd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In poetry, the repetition of vowel sounds is called _____.', '["Alliteration","Consonance","Assonance","Onomatopoeia"]', 2, 'Assonance is the repetition of similar vowel sounds within close proximity, such as ''the light of the fire is a sight''.', NULL, 'WAEC_Literature_2024.json', '5787b66053f3e3c1bcbf2382564c56a6260c4bf8f214cf1e0720bcdb12f5cffd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A story in which characters and events represent abstract qualities or moral meanings is a/an _____.', '["Fable","Allegory","Parody","Satire"]', 1, 'An allegory, like Bunyan''s ''Pilgrim''s Progress'' or Orwell''s ''Animal Farm'', uses symbolic figures to convey a deeper message.', NULL, 'WAEC_Literature_2024.json', '603654d061669ef83b8653ec236b954f2ed1a4559d5a8ece4bfb90fa4ca4d815');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In Buchi Emecheta''s Second Class Citizen, why does Adah marry Francis?', '["She loves him deeply","To enable her to continue her education","Her parents forced her","He was the wealthiest suitor"]', 1, 'Adah views marriage primarily as a means to achieve her dream of going to the United Kingdom and furthering her education, as single women faced more restrictions.', NULL, 'WAEC_Literature_2024.json', '87c4560e324edc949f2e71cca14bcb0a58ba82b2a962e0aff4631974edba9d05');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'Which character in Unexpected Joy at Dawn represents the theme of identity crisis across borders?', '["Nii Tackie","Mama Orojo","Massa","Marshak"]', 0, 'Nii Tackie is a Ghanaian by blood but lives in Nigeria, and later faces the ''alien'' status in both countries during the deportation eras.', NULL, 'WAEC_Literature_2024.json', 'b3acf035c3cf1b853e698bde609b85489f6fdaa8897c8bf393aeccd03f5ac016');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The atmosphere or emotional aura of a work is its _____.', '["Theme","Plot","Mood","Style"]', 2, 'Mood refers to the feeling created in the reader by a literary work or passage.', NULL, 'WAEC_Literature_2024.json', '03c0ba0b2f1f814ae850e4cd15e5a6322e731c9548a540a0f1bf8b1ff4f7f986');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In Drama, the purging of emotions (pity and fear) experienced by the audience is _____.', '["Anagnorisis","Catharsis","Exposition","Suspense"]', 1, 'Aristotle defined catharsis as the emotional release felt by the audience at the end of a tragedy.', NULL, 'WAEC_Literature_2024.json', 'a80ef6d2a0a12007a7ff2d8fa1fbb7496b84d23a8e810b8ff1beb2b53fa77a43');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A statement that appears self-contradictory but reveals a truth is a _____.', '["Paradox","Oxymoron","Irony","Euphemism"]', 0, 'A paradox is a statement that seems impossible but contains a hidden truth, such as ''The child is father of the man''.', NULL, 'WAEC_Literature_2024.json', 'aa12eb88081c48b0905eb3210b8ee9b626b63b04f581f2518e78438d70b2ae30');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The literary device used to give a hint of what is to happen later in a story is _____.', '["Flashback","In media res","Foreshadowing","Juxtaposition"]', 2, 'Foreshadowing provides clues or hints to prepare the reader for future events in the plot.', NULL, 'WAEC_Literature_2024.json', 'c93e8293fec69a82365c0d3cf3d87147f30e7165d52c788b83770b028ef2afe0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A mournful poem, typically a lament for the dead, is an _____.', '["Ode","Elegy","Epic","Limerick"]', 1, 'An elegy is a poem of serious reflection, typically a lament for the deceased.', NULL, 'WAEC_Literature_2024.json', 'e540523585df6289a69af1ca4606883b0a9aea3da291f3d3ac2d1e1c8c94fe6f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In Wole Soyinka''s The Lion and the Jewel, Baroka is the _____.', '["School teacher","Bale of Ilujinle","The Jewel","The Photographer"]', 1, 'Baroka is the ''Lion'', the Bale (village head) of Ilujinle, who competes for Sidi''s hand.', NULL, 'WAEC_Literature_2024.json', 'd503cd8e0f7bffc6e55da8656511f819a5ffcbc8e0d4f5030cc8753c92243f0b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'Sidi refuses to marry Lakunle because he _____.', '["Is too old","Is poor","Refuses to pay the bride price","Is a foreigner"]', 2, 'Sidi insists on the bride price as a measure of her worth in tradition; Lakunle considers it a ''barbarous'' custom and refuses.', NULL, 'WAEC_Literature_2024.json', '5301fbdd58dea3b18e3eb23300b2ee06e6156cd61bbc3b7561c4ad9442230a5b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The character who provides a contrast to the protagonist is the _____.', '["Antagonist","Foil","Confidant","Hero"]', 1, 'A foil is a character whose traits are the opposite of the protagonist''s, thereby highlighting the protagonist’s characteristics.', NULL, 'WAEC_Literature_2024.json', 'f29267d60ace776112b8eb3cdb99caec77024fdf0d5ffbdd9f0574891e271e80');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A long narrative poem celebrating the deeds of a legendary hero is an _____.', '["Epic","Ode","Ballad","Lyric"]', 0, 'Epics like The Odyssey or Beowulf are grand in scale and focus on heroic figures and national myths.', NULL, 'WAEC_Literature_2024.json', 'e1d7a0dd58a0e1250bba90779a8bfcef4a47c9dc0e2eb79e2ebc4a72c6078b10');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, '''Parting is such sweet sorrow'' is an example of _____.', '["Hyperbole","Oxymoron","Litotes","Metonymy"]', 1, 'Oxymoron joins two contradictory terms (''sweet'' and ''sorrow'') to create a paradoxical effect.', NULL, 'WAEC_Literature_2024.json', 'e92ce3f0695654d8bc8b3aba3103ccc20f1411cadb970974f9986e51970ed2d6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In Let Me Die Alone, Yoko''s decision to commit suicide is driven by _____.', '["Fear of the warriors","Humiliation and false accusations","Loss of her beauty","Hatred for her husband"]', 1, 'Queen Yoko commits suicide after being falsely accused of killing a child and realizing the treachery within her chiefdom.', NULL, 'WAEC_Literature_2024.json', '0b9f5fe37de5abd88fc091c839e9a25ab9025e6cda9b852b14ace66d31107766');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The protagonist of Ralph Ellison''s Invisible Man is invisible because _____.', '["He is a ghost","He wears a special suit","Society refuses to see him as a human being","He lives underground"]', 2, 'The invisibility is metaphorical; it represents the racial prejudice that prevents white society from acknowledging his individuality and humanity.', NULL, 'WAEC_Literature_2024.json', '5fdd9e315840f67e658b59bb2e942673371b8798d92928d32619560f8f7161bf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A poem written in praise of a person, object, or event is a/an _____.', '["Elegy","Ode","Sonnet","Satire"]', 1, 'An ode is a formal, often ceremonial lyric poem that addresses and often celebrates a person, place, thing, or idea.', NULL, 'WAEC_Literature_2024.json', '4f188686dd151b8313615e853daa70392e1e1abbc680345ba6ef0c37e4300fcd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In Emily Brontë''s Wuthering Heights, the primary setting represents _____.', '["Urban chaos","The wildness of nature and human passion","Religious stability","Industrial progress"]', 1, 'The moors and the house ''Wuthering Heights'' signify the stormy, untamed nature of Heathcliff and Catherine''s love.', NULL, 'WAEC_Literature_2024.json', '357eca4763d0054dc758436342843f0ac9bd382a0745bcceaaff9083ecf43f97');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The rhyme scheme of a typical Shakespearean sonnet is _____.', '["abba abba cde cde","abab cdcd efef gg","aabb ccdd eeff gg","abcd abcd abcd ee"]', 1, 'The Shakespearean (English) sonnet consists of three quatrains and a final rhyming couplet.', NULL, 'WAEC_Literature_2024.json', 'afdcce742747621cb8ef13eded9a772f8e6ff4012d98c7a6d998fa495cbf9668');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The person who tells the story in a novel is the _____.', '["Author","Narrator","Protagonist","Antagonist"]', 1, 'The narrator is the voice or character through which the author tells the story; the narrator is not necessarily the author.', NULL, 'WAEC_Literature_2024.json', '70a20036fc733ae98b08989a9c404cdb9f8d58a0358d672322b4a9bb32b50059');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, '''The white house issued a statement'' is an example of _____.', '["Synecdoche","Metonymy","Irony","Personification"]', 1, 'Metonymy replaces the name of a thing with the name of something else with which it is closely connected (the building representing the administration).', NULL, 'WAEC_Literature_2024.json', '829d5552e21aa26231bd86111d1e2cb897d4ae938118cefd8fc3b691e5c6ffab');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In Look Back in Anger, Jimmy Porter''s ''anger'' is primarily directed at _____.', '["His wife''s upper-middle-class background","The educational system","The government of America","His best friend Cliff"]', 0, 'Jimmy Porter represents the ''Angry Young Men'' of the 1950s, railing against the complacency of the British class system represented by Alison''s family.', NULL, 'WAEC_Literature_2024.json', '7ceb3c689a84837c106ee87ad4afe0341de5789809ada22b3ecafc0e9ee451d6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The use of ''thou'' and ''thee'' in older literature are examples of _____.', '["Neologisms","Archaic language","Slang","Jargon"]', 1, 'Archaisms are words or styles of language that are no longer in everyday use but are used for literary effect.', NULL, 'WAEC_Literature_2024.json', '7038be17d68c3f6617bdebd7d5edc0d0b68273b533a4a48d8611cd9fa032e297');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A story that teaches a moral lesson using animals as characters is a/an _____.', '["Parable","Fable","Myth","Legend"]', 1, 'Fables, such as Aesop''s, utilize anthropomorphized animals to deliver a moral truth.', NULL, 'WAEC_Literature_2024.json', '9142cefe6b0353427e8bf91b985828115f091973c246139c0a783191b906b04f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In the poem ''The Grieved Lands'', the tone is one of _____.', '["Joy and celebration","Resilience and defiance","Indifference","Humor"]', 1, 'Agostinho Neto''s poem speaks to the suffering and strength of the African people under colonial oppression.', NULL, 'WAEC_Literature_2024.json', '6a9e96288f72f54fdb19f2b62d9bc3a7723de1209d2019a33ae225271ca52166');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The repetition of consonant sounds at the beginning of words is _____.', '["Assonance","Onomatopoeia","Alliteration","Pun"]', 2, 'Alliteration is the repetition of the same initial consonant sounds in a sequence of words, like ''Peter Piper picked a peck''.', NULL, 'WAEC_Literature_2024.json', '7343c15844ba48b3a7f2b3c078493c5744005f5ac87d020924a891b37bc51a7c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In Fences, Troy Maxson''s ''fence'' symbolizes _____.', '["His carpentry skills","Emotional barriers and protection of his family","His wealth","The boundary of the city"]', 1, 'The fence is a central metaphor for keeping people out (death, change) and keeping people in (family, legacy).', NULL, 'WAEC_Literature_2024.json', '48749d4e70ae7b09367f8e76001dba48121f70f1ae3e1da5acc79494884a6a7b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The climax of a plot is the _____.', '["Beginning of the story","Point of highest tension","Resolution of the conflict","Introduction of characters"]', 1, 'The climax is the turning point of the story where the conflict reaches its peak intensity.', NULL, 'WAEC_Literature_2024.json', '1b6ed40be908ac75a7163423db5e09a1b68524c6f3bd4491d29ec07b0f08a714');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A play on words that sound similar but have different meanings is a _____.', '["Sarcasm","Pun","Euphemism","Understatement"]', 1, 'A pun exploits different possible meanings of a word or the fact that there are words which sound alike but have different meanings.', NULL, 'WAEC_Literature_2024.json', '730f8112b0ba36f82b1bf3ba98ea8c9844d3f1dd4c9509dd7929015ba35e8eda');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The main theme of ''Caged Bird'' by Maya Angelou is _____.', '["The beauty of nature","The struggle for freedom vs oppression","The importance of singing","The history of aviation"]', 1, 'The poem contrasts a free bird with a caged bird to illustrate the African American experience of captivity and longing for liberty.', NULL, 'WAEC_Literature_2024.json', '69e2d65f359ed56ac812fab40befd9451693d7e348281b10af8474b8000289f3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'An exaggerated statement not meant to be taken literally is _____.', '["Litotes","Hyperbole","Simile","Synecdoche"]', 1, 'Hyperbole is an intentional exaggeration used for emphasis or comic effect, like ''I''ve told you a million times''.', NULL, 'WAEC_Literature_2024.json', '03976a39864ab0104948d33ac3adee463ebeb3018eeb0259016d1d17a9b94c1b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In prose, the method of describing a character''s traits is _____.', '["Plotting","Characterization","Setting","Narration"]', 1, 'Characterization is the process by which the writer reveals the personality of a character, either directly or indirectly.', NULL, 'WAEC_Literature_2024.json', '9d0a6858abf6e9d80e7f8d498651157d38fa765a85909c517b11664d7b102d87');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The ''Grave Diggers'' scene in Shakespeare''s Hamlet provides _____.', '["Tragic climax","Comic relief","Exposition","Epilogue"]', 1, 'Comic relief is a humorous scene included in a tragedy to provide a temporary emotional break for the audience.', NULL, 'WAEC_Literature_2024.json', '9fdd1ea88d826ebfb202a26a0056d577d818fb86fce566d78bc92a7b1ab39170');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A reference to a well-known person, place, or event from history or literature is an _____.', '["Allusion","Illusion","Allegory","Apostrophe"]', 0, 'An allusion is a brief and indirect reference to a person, place, thing or idea of historical, cultural, literary or political significance.', NULL, 'WAEC_Literature_2024.json', '31a0018a0f7008435dd9b35a6929e58e6e5b862008f5cc7fd6546ed97db71a42');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In ''The Leader and the Led'', the animals are looking for _____.', '["Food","A leader","A new home","War"]', 1, 'Niyi Osundare''s poem uses animals to satirize the quest for leadership in Africa and the qualities required of a true leader.', NULL, 'WAEC_Literature_2024.json', 'd8ab0bfa53a07907b3d95c9e0b0a60da4ab44082718611a3411537d243a91ec6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The central character in a story is the _____.', '["Antagonist","Protagonist","Foil","Deuteragonist"]', 1, 'The protagonist is the main figure or one of the most prominent figures in a real situation or a story.', NULL, 'WAEC_Literature_2024.json', 'df4653ecab4d42486a862d82bf7a2a8ebf5e9c32dfd911891be4b536dd7210eb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A poem that tells a story, often meant to be sung, is a _____.', '["Limerick","Ballad","Haiku","Elegy"]', 1, 'A ballad is a type of narrative poem that is typically structured with four-line stanzas and tells a folk tale or legend.', NULL, 'WAEC_Literature_2024.json', '012103ef23f76c6f4a64e419f58af0941d0b50e33e8acfef7ad7f628c5db2303');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The resolution of the plot in a story is also called the _____.', '["Rising action","Climax","Denouement","Falling action"]', 2, 'Denouement is the final part of a play, film, or narrative in which the strands of the plot are drawn together and matters are explained or resolved.', NULL, 'WAEC_Literature_2024.json', '788955fcc6a4743dc1ca7a30397dbd37a7273846cc2cd075789f7a9df77661b6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In Second Class Citizen, the ''burning of the manuscript'' symbolizes _____.', '["Francis''s support for Adah","The destruction of Adah''s intellectual and creative dreams","An accident in the house","A ritual cleaning"]', 1, 'Francis burns Adah''s novel, The Bride Price, which represents his jealousy and his attempt to suppress her independence and success.', NULL, 'WAEC_Literature_2024.json', 'ac3168262947faa900d77c70a1e276c5ebd8fc71c0f6ccbb6aa4a1d59c4bcaa5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The term ''In media res'' means _____.', '["Starting at the beginning","Starting in the middle of things","Starting at the end","A story with no end"]', 1, '''In media res'' is a narrative technique where the story opens in the midst of action, rather than from the chronological beginning.', NULL, 'WAEC_Literature_2024.json', '7562bc92ce99ca253f6cac749f0a1e7f5d71a3158de0ff5e189a541ec63195c0');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'An address to an absent person or a personified object is an _____.', '["Alliteration","Apostrophe","Assonance","Anaphora"]', 1, 'Apostrophe is a figure of speech in which the poet addresses an absent person, an abstract idea, or a thing (e.g., ''O wild West Wind'').', NULL, 'WAEC_Literature_2024.json', 'e9242ce612fa0117e2f5db5bdd791338c9ac7a78e4dec45bf6d89e2d5fef2f48');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'Which of these is a characteristic of African traditional oral literature?', '["Written in Latin","Emphasis on performance and communal participation","Always written by one author","Strictly for children"]', 1, 'Oral literature (orature) thrives on live performance, audience interaction, and is passed down through generations.', NULL, 'WAEC_Literature_2024.json', '95c91712836931462143583761508895fe7e28cf02c1724a307d11c844c6e79e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In Look Back in Anger, what instrument does Jimmy Porter play?', '["Piano","Trumpet","Violin","Guitar"]', 1, 'Jimmy Porter plays the trumpet, which serves as an auditory symbol of his noisy, disruptive, and ''angry'' presence.', NULL, 'WAEC_Literature_2024.json', '2cf49b153be7e791af96b80f67b98568280efbe6f2c49f7cf4b50dd521023bef');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The comparison of two unlike things using ''like'' or ''as'' is a _____.', '["Metaphor","Simile","Metonymy","Synecdoche"]', 1, 'A simile is an explicit comparison, while a metaphor is an implicit one.', NULL, 'WAEC_Literature_2024.json', '859d587b4918d89fb0c4f181dd44f9708ae57f9a3d6d5a937f8276084dd94d58');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A poem with no regular meter or rhyme scheme is called _____.', '["Blank verse","Free verse","Couplet","Quatrain"]', 1, 'Free verse poetry does not follow strict rules of rhythm or rhyme, allowing for more natural speech-like patterns.', NULL, 'WAEC_Literature_2024.json', 'a7af4b67a56632faea4b7a7e04aaa39bb0e25db66193778547b9eb24e29d3ddd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The pattern of end rhymes in a poem is the _____.', '["Rhythm","Meter","Rhyme Scheme","Stanza"]', 2, 'The rhyme scheme is labeled with letters (e.g., AABB) to represent the sounds at the end of each line.', NULL, 'WAEC_Literature_2024.json', 'b6c3358bf4465ad5a407e4d778c7ffb7ac28c7a0dc26d6dd27b5daeb86a016f2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In drama, a character whose fate is determined by a supernatural power or the gods is common in _____.', '["Modern comedy","Greek tragedy","Farce","Satire"]', 1, 'In classical Greek tragedy, the concept of ''Fate'' or ''Destiny'' is a central force that the hero cannot escape.', NULL, 'WAEC_Literature_2024.json', '6699ae4a6026e83468e97bebd5dd0c3c17c5acfa62b5a3fe17f5b516411712ed');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The use of a part to represent the whole is _____.', '["Metonymy","Synecdoche","Hyperbole","Simile"]', 1, 'Synecdoche is a figure of speech in which a part is made to represent the whole or vice versa (e.g., ''all hands on deck'' where ''hands'' means ''men'').', NULL, 'WAEC_Literature_2024.json', 'ae2bb8ae4d36bfd626144cd84c31f6cd8dd531585d314b4d46d00383885801cd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In Wuthering Heights, Heathcliff is described as a _____ hero.', '["Byronic","Epic","Tragic","Reluctant"]', 0, 'A Byronic hero is a moody, rebellious, and dark figure with a troubled past, fitting Heathcliff’s character perfectly.', NULL, 'WAEC_Literature_2024.json', 'd330390e3427c0f6b61f5a9edb57d5fd925921d3d6451bfb4e2b9d8a9d13cb0a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The moral or message of a literary work is its _____.', '["Theme","Motif","Style","Subject"]', 0, 'A theme is a central idea or underlying message that the author explores throughout the text.', NULL, 'WAEC_Literature_2024.json', 'a575e9caac12e1962fcd1c96138f00e00638765b59e23a9834d8077cc94ce138');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A short, clever statement of a wise or witty truth is an _____.', '["Epigram","Epic","Epitaph","Epilogue"]', 0, 'An epigram is a pithy saying or remark expressing an idea in a clever and amusing way.', NULL, 'WAEC_Literature_2024.json', '667d3855e74e7b81607757e259d492a7385d17c8d750338d4803d2ecd099e0ef');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In ''The Good-Morrow'', John Donne compares the lovers to _____.', '["Soldiers at war","Hemispheres or maps","Birds in a cage","Flowers in spring"]', 1, 'As a Metaphysical poet, Donne uses a ''conceit'' (an elaborate metaphor) comparing the lovers'' faces to two better hemispheres.', NULL, 'WAEC_Literature_2024.json', '08aea270a1c83ad9a893fd2e9c6d9e94ca603f5e3ec914115a5b18fe083b6195');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'An unrhymed poem written in iambic pentameter is _____.', '["Free verse","Blank verse","Sonnet","Haiku"]', 1, 'Blank verse is a standard form for English dramatic and epic poetry, famously used by Shakespeare and Milton.', NULL, 'WAEC_Literature_2024.json', '9ffa2e2f78df081c8f0f9c500e9f4f5914e00e75927b8ffb060ec6f6467f5fb8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The repetition of a word or phrase at the beginning of successive clauses is _____.', '["Epistrophe","Anaphora","Chiasmus","Litotes"]', 1, 'Anaphora is used for emphasis and rhythm, common in speeches and religious texts (e.g., ''I have a dream...'').', NULL, 'WAEC_Literature_2024.json', '6c4c4c1ca9c7d4d4edfb4a818184f7a44257bc09eaeec76f2f83e38ef64eb46e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In ''Journey of the Magi'', the journey represents _____.', '["A fun vacation","A spiritual transition and the pain of birth and death","A business trip","Military conquest"]', 1, 'T.S. Eliot explores the internal conflict of the Magi as they witness the end of their old pagan world and the birth of Christianity.', NULL, 'WAEC_Literature_2024.json', '53e6f9778aa5b26aa5cb501a2f4cc5a78ab6b69162e3a5f6de8225aa9665c6f3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A comic imitation of a serious work is a _____.', '["Satire","Parody","Fable","Tragedy"]', 1, 'Parody imitates the style of a particular writer, artist, or genre with deliberate exaggeration for comic effect.', NULL, 'WAEC_Literature_2024.json', 'ead56d284fa79d2d9f749e57e6360aa1309005e054195c210ff259baaf92d974');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'A play that ridicules the vices and follies of society is a _____.', '["Melodrama","Farce","Satire","Opera"]', 2, 'Satire uses humor, irony, and exaggeration to expose and criticize people''s stupidity or vices.', NULL, 'WAEC_Literature_2024.json', 'daa4f36ffee7f583b94c6009fd60f337dc22d4d886263d186b0992617e897663');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The term used for the ''dictionary meaning'' of a word is _____.', '["Connotation","Denotation","Imagery","Context"]', 1, 'Denotation is the literal meaning; connotation is the emotional or cultural association attached to the word.', NULL, 'WAEC_Literature_2024.json', 'ab29d2a0b02585e4388bb4ae98387740652e3e8b5eee34a7518d566c6f4e4ec1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'In Unexpected Joy at Dawn, the ''aliens'' are _____.', '["Creatures from space","Ghanaians in Nigeria and Nigerians in Ghana","Europeans in Africa","Politicians"]', 1, 'The title and story refer to the Alien Compliance Order and the reciprocal expulsions of West African migrants.', NULL, 'WAEC_Literature_2024.json', '1a09e3f8a2055ffe56f9c27dc9004e1263a41f26d96cf8e55d9ec99fa768650c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'The ''voice'' in a poem is the _____.', '["Author","Persona","Audience","Narrator"]', 1, 'In poetry, the speaker or ''persona'' is the character assumed by the poet.', NULL, 'WAEC_Literature_2024.json', '6c8ff43f5a174710c486348141f5b51f3061a345507006898a55d966ab400075');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2024, NULL, 'Identify the device in ''He is no fool''.', '["Hyperbole","Litotes","Simile","Sarcasm"]', 1, 'Litotes is an ironical understatement in which an affirmative is expressed by the negative of its contrary (stating ''no fool'' to mean ''wise'').', NULL, 'WAEC_Literature_2024.json', '84dd02b9bf350e0709fa0ce6d601ccf14e6e36a0673468c2194f1e535bc0cfb3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2025, NULL, 'The phrase ''howl like a wounded animal'' is a:', '["Metaphor","Simile","Personification","Hyperbole"]', 1, NULL, '<b>The Storm</b><br><br>The sky turned a bruised purple as the wind began to howl like a wounded animal. Trees bent in submission, their branches scraping the ground in a desperate plea for mercy. Amaka hurriedly gathered the drying clothes, her wrapper whipping furiously around her legs. Thunder rumbled, a deep, angry growl from the belly of the clouds, followed by a blinding flash that tore the sky apart. It was not just a rainstorm; it was nature declaring war on the village.', 'WAEC_Literature_2025.json', 'adda52c506d6916f05bdea77b2f468907c31cf8d7959b0dd2e8e81c6cc8821ba');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2025, NULL, 'The atmosphere in the passage is:', '["Peaceful","Chaotic and threatening","Joyful","Boring"]', 1, NULL, '<b>The Storm</b><br><br>The sky turned a bruised purple as the wind began to howl like a wounded animal. Trees bent in submission, their branches scraping the ground in a desperate plea for mercy. Amaka hurriedly gathered the drying clothes, her wrapper whipping furiously around her legs. Thunder rumbled, a deep, angry growl from the belly of the clouds, followed by a blinding flash that tore the sky apart. It was not just a rainstorm; it was nature declaring war on the village.', 'WAEC_Literature_2025.json', '801979c44a2ba29f3741bc6900abd1f408f4ff90c3b59e55733e4421aae821a9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2025, NULL, '''Nature declaring war on the village'' is an example of:', '["Hyperbole","Litotes","Irony","Euphemism"]', 0, NULL, '<b>The Storm</b><br><br>The sky turned a bruised purple as the wind began to howl like a wounded animal. Trees bent in submission, their branches scraping the ground in a desperate plea for mercy. Amaka hurriedly gathered the drying clothes, her wrapper whipping furiously around her legs. Thunder rumbled, a deep, angry growl from the belly of the clouds, followed by a blinding flash that tore the sky apart. It was not just a rainstorm; it was nature declaring war on the village.', 'WAEC_Literature_2025.json', 'ba77a67424da484f1438ed1e0a1d50a4efbfc4500471aaa57270c50af5c47a79');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2025, NULL, 'The word ''submission'' implies that the trees were:', '["Fighting back","Yielding/Defeated","Breaking","Growing"]', 1, NULL, '<b>The Storm</b><br><br>The sky turned a bruised purple as the wind began to howl like a wounded animal. Trees bent in submission, their branches scraping the ground in a desperate plea for mercy. Amaka hurriedly gathered the drying clothes, her wrapper whipping furiously around her legs. Thunder rumbled, a deep, angry growl from the belly of the clouds, followed by a blinding flash that tore the sky apart. It was not just a rainstorm; it was nature declaring war on the village.', 'WAEC_Literature_2025.json', '0657d4524f7e1a1b0b796dd6cca4ccf2165744a59bc013c2e3973dc1002cd35f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2025, NULL, 'The thunder is described using the literary device of:', '["Personification","Alliteration","Oxymoron","Pun"]', 0, NULL, '<b>The Storm</b><br><br>The sky turned a bruised purple as the wind began to howl like a wounded animal. Trees bent in submission, their branches scraping the ground in a desperate plea for mercy. Amaka hurriedly gathered the drying clothes, her wrapper whipping furiously around her legs. Thunder rumbled, a deep, angry growl from the belly of the clouds, followed by a blinding flash that tore the sky apart. It was not just a rainstorm; it was nature declaring war on the village.', 'WAEC_Literature_2025.json', '5945aae8aefb2e53ab456967a513104a06f6b999355407166fed51d9384a3f2d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Literature', 2025, NULL, 'A poem of fourteen lines is called a:', '["Ballad","Sonnet","Ode","Elegy"]', 1, NULL, NULL, 'WAEC_Literature_2025.json', '746eac98cf5ceef07ceb6a0a8a23de24ba8f347b494a0165eaa86b07fd5cb5b3');
