INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Convert $11011_2$ to base 10.', '["25","26","28","27"]', 3, '$11011_2 = (1 \times 2^4) + (1 \times 2^3) + (0 \times 2^2) + (1 \times 2^1) + (1 \times 2^0) = 16 + 8 + 0 + 2 + 1 = 27_{10}$.', NULL, 'WAEC_Mathematics_2024.json', 'e82e7f4a863db2e9a674362a3083ba7b08a5f43c05e597838029fa4726df8602');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Evaluate $(3 \times 4) \pmod 5$.', '["2","1","3","4"]', 0, 'First multiply: $3 \times 4 = 12$. Then convert to modulo 5 by finding the remainder when 12 is divided by 5: $12 \div 5 = 2$ remainder $2$. Thus, it is $2 \pmod 5$.', NULL, 'WAEC_Mathematics_2024.json', 'abaec4dfd143d749022999a932885897532be6e8735c1f853c94a3564d9b50b3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Simplify $0.0025 \times 0.04$ and express your answer in standard form.', '["$1.0 \\times 10^{-3}$","$1.0 \\times 10^{-4}$","$1.0 \\times 10^{-5}$","$1.0 \\times 10^4$"]', 1, '$0.0025 = 2.5 \times 10^{-3}$ and $0.04 = 4 \times 10^{-2}$. Multiplying them: $(2.5 \times 4) \times 10^{-3 + -2} = 10 \times 10^{-5} = 1.0 \times 10^{-4}$.', NULL, 'WAEC_Mathematics_2024.json', '684c377d46729eee11213fbdea2858bc2e179c823f1be6414a0481f221d98c07');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Simplify $\sqrt{72} - \sqrt{32}$.', '["$3\\sqrt{2}$","$\\sqrt{2}$","$2\\sqrt{2}$","$4\\sqrt{2}$"]', 2, 'Simplify the surds first: $\sqrt{36 \times 2} - \sqrt{16 \times 2} = 6\sqrt{2} - 4\sqrt{2} = 2\sqrt{2}$.', NULL, 'WAEC_Mathematics_2024.json', '1e4621ca9d72c321afe72bdb58c2fbcb5581b7ddd0b21a450fa4fcfa6f141f5a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Given $A = \{1, 2, 3\}$ and $B = \{2, 3, 4\}$, find $A \cap B$.', '["$\\{1, 4\\}$","$\\{1, 2\\}$","$\\{3, 4\\}$","$\\{2, 3\\}$"]', 3, 'The intersection of sets A and B ($A \cap B$) contains elements present in both sets. Both sets contain 2 and 3. Therefore, $A \cap B = \{2, 3\}$.', NULL, 'WAEC_Mathematics_2024.json', '704bed7a9c99c7f8c6b0ca36ffbdae3b9be37c63a9d7ef66c696371d337a7649');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'A trader buys an item for $₦4000$ and sells it for $₦5000$. Find the percentage profit.', '["25%","20%","30%","40%"]', 0, 'Profit = Selling Price - Cost Price = $₦5000 - ₦4000 = ₦1000$. Percentage Profit = $(\frac{1000}{4000}) \times 100 = 25\%$.', NULL, 'WAEC_Mathematics_2024.json', 'fb490560ebfd7333078f953a30a1b522bf430b68406667713b03f0f68a06df61');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the simple interest on $₦10,000$ for 2 years at 5% per annum.', '["$₦500$","$₦1000$","$₦1500$","$₦2000$"]', 1, '$I = \frac{PRT}{100} = \frac{10000 \times 5 \times 2}{100} = \frac{100000}{100} = ₦1000$.', NULL, 'WAEC_Mathematics_2024.json', 'ed386011eb5e618c171a0d0503582e5acba34d543a73847fccb4c7c7fb158563');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Simplify $16^{\frac{3}{4}}$.', '["4","16","8","2"]', 2, '$16^{\frac{3}{4}} = (\sqrt[4]{16})^3$. Since $2^4 = 16$, the 4th root of 16 is 2. Therefore, $2^3 = 8$.', NULL, 'WAEC_Mathematics_2024.json', '0390266c309efd16d8b5d25d8fd41d184d4b7ba8ccb0bae6e16750dfa1abcbde');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Simplify $\log_{10} 25 + \log_{10} 4$.', '["1","3","4","2"]', 3, 'Addition of logarithms with the same base means multiplying the arguments: $\log_{10}(25 \times 4) = \log_{10}(100) = 2$.', NULL, 'WAEC_Mathematics_2024.json', '1c4ef2c1b5f94140545d0eaaeff53667f0fad46521d47f2d9ff43d5354123616');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'If $y \propto x$ and $y = 10$ when $x = 2$, find $y$ when $x = 5$.', '["25","20","30","35"]', 0, 'Since $y = kx$, $10 = k(2)$, so the constant $k = 5$. When $x = 5$, $y = 5 \times 5 = 25$.', NULL, 'WAEC_Mathematics_2024.json', '1040e4ce3826af41e27cd82a800f614003909918fa531f815974837061628c21');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Divide 45 in the ratio 2:3.', '["15, 30","18, 27","20, 25","22, 23"]', 1, 'Total ratio = $2 + 3 = 5$. First share = $\frac{2}{5} \times 45 = 18$. Second share = $\frac{3}{5} \times 45 = 27$.', NULL, 'WAEC_Mathematics_2024.json', 'da099c62483a754ceef04f113c10d0190fc87c4660e8d202d3aaed226e8cbcd6');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the value of $\frac{2}{3} + \frac{1}{4} - \frac{1}{2}$.', '["$\\frac{1}{12}$","$\\frac{7}{12}$","$\\frac{5}{12}$","$\\frac{11}{12}$"]', 2, 'The LCM of 3, 4, and 2 is 12. $\frac{8}{12} + \frac{3}{12} - \frac{6}{12} = \frac{8 + 3 - 6}{12} = \frac{5}{12}$.', NULL, 'WAEC_Mathematics_2024.json', '6e0804a29b60fdf3a7517f124e7eda6b45ce07a008463e16ffea39afa6f47809');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Approximate 0.0456 to 2 significant figures.', '["0.050","0.045","0.04","0.046"]', 3, 'The first significant figure is 4, the second is 5. The next digit is 6, which rounds the 5 up to 6. Hence, 0.046.', NULL, 'WAEC_Mathematics_2024.json', '0b05d688a1300c72ae46d659cff23824393f06dc4bf253ac79ba4d3c15c14b52');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Evaluate $34_5 + 23_5$.', '["$112_5$","$121_5$","$111_5$","$102_5$"]', 0, 'Adding in base 5: $4+3=7$ (Write $2$, carry $1$). $3+2+1=6$ (Write $1$, carry $1$). Therefore, the sum is $112_5$.', NULL, 'WAEC_Mathematics_2024.json', '5c5c324f367f165efc807c58abb5dec0581320d84529865610d7c2ca50f89716');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Solve for x: $\log_2 x = 3$.', '["4","8","6","9"]', 1, 'Convert the logarithmic equation to an exponential one: $x = 2^3 = 8$.', NULL, 'WAEC_Mathematics_2024.json', '9b2169b37cdd8a0e1cd58498bf70c445366047e9afba39b3424db30f442b772e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Factorize completely: $2x^2 - 8$.', '["$(2x-4)(2x+4)$","$2(x-4)(x+4)$","$2(x-2)(x+2)$","$(x-2)(x+2)$"]', 2, 'First factor out 2: $2(x^2 - 4)$. Then factor the difference of two squares: $2(x-2)(x+2)$.', NULL, 'WAEC_Mathematics_2024.json', 'cd56bf076f837882ab204d7e686a1302db5335a67598ba12dee7769cdc28bafd');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Simplify the algebraic fraction: $\frac{x^2 - y^2}{x + y}$.', '["$x+y$","$x^2-y$","$y-x$","$x-y$"]', 3, 'Expand the difference of two squares: $\frac{(x-y)(x+y)}{x+y}$. Cancel out $(x+y)$ to leave $x-y$.', NULL, 'WAEC_Mathematics_2024.json', 'a029458c3ca295dea2f994d19b130f4ef62943ad8ef506e7dfb54cfa0535ca9f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Make $r$ the subject of the formula: $A = \pi r^2$.', '["$r = \\sqrt{\\frac{A}{\\pi}}$","$r = \\frac{A}{\\pi}$","$r = \\frac{\\pi}{A}$","$r = \\sqrt{\\frac{\\pi}{A}}$"]', 0, 'Divide both sides by $\pi$ to get $r^2 = \frac{A}{\pi}$. Then take the square root of both sides to get $r = \sqrt{\frac{A}{\pi}}$.', NULL, 'WAEC_Mathematics_2024.json', '4f5541f0446731c73cda5b0b779becffff963843f484d2be0e176291f88a7260');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Solve the equation: $3(x - 2) = 15$.', '["5","7","3","9"]', 1, 'Divide both sides by 3: $x - 2 = 5$. Add 2 to both sides: $x = 7$.', NULL, 'WAEC_Mathematics_2024.json', 'de65c694a62461a0f5dc49d14cb275dfe2df1fc805f0ff2e0f80ca0c154c4adf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Solve simultaneously: $x+y=5$ and $x-y=1$.', '["$(2,3)$","$(4,1)$","$(3,2)$","$(1,4)$"]', 2, 'Adding both equations: $2x = 6 \implies x = 3$. Substitute $x=3$ into $x+y=5$, giving $3+y=5 \implies y=2$.', NULL, 'WAEC_Mathematics_2024.json', 'c95871005451485fb9f0d45bacc07c03a4035c9ac4e6410e6d891cac5eacce5b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the roots of the quadratic equation: $x^2 - 5x + 6 = 0$.', '["$-2, -3$","$-1, -6$","$1, 6$","$2, 3$"]', 3, 'Factorize the quadratic: $(x-2)(x-3) = 0$. Therefore, $x=2$ or $x=3$.', NULL, 'WAEC_Mathematics_2024.json', '30a934c4d93f479d1b272f0f0686ccc60dba66590a8b1b8c5a7eb4a86bfb5b4f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Solve the inequality: $2x - 5 < 7$.', '["$x < 6$","$x > 6$","$x \\leq 6$","$x \\geq 6$"]', 0, 'Add 5 to both sides: $2x < 12$. Divide by 2: $x < 6$.', NULL, 'WAEC_Mathematics_2024.json', 'cf8373d831f938dd97d6ab3f39cdeb90d8c3f8c28d658bf79712561a22d8e505');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the remainder when $x^3 - 2x^2 + x - 5$ is divided by $x-1$.', '["5","-5","-3","3"]', 1, 'Using the remainder theorem, substitute $x=1$ into the polynomial: $f(1) = 1^3 - 2(1)^2 + 1 - 5 = 1 - 2 + 1 - 5 = -5$.', NULL, 'WAEC_Mathematics_2024.json', '020c0cd42c4df5d34ee399979ecdff58532438deb535b9adcf95bd27acce385f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the 5th term of the Arithmetic Progression: 2, 5, 8, ...', '["11","17","14","20"]', 2, 'The formula is $u_n = a + (n-1)d$. Here $a=2, d=3, n=5$. $u_5 = 2 + 4(3) = 2 + 12 = 14$.', NULL, 'WAEC_Mathematics_2024.json', 'c40e316351d08e22d51226aa104517d5515a4107d4c8fa65268d17f982b4440c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the sum to infinity of the Geometric Progression: 4, 2, 1, ...', '["6","10","4","8"]', 3, 'Sum to infinity $S = \frac{a}{1-r}$. Here $a=4, r=0.5$. $S = \frac{4}{1 - 0.5} = \frac{4}{0.5} = 8$.', NULL, 'WAEC_Mathematics_2024.json', 'e14b597d017cd6d2f5021e43edb12f753163abb970a5c8ee968e784cca30088b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Calculate the sum of the first 10 terms of the sequence 1, 3, 5, ...', '["100","90","110","50"]', 0, 'Using $S_n = \frac{n}{2}(2a + (n-1)d)$. $n=10, a=1, d=2$. $S_{10} = 5(2(1) + 9(2)) = 5(2+18) = 5(20) = 100$.', NULL, 'WAEC_Mathematics_2024.json', 'f88115b40d3ffb6343af3e7bf68599292d72d94e3f3e96e069a4eb6b230a86cf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the determinant of the matrix $\begin{pmatrix} 3 & 2 \\ 4 & 5 \end{pmatrix}$.', '["-7","7","10","23"]', 1, 'Determinant = $(3 \times 5) - (2 \times 4) = 15 - 8 = 7$.', NULL, 'WAEC_Mathematics_2024.json', 'ea5709d7d0e16a595f662387ab9cdfa805f947687226ff2d23767cbc556f38a1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'If the determinant of $\begin{pmatrix} x & 3 \\ 2 & x \end{pmatrix}$ is -5, find the positive value of $x$.', '["2","3","1","4"]', 2, 'Determinant = $x^2 - 6$. So, $x^2 - 6 = -5 \implies x^2 = 1$. The positive value is $x = 1$.', NULL, 'WAEC_Mathematics_2024.json', '688b2207ca7946ef28931d6b08d39a5bc21ffd9d91b00b87f0b3b781fdd664d2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the sum of the roots of the equation $2x^2 - 5x + 3 = 0$.', '["$-\\frac{5}{2}$","$\\frac{3}{2}$","$-\\frac{3}{2}$","$\\frac{5}{2}$"]', 3, 'For $ax^2 + bx + c = 0$, the sum of roots $\alpha + \beta = -\frac{b}{a}$. Here, $a=2, b=-5$. Sum = $-(\frac{-5}{2}) = \frac{5}{2}$.', NULL, 'WAEC_Mathematics_2024.json', 'b3be50eb3c676498a0ebd95d1f892494a91ae554b87e261480960be7548a79e7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'A binary operation is defined by $x * y = x^2 + y$. Evaluate $3 * 4$.', '["13","12","10","15"]', 0, 'Substitute $x=3, y=4$ into the operation: $3^2 + 4 = 9 + 4 = 13$.', NULL, 'WAEC_Mathematics_2024.json', '9521a3ac73091579e43db2a470b5e67854d38279b94a945a54604b475d76de0b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Simplify $(x+2)^2 - x^2$.', '["$4x$","$4x+4$","$4x-4$","$2x+4$"]', 1, 'Expand the square: $x^2 + 4x + 4 - x^2$. The $x^2$ terms cancel out, leaving $4x + 4$.', NULL, 'WAEC_Mathematics_2024.json', '9c52b9735153fb44b4a00f32ecc478f5ea371e8203a1d4d5c9c440282ae38d00');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Which of these shapes is defined by the region $x \geq 0, y \geq 0, x+y \leq 4$?', '["Rectangle","Square","Triangle","Trapezium"]', 2, 'The boundaries $x=0$ (y-axis), $y=0$ (x-axis), and the line $x+y=4$ enclose a right-angled triangle in the first quadrant.', NULL, 'WAEC_Mathematics_2024.json', 'fb33b5a160530c96655287b0f374d91b1020f444b90542f03ba02f686bb94459');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'For what values of $x$ is the fraction $\frac{x+2}{x^2 - 4}$ undefined?', '["$2$ only","$-2$ only","$4$","$\\pm 2$"]', 3, 'A fraction is undefined when its denominator is zero. $x^2 - 4 = 0 \implies x^2 = 4 \implies x = \pm 2$.', NULL, 'WAEC_Mathematics_2024.json', 'b552ff063b8f474c7f33fb9b2b6fe3e3d09651e5b29b9536a9ce8239cb5bd903');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Solve for x: $\sqrt{2x + 1} = 3$.', '["4","3","5","8"]', 0, 'Square both sides: $2x + 1 = 9$. Subtract 1: $2x = 8$. Divide by 2: $x = 4$.', NULL, 'WAEC_Mathematics_2024.json', '6b7bbd93477c0fbfb87d0b4fc01a69b4d2a226685640bbb1485d2b521387324f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Solve for x: $2^x = \frac{1}{8}$.', '["3","-3","-2","2"]', 1, 'Express $\frac{1}{8}$ as a power of 2: $\frac{1}{2^3} = 2^{-3}$. Therefore, $2^x = 2^{-3}$, giving $x = -3$.', NULL, 'WAEC_Mathematics_2024.json', '14e084696373fbb34da2f2d5440948b36b50b3ea856f0c5d966e232fc219065b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'The angles of a triangle are $3x$, $4x$, and $5x$. Find the largest angle.', '["$45^\\circ$","$60^\\circ$","$75^\\circ$","$90^\\circ$"]', 2, 'The sum of angles in a triangle is $180^\circ$. $3x + 4x + 5x = 12x = 180 \implies x=15$. The largest angle is $5(15) = 75^\circ$.', NULL, 'WAEC_Mathematics_2024.json', '0208b41a94dc1b942fd20516070431bbb59dd15e1862a7e6c7b8f8a20b419af3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the sum of the interior angles of a regular hexagon.', '["$360^\\circ$","$540^\\circ$","$900^\\circ$","$720^\\circ$"]', 3, 'Formula: $(n-2) \times 180^\circ$. For a hexagon, $n=6$. $(6-2) \times 180^\circ = 4 \times 180^\circ = 720^\circ$.', NULL, 'WAEC_Mathematics_2024.json', '81694468d043ad2e14b68122d8c3c2f03a644d845f5cd04c957696d0099de432');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'If the angle subtended by an arc at the circumference is $40^\circ$, what is the angle subtended at the center?', '["$80^\\circ$","$20^\\circ$","$60^\\circ$","$40^\\circ$"]', 0, 'The angle at the center is twice the angle at the circumference. $2 \times 40^\circ = 80^\circ$.', NULL, 'WAEC_Mathematics_2024.json', 'b183f9f589c7a308466dc76ab35fe592be45260473eeebd85bad0952ff1aa4e7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'If $\sin \theta = \frac{3}{5}$ and $\theta$ is acute, find $\cos \theta$.', '["$\\frac{3}{4}$","$\\frac{4}{5}$","$\\frac{5}{4}$","$\\frac{5}{3}$"]', 1, 'Using a right-angled triangle, Opp=3, Hyp=5. By Pythagoras, Adj = $\sqrt{5^2 - 3^2} = 4$. So, $\cos \theta = \frac{Adj}{Hyp} = \frac{4}{5}$.', NULL, 'WAEC_Mathematics_2024.json', 'bb16a90d7aa45453732eb2462b17000cb42ea90962be71d5521a22d76c8ccd27');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'In triangle ABC, $a=5$, $\sin A = 0.5$, and $\sin B = 0.8$. Find $b$.', '["6","10","8","12"]', 2, 'Using the Sine Rule: $\frac{a}{\sin A} = \frac{b}{\sin B}$. $\frac{5}{0.5} = \frac{b}{0.8} \implies 10 = \frac{b}{0.8} \implies b = 10(0.8) = 8$.', NULL, 'WAEC_Mathematics_2024.json', 'c03f4ccbaab044af54b7ad6bc68d7278cf81df502dd26040887caa93aeafc735');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the distance between the points $(1,2)$ and $(4,6)$.', '["3","4","7","5"]', 3, 'Distance formula: $\sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2} = \sqrt{(4-1)^2 + (6-2)^2} = \sqrt{3^2 + 4^2} = \sqrt{25} = 5$.', NULL, 'WAEC_Mathematics_2024.json', '82ad0750244e67c992f12da53614eea95f43463c84207845b4294031247e9828');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the gradient of the line passing through $(2,3)$ and $(4,7)$.', '["2","$\\frac{1}{2}$","-2","$-\\frac{1}{2}$"]', 0, 'Gradient $m = \frac{y_2 - y_1}{x_2 - x_1} = \frac{7-3}{4-2} = \frac{4}{2} = 2$.', NULL, 'WAEC_Mathematics_2024.json', '25fbe99df033b591eb937390b67bac647a0ab1ef0f50b4a8ac0054b3500bc738');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'What is the gradient of a line parallel to the line $y = 3x + 4$?', '["-3","3","$\\frac{1}{3}$","$-\\frac{1}{3}$"]', 1, 'Parallel lines have the same gradient. The equation is in $y = mx + c$ form, where $m=3$. Thus, the parallel gradient is 3.', NULL, 'WAEC_Mathematics_2024.json', 'c1f1c48805eb08c479b00d8f9c0e0273c220f9b6bf7833ae389235da801f1a4d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'If town A is on a bearing of $040^\circ$ from town B, what is the bearing of B from A?', '["$140^\\circ$","$040^\\circ$","$220^\\circ$","$320^\\circ$"]', 2, 'Back bearing = Given bearing + $180^\circ$ (if given $< 180$). $040^\circ + 180^\circ = 220^\circ$.', NULL, 'WAEC_Mathematics_2024.json', '522c45149cc10862282cab7fbbfac945490779db8c6feb6a53d840f50ee914ba');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'A pole 10m high casts a shadow 10m long. Find the angle of elevation of the sun.', '["$30^\\circ$","$60^\\circ$","$90^\\circ$","$45^\\circ$"]', 3, '$\tan \theta = \frac{\text{Opposite}}{\text{Adjacent}} = \frac{10}{10} = 1$. The angle whose tangent is 1 is $45^\circ$.', NULL, 'WAEC_Mathematics_2024.json', 'cb533685ee18bd1c3e95f0f7c74c1a0a6bfcee5821585df4e22cc1e710b1cf60');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Simplify $1 - \sin^2 \theta$.', '["$\\cos^2 \\theta$","$\\tan^2 \\theta$","$\\sec^2 \\theta$","$\\sin^2 \\theta$"]', 0, 'From the fundamental trigonometric identity $\sin^2 \theta + \cos^2 \theta = 1$, we derive $1 - \sin^2 \theta = \cos^2 \theta$.', NULL, 'WAEC_Mathematics_2024.json', '26486abae3fdc397733f1753ac73170c6a878c940dc5ec2ebf49237e3155a10c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'The angle subtended by a diameter at the circumference of a circle is:', '["$45^\\circ$","$90^\\circ$","$60^\\circ$","$180^\\circ$"]', 1, 'By circle theorems, the angle in a semicircle (subtended by the diameter) is always a right angle ($90^\circ$).', NULL, 'WAEC_Mathematics_2024.json', '541f60c187066212ce303085eccd8345ebb749e131c5e32dcb0f6ed8e6f842db');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'The exterior angle of a regular polygon is $36^\circ$. How many sides does it have?', '["8","12","10","15"]', 2, 'The sum of exterior angles of any polygon is $360^\circ$. Number of sides $n = \frac{360^\circ}{36^\circ} = 10$.', NULL, 'WAEC_Mathematics_2024.json', '216841ecb5ff549ea3220aaf2513f780ba4db641bdb76b4921a3d54f1e553d45');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'In a cyclic quadrilateral, one angle is $110^\circ$. Find the size of the opposite angle.', '["$110^\\circ$","$90^\\circ$","$80^\\circ$","$70^\\circ$"]', 3, 'Opposite angles of a cyclic quadrilateral are supplementary (they sum to $180^\circ$). $180^\circ - 110^\circ = 70^\circ$.', NULL, 'WAEC_Mathematics_2024.json', '4dae0fdc9198d7eb51aa9bbf06435bf0aa00172280acf8fb376deb91d882ffe5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'What is the equation of a line passing through the origin with a gradient of 4?', '["$y = 4x$","$y = 4$","$x = 4$","$y = x + 4$"]', 0, 'The equation is $y = mx + c$. At the origin $(0,0)$, $c = 0$. Given $m = 4$, the equation is $y = 4x$.', NULL, 'WAEC_Mathematics_2024.json', '12607939de224308967f7aebaa48760d646c409116f70fd256d5f9364e3e742c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Calculate the area of a circle of radius 7cm (Take $\pi = \frac{22}{7}$).', '["$44\\text{ cm}^2$","$154\\text{ cm}^2$","$308\\text{ cm}^2$","$616\\text{ cm}^2$"]', 1, 'Area $A = \pi r^2 = \frac{22}{7} \times 7^2 = \frac{22}{7} \times 49 = 154\text{ cm}^2$.', NULL, 'WAEC_Mathematics_2024.json', '97120858698f18b022bb2584eab19c15153c7d12f32d2eb667f678f893fd0316');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the volume of a cylinder of radius 3cm and height 7cm (Take $\pi = \frac{22}{7}$).', '["$132\\text{ cm}^3$","$264\\text{ cm}^3$","$198\\text{ cm}^3$","$396\\text{ cm}^3$"]', 2, 'Volume $V = \pi r^2 h = \frac{22}{7} \times 3^2 \times 7 = 22 \times 9 = 198\text{ cm}^3$.', NULL, 'WAEC_Mathematics_2024.json', '4f4b66f2929ffdd0ebe0bd5b5c53fc61280ada905b5c2275416d64e2f34c15cf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the area of a sector of a circle with radius 6cm and angle $60^\circ$.', '["$3\\pi\\text{ cm}^2$","$12\\pi\\text{ cm}^2$","$36\\pi\\text{ cm}^2$","$6\\pi\\text{ cm}^2$"]', 3, 'Area = $\frac{\theta}{360^\circ} \times \pi r^2 = \frac{60}{360} \times \pi \times 6^2 = \frac{1}{6} \times 36\pi = 6\pi\text{ cm}^2$.', NULL, 'WAEC_Mathematics_2024.json', 'ffbab5759750269ee0cb478854e6a46ec00f722f029692f195c1e631a9a0f13e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the difference in longitude between $A(10^\circ N, 20^\circ E)$ and $B(10^\circ N, 40^\circ W)$.', '["$60^\\circ$","$20^\\circ$","$40^\\circ$","$80^\\circ$"]', 0, 'Since point A is in the East and point B is in the West, their difference in longitude is the sum of the angles: $20^\circ + 40^\circ = 60^\circ$.', NULL, 'WAEC_Mathematics_2024.json', 'c847a654ec7009af9e5b32445e4c04fc073ec456fb8d1343f5562dee7ea1a871');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Calculate the surface area of a sphere of radius 7cm (Take $\pi = \frac{22}{7}$).', '["$154\\text{ cm}^2$","$616\\text{ cm}^2$","$308\\text{ cm}^2$","$88\\text{ cm}^2$"]', 1, 'Surface Area = $4\pi r^2 = 4 \times \frac{22}{7} \times 7^2 = 4 \times 22 \times 7 = 616\text{ cm}^2$.', NULL, 'WAEC_Mathematics_2024.json', 'af98a2d04c99689ca5696ecaa541a3477144ad5dba72ab26d7e57e44f13d2930');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the derivative of $y = 3x^2 - 2x + 1$ with respect to x.', '["$6x+2$","$3x-2$","$6x-2$","$6x$"]', 2, 'Using the power rule: $\frac{dy}{dx} = 2(3)x^{2-1} - 1(2)x^{1-1} + 0 = 6x - 2$.', NULL, 'WAEC_Mathematics_2024.json', 'd4a18884a4f374241d0f8df00c81caff0acde63fb414e927ca95f77441f9de18');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Evaluate the indefinite integral $\int 2x dx$.', '["$2x^2+c$","$x+c$","$2+c$","$x^2+c$"]', 3, 'Using the integration power rule: $\int 2x dx = \frac{2x^2}{2} + c = x^2 + c$.', NULL, 'WAEC_Mathematics_2024.json', '95e327b633e37ea4e1d95f192e8962812e50d6a61d60fcf69313a2d254bbfc49');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the maximum value of $y = 4x - x^2$.', '["4","2","6","8"]', 0, 'Differentiate and set to 0 to find the turning point: $\frac{dy}{dx} = 4 - 2x = 0 \implies x=2$. Substitute $x=2$ back into $y$: $y = 4(2) - (2)^2 = 8 - 4 = 4$.', NULL, 'WAEC_Mathematics_2024.json', '00b77c5043e2b03ba893a3d3085ea1127494d26e02ec0f0e91f28b6ec3701a38');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Calculate the perimeter of a sector of radius 7cm and angle $90^\circ$ (Take $\pi = \frac{22}{7}$).', '["11cm","25cm","18cm","36cm"]', 1, 'Arc length = $\frac{90}{360} \times 2 \times \frac{22}{7} \times 7 = \frac{1}{4} \times 44 = 11$. Perimeter = Arc length + 2(radius) = $11 + 7 + 7 = 25\text{ cm}$.', NULL, 'WAEC_Mathematics_2024.json', 'a28d63cb3cac04bb28746d3308ef8b9b491cb773c676edf131e700dee0009d5a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the area of a trapezium with parallel sides 4cm and 6cm, and a perpendicular height of 5cm.', '["$20\\text{ cm}^2$","$30\\text{ cm}^2$","$25\\text{ cm}^2$","$50\\text{ cm}^2$"]', 2, 'Area = $\frac{1}{2} (a+b)h = \frac{1}{2}(4+6) \times 5 = \frac{1}{2}(10) \times 5 = 25\text{ cm}^2$.', NULL, 'WAEC_Mathematics_2024.json', '1b08f710fd94e3e675274526c951c2b06e146232b6e681970af1d97404cfa1d9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the mean of the numbers: 2, 4, 6, 8, 10.', '["5","7","8","6"]', 3, 'Mean = $\frac{\text{Sum}}{\text{Count}} = \frac{2+4+6+8+10}{5} = \frac{30}{5} = 6$.', NULL, 'WAEC_Mathematics_2024.json', '4de7b58076504405e8c7ad38b7462807ab145efd22d7e700933c7f0b08b7cdeb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the median of the set: 3, 1, 4, 2, 5.', '["3","2","4","5"]', 0, 'First sort the data: 1, 2, 3, 4, 5. The middle value is 3.', NULL, 'WAEC_Mathematics_2024.json', 'bdc28f1d7670a1bfa222328281e876ed3d0b62c5eab318700d1e1ce5701b8783');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Determine the mode of this data: 2, 3, 3, 4, 5, 3, 2.', '["2","3","4","5"]', 1, 'The mode is the number that appears most frequently. 3 appears three times, more than any other number.', NULL, 'WAEC_Mathematics_2024.json', '84dce8c3b5b58868f6c1aba05651885157a710f928a03f253457e406b0242b47');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'A coin is tossed twice. What is the probability of getting exactly one head?', '["$\\frac{1}{4}$","$\\frac{3}{4}$","$\\frac{1}{2}$","1"]', 2, 'Sample space: {HH, HT, TH, TT}. Outcomes with exactly one head: {HT, TH}. Probability = $\frac{2}{4} = \frac{1}{2}$.', NULL, 'WAEC_Mathematics_2024.json', '3c9db56971c809ec93e14b0c99ada9b21bb347814a6209e863279d7fa40e6043');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Two fair dice are thrown. Find the probability of scoring a sum of 7.', '["$\\frac{1}{12}$","$\\frac{1}{8}$","$\\frac{1}{4}$","$\\frac{1}{6}$"]', 3, 'There are 36 possible outcomes. Pairs summing to 7 are: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1). Total = 6 ways. Prob = $\frac{6}{36} = \frac{1}{6}$.', NULL, 'WAEC_Mathematics_2024.json', '88445a8312cbc76c745825c190312a5b9fd1197514a95f361770b8c16ea2e4d9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'Find the range of the following set of numbers: 12, 5, 18, 3, 9.', '["15","12","13","14"]', 0, 'Range = Maximum value - Minimum value = $18 - 3 = 15$.', NULL, 'WAEC_Mathematics_2024.json', '6f07cb5530e5c985a4919c113dd99262f1bb894d4e3a095e2e6557124ca58758');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'In a pie chart representing 72 students, if 12 students study Physics, what is the sectorial angle for Physics?', '["$30^\\circ$","$60^\\circ$","$45^\\circ$","$90^\\circ$"]', 1, 'Angle = $(\frac{\text{Frequency}}{\text{Total}}) \times 360^\circ = (\frac{12}{72}) \times 360^\circ = \frac{1}{6} \times 360^\circ = 60^\circ$.', NULL, 'WAEC_Mathematics_2024.json', 'a921eaa0ad113ece39716f08ff69ec843928c2f7e2a783238b5ce23d33b41034');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'A and B are independent events. P(A) = 0.4 and P(B) = 0.5. Find P(A and B).', '["0.9","0.4","0.2","0.5"]', 2, 'For independent events, $P(A \text{ and } B) = P(A) \times P(B) = 0.4 \times 0.5 = 0.2$.', NULL, 'WAEC_Mathematics_2024.json', 'ee619a51489850f0e8d610a4948be9f604bdf55ba37dc266a855820bd96847da');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'If the variance of a distribution is 16, what is its standard deviation?', '["8","256","2","4"]', 3, 'Standard Deviation is the square root of the variance. $\sqrt{16} = 4$.', NULL, 'WAEC_Mathematics_2024.json', 'f7277caf5b9125ffe5dae439dd28a13824ef7cbf19ff4fe8ab821c7c5f550987');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Mathematics', 2024, NULL, 'An urn contains 3 red balls and 2 blue balls. A ball is picked at random. Find the probability it is red.', '["$\\frac{3}{5}$","$\\frac{2}{5}$","$\\frac{1}{2}$","$\\frac{1}{5}$"]', 0, 'Total balls = 5. Red balls = 3. Probability of picking red = $\frac{3}{5}$.', NULL, 'WAEC_Mathematics_2024.json', '918a01b921277121935388f06778510449d3efcf424978551d1336c3ac240622');
