INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'The clinical thermometer has a constriction to _____.', '["Make it more sensitive","Prevent mercury from flowing back into the bulb quickly","Protect the bulb","Increase the range of temperature"]', 1, 'The constriction allows the mercury level to stay at the maximum temperature reached until it is shaken down, allowing for a proper reading.', NULL, 'WAEC_Physics_2024.json', '4d48e9b12243d5f8ecf302e98b32587d45278fdd26530db8bbd63733bb0e1c2a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'Which mode of heat transfer does not require a material medium?', '["Conduction","Convection","Radiation","Evaporation"]', 2, 'Radiation transfers energy through electromagnetic waves, which can travel through a vacuum.', NULL, 'WAEC_Physics_2024.json', 'dd3ff0c842f3bd4bd7835a5eed6a734918feada7288c9e7d0fddd673942c9e73');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'The scent of a perfume spreads through a room mainly by the process of _____.', '["Osmosis","Convection","Diffusion","Capillarity"]', 2, 'Diffusion is the movement of particles from a region of higher concentration to lower concentration.', NULL, 'WAEC_Physics_2024.json', '7f786fb6b95e5f9a5de8882071a38f3fd356b0bb5bce2e8d9d3a7f8b8e53f75a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'Water is used as a coolant in car radiators because _____.', '["It is cheap","It has a high specific heat capacity","It is easily available","It is a liquid"]', 1, 'Water''s high specific heat capacity allows it to absorb a large amount of heat with a small rise in its own temperature.', NULL, 'WAEC_Physics_2024.json', '903b874be70f9a1ad44153bb0f41477a7c5be8fcacecbbe7175722eec1515dd4');
