INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'The phenomenon of light bending as it passes from one medium to another is called _____.', '["Reflection","Refraction","Diffraction","Dispersion"]', 1, 'Refraction is caused by the change in speed of light when it enters a medium with a different optical density.', NULL, 'WAEC_Physics_2024.json', '59b8c829b3e2b73c6d1a74bd034ea9b0645807faacd3c8dca1132fae086266a1');
