INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'Which of the following colors of light has the shortest wavelength?', '["Red","Green","Blue","Violet"]', 3, 'In the visible spectrum, Violet has the shortest wavelength (highest frequency) and Red has the longest wavelength.', NULL, 'WAEC_Physics_2024.json', '6277f95b7ee48274f156ef0d238d55b1b3e8adc32b7be5c1e3adfc8c0afdde91');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'The formation of a rainbow is due to _____.', '["Reflection and Diffraction","Refraction and Dispersion","Polarization","Interference"]', 1, 'A rainbow is formed by the refraction and internal reflection of sunlight in water droplets, leading to the dispersion of light into its component colors.', NULL, 'WAEC_Physics_2024.json', 'ad872220aaf3afbd06c4c39a2d67519fc52be3209cd28c27fc7dac4402d9d72b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'A magnifying glass is a _____.', '["Concave lens","Convex lens","Concave mirror","Convex mirror"]', 1, 'A convex (converging) lens forms a magnified, virtual, and erect image when the object is placed within the focal point.', NULL, 'WAEC_Physics_2024.json', 'db2caa643b4366e16fa477bf4af38b544cfb6768d9aae3a70c6f136ddcb5356e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'The persistence of sound after the source has stopped is known as _____.', '["Echo","Reverberation","Resonance","Pitch"]', 1, 'Reverberation is the collection of reflected sounds from the surfaces in an enclosure.', NULL, 'WAEC_Physics_2024.json', 'c2b3dd1ac8fc16a320bd40e2745ba7081f954c8a363b22cd51e22506073cb999');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'Two sound waves of slightly different frequencies produce _____.', '["Echoes","Beats","Harmonics","Overtones"]', 1, 'Beats are produced by the interference of two sound waves of slightly different frequencies, resulting in periodic variations in intensity.', NULL, 'WAEC_Physics_2024.json', 'bed50d8e41357af4b9564b5f5ec0ff2e6e13c835f5c086770d4ed3ba96129266');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'The unit of luminous intensity is the _____.', '["Lumen","Lux","Candela","Watt"]', 2, 'The Candela (cd) is the S.I. unit for luminous intensity.', NULL, 'WAEC_Physics_2024.json', 'cd3dad656b2afcbc55b12a9a5c9fca72bedf703ddca525e70ce64e2ae3c6010a');
