INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'Total internal reflection occurs when light travels from _____.', '["Air to water","Glass to water","Water to glass","Vacuum to air"]', 1, 'Total internal reflection only occurs when light travels from a denser medium to a less dense medium at an angle greater than the critical angle.', NULL, 'WAEC_Physics_2024.json', 'e9373c248b2905ba30f069561542eeb52e6601ef9c1fc5c5cf7c6bcf3e383c03');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'The pitch of a musical note depends on its _____.', '["Amplitude","Frequency","Wavelength","Velocity"]', 1, 'Pitch is the brain''s perception of frequency. High frequency corresponds to high pitch.', NULL, 'WAEC_Physics_2024.json', '2a082a6c064f4ae7d3aa63eed72861c53e00f204a435cd2ae671341c458ebeaa');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'The S.I. unit of electric charge is _____.', '["Ampere","Volt","Coulomb","Ohm"]', 2, 'The Coulomb (C) is the unit of charge, defined as the charge transported by a constant current of one ampere in one second.', NULL, 'WAEC_Physics_2024.json', 'dedda4bbe1e68af9221b6297fbb8b3442ce98d4a30906e8f1a4e69b408b5f813');
