INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'The process of splitting an atom into two smaller nuclei is called _____.', '["Nuclear fusion","Nuclear fission","Radioactivity","Ionization"]', 1, 'Nuclear fission is the process where a heavy nucleus (like Uranium) splits into smaller nuclei, releasing a large amount of energy.', NULL, 'WAEC_Physics_2024.json', 'b9e85c81a986cc340095dc0ebefbba5e35a61ae9251ddcdc3aad1e88800a5c7f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'Which of the following radiations has the highest ionizing power?', '["Alpha particles","Beta particles","Gamma rays","X-rays"]', 0, 'Alpha particles are relatively large and doubly charged, making them very effective at knocking electrons off atoms (ionizing).', NULL, 'WAEC_Physics_2024.json', 'a06e9ba9f132b46f6bcb5eaf11a6ce2a2e1413d2d03e854b865d375724855b6f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'The time taken for half the atoms in a radioactive sample to decay is the _____.', '["Decay constant","Half-life","Mean life","Activity"]', 1, 'Half-life is the characteristic time for a radioactive substance to reduce to half of its initial quantity.', NULL, 'WAEC_Physics_2024.json', 'd10e7016093739589603298c5b38d7653387dbcce6091b8b1b9d643d7b0b52f2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'Which of the following is an isotope of Hydrogen?', '["Helium","Deuterium","Lithium","Beryllium"]', 1, 'Deuterium is an isotope of hydrogen with one proton and one neutron. Tritium is another.', NULL, 'WAEC_Physics_2024.json', 'c4b623366b00f409569270315c41b341efd36bcc377e3a581e20a930e3d5818d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'The photoelectric effect proves the _____.', '["Wave nature of light","Particle nature of light","Refraction of light","Polarization of light"]', 1, 'The photoelectric effect shows that light can behave as discrete packets of energy called photons (particle nature).', NULL, 'WAEC_Physics_2024.json', '2686b419c617b2f0ff2fdccc3931fcfa4cbf04ef10b168bae7f2516f426bda01');
