INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'A step-up transformer increases _____.', '["Power","Current","Voltage","Resistance"]', 2, 'A step-up transformer increases voltage while simultaneously decreasing current (to conserve power).', NULL, 'WAEC_Physics_2024.json', '687df92d6633698d1b81b9c5fcc0fc0f97f76a63c3b00023fc8f0ee7701292c7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'The resistance of a semiconductor _____ with an increase in temperature.', '["Increases","Decreases","Remains the same","Becomes zero"]', 1, 'Unlike metals, semiconductors have a negative temperature coefficient of resistance; as they get hotter, more charge carriers are freed, reducing resistance.', NULL, 'WAEC_Physics_2024.json', '78d9556f70dc1ccc010c2c4be2915b8961942c38991476c0623d80a73a7513d5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'Which component allows current to flow in only one direction?', '["Resistor","Capacitor","Diode","Inductor"]', 2, 'A diode acts as a one-way valve for electricity, allowing current to flow only when forward-biased.', NULL, 'WAEC_Physics_2024.json', 'adb326402c97df49096a5504db8b773d6f5c23a94be19331a3b6467c303329d5');
