INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'The color of an object is determined by the color of light that it _____.', '["Absorbs","Refracts","Reflects","Transmits"]', 2, 'We see the color of light that an opaque object reflects. A red apple reflects red light and absorbs other colors.', NULL, 'WAEC_Physics_2024.json', '52b4c3410fe8e3881b6487a635d634df4e109ba7de8e526f4c5fed89b95c110a');
