INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Physics', 2024, NULL, 'Which of the following is an example of an artificial satellite?', '["The Moon","Comet Halley","International Space Station","The Sun"]', 2, 'Artificial satellites are man-made objects placed in orbit. The Moon is a natural satellite.', NULL, 'WAEC_Physics_2024.json', '7452aacef492941e8e371ff61bbc8c34010cc706e292aa1c7d03177183a74674');
