INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni iṣẹ́ ''ẹ̀mí'' nínú ìpín mẹ́ta tí Yorùbá pín ènìyàn sí?', '["Láti gbé ara ró","Láti fún ènìyàn ní ìjìnlẹ̀ òye","Láti sọ ara di alààyè","Láti yan orí ní àjálá mọpin"]', 2, 'In Yoruba metaphysics, the ''Ẹ̀mí'' (soul/breath) is the life-giving force provided by Olodumare that animates the ''Ara'' (body).', NULL, 'WAEC_Yoruba_2024.json', '43f788e588876fdb37f910e95188a133430f1c9efa1320a854835ffc80e4e8d1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Báwo ni a ṣe ń kọ ''emi'' pẹ̀lú àmì ohùn tí ó tọ́ bí ó bá dúró fún ''breath of life''?', '["Èmi","Ẹ̀mí","Emí","Ẹmi"]', 1, 'The word for soul or spirit is written as ''Ẹ̀mí'' with a low tone on ''Ẹ'' and a high tone on ''i''.', NULL, 'WAEC_Yoruba_2024.json', 'ad6d0d4f46db803627eb467947ab46a2a4e5d85394a7c16d2979401aa8e79c5f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Inú fọ́nẹ́tíìkì, ''e'' ati ''ẹ'' jẹ́ fọ́wẹ́lì _____.', '["Aránpúpò","Àránmú","Àìránmú","Atẹnu"]', 2, '''e'' and ''ẹ'' are oral vowels (fọ́wẹ́lì àìránmú) because air flows only through the mouth during their production.', NULL, 'WAEC_Yoruba_2024.json', 'f87ef815b09a79b7eaf774c7b9490109f512dc0f99d78d23c08a8d17231d3ba4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni ìyàtọ̀ láàárín ''Èmi'' àti ''Mo'' nínú gírámà Yorùbá?', '["Kò sí ìyàtọ̀","Èmi jẹ́ fún ìtẹnumọ́, Mo jẹ́ asojú-orúkọ lásán","Mo jẹ́ fún ìtẹnumọ́, Èmi jẹ́ asojú-orúkọ lásán","Èmi ni a ń lò lẹ́yìn ọ̀rọ̀-ìṣe"]', 1, '''Èmi'' is the emphatic/strong form of the first-person singular pronoun, while ''Mo'' is the short/clitic form used as a subject.', NULL, 'WAEC_Yoruba_2024.json', '6b2e179af8022e5d470e58aead8c455ebb8f7b7532f7f82393eae511c843cdb2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Nínú àsà Yorùbá, ta ni ẹni tí ń mọ ''Ara''?', '["Olódùmarè","Àjàlá","Ọbàtálá","Ògún"]', 2, 'Obatala is the deity responsible for molding the physical body (Ara) from clay.', NULL, 'WAEC_Yoruba_2024.json', '59b4b180965dbd35075cc5ac59c1fe85d7db4ae31eccd26d14e278926ef1845a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Parí òwe yìí: ''Ẹ̀mí m'' bẹ, _____ m'' bẹ''.', '["Owó","Ìmọ́lẹ̀","Ìtura","Àlàáfíà"]', 2, 'The proverb ''Ẹ̀mí m'' bẹ, ìtura m'' bẹ'' implies that as long as there is life, there is hope for comfort/relief.', NULL, 'WAEC_Yoruba_2024.json', '86751d11f113db48ef0960f2afd64a9edadb90e74c79a1825a0deb6e88dbd534');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Àpólà-ọ̀rọ̀ wo ni ''Èmi tìkarami''?', '["Àpólà-orúkọ","Àpólà-ìṣe","Àpólà-atọ́ka","Àpólà-asọpọ̀"]', 0, '''Èmi tìkarami'' (I, myself) functions as a noun phrase (Àpólà-orúkọ) focusing on the subject.', NULL, 'WAEC_Yoruba_2024.json', '1ff691018dd3dda7dc340ec97b02c1f6e49489726bdf2642d0d86d0f56a832f7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni iṣẹ́ fáwẹ́lì nínú ọ̀rọ̀ Yorùbá?', '["Wọ́n ń bẹ̀rẹ̀ ọ̀rọ̀-ìṣe","Wọ́n ń gbé ohùn jáde","Wọ́n ń parí ọ̀rọ̀-orúkọ","Wọ́n jẹ́ kọ́nṣónáǹtì"]', 1, 'Vowels are the nucleus of syllables in Yoruba; every syllable must contain a vowel to carry a tone.', NULL, 'WAEC_Yoruba_2024.json', 'f980f535e9478c2a2f8e2321a7c98c93536572343c826dfbeecfead82c64a1d2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Mélòó ni fáwẹ́lì àránmú nínú èdè Yorùbá?', '["Meje","Márùn-ún","Mẹ́sàn-án","Mẹ́fà"]', 1, 'There are five nasal vowels in standard Yoruba: an, ẹn, in, ọn, un.', NULL, 'WAEC_Yoruba_2024.json', 'aa3ba646da89c0eda1279968123094148b33b30dea56ab6a6a0c06f4dea9226f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Èwo nínú àwọn wọ̀nyí ni kì í ṣe kọ́nṣónáǹtì nínú èdè Yorùbá?', '["p","gb","c","y"]', 2, 'The letter ''c'' does not exist in the Yoruba alphabet; its sound is usually represented by ''s'' or ''ṣ''.', NULL, 'WAEC_Yoruba_2024.json', 'd933f2456514809c6e3fc74167a9dae6cb74cd086c1b0187779e4a4f71c7bad8');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni Yorùbá ń pè ní ''Ẹ̀fọ̀n''?', '["Elephant","Buffalo","Tiger","Deer"]', 1, '''Ẹ̀fọ̀n'' is the Yoruba name for a Buffalo.', NULL, 'WAEC_Yoruba_2024.json', '9e6fe5df67c25dc54b6304b14833714f6403578f637373998c74707f149faf6a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Nínú lítíréṣọ̀ àtẹnudẹ́nu, kí ni ''Àlọ̀ Àpagbe''?', '["Àlọ̀ tí kò ní orin","Àlọ̀ tí ó ní orin","Àlọ̀ nípa ìtàn ìṣẹ̀dá","Àlọ̀ nípa àwọn ọba"]', 1, 'Àlọ̀ Àpagbe refers to folktales that involve songs where the audience joins in the chorus.', NULL, 'WAEC_Yoruba_2024.json', '091be5d7a04b8422b90972e5c2f466deb1450ea0367488975024a8e99ce54adb');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Ta ni akọni nínú ìwé ''Ògbójú Ọdẹ nínú Igbó Irúnmalẹ̀''?', '["Àkàrà-oògùn","Kákò","Ọmọ-òdú","Ìrìnkèrindò"]', 0, 'Akara-oogun is the central protagonist in D.O. Fagunwa''s famous novel.', NULL, 'WAEC_Yoruba_2024.json', '00d1969ddbc3a76a94c1b0db70385483f1c1bae64189be508136fe86d5ccb9ef');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni orúkọ àmì ohùn orí ''i'' nínú ọ̀rọ̀ ''mì''?', '["Kòkòrò","Pe-n-pè-re-pè","Àmì-ìsàlẹ̀","Àmì-òkè"]', 2, 'The low tone marks (`) are called Àmì-ìsàlẹ̀ or Àmì-dò.', NULL, 'WAEC_Yoruba_2024.json', '8695a41fed78e1d1a3a89b1cf78d78c9874b42206150c40c5c5fd62b7e9a41b2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Èwo nínú àwọn wọ̀nyí ni ó jẹ́ àmì-ìdánimọ̀ fún ''Ẹ̀mí'' nínú èdè Yorùbá?', '["Mímí","Rírìn","Sísùn","Jíjẹun"]', 0, 'Breathing (Mímí) is the physical manifestation of the presence of ''Ẹ̀mí'' (the soul/life force).', NULL, 'WAEC_Yoruba_2024.json', '7c01680a12244ee6f28dcd7af5e95da429897e49384926d4e9226b446dd5a7c5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni ''Ọmọ-olórí-ire'' nínú àṣà Yorùbá?', '["Ọmọ tí ó ní owó lọ́wọ́","Ọmọ tí àyànmọ́ rẹ̀ dára","Ọmọ tí ó ga","Ọmọ tí ó jẹ́ àgbà"]', 1, 'An ''olórí-ire'' is someone believed to have chosen a good ''Ori'' (destiny/inner head) before coming to earth.', NULL, 'WAEC_Yoruba_2024.json', '6055eee17dd9b912c6a5c0bac2a252cdcdd185c46e815b1dcd6450445cc11265');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Báwo ni a ṣe ń pè ''Pronoun'' ní èdè Yorùbá?', '["Ọ̀rọ̀-orúkọ","Ọ̀rọ̀-asojú-orúkọ","Ọ̀rọ̀-ìṣe","Ọ̀rọ̀-àpèjúwe"]', 1, 'The word for Pronoun is Ọ̀rọ̀-asojú-orúkọ (a word that stands in for a name).', NULL, 'WAEC_Yoruba_2024.json', '182396c28e68b6de0585a00e341ff0ea7c22dc540db652d2478830cfddb210e5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Nínú lítíréṣọ̀ àtinúdá, ta ni ó kọ ''Ẹfúnsetán Aníwúrà''?', '["D.O. Fagunwa","Akinwunmi Isola","J.F. Odunjo","Adebayọ Faleti"]', 1, 'The historical drama ''Efunsetan Aniwura'' was written by Professor Akinwunmi Isola.', NULL, 'WAEC_Yoruba_2024.json', 'cf9e0aae41e904b7a6578bdbdcc2a8bd5c5b6a774429c87e37e056a8d63a6a15');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni iṣẹ́-oògùn ''Èmi'' nínú gírámà?', '["Láti jẹ́ ẹni kẹta","Láti jẹ́ ẹni kìn-ín-ní","Láti jẹ́ ẹni kẹjì","Láti jẹ́ ẹni púpọ̀"]', 1, '''Èmi'' is the first-person singular (ẹni kìn-ín-ní ẹyọ) pronoun.', NULL, 'WAEC_Yoruba_2024.json', 'fdff0953d798f1a85e7485ae19faf5ae99421808bfba517c799353be37f5c04f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Gẹ́gẹ́ bí nkan tí o kà, kí ni ń ṣẹlẹ̀ sí ẹ̀mí lẹ́yìn ikú?', '["Ó ń kú pẹ̀lú ara","Ó ń padà sí ọ̀dọ̀ Ẹlẹ́dàá","Ó ń di òkúta","Ó ń di ẹran"]', 1, 'The passage states that when the body dies, the soul (ẹ̀mí) returns to the Creator (Ẹlẹ́dàá).', 'Ẹ̀mí ènìyàn kò ní kú. Bí ara bá kú, ẹ̀mí á padà sí ọ̀dọ̀ Ẹlẹ́dàá rẹ̀. Yorùbá gbàgbọ́ pé ayé ni ọjà, ọ̀run ni ilé. Ohun tí ènìyàn bá ṣe ní ayé ni yóò lọ sọ ní ọ̀run. Èyí ni ó jẹ́ kí àwọn àgbà máa sọ pé ''Ìwà lẹ̀ṣìn ènìyàn''. Bí ènìyàn bá ní ìwà rere, ẹ̀mí rẹ̀ á sinmi lẹ́yìn ikú.', 'WAEC_Yoruba_2024.json', '35c62fbb18ba1de9c3fb7e6360e99fe5d0d360f1932845a925702f0a80df0b5e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni ìtumọ̀ ''Ayé ni ọjà, ọ̀run ni ilé''?', '["Ayé jẹ́ ibi tí a ti ń tajà","Ayé jẹ́ ibi ìgbà díẹ̀, ọ̀run ni ibùgbé títí ayé","Ọ̀run kò dára bí ayé","Ilé wa wà ní ọjà"]', 1, 'This is a philosophical proverb meaning earth is a temporary marketplace while heaven is our true home.', 'Ẹ̀mí ènìyàn kò ní kú. Bí ara bá kú, ẹ̀mí á padà sí ọ̀dọ̀ Ẹlẹ́dàá rẹ̀. Yorùbá gbàgbọ́ pé ayé ni ọjà, ọ̀run ni ilé. Ohun tí ènìyàn bá ṣe ní ayé ni yóò lọ sọ ní ọ̀run. Èyí ni ó jẹ́ kí àwọn àgbà máa sọ pé ''Ìwà lẹ̀ṣìn ènìyàn''. Bí ènìyàn bá ní ìwà rere, ẹ̀mí rẹ̀ á sinmi lẹ́yìn ikú.', 'WAEC_Yoruba_2024.json', '00eafd47f54bb6d3768e47c250e159b80b4eb8015bfbacf0d95e6752d5fa49ac');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni ohun tí ó ṣe pàtàkì jù nínú ìrìn-àjò ẹ̀mí gẹ́gẹ́ bí passage yìí ṣe sọ?', '["Owó","Ìwà","Ẹ̀wà","Iṣẹ́"]', 1, 'The passage emphasizes ''Ìwà'' (character) as the most important thing for the soul''s rest.', 'Ẹ̀mí ènìyàn kò ní kú. Bí ara bá kú, ẹ̀mí á padà sí ọ̀dọ̀ Ẹlẹ́dàá rẹ̀. Yorùbá gbàgbọ́ pé ayé ni ọjà, ọ̀run ni ilé. Ohun tí ènìyàn bá ṣe ní ayé ni yóò lọ sọ ní ọ̀run. Èyí ni ó jẹ́ kí àwọn àgbà máa sọ pé ''Ìwà lẹ̀ṣìn ènìyàn''. Bí ènìyàn bá ní ìwà rere, ẹ̀mí rẹ̀ á sinmi lẹ́yìn ikú.', 'WAEC_Yoruba_2024.json', '5c5814ca715a1a979c2a5057efdfc26a867bcc3c76ed9b3801a46c82e0f28b71');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Èwo ni ''Nasal Vowel'' nínú àwọn wọ̀nyí?', '["a","e","in","o"]', 2, '''in'' is a nasal vowel in Yoruba phonology.', NULL, 'WAEC_Yoruba_2024.json', 'debbc4d641dac18590f5291e1ccbf0712ddb31d05a2f0add7754738571ca04bc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni ohun tí a ń lò láti fi kọ àmì ohùn ''re'' nínú gírámà Yorùbá?', '["Àmì-òkè","Àmì-ìsàlẹ̀","Kò sí àmì","Àmì-ẹyẹ"]', 2, 'The mid-tone (re) is typically left unmarked in Yoruba orthography.', NULL, 'WAEC_Yoruba_2024.json', '4b7a499fef3068aa139548207ef1c3b376270437fd8ff223001785911922ad64');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Ta ni Olúwa ''Ẹ̀mí'' nínú ìgbàgbọ́ Yorùbá?', '["Èṣù","Olódùmarè","Sàngó","Ọ̀yá"]', 1, 'Olodumare (God) is the supreme giver and owner of the soul (Ẹ̀mí).', NULL, 'WAEC_Yoruba_2024.json', '08473f5d07e8eea99b4a8241e0747c7609e72d8cc917cd7d26d161e7d2b0ddb5');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Mélòó ni kọ́nṣónáǹtì Yorùbá?', '["Mẹ́rin-dín-lógún","Mẹ́jọ-dín-lógún","Mẹ́tà-dín-lógún","Mẹ́ẹ̀ẹ́dógún"]', 1, 'There are 18 consonants in the standard Yoruba alphabet (b, d, f, g, gb, h, j, k, l, m, n, p, r, s, ṣ, t, w, y).', NULL, 'WAEC_Yoruba_2024.json', '2349fae74b957a1b2da1f564d3775994772526eaffca306156fb62144f586455');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni iṣẹ́ ''ẹ̀mí'' nínú gírámà nígbà tí a bá ń sọ̀rọ̀ nípa ''I''?', '["Láti jẹ́ ọ̀rọ̀-ìṣe","Láti jẹ́ ọ̀rọ̀-asojú-orúkọ ẹni kìn-ín-ní","Láti jẹ́ ọ̀rọ̀-àpèjúwe","Láti jẹ́ ọ̀rọ̀-atọ́ka"]', 1, 'When referring to ''I'', ''Èmi'' is the first-person singular pronoun.', NULL, 'WAEC_Yoruba_2024.json', '60651fd8eec59924f4de2e767dddbb40257a0ff57dd7613717f865e1292c088e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Nínú ''Ogboju Ode'', ta ni a mọ̀ sí ''ẹni tí ó ní ìyá méjì''?', '["Àkàrà-oògùn","Olowo-aiye","Aramada-okunrin","Gbogbo rẹ̀"]', 0, 'This refers to the protagonist Akara-oogun in Fagunwa''s literature.', NULL, 'WAEC_Yoruba_2024.json', '59dd4a55bf38cdbb39f0aa56203055aa94f0b9273b7a15d87d9291ff6a5c9ade');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni ìtumọ̀ ''Ààyè''?', '["Iku","Ibi tí ẹ̀mí wà/Life","Òkúta","Òrun"]', 1, '''Ààyè'' refers to being alive or a living space where life exists.', NULL, 'WAEC_Yoruba_2024.json', '66441986d0ab66343e9197f6c4843e79c2af64e8056fb95e22914943f4b68d1b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni Yorùbá ń pè ní ''Syllable''?', '["Mọ́fíìmù","Sílẹ́bù","Fóníìmù","Gírámà"]', 1, 'Yoruba language uses ''Sílẹ́bù'' for Syllable.', NULL, 'WAEC_Yoruba_2024.json', 'ecccb207f03c11743125926690d702d6b52f315234c82a21d6a7676d0b32650c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Mélòó ni fáwẹ́lì inú èdè Yorùbá lápapọ̀?', '["Meje","Mẹ́fà","Mẹ́ẹ̀ẹ́dógún","Mẹ́tàlá"]', 3, 'Standard Yoruba has 12-13 vowels depending on dialect counting: 7 oral (a, e, ẹ, i, o, ọ, u) and 5 nasal (an, ẹn, in, ọn, un).', NULL, 'WAEC_Yoruba_2024.json', 'ea609f5ed386312baa1fb7560b779b51e74a03daa814b0fee761d6a06c4f093c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni orúkọ fáwẹ́lì tí a ń pè ní ''ẹ''?', '["Fáwẹ́lì iwájú, a-mí-sí-nu","Fáwẹ́lì iwájú, kéré-díẹ̀","Fáwẹ́lì ẹ̀yìn","Fáwẹ́lì àárín"]', 1, '''ẹ'' is a front, half-open vowel (iwájú, kéré-díẹ̀).', NULL, 'WAEC_Yoruba_2024.json', '168e2846bbd706d4f8e4ba95ebc33958cb9a6dadd9ebc24dff19957325625156');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Èwo nínú àwọn wọ̀nyí ni kì í ṣe ọ̀nà ìpè kọ́nṣónáǹtì?', '["Aránmú","Atẹnu","Ayán-nu","gb"]', 3, '''gb'' is a consonant itself, not a place or manner of articulation.', NULL, 'WAEC_Yoruba_2024.json', '0b221fe670b1fd5b11300e1dd1fce7caff57499784bd6da0dc52d8023d7bdd3b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Inú ''Sàngó'', àmì ohùn wo ni ó wà lórí ''o''?', '["Do","Re","Mi","Kò sí"]', 2, 'In Sàngó, the ''o'' carries a high tone (Mi).', NULL, 'WAEC_Yoruba_2024.json', '50ad89ab1c62a5703ba12fd99df3aad93965cc7ed123f82df00a058b75ed2252');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni Yorùbá ń pè ní ''Subject''?', '["Olùwà","Àbọ̀","Ọ̀rọ̀-ìṣe","Ẹyọ"]', 0, 'The Subject of a sentence is called ''Olùwà''.', NULL, 'WAEC_Yoruba_2024.json', 'e987b0df61dbfd9d6fa6aedec8cc5c2032ecb708c6a603a262ef52eb94b4e3e7');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni Yorùbá ń pè ní ''Object''?', '["Olùwà","Àbọ̀","Àpólà","Kàn-an-nì"]', 1, 'The Object of a sentence is called ''Àbọ̀''.', NULL, 'WAEC_Yoruba_2024.json', '6c308601424994e015e773cfc30f31ab421dd9b01bba53367232dabc9d70fb27');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Parí òwe yìí: ''Iṣẹ́ ni oògùn _____''?', '["Owó","Àìsàn","Ìyà","Ibi"]', 2, 'The proverb ''Iṣẹ́ ni oògùn ìyà'' means work is the antidote to poverty/suffering.', NULL, 'WAEC_Yoruba_2024.json', 'd86ca65162bf67b7f3acb464260ecc23b9ecc934fbe60b3c3a6eb97788bef7bc');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni ''Èmi'' nínú gírámà Yorùbá fún ẹni tí ń sọ̀rọ̀?', '["First person","Second person","Third person","None of the above"]', 0, '''Èmi'' corresponds to the First Person singular.', NULL, 'WAEC_Yoruba_2024.json', 'f603ccd291380bb0c1955f63904ee1003ad63580c8a8ce3f9ca6d389a44d41c9');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Èwo nínú àwọn wọ̀nyí ni ó jẹ́ orúkọ-àbíkú?', '["Ìgè","Bánjókòó","Àdùfẹ́","Ẹ̀rù-ò-boni"]', 1, 'Names like ''Banjoko'' (Stay with us) are given to Abiku children to encourage them to stay alive.', NULL, 'WAEC_Yoruba_2024.json', 'd00a19083e16b8aa0bf7651cd524c1df1e304f1fb6e281b9da088329d006fa03');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni Yorùbá ń pè ní ''Naming Ceremony''?', '["Ìsọmọlórúkọ","Ìgbéyàwó","Ìsìnkú","Ìwúyè"]', 0, 'Ìsọmọlórúkọ is the naming ceremony usually performed on the 8th or 9th day.', NULL, 'WAEC_Yoruba_2024.json', '1ea9b97edfbdd16cce6da3a22ffec6a9692297bae1cdf57ddf4514a9321f2223');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni ohun tí a ń lò nínú ìsọmọlórúkọ láti dúró fún ''Ìtura''?', '["Iyọ̀","Oyin","Omi","Atare"]', 2, 'Water (Omi) is used in ceremonies to symbolize coolness and comfort (ìtura).', NULL, 'WAEC_Yoruba_2024.json', '9a1ee8fe6bdd109ae22c416ac6bf2f1b3536be51414ebffc4fdfaa32a0b70555');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni àyà-fún-mú nínú èdè Yorùbá?', '["Èémí","Ìmú","Fọ́nẹ́tíìkì","Kọ́nṣónáǹtì àránmú"]', 3, 'Nasal consonants are produced with air passing through the nose.', NULL, 'WAEC_Yoruba_2024.json', '25db0d21e933578270836bd66e599678698d19c509f6a34f3bd888e67730f9c4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Èwo ni ''Labio-dental fricative'' kọ́nṣónáǹtì?', '["f","s","h","p"]', 0, 'The consonant ''f'' is a labio-dental fricative.', NULL, 'WAEC_Yoruba_2024.json', 'c336cce6b658fe81b6547583fb8f95fc848cdb6eec98eb391e149bfd527dbe7d');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni Yorùbá ń pè ní ''Literature''?', '["Gírámà","Lítíréṣọ̀","Àṣà","Ìtàn"]', 1, 'Literature is translated as ''Lítíréṣọ̀''.', NULL, 'WAEC_Yoruba_2024.json', '5e6631e630c0c72069aae0baefa2c18512fc970647c9cb3cbe03c0c6437d2e87');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni ''Oriki''?', '["Àlọ̀","Ewì ìyìn/Appellation","Ìtàn àròsọ","Erè kárí ayé"]', 1, 'Oriki are panegyrics or praise poetry used to highlight lineage or character.', NULL, 'WAEC_Yoruba_2024.json', '84e4791e9e9750d41f444407c6ed6184a8b5ef1a233827b5f28884dbb39b0ec3');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Èwo nínú àwọn wọ̀nyí ni kì í ṣe iṣẹ́-òbí Yorùbá?', '["Ìtọ́jú ọmọ","Kíkọ́ ọmọ ní ìṣẹ́","Kíkọ́ ọmọ láti jalè","Kíkọ́ ọmọ ní ìwà"]', 2, 'Stealing is contrary to ''Omoluabi'' values taught by parents.', NULL, 'WAEC_Yoruba_2024.json', 'c10f16d2273170e06fc6b908da94b0496ed6f7c67676db2ee5cb27d919de0d4a');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni Yorùbá ń pè ní ''Good character''?', '["Ìwà tútù","Ìwà rere","Ìwà ìbàjẹ́","Ìwà ọ̀pẹ"]', 1, 'Good character is ''Ìwà rere''.', NULL, 'WAEC_Yoruba_2024.json', 'bcbe5a81bcf830e0e635b2b50c45a2cbc15409d51315e3b95d3142c502531118');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Èwo nínú àwọn wọ̀nyí ni ohun èlò kọ̀ǹpútà nínú èdè Yorùbá?', '["Ìpàtẹ","Pẹ́n-ń-rẹ́n-rẹ́n","Bọ́tìnnì","Gbogbo rẹ̀"]', 3, 'These are Yoruba terms for screen, mouse/pen, and buttons.', NULL, 'WAEC_Yoruba_2024.json', '8d97f27b5acaa1ee0cc4e135ca510bb749c27d9ca05c48c3eb1d2950bb5bdae4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni orúkọ Yorùbá fún ''Market''?', '["Ilé","Ọjà","Igbó","Odò"]', 1, '''Ọjà'' is a market.', NULL, 'WAEC_Yoruba_2024.json', '4ffcb1da52fe2634b37805e90fdba7dcf3eaf632f0cf0b57481fe783e9df565f');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni ''Ìrè''?', '["Blessing","Curse","Fight","Death"]', 0, '''Ìrè'' refers to goodness or blessings.', NULL, 'WAEC_Yoruba_2024.json', '8d1184d82714a38ec10747efa7d1e79cae7535d57477f93ca16d7563eedbcc9c');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Ta ni ó mọ ''Orí'' ní Ìmọ̀-ìṣẹ̀dá Yorùbá?', '["Àjàlá mọpin","Ọbàtálá","Ògún","Sàngó"]', 0, 'Ajalamopin is the potter in heaven who creates the inner heads (Ori).', NULL, 'WAEC_Yoruba_2024.json', '4034bee283028cb2fbd0c340c896a4c425e6244152e3168344aa09315d7bb3d2');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni Yorùbá ń pè ní ''Destiny''?', '["Owó","Àyànmọ́","Ara","Iṣẹ́"]', 1, 'Destiny is known as ''Àyànmọ́'' or ''Àpín-orí''.', NULL, 'WAEC_Yoruba_2024.json', '6836617938c4a38c5536661c656a63ab230b1923412a486c14b21093cb116084');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Èwo nínú àwọn wọ̀nyí ni ó jẹ́ kọ́nṣónáǹtì ''fìpè-fagbe'' (Voiced)?', '["f","b","s","k"]', 1, '''b'' is a voiced bilabial stop.', NULL, 'WAEC_Yoruba_2024.json', '598ac76c168af9d8c1a47680a514042eb83acb405571f76d6b9c78cf468d694b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni ''Èmi'' ń jẹ́ nínú gbólóhùn yìí: ''Èmi ni alága''?', '["Olùwà","Àbọ̀","Ẹ̀yán","Ọ̀rọ̀-ìpọ́"]', 0, 'In ''Èmi ni alága'', ''Èmi'' is the Subject (Olùwà).', NULL, 'WAEC_Yoruba_2024.json', 'f0a5fbb425bb6c0709c2507655323ffe4085206c6d9aad73dd6896a53fecc82b');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Èwo ni fáwẹ́lì iwájú, fífẹ̀ (open front)?', '["a","i","u","o"]', 0, '''a'' is an open front vowel in Yoruba.', NULL, 'WAEC_Yoruba_2024.json', '22f79570de49288d5b27afa11a993d322d97c05b164db29e3276af682f71c998');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Mélòó ni fáwẹ́lì ''ẹyọ'' (Oral) nínú èdè Yorùbá?', '["Meje","Márùn-ún","Mẹ́sàn-án","Mẹ́ẹ̀ẹ́dógún"]', 0, 'There are 7 oral vowels: a, e, ẹ, i, o, ọ, u.', NULL, 'WAEC_Yoruba_2024.json', 'df632fdff724c4d90ecae7f9ead4ed1c8efda65925779f9785cce406615a8a42');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni Yorùbá ń pè ní ''Culture''?', '["Èdè","Àṣà","Lítíréṣọ̀","Ìtàn"]', 1, 'Culture is ''Àṣà''.', NULL, 'WAEC_Yoruba_2024.json', 'fea278de3e608b2ac1a0bafb639dbcfef0ff9863619fe47528e63b58ba4fea27');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Èwo nínú àwọn wọ̀nyí ni iṣẹ́-abínibí Yorùbá?', '["Àgbẹ̀","Akọ̀wé","Mẹ́káníìkì","Tẹ́ńpù"]', 0, 'Farming (Àgbẹ̀) is a primary traditional occupation of the Yoruba.', NULL, 'WAEC_Yoruba_2024.json', '3fc1a964f4e5ae27c9d40b1b5e4821e2c5f56b3c0b5f412373a0ca1f9a60f984');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Ta ni Ọba tí ó ní ''Ilé-Ifẹ̀''?', '["Aláàfin","Ọọ̀ni","Oba","Awùjalẹ̀"]', 1, 'The Ooni is the traditional ruler of Ile-Ife.', NULL, 'WAEC_Yoruba_2024.json', '2ad7f30dcb37bea67e9594cf2a501670b64d20e07ddb06daa2d2862c5c580261');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Báwo ni a ṣe ń kí ẹni tí ó ń ṣiṣẹ́?', '["Ẹ kú àárọ̀","Ẹ kú iṣẹ́","Ẹ kú àbọ̀","Ẹ kú ìjókòó"]', 1, '''Ẹ kú iṣẹ́'' is the greeting for someone working.', NULL, 'WAEC_Yoruba_2024.json', '306650ead720a862b5443298d6fdf7e84c68b68e9c083413a6e267d78f961615');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni ''Ẹ̀mí'' nínú ohun tí ó wà lórí ilẹ̀?', '["Erùpẹ̀","Èrò","Èèyàn","Gbogbo rẹ̀"]', 2, 'A person (Èèyàn) is the primary vessel for ''Ẹ̀mí'' in human context.', NULL, 'WAEC_Yoruba_2024.json', 'a0c54bff0516496904916eb98b655d76be86b48669d5b28688c285ce3126b28e');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Èwo nínú àwọn wọ̀nyí ni ó jẹ́ fáwẹ́lì àránmú ''un''?', '["High back nasal","Low back nasal","Front nasal","Mid nasal"]', 0, '''un'' is a high back nasal vowel.', NULL, 'WAEC_Yoruba_2024.json', '88beb64c43cc0f6e05b8f93c1a9cd0dac0ac62fbb66c82250723a75099aae873');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni ìtumọ̀ ''Àkókò''?', '["Time","Wealth","Power","Work"]', 0, '''Àkókò'' means Time.', NULL, 'WAEC_Yoruba_2024.json', 'c58a33d004698722e2e5da2d469745ed236bd333ecca7370f01135462e5abdcf');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni ohun tí Yorùbá ń pè ní ''Family''?', '["Ẹ̀bí","Ìlú","Ọjà","Ayé"]', 0, 'Family is ''Ẹ̀bí''.', NULL, 'WAEC_Yoruba_2024.json', 'c27cf68fb66b0d90ecf8e8e6c913ddac573aa6d45ec751a5f58b6e3d7a251bd1');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Èwo nínú àwọn wọ̀nyí ni kì í ṣe ọ̀rọ̀-asopọ̀?', '["Àti","Sùgbọ́n","Tàbí","Èmi"]', 3, '''Èmi'' is a pronoun, while the others are conjunctions.', NULL, 'WAEC_Yoruba_2024.json', '4cf0bc96b471d58517a4b8519c804e44e6377c1c459d3af5c9474d1192ab57d4');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Kí ni iṣẹ́ ''Èmi'' nínú èdè?', '["Communication of self","Description of house","Telling time","None"]', 0, '''Èmi'' expresses the first person identity.', NULL, 'WAEC_Yoruba_2024.json', '008f2938037bbe05440a5a0bb3f6d8d2c174e43014fc23740acfde15941b6c39');
INSERT OR IGNORE INTO questions (exam, subject, year, topic, q_text, options_json, answer_idx, explanation, passage, source_file, hash) VALUES ('WAEC', 'Yoruba', 2024, NULL, 'Parí òwe yìí: ''Bí ẹ̀mí bá wà, _____ á wà''?', '["Ìrètí","Owó","Ibi","Iṣẹ́"]', 0, 'The proverb implies ''Where there is life, there is hope'' (Ìrètí).', NULL, 'WAEC_Yoruba_2024.json', 'be86ba56d8d10ff3b8e78dd44b1759de09bb62e51d6128a295f5a5b0beff7d6e');
